class RunnerError(ValueError):
    """The runner cannot establish a required host-owned fact."""


def _absolute_executable_path(value: object) -> Path:
    """Accept one canonical absolute executable spelling without resolving it.

    Resolving here would follow a potentially substituted symlink before the
    descriptor-backed contract reader gets to reject it.  The runner therefore
    preserves the code-owned spelling and delegates every open/reseal to the
    contract's no-follow executable reader.
    """

    if (type(value) is not str or not value.startswith("/") or value.startswith("//")
            or "\\" in value or "\0" in value):
        raise RunnerError("registered executable path is not canonical")
    path = PurePosixPath(value)
    if (value == "/" or path.as_posix() != value
            or any(part in {"", ".", ".."} for part in path.parts)):
        raise RunnerError("registered executable path is not canonical")
    return Path(value)


@dataclass(frozen=True)
class RunnerOwnedExecutableRegistration:
    """A code-owned candidate, never a caller or environment selector."""

    client: str
    resolved_path: Path | str
    expected_version: str
    native_format: str

    def __post_init__(self) -> None:
        if self.client not in {"claude", "codex"}:
            raise RunnerError("registered executable client unsupported")
        path = _absolute_executable_path(os.fspath(self.resolved_path))
        if (type(self.expected_version) is not str
                or re.fullmatch(r"[0-9]+(?:\.[0-9]+)+", self.expected_version) is None
                or type(self.native_format) is not str or not self.native_format):
            raise RunnerError("registered executable metadata invalid")
        object.__setattr__(self, "resolved_path", path)


# This is an installation *registration*, not discovery.  Its literal path
# comes from the Task 7d local preflight, is never derived from PATH, HOME,
# config, or caller input, and remains unusable unless the descriptor-pinned
# bytes also match Task 7a's default digest-keyed build registry.
_RUNNER_OWNED_EXECUTABLES: Mapping[str, RunnerOwnedExecutableRegistration] = MappingProxyType({
    "claude": RunnerOwnedExecutableRegistration(
        client="claude",
        resolved_path=Path("/Users/rishikeshranjan/.local/share/claude/versions/2.1.251"),
        expected_version="2.1.251",
        native_format="claude-stream-json-2.1.251-v1",
    ),
})


def _reject_duplicates(items: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in items:
        if key in result:
            raise RunnerError("duplicate JSON key")
        result[key] = value
    return result


def _strict_json(raw: str | bytes, *, label: str) -> Any:
    try:
        return json.loads(
            raw,
            object_pairs_hook=_reject_duplicates,
            parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)),
        )
    except (TypeError, UnicodeDecodeError, ValueError, json.JSONDecodeError) as error:
        raise RunnerError(f"invalid {label} JSON") from error


def _canonical_json(value: Any) -> bytes:
    return json.dumps(
        value, ensure_ascii=False, allow_nan=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def _line(value: Any) -> bytes:
    return _canonical_json(value) + b"\n"


def _sha256(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def _identity(path: Path) -> dict[str, int]:
    info = path.lstat()
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
        raise RunnerError("unsafe regular-file identity")
    return {
        "device": info.st_dev,
        "inode": info.st_ino,
        "mode": info.st_mode,
        "uid": info.st_uid,
        "nlink": info.st_nlink,
        "bytes": info.st_size,
        "mtime_ns": info.st_mtime_ns,
        "ctime_ns": info.st_ctime_ns,
    }


def _directory_identity(path: Path) -> tuple[int, int, int, int, int, int, int]:
    info = path.lstat()
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
        raise RunnerError("unsafe directory identity")
    return (
        info.st_dev,
        info.st_ino,
        info.st_mode,
        info.st_uid,
        info.st_nlink,
        info.st_mtime_ns,
        info.st_ctime_ns,
    )


def _safe_read(path: Path, *, maximum: int = _MAX_CAPTURE_BYTES) -> bytes:
    try:
        before = path.lstat()
        if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
            raise RunnerError("unsafe capture artifact")
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0))
    except RunnerError:
        raise
    except OSError as error:
        raise RunnerError("capture artifact unavailable") from error
    try:
        chunks: list[bytes] = []
        total = 0
        while True:
            chunk = os.read(fd, min(1 << 20, maximum - total + 1))
            if not chunk:
                break
            total += len(chunk)
            if total > maximum:
                raise RunnerError("capture artifact exceeds size limit")
            chunks.append(chunk)
        after = os.fstat(fd)
        named = path.lstat()
    finally:
        os.close(fd)
    if (before.st_dev, before.st_ino, before.st_mode, before.st_uid, before.st_nlink,
            before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (
                after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_nlink,
                after.st_size, after.st_mtime_ns, after.st_ctime_ns,
            ) or (
                after.st_dev, after.st_ino, after.st_mode, after.st_uid, after.st_nlink,
                after.st_size, after.st_mtime_ns, after.st_ctime_ns,
            ) != (
                named.st_dev, named.st_ino, named.st_mode, named.st_uid, named.st_nlink,
                named.st_size, named.st_mtime_ns, named.st_ctime_ns,
            ):
        raise RunnerError("capture artifact changed while read")
    return b"".join(chunks)


def _write_private(
    path: Path,
    raw: bytes,
) -> tuple[int, int, int, int, int, int, int, int]:
    """Exclusively write one private file and retain its production identity."""

    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    try:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
    except OSError as error:
        raise RunnerError("cannot create private control artifact") from error
    try:
        offset = 0
        while offset < len(raw):
            offset += os.write(fd, raw[offset:])
        os.fsync(fd)
        opened = os.fstat(fd)
        try:
            named = os.stat(path, follow_symlinks=False)
        except OSError as error:
            raise RunnerError("private control artifact changed while written") from error
        identity = PinnedDirectory._regular_identity(opened)
        if (not stat.S_ISREG(opened.st_mode)
                or opened.st_nlink != 1
                or identity != PinnedDirectory._regular_identity(named)):
            raise RunnerError("private control artifact changed while written")
    finally:
        os.close(fd)
    return identity


def _is_hex64(value: object) -> bool:
    return type(value) is str and len(value) == 64 and set(value) <= _SHA


def parse_client_command_json(raw: str) -> list[str]:
    """Parse only a JSON argv array; shell syntax is never a transport."""

    value = _strict_json(raw, label="client command")
    if type(value) is not list or not value:
        raise RunnerError("client command must be a nonempty JSON argv array")
    if any(type(item) is not str or not item or "\0" in item for item in value):
        raise RunnerError("client command must contain nonempty strings")
    return list(value)


_CODEX_TEMPLATE = [
    "codex", "exec", "--json", "--ignore-user-config", "--ignore-rules", "--ephemeral",
    "--sandbox", "workspace-write", "-c", "sandbox_workspace_write.network_access=false",
    "-C", "{workspace}", "-",
]
_CLAUDE_TEMPLATE = [
    "claude", "--print", "--output-format", "stream-json", "--restricted",
    "--strict-mcp-config", "--mcp-config", "{mcp_config}", "--no-chrome",
    "--no-session-persistence", "--permission-mode", "dontAsk", "--tools",
    "Read,Edit,Write,Glob,Grep,Bash", "--allowedTools",
    "Read,Edit,Write,Glob,Grep,Bash(./brain *),Bash(git status *),Bash(git diff *)",
    "--verbose", "{prompt}",
]


def build_effective_argv(
    client: str,
    template: Sequence[str],
    workspace: Path,
    mcp_config: Path,
    prompt: str,
) -> list[str]:
    """Expand only documented runner-owned template slots in an exact profile."""

    workspace = workspace.resolve()
    mcp_config = mcp_config.resolve()
    if client == "codex":
        if list(template) != _CODEX_TEMPLATE:
            raise RunnerError("closed Codex profile rejected")
        return [str(workspace) if item == "{workspace}" else item for item in template]
    if client == "claude":
        if list(template) != _CLAUDE_TEMPLATE:
            raise RunnerError("closed Claude profile rejected")
        return [
            str(mcp_config) if item == "{mcp_config}" else prompt if item == "{prompt}" else item
            for item in template
        ]
    raise RunnerError("unsupported client")


