@dataclass(frozen=True)
class PinnedDirectory:
    """Retain a descriptor root and recheck every absolute ancestry edge.

    A pathname-only pin leaves a check-to-use gap when conversion later opens
    raw shim captures.  This object retains the leaf descriptor selected by
    the original no-follow walk and reads descendants descriptor-relatively;
    it still rejects a renamed/replaced public root rather than treating a
    stale descriptor as permission to finish a run.
    """

    path: Path
    edges: tuple[tuple[str, tuple[int, int, int, int]], ...]
    private: bool
    root_fd: int = field(init=False, repr=False, compare=False)

    def __post_init__(self) -> None:
        path, edges, _private = PinnedDirectory._validated_root_shape(
            self.path, self.edges, self.private,
        )
        fd = -1
        try:
            fd = PinnedDirectory._open_leaf(path)
            observed = os.fstat(fd)
            identity = (observed.st_dev, observed.st_ino, observed.st_mode, observed.st_uid)
            if identity != edges[-1][1]:
                raise RunnerError("trusted root changed while retained")
            object.__setattr__(self, "root_fd", fd)
            fd = -1
        except RunnerError:
            raise
        except (AttributeError, TypeError, ValueError, OSError) as error:
            raise RunnerError("trusted root is invalid") from error
        finally:
            if fd >= 0:
                os.close(fd)

    @staticmethod
    def _validated_root_shape(
        path: object,
        edges: object,
        private: object,
    ) -> tuple[Path, tuple[tuple[str, tuple[int, int, int, int]], ...], bool]:
        """Return canonical immutable root fields before descriptor use."""

        if (not isinstance(path, Path)
                or not path.is_absolute()
                or path == Path("/")
                or type(private) is not bool
                or type(edges) is not tuple
                or not edges):
            raise RunnerError("trusted root is invalid")
        copied: list[tuple[str, tuple[int, int, int, int]]] = []
        for edge in edges:
            if (type(edge) is not tuple or len(edge) != 2
                    or type(edge[0]) is not str
                    or type(edge[1]) is not tuple or len(edge[1]) != 4
                    or any(type(item) is not int for item in edge[1])):
                raise RunnerError("trusted root is invalid")
            copied.append((edge[0], tuple(edge[1])))
        result = tuple(copied)
        if result[-1][0] != str(path):
            raise RunnerError("trusted root is invalid")
        return path, result, private

    @classmethod
    def pin(cls, path: Path, *, private: bool) -> "PinnedDirectory":
        path = path.resolve(strict=True)
        if not path.is_absolute() or path == Path("/"):
            raise RunnerError("trusted root must be a non-root absolute directory")
        edges = cls._walk(path)
        leaf = edges[-1][1]
        if private and (leaf[2] & 0o077):
            raise RunnerError("control root is not private")
        return cls(path, edges, private)

    @classmethod
    def retain(cls, source: "PinnedDirectory") -> "PinnedDirectory":
        """Duplicate one already-verified descriptor without reopening its path.

        A returned diagnostic token may retain a public ``PinnedDirectory``
        facade.  Private launch state needs a distinct descriptor owner: a
        fresh pathname walk here could accidentally adopt a replacement as a
        new baseline, while sharing ``root_fd`` leaves the private path
        vulnerable to direct Python field replacement on the public facade.
        """

        if type(source) is not cls:
            raise RunnerError("retained trusted root is invalid")
        try:
            cls.verify(source)
            path, edges, private = cls._validated_root_shape(
                source.path, source.edges, source.private,
            )
            fd = os.dup(source.root_fd)
            try:
                os.set_inheritable(fd, False)
                observed = os.fstat(fd)
                identity = (
                    observed.st_dev, observed.st_ino, observed.st_mode, observed.st_uid,
                )
                if identity != edges[-1][1]:
                    raise RunnerError("retained trusted root changed")
                retained = object.__new__(cls)
                object.__setattr__(retained, "path", path)
                object.__setattr__(retained, "edges", edges)
                object.__setattr__(retained, "private", private)
                object.__setattr__(retained, "root_fd", fd)
                fd = -1
                try:
                    cls.verify(retained)
                except BaseException:
                    # Ownership transferred before the final structural
                    # recheck.  Match ``retain_relative_directory`` and
                    # release the duplicate if that recheck rejects it.
                    cls.close(retained)
                    raise
                return retained
            finally:
                if fd >= 0:
                    os.close(fd)
        except RunnerError:
            raise
        except (AttributeError, TypeError, ValueError, OSError) as error:
            raise RunnerError("retained trusted root is unavailable") from error

    @classmethod
    def retain_relative_directory(
        cls,
        source: "PinnedDirectory",
        relative: str,
        *,
        private: bool,
    ) -> "PinnedDirectory":
        """Retain one existing descendant without a pathname re-baseline.

        The host diagnostic reaches its growing run directory only after a
        phase-two token has been retained.  Opening ``writer.run_root`` by
        pathname there could make a replacement directory appear to be the
        new baseline.  Descend from the already-retained control descriptor
        instead and extend its verified ancestry edges with each child.
        """

        if type(source) is not cls or type(private) is not bool:
            raise RunnerError("retained trusted child root is invalid")
        parts = cls._relative_parts(relative)
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        directory = -1
        try:
            cls.verify(source)
            directory = os.dup(source.root_fd)
            path, retained_edges, _source_private = cls._validated_root_shape(
                source.path, source.edges, source.private,
            )
            edges = list(retained_edges)
            for part in parts:
                before = os.stat(part, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
                    raise RunnerError("retained trusted child root is unsafe")
                child = os.open(part, flags, dir_fd=directory)
                try:
                    opened = os.fstat(child)
                    after = os.stat(part, dir_fd=directory, follow_symlinks=False)
                    expected = (before.st_dev, before.st_ino, before.st_mode, before.st_uid)
                    observed = (opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid)
                    named = (after.st_dev, after.st_ino, after.st_mode, after.st_uid)
                    if observed != expected or named != expected:
                        raise RunnerError("retained trusted child root changed while opened")
                    if private and part == parts[-1] and (opened.st_mode & 0o077):
                        raise RunnerError("retained trusted child root is not private")
                    path /= part
                    edges.append((str(path), observed))
                    os.close(directory)
                    directory = child
                    child = -1
                finally:
                    if child >= 0:
                        os.close(child)
            retained = object.__new__(cls)
            object.__setattr__(retained, "path", path)
            object.__setattr__(retained, "edges", tuple(edges))
            object.__setattr__(retained, "private", private)
            object.__setattr__(retained, "root_fd", directory)
            directory = -1
            try:
                cls.verify(retained)
            except BaseException:
                cls.close(retained)
                raise
            return retained
        except RunnerError:
            raise
        except (AttributeError, TypeError, ValueError, OSError) as error:
            raise RunnerError("retained trusted child root is unavailable") from error
        finally:
            if directory >= 0:
                os.close(directory)

    @staticmethod
    def _walk(path: Path) -> tuple[tuple[str, tuple[int, int, int, int]], ...]:
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        fd = os.open("/", flags)
        result: list[tuple[str, tuple[int, int, int, int]]] = []
        current = Path("/")
        try:
            root = os.fstat(fd)
            result.append(("/", (root.st_dev, root.st_ino, root.st_mode, root.st_uid)))
            for part in path.parts[1:]:
                before = os.stat(part, dir_fd=fd, follow_symlinks=False)
                if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
                    raise RunnerError("trusted root has an unsafe ancestor")
                child = os.open(part, flags, dir_fd=fd)
                try:
                    after = os.fstat(child)
                    named = os.stat(part, dir_fd=fd, follow_symlinks=False)
                    # A directory's link count changes legitimately when the
                    # fixture creates/removes subdirectories, so device/inode,
                    # mode, and owner are the stable pinned edge identity.
                    before_tuple = (before.st_dev, before.st_ino, before.st_mode, before.st_uid)
                    after_tuple = (after.st_dev, after.st_ino, after.st_mode, after.st_uid)
                    named_tuple = (named.st_dev, named.st_ino, named.st_mode, named.st_uid)
                    if before_tuple != after_tuple or after_tuple != named_tuple:
                        raise RunnerError("trusted root changed while opened")
                    current /= part
                    result.append((str(current), after_tuple))
                except BaseException:
                    # ``fd`` remains the parent until the child has passed
                    # every identity check.  Closing only the parent in a
                    # ``finally`` would leak this child and leave the outer
                    # cleanup to double-close the parent on an error path.
                    os.close(child)
                    raise
                else:
                    os.close(fd)
                    fd = child
        finally:
            os.close(fd)
        return tuple(result)

    @staticmethod
    def _open_leaf(path: Path) -> int:
        """Open the pinned leaf by descriptor-walking every absolute edge."""

        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        fd = os.open("/", flags)
        try:
            for part in path.parts[1:]:
                before = os.stat(part, dir_fd=fd, follow_symlinks=False)
                if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
                    raise RunnerError("trusted root has an unsafe ancestor")
                child = os.open(part, flags, dir_fd=fd)
                try:
                    after = os.fstat(child)
                    named = os.stat(part, dir_fd=fd, follow_symlinks=False)
                    expected = (before.st_dev, before.st_ino, before.st_mode, before.st_uid)
                    if ((after.st_dev, after.st_ino, after.st_mode, after.st_uid) != expected
                            or (named.st_dev, named.st_ino, named.st_mode, named.st_uid) != expected):
                        raise RunnerError("trusted root changed while opened")
                except BaseException:
                    os.close(child)
                    raise
                os.close(fd)
                fd = child
            return fd
        except BaseException:
            os.close(fd)
            raise

    @staticmethod
    def _regular_identity(info: os.stat_result) -> tuple[int, int, int, int, int, int, int, int]:
        return (
            info.st_dev, info.st_ino, info.st_mode, info.st_uid, info.st_nlink,
            info.st_size, info.st_mtime_ns, info.st_ctime_ns,
        )

    @staticmethod
    def _relative_parts(relative: str) -> tuple[str, ...]:
        if type(relative) is not str or not relative:
            raise RunnerError("unsafe pinned relative path")
        path = PurePosixPath(relative)
        if (path.is_absolute() or path.as_posix() != relative or not path.parts
                or any(part in {"", ".", ".."} for part in path.parts)):
            raise RunnerError("unsafe pinned relative path")
        return path.parts

    def verify(self) -> None:
        path, edges, private = PinnedDirectory._validated_root_shape(
            self.path, self.edges, self.private,
        )
        if type(self.root_fd) is not int or self.root_fd < 0:
            raise RunnerError("trusted root descriptor is closed")
        observed = PinnedDirectory._walk(path)
        if observed != edges:
            raise RunnerError("trusted root or ancestor changed")
        retained = os.fstat(self.root_fd)
        if (retained.st_dev, retained.st_ino, retained.st_mode, retained.st_uid) != edges[-1][1]:
            raise RunnerError("trusted root descriptor changed")
        if private and (observed[-1][1][2] & 0o077):
            raise RunnerError("control root permissions changed")

    def read_relative(self, relative: str, *, maximum: int = _MAX_CAPTURE_BYTES) -> bytes:
        """Read one single-link regular descendant through the retained root."""

        if type(maximum) is not int or maximum < 0:
            raise RunnerError("invalid pinned read bound")
        PinnedDirectory.verify(self)
        parts = PinnedDirectory._relative_parts(relative)
        directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        file_flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        directory = os.dup(self.root_fd)
        file_fd: int | None = None
        try:
            for part in parts[:-1]:
                before = os.stat(part, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
                    raise RunnerError("unsafe pinned capture ancestor")
                child = os.open(part, directory_flags, dir_fd=directory)
                try:
                    after = os.fstat(child)
                    named = os.stat(part, dir_fd=directory, follow_symlinks=False)
                    expected = (before.st_dev, before.st_ino, before.st_mode, before.st_uid)
                    if ((after.st_dev, after.st_ino, after.st_mode, after.st_uid) != expected
                            or (named.st_dev, named.st_ino, named.st_mode, named.st_uid) != expected):
                        raise RunnerError("pinned capture ancestor changed while opened")
                except BaseException:
                    os.close(child)
                    raise
                os.close(directory)
                directory = child
            before = os.stat(parts[-1], dir_fd=directory, follow_symlinks=False)
            if (stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode)
                    or before.st_nlink != 1):
                raise RunnerError("unsafe pinned capture artifact")
            file_fd = os.open(parts[-1], file_flags, dir_fd=directory)
            opened = os.fstat(file_fd)
            named = os.stat(parts[-1], dir_fd=directory, follow_symlinks=False)
            expected = PinnedDirectory._regular_identity(before)
            if (PinnedDirectory._regular_identity(opened) != expected
                    or PinnedDirectory._regular_identity(named) != expected):
                raise RunnerError("pinned capture artifact changed while opened")
            chunks: list[bytes] = []
            total = 0
            while True:
                chunk = os.read(file_fd, min(1 << 20, maximum - total + 1))
                if not chunk:
                    break
                total += len(chunk)
                if total > maximum:
                    raise RunnerError("pinned capture artifact exceeds size limit")
                chunks.append(chunk)
            after = os.fstat(file_fd)
            named_after = os.stat(parts[-1], dir_fd=directory, follow_symlinks=False)
            if (PinnedDirectory._regular_identity(after) != expected
                    or PinnedDirectory._regular_identity(named_after) != expected):
                raise RunnerError("pinned capture artifact changed while read")
            return b"".join(chunks)
        except OSError as error:
            raise RunnerError("pinned capture artifact unavailable") from error
        finally:
            if file_fd is not None:
                os.close(file_fd)
            os.close(directory)
            # Check both public ancestry and retained descriptor after the
            # read.  A changed root turns the whole run incomplete.
            PinnedDirectory.verify(self)

    def create_private_child(self, prefix: str) -> "PinnedDirectory":
        """Create one exclusive private child while this root remains pinned."""

        if (type(prefix) is not str or not prefix or any(
                character not in "abcdefghijklmnopqrstuvwxyz0123456789.-_"
                for character in prefix)):
            raise RunnerError("invalid private stage prefix")
        PinnedDirectory.verify(self)
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        for _attempt in range(16):
            name = prefix + uuid.uuid4().hex
            try:
                os.mkdir(name, 0o700, dir_fd=self.root_fd)
            except FileExistsError:
                continue
            except OSError as error:
                raise RunnerError("cannot create private diagnostic stage") from error
            try:
                created = os.stat(name, dir_fd=self.root_fd, follow_symlinks=False)
                if stat.S_ISLNK(created.st_mode) or not stat.S_ISDIR(created.st_mode):
                    raise RunnerError("private diagnostic stage is unsafe")
                created_identity = (created.st_dev, created.st_ino, created.st_mode, created.st_uid)
                os.fsync(self.root_fd)
                sealed = os.stat(name, dir_fd=self.root_fd, follow_symlinks=False)
                if (sealed.st_dev, sealed.st_ino, sealed.st_mode, sealed.st_uid) != created_identity:
                    raise RunnerError("private diagnostic stage changed before retention")
                child_fd = os.open(name, flags, dir_fd=self.root_fd)
                try:
                    opened = os.fstat(child_fd)
                    named = os.stat(name, dir_fd=self.root_fd, follow_symlinks=False)
                    if ((opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid) != created_identity
                            or (named.st_dev, named.st_ino, named.st_mode, named.st_uid)
                            != created_identity):
                        raise RunnerError("private diagnostic stage changed while retained")
                    if opened.st_mode & 0o077:
                        raise RunnerError("private diagnostic stage is not private")
                    PinnedDirectory.verify(self)
                    child_path = self.path / name
                    child = object.__new__(PinnedDirectory)
                    object.__setattr__(child, "path", child_path)
                    object.__setattr__(
                        child, "edges", self.edges + ((str(child_path), created_identity),),
                    )
                    object.__setattr__(child, "private", True)
                    object.__setattr__(child, "root_fd", child_fd)
                    child_fd = -1
                    return child
                finally:
                    if child_fd >= 0:
                        os.close(child_fd)
            except OSError as error:
                raise RunnerError("cannot seal private diagnostic stage") from error
        raise RunnerError("cannot allocate private diagnostic stage")

    def write_relative_exclusive(self, relative: str, raw: bytes) -> tuple[int, int, int, int, int, int, int, int]:
        """Descriptor-write one existing private descendant and return its identity."""

        if type(raw) is not bytes:
            raise RunnerError("invalid private staged artifact")
        PinnedDirectory.verify(self)
        parts = PinnedDirectory._relative_parts(relative)
        directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        directory = os.dup(self.root_fd)
        file_fd: int | None = None
        try:
            for part in parts[:-1]:
                named = os.stat(part, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISLNK(named.st_mode) or not stat.S_ISDIR(named.st_mode):
                    raise RunnerError("unsafe private staged artifact ancestor")
                child = os.open(part, directory_flags, dir_fd=directory)
                try:
                    opened = os.fstat(child)
                    after = os.stat(part, dir_fd=directory, follow_symlinks=False)
                    expected = (named.st_dev, named.st_ino, named.st_mode, named.st_uid)
                    if ((opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid) != expected
                            or (after.st_dev, after.st_ino, after.st_mode, after.st_uid) != expected):
                        raise RunnerError("private staged artifact ancestor changed while opened")
                except BaseException:
                    os.close(child)
                    raise
                os.close(directory)
                directory = child
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
            file_fd = os.open(parts[-1], flags, 0o600, dir_fd=directory)
            offset = 0
            while offset < len(raw):
                offset += os.write(file_fd, raw[offset:])
            os.fsync(file_fd)
            opened = os.fstat(file_fd)
            named = os.stat(parts[-1], dir_fd=directory, follow_symlinks=False)
            identity = PinnedDirectory._regular_identity(opened)
            if identity != PinnedDirectory._regular_identity(named) or opened.st_nlink != 1:
                raise RunnerError("private staged artifact changed while written")
            os.fsync(directory)
            return identity
        except OSError as error:
            raise RunnerError("cannot create private staged artifact") from error
        finally:
            if file_fd is not None:
                os.close(file_fd)
            os.close(directory)
            PinnedDirectory.verify(self)

    def snapshot_relative(self, relative: str) -> tuple[bytes, tuple[int, int, int, int, int, int, int, int]]:
        """Freeze bytes and identity from one no-follow descriptor read."""

        PinnedDirectory.verify(self)
        parts = PinnedDirectory._relative_parts(relative)
        directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        file_flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        directory = os.dup(self.root_fd)
        file_fd: int | None = None
        try:
            for part in parts[:-1]:
                before = os.stat(part, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
                    raise RunnerError("unsafe frozen control artifact ancestor")
                child = os.open(part, directory_flags, dir_fd=directory)
                try:
                    opened = os.fstat(child)
                    named = os.stat(part, dir_fd=directory, follow_symlinks=False)
                    expected_directory = (before.st_dev, before.st_ino, before.st_mode, before.st_uid)
                    if ((opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid) != expected_directory
                            or (named.st_dev, named.st_ino, named.st_mode, named.st_uid)
                            != expected_directory):
                        raise RunnerError("frozen control artifact ancestor changed while opened")
                except BaseException:
                    os.close(child)
                    raise
                os.close(directory)
                directory = child
            before = os.stat(parts[-1], dir_fd=directory, follow_symlinks=False)
            if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
                raise RunnerError("unsafe frozen control artifact")
            expected = PinnedDirectory._regular_identity(before)
            file_fd = os.open(parts[-1], file_flags, dir_fd=directory)
            if PinnedDirectory._regular_identity(os.fstat(file_fd)) != expected:
                raise RunnerError("frozen control artifact changed while opened")
            chunks: list[bytes] = []
            total = 0
            while True:
                chunk = os.read(file_fd, min(1 << 20, _MAX_CAPTURE_BYTES - total + 1))
                if not chunk:
                    break
                total += len(chunk)
                if total > _MAX_CAPTURE_BYTES:
                    raise RunnerError("frozen control artifact exceeds size limit")
                chunks.append(chunk)
            after = os.fstat(file_fd)
            named = os.stat(parts[-1], dir_fd=directory, follow_symlinks=False)
            if (PinnedDirectory._regular_identity(after) != expected
                    or PinnedDirectory._regular_identity(named) != expected):
                raise RunnerError("frozen control artifact changed while read")
            return b"".join(chunks), expected
        except OSError as error:
            raise RunnerError("frozen control artifact unavailable") from error
        finally:
            if file_fd is not None:
                os.close(file_fd)
            os.close(directory)
            PinnedDirectory.verify(self)

    def reverify_snapshot(
        self, relative: str, snapshot: tuple[bytes, tuple[int, int, int, int, int, int, int, int]],
    ) -> None:
        raw, identity = snapshot
        observed_raw, observed_identity = PinnedDirectory.snapshot_relative(self, relative)
        if observed_raw != raw or observed_identity != identity:
            raise RunnerError("frozen control artifact changed before diagnostic adoption")

    def snapshot_tree(self) -> Mapping[str, tuple[int, int, int, int, int, int, int, int]]:
        """Snapshot a private child tree through retained descriptors only."""

        PinnedDirectory.verify(self)
        directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        result: dict[str, tuple[int, int, int, int, int, int, int, int]] = {}

        def descend(directory: int, prefix: str) -> None:
            for name in sorted(os.listdir(directory)):
                relative = name if not prefix else prefix + "/" + name
                named = os.stat(name, dir_fd=directory, follow_symlinks=False)
                if stat.S_ISDIR(named.st_mode) and not stat.S_ISLNK(named.st_mode):
                    child = os.open(name, directory_flags, dir_fd=directory)
                    try:
                        opened = os.fstat(child)
                        after = os.stat(name, dir_fd=directory, follow_symlinks=False)
                        expected = (named.st_dev, named.st_ino, named.st_mode, named.st_uid)
                        if ((opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid) != expected
                                or (after.st_dev, after.st_ino, after.st_mode, after.st_uid) != expected):
                            raise RunnerError("private staged tree changed while opened")
                        result[relative + "/"] = PinnedDirectory._regular_identity(opened)
                        descend(child, relative)
                    finally:
                        os.close(child)
                elif stat.S_ISREG(named.st_mode) and not stat.S_ISLNK(named.st_mode) and named.st_nlink == 1:
                    result[relative] = PinnedDirectory._regular_identity(named)
                else:
                    raise RunnerError("private staged tree is unsafe")

        directory = os.dup(self.root_fd)
        try:
            descend(directory, "")
            return MappingProxyType(result)
        except OSError as error:
            raise RunnerError("private staged tree is unavailable") from error
        finally:
            os.close(directory)
            PinnedDirectory.verify(self)

    def reverify_tree(
        self, snapshot: Mapping[str, tuple[int, int, int, int, int, int, int, int]],
    ) -> None:
        if PinnedDirectory.snapshot_tree(self) != snapshot:
            raise RunnerError("private staged tree changed before diagnostic adoption")

    def close(self) -> None:
        fd = self.root_fd
        if fd >= 0:
            try:
                os.close(fd)
            except OSError:
                pass
            object.__setattr__(self, "root_fd", -1)

    def __del__(self) -> None:  # pragma: no cover - interpreter finalization timing
        try:
            self.close()
        except Exception:
            pass


@dataclass(frozen=True)
class PreparedWorkspace:
    run_root: Path
    workspace: Path
    control_root: Path
    wrapper: Path
    wrapper_seal: WrapperSeal
    control_pin: PinnedDirectory
    workspace_pin: PinnedDirectory
    scenario: dict[str, Any]
    fixture: dict[str, Any]
    # Byte snapshots copied before any phase begins.  Mock-web control assets
    # must never be reread from the mutable source-fixture tree between
    # approval and capture.
    fixture_control_assets: Mapping[str, bytes]


@dataclass(frozen=True)
class _RegisteredActualScenarioFixtureMetadata:
    """One immutable generated scenario/fixture identity for the private bridge.

    ``PreparedWorkspace`` deliberately exposes dictionaries for the generic
    evaluator.  The registered actual bridge must not carry those mutable
    containers across its phase boundaries, so it retains only canonical
    generated scenario bytes and the fixture identity those bytes selected.
    """

    scenario_id: str
    scenario_raw: bytes
    scenario_sha256: str
    fixture_id: str
    fixture_sha256: str

    def __post_init__(self) -> None:
        if (type(self.scenario_id) is not str
                or type(self.scenario_raw) is not bytes
                or type(self.scenario_sha256) is not str
                or type(self.fixture_id) is not str
                or type(self.fixture_sha256) is not str
                or not _is_hex64(self.scenario_sha256)
                or not _is_hex64(self.fixture_sha256)
                or _FIXTURE_IDS.get(self.scenario_id) != self.fixture_id):
            raise RunnerError("registered actual scenario/fixture metadata is invalid")
        value = _strict_json(
            self.scenario_raw,
            label="registered actual frozen scenario",
        )
        if type(value) is not dict:
            raise RunnerError("registered actual scenario/fixture metadata is invalid")
        try:
            canonical = canonical_scenario_bytes(value)
        except (TypeError, ValueError) as error:
            raise RunnerError("registered actual scenario/fixture metadata is invalid") from error
        if (canonical != self.scenario_raw
                or _sha256(canonical) != self.scenario_sha256
                or value.get("id") != self.scenario_id
                or value.get("fixture_id") != self.fixture_id
                # Five generated scenarios are deliberately offline; only the
                # approval/capture scenario is mock-only.  Both modes are
                # closed scenario-contract values, while any other mode must
                # still fail before a registered run can be prepared.
                or value.get("network_mode") not in {"disabled", "mock_only"}):
            raise RunnerError("registered actual scenario/fixture metadata is invalid")

    def scenario(self) -> dict[str, Any]:
        """Return a fresh parsed view of the retained canonical scenario bytes."""

        self.__post_init__()
        value = _strict_json(
            self.scenario_raw,
            label="registered actual frozen scenario",
        )
        if type(value) is not dict:  # defensive: ``__post_init__`` closes this.
            raise RunnerError("registered actual scenario/fixture metadata is invalid")
        return value

    def __reduce__(self) -> object:
        raise TypeError("registered actual scenario/fixture metadata is not serializable")


def _freeze_registered_actual_scenario_fixture_metadata(
    prepared: PreparedWorkspace,
    plan: "RegisteredActualScenarioPlan",
) -> _RegisteredActualScenarioFixtureMetadata:
    """Capture canonical metadata before the registered bridge has phase state."""

    if type(prepared) is not PreparedWorkspace or type(plan) is not RegisteredActualScenarioPlan:
        raise RunnerError("registered actual scenario/fixture metadata is invalid")
    scenario = prepared.scenario
    fixture = prepared.fixture
    if type(scenario) is not dict or type(fixture) is not dict:
        raise RunnerError("registered actual scenario/fixture metadata is invalid")
    fixture_id = scenario.get("fixture_id")
    fixture_sha256 = fixture.get("tree_sha256")
    if (scenario.get("id") != plan.scenario_id
            or fixture.get("scenario_id") != plan.scenario_id
            or type(fixture_id) is not str
            or type(fixture_sha256) is not str
            or not _is_hex64(fixture_sha256)):
        raise RunnerError("registered actual scenario/fixture metadata is invalid")
    try:
        raw = canonical_scenario_bytes(scenario)
    except (TypeError, ValueError) as error:
        raise RunnerError("registered actual scenario/fixture metadata is invalid") from error
    metadata = _RegisteredActualScenarioFixtureMetadata(
        scenario_id=plan.scenario_id,
        scenario_raw=raw,
        scenario_sha256=_sha256(raw),
        fixture_id=fixture_id,
        fixture_sha256=fixture_sha256,
    )
    metadata.__post_init__()
    return metadata


def _seal_wrapper(path: Path) -> WrapperSeal:
    return WrapperSeal(path, _identity(path), _sha256(_safe_read(path)))


def verify_wrapper(seal: WrapperSeal) -> None:
    try:
        identity = _identity(seal.path)
        digest = _sha256(_safe_read(seal.path))
    except RunnerError as error:
        raise RunnerError("wrapper unavailable or unsafe") from error
    if identity != seal.identity or digest != seal.sha256:
        raise RunnerError("wrapper changed during evaluation")


def _seal_control_file(path: Path) -> ControlFileSeal:
    identity = _identity(path)
    if identity["mode"] & 0o077 or identity["nlink"] != 1:
        raise RunnerError("unsafe runner control file")
    return ControlFileSeal(path, identity, _sha256(_safe_read(path)))


def verify_control_file(seal: ControlFileSeal) -> None:
    try:
        identity = _identity(seal.path)
        digest = _sha256(_safe_read(seal.path))
    except RunnerError as error:
        raise RunnerError("runner control file unavailable or unsafe") from error
    if identity != seal.identity or digest != seal.sha256:
        raise RunnerError("runner control file changed during evaluation")


def verify_phase_control(seals: PhaseControlSeals) -> None:
    verify_control_file(seals.config)
    _verify_phase_fixture_assets(seals)


def _verify_phase_fixture_assets(seals: PhaseControlSeals) -> None:
    """Recheck phase assets without treating an intentional config rewrite as safe.

    ``brain-shim.json`` is replaced at each phase boundary, so its prior seal
    cannot survive the call that builds the next phase.  Fixture assets do
    survive.  Rechecking them both immediately before and immediately after
    that rewrite closes the tiny check-to-use interval for a same-byte inode
    replacement.
    """

    for asset_seal, raw in seals.fixture_assets.values():
        if _sha256(raw) != asset_seal.sha256:
            raise RunnerError("fixture control snapshot is internally inconsistent")
        verify_control_file(asset_seal)


def _root_ignore(directory: str, names: list[str]) -> set[str]:
    """Exclude live state and every reusable Python/test cache from a copy.

    The copied tree imports its own ``tests.evals.run_cross_client`` wrapper.
    A timestamp-valid ``__pycache__`` entry from the caller's tree could
    otherwise be chosen by CPython before the copied source is executed.  Do
    not treat caches as benign source inputs: they are prior evaluator output
    and have no generator-owned manifest or host provenance.
    """

    ignored = {
        name for name in names
        if name in {
            "__pycache__", ".pytest_cache", ".ruff_cache", ".mypy_cache",
            ".hypothesis", ".tox", ".nox", ".coverage", "htmlcov",
        }
        or name.endswith((".pyc", ".pyo"))
    }
    # Do not clone a user's live archive.  Nested generated fixtures remain in
    # the code copy, but root-level live data/control roots are excluded too.
    if Path(directory).resolve() == ROOT:
        ignored |= {
            name for name in names
            if name in {".git", ".brain", ".context", "sources", "wiki"}
        }
    return ignored


def _scenario(scenario_id: str) -> dict[str, Any]:
    filename = _SCENARIO_FILENAMES.get(scenario_id)
    if filename is None:
        raise RunnerError("unknown scenario")
    path = SCENARIO_ROOT / filename
    if not path.is_file():
        raise RunnerError("unknown scenario")
    value = _strict_json(path.read_bytes(), label="scenario")
    if type(value) is not dict or value.get("id") != scenario_id:
        raise RunnerError("invalid scenario")
    return value


def _fixture(scenario: Mapping[str, Any]) -> tuple[Path, dict[str, Any]]:
    scenario_id = scenario.get("id")
    expected_fixture_id = _FIXTURE_IDS.get(scenario_id)
    fixture_id = scenario.get("fixture_id")
    if expected_fixture_id is None or fixture_id != expected_fixture_id:
        raise RunnerError("invalid scenario fixture")
    root = FIXTURE_ROOT / expected_fixture_id
    value = _strict_json((root / "fixture-manifest.json").read_bytes(), label="fixture manifest")
    if (type(value) is not dict or value.get("scenario_id") != scenario_id
            or not _is_hex64(value.get("tree_sha256", ""))):
        raise RunnerError("invalid fixture manifest")
    return root, value


def _scenario_ids_for_cli(selection: str) -> tuple[str, ...]:
    """Resolve only a closed single scenario or the fixed all-scenarios list."""

    if selection == "all":
        return KNOWN_SCENARIO_IDS
    if selection not in _SCENARIO_FILENAMES:
        raise RunnerError("unknown scenario")
    return (selection,)


def validate_fixture_overlay(workspace: Path, fixture: Mapping[str, Any]) -> None:
    """Prove the copied archive tree is exactly the generator-owned overlay."""

    expected_raw = fixture.get("paths")
    expected_hash = fixture.get("tree_sha256")
    if type(expected_raw) is not list or type(expected_hash) is not str or not _is_hex64(expected_hash):
        raise RunnerError("invalid fixture overlay manifest")
    expected: list[str] = []
    for item in expected_raw:
        if type(item) is not str or not item.startswith("repo/"):
            raise RunnerError("invalid fixture overlay manifest")
        relative = item.removeprefix("repo/")
        pure = PurePosixPath(relative)
        if not relative or pure.is_absolute() or pure.as_posix() != relative or ".." in pure.parts:
            raise RunnerError("invalid fixture overlay manifest")
        expected.append(relative)
    if expected != sorted(set(expected)):
        raise RunnerError("invalid fixture overlay manifest")

    workspace = workspace.resolve()
    actual: dict[str, Path] = {}
    for top in ("config", "sources", "wiki"):
        root = workspace / top
        if not root.is_dir() or root.is_symlink():
            raise RunnerError("fixture overlay root unavailable")
        for directory, directories, files in os.walk(root, followlinks=False):
            directory_path = Path(directory)
            for name in directories:
                candidate = directory_path / name
                if candidate.is_symlink() or not candidate.is_dir():
                    raise RunnerError("fixture overlay contains unsafe directory")
            for name in files:
                candidate = directory_path / name
                if candidate.is_symlink() or not candidate.is_file():
                    raise RunnerError("fixture overlay contains unsafe file")
                actual[candidate.relative_to(workspace).as_posix()] = candidate
    if sorted(actual) != expected:
        raise RunnerError("fixture overlay paths differ from manifest")
    digest = hashlib.sha256()
    for relative in expected:
        raw = _safe_read(actual[relative])
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        digest.update(_sha256(raw).encode("ascii"))
        digest.update(b"\0")
    if digest.hexdigest() != expected_hash:
        raise RunnerError("fixture overlay hash differs from manifest")


def validate_fixture_source_tree(fixture_repo: Path, fixture: Mapping[str, Any]) -> None:
    """Verify the generator-owned fixture itself before it is overlaid.

    The copied workspace necessarily also contains runner source code, so its
    full tree cannot equal the fixture manifest.  The fixture source tree has
    no such exception: every regular file and directory must be manifest
    accounted for before it can influence an evaluated workspace.
    """

    expected_raw = fixture.get("paths")
    expected_hash = fixture.get("tree_sha256")
    if type(expected_raw) is not list or type(expected_hash) is not str or not _is_hex64(expected_hash):
        raise RunnerError("invalid fixture overlay manifest")
    expected: list[str] = []
    for item in expected_raw:
        if type(item) is not str or not item.startswith("repo/"):
            raise RunnerError("invalid fixture overlay manifest")
        relative = item.removeprefix("repo/")
        pure = PurePosixPath(relative)
        if not relative or pure.is_absolute() or pure.as_posix() != relative or ".." in pure.parts:
            raise RunnerError("invalid fixture overlay manifest")
        expected.append(relative)
    if expected != sorted(set(expected)):
        raise RunnerError("invalid fixture overlay manifest")

    fixture_repo = fixture_repo.resolve()
    root_info = fixture_repo.lstat()
    if fixture_repo.is_symlink() or not stat.S_ISDIR(root_info.st_mode):
        raise RunnerError("fixture overlay root unavailable")
    allowed_directories: set[str] = set()
    for relative in expected:
        parent = PurePosixPath(relative).parent
        while parent != PurePosixPath("."):
            allowed_directories.add(parent.as_posix())
            parent = parent.parent
    actual: dict[str, Path] = {}
    for directory, directories, files in os.walk(fixture_repo, followlinks=False):
        directory_path = Path(directory)
        for name in directories:
            candidate = directory_path / name
            relative = candidate.relative_to(fixture_repo).as_posix()
            if (candidate.is_symlink() or not candidate.is_dir()
                    or relative not in allowed_directories):
                raise RunnerError("fixture overlay contains unsafe directory")
        for name in files:
            candidate = directory_path / name
            if candidate.is_symlink() or not candidate.is_file():
                raise RunnerError("fixture overlay contains unsafe file")
            actual[candidate.relative_to(fixture_repo).as_posix()] = candidate
    if sorted(actual) != expected:
        raise RunnerError("fixture overlay paths differ from manifest")
    digest = hashlib.sha256()
    for relative in expected:
        raw = _safe_read(actual[relative])
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        digest.update(_sha256(raw).encode("ascii"))
        digest.update(b"\0")
    if digest.hexdigest() != expected_hash:
        raise RunnerError("fixture overlay hash differs from manifest")


def _install_wrapper(workspace: Path, control: Path) -> WrapperSeal:
    launcher = workspace / "brain"
    original_identity = _identity(launcher)
    original = _safe_read(launcher)
    if _identity(launcher) != original_identity:
        raise RunnerError("copied launcher changed before wrapper installation")
    _write_private(control / "original-brain.bin", original)
    _write_private(control / "original-brain.json", _canonical_json({
        "identity": original_identity,
        "sha256": _sha256(original),
    }))
    body = (
        f"#!{Path(sys.executable).resolve()}\n"
        "from tests.evals.run_cross_client import shim_entrypoint\n"
        "raise SystemExit(shim_entrypoint())\n"
    ).encode("utf-8")
    launcher.unlink()
    _write_private(launcher, body)
    launcher.chmod(0o700)
    return _seal_wrapper(launcher)


def _runner_git_binary() -> Path:
    """Choose Git only from runner-owned absolute candidates, never PATH."""

    for candidate in _RUNNER_GIT_BINARIES:
        try:
            identity = _identity(candidate)
        except (OSError, RunnerError):
            continue
        if not identity["mode"] & 0o022 and identity["mode"] & 0o111:
            return candidate
    raise RunnerError("private Git initialization unavailable")


def prepare_isolated_workspace(
    scenario_id: str,
    *,
    scratch_root: Path | None = None,
) -> PreparedWorkspace:
    """Create a disposable private fixture workspace without mutating the user brain."""

    scenario = _scenario(scenario_id)
    fixture_root, fixture = _fixture(scenario)
    validate_fixture_source_tree(fixture_root / "repo", fixture)
    # The mock-web fixture is runner input, not a live service.  Capture its
    # exact bytes while setup is still validating the fixture tree, then make
    # every later phase derive control files from this immutable snapshot.
    # In particular, never reopen ``FIXTURE_ROOT`` after the approval phase:
    # it is a shared source tree that a concurrent/test process could replace.
    fixture_control_assets: Mapping[str, bytes] = MappingProxyType({})
    if scenario["network_mode"] == "mock_only":
        captured_assets: dict[str, bytes] = {}
        for name in ("static-shell.html", "rendered-dom.html", "unused-candidate.html"):
            captured_assets[name] = _safe_read(fixture_root / name)
        fixture_control_assets = MappingProxyType(captured_assets)
    if scratch_root is None:
        run_root = Path(tempfile.mkdtemp(prefix="second-brain-eval-"))
    else:
        scratch_root = scratch_root.resolve()
        scratch_root.mkdir(mode=0o700, parents=True, exist_ok=True)
        run_root = Path(tempfile.mkdtemp(prefix="second-brain-eval-", dir=scratch_root))
    run_root.chmod(0o700)
    workspace = run_root / "workspace"
    control = run_root / "control"
    control.mkdir(mode=0o700)
    # A fresh tree retains source code only.  The overlay is the sole archive.
    # Preserve the canonical agent-instruction links.  Dereferencing them
    # turns the copied checkout into an invalid brain (and makes its own
    # ``validate`` command fail) before a client is ever launched.
    shutil.copytree(
        ROOT, workspace, ignore=_root_ignore, copy_function=shutil.copy2,
        symlinks=True,
    )
    for name in (".git", ".brain", "sources", "wiki"):
        target = workspace / name
        if target.exists() or target.is_symlink():
            if target.is_dir() and not target.is_symlink():
                shutil.rmtree(target)
            else:
                target.unlink()
    # A source checkout can itself contain prior evaluator output.  It is not
    # fixture input and must never be visible to the evaluated client.
    prior_runs = workspace / "tests" / "evals" / "runs"
    if prior_runs.exists() or prior_runs.is_symlink():
        if prior_runs.is_dir() and not prior_runs.is_symlink():
            shutil.rmtree(prior_runs)
        else:
            prior_runs.unlink()
    shutil.copytree(fixture_root / "repo", workspace, dirs_exist_ok=True, copy_function=shutil.copy2)
    validate_fixture_overlay(workspace, fixture)
    paths = RepoPaths.discover(workspace)
    records = LedgerStore(paths).load_all()
    restore_scenario_metadata(paths, records)
    git_home = control / "git-home"
    git_home.mkdir(mode=0o700)
    git_binary = _runner_git_binary()
    git_environment = {
        "HOME": str(git_home),
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
        "PATH": "/usr/bin:/bin",
        "GIT_CONFIG_NOSYSTEM": "1",
        "GIT_CONFIG_GLOBAL": os.devnull,
        "GIT_TEMPLATE_DIR": "",
    }
    try:
        subprocess.run(
            [str(git_binary), "-c", "init.templateDir=", "-c", "core.hooksPath=", "init", "-q"],
            cwd=workspace, env=git_environment, stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True,
        )
    except (OSError, subprocess.CalledProcessError) as error:
        raise RunnerError("private Git initialization failed") from error
    seal = _install_wrapper(workspace, control)
    workspace = workspace.resolve()
    control = control.resolve()
    if control.is_relative_to(workspace) or workspace.is_relative_to(control):
        raise RunnerError("workspace and control root must be disjoint")
    return PreparedWorkspace(
        run_root, workspace, control, seal.path.resolve(), seal,
        PinnedDirectory.pin(control, private=True), PinnedDirectory.pin(workspace, private=False),
        scenario, fixture, fixture_control_assets,
    )


class SharedTrace:
    """In-memory, contiguous trace used by focused tests and pure normalizing code."""

    def __init__(self, *, run_id: str, execution_id: str) -> None:
        self.run_id = run_id
        self.execution_id = execution_id
        self._records: list[dict[str, Any]] = []

    def _append(self, kind: str, **fields: Any) -> int:
        sequence = len(self._records) + 1
        self._records.append({"sequence": sequence, "kind": kind, **fields})
        return sequence

    def command_start(self) -> str:
        command_id = f"shim-command-{len(self._records) + 1:08d}"
        self._append("command_start", command_id=command_id)
        return command_id

    def source_state(self, command_id: str, source_state_id: str) -> int:
        return self._append("source_state", command_id=command_id, source_state_id=source_state_id)

    def command_end(self, command_id: str) -> int:
        return self._append("command_end", command_id=command_id)

    def native_record(self, raw: bytes, *, transcript_id: str = "transcript", byte_start: int = 0) -> int:
        sequence = len(self._records) + 1
        return self._append(
            "native_record", transcript_id=transcript_id, byte_start=byte_start,
            byte_end=byte_start + len(raw), sha256=_sha256(raw),
            # Pure parser tests have no evidence writer.  They still model
            # the production row shape so validation cannot accidentally
            # bless an unbound native record.
            workspace_snapshot_id=f"shared-snapshot-{sequence}",
        )

    def records(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._records]


def validate_trace_records(
    records: Sequence[Mapping[str, Any]], *, complete: bool = True
) -> None:
    """Reject gaps, duplicated ownership, and malformed host ordering records.

    The locked writer validates prefixes between a command's start and end;
    callers sealing an execution use the default complete form.
    """

    if not records or [item.get("sequence") for item in records] != list(range(1, len(records) + 1)):
        raise RunnerError("trace sequence is not contiguous")
    open_commands: set[str] = set()
    closed_commands: set[str] = set()
    for item in records:
        kind = item.get("kind")
        if kind == "command_start":
            command_id = item.get("command_id")
            if type(command_id) is not str or command_id in open_commands | closed_commands:
                raise RunnerError("trace command start invalid")
            open_commands.add(command_id)
        elif kind == "source_state":
            source_state = item.get("source_state_id")
            capture_path = item.get("capture_path")
            if (item.get("command_id") not in open_commands
                    or (type(source_state) is str) == (type(capture_path) is str)):
                raise RunnerError("trace source-state ordering invalid")
        elif kind == "command_end":
            command_id = item.get("command_id")
            if command_id not in open_commands:
                raise RunnerError("trace command end invalid")
            open_commands.remove(command_id)
            closed_commands.add(command_id)
        elif kind == "native_record":
            expected = {
                "sequence", "kind", "transcript_id", "byte_start", "byte_end", "sha256",
                "workspace_snapshot_id",
            }
            if (set(item) != expected
                    or type(item.get("transcript_id")) is not str or not item["transcript_id"]
                    or type(item.get("workspace_snapshot_id")) is not str
                    or not item["workspace_snapshot_id"]
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in item["workspace_snapshot_id"])
                    or type(item.get("byte_start")) is not int
                    or type(item.get("byte_end")) is not int or item["byte_start"] < 0
                    or item["byte_end"] < item["byte_start"] or not _is_hex64(item.get("sha256", ""))):
                raise RunnerError("trace native-record invalid")
        else:
            raise RunnerError("trace record kind invalid")
    if complete and open_commands:
        raise RunnerError("trace command remained open")


_ControlTraceSnapshot = tuple[
    bytes, tuple[int, int, int, int, int, int, int, int],
]


def _valid_regular_identity(value: object) -> bool:
    return (
        type(value) is tuple
        and len(value) == 8
        and all(type(item) is int for item in value)
        and value[4] == 1
        and value[5] >= 0
    )


def _regular_file_identity(info: os.stat_result) -> tuple[int, int, int, int, int, int, int, int]:
    """Use the same descriptor identity shape as ``PinnedDirectory``."""

    return (
        info.st_dev,
        info.st_ino,
        info.st_mode,
        info.st_uid,
        info.st_nlink,
        info.st_size,
        info.st_mtime_ns,
        info.st_ctime_ns,
    )


def _private_fd_path_identity(
    path: Path,
    descriptor: int,
) -> tuple[int, int, int, int, int, int, int, int]:
    """Require a private writer fd and its current pathname to be one file."""

    opened = os.fstat(descriptor)
    named = path.stat(follow_symlinks=False)
    identity = _regular_file_identity(opened)
    if (
        not stat.S_ISREG(opened.st_mode)
        or opened.st_nlink != 1
        or stat.S_ISLNK(named.st_mode)
        or not stat.S_ISREG(named.st_mode)
        or named.st_nlink != 1
        or identity != _regular_file_identity(named)
    ):
        raise RunnerError("private receipt path changed while written")
    return identity


def _private_fd_digest(
    descriptor: int,
    *,
    start: int,
    byte_count: int,
) -> tuple[str, int, bool]:
    """Hash one exact descriptor range without retaining its raw bytes."""

    if start < 0 or byte_count < 0:
        raise RunnerError("private receipt range is invalid")
    digest = hashlib.sha256()
    offset = start
    remaining = byte_count
    rows = 0
    terminated = byte_count == 0
    while remaining:
        chunk = os.pread(descriptor, min(65_536, remaining), offset)
        if not chunk:
            raise RunnerError("private receipt file shortened while read")
        digest.update(chunk)
        rows += chunk.count(b"\n")
        terminated = chunk.endswith(b"\n")
        offset += len(chunk)
        remaining -= len(chunk)
    return digest.hexdigest(), rows, terminated


@dataclass(frozen=True)
class _ControlTraceWriteReceipt:
    """Private FD-time metadata for one append to a runner trace.

    The receipt contains no trace bytes.  Its parent ledger binds the
    descriptor-time prefix chain to a later pinned trace read, so a same-byte
    pathname replacement cannot become a post-launch baseline.
    """

    execution_id: str
    relative_path: str
    sequence: int
    kind: str
    row_sha256: str
    row_bytes: int
    prior_sha256: str
    prior_bytes: int
    prior_identity: tuple[int, int, int, int, int, int, int, int]
    completed_sha256: str
    completed_bytes: int
    completed_identity: tuple[int, int, int, int, int, int, int, int]
    prior_rows: int
    completed_rows: int

    def __post_init__(self) -> None:
        relative = PurePosixPath(self.relative_path) if type(self.relative_path) is str else None
        digest_values = (
            self.row_sha256,
            self.prior_sha256,
            self.completed_sha256,
        )
        count_values = (
            self.sequence,
            self.row_bytes,
            self.prior_bytes,
            self.completed_bytes,
            self.prior_rows,
            self.completed_rows,
        )
        if (
            type(self.execution_id) is not str
            or not self.execution_id
            or type(self.kind) is not str
            or not self.kind
            or relative is None
            or relative.is_absolute()
            or relative.as_posix() != self.relative_path
            or not relative.parts
            or any(part in {"", ".", ".."} for part in relative.parts)
            or any(not _is_hex64(value) for value in digest_values)
            or any(type(value) is not int or value < 0 for value in count_values)
            or self.sequence <= 0
            or self.row_bytes <= 0
            or not _valid_regular_identity(self.prior_identity)
            or not _valid_regular_identity(self.completed_identity)
            or self.prior_identity[5] != self.prior_bytes
            or self.completed_identity[5] != self.completed_bytes
            or self.prior_identity[:5] != self.completed_identity[:5]
            or self.completed_bytes != self.prior_bytes + self.row_bytes
            or self.completed_rows != self.prior_rows + 1
        ):
            raise RunnerError("private trace write receipt is invalid")


_ControlTraceReceiptSink = Callable[[_ControlTraceWriteReceipt], None]


def _validated_control_trace_snapshot(value: object) -> _ControlTraceSnapshot | None:
    """Type-check one private trace transition receipt."""

    if value is None:
        return None
    if (type(value) is not tuple or len(value) != 2
            or type(value[0]) is not bytes
            or type(value[1]) is not tuple or len(value[1]) != 8
            or any(type(item) is not int for item in value[1])):
        raise RunnerError("expected native trace transition is invalid")
    return value


class ControlTraceWriter:
    """A file-locked, single sequence allocator shared by shim and pipe reader."""

    def __init__(
        self,
        control_root: Path,
        execution_id: str,
        *,
        control_pin: PinnedDirectory | None = None,
        trace_receipt_sink: _ControlTraceReceiptSink | None = None,
    ) -> None:
        self.control_root = control_root.resolve()
        if control_pin is not None and control_pin.path != self.control_root:
            raise RunnerError("trace control pin mismatch")
        if trace_receipt_sink is not None and not callable(trace_receipt_sink):
            raise RunnerError("trace receipt sink is invalid")
        self.control_pin = control_pin
        # This is a default-off private seam.  It is armed only by the
        # disconnected phase-two receipt-ledger path and never adds a trace
        # field, control schema, CLI argument, or public artifact.
        self._trace_receipt_sink = trace_receipt_sink
        # The historical expected-native helper intentionally has the narrow
        # ``(expected, line)`` seam used by hostile-race tests.  An armed
        # caller places bounded receipt metadata here while holding the trace
        # lock so the original helper can emit its receipt before closing its
        # producer fd, without changing that seam's call signature.
        self._armed_native_trace_receipt_context: tuple[int, str] | None = None
        self.execution_id = execution_id
        self.path = self.control_root / f"runner-trace-{execution_id}.jsonl"
        self.lock_path = self.control_root / ".runner-trace.lock"

    def _emit_trace_receipt(self, receipt: _ControlTraceWriteReceipt) -> None:
        sink = self._trace_receipt_sink
        if sink is None:
            return
        try:
            # The caller keeps the just-written trace fd open throughout this
            # callback.  A receiver gets metadata only, never trace bytes or
            # the writable descriptor.
            sink(receipt)
        except Exception as error:
            raise RunnerError("private trace receipt sink failed") from error

    def _arm_private_trace_receipts(self, sink: _ControlTraceReceiptSink) -> None:
        """Install the phase-two-only sink before any trace row can exist."""

        if (not callable(sink) or self._trace_receipt_sink is not None
                or self.path.exists()):
            raise RunnerError("private trace receipt sink cannot be armed")
        self._trace_receipt_sink = sink

    def _receipt_trace_snapshot(self) -> _ControlTraceSnapshot | None:
        """Read one full no-follow trace snapshot for an armed append.

        This private helper is intentionally unused in the legacy branch so
        existing default trace writes retain their historical bytes and I/O
        shape.  The surrounding trace lock serializes normal writers; the
        descriptor/path comparisons make a hostile pathname swap fail closed.
        """

        try:
            named_before = self.path.stat(follow_symlinks=False)
        except FileNotFoundError:
            return None
        except OSError as error:
            raise RunnerError("private trace receipt is unavailable") from error
        if stat.S_ISLNK(named_before.st_mode) or not stat.S_ISREG(named_before.st_mode):
            raise RunnerError("private trace receipt path is unsafe")
        descriptor: int | None = None
        try:
            descriptor = os.open(
                self.path,
                os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
            )
            opened = os.fstat(descriptor)
            expected = _regular_file_identity(named_before)
            if (
                not stat.S_ISREG(opened.st_mode)
                or opened.st_nlink != 1
                or _regular_file_identity(opened) != expected
            ):
                raise RunnerError("private trace receipt changed while opened")
            chunks: list[bytes] = []
            total = 0
            while True:
                chunk = os.read(descriptor, min(1 << 20, _MAX_CAPTURE_BYTES - total + 1))
                if not chunk:
                    break
                total += len(chunk)
                if total > _MAX_CAPTURE_BYTES:
                    raise RunnerError("private trace receipt exceeds size limit")
                chunks.append(chunk)
            after = os.fstat(descriptor)
            named_after = self.path.stat(follow_symlinks=False)
            if (
                _regular_file_identity(after) != expected
                or _regular_file_identity(named_after) != expected
            ):
                raise RunnerError("private trace receipt changed while read")
            return b"".join(chunks), expected
        except OSError as error:
            raise RunnerError("private trace receipt is unavailable") from error
        finally:
            if descriptor is not None:
                os.close(descriptor)

    def _append_receipted_trace(
        self,
        prior: _ControlTraceSnapshot | None,
        line: bytes,
        *,
        sequence: int,
        kind: str,
    ) -> _ControlTraceSnapshot:
        """Append and receipt one trace row while both writer fds stay live."""

        if (type(line) is not bytes or line.count(b"\n") != 1 or not line.endswith(b"\n")
                or type(sequence) is not int or sequence <= 0
                or type(kind) is not str or not kind):
            raise RunnerError("private trace receipt append is invalid")
        prior_raw = b"" if prior is None else prior[0]
        if (prior is not None and (
                type(prior_raw) is not bytes
                or not _valid_regular_identity(prior[1])
                or prior[1][5] != len(prior_raw)
        )):
            raise RunnerError("private trace receipt predecessor is invalid")
        flags = os.O_RDWR | os.O_APPEND | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        flags |= os.O_CREAT | os.O_EXCL if prior is None else 0
        descriptor: int | None = None
        try:
            descriptor = os.open(self.path, flags, 0o600)
            prior_identity = _private_fd_path_identity(self.path, descriptor)
            if (
                prior is not None and prior_identity != prior[1]
                or prior is None and prior_identity[5] != 0
            ):
                raise RunnerError("private trace receipt changed before append")
            observed_prior = os.pread(descriptor, len(prior_raw) + 1, 0)
            if observed_prior != prior_raw:
                raise RunnerError("private trace receipt prefix changed before append")
            offset = 0
            while offset < len(line):
                written = os.write(descriptor, line[offset:])
                if written <= 0:
                    raise RunnerError("private trace receipt write did not advance")
                offset += written
            os.fsync(descriptor)
            completed_identity = _private_fd_path_identity(self.path, descriptor)
            expected_raw = prior_raw + line
            observed = os.pread(descriptor, len(expected_raw) + 1, 0)
            if (
                completed_identity[:5] != prior_identity[:5]
                or completed_identity[5] != len(expected_raw)
                or observed != expected_raw
                or _private_fd_path_identity(self.path, descriptor) != completed_identity
            ):
                raise RunnerError("private trace receipt changed while appended")
            prior_sha256, prior_rows, prior_terminated = _private_fd_digest(
                descriptor, start=0, byte_count=len(prior_raw),
            )
            # The first digest is intentionally taken from the still-open fd
            # after exact-prefix comparison.  It must agree with the known
            # predecessor bytes, otherwise a replacement cannot become the
            # sidecar's baseline.
            if (
                prior_sha256 != _sha256(prior_raw)
                or not prior_terminated
                or prior_rows != prior_raw.count(b"\n")
            ):
                raise RunnerError("private trace receipt prefix changed while appended")
            completed_sha256, completed_rows, completed_terminated = _private_fd_digest(
                descriptor, start=0, byte_count=len(expected_raw),
            )
            if (
                completed_sha256 != _sha256(expected_raw)
                or completed_rows != prior_rows + 1
                or not completed_terminated
                or _private_fd_path_identity(self.path, descriptor) != completed_identity
            ):
                raise RunnerError("private trace receipt changed while appended")
            receipt = _ControlTraceWriteReceipt(
                execution_id=self.execution_id,
                relative_path=self.path.name,
                sequence=sequence,
                kind=kind,
                row_sha256=_sha256(line),
                row_bytes=len(line),
                prior_sha256=prior_sha256,
                prior_bytes=len(prior_raw),
                prior_identity=prior_identity,
                completed_sha256=completed_sha256,
                completed_bytes=len(expected_raw),
                completed_identity=completed_identity,
                prior_rows=prior_rows,
                completed_rows=completed_rows,
            )
            self._emit_trace_receipt(receipt)
            return expected_raw, completed_identity
        except OSError as error:
            raise RunnerError("private trace receipt append is unavailable") from error
        finally:
            if descriptor is not None:
                os.close(descriptor)

    def _append_expected_native_trace(
        self,
        expected: _ControlTraceSnapshot | None,
        line: bytes,
    ) -> _ControlTraceSnapshot:
        """Append one native row from a retained trace transition receipt.

        The generic trace writer normally supports ordinary legacy callers.
        The disconnected phase-two route supplies an exact prior snapshot,
        which lets this narrow branch reject a trace replacement between the
        snapshot capture and the append itself.  On the first native row it
        uses exclusive descriptor-relative creation, so a foreign trace can
        never become that row's initial identity.
        """

        control_pin = self.control_pin
        if (not isinstance(control_pin, PinnedDirectory)
                or control_pin.path != self.control_root
                or type(line) is not bytes or not line):
            raise RunnerError("expected native trace transition is invalid")
        # This branch opens through ``root_fd`` directly instead of one of
        # PinnedDirectory's public read/write helpers.  Validate the retained
        # descriptor immediately before that raw-FD use so a mutable facade
        # cannot substitute a foreign directory between trace checkpoints.
        PinnedDirectory.verify(control_pin)
        if expected is None:
            prior_raw = b""
            flags = (
                os.O_RDWR | os.O_APPEND | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0)
            )
        else:
            prior_raw, prior_identity = expected
            if (type(prior_raw) is not bytes
                    or type(prior_identity) is not tuple or len(prior_identity) != 8
                    or any(type(value) is not int for value in prior_identity)):
                raise RunnerError("expected native trace transition is invalid")
            flags = os.O_RDWR | os.O_APPEND | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        trace_fd: int | None = None
        try:
            trace_fd = os.open(self.path.name, flags, 0o600, dir_fd=control_pin.root_fd)
            opened = os.fstat(trace_fd)
            named = os.stat(self.path.name, dir_fd=control_pin.root_fd, follow_symlinks=False)
            before_identity = PinnedDirectory._regular_identity(opened)
            if (not stat.S_ISREG(opened.st_mode)
                    or opened.st_nlink != 1
                    or before_identity != PinnedDirectory._regular_identity(named)
                    or expected is not None and before_identity != expected[1]
                    or expected is None and opened.st_size != 0):
                raise RunnerError("expected native trace changed before append")
            offset = 0
            while offset < len(line):
                offset += os.write(trace_fd, line[offset:])
            os.fsync(trace_fd)
            opened_after = os.fstat(trace_fd)
            named_after = os.stat(
                self.path.name, dir_fd=control_pin.root_fd, follow_symlinks=False,
            )
            identity = PinnedDirectory._regular_identity(opened_after)
            expected_raw = prior_raw + line
            observed = os.pread(trace_fd, len(expected_raw) + 1, 0)
            if (not stat.S_ISREG(opened_after.st_mode)
                    or opened_after.st_nlink != 1
                    or identity != PinnedDirectory._regular_identity(named_after)
                    or opened_after.st_size != len(expected_raw)
                    or observed != expected_raw):
                raise RunnerError("expected native trace changed while appended")
            if self._trace_receipt_sink is not None:
                context = self._armed_native_trace_receipt_context
                if (type(context) is not tuple or len(context) != 2
                        or type(context[0]) is not int or context[0] <= 0
                        or type(context[1]) is not str or not context[1]):
                    raise RunnerError("expected native trace receipt is invalid")
                sequence, kind = context
                prior_rows = prior_raw.count(b"\n")
                completed_rows = expected_raw.count(b"\n")
                if (
                    not (not prior_raw or prior_raw.endswith(b"\n"))
                    or completed_rows != prior_rows + 1
                ):
                    raise RunnerError("expected native trace receipt is invalid")
                self._emit_trace_receipt(
                    _ControlTraceWriteReceipt(
                        execution_id=self.execution_id,
                        relative_path=self.path.name,
                        sequence=sequence,
                        kind=kind,
                        row_sha256=_sha256(line),
                        row_bytes=len(line),
                        prior_sha256=_sha256(prior_raw),
                        prior_bytes=len(prior_raw),
                        prior_identity=before_identity,
                        completed_sha256=_sha256(expected_raw),
                        completed_bytes=len(expected_raw),
                        completed_identity=identity,
                        prior_rows=prior_rows,
                        completed_rows=completed_rows,
                    )
                )
            PinnedDirectory.verify(control_pin)
            return observed, identity
        except OSError as error:
            raise RunnerError("expected native trace append unavailable") from error
        finally:
            if trace_fd is not None:
                os.close(trace_fd)

    def _append(
        self,
        kind: str,
        fields: Mapping[str, Any],
        *,
        native_snapshot_factory: Callable[[int], str] | None = None,
        native_snapshot_observer: Callable[[str], None] | None = None,
        expected_trace_provider: Callable[[], _ControlTraceSnapshot | None] | None = None,
        after_native_trace_append: Callable[[_ControlTraceSnapshot], None] | None = None,
    ) -> int:
        if native_snapshot_observer is not None and not callable(native_snapshot_observer):
            raise RunnerError("native workspace snapshot observer is invalid")
        if ((expected_trace_provider is None) != (after_native_trace_append is None)
                or expected_trace_provider is not None and (
                    not callable(expected_trace_provider)
                    or not callable(after_native_trace_append)
                )):
            raise RunnerError("native trace transition observer is invalid")
        guarded_native_trace = expected_trace_provider is not None
        if (guarded_native_trace and (
                kind != "native_record" or native_snapshot_factory is None
                or self.control_pin is None
        )):
            raise RunnerError("native trace transition observer is invalid")
        if self.control_pin is not None:
            PinnedDirectory.verify(self.control_pin)
        if (not guarded_native_trace
                and self.path.exists() and (self.path.is_symlink() or not self.path.is_file())):
            raise RunnerError("unsafe shared trace")
        fd = os.open(self.lock_path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            rows: list[dict[str, Any]] = []
            expected_before: _ControlTraceSnapshot | None = None
            receipt_prior: _ControlTraceSnapshot | None = None
            if guarded_native_trace:
                expected_before = _validated_control_trace_snapshot(expected_trace_provider())
                raw = b"" if expected_before is None else expected_before[0]
                rows = [_strict_json(line, label="shared trace") for line in raw.splitlines()]
                validate_trace_records(rows, complete=False) if rows else None
            elif self.path.exists():
                if self._trace_receipt_sink is not None:
                    receipt_prior = self._receipt_trace_snapshot()
                    if receipt_prior is None:
                        raise RunnerError("private trace receipt disappeared before append")
                    raw = receipt_prior[0]
                else:
                    raw = (
                        PinnedDirectory.read_relative(self.control_pin, self.path.name)
                        if self.control_pin is not None else _safe_read(self.path)
                    )
                rows = [_strict_json(line, label="shared trace") for line in raw.splitlines()]
                validate_trace_records(rows, complete=False) if rows else None
            elif self._trace_receipt_sink is not None:
                # Retain explicit absence: the armed append uses O_EXCL, so a
                # trace planted after this observation cannot become a valid
                # first phase-two trace identity.
                receipt_prior = None
            sequence = len(rows) + 1
            row_fields = dict(fields)
            if native_snapshot_factory is not None:
                if kind != "native_record":
                    raise RunnerError("native snapshot factory used for non-native trace")
                snapshot_id = native_snapshot_factory(sequence)
                if (type(snapshot_id) is not str or not snapshot_id
                        or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                               for character in snapshot_id)):
                    raise RunnerError("native workspace snapshot identity invalid")
                row_fields["workspace_snapshot_id"] = snapshot_id
                if native_snapshot_observer is not None:
                    native_snapshot_observer(snapshot_id)
            elif native_snapshot_observer is not None:
                raise RunnerError("native workspace snapshot observer is invalid")
            row = {"sequence": sequence, "kind": kind, **row_fields}
            line = _line(row)
            if guarded_native_trace:
                expected_after = _validated_control_trace_snapshot(expected_trace_provider())
                if expected_after != expected_before:
                    raise RunnerError("expected native trace changed before append")
                # Existing focused tests deliberately replace this private
                # helper with its historical two-argument seam.  Preserve
                # that call shape even when the receipt sink is armed: the
                # original helper reads lock-scoped private context and emits
                # its FD-time receipt before it closes the trace descriptor.
                if self._trace_receipt_sink is None:
                    receipt = self._append_expected_native_trace(expected_after, line)
                else:
                    if self._armed_native_trace_receipt_context is not None:
                        raise RunnerError("expected native trace receipt is already armed")
                    self._armed_native_trace_receipt_context = (sequence, kind)
                    try:
                        receipt = self._append_expected_native_trace(expected_after, line)
                    finally:
                        self._armed_native_trace_receipt_context = None
                after_native_trace_append(receipt)
            elif self._trace_receipt_sink is not None:
                self._append_receipted_trace(
                    receipt_prior, line, sequence=sequence, kind=kind,
                )
            else:
                with self.path.open("ab", buffering=0) as stream:
                    stream.write(line)
                    stream.flush()
                    os.fsync(stream.fileno())
            if self.control_pin is not None:
                PinnedDirectory.verify(self.control_pin)
            return sequence
        finally:
            fcntl.flock(fd, fcntl.LOCK_UN)
            os.close(fd)

    def append(self, kind: str, **fields: Any) -> int:
        return self._append(kind, fields)

    def append_native_record(
        self,
        *,
        transcript_id: str,
        byte_start: int,
        byte_end: int,
        sha256: str,
        snapshot_factory: Callable[[int], str],
        snapshot_observer: Callable[[str], None] | None = None,
        expected_trace_provider: Callable[[], _ControlTraceSnapshot | None] | None = None,
        after_native_trace_append: Callable[[_ControlTraceSnapshot], None] | None = None,
    ) -> int:
        """Atomically bind an arrived native record to its host snapshot.

        The snapshot has to exist before the native row receives a durable
        sequence.  Holding the shared trace lock across the capture and row
        append prevents a shim command from slipping between that capture and
        the record it is intended to witness.
        """

        return self._append(
            "native_record",
            {
                "transcript_id": transcript_id,
                "byte_start": byte_start,
                "byte_end": byte_end,
                "sha256": sha256,
            },
            native_snapshot_factory=snapshot_factory,
            native_snapshot_observer=snapshot_observer,
            expected_trace_provider=expected_trace_provider,
            after_native_trace_append=after_native_trace_append,
        )

    def records(self) -> list[dict[str, Any]]:
        if not self.path.exists():
            return []
        raw = (
            PinnedDirectory.read_relative(self.control_pin, self.path.name)
            if self.control_pin is not None else _safe_read(self.path)
        )
        rows = [_strict_json(line, label="shared trace") for line in raw.splitlines()]
        validate_trace_records(rows) if rows else None
        return rows


_PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS = frozenset({
    "brain-shim-trace.jsonl",
    "brain-shim-capture-index.jsonl",
    "brain-shim-command-log.jsonl",
    "runner-preapply-manifests.jsonl",
})
_PHASE_ONE_RAW_PREDECESSOR_TARGETS = _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
_PHASE_TWO_RAW_RECEIPT_KIND = "registered_actual_phase_two_raw_write_receipts"
_PHASE_TWO_TRACE_RECEIPT_KIND = "registered_actual_phase_two_private_trace_receipts"


def _private_receipt_identity_from_json(value: object) -> tuple[int, int, int, int, int, int, int, int]:
    """Decode one bounded identity stored in a private receipt row."""

    if (type(value) is not list or len(value) != 8
            or any(type(item) is not int for item in value)):
        raise RunnerError("private receipt identity is invalid")
    identity = tuple(value)
    if not _valid_regular_identity(identity):
        raise RunnerError("private receipt identity is invalid")
    return identity


def _private_receipt_relative_path(value: object) -> str:
    if type(value) is not str:
        raise RunnerError("private receipt path is invalid")
    path = PurePosixPath(value)
    if (not value or path.is_absolute() or path.as_posix() != value or not path.parts
            or any(part in {"", ".", ".."} for part in path.parts)):
        raise RunnerError("private receipt path is invalid")
    return value


def _private_receipt_command_id(value: object) -> str:
    if (type(value) is not str or not re.fullmatch(r"shim-command-[0-9a-f]{32}", value)):
        raise RunnerError("private receipt command identity is invalid")
    return value


def _private_receipt_header(
    *,
    kind: str,
    run_id: str,
    execution_id: str,
    nonce: str,
    raw_prelaunch: Mapping[str, "_PrivateRawFileBaseline | None"] | None = None,
) -> bytes:
    if (kind not in {_PHASE_TWO_RAW_RECEIPT_KIND, _PHASE_TWO_TRACE_RECEIPT_KIND}
            or not _is_hex64(run_id) or execution_id != "execution-2"
            or not re.fullmatch(r"[0-9a-f]{32}", nonce)):
        raise RunnerError("private receipt ledger header is invalid")
    header: dict[str, Any] = {
        "schema_version": 1,
        "kind": kind,
        "run_id": run_id,
        "execution_id": execution_id,
        "nonce": nonce,
    }
    if kind == _PHASE_TWO_RAW_RECEIPT_KIND:
        if raw_prelaunch is None:
            raise RunnerError("private raw receipt ledger header is invalid")
        header["raw_prelaunch"] = _private_raw_prelaunch_payload(raw_prelaunch)
    elif raw_prelaunch is not None:
        raise RunnerError("private trace receipt ledger header is invalid")
    return _line(header)


@dataclass(frozen=True)
class _PrivateRawFileBaseline:
    """Metadata-only pre-launch view of one raw append target."""

    relative_path: str
    sha256: str
    byte_count: int
    identity: tuple[int, int, int, int, int, int, int, int]
    rows: int

    def __post_init__(self) -> None:
        if (self.relative_path not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                or not _is_hex64(self.sha256)
                or type(self.byte_count) is not int or self.byte_count < 0
                or not _valid_regular_identity(self.identity)
                or self.identity[5] != self.byte_count
                or type(self.rows) is not int or self.rows < 0):
            raise RunnerError("private raw receipt baseline is invalid")


@dataclass(frozen=True)
class _RegisteredActualPhaseOneRawPredecessors:
    """Frozen phase-one raw journals that phase two may only append to.

    The phase-one conversion retains the bytes used as later delta prefixes,
    but byte equality alone cannot distinguish a same-byte pathname
    replacement.  This small private companion retains the original
    descriptor identities so phase-two receipt allocation cannot silently
    adopt a new predecessor.
    """

    values: Mapping[str, _PrivateRawFileBaseline | None]

    def __post_init__(self) -> None:
        if not isinstance(self.values, Mapping) or set(self.values) != _PHASE_ONE_RAW_PREDECESSOR_TARGETS:
            raise RunnerError("registered actual phase-one raw predecessors are invalid")
        frozen: dict[str, _PrivateRawFileBaseline | None] = {}
        for relative in _PHASE_ONE_RAW_PREDECESSOR_TARGETS:
            baseline = self.values[relative]
            if (baseline is not None
                    and (type(baseline) is not _PrivateRawFileBaseline
                         or baseline.relative_path != relative)):
                raise RunnerError("registered actual phase-one raw predecessors are invalid")
            frozen[relative] = baseline
        if (frozen["brain-shim-capture-index.jsonl"] is None
                or frozen["brain-shim-command-log.jsonl"] is None):
            raise RunnerError("registered actual phase-one raw predecessors are incomplete")
        object.__setattr__(self, "values", MappingProxyType(frozen))

    def verify_current(self, control_pin: PinnedDirectory) -> None:
        """Require the named root files to remain the original phase-one files."""

        self.__post_init__()
        if not isinstance(control_pin, PinnedDirectory) or not control_pin.private:
            raise RunnerError("registered actual phase-one raw predecessor pin is invalid")
        for relative, baseline in self.values.items():
            current = _private_snapshot_optional(control_pin, relative)
            if baseline is None:
                if current is not None:
                    raise RunnerError("registered actual phase-one raw predecessor appeared")
                continue
            if current is None:
                raise RunnerError("registered actual phase-one raw predecessor disappeared")
            raw, identity = current
            if (not raw.endswith(b"\n")
                    or _sha256(raw) != baseline.sha256
                    or len(raw) != baseline.byte_count
                    or identity != baseline.identity
                    or raw.count(b"\n") != baseline.rows):
                raise RunnerError("registered actual phase-one raw predecessor changed")
        PinnedDirectory.verify(control_pin)

    def require_prelaunch_match(
        self,
        raw_prelaunch: Mapping[str, _PrivateRawFileBaseline | None],
    ) -> None:
        """Join allocation's fixed raw baselines to phase one's exact files."""

        self.__post_init__()
        if (not isinstance(raw_prelaunch, Mapping)
                or set(raw_prelaunch) != _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS):
            raise RunnerError("registered actual phase-one raw predecessor match is invalid")
        for relative, expected in self.values.items():
            observed = raw_prelaunch.get(relative)
            if observed != expected:
                raise RunnerError("registered actual phase-one raw predecessor changed before allocation")

    def __reduce__(self) -> object:
        raise TypeError("registered actual phase-one raw predecessors are not serializable")


_RegisteredActualPhaseOneRawPredecessorSnapshot = tuple[
    tuple[
        str,
        str | None,
        int | None,
        tuple[int, int, int, int, int, int, int, int] | None,
        int | None,
    ],
    ...,
]


def _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(
    snapshot: object,
) -> bool:
    """Validate the primitive form retained across the phase-two token."""

    if type(snapshot) is not tuple or len(snapshot) != len(_PHASE_ONE_RAW_PREDECESSOR_TARGETS):
        return False
    expected_paths = sorted(_PHASE_ONE_RAW_PREDECESSOR_TARGETS)
    for expected_relative, row in zip(expected_paths, snapshot):
        if type(row) is not tuple or len(row) != 5:
            return False
        relative, digest, byte_count, identity, rows = row
        if relative != expected_relative:
            return False
        if digest is None:
            if byte_count is not None or identity is not None or rows is not None:
                return False
            continue
        if (type(digest) is not str or not _is_hex64(digest)
                or type(byte_count) is not int or byte_count < 0
                or not _valid_regular_identity(identity)
                or identity[5] != byte_count
                or type(rows) is not int or rows < 0):
            return False
    by_path = dict(zip(expected_paths, snapshot))
    return (
        by_path["brain-shim-capture-index.jsonl"][1] is not None
        and by_path["brain-shim-command-log.jsonl"][1] is not None
    )


def _freeze_registered_actual_phase_one_raw_predecessor_snapshot(
    predecessors: _RegisteredActualPhaseOneRawPredecessors,
) -> _RegisteredActualPhaseOneRawPredecessorSnapshot:
    """Copy phase-one raw-baseline primitives beyond mutable token fields.

    ``values`` is a mapping proxy after normal construction, but a hostile
    in-process seam can replace that frozen dataclass field.  A local tuple
    captured before hydration is the independent comparison point for every
    later raw-journal check in this setup invocation.
    """

    if type(predecessors) is not _RegisteredActualPhaseOneRawPredecessors:
        raise RunnerError("registered actual phase-one raw predecessor snapshot is invalid")
    predecessors.__post_init__()
    frozen: list[
        tuple[
            str,
            str | None,
            int | None,
            tuple[int, int, int, int, int, int, int, int] | None,
            int | None,
        ]
    ] = []
    for relative in sorted(_PHASE_ONE_RAW_PREDECESSOR_TARGETS):
        baseline = predecessors.values[relative]
        if baseline is None:
            frozen.append((relative, None, None, None, None))
            continue
        if type(baseline) is not _PrivateRawFileBaseline:
            raise RunnerError("registered actual phase-one raw predecessor snapshot is invalid")
        baseline.__post_init__()
        frozen.append((
            relative,
            baseline.sha256,
            baseline.byte_count,
            tuple(baseline.identity),
            baseline.rows,
        ))
    snapshot = tuple(frozen)
    if not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(snapshot):
        raise RunnerError("registered actual phase-one raw predecessor snapshot is invalid")
    return snapshot


def _verify_registered_actual_phase_one_raw_predecessor_snapshot(
    predecessors: _RegisteredActualPhaseOneRawPredecessors,
    expected: _RegisteredActualPhaseOneRawPredecessorSnapshot,
) -> None:
    """Reject a replaced raw-baseline token before accepting its path bytes."""

    if (not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(expected)
            or _freeze_registered_actual_phase_one_raw_predecessor_snapshot(predecessors)
            != expected):
        raise RunnerError("registered actual phase-one raw predecessor baseline changed")


def _private_raw_prelaunch_payload(
    value: Mapping[str, _PrivateRawFileBaseline | None],
) -> dict[str, object]:
    """Encode the fixed raw-journal predecessor map into the private header."""

    if not isinstance(value, Mapping) or set(value) != _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        raise RunnerError("private raw receipt prelaunch metadata is invalid")
    result: dict[str, object] = {}
    for relative in sorted(_PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS):
        baseline = value[relative]
        if baseline is None:
            result[relative] = None
            continue
        if type(baseline) is not _PrivateRawFileBaseline or baseline.relative_path != relative:
            raise RunnerError("private raw receipt prelaunch metadata is invalid")
        result[relative] = {
            "sha256": baseline.sha256,
            "byte_count": baseline.byte_count,
            "identity": list(baseline.identity),
            "rows": baseline.rows,
        }
    return result


def _private_raw_prelaunch_from_json(
    value: object,
) -> Mapping[str, _PrivateRawFileBaseline | None]:
    """Decode a child-visible, metadata-only raw-journal predecessor map."""

    if type(value) is not dict or set(value) != _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        raise RunnerError("private raw receipt prelaunch metadata is invalid")
    result: dict[str, _PrivateRawFileBaseline | None] = {}
    for relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        encoded = value[relative]
        if encoded is None:
            result[relative] = None
            continue
        if (type(encoded) is not dict
                or set(encoded) != {"sha256", "byte_count", "identity", "rows"}):
            raise RunnerError("private raw receipt prelaunch metadata is invalid")
        identity = _private_receipt_identity_from_json(encoded["identity"])
        result[relative] = _PrivateRawFileBaseline(
            relative,
            encoded["sha256"],
            encoded["byte_count"],
            identity,
            encoded["rows"],
        )
    return MappingProxyType(result)


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoReceiptLedgerBaseline:
    """One exclusive private receipt header retained across the live phase."""

    relative_path: str
    kind: str
    run_id: str
    execution_id: str
    nonce: str
    header: bytes
    identity: tuple[int, int, int, int, int, int, int, int]
    raw_prelaunch: Mapping[str, _PrivateRawFileBaseline | None] | None = None

    def __post_init__(self) -> None:
        expected_name = {
            _PHASE_TWO_RAW_RECEIPT_KIND: _PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER,
            _PHASE_TWO_TRACE_RECEIPT_KIND: _PHASE_TWO_TRACE_RECEIPT_LEDGER,
        }.get(self.kind)
        if self.kind == _PHASE_TWO_RAW_RECEIPT_KIND:
            normalized_prelaunch = _private_raw_prelaunch_from_json(
                _private_raw_prelaunch_payload(self.raw_prelaunch)
            )
        elif self.raw_prelaunch is not None:
            raise RunnerError("private receipt ledger baseline is invalid")
        else:
            normalized_prelaunch = None
        expected_header = _private_receipt_header(
            kind=self.kind,
            run_id=self.run_id,
            execution_id=self.execution_id,
            nonce=self.nonce,
            raw_prelaunch=normalized_prelaunch,
        )
        if (self.relative_path != expected_name or self.header != expected_header
                or not _valid_regular_identity(self.identity)
                or self.identity[5] != len(self.header)):
            raise RunnerError("private receipt ledger baseline is invalid")
        object.__setattr__(self, "raw_prelaunch", normalized_prelaunch)


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoReceiptLedgers:
    """Private parent retention for the two phase-two receipt channels.

    This object is deliberately non-serializable.  It holds only bounded
    headers, identities, hashes, and tree metadata; it never retains raw shim
    capture bytes or becomes an evidence artifact.
    """

    run_id: str
    execution_id: str
    raw_ledger: _RegisteredActualPhaseTwoReceiptLedgerBaseline
    trace_ledger: _RegisteredActualPhaseTwoReceiptLedgerBaseline
    raw_prelaunch: Mapping[str, _PrivateRawFileBaseline | None]
    prelaunch_tree: Mapping[str, tuple[int, int, int, int, int, int, int, int]]

    def __post_init__(self) -> None:
        if (not _is_hex64(self.run_id) or self.execution_id != "execution-2"
                or type(self.raw_ledger) is not _RegisteredActualPhaseTwoReceiptLedgerBaseline
                or type(self.trace_ledger) is not _RegisteredActualPhaseTwoReceiptLedgerBaseline
                or self.raw_ledger.run_id != self.run_id
                or self.trace_ledger.run_id != self.run_id
                or self.raw_ledger.execution_id != self.execution_id
                or self.trace_ledger.execution_id != self.execution_id
                or self.raw_ledger.kind != _PHASE_TWO_RAW_RECEIPT_KIND
                or self.trace_ledger.kind != _PHASE_TWO_TRACE_RECEIPT_KIND
                or not isinstance(self.raw_prelaunch, Mapping)
                or not isinstance(self.prelaunch_tree, Mapping)
                or set(self.raw_prelaunch) != _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS):
            raise RunnerError("registered actual phase-two receipt ledgers are invalid")
        raw_prelaunch: dict[str, _PrivateRawFileBaseline | None] = {}
        for relative, baseline in self.raw_prelaunch.items():
            if relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
                raise RunnerError("registered actual phase-two receipt ledgers are invalid")
            if baseline is not None and type(baseline) is not _PrivateRawFileBaseline:
                raise RunnerError("registered actual phase-two receipt ledgers are invalid")
            raw_prelaunch[relative] = baseline
        if self.raw_ledger.raw_prelaunch != raw_prelaunch:
            raise RunnerError("registered actual phase-two raw receipt header changed")
        tree: dict[str, tuple[int, int, int, int, int, int, int, int]] = {}
        for relative, identity in self.prelaunch_tree.items():
            if (type(relative) is not str or not relative
                    or type(identity) is not tuple or len(identity) != 8
                    or any(type(item) is not int for item in identity)):
                raise RunnerError("registered actual phase-two receipt ledgers are invalid")
            tree[relative] = identity
        object.__setattr__(self, "raw_prelaunch", MappingProxyType(raw_prelaunch))
        object.__setattr__(self, "prelaunch_tree", MappingProxyType(tree))


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoReceiptLedgerVerification:
    """Ephemeral result of a strict private ledger reread."""

    trace_snapshot: _ControlTraceSnapshot | None
    raw_receipt_paths: frozenset[str]
    raw_snapshots: Mapping[str, _ControlTraceSnapshot]
    raw_absent_paths: frozenset[str]
    raw_append_command_ids: Mapping[str, tuple[str, ...]]

    def __post_init__(self) -> None:
        if type(self.raw_receipt_paths) is not frozenset:
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        receipt_paths: set[str] = set()
        for relative in self.raw_receipt_paths:
            relative = _private_receipt_relative_path(relative)
            if not _private_raw_receipt_target_is_allowed(relative):
                raise RunnerError("registered actual phase-two receipt verification is invalid")
            receipt_paths.add(relative)
        if len(receipt_paths) != len(self.raw_receipt_paths) or not isinstance(self.raw_snapshots, Mapping):
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        snapshots: dict[str, _ControlTraceSnapshot] = {}
        for relative, snapshot in self.raw_snapshots.items():
            relative = _private_receipt_relative_path(relative)
            if not _private_raw_receipt_target_is_allowed(relative):
                raise RunnerError("registered actual phase-two receipt verification is invalid")
            snapshot = _validated_control_trace_snapshot(snapshot)
            if (snapshot is None
                    or not _valid_regular_identity(snapshot[1])
                    or snapshot[1][5] != len(snapshot[0])):
                raise RunnerError("registered actual phase-two receipt verification is invalid")
            if relative in snapshots:
                raise RunnerError("registered actual phase-two receipt verification is invalid")
            snapshots[relative] = snapshot
        if type(self.raw_absent_paths) is not frozenset:
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        absent: set[str] = set()
        for relative in self.raw_absent_paths:
            relative = _private_receipt_relative_path(relative)
            if relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
                raise RunnerError("registered actual phase-two receipt verification is invalid")
            absent.add(relative)
        if (len(absent) != len(self.raw_absent_paths)
                or set(snapshots) & absent
                or not receipt_paths.issubset(snapshots)
                or any(
                    relative not in snapshots and relative not in absent
                    for relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                )
                or any(
                    relative not in receipt_paths
                    and relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                    for relative in snapshots
                )):
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        if not isinstance(self.raw_append_command_ids, Mapping):
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        append_command_ids: dict[str, tuple[str, ...]] = {}
        for relative, command_ids in self.raw_append_command_ids.items():
            relative = _private_receipt_relative_path(relative)
            if (relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                    or relative not in receipt_paths
                    or type(command_ids) is not tuple):
                raise RunnerError("registered actual phase-two receipt verification is invalid")
            for command_id in command_ids:
                _private_receipt_command_id(command_id)
            append_command_ids[relative] = command_ids
        if set(append_command_ids) != receipt_paths & _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        trace = _validated_control_trace_snapshot(self.trace_snapshot)
        if trace is not None and (
                not _valid_regular_identity(trace[1]) or trace[1][5] != len(trace[0])):
            raise RunnerError("registered actual phase-two receipt verification is invalid")
        object.__setattr__(self, "trace_snapshot", trace)
        object.__setattr__(self, "raw_receipt_paths", frozenset(receipt_paths))
        object.__setattr__(self, "raw_snapshots", MappingProxyType(snapshots))
        object.__setattr__(self, "raw_absent_paths", frozenset(absent))
        object.__setattr__(self, "raw_append_command_ids", MappingProxyType(append_command_ids))


def _private_receipt_read_all(descriptor: int) -> bytes:
    """Read one bounded ledger through the descriptor that will be appended."""

    chunks: list[bytes] = []
    offset = 0
    while True:
        chunk = os.pread(descriptor, min(65_536, _MAX_CAPTURE_BYTES - offset + 1), offset)
        if not chunk:
            return b"".join(chunks)
        offset += len(chunk)
        if offset > _MAX_CAPTURE_BYTES:
            raise RunnerError("private receipt ledger exceeds size limit")
        chunks.append(chunk)


def _private_pinned_fd_identity(
    control_pin: PinnedDirectory,
    relative: str,
    descriptor: int,
) -> tuple[int, int, int, int, int, int, int, int]:
    """Require a live fd to remain the pinned root's named single-link file."""

    PinnedDirectory.verify(control_pin)
    opened = os.fstat(descriptor)
    named = os.stat(relative, dir_fd=control_pin.root_fd, follow_symlinks=False)
    identity = _regular_file_identity(opened)
    if (not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1
            or stat.S_ISLNK(named.st_mode) or not stat.S_ISREG(named.st_mode)
            or named.st_nlink != 1 or identity != _regular_file_identity(named)):
        raise RunnerError("private receipt ledger changed while written")
    return identity


def _private_receipt_payload_identity(value: object, *, byte_count: object) -> tuple[int, int, int, int, int, int, int, int]:
    identity = _private_receipt_identity_from_json(value)
    if type(byte_count) is not int or byte_count < 0 or identity[5] != byte_count:
        raise RunnerError("private receipt byte count is invalid")
    return identity


def _validate_private_raw_receipt_payload(value: object) -> None:
    if type(value) is not dict or type(value.get("kind")) is not str:
        raise RunnerError("private raw receipt payload is invalid")
    kind = value["kind"]
    if kind == "write":
        expected = {"kind", "relative_path", "sha256", "byte_count", "identity"}
        if set(value) != expected:
            raise RunnerError("private raw receipt payload is invalid")
        _private_receipt_relative_path(value["relative_path"])
        if not _is_hex64(value["sha256"]):
            raise RunnerError("private raw receipt payload is invalid")
        _private_receipt_payload_identity(value["identity"], byte_count=value["byte_count"])
        return
    if kind != "append":
        raise RunnerError("private raw receipt payload is invalid")
    expected = {
        "kind", "relative_path", "prior_sha256", "prior_bytes", "prior_identity",
        "appended_sha256", "appended_bytes", "completed_sha256", "completed_bytes",
        "completed_identity", "prior_rows", "completed_rows",
    }
    if set(value) != expected:
        raise RunnerError("private raw receipt payload is invalid")
    _private_receipt_relative_path(value["relative_path"])
    if (not all(_is_hex64(value[name]) for name in (
            "prior_sha256", "appended_sha256", "completed_sha256",
    )) or type(value["appended_bytes"]) is not int or value["appended_bytes"] <= 0
            or type(value["prior_rows"]) is not int or value["prior_rows"] < 0
            or type(value["completed_rows"]) is not int
            or value["completed_rows"] != value["prior_rows"] + 1):
        raise RunnerError("private raw receipt payload is invalid")
    prior = _private_receipt_payload_identity(
        value["prior_identity"], byte_count=value["prior_bytes"],
    )
    completed = _private_receipt_payload_identity(
        value["completed_identity"], byte_count=value["completed_bytes"],
    )
    if (completed[:5] != prior[:5]
            or value["completed_bytes"] != value["prior_bytes"] + value["appended_bytes"]):
        raise RunnerError("private raw receipt payload is invalid")


def _validate_private_trace_receipt_payload(value: object) -> None:
    expected = {
        "kind", "execution_id", "relative_path", "sequence", "trace_kind",
        "row_sha256", "row_bytes", "prior_sha256", "prior_bytes", "prior_identity",
        "completed_sha256", "completed_bytes", "completed_identity", "prior_rows",
        "completed_rows",
    }
    if type(value) is not dict or set(value) != expected or value.get("kind") != "trace":
        raise RunnerError("private trace receipt payload is invalid")
    if (value.get("execution_id") != "execution-2"
            or value.get("relative_path") != "runner-trace-execution-2.jsonl"
            or type(value.get("sequence")) is not int or value["sequence"] <= 0
            or type(value.get("trace_kind")) is not str or not value["trace_kind"]
            or not all(_is_hex64(value.get(name)) for name in (
                "row_sha256", "prior_sha256", "completed_sha256",
            )) or type(value.get("row_bytes")) is not int or value["row_bytes"] <= 0
            or type(value.get("prior_rows")) is not int or value["prior_rows"] < 0
            or type(value.get("completed_rows")) is not int
            or value["completed_rows"] != value["prior_rows"] + 1):
        raise RunnerError("private trace receipt payload is invalid")
    prior = _private_receipt_payload_identity(
        value["prior_identity"], byte_count=value.get("prior_bytes"),
    )
    completed = _private_receipt_payload_identity(
        value["completed_identity"], byte_count=value.get("completed_bytes"),
    )
    if (completed[:5] != prior[:5]
            or value["completed_bytes"] != value["prior_bytes"] + value["row_bytes"]):
        raise RunnerError("private trace receipt payload is invalid")


def _validate_private_receipt_ledger_rows(
    raw: bytes,
    baseline: _RegisteredActualPhaseTwoReceiptLedgerBaseline,
) -> tuple[dict[str, Any], ...]:
    """Require canonical chained metadata rows after one exact private header."""

    if type(raw) is not bytes or not raw.startswith(baseline.header):
        raise RunnerError("private receipt ledger header changed")
    tail = raw[len(baseline.header):]
    if not tail:
        return ()
    if not tail.endswith(b"\n"):
        raise RunnerError("private receipt ledger is truncated")
    rows: list[dict[str, Any]] = []
    prefix = baseline.header
    for position, line in enumerate(tail.splitlines(keepends=True), start=1):
        if not line or not line.endswith(b"\n"):
            raise RunnerError("private receipt ledger is truncated")
        value = _strict_json(line[:-1], label="private receipt ledger")
        if type(value) is not dict or _line(value) != line:
            raise RunnerError("private receipt ledger is not canonical")
        expected = {
            "schema_version", "execution_id", "sequence", "sidecar_prior_sha256",
            "sidecar_prior_bytes", "sidecar_prior_rows", "receipt",
        }
        if baseline.kind == _PHASE_TWO_RAW_RECEIPT_KIND:
            expected.add("command_id")
        if (set(value) != expected or value.get("schema_version") != 1
                or value.get("execution_id") != baseline.execution_id
                or value.get("sequence") != position
                or not _is_hex64(value.get("sidecar_prior_sha256"))
                or value.get("sidecar_prior_sha256") != _sha256(prefix)
                or value.get("sidecar_prior_bytes") != len(prefix)
                or value.get("sidecar_prior_rows") != position - 1):
            raise RunnerError("private receipt ledger chain is invalid")
        if baseline.kind == _PHASE_TWO_RAW_RECEIPT_KIND:
            _private_receipt_command_id(value.get("command_id"))
            _validate_private_raw_receipt_payload(value.get("receipt"))
        else:
            _validate_private_trace_receipt_payload(value.get("receipt"))
        rows.append(value)
        prefix += line
    return tuple(rows)


def _raw_receipt_payload(receipt: object) -> dict[str, Any]:
    """Project shim's private objects into a bounded, JSON-safe ledger row."""

    # Deliberately import here: the shim remains independently usable, and
    # this runner-only protocol must not create a public import dependency.
    from tests.evals import brain_shim

    if type(receipt) is brain_shim._RawWriteReceipt:
        return {
            "kind": "write",
            "relative_path": receipt.relative_path,
            "sha256": receipt.sha256,
            "byte_count": receipt.byte_count,
            "identity": list(receipt.identity),
        }
    if type(receipt) is brain_shim._RawAppendReceipt:
        return {
            "kind": "append",
            "relative_path": receipt.relative_path,
            "prior_sha256": receipt.prior_sha256,
            "prior_bytes": receipt.prior_bytes,
            "prior_identity": list(receipt.prior_identity),
            "appended_sha256": receipt.appended_sha256,
            "appended_bytes": receipt.appended_bytes,
            "completed_sha256": receipt.completed_sha256,
            "completed_bytes": receipt.completed_bytes,
            "completed_identity": list(receipt.completed_identity),
            "prior_rows": receipt.prior_rows,
            "completed_rows": receipt.completed_rows,
        }
    raise RunnerError("private raw receipt event is invalid")


def _trace_receipt_payload(receipt: _ControlTraceWriteReceipt) -> dict[str, Any]:
    if type(receipt) is not _ControlTraceWriteReceipt:
        raise RunnerError("private trace receipt event is invalid")
    return {
        "kind": "trace",
        "execution_id": receipt.execution_id,
        "relative_path": receipt.relative_path,
        "sequence": receipt.sequence,
        "trace_kind": receipt.kind,
        "row_sha256": receipt.row_sha256,
        "row_bytes": receipt.row_bytes,
        "prior_sha256": receipt.prior_sha256,
        "prior_bytes": receipt.prior_bytes,
        "prior_identity": list(receipt.prior_identity),
        "completed_sha256": receipt.completed_sha256,
        "completed_bytes": receipt.completed_bytes,
        "completed_identity": list(receipt.completed_identity),
        "prior_rows": receipt.prior_rows,
        "completed_rows": receipt.completed_rows,
    }


class _PrivateReceiptLedgerSink:
    """Append bounded receipt metadata while its raw producer fd is still live."""

    def __init__(
        self,
        control_pin: PinnedDirectory,
        baseline: _RegisteredActualPhaseTwoReceiptLedgerBaseline,
    ) -> None:
        if (not isinstance(control_pin, PinnedDirectory) or not control_pin.private
                or type(baseline) is not _RegisteredActualPhaseTwoReceiptLedgerBaseline):
            raise RunnerError("private receipt ledger sink is invalid")
        current, identity = PinnedDirectory.snapshot_relative(
            control_pin, baseline.relative_path,
        )
        if (identity[:5] != baseline.identity[:5]
                or not current.startswith(baseline.header)):
            raise RunnerError("private receipt ledger sink baseline changed")
        rows = _validate_private_receipt_ledger_rows(current, baseline)
        self._control_pin = control_pin
        self._baseline = baseline
        self._raw_append_predecessors: dict[str, _PrivateRawFileBaseline | None] | None
        self._prepared_raw_appends: dict[str, _PrivateRawFileBaseline | None] = {}
        if baseline.kind != _PHASE_TWO_RAW_RECEIPT_KIND:
            self._raw_append_predecessors = None
            return
        if baseline.raw_prelaunch is None:
            raise RunnerError("private raw receipt sink is missing predecessor metadata")
        predecessors = dict(baseline.raw_prelaunch)
        for row in rows:
            self._advance_raw_append_predecessor(
                row["receipt"], predecessors=predecessors, require_prepare=False,
            )
        self._raw_append_predecessors = predecessors

    @staticmethod
    def _advance_raw_append_predecessor(
        receipt: Mapping[str, Any],
        *,
        predecessors: dict[str, _PrivateRawFileBaseline | None],
        require_prepare: bool,
        prepared: Mapping[str, _PrivateRawFileBaseline | None] | None = None,
    ) -> None:
        """Require one journal receipt to extend the retained predecessor."""

        kind = receipt.get("kind")
        relative = _private_receipt_relative_path(receipt.get("relative_path"))
        if kind == "write":
            if relative in predecessors:
                raise RunnerError("private raw journal was written instead of appended")
            return
        if kind != "append":
            raise RunnerError("private raw receipt kind is invalid")
        if relative not in predecessors:
            raise RunnerError("private raw append target is not registered")
        expected = predecessors[relative]
        if require_prepare and (prepared is None or prepared.get(relative, object()) != expected):
            raise RunnerError("private raw append was not prepared")
        if expected is None:
            if (receipt.get("prior_sha256") != _sha256(b"")
                    or receipt.get("prior_bytes") != 0
                    or receipt.get("prior_rows") != 0):
                raise RunnerError("private raw append predecessor is invalid")
        elif (
            receipt.get("prior_sha256") != expected.sha256
            or receipt.get("prior_bytes") != expected.byte_count
            or receipt.get("prior_rows") != expected.rows
            or tuple(receipt.get("prior_identity", ())) != expected.identity
        ):
            raise RunnerError("private raw append predecessor changed")
        completed_identity = _private_receipt_payload_identity(
            receipt.get("completed_identity"), byte_count=receipt.get("completed_bytes"),
        )
        predecessors[relative] = _PrivateRawFileBaseline(
            relative,
            receipt.get("completed_sha256"),
            receipt.get("completed_bytes"),
            completed_identity,
            receipt.get("completed_rows"),
        )

    def prepare_raw_append(self, relative_path: str) -> object:
        """Return the private shim preflight for one registered raw journal.

        The object is intentionally built only after the child has parsed the
        parent-pinned header.  It is neither serialized into a public artifact
        nor available on unarmed routes.
        """

        if self._baseline.kind != _PHASE_TWO_RAW_RECEIPT_KIND:
            raise RunnerError("private raw append sink is invalid")
        relative = _private_receipt_relative_path(relative_path)
        predecessors = self._raw_append_predecessors
        if predecessors is None or relative not in predecessors:
            raise RunnerError("private raw append target is not registered")
        expected = predecessors[relative]
        self._prepared_raw_appends[relative] = expected
        # Keep the runner protocol independent from the shim at module import
        # time.  The child invokes this only from Recorder's default-off hook.
        from tests.evals import brain_shim

        if expected is None:
            return brain_shim._RawAppendPreflight(
                True, _sha256(b""), 0, None, 0,
            )
        return brain_shim._RawAppendPreflight(
            False,
            expected.sha256,
            expected.byte_count,
            expected.identity,
            expected.rows,
        )

    def _append(self, receipt: dict[str, Any], *, command_id: str | None) -> None:
        baseline = self._baseline
        if baseline.kind == _PHASE_TWO_RAW_RECEIPT_KIND:
            _private_receipt_command_id(command_id)
            _validate_private_raw_receipt_payload(receipt)
        else:
            if command_id is not None:
                raise RunnerError("private trace receipt command identity is invalid")
            _validate_private_trace_receipt_payload(receipt)
        descriptor: int | None = None
        try:
            PinnedDirectory.verify(self._control_pin)
            descriptor = os.open(
                baseline.relative_path,
                os.O_RDWR | os.O_APPEND | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
                dir_fd=self._control_pin.root_fd,
            )
            fcntl.flock(descriptor, fcntl.LOCK_EX)
            before_identity = _private_pinned_fd_identity(
                self._control_pin, baseline.relative_path, descriptor,
            )
            if before_identity[:5] != baseline.identity[:5]:
                raise RunnerError("private receipt ledger was replaced")
            before = _private_receipt_read_all(descriptor)
            rows = _validate_private_receipt_ledger_rows(before, baseline)
            row: dict[str, Any] = {
                "schema_version": 1,
                "execution_id": baseline.execution_id,
                "sequence": len(rows) + 1,
                "sidecar_prior_sha256": _sha256(before),
                "sidecar_prior_bytes": len(before),
                "sidecar_prior_rows": len(rows),
                "receipt": receipt,
            }
            if baseline.kind == _PHASE_TWO_RAW_RECEIPT_KIND:
                assert command_id is not None
                row["command_id"] = command_id
            line = _line(row)
            offset = 0
            while offset < len(line):
                written = os.write(descriptor, line[offset:])
                if written <= 0:
                    raise RunnerError("private receipt ledger write did not advance")
                offset += written
            os.fsync(descriptor)
            after_identity = _private_pinned_fd_identity(
                self._control_pin, baseline.relative_path, descriptor,
            )
            observed = os.pread(descriptor, len(before) + len(line) + 1, 0)
            if (after_identity[:5] != before_identity[:5]
                    or after_identity[5] != len(before) + len(line)
                    or observed != before + line
                    or _private_pinned_fd_identity(
                        self._control_pin, baseline.relative_path, descriptor,
                    ) != after_identity):
                raise RunnerError("private receipt ledger changed while appended")
        except OSError as error:
            raise RunnerError("private receipt ledger is unavailable") from error
        finally:
            if descriptor is not None:
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_UN)
                finally:
                    os.close(descriptor)

    def append_raw(self, receipt: object, *, command_id: str) -> None:
        if self._baseline.kind != _PHASE_TWO_RAW_RECEIPT_KIND:
            raise RunnerError("private raw receipt sink is invalid")
        payload = _raw_receipt_payload(receipt)
        predecessors = self._raw_append_predecessors
        if predecessors is None:
            raise RunnerError("private raw receipt sink is invalid")
        self._advance_raw_append_predecessor(
            payload,
            predecessors=dict(predecessors),
            require_prepare=True,
            prepared=self._prepared_raw_appends,
        )
        self._append(payload, command_id=command_id)
        self._advance_raw_append_predecessor(
            payload,
            predecessors=predecessors,
            require_prepare=True,
            prepared=self._prepared_raw_appends,
        )
        if payload.get("kind") == "append":
            self._prepared_raw_appends.pop(payload["relative_path"], None)

    def append_trace(self, receipt: _ControlTraceWriteReceipt) -> None:
        if self._baseline.kind != _PHASE_TWO_TRACE_RECEIPT_KIND:
            raise RunnerError("private trace receipt sink is invalid")
        self._append(_trace_receipt_payload(receipt), command_id=None)


def _private_optional_raw_baseline(
    control_pin: PinnedDirectory,
    relative: str,
) -> _PrivateRawFileBaseline | None:
    if relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        raise RunnerError("private raw receipt baseline target is invalid")
    try:
        raw, identity = PinnedDirectory.snapshot_relative(control_pin, relative)
    except RunnerError:
        if _pinned_control_capture_is_absent(control_pin, relative):
            return None
        raise
    if not raw.endswith(b"\n") and raw:
        raise RunnerError("private raw receipt baseline is truncated")
    return _PrivateRawFileBaseline(relative, _sha256(raw), len(raw), identity, raw.count(b"\n"))


def _require_private_raw_prelaunch_matches_tree(
    prelaunch_tree: Mapping[str, tuple[int, int, int, int, int, int, int, int]],
    raw_prelaunch: Mapping[str, _PrivateRawFileBaseline | None],
) -> None:
    """Refuse to adopt a raw predecessor observed after the tree baseline.

    The tree is the first pinned pre-Popen observation.  Individual raw
    journal snapshots supply the metadata that will enter the header, but
    they must describe precisely the same files (or absence).  Otherwise a
    replacement between those two reads could become a new child preflight
    baseline before the exclusive ledger headers exist.
    """

    if set(raw_prelaunch) != _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        raise RunnerError("private raw receipt prelaunch map is invalid")
    for relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        baseline = raw_prelaunch[relative]
        tree_identity = prelaunch_tree.get(relative)
        if baseline is None:
            if tree_identity is not None:
                raise RunnerError("private raw receipt predecessor changed before header")
            continue
        if tree_identity != baseline.identity:
            raise RunnerError("private raw receipt predecessor changed before header")


def _allocate_registered_actual_phase_two_receipt_ledgers(
    prepared_run: "_RegisteredActualPreparedRun",
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    prepared_phase: "_RegisteredActualPreparedPhase",
    *,
    expected_raw_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot,
    expected_pre_allocation_control_tree: Mapping[
        str, tuple[int, int, int, int, int, int, int, int],
    ],
    expected_workspace_inventory: _RegisteredActualPhaseTwoWorkspaceInventory,
    launch_binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> _RegisteredActualPhaseTwoReceiptLedgers:
    """Allocate exactly two private headers after the final pre-Popen gate."""

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase != "approved_capture"
            or prepared_phase.prepared_run is not prepared_run
            or prepared_phase.writer is not prepared_run.writer
            or phase_one_diagnostic.prepared_phase.prepared_run is not prepared_run
            or phase_one_diagnostic.prepared_phase.control_pin is not prepared_phase.control_pin
            or prepared_phase.control_pin.path != prepared_run.writer.control_root
            or not prepared_phase.control_pin.private
            or not isinstance(expected_pre_allocation_control_tree, Mapping)
            or type(launch_binding) is not _RegisteredActualPhaseTwoLaunchBinding
            or not _registered_actual_phase_two_workspace_inventory_is_valid(
                expected_workspace_inventory,
            )):
        raise RunnerError("registered actual phase-two receipt allocation is invalid")
    if (launch_binding.prepared_run is not prepared_run
            or launch_binding.phase_one_diagnostic is not phase_one_diagnostic
            or launch_binding.token_control_pin is not prepared_phase.control_pin
            or launch_binding.token_workspace_pin is not prepared_phase.workspace_pin):
        raise RunnerError("registered actual phase-two receipt allocation is invalid")
    if (not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(expected_raw_snapshot)
            or prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot):
        raise RunnerError("registered actual phase-two raw predecessor snapshot changed")
    if (launch_binding.raw_predecessor_snapshot != expected_raw_snapshot
            or launch_binding.workspace_inventory != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained launch token changed")
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    control_pin = launch_binding.control_pin
    PinnedDirectory.verify(control_pin)
    # The pre-Popen gate, rather than this allocator's fresh tree walk, owns
    # the last admissible no-ledger state.  Replaying it before any allocation
    # read prevents a post-gate control mutation from becoming a new header
    # baseline.
    PinnedDirectory.reverify_tree(control_pin, expected_pre_allocation_control_tree)
    _verify_registered_actual_phase_two_workspace_inventory_is_current(
        launch_binding.workspace_pin,
        expected_workspace_inventory,
    )
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        expected_raw_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(control_pin)
    for relative in (_PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER, _PHASE_TWO_TRACE_RECEIPT_LEDGER):
        if not _pinned_control_capture_is_absent(control_pin, relative):
            raise RunnerError("registered actual phase-two receipt ledger already exists")
    if not _pinned_control_capture_is_absent(control_pin, launch_binding.trace.path.name):
        raise RunnerError("registered actual phase-two trace exists before receipt allocation")
    prelaunch_tree = expected_pre_allocation_control_tree
    raw_prelaunch = {
        relative: _private_optional_raw_baseline(control_pin, relative)
        for relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
    }
    _require_private_raw_prelaunch_matches_tree(prelaunch_tree, raw_prelaunch)
    # This comparison is deliberately after the allocation snapshots and
    # before either exclusive header write.  It prevents a same-byte phase-one
    # journal replacement from becoming the predecessor recorded in the
    # child-visible header.
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        expected_raw_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(control_pin)
    phase_one_diagnostic.raw_predecessors.require_prelaunch_match(raw_prelaunch)
    if prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot:
        raise RunnerError("registered actual phase-two raw predecessor snapshot changed")
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        expected_raw_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(control_pin)
    # The raw-predecessor readers above are hostile helper boundaries too.
    # Recheck the retained full tree and workspace immediately before the
    # header bytes are constructed, so they cannot introduce a non-raw
    # control or workspace state that this allocator would otherwise adopt.
    PinnedDirectory.reverify_tree(control_pin, expected_pre_allocation_control_tree)
    _verify_registered_actual_phase_two_workspace_inventory_is_current(
        launch_binding.workspace_pin,
        expected_workspace_inventory,
    )
    # Raw-predecessor readers are hostile helper boundaries.  A returned
    # token or mutable fixture/control map must still match the detached
    # launch baseline immediately before either ledger header is constructed.
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    raw_nonce = uuid.uuid4().hex
    trace_nonce = uuid.uuid4().hex
    raw_header = _private_receipt_header(
        kind=_PHASE_TWO_RAW_RECEIPT_KIND,
        run_id=prepared_run.run_id,
        execution_id="execution-2",
        nonce=raw_nonce,
        raw_prelaunch=raw_prelaunch,
    )
    trace_header = _private_receipt_header(
        kind=_PHASE_TWO_TRACE_RECEIPT_KIND,
        run_id=prepared_run.run_id,
        execution_id="execution-2",
        nonce=trace_nonce,
    )
    raw_identity = PinnedDirectory.write_relative_exclusive(
        control_pin, _PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER, raw_header,
    )
    trace_identity = PinnedDirectory.write_relative_exclusive(
        control_pin, _PHASE_TWO_TRACE_RECEIPT_LEDGER, trace_header,
    )
    raw = _RegisteredActualPhaseTwoReceiptLedgerBaseline(
        _PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER, _PHASE_TWO_RAW_RECEIPT_KIND,
        prepared_run.run_id, "execution-2", raw_nonce, raw_header, raw_identity, raw_prelaunch,
    )
    trace = _RegisteredActualPhaseTwoReceiptLedgerBaseline(
        _PHASE_TWO_TRACE_RECEIPT_LEDGER, _PHASE_TWO_TRACE_RECEIPT_KIND,
        prepared_run.run_id, "execution-2", trace_nonce, trace_header, trace_identity,
    )
    PinnedDirectory.reverify_snapshot(control_pin, raw.relative_path, (raw.header, raw.identity))
    PinnedDirectory.reverify_snapshot(control_pin, trace.relative_path, (trace.header, trace.identity))
    return _RegisteredActualPhaseTwoReceiptLedgers(
        prepared_run.run_id, "execution-2", raw, trace, raw_prelaunch, prelaunch_tree,
    )


def _revalidate_registered_actual_phase_two_post_allocation_boundary(
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    prepared_phase: "_RegisteredActualPreparedPhase",
    receipt_ledgers: _RegisteredActualPhaseTwoReceiptLedgers,
    *,
    expected_pre_allocation_control_tree: Mapping[
        str, tuple[int, int, int, int, int, int, int, int],
    ],
    expected_raw_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot,
    expected_evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
    expected_workspace_inventory: _RegisteredActualPhaseTwoWorkspaceInventory,
    launch_binding: _RegisteredActualPhaseTwoLaunchBinding,
    trace_receipt_sink: _PrivateReceiptLedgerSink,
) -> None:
    """Recheck the one legal ledger delta immediately before ``Popen``.

    Receipt allocation and sink arming are private helper boundaries between
    the final no-ledger launch gate and the process-creation call.  They may
    add exactly two ledger headers; no other control-tree or workspace change
    is admissible in that interval.
    """

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(receipt_ledgers) is not _RegisteredActualPhaseTwoReceiptLedgers
            or not isinstance(expected_pre_allocation_control_tree, Mapping)
            or not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(
                expected_raw_snapshot,
            )
            or not isinstance(expected_evidence_provenance, Mapping)
            or not expected_evidence_provenance
            or type(launch_binding) is not _RegisteredActualPhaseTwoLaunchBinding
            or type(trace_receipt_sink) is not _PrivateReceiptLedgerSink
            or not _registered_actual_phase_two_workspace_inventory_is_valid(
                expected_workspace_inventory,
            )):
        raise RunnerError("registered actual phase-two post-allocation inputs are invalid")
    if (launch_binding.phase_one_diagnostic is not phase_one_diagnostic
            or launch_binding.raw_predecessor_snapshot != expected_raw_snapshot
            or launch_binding.evidence_provenance != expected_evidence_provenance
            or launch_binding.workspace_inventory != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained launch token changed")
    control_pin = launch_binding.control_pin
    if (not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot
            or prepared_phase.sealed_evidence_provenance != expected_evidence_provenance
            or prepared_phase.sealed_initial_workspace_inventory
            != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained setup state changed")
    launch_binding.assert_current(
        prepared_phase,
        receipt_ledgers=receipt_ledgers,
        trace_receipt_sink=trace_receipt_sink,
    )

    expected_tree = dict(expected_pre_allocation_control_tree)
    for baseline in (receipt_ledgers.raw_ledger, receipt_ledgers.trace_ledger):
        if (baseline.relative_path in expected_tree
                or not _valid_regular_identity(baseline.identity)):
            raise RunnerError("registered actual phase-two post-allocation tree is invalid")
        expected_tree[baseline.relative_path] = baseline.identity
    post_allocation_control_tree = MappingProxyType(expected_tree)
    PinnedDirectory.reverify_tree(control_pin, post_allocation_control_tree)
    _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, receipt_ledgers, control_pin=control_pin,
    )
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        expected_raw_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(control_pin)
    _verify_registered_actual_phase_two_expected_evidence_provenance(
        prepared_phase.writer,
        control_pin=control_pin,
        expected=expected_evidence_provenance,
    )
    if (prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot
            or prepared_phase.sealed_evidence_provenance != expected_evidence_provenance
            or prepared_phase.sealed_initial_workspace_inventory
            != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained setup state changed")
    # The receipt/evidence readers above must not establish a different tree
    # as their own baseline before the final workspace scan.
    PinnedDirectory.reverify_tree(control_pin, post_allocation_control_tree)
    _verify_registered_actual_phase_two_workspace_inventory_is_current(
        launch_binding.workspace_pin,
        expected_workspace_inventory,
    )
    # The workspace scanner is a helper boundary too.  Its callback must not
    # be able to alter a root control or either newly-created ledger after the
    # preceding tree replay and still reach the adjacent ``Popen`` call.
    PinnedDirectory.reverify_tree(control_pin, post_allocation_control_tree)
    if (prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot
            or prepared_phase.sealed_evidence_provenance != expected_evidence_provenance
            or prepared_phase.sealed_initial_workspace_inventory
            != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained setup state changed")
    launch_binding.assert_current(
        prepared_phase,
        receipt_ledgers=receipt_ledgers,
        trace_receipt_sink=trace_receipt_sink,
    )


def _load_registered_actual_phase_two_child_receipt_ledgers(
    control_pin: PinnedDirectory,
    *,
    run_id: str,
    execution_id: str,
) -> tuple[_PrivateReceiptLedgerSink, _PrivateReceiptLedgerSink]:
    """Open the parent-created ledgers in the child without adding state fields."""

    if (not isinstance(control_pin, PinnedDirectory) or not control_pin.private
            or not _is_hex64(run_id) or execution_id != "execution-2"):
        raise RunnerError("private child receipt ledger state is invalid")
    baselines: list[_RegisteredActualPhaseTwoReceiptLedgerBaseline] = []
    for relative, kind in (
        (_PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER, _PHASE_TWO_RAW_RECEIPT_KIND),
        (_PHASE_TWO_TRACE_RECEIPT_LEDGER, _PHASE_TWO_TRACE_RECEIPT_KIND),
    ):
        raw, identity = PinnedDirectory.snapshot_relative(control_pin, relative)
        if not raw.endswith(b"\n"):
            raise RunnerError("private child receipt ledger header is invalid")
        header_value = _strict_json(raw.splitlines(keepends=True)[0][:-1], label="private receipt header")
        expected_header_keys = {"schema_version", "kind", "run_id", "execution_id", "nonce"}
        if kind == _PHASE_TWO_RAW_RECEIPT_KIND:
            expected_header_keys.add("raw_prelaunch")
        if (type(header_value) is not dict
                or set(header_value) != expected_header_keys
                or header_value.get("schema_version") != 1
                or header_value.get("kind") != kind
                or header_value.get("run_id") != run_id
                or header_value.get("execution_id") != execution_id
                or not isinstance(header_value.get("nonce"), str)):
            raise RunnerError("private child receipt ledger header is invalid")
        raw_prelaunch = (
            _private_raw_prelaunch_from_json(header_value["raw_prelaunch"])
            if kind == _PHASE_TWO_RAW_RECEIPT_KIND else None
        )
        header = _private_receipt_header(
            kind=kind,
            run_id=run_id,
            execution_id=execution_id,
            nonce=header_value["nonce"],
            raw_prelaunch=raw_prelaunch,
        )
        if not raw.startswith(header):
            raise RunnerError("private child receipt ledger header is invalid")
        # The child can start after the parent has already appended a trace
        # receipt.  It therefore retains only the stable identity fields it
        # can prove from its current descriptor; the parent retains the full
        # pre-Popen header identity and rejects any replacement later.
        header_identity = (*identity[:5], len(header), identity[6], identity[7])
        baseline = _RegisteredActualPhaseTwoReceiptLedgerBaseline(
            relative,
            kind,
            run_id,
            execution_id,
            header_value["nonce"],
            header,
            header_identity,
            raw_prelaunch,
        )
        _validate_private_receipt_ledger_rows(raw, baseline)
        baselines.append(baseline)
    return _PrivateReceiptLedgerSink(control_pin, baselines[0]), _PrivateReceiptLedgerSink(control_pin, baselines[1])


def _private_raw_receipt_target_is_allowed(relative: str) -> bool:
    if relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        return True
    path = PurePosixPath(relative)
    return (
        len(path.parts) >= 3
        and path.parts[0] in {"brain-shim-captures", "runner-preapply-manifests"}
        and bool(re.fullmatch(r"shim-command-[0-9a-f]{32}", path.parts[1]))
        and all(part not in {"", ".", ".."} for part in path.parts[2:])
    )


def _private_snapshot_optional(
    control_pin: PinnedDirectory,
    relative: str,
) -> _ControlTraceSnapshot | None:
    try:
        return PinnedDirectory.snapshot_relative(control_pin, relative)
    except RunnerError:
        if _pinned_control_capture_is_absent(control_pin, relative):
            return None
        raise


def _verify_private_raw_append_receipt_bytes(
    raw: bytes,
    receipt: Mapping[str, Any],
) -> None:
    """Bind every append receipt to its exact retained file ranges.

    Metadata chaining alone does not prove that an intermediate append still
    describes the retained file.  Recomputing each prefix and appended range
    prevents a forged middle receipt from hiding behind a valid final digest.
    """

    prior_bytes = receipt.get("prior_bytes")
    completed_bytes = receipt.get("completed_bytes")
    appended_bytes = receipt.get("appended_bytes")
    prior_rows = receipt.get("prior_rows")
    completed_rows = receipt.get("completed_rows")
    if (type(raw) is not bytes
            or type(prior_bytes) is not int
            or type(completed_bytes) is not int
            or type(appended_bytes) is not int
            or type(prior_rows) is not int
            or type(completed_rows) is not int
            or prior_bytes < 0
            or completed_bytes <= prior_bytes
            or completed_bytes > len(raw)
            or appended_bytes != completed_bytes - prior_bytes):
        raise RunnerError("private raw receipt bytes are invalid")
    prefix = raw[:prior_bytes]
    appended = raw[prior_bytes:completed_bytes]
    completed = raw[:completed_bytes]
    if (_sha256(prefix) != receipt.get("prior_sha256")
            or prefix.count(b"\n") != prior_rows
            or prefix and not prefix.endswith(b"\n")
            or _sha256(appended) != receipt.get("appended_sha256")
            or appended.count(b"\n") != 1
            or not appended.endswith(b"\n")
            or _sha256(completed) != receipt.get("completed_sha256")
            or completed.count(b"\n") != completed_rows
            or not completed.endswith(b"\n")):
        raise RunnerError("private raw receipt bytes are invalid")


def _verify_private_raw_receipt_records(
    control_pin: PinnedDirectory,
    ledgers: _RegisteredActualPhaseTwoReceiptLedgers,
    rows: Sequence[Mapping[str, Any]],
) -> tuple[
    frozenset[str],
    Mapping[str, _ControlTraceSnapshot],
    frozenset[str],
    Mapping[str, tuple[str, ...]],
]:
    """Join raw receipt metadata to current pinned captures without rebaselining.

    Keep the exact descriptor snapshots that the ledger already authenticated.
    A later post-launch handoff must consume these bytes rather than taking a
    second path-selected snapshot that could turn a replacement into a new
    baseline.
    """

    by_path: dict[str, list[Mapping[str, Any]]] = {}
    append_command_ids: dict[str, list[str]] = {}
    snapshots: dict[str, _ControlTraceSnapshot] = {}
    for row in rows:
        receipt = row.get("receipt")
        if not isinstance(receipt, Mapping):
            raise RunnerError("private raw receipt ledger is invalid")
        command_id = _private_receipt_command_id(row.get("command_id"))
        relative = _private_receipt_relative_path(receipt.get("relative_path"))
        if not _private_raw_receipt_target_is_allowed(relative):
            raise RunnerError("private raw receipt target is invalid")
        kind = receipt.get("kind")
        if ((kind == "append" and relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS)
                or (kind == "write" and relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS)):
            raise RunnerError("private raw receipt route is invalid")
        path = PurePosixPath(relative)
        if (relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                and (len(path.parts) < 3 or path.parts[1] != command_id)):
            raise RunnerError("private raw receipt command ownership is invalid")
        if kind == "write" and relative in ledgers.prelaunch_tree:
            raise RunnerError("private raw receipt dynamic target existed before launch")
        by_path.setdefault(relative, []).append(receipt)
        if kind == "append":
            append_command_ids.setdefault(relative, []).append(command_id)
    for relative, entries in by_path.items():
        current = _private_snapshot_optional(control_pin, relative)
        if current is None:
            raise RunnerError("private raw receipt target disappeared")
        raw, identity = current
        prior: Mapping[str, Any] | None = None
        for receipt in entries:
            kind = receipt.get("kind")
            if kind == "write":
                if prior is not None:
                    raise RunnerError("private raw receipt write chain is invalid")
                prior = receipt
                continue
            if kind != "append":
                raise RunnerError("private raw receipt chain is invalid")
            if prior is None:
                baseline = ledgers.raw_prelaunch.get(relative)
                if baseline is None:
                    if (receipt.get("prior_sha256") != _sha256(b"")
                            or receipt.get("prior_bytes") != 0
                            or receipt.get("prior_rows") != 0):
                        raise RunnerError("private raw receipt predecessor is invalid")
                elif (receipt.get("prior_sha256") != baseline.sha256
                        or receipt.get("prior_bytes") != baseline.byte_count
                        or receipt.get("prior_rows") != baseline.rows
                        or tuple(receipt.get("prior_identity", ())) != baseline.identity):
                    raise RunnerError("private raw receipt predecessor changed")
            else:
                if prior.get("kind") != "append" or (
                    receipt.get("prior_sha256"), receipt.get("prior_bytes"),
                    tuple(receipt.get("prior_identity", ())), receipt.get("prior_rows"),
                ) != (
                    prior.get("completed_sha256"), prior.get("completed_bytes"),
                    tuple(prior.get("completed_identity", ())), prior.get("completed_rows"),
                ):
                    raise RunnerError("private raw receipt chain is invalid")
            _verify_private_raw_append_receipt_bytes(raw, receipt)
            prior = receipt
        assert prior is not None
        if prior.get("kind") == "write":
            expected_sha, expected_bytes, expected_identity = (
                prior.get("sha256"), prior.get("byte_count"), tuple(prior.get("identity", ())),
            )
        else:
            expected_sha, expected_bytes, expected_identity = (
                prior.get("completed_sha256"), prior.get("completed_bytes"),
                tuple(prior.get("completed_identity", ())),
            )
        if (_sha256(raw) != expected_sha or len(raw) != expected_bytes or identity != expected_identity):
            raise RunnerError("private raw receipt target changed")
        snapshots[relative] = current
    current_tree = PinnedDirectory.snapshot_tree(control_pin)
    for relative, baseline in ledgers.raw_prelaunch.items():
        if baseline is not None and relative not in current_tree:
            raise RunnerError("private raw receipt predecessor disappeared")
    for relative, identity in current_tree.items():
        if relative.endswith("/"):
            continue
        if not (relative.startswith("brain-shim-captures/")
                or relative.startswith("runner-preapply-manifests/")
                or relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS):
            continue
        baseline_identity = ledgers.prelaunch_tree.get(relative)
        if baseline_identity != identity and relative not in by_path:
            raise RunnerError("private raw receipt target changed without receipt")
        if baseline_identity is None and relative not in by_path:
            raise RunnerError("private raw receipt target appeared without receipt")
    absent: set[str] = set()
    for relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
        if relative in snapshots:
            continue
        baseline = ledgers.raw_prelaunch[relative]
        current = _private_snapshot_optional(control_pin, relative)
        if baseline is None:
            if current is not None:
                raise RunnerError("private raw receipt target appeared without receipt")
            absent.add(relative)
            continue
        if current is None:
            raise RunnerError("private raw receipt predecessor disappeared")
        raw, identity = current
        if (_sha256(raw) != baseline.sha256
                or len(raw) != baseline.byte_count
                or identity != baseline.identity):
            raise RunnerError("private raw receipt predecessor changed")
        snapshots[relative] = current
    return (
        frozenset(by_path),
        MappingProxyType(snapshots),
        frozenset(absent),
        MappingProxyType({
            relative: tuple(command_ids)
            for relative, command_ids in append_command_ids.items()
        }),
    )


def _verify_private_trace_receipt_records(
    control_pin: PinnedDirectory,
    rows: Sequence[Mapping[str, Any]],
) -> _ControlTraceSnapshot | None:
    """Bind every phase-two trace row to its sink-time metadata chain."""

    trace_name = "runner-trace-execution-2.jsonl"
    current = _private_snapshot_optional(control_pin, trace_name)
    if not rows:
        if current is not None:
            raise RunnerError("private trace appeared without receipt")
        return None
    if current is None:
        raise RunnerError("private trace receipt target disappeared")
    raw, identity = current
    parsed = tuple(_strict_json(line, label="private trace") for line in raw.splitlines())
    validate_trace_records(parsed, complete=False)
    if len(parsed) != len(rows):
        raise RunnerError("private trace receipt row count is invalid")
    prior: Mapping[str, Any] | None = None
    for index, (ledger_row, trace_row) in enumerate(zip(rows, parsed), start=1):
        receipt = ledger_row.get("receipt")
        if not isinstance(receipt, Mapping):
            raise RunnerError("private trace receipt row is invalid")
        if (receipt.get("sequence") != trace_row.get("sequence")
                or receipt.get("trace_kind") != trace_row.get("kind")
                or receipt.get("prior_rows") != index - 1
                or receipt.get("completed_rows") != index):
            raise RunnerError("private trace receipt chain is invalid")
        prior_bytes = receipt.get("prior_bytes")
        completed_bytes = receipt.get("completed_bytes")
        if (type(prior_bytes) is not int or type(completed_bytes) is not int
                or prior_bytes < 0 or completed_bytes <= prior_bytes
                or completed_bytes > len(raw)
                or _sha256(raw[:prior_bytes]) != receipt.get("prior_sha256")
                or raw[:prior_bytes].count(b"\n") != receipt.get("prior_rows")
                or raw[:prior_bytes] and not raw[:prior_bytes].endswith(b"\n")
                or completed_bytes - prior_bytes != receipt.get("row_bytes")):
            raise RunnerError("private trace receipt bytes are invalid")
        row_raw = raw[prior_bytes:completed_bytes]
        if (_sha256(row_raw) != receipt.get("row_sha256")
                or row_raw.count(b"\n") != 1
                or not row_raw.endswith(b"\n")):
            raise RunnerError("private trace receipt bytes are invalid")
        if (_sha256(raw[:completed_bytes]) != receipt.get("completed_sha256")
                or raw[:completed_bytes].count(b"\n") != receipt.get("completed_rows")
                or not raw[:completed_bytes].endswith(b"\n")):
            raise RunnerError("private trace receipt bytes are invalid")
        if prior is None:
            if (receipt.get("prior_sha256") != _sha256(b"")
                    or prior_bytes != 0 or receipt.get("prior_rows") != 0):
                raise RunnerError("private trace receipt predecessor is invalid")
        elif (
            receipt.get("prior_sha256"), prior_bytes, tuple(receipt.get("prior_identity", ())),
        ) != (
            prior.get("completed_sha256"), prior.get("completed_bytes"),
            tuple(prior.get("completed_identity", ())),
        ):
            raise RunnerError("private trace receipt chain is invalid")
        prior = receipt
    assert prior is not None
    if (_sha256(raw) != prior.get("completed_sha256")
            or len(raw) != prior.get("completed_bytes")
            or identity != tuple(prior.get("completed_identity", ()))):
        raise RunnerError("private trace receipt target changed")
    return current


def _verify_registered_actual_phase_two_receipt_ledgers(
    prepared_phase: "_RegisteredActualPreparedPhase",
    ledgers: _RegisteredActualPhaseTwoReceiptLedgers,
    *,
    control_pin: PinnedDirectory | None = None,
) -> _RegisteredActualPhaseTwoReceiptLedgerVerification:
    """Fail closed on every ledger/raw/trace replacement before token capture."""

    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(ledgers) is not _RegisteredActualPhaseTwoReceiptLedgers
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.writer.run_id != ledgers.run_id
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != prepared_phase.writer.control_root):
        raise RunnerError("registered actual phase-two receipt verification is invalid")
    PinnedDirectory.verify(control_pin)
    decoded: dict[str, tuple[Mapping[str, Any], ...]] = {}
    for baseline in (ledgers.raw_ledger, ledgers.trace_ledger):
        raw, identity = PinnedDirectory.snapshot_relative(
            control_pin, baseline.relative_path,
        )
        if identity[:5] != baseline.identity[:5] or not raw.startswith(baseline.header):
            raise RunnerError("registered actual phase-two receipt ledger changed")
        decoded[baseline.kind] = _validate_private_receipt_ledger_rows(raw, baseline)
    raw_paths, raw_snapshots, raw_absent_paths, raw_append_command_ids = (
        _verify_private_raw_receipt_records(
            control_pin, ledgers, decoded[_PHASE_TWO_RAW_RECEIPT_KIND],
        )
    )
    trace_snapshot = _verify_private_trace_receipt_records(
        control_pin, decoded[_PHASE_TWO_TRACE_RECEIPT_KIND],
    )
    PinnedDirectory.verify(control_pin)
    return _RegisteredActualPhaseTwoReceiptLedgerVerification(
        trace_snapshot=trace_snapshot,
        raw_receipt_paths=raw_paths,
        raw_snapshots=raw_snapshots,
        raw_absent_paths=raw_absent_paths,
        raw_append_command_ids=raw_append_command_ids,
    )


@dataclass(frozen=True)
class NativeNormalization:
    complete: bool
    reason: str | None
    records: dict[int, dict[str, Any]] = field(default_factory=dict)


def _native_records_contain_event_text(records: Mapping[int, Mapping[str, Any]]) -> bool:
    """Conservatively detect decoded marker-like assistant text.

    JSON transport spelling is not semantic authority: ``\\u0045VENT:`` and
    literal ``EVENT:`` decode to the same sourced Claude text projection.  The
    exact-line validation still belongs to ``extract_event_markers``; this
    helper only decides whether an unstreamed transcript must be refused and
    whether the stream seam needs a marker-time workspace snapshot.
    """

    for record in records.values():
        texts = record.get("texts") if isinstance(record, Mapping) else None
        if isinstance(texts, Mapping) and any(
                isinstance(text, str) and "EVENT:" in text for text in texts.values()):
            return True
    return False


@dataclass(frozen=True)
class MarkerCandidate:
    """A parser-backed, trace-bound marker candidate.

    This is intentionally not an event claim.  The semantic normalizer still
    has to prove the relevant command, receipt, diff, approval, or cursor
    corroboration before it could write an event record.
    """

    event_name: str
    marker: str
    byte_start: int
    byte_end: int
    excerpt_sha256: str
    native_record_start: int
    native_record_end: int
    native_record_sha256: str
    text_pointer: str
    trace_sequence: int


@dataclass(frozen=True)
class SemanticMarkerEvidence:
    """A marker whose execution and transcript are owned by the host trace."""

    marker_id: str
    execution_id: str
    candidate: MarkerCandidate
    transcript_id: str = "transcript"


@dataclass(frozen=True)
class SemanticCommandEvidence:
    """Typed command evidence selected from Task 7b's indexed bridge output."""

    command_id: str
    execution_id: str
    argv: tuple[str, ...]
    result: Mapping[str, Any]
    result_raw: bytes
    result_sha256: str
    start_sequence: int
    end_sequence: int
    exit_code: int = 0
    artifact_ids: Mapping[str, str] = field(default_factory=dict)


@dataclass(frozen=True)
class SemanticDeliveryEvidence:
    """A host-indexed immutable delivery projected for a receipt operation."""

    delivery_id: str
    operation: str
    artifact_id: str
    items: tuple[Mapping[str, str], ...]


@dataclass(frozen=True)
class SemanticCursorProofEvidence:
    """One host-built ordered cursor chain for a drained semantic event."""

    proof_id: str
    execution_id: str
    family: str
    command_ids: tuple[str, ...]


@dataclass(frozen=True)
class SemanticNormalizationInput:
    """All typed evidence the semantic planner may consider.

    ``artifact_types`` comes from the runner's immutable evidence index; callers
    cannot satisfy a reference merely by selecting an arbitrary matching name.
    ``event_references`` has one exact mapping per semantic event and is where
    host-produced diffs, approvals, packets, manifests, and cursor proofs are
    supplied after their own capture/normalization.
    """

    run_id: str
    scenario: Mapping[str, Any]
    execution_order: Mapping[str, int]
    markers: tuple[SemanticMarkerEvidence, ...]
    commands: tuple[SemanticCommandEvidence, ...]
    artifact_types: Mapping[str, str]
    event_references: Mapping[str, Mapping[str, str]]
    deliveries: tuple[SemanticDeliveryEvidence, ...]
    cursor_proofs: tuple[SemanticCursorProofEvidence, ...] = ()


@dataclass(frozen=True)
class SemanticEventPlan:
    """All-or-nothing event/receipt plan suitable for later host emission."""

    events: tuple[dict[str, Any], ...]
    event_records: Mapping[str, dict[str, Any]]
    marker_records: Mapping[str, dict[str, Any]]
    receipts: tuple[dict[str, Any], ...]
    deliveries: tuple[dict[str, Any], ...]
    incomplete_reasons: tuple[str, ...]

    @property
    def complete(self) -> bool:
        return not self.incomplete_reasons


_SEMANTIC_REUSE_GROUPS = (
    (
        "public_web_access", "snapshot_used_source", "initial_snapshot_receipt_verified",
    ),
    (
        "rendered_snapshot_url", "rendered_snapshot_receipt_verified",
        "verify_snapshot_active_representation",
    ),
    (
        "register_extraction_handoff", "verify_registration_active_representation",
    ),
    ("freshness_search_batched", "freshness_search_drained"),
    ("source_pass_discovery", "source_pass_discovery_drained"),
    ("source_pass_expansion", "source_pass_expansion_drained"),
    ("source_pass_verification", "source_pass_verification_drained"),
)


def _semantic_position(
    execution_order: Mapping[str, int], execution_id: str, sequence: int,
) -> tuple[int, int] | None:
    index = execution_order.get(execution_id)
    if type(index) is not int or index < 0 or type(sequence) is not int or sequence < 1:
        return None
    return index, sequence


def _semantic_marker_order_position(
    execution_order: Mapping[str, int], marker: SemanticMarkerEvidence,
) -> tuple[int, int, int, int] | None:
    """Mirror Task 7a's native marker ordering key before artifact emission.

    One assistant native record may legitimately contain more than one exact
    ``EVENT:...`` line.  The shared trace sequence alone therefore cannot be
    an event identity.  Task 7a orders those markers by phase, native-record
    byte offset, content-block index, and byte offset within that text block;
    retain the same closed ordering here so an incomplete runner cannot later
    produce an event layout that the public validator would reject.
    """

    candidate = marker.candidate
    phase = _semantic_position(
        execution_order, marker.execution_id, candidate.trace_sequence,
    )
    if phase is None:
        return None
    pointer = candidate.text_pointer
    prefix = "/message/content/"
    suffix = "/text"
    index_text = pointer.removeprefix(prefix).removesuffix(suffix)
    if (not pointer.startswith(prefix) or not pointer.endswith(suffix)
            or not index_text.isdecimal()
            or pointer != f"{prefix}{int(index_text)}{suffix}"):
        return None
    if (type(candidate.native_record_start) is not int
            or type(candidate.native_record_end) is not int
            or candidate.native_record_start < 0
            or candidate.native_record_end <= candidate.native_record_start
            or not _is_hex64(candidate.native_record_sha256)):
        return None
    return (phase[0], candidate.native_record_start, int(index_text), candidate.byte_start)


def _semantic_marker_record(
    run_id: str, marker: SemanticMarkerEvidence,
) -> dict[str, Any]:
    candidate = marker.candidate
    return {
        "run_id": run_id,
        "execution_id": marker.execution_id,
        "transcript_id": marker.transcript_id,
        "marker": candidate.marker,
        "byte_start": candidate.byte_start,
        "byte_end": candidate.byte_end,
        "excerpt_sha256": candidate.excerpt_sha256,
        "native_record_start": candidate.native_record_start,
        "native_record_end": candidate.native_record_end,
        "native_record_sha256": candidate.native_record_sha256,
        "text_pointer": candidate.text_pointer,
    }


def _marker_trace_sequence_matches(
    marker: SemanticMarkerEvidence,
    native_records: Mapping[int, Mapping[str, Any]],
) -> bool:
    """Bind a planner marker's unsealed sequence to Task 7a trace evidence.

    The public marker artifact intentionally contains native byte/span facts,
    not a duplicate trace sequence.  The normalizer must therefore derive the
    sequence from the sealed execution trace before using the in-memory
    candidate to choose a workspace snapshot or source checkpoint.
    """

    candidate = marker.candidate
    native = native_records.get(candidate.native_record_start)
    return bool(
        isinstance(native, Mapping)
        and native.get("end") == candidate.native_record_end
        and native.get("sha256") == candidate.native_record_sha256
        and native.get("sequence") == candidate.trace_sequence
        and type(candidate.trace_sequence) is int
        and candidate.trace_sequence > 0
    )


def _indexed_native_trace_rows(
    writer: EvidenceWriter,
) -> dict[str, dict[int, Mapping[str, Any]]]:
    """Load every sealed process trace and close its snapshot graph locally.

    The public validator performs the same graph check for a pass.  The
    normalizer needs it earlier: otherwise an in-memory snapshot list could
    select an alternate artifact with the same visible provenance but a
    different captured inventory before public validation gets a chance to
    reject it.
    """

    entries = _writer_entry_map(writer)
    native_by_execution: dict[str, dict[int, Mapping[str, Any]]] = {}
    for artifact_id, entry in entries.items():
        if entry.get("type") != "process":
            continue
        process = _strict_json(
            _writer_artifact_bytes(writer, artifact_id, "process"),
            label="marker trace process",
        )
        if (type(process) is not dict
                or type(process.get("execution_id")) is not str
                or not process["execution_id"]
                or type(process.get("trace_id")) is not str
                or not _is_hex64(process.get("trace_sha256", ""))
                or process["execution_id"] in native_by_execution):
            raise RunnerError("marker trace process binding invalid")
        trace = _strict_json(
            _writer_artifact_bytes(writer, process["trace_id"], "execution_trace"),
            label="marker execution trace",
        )
        if (type(trace) is not dict
                or set(trace) != {"schema_version", "run_id", "execution_id", "records"}
                or trace.get("schema_version") != 1
                or trace.get("run_id") != writer.run_id
                or trace.get("execution_id") != process["execution_id"]
                or not isinstance(trace.get("records"), list)
                or _sha256(_canonical_json(trace)) != process["trace_sha256"]):
            raise RunnerError("marker execution trace binding invalid")
        validate_trace_records(trace["records"])
        _reject_native_inside_command_interval(trace["records"])
        native_rows: dict[int, Mapping[str, Any]] = {}
        snapshot_ids: set[str] = set()
        for row in trace["records"]:
            if row.get("kind") != "native_record":
                continue
            start = row.get("byte_start")
            if type(start) is not int or start in native_rows:
                raise RunnerError("marker native trace identity invalid")
            snapshot_id = row.get("workspace_snapshot_id")
            if type(snapshot_id) is not str or snapshot_id in snapshot_ids:
                raise RunnerError("native trace workspace snapshot is not distinct")
            _indexed_trace_workspace_snapshot(
                writer, execution_id=process["execution_id"], native_row=row,
            )
            snapshot_ids.add(snapshot_id)
            # Task 7a's ``_execution_trace`` exposes a compact native-record
            # view using ``end``.  Adapt only this field while retaining the
            # indexed row's transcript identity for the extra runner check.
            native_rows[start] = {**row, "end": row["byte_end"]}
        native_by_execution[process["execution_id"]] = native_rows
    return native_by_execution


def _indexed_native_snapshot_ids(
    writer: EvidenceWriter,
) -> dict[tuple[str, int], str]:
    """Return the one trace-owned workspace snapshot ID for each native row."""

    bindings: dict[tuple[str, int], str] = {}
    for execution_id, rows in _indexed_native_trace_rows(writer).items():
        for row in rows.values():
            sequence = row.get("sequence")
            snapshot_id = row.get("workspace_snapshot_id")
            key = (execution_id, sequence)
            if (type(sequence) is not int or sequence <= 0
                    or type(snapshot_id) is not str or not snapshot_id
                    or key in bindings):
                raise RunnerError("native trace workspace snapshot binding invalid")
            bindings[key] = snapshot_id
    return bindings


def _verified_marker_trace_evidence(
    writer: EvidenceWriter,
    markers: Sequence[SemanticMarkerEvidence],
) -> tuple[SemanticMarkerEvidence, ...]:
    """Return markers only after their snapshot key joins sealed trace bytes.

    ``MarkerCandidate.trace_sequence`` is parser-side working state, whereas
    each workspace snapshot is keyed by that number.  Do this join immediately
    after capture conversion and before any diff, packet, approval, or event
    projection gets access to the candidates.  A later replay repeats the
    check as defense in depth, but cannot retract already-emitted artifacts.
    """

    if not markers:
        return ()
    native_by_execution = _indexed_native_trace_rows(writer)

    verified: list[SemanticMarkerEvidence] = []
    for marker in markers:
        native_rows = native_by_execution.get(marker.execution_id)
        native = (
            native_rows.get(marker.candidate.native_record_start)
            if native_rows is not None else None
        )
        if (native is None
                or native.get("transcript_id") != marker.transcript_id
                or not _marker_trace_sequence_matches(marker, native_rows)):
            raise RunnerError("marker trace sequence is not sealed")
        verified.append(marker)
    return tuple(verified)


def _semantic_command_matches(name: str, command: SemanticCommandEvidence) -> bool:
    """Delegate exact command/result syntax to Task 7a's closed validator."""

    if (not command.command_id or not command.execution_id
            or type(command.start_sequence) is not int
            or type(command.end_sequence) is not int
            or not 0 < command.start_sequence < command.end_sequence
            or type(command.exit_code) is not int or command.exit_code not in {0, 1}
            or any(type(item) is not str for item in command.argv)
            or type(command.result) is not dict or type(command.result_raw) is not bytes
            or _sha256(command.result_raw) != command.result_sha256
            or list(command.argv[:2]) != ["./brain", "--json"]):
        return False
    try:
        from tests.evals import event_log_contract as contract

        if _strict_json(command.result_raw, label="semantic command result") != command.result:
            return False
        # Keep candidate selection as strict as Task 7a's indexed
        # ``_result`` observation gate.  The event-specific parser below is
        # deliberately narrower, and on its own would accidentally accept a
        # `validate` response coupled to a nonzero outer shim exit.
        suffix = list(command.argv[2:])
        if not suffix:
            return False
        observed_command = (
            " ".join(suffix[:2])
            if suffix[0] in {"source", "wiki", "links", "eval"}
            else suffix[0]
        )
        manifest_result = (
            observed_command in {"sync", "init", "source snapshot-url"}
            or (
                observed_command == "eval mock-web-capture"
                and suffix[2:4] == ["--fixture-id", "web-approval-and-capture.initial"]
            )
        )
        if manifest_result:
            from tests.evals import semantic_evidence as semantic

            semantic.parse_manifest_response(
                command.result, observed_exit_code=command.exit_code,
            )
            if command.result.get("command") != observed_command:
                return False
        else:
            if command.exit_code != 0:
                return False
            contract._envelope(command.result, observed_command)
        # ``_event_command`` carries the per-rule argv/result parser.  It does
        # not trust a marker or a generic successful command as a substitute.
        contract._event_command(name, list(command.argv), dict(command.result))
    except Exception:
        return False
    return True


def _semantic_delivery_data(
    name: str,
    deliveries: Mapping[str, SemanticDeliveryEvidence],
) -> dict[str, Any] | None:
    if name.endswith("_handoff_delivery_verified"):
        operation = name.removesuffix("_handoff_delivery_verified")
        delivery = deliveries.get(operation)
        if delivery is None:
            return None
        return {
            "delivery_id": delivery.delivery_id,
            "item_mappings": [
                {"item_id": item["item_id"], "handoff_source_id": item["handoff_source_id"]}
                for item in delivery.items
            ],
        }
    kind = {
        "branch_extraction_handoff": "extraction",
        "branch_rendered_web_capture_handoff": "rendered_web_capture",
    }.get(name)
    if kind is None:
        return None
    matches = [
        (delivery, item)
        for delivery in deliveries.values()
        for item in delivery.items
        if item.get("kind") == kind
    ]
    if len(matches) != 1:
        return None
    delivery, item = matches[0]
    return {
        "delivery_id": delivery.delivery_id,
        "item_id": item["item_id"],
        "handoff_id": item["handoff_id"],
        "handoff_source_id": item["handoff_source_id"],
    }


def _semantic_receipt_id(operation: str) -> str:
    return "receipt-" + operation.replace("_", "-")


def _semantic_cursor_family(name: str) -> str | None:
    """Return the closed Task 7a cursor family for a marker event."""

    if name == "wiki_no_supported_evidence":
        return "wiki_search"
    if name == "freshness_search_drained":
        return "freshness_search_batched"
    if name.endswith("_drained"):
        return name.removesuffix("_drained")
    return None


def _semantic_cursor_drain_for_start(name: str) -> str | None:
    if name == "freshness_search_batched":
        return "freshness_search_drained"
    if name.startswith("source_pass_"):
        return name + "_drained"
    return None


def _semantic_reuse_may_extend(users: Sequence[str], name: str) -> bool:
    """Only a prefix/subset of an explicit Task 7a alias group can reuse."""

    expanded = set(users) | {name}
    return any(expanded <= set(group) for group in _SEMANTIC_REUSE_GROUPS)


def _semantic_command_requires_source_state(
    name: str, scenario: Mapping[str, Any],
) -> bool:
    """Return whether Task 7a validates this selected command's host state.

    These are deliberately narrower than every product command: Task 7b only
    captures state where its command-bound checkpoint is contract authority.
    In particular, a durable or acknowledgement receipt is not made
    impossible merely because the bridge has no post-acknowledgement state
    seam.
    """

    if name == "register_extraction_handoff":
        return True
    # Task 3's contradictory-evidence interpretation decision is bound to
    # the final ``wiki apply`` checkpoint.  That checkpoint retains the
    # exact ledger, raw, and extracted captures whose identities resolve the
    # terminal QuestionRecord citations; without it a private replay could
    # never establish the closed decision witness.
    if scenario.get("id") == "contradictory-evidence" and name == "wiki_apply":
        return True
    return (
        scenario.get("id") == "web-approval-and-capture"
        and scenario.get("network_mode") == "mock_only"
        and name in {"wiki_apply", "persist_claim"}
    )


def plan_semantic_events(evidence: SemanticNormalizationInput) -> SemanticEventPlan:
    """Build a closed all-or-nothing semantic event plan from host evidence.

    This planner intentionally does *selection* rather than reimplementing
    Task 7a's final semantic proof.  It maps every known event mode to the
    exact marker, command, and typed support it requires, rejects ambiguous or
    unordered choices, and gives the final descriptor-backed contract the
    chosen IDs to validate deeply.  An incomplete plan emits no partial event
    claims, receipt claims, or delivery claims.
    """

    reasons: list[str] = []
    scenario = evidence.scenario
    required_raw = scenario.get("required_events") if isinstance(scenario, Mapping) else None
    receipt_operations_raw = scenario.get("receipt_operations") if isinstance(scenario, Mapping) else None
    if (not _is_hex64(evidence.run_id) or type(required_raw) is not list
            or any(type(name) is not str for name in required_raw)
            or len(required_raw) != len(set(required_raw))
            or type(receipt_operations_raw) is not list
            or any(type(operation) is not str for operation in receipt_operations_raw)):
        return SemanticEventPlan((), {}, {}, (), (), ("semantic_invalid_scenario",))
    required = tuple(required_raw)
    receipt_operations = tuple(receipt_operations_raw)
    try:
        from tests.evals import event_log_contract as contract
    except Exception:
        return SemanticEventPlan((), {}, {}, (), (), ("semantic_contract_unavailable",))
    if any(name not in contract.EVENT_RULES for name in required):
        return SemanticEventPlan((), {}, {}, (), (), ("semantic_unknown_event_rule",))

    markers: dict[str, SemanticMarkerEvidence] = {}
    marker_positions: dict[str, tuple[int, int, int, int]] = {}
    marker_ids: set[str] = set()
    for marker in evidence.markers:
        candidate = marker.candidate
        expected_marker = "EVENT:" + candidate.event_name + "\n"
        if (not marker.marker_id or marker.marker_id in marker_ids
                or not marker.execution_id or not marker.transcript_id
                or marker.candidate.event_name not in required
                or marker.candidate.event_name in markers
                or candidate.marker != expected_marker
                or type(candidate.byte_start) is not int or type(candidate.byte_end) is not int
                or candidate.byte_start < 0 or candidate.byte_end <= candidate.byte_start
                or candidate.excerpt_sha256 != _sha256(candidate.marker.encode("utf-8"))):
            reasons.append("semantic_invalid_marker")
            continue
        position = _semantic_marker_order_position(evidence.execution_order, marker)
        if position is None:
            reasons.append("semantic_invalid_marker")
            continue
        marker_ids.add(marker.marker_id)
        markers[marker.candidate.event_name] = marker
        marker_positions[marker.candidate.event_name] = position
    ordered_marker_positions = [
        marker_positions[name] for name in required if name in marker_positions
    ]
    if len(ordered_marker_positions) != len(set(ordered_marker_positions)):
        reasons.append("semantic_marker_position_reused")
    if ordered_marker_positions != sorted(ordered_marker_positions):
        reasons.append("semantic_marker_order_invalid")
    # Apply the contract's same-text span rule in emitted event order rather
    # than trusting the caller's evidence tuple ordering.  Adjacent exact
    # marker lines in one assistant text block are valid; overlap is not.
    marker_spans: dict[tuple[str, str, int, str], int] = {}
    for name in required:
        marker = markers.get(name)
        if marker is None:
            continue
        candidate = marker.candidate
        span_key = (
            marker.execution_id, marker.transcript_id,
            candidate.native_record_start, candidate.text_pointer,
        )
        if candidate.byte_start < marker_spans.get(span_key, 0):
            reasons.append("semantic_marker_span_overlap")
        marker_spans[span_key] = candidate.byte_end
    for name in required:
        if name not in markers:
            reasons.append("semantic_missing_marker:" + name)

    command_by_id: dict[str, SemanticCommandEvidence] = {}
    for command in evidence.commands:
        if command.command_id in command_by_id or not command.command_id:
            reasons.append("semantic_duplicate_command")
            continue
        start = _semantic_position(evidence.execution_order, command.execution_id, command.start_sequence)
        end = _semantic_position(evidence.execution_order, command.execution_id, command.end_sequence)
        if start is None or end is None or not start < end:
            reasons.append("semantic_command_execution_untrusted")
            continue
        command_by_id[command.command_id] = command

    cursor_proofs: dict[str, SemanticCursorProofEvidence] = {}
    for proof in evidence.cursor_proofs:
        if (not proof.proof_id or proof.proof_id in cursor_proofs
                or evidence.artifact_types.get(proof.proof_id) != "cursor_proof"
                or not proof.execution_id or not proof.family
                or not proof.command_ids or len(set(proof.command_ids)) != len(proof.command_ids)):
            reasons.append("semantic_invalid_cursor_proof")
            continue
        prior_end: tuple[int, int] | None = None
        valid = True
        for command_id in proof.command_ids:
            command = command_by_id.get(command_id)
            if command is None or command.execution_id != proof.execution_id:
                valid = False
                break
            start = _semantic_position(evidence.execution_order, command.execution_id, command.start_sequence)
            end = _semantic_position(evidence.execution_order, command.execution_id, command.end_sequence)
            if start is None or end is None or prior_end is not None and start <= prior_end:
                valid = False
                break
            prior_end = end
        if not valid:
            reasons.append("semantic_invalid_cursor_proof")
            continue
        cursor_proofs[proof.proof_id] = proof

    deliveries_by_operation: dict[str, SemanticDeliveryEvidence] = {}
    for delivery in evidence.deliveries:
        if (delivery.operation in deliveries_by_operation or not delivery.delivery_id
                or evidence.artifact_types.get(delivery.artifact_id) != "delivery"
                or not delivery.items):
            reasons.append("semantic_invalid_delivery")
            continue
        valid_items = all(
            isinstance(item, Mapping)
            and set(item) == {"item_id", "kind", "handoff_id", "handoff_source_id", "payload_sha256"}
            and all(type(item[key]) is str and item[key] for key in item)
            and item["kind"] in {"extraction", "rendered_web_capture"}
            and _is_hex64(item["payload_sha256"])
            for item in delivery.items
        )
        if not valid_items:
            reasons.append("semantic_invalid_delivery")
            continue
        deliveries_by_operation[delivery.operation] = delivery

    # Cursor proof selection is deliberately preplanned.  The event-specific
    # command validator only knows that a drain result is a search page; this
    # host map pins it to the last command in the complete chain and pins its
    # paired start event to the first.  A generic search row can never be
    # substituted after the fact.
    forced_commands: dict[str, SemanticCommandEvidence] = {}
    referenced_cursor_proofs: dict[str, SemanticCursorProofEvidence] = {}
    for name in required:
        rule = contract.EVENT_RULES[name]
        if not any(key == "cursor_proof_id" for key, _kind in rule.references):
            continue
        references = evidence.event_references.get(name, {})
        proof_id = references.get("cursor_proof_id") if isinstance(references, Mapping) else None
        proof = cursor_proofs.get(proof_id) if type(proof_id) is str else None
        family = _semantic_cursor_family(name)
        if proof is None or family is None or proof.family != family:
            reasons.append("semantic_missing_cursor_proof:" + name)
            continue
        marker = markers.get(name)
        if marker is not None and proof.execution_id != marker.execution_id:
            reasons.append("semantic_cursor_execution_mismatch:" + name)
            continue
        referenced_cursor_proofs[proof_id] = proof
        if rule.mode == "product_cli":
            forced_commands[name] = command_by_id[proof.command_ids[-1]]

    for name in required:
        drain = _semantic_cursor_drain_for_start(name)
        if drain is None or drain not in required:
            continue
        references = evidence.event_references.get(drain, {})
        proof_id = references.get("cursor_proof_id") if isinstance(references, Mapping) else None
        proof = cursor_proofs.get(proof_id) if type(proof_id) is str else None
        expected_family = _semantic_cursor_family(drain)
        marker = markers.get(name)
        if (proof is None or expected_family is None or proof.family != expected_family
                or marker is not None and proof.execution_id != marker.execution_id):
            reasons.append("semantic_missing_cursor_start:" + name)
            continue
        forced_commands[name] = command_by_id[proof.command_ids[0]]

    working_events: list[dict[str, Any]] = []
    working_records: dict[str, dict[str, Any]] = {}
    working_markers: dict[str, dict[str, Any]] = {}
    selected_commands: dict[str, list[str]] = {}
    selected_by_name: dict[str, SemanticCommandEvidence] = {}
    previous_marker: tuple[int, int] | None = None
    for sequence, name in enumerate(required, 1):
        marker = markers.get(name)
        if marker is None:
            continue
        rule = contract.EVENT_RULES[name]
        marker_order_position = _semantic_marker_order_position(
            evidence.execution_order, marker,
        )
        marker_position = _semantic_position(
            evidence.execution_order, marker.execution_id, marker.candidate.trace_sequence,
        )
        if marker_order_position is None or marker_position is None:
            continue
        expected_references = {key: artifact_type for key, artifact_type in rule.references}
        supplied_references = evidence.event_references.get(name, {})
        if not isinstance(supplied_references, Mapping):
            reasons.append("semantic_invalid_reference:" + name)
            continue
        references = dict(supplied_references)

        command: SemanticCommandEvidence | None = None
        if rule.mode in {"product_cli", "fixture_eval"}:
            candidates: list[SemanticCommandEvidence] = []
            forced = forced_commands.get(name)
            for possible in command_by_id.values():
                start = _semantic_position(evidence.execution_order, possible.execution_id, possible.start_sequence)
                end = _semantic_position(evidence.execution_order, possible.execution_id, possible.end_sequence)
                existing_users = selected_commands.get(possible.command_id, [])
                can_reuse = bool(existing_users) and _semantic_reuse_may_extend(existing_users, name)
                if (possible.execution_id != marker.execution_id or start is None or end is None
                        or not end < marker_position
                        or forced is not None and possible.command_id != forced.command_id
                        or previous_marker is not None and start <= previous_marker and not can_reuse
                        or not _semantic_command_matches(name, possible)):
                    continue
                candidates.append(possible)
            if len(candidates) != 1:
                reasons.append("semantic_missing_command:" + name if not candidates else "semantic_ambiguous_command:" + name)
            else:
                command = candidates[0]
                selected_by_name[name] = command
                selected_commands.setdefault(command.command_id, []).append(name)

        if command is not None and _semantic_command_requires_source_state(name, scenario):
            source_state_id = command.artifact_ids.get("source_state")
            if evidence.artifact_types.get(source_state_id) != "source_state":
                reasons.append("semantic_missing_command_source_state:" + name)

        # A wiki manifest belongs to the exact observed `wiki apply` command
        # selected by this marker/timeline, not to a global command-name pool.
        # This matters when a run reconciles citations and later applies a
        # distinct final update: both share Task 7a's argv grammar but have
        # different pre-dispatch captured manifests.
        if "manifest_id" in expected_references and command is not None:
            command_manifest = command.artifact_ids.get("wiki_manifest")
            supplied_manifest = references.get("manifest_id")
            if supplied_manifest is None and type(command_manifest) is str:
                references["manifest_id"] = command_manifest
            elif (supplied_manifest is not None and supplied_manifest != command_manifest):
                reasons.append("semantic_manifest_command_mismatch:" + name)
        for key, artifact_type in expected_references.items():
            artifact_id = references.get(key)
            if type(artifact_id) is not str or evidence.artifact_types.get(artifact_id) != artifact_type:
                reasons.append("semantic_missing_reference:" + name + ":" + key)
        if set(references) != set(expected_references):
            reasons.append("semantic_unexpected_reference:" + name)

        data: dict[str, Any] = {}
        receipt_operation = name.split("_receipt_", 1)[0] if "_receipt_" in name else None
        if receipt_operation is not None:
            if receipt_operation not in receipt_operations:
                reasons.append("semantic_unexpected_receipt_event:" + name)
            else:
                data = {"receipt_id": _semantic_receipt_id(receipt_operation)}
        elif rule.mode == "marker_delivery":
            data = _semantic_delivery_data(name, deliveries_by_operation) or {}
            if not data:
                reasons.append("semantic_missing_delivery:" + name)

        marker_record = _semantic_marker_record(evidence.run_id, marker)
        record_id = f"event-{sequence}"
        record: dict[str, Any] = {
            "run_id": evidence.run_id,
            "execution_id": marker.execution_id,
            "event_name": name,
            "marker_id": marker.marker_id,
            "evidence_mode": rule.mode,
            **dict(references),
        }
        corroboration_ids: list[str] = []
        if command is not None:
            record |= {
                "command_id": command.command_id,
                "argv_sha256": _sha256(_canonical_json(list(command.argv))),
                # Task 7a's event-record join is over the parsed JSON value;
                # the command observation separately seals the exact captured
                # bytes (which may include harmless framing such as a newline).
                "result_sha256": _sha256(_canonical_json(command.result)),
            }
            corroboration_ids = [command.command_id]
        working_markers[marker.marker_id] = marker_record
        working_records[record_id] = record
        working_events.append({
            "sequence": sequence, "name": name, "execution_id": marker.execution_id,
            "transcript_marker_id": marker.marker_id, "event_record_id": record_id,
            "corroboration_ids": corroboration_ids, "data": data,
            "evidence_mode": rule.mode,
        })
        previous_marker = marker_position

    # Reproduce the public contract's cursor-aware ordering boundary before a
    # plan can emit artifacts: every proof page must close before its marker,
    # and a command first seen after an earlier event cannot predate that
    # marker.  Reused explicit aliases remain valid because their command ID
    # is already in ``seen_commands``.
    seen_commands: set[str] = set()
    prior_marker: tuple[int, int] | None = None
    for event in working_events:
        marker = markers.get(event["name"])
        record = working_records[event["event_record_id"]]
        if marker is None:
            continue
        marker_position = _semantic_position(
            evidence.execution_order, marker.execution_id, marker.candidate.trace_sequence,
        )
        if marker_position is None:
            continue
        command_ids: list[str] = []
        proof_id = record.get("cursor_proof_id")
        if type(proof_id) is str:
            proof = referenced_cursor_proofs.get(proof_id)
            if proof is None:
                reasons.append("semantic_missing_cursor_proof:" + event["name"])
            else:
                command_ids.extend(proof.command_ids)
        command_id = record.get("command_id")
        if type(command_id) is str and command_id not in command_ids:
            command_ids.append(command_id)
        for command_id in command_ids:
            command = command_by_id.get(command_id)
            if command is None:
                reasons.append("semantic_missing_command:" + event["name"])
                continue
            start = _semantic_position(evidence.execution_order, command.execution_id, command.start_sequence)
            end = _semantic_position(evidence.execution_order, command.execution_id, command.end_sequence)
            if start is None or end is None or command.execution_id != marker.execution_id or not end < marker_position:
                reasons.append("semantic_command_marker_order:" + event["name"])
                continue
            if command_id not in seen_commands and prior_marker is not None and start <= prior_marker:
                reasons.append("semantic_command_prerequisite_order:" + event["name"])
            seen_commands.add(command_id)
        prior_marker = marker_position

    for users in selected_commands.values():
        if len(users) > 1 and tuple(users) not in _SEMANTIC_REUSE_GROUPS:
            reasons.append("semantic_command_reuse:" + ",".join(users))

    # The public validator's global audit requires every observed outer shim
    # invocation to have one workflow purpose.  Retain that property while
    # still allowing a complete cursor proof to own its continuation rows.
    accounted_commands = set(selected_commands)
    for proof in referenced_cursor_proofs.values():
        accounted_commands.update(proof.command_ids)
    for command_id in command_by_id:
        if command_id not in accounted_commands:
            reasons.append("semantic_unaccounted_command:" + command_id)

    receipts: list[dict[str, Any]] = []
    planned_deliveries: list[dict[str, Any]] = []
    for operation in receipt_operations:
        stages = ("verified", "consumed", "durable", "acknowledged")
        commands = [selected_by_name.get(f"{operation}_receipt_{stage}") for stage in stages]
        if any(command is None for command in commands):
            reasons.append("semantic_missing_receipt_lifecycle:" + operation)
            continue
        verify, consume, durable, acknowledge = commands
        assert verify is not None and consume is not None and durable is not None and acknowledge is not None
        if len({verify.command_id, consume.command_id, durable.command_id, acknowledge.command_id}) != 4:
            reasons.append("semantic_receipt_command_reuse:" + operation)
            continue
        source_state_ids: list[str] = []
        # Task 7b owns a post-command source checkpoint for receipt
        # verification and first consumption.  It intentionally does not
        # synthesize one after acknowledgement, so requiring every role here
        # would make the real bridge impossible to satisfy.  Task 7a uses
        # these two checkpoints as the lifecycle authority and audits any
        # optional later checkpoint if one exists.
        for stage, command in (("verified", verify), ("consumed", consume)):
            assert command is not None
            state_id = command.artifact_ids.get("source_state")
            if evidence.artifact_types.get(state_id) != "source_state":
                reasons.append("semantic_missing_receipt_source_state:" + operation + ":" + stage)
                continue
            source_state_ids.append(state_id)
        # Each shim observation owns its own post-command checkpoint.  A
        # shared arbitrary state ID could otherwise hide an intervening ledger
        # mutation that Task 7a's receipt lifecycle must reject.
        if len(source_state_ids) != 2:
            continue
        if len(set(source_state_ids)) != len(source_state_ids):
            reasons.append("semantic_receipt_source_state_reuse:" + operation)
            continue
        stream_id = verify.artifact_ids.get("sync_stream")
        durable_id = durable.artifact_ids.get("consumption_receipt")
        if evidence.artifact_types.get(stream_id) != "sync_stream":
            reasons.append("semantic_missing_receipt_stream:" + operation)
            continue
        if evidence.artifact_types.get(durable_id) != "consumption_receipt":
            reasons.append("semantic_missing_receipt_durable:" + operation)
            continue
        delivery = deliveries_by_operation.get(operation)
        requires_delivery = f"{operation}_handoff_delivery_verified" in required
        if requires_delivery and delivery is None:
            reasons.append("semantic_missing_receipt_delivery:" + operation)
            continue
        if not requires_delivery and delivery is not None:
            reasons.append("semantic_unexpected_receipt_delivery:" + operation)
            continue
        receipt_id = _semantic_receipt_id(operation)
        receipts.append({
            "id": receipt_id, "operation": operation,
            "verify_command_id": verify.command_id, "consume_command_id": consume.command_id,
            "durable_command_id": durable.command_id, "acknowledge_command_id": acknowledge.command_id,
            "delivery_id": None if delivery is None else delivery.delivery_id,
            "stream_artifact_id": stream_id, "durable_artifact_id": durable_id,
        })
        if delivery is not None:
            planned_deliveries.append({
                "id": delivery.delivery_id, "receipt_id": receipt_id,
                "delivery_artifact_id": delivery.artifact_id,
                "items": [dict(item) for item in delivery.items],
            })

    if reasons:
        return SemanticEventPlan(
            (), {}, {}, (), (), tuple(sorted(set(reasons))),
        )
    return SemanticEventPlan(
        tuple(working_events), working_records, working_markers,
        tuple(receipts), tuple(planned_deliveries), (),
    )


def normalize_native_transcript(*, client: str, version: str, transcript: bytes) -> NativeNormalization:
    """Use only Task 7a's sourced parser; unknown formats are never inferred."""

    if client == "codex":
        return NativeNormalization(False, "unsupported_native_format")
    if client != "claude" or version != "2.1.251":
        return NativeNormalization(False, "unsupported_native_format")
    try:
        # This is the one version-matched adapter accepted by the event-log
        # contract.  It also rejects marker text in unapproved record shapes.
        from tests.evals.event_log_contract import _native_transcript

        records = _native_transcript(transcript, client, version, "claude-stream-json-2.1.251-v1")
    except Exception:
        return NativeNormalization(False, "unsupported_native_format")
    return NativeNormalization(True, None, records)


def extract_event_markers(
    *,
    transcript: bytes,
    native_records: Mapping[int, Mapping[str, Any]],
    trace_records: Sequence[Mapping[str, Any]],
    transcript_id: str,
    allowed_event_names: Iterable[str],
) -> tuple[MarkerCandidate, ...]:
    """Extract only exact event lines from the sourced Claude parser output.

    A marker never becomes evidence merely by being in assistant prose.  This
    helper returns byte-accurate candidates only after independently reusing
    the Task 7a parser and joining every native row to the runner's shared
    ordering trace.  The caller must still perform event-specific
    corroboration and therefore cannot use this routine to synthesize a pass.
    """

    allowed = frozenset(allowed_event_names)
    if (not allowed or any(type(name) is not str or not name for name in allowed)
            or type(transcript_id) is not str or not transcript_id):
        raise RunnerError("invalid event marker allowlist")
    try:
        from tests.evals import event_log_contract as contract

        parsed = contract._native_transcript(
            transcript, "claude", "2.1.251", "claude-stream-json-2.1.251-v1"
        )
    except Exception as error:
        raise RunnerError("unsupported native transcript for marker extraction") from error
    if dict(native_records) != parsed:
        raise RunnerError("native parser record mismatch")

    validate_trace_records(trace_records)
    traced: dict[int, tuple[int, Mapping[str, Any]]] = {}
    trace_offsets: list[int] = []
    for row in trace_records:
        if row.get("kind") != "native_record":
            continue
        if set(row) != {
            "sequence", "kind", "transcript_id", "byte_start", "byte_end", "sha256",
            "workspace_snapshot_id",
        }:
            raise RunnerError("shared native trace shape invalid")
        start = row["byte_start"]
        if (row["transcript_id"] != transcript_id or type(start) is not int
                or start in traced):
            raise RunnerError("shared native trace binding invalid")
        traced[start] = (row["sequence"], row)
        trace_offsets.append(start)

    ordered_starts = sorted(parsed)
    if trace_offsets != ordered_starts or set(traced) != set(parsed):
        raise RunnerError("shared native trace does not partition transcript")

    previous_end = 0
    for start in ordered_starts:
        record = parsed[start]
        end = record.get("end")
        digest = record.get("sha256")
        raw = transcript[start:end] if type(end) is int else b""
        sequence, trace = traced[start]
        if (start != previous_end or type(end) is not int or end <= start
                or type(digest) is not str or end > len(transcript)
                or _sha256(raw) != digest or trace["byte_end"] != end
                or trace["sha256"] != digest or type(sequence) is not int):
            raise RunnerError("native transcript trace span mismatch")
        previous_end = end
    if previous_end != len(transcript):
        raise RunnerError("native transcript trace is incomplete")

    candidates: list[MarkerCandidate] = []
    seen_names: set[str] = set()
    for start in ordered_starts:
        record = parsed[start]
        texts = record["texts"]
        if type(texts) is not dict:
            raise RunnerError("native parser text projection invalid")
        ordered_texts: list[tuple[int, str, str]] = []
        for pointer, text in texts.items():
            if type(pointer) is not str or type(text) is not str:
                raise RunnerError("native marker pointer invalid")
            prefix = "/message/content/"
            suffix = "/text"
            index_text = pointer.removeprefix(prefix).removesuffix(suffix)
            if (not pointer.startswith(prefix) or not pointer.endswith(suffix)
                    or not index_text.isdecimal()
                    or pointer != f"{prefix}{int(index_text)}{suffix}"):
                raise RunnerError("native marker pointer invalid")
            ordered_texts.append((int(index_text), pointer, text))
        for _index, pointer, text in sorted(ordered_texts):
            raw_text = text.encode("utf-8")
            try:
                code_lines = contract._native_markdown_code_coverage(text, raw_text)
                line_spans = contract._native_text_line_spans(raw_text)
            except Exception as error:
                raise RunnerError("native marker markdown classification failed") from error
            for line_index, (line_start, line_end) in enumerate(line_spans):
                if line_index in code_lines:
                    continue
                line = raw_text[line_start:line_end]
                marker = contract._NATIVE_EVENT_LINE.fullmatch(line)
                if marker is not None:
                    event_name = marker.group(1).decode("ascii")
                    if event_name not in allowed:
                        raise RunnerError("unrecognized transcript marker")
                    if event_name in seen_names:
                        raise RunnerError("duplicate transcript marker")
                    seen_names.add(event_name)
                    sequence, _trace = traced[start]
                    candidates.append(MarkerCandidate(
                        event_name=event_name,
                        marker=line.decode("ascii"),
                        byte_start=line_start,
                        byte_end=line_start + len(line),
                        excerpt_sha256=_sha256(line),
                        native_record_start=start,
                        native_record_end=record["end"],
                        native_record_sha256=record["sha256"],
                        text_pointer=pointer,
                        trace_sequence=sequence,
                    ))
                elif line.startswith(b"EVENT:"):
                    raise RunnerError("malformed transcript marker line")
    return tuple(candidates)


@dataclass(frozen=True)
class ProcessCapture:
    exit_code: int
    stdout: bytes
    stderr: bytes
    version: bytes
    help: bytes
    # Test-only streaming seam.  The closed registered Claude/web
    # approval-phase bridge feeds its actual pipe reader through this same
    # interface; a complete stdout value remains supported for failure tests.
    stdout_chunks: Iterable[bytes] | None = None


ProcessRunner = Callable[[list[str], Path, dict[str, str], bytes], ProcessCapture]


@dataclass(frozen=True)
class _TestOnlyRegisteredLiveLaunch:
    """Host-test adapters for the registered live path, never a pass authority.

    This private seam has no CLI/environment/configuration input.  It exists
    solely so focused tests can exercise the registered-launch assembly with
    fake probe and pipe objects; ``run_scenario`` records an irrevocable
    incomplete reason whenever it is present.
    """

    probe_runner: Callable[[list[str], Path, dict[str, str]], subprocess.CompletedProcess[bytes]]
    popen_factory: Callable[..., Any]

    def __post_init__(self) -> None:
        if not callable(self.probe_runner) or not callable(self.popen_factory):
            raise RunnerError("test registered live launch adapters invalid")
        if self.popen_factory is subprocess.Popen:
            raise RunnerError("test registered live launch cannot use subprocess.Popen")


# This remains ``None`` in every normal invocation.  Tests may monkeypatch
# it with fake in-process adapters, but the run still has a structural
# incomplete reason and never reaches pass publication.
_TEST_ONLY_REGISTERED_LIVE_LAUNCH: _TestOnlyRegisteredLiveLaunch | None = None


@dataclass(frozen=True)
class RegisteredLivePhase:
    """Pre-publication evidence from one runner-registered live phase.

    This is deliberately not an execution-log claim.  It carries the host
    facts a later reviewed public-emission route would need, while ordinary
    ``run_scenario`` remains incomplete-only until that route is introduced
    atomically.
    """

    capture: ProcessCapture
    trusted_executable: Any
    trusted_context: Any
    control_pin: PinnedDirectory
    workspace_pin: PinnedDirectory
    executable_id: str
    version_id: str
    help_id: str
    argv: tuple[str, ...]
    reported_version: str
    native_format: str
    supported_build_id: str
    launch_identity: Mapping[str, int]
    launch_sha256: str
    seal_identity: Mapping[str, int]
    seal_sha256: str


class _NativeStdoutArrivalCapture:
    """Retain stdout while binding each complete arrived row to a snapshot."""

    def __init__(
        self,
        *,
        trace: ControlTraceWriter,
        transcript_id: str,
        on_native_record: Callable[[bytes, int, int, int], str],
        after_native_snapshot: Callable[[str], None] | None = None,
        after_native_record: Callable[[], None] | None = None,
        expected_trace_provider: Callable[[], _ControlTraceSnapshot | None] | None = None,
        after_native_trace_append: Callable[[_ControlTraceSnapshot], None] | None = None,
    ) -> None:
        if after_native_snapshot is not None and not callable(after_native_snapshot):
            raise RunnerError("native stdout post-snapshot checkpoint is invalid")
        if after_native_record is not None and not callable(after_native_record):
            raise RunnerError("native stdout post-record checkpoint is invalid")
        if ((expected_trace_provider is None) != (after_native_trace_append is None)
                or expected_trace_provider is not None and (
                    not callable(expected_trace_provider)
                    or not callable(after_native_trace_append)
                )):
            raise RunnerError("native stdout trace transition checkpoint is invalid")
        self._trace = trace
        self._transcript_id = transcript_id
        self._on_native_record = on_native_record
        self._after_native_snapshot = after_native_snapshot
        self._after_native_record = after_native_record
        self._expected_trace_provider = expected_trace_provider
        self._after_native_trace_append = after_native_trace_append
        self._retained: list[bytes] = []
        self._partial = b""
        self._offset = 0
        self._total = 0

    def _append_native(self, raw: bytes) -> None:
        start = self._offset
        append_kwargs: dict[str, Any] = {
            "transcript_id": self._transcript_id,
            "byte_start": start,
            "byte_end": start + len(raw),
            "sha256": _sha256(raw),
            "snapshot_factory": (
                lambda sequence, current=raw, current_start=start: self._on_native_record(
                    current, current_start, current_start + len(current), sequence,
                )
            ),
        }
        if self._after_native_snapshot is not None:
            append_kwargs["snapshot_observer"] = self._after_native_snapshot
        # Preserve the legacy append call shape unless a private caller has
        # explicitly requested the phase-two transition receipt protocol.
        if self._expected_trace_provider is not None:
            append_kwargs["expected_trace_provider"] = self._expected_trace_provider
            append_kwargs["after_native_trace_append"] = self._after_native_trace_append
        self._trace.append_native_record(**append_kwargs)
        if self._after_native_record is not None:
            self._after_native_record()
        self._offset += len(raw)

    def feed(self, chunk: bytes) -> None:
        if type(chunk) is not bytes:
            raise RunnerError("native stdout stream yielded non-bytes")
        self._total += len(chunk)
        if self._total > _MAX_CAPTURE_BYTES:
            raise RunnerError("native stdout stream exceeds size limit")
        self._retained.append(chunk)
        self._partial += chunk
        while True:
            newline = self._partial.find(b"\n")
            if newline < 0:
                return
            line, self._partial = self._partial[:newline + 1], self._partial[newline + 1:]
            self._append_native(line)

    def finish(self) -> bytes:
        if self._partial:
            self._append_native(self._partial)
            self._partial = b""
        return b"".join(self._retained)


def _capture_native_stdout(
    capture: ProcessCapture,
    *, trace: ControlTraceWriter,
    transcript_id: str,
    on_native_record: Callable[[bytes, int, int, int], str] | None = None,
    after_native_snapshot: Callable[[str], None] | None = None,
    after_native_record: Callable[[], None] | None = None,
    expected_trace_provider: Callable[[], _ControlTraceSnapshot | None] | None = None,
    after_native_trace_append: Callable[[_ControlTraceSnapshot], None] | None = None,
) -> bytes:
    """Consume native stdout in arrival order and allocate its trace rows.

    A chunk is not necessarily a JSONL record.  The writer therefore retains a
    partial line until its LF arrives, then atomically gives that exact record
    the next sequence number.  This makes the test seam capable of witnessing
    a shim invocation between two client records instead of assigning every
    native row only after the process callback has returned.
    """

    if capture.stdout_chunks is None:
        chunks: Iterable[bytes] = (capture.stdout,)
    else:
        if capture.stdout:
            raise RunnerError("streaming capture also supplied complete stdout")
        chunks = capture.stdout_chunks
    if on_native_record is None:
        raise RunnerError("native stdout capture requires a workspace snapshot sink")

    arrival = _NativeStdoutArrivalCapture(
        trace=trace,
        transcript_id=transcript_id,
        on_native_record=on_native_record,
        after_native_snapshot=after_native_snapshot,
        after_native_record=after_native_record,
        expected_trace_provider=expected_trace_provider,
        after_native_trace_append=after_native_trace_append,
    )
    for chunk in chunks:
        # Capture a host inventory for every arrived native record.  The
        # parser later determines which records contain admissible markers,
        # including JSON-escaped marker text that raw-byte matching cannot
        # see.  The capture occurs before the row receives its shared trace
        # sequence and cannot become an event claim by itself.
        arrival.feed(chunk)
    return arrival.finish()


def _close_live_streams(streams: Iterable[Any]) -> None:
    """Close pipe descriptors on every launch/error path."""

    for stream in streams:
        try:
            if not stream.closed:
                stream.close()
        except (AttributeError, OSError, ValueError):
            pass


def _terminate_and_reap_live_process(process: Any) -> None:
    """Best-effort cleanup that never masks the original capture failure."""

    try:
        process.terminate()
    except Exception:
        pass
    try:
        process.wait(timeout=_LIVE_PROCESS_REAP_TIMEOUT_SECONDS)
        return
    except subprocess.TimeoutExpired:
        try:
            process.kill()
        except Exception:
            pass
        try:
            process.wait(timeout=_LIVE_PROCESS_REAP_TIMEOUT_SECONDS)
        except Exception:
            pass
    except Exception:
        pass


def _remaining_live_phase_time(started_at: float) -> float:
    remaining = _LIVE_PHASE_TOTAL_TIMEOUT_SECONDS - (time.monotonic() - started_at)
    if remaining <= 0:
        raise RunnerError("registered client process timed out")
    return remaining


def _stream_live_phase(
    *,
    argv: Sequence[str],
    cwd: Path,
    environment: Mapping[str, str],
    stdin: bytes,
    trace: ControlTraceWriter,
    transcript_id: str,
    on_native_record: Callable[[bytes, int, int, int], str],
    popen_factory: Callable[..., Any] = subprocess.Popen,
    pre_popen_guard: Callable[[], None] | None = None,
    after_native_snapshot: Callable[[str], None] | None = None,
    after_native_record: Callable[[], None] | None = None,
    expected_trace_provider: Callable[[], _ControlTraceSnapshot | None] | None = None,
    after_native_trace_append: Callable[[_ControlTraceSnapshot], None] | None = None,
) -> ProcessCapture:
    """Run one already-registered client while draining both pipes live.

    The caller is responsible for executable registration and fresh probes.
    This API refuses a symbolic/noncanonical program path so it cannot become
    an alternate discovery route.  It never calls ``communicate``: every
    native stdout row is snapshotted and appended to the shared trace before
    the final process exit is waited for.
    """

    if (type(stdin) is not bytes or type(transcript_id) is not str or not transcript_id
            or not isinstance(argv, Sequence) or isinstance(argv, (str, bytes))
            or not argv or any(type(item) is not str or not item or "\0" in item for item in argv)):
        raise RunnerError("live phase invocation invalid")
    if pre_popen_guard is not None and not callable(pre_popen_guard):
        raise RunnerError("live phase pre-Popen guard is invalid")
    if after_native_record is not None and not callable(after_native_record):
        raise RunnerError("live phase post-record checkpoint is invalid")
    if after_native_snapshot is not None and not callable(after_native_snapshot):
        raise RunnerError("live phase post-snapshot checkpoint is invalid")
    if ((expected_trace_provider is None) != (after_native_trace_append is None)
            or expected_trace_provider is not None and (
                not callable(expected_trace_provider)
                or not callable(after_native_trace_append)
            )):
        raise RunnerError("live phase trace transition checkpoint is invalid")
    _absolute_executable_path(argv[0])
    if not cwd.is_absolute() or not cwd.is_dir():
        raise RunnerError("live phase workspace unavailable")
    if (not isinstance(environment, Mapping)
            or any(type(key) is not str or type(value) is not str for key, value in environment.items())):
        raise RunnerError("live phase environment invalid")
    # A private caller may use this final, zero-input callback to repeat a
    # transition gate after probes but directly before process creation.  It
    # deliberately runs adjacent to ``Popen`` so a phase boundary cannot be
    # approved only at setup time and then silently drift during probing.
    if pre_popen_guard is not None:
        pre_popen_guard()
    try:
        process = popen_factory(
            list(argv), cwd=cwd, env=dict(environment), stdin=subprocess.PIPE,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0,
            close_fds=True, shell=False,
        )
    except OSError as error:
        raise RunnerError("registered client launch unavailable") from error
    acquired_streams: list[Any] = []
    try:
        try:
            stdin_stream = process.stdin
            acquired_streams.append(stdin_stream)
            stdout_stream = process.stdout
            acquired_streams.append(stdout_stream)
            stderr_stream = process.stderr
            acquired_streams.append(stderr_stream)
        except (AttributeError, OSError, ValueError) as error:
            raise RunnerError("registered client launch streams unavailable") from error
        if stdin_stream is None or stdout_stream is None or stderr_stream is None:
            raise RunnerError("registered client launch streams unavailable")
    except BaseException:
        _close_live_streams(acquired_streams)
        _terminate_and_reap_live_process(process)
        raise

    streams = {"stdout": stdout_stream, "stderr": stderr_stream}
    started_at = time.monotonic()

    try:
        try:
            if stdin:
                stdin_stream.write(stdin)
            stdin_stream.flush()
        finally:
            stdin_stream.close()
    except (OSError, ValueError, AttributeError) as error:
        _close_live_streams(streams.values())
        _terminate_and_reap_live_process(process)
        raise RunnerError("registered client stdin delivery failed") from error

    arrival = _NativeStdoutArrivalCapture(
        trace=trace,
        transcript_id=transcript_id,
        on_native_record=on_native_record,
        after_native_snapshot=after_native_snapshot,
        after_native_record=after_native_record,
        expected_trace_provider=expected_trace_provider,
        after_native_trace_append=after_native_trace_append,
    )
    stderr_chunks: list[bytes] = []
    stderr_total = 0
    selector: Any | None = None
    process_waited = False
    try:
        selector = selectors.DefaultSelector()
        for name, stream in streams.items():
            try:
                fd = stream.fileno()
                os.set_blocking(fd, False)
            except (AttributeError, OSError, ValueError) as error:
                raise RunnerError("registered client stream is not selectable") from error
            selector.register(stream, selectors.EVENT_READ, data=name)
        last_activity = time.monotonic()
        while selector.get_map():
            events = selector.select(timeout=min(1.0, _remaining_live_phase_time(started_at)))
            if not events:
                if time.monotonic() - last_activity > _LIVE_STREAM_IDLE_TIMEOUT_SECONDS:
                    raise RunnerError("registered client stream timed out")
                continue
            for key, _mask in events:
                try:
                    chunk = os.read(key.fd, _LIVE_STREAM_READ_BYTES)
                except BlockingIOError:
                    continue
                except OSError as error:
                    raise RunnerError("registered client stream read failed") from error
                if not chunk:
                    selector.unregister(key.fileobj)
                    key.fileobj.close()
                    continue
                last_activity = time.monotonic()
                if key.data == "stdout":
                    arrival.feed(chunk)
                else:
                    stderr_total += len(chunk)
                    if stderr_total > _MAX_CAPTURE_BYTES:
                        raise RunnerError("registered client stderr exceeds size limit")
                    stderr_chunks.append(chunk)
        # The pipes are fully drained and all native records have their
        # snapshot/trace ordering before we ask the process for its exit.
        stdout = arrival.finish()
        try:
            exit_code = process.wait(timeout=_remaining_live_phase_time(started_at))
        except subprocess.TimeoutExpired as error:
            raise RunnerError("registered client process timed out") from error
        except (AttributeError, OSError, TypeError, ValueError) as error:
            raise RunnerError("registered client wait failed") from error
        process_waited = True
        if type(exit_code) is not int:
            raise RunnerError("registered client exit status invalid")
        return ProcessCapture(exit_code, stdout, b"".join(stderr_chunks), b"", b"")
    except BaseException:
        if not process_waited:
            _terminate_and_reap_live_process(process)
        raise
    finally:
        if selector is not None:
            selector.close()
        _close_live_streams(streams.values())


def _runner_owned_registration(client: str) -> RunnerOwnedExecutableRegistration:
    """Return only a code-owned, exact client registration."""

    registration = _RUNNER_OWNED_EXECUTABLES.get(client)
    if not isinstance(registration, RunnerOwnedExecutableRegistration) or registration.client != client:
        raise RunnerError("client executable is not runner-registered")
    return registration


@dataclass(frozen=True)
class RegisteredActualScenarioPlan:
    """Closed inputs for the registered phase-one diagnostic bridge.

    The private dispatcher accepts only the exact Claude
    ``web-approval-and-capture`` plan, and only its ``approval`` phase.
    This value carries no host process, probe, environment, executable
    override, phase-two, or pass authority; callers cannot use it to select
    an executable from JSON, PATH, HOME, or test adapters.
    """

    client: str
    scenario_id: str
    scratch_root: Path | None
    symbolic_template: tuple[str, ...]
    network_attestation: str
    registration: RunnerOwnedExecutableRegistration


@dataclass(frozen=True)
class _RegisteredActualAuthority:
    """Private route token for one closed, runner-prepared actual plan.

    This is an API-routing boundary, not a substitute for the pinned host
    evidence that the closed bridge must establish.  Keeping the plan
    behind this concrete private type makes it impossible for the legacy
    JSON/process-runner route to accidentally call the actual dispatcher.
    """

    plan: RegisteredActualScenarioPlan

    def __post_init__(self) -> None:
        if type(self.plan) is not RegisteredActualScenarioPlan:
            raise RunnerError("registered actual authority is invalid")


def _runner_owned_symbolic_profile(client: str) -> tuple[tuple[str, ...], str]:
    """Select a fixed client profile without accepting caller argv or policy."""

    if client == "codex":
        return tuple(_CODEX_TEMPLATE), "workspace-egress-denied"
    if client == "claude":
        return tuple(_CLAUDE_TEMPLATE), "mock-only"
    raise RunnerError("unsupported client")


def prepare_registered_actual_scenario(
    *,
    client: str,
    scenario_id: str,
    scratch_root: Path | None = None,
) -> RegisteredActualScenarioPlan:
    """Prepare a closed actual-live plan; this function cannot launch or pass.

    It is intentionally separate from ``run_scenario`` and the public CLI.
    Legacy CLI JSON remains an incomplete-only symbolic-profile selector; the
    closed private bridge receives neither that JSON nor a caller-provided
    executable, environment, process adapter, probe adapter, or Popen hook.
    """

    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual execution")
    if (type(client) is not str or type(scenario_id) is not str
            or scratch_root is not None and not isinstance(scratch_root, Path)):
        raise RunnerError("registered actual scenario inputs invalid")
    # Validate the closed generated scenario before constructing any future
    # workspace.  This is intentionally a read-only dispatch check.
    _scenario(scenario_id)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(client)
    registration = _runner_owned_registration(client)
    return RegisteredActualScenarioPlan(
        client=client,
        scenario_id=scenario_id,
        scratch_root=scratch_root,
        symbolic_template=symbolic_template,
        network_attestation=network_attestation,
        registration=registration,
    )


def _run_registered_actual_plan(authority: _RegisteredActualAuthority) -> "RunOutcome":
    """Run only the closed Claude/web phase-one diagnostic bridge.

    This is not a general actual dispatcher: every non-Claude/web plan stops
    before workspace construction, and the one enabled path ends at sealed
    incomplete diagnostic evidence without semantic or phase-two authority.
    """

    if type(authority) is not _RegisteredActualAuthority:
        raise RunnerError("registered actual authority is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot execute actual execution")
    plan = authority.plan
    if type(plan) is not RegisteredActualScenarioPlan:
        raise RunnerError("registered actual authority is invalid")
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phase_plan(plan.scenario_id) != ("approval", "approved_capture")):
        raise RunnerError("registered actual phase-one diagnostic bridge rejects this plan")

    prepared_run = _prepare_registered_actual_run(authority)
    prepared_phase = _prepare_registered_actual_phase_one(prepared_run)
    live_phase = _launch_actual_registered_live_phase(prepared_phase)
    diagnostic = _index_registered_actual_phase_one_diagnostic(prepared_phase, live_phase)
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    if not _registered_phase_evidence_is_bound(
        writer=prepared_run.writer,
        workspace=prepared_run.prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=diagnostic.live_phase,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    receipt_gate = _reconstruct_actual_phase_one_receipt_gate(
        writer=prepared_run.writer,
        phase_one=diagnostic.live_phase,
        scenario=scenario,
        conversion=diagnostic.conversion,
        workspace=prepared_run.prepared.workspace,
        execution_id="execution-1",
    )
    if receipt_gate is not None and (
            type(receipt_gate) is not PhaseOneReceiptGate
            or receipt_gate.execution_id != "execution-1"):
        raise RunnerError("registered actual phase-one receipt gate is invalid")
    if not _registered_phase_evidence_is_bound(
        writer=prepared_run.writer,
        workspace=prepared_run.prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=diagnostic.live_phase,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    log = _incomplete_log(
        run_id=prepared_run.run_id,
        scenario=scenario,
        client="claude",
        version=live_phase.reported_version,
        fixture_sha256=metadata.fixture_sha256,
        executions=[{
            "id": "execution-1", "phase": "approval", "kind": "actual_client_process",
            "policy_id": diagnostic.policy_id, "process_id": diagnostic.process_id,
            "transcript_id": diagnostic.transcript_id,
        }],
        reasons=[
            "public_semantic_projection_unavailable"
            if receipt_gate is not None else "web_approval_phase_unverified"
        ],
    )
    path = _finalize_registered_actual_phase_one_diagnostic(prepared_run.writer, log)
    return RunOutcome(
        log, path, prepared_run.prepared.workspace, prepared_run.prepared.control_root,
        trusted_context=None,
    )


def run_registered_actual_scenario(
    *,
    client: str,
    scenario_id: str,
    scratch_root: Path | None = None,
) -> "RunOutcome":
    """Enter the closed actual phase-one diagnostic bridge only."""

    plan = prepare_registered_actual_scenario(
        client=client, scenario_id=scenario_id, scratch_root=scratch_root,
    )
    return _run_registered_actual_plan(_RegisteredActualAuthority(plan))


def _verify_registered_phase_roots(
    *,
    writer: EvidenceWriter,
    workspace: Path,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
    trace: ControlTraceWriter,
) -> None:
    """Require the live phase to retain disjoint pinned control/workspace roots."""

    if (not isinstance(control_pin, PinnedDirectory) or not isinstance(workspace_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != writer.control_root.resolve()
            or workspace_pin.path != workspace.resolve()
            or trace.control_root != control_pin.path or trace.control_pin is not control_pin):
        raise RunnerError("registered live phase root pin mismatch")
    control = control_pin.path
    workspace_root = workspace_pin.path
    if (control == workspace_root or control in workspace_root.parents
            or workspace_root in control.parents):
        raise RunnerError("registered live phase roots overlap")
    PinnedDirectory.verify(control_pin)
    PinnedDirectory.verify(workspace_pin)


def _registered_executable_observation(
    trusted_executable: Any,
) -> tuple[dict[str, int], str]:
    """Descriptor-read and compare one phase-local executable observation."""

    try:
        from tests.evals import event_log_contract as contract

        raw, identity = contract._read_executable(os.fspath(trusted_executable.resolved_path))
    except Exception as error:
        raise RunnerError("registered executable unavailable") from error
    digest = _sha256(raw)
    if identity != dict(trusted_executable.identity) or digest != trusted_executable.sha256:
        raise RunnerError("registered executable changed during evaluation")
    return identity, digest


def _remaining_registered_probe_time(started_at: float) -> float:
    """Return the remaining total wall-clock budget for one closed probe."""

    remaining = _REGISTERED_PROBE_TIMEOUT_SECONDS - (time.monotonic() - started_at)
    if remaining <= 0:
        raise RunnerError("registered executable probe timed out")
    return remaining


def _bounded_registered_probe(
    *,
    argv: list[str],
    cwd: Path,
    environment: Mapping[str, str],
) -> subprocess.CompletedProcess[bytes]:
    """Drain one trusted version/help probe under time and byte bounds.

    ``subprocess.run(..., stdout=PIPE, stderr=PIPE)`` buffers an unbounded
    child stream before a caller can inspect it.  Probe bytes are evidence, so
    this tiny owner drains both streams concurrently and stops at their hard
    independent limits before returning the exact successful bytes.
    """

    started_at = time.monotonic()
    try:
        process = subprocess.Popen(
            argv, cwd=cwd, env=dict(environment), stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0,
            close_fds=True, shell=False,
        )
    except OSError as error:
        raise RunnerError("registered executable probe unavailable") from error

    acquired_streams: list[Any] = []
    try:
        try:
            stdout_stream = process.stdout
            acquired_streams.append(stdout_stream)
            stderr_stream = process.stderr
            acquired_streams.append(stderr_stream)
        except (AttributeError, OSError, ValueError) as error:
            raise RunnerError("registered executable probe streams unavailable") from error
        if stdout_stream is None or stderr_stream is None:
            raise RunnerError("registered executable probe streams unavailable")
    except BaseException:
        _close_live_streams(acquired_streams)
        _terminate_and_reap_live_process(process)
        raise

    streams = {"stdout": stdout_stream, "stderr": stderr_stream}
    chunks: dict[str, list[bytes]] = {"stdout": [], "stderr": []}
    totals = {"stdout": 0, "stderr": 0}
    selector: Any | None = None
    process_waited = False
    try:
        selector = selectors.DefaultSelector()
        for name, stream in streams.items():
            try:
                fd = stream.fileno()
                os.set_blocking(fd, False)
            except (AttributeError, OSError, ValueError) as error:
                raise RunnerError("registered executable probe stream is not selectable") from error
            selector.register(stream, selectors.EVENT_READ, data=name)
        while selector.get_map():
            events = selector.select(timeout=min(1.0, _remaining_registered_probe_time(started_at)))
            if not events:
                continue
            for key, _mask in events:
                try:
                    chunk = os.read(key.fd, _LIVE_STREAM_READ_BYTES)
                except BlockingIOError:
                    continue
                except OSError as error:
                    raise RunnerError("registered executable probe stream read failed") from error
                if not chunk:
                    selector.unregister(key.fileobj)
                    key.fileobj.close()
                    continue
                stream_name = key.data
                totals[stream_name] += len(chunk)
                if totals[stream_name] > _MAX_REGISTERED_PROBE_BYTES:
                    raise RunnerError("registered executable probe output exceeds size limit")
                chunks[stream_name].append(chunk)
        try:
            exit_code = process.wait(timeout=_remaining_registered_probe_time(started_at))
        except subprocess.TimeoutExpired as error:
            raise RunnerError("registered executable probe timed out") from error
        except (AttributeError, OSError, TypeError, ValueError) as error:
            raise RunnerError("registered executable probe wait failed") from error
        process_waited = True
        if type(exit_code) is not int:
            raise RunnerError("registered executable probe exit status invalid")
        return subprocess.CompletedProcess(
            argv, exit_code, b"".join(chunks["stdout"]), b"".join(chunks["stderr"]),
        )
    except BaseException:
        if not process_waited:
            _terminate_and_reap_live_process(process)
        raise
    finally:
        if selector is not None:
            selector.close()
        _close_live_streams(streams.values())


def _registered_probe(
    *,
    argv: list[str],
    cwd: Path,
    environment: Mapping[str, str],
    probe_runner: Callable[[list[str], Path, dict[str, str]], subprocess.CompletedProcess[bytes]] | None,
) -> subprocess.CompletedProcess[bytes]:
    """Run exactly one fresh absolute-path probe under runner-owned inputs."""

    try:
        if probe_runner is None:
            completed = _bounded_registered_probe(
                argv=argv, cwd=cwd, environment=environment,
            )
        else:
            completed = probe_runner(list(argv), cwd, dict(environment))
    except subprocess.TimeoutExpired as error:
        raise RunnerError("registered executable probe timed out") from error
    except OSError as error:
        raise RunnerError("registered executable probe unavailable") from error
    if (not isinstance(completed, subprocess.CompletedProcess)
            or type(completed.returncode) is not int
            or type(completed.stdout) is not bytes or type(completed.stderr) is not bytes):
        raise RunnerError("registered executable probe result invalid")
    if (len(completed.stdout) > _MAX_REGISTERED_PROBE_BYTES
            or len(completed.stderr) > _MAX_REGISTERED_PROBE_BYTES):
        raise RunnerError("registered executable probe output exceeds size limit")
    if completed.returncode != 0 or not completed.stdout:
        raise RunnerError("registered executable probe failed")
    return completed


def _registered_live_trusted_context(
    *,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
    trusted_executables: Mapping[str, Any],
) -> Any:
    """Build one descriptor-root-bound context from already-prelaunch facts."""

    if (not isinstance(control_pin, PinnedDirectory) or not isinstance(workspace_pin, PinnedDirectory)
            or not control_pin.private):
        raise RunnerError("registered live context root pins unavailable")
    control = control_pin.path
    workspace = workspace_pin.path
    if (control == workspace or control in workspace.parents or workspace in control.parents):
        raise RunnerError("registered live context roots overlap")
    PinnedDirectory.verify(control_pin)
    PinnedDirectory.verify(workspace_pin)
    try:
        from tests.evals import event_log_contract as contract

        return contract.TrustedRunContext(
            control, workspace, trusted_executables=dict(trusted_executables),
        )
    except Exception as error:
        raise RunnerError("registered live context unavailable") from error


def _registered_actual_phase_two_private_trusted_context(
    *,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
    phase_one_trusted: Any,
    phase_two_trusted: Any,
) -> Any:
    """Detach phase-two executable authority from the returned token context.

    The prepared phase keeps its original context as a shaped diagnostic
    facade, but a caller can mutate nested frozen-Python objects with
    ``object.__setattr__``.  Before that phase can escape, copy the two
    descriptor-verified executable expectations into a fresh private context
    retained only by the one-shot launch binding.
    """

    if (not isinstance(control_pin, PinnedDirectory)
            or not isinstance(workspace_pin, PinnedDirectory)
            or not control_pin.private
            or workspace_pin.private):
        raise RunnerError("registered actual phase-two private context roots are invalid")
    try:
        from tests.evals import event_log_contract as contract

        def clone(executable: Any, execution_id: str) -> Any:
            if (type(executable) is not contract.TrustedExecutable
                    or executable.execution_id != execution_id
                    or executable.client != "claude"
                    or not isinstance(executable.resolved_path, Path)
                    or type(executable.identity) is not MappingProxyType
                    or type(executable.sha256) is not str
                    or type(executable.supported_build_id) is not str):
                raise RunnerError("registered actual phase-two private executable is invalid")
            copied = contract.TrustedExecutable(
                executable.execution_id,
                executable.client,
                os.fspath(executable.resolved_path),
                dict(executable.identity),
                executable.sha256,
                executable.supported_build_id,
            )
            if copied is executable:
                raise RunnerError("registered actual phase-two private executable is invalid")
            return copied

        private_phase_one = clone(phase_one_trusted, "execution-1")
        private_phase_two = clone(phase_two_trusted, "execution-2")
        if private_phase_one is private_phase_two:
            raise RunnerError("registered actual phase-two private executable is invalid")
        context = _registered_live_trusted_context(
            control_pin=control_pin,
            workspace_pin=workspace_pin,
            trusted_executables={
                "execution-1": private_phase_one,
                "execution-2": private_phase_two,
            },
        )
        for execution_id, expected in (
                ("execution-1", private_phase_one),
                ("execution-2", private_phase_two)):
            registration, selected = _registered_live_context_phase(
                client="claude",
                execution_id=execution_id,
                control_pin=control_pin,
                workspace_pin=workspace_pin,
                trusted_context=context,
                expected_execution_ids=frozenset({"execution-1", "execution-2"}),
            )
            if registration is not _runner_owned_registration("claude") or selected is not expected:
                raise RunnerError("registered actual phase-two private context is invalid")
            _registered_executable_observation(selected)
        return context
    except RunnerError:
        raise
    except Exception as error:
        raise RunnerError("registered actual phase-two private context is unavailable") from error


def _prepare_registered_live_executable(
    *,
    client: str,
    execution_id: str,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
) -> tuple[RunnerOwnedExecutableRegistration, Any]:
    """Create one fresh phase-local TrustedExecutable before its launch."""

    registration = _runner_owned_registration(client)
    executable_path = os.fspath(registration.resolved_path)
    try:
        from tests.evals import event_log_contract as contract

        raw, identity = contract._read_executable(executable_path)
        digest = _sha256(raw)
        default_context = _registered_live_trusted_context(
            control_pin=control_pin, workspace_pin=workspace_pin,
            trusted_executables={},
        )
        supported_build_id = default_context.supported_builds.get((
            client, registration.expected_version, registration.native_format, digest,
        ))
        if supported_build_id is None:
            raise RunnerError("registered executable build is unsupported")
        trusted = contract.TrustedExecutable(
            execution_id, client, executable_path, identity, digest, supported_build_id,
        )
    except RunnerError:
        raise
    except Exception as error:
        raise RunnerError("registered executable prelaunch trust unavailable") from error
    return registration, trusted


def _registered_live_context_phase(
    *,
    client: str,
    execution_id: str,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
    trusted_context: Any,
    expected_execution_ids: frozenset[str] | None = None,
) -> tuple[RunnerOwnedExecutableRegistration, Any]:
    """Select this phase's static executable only from its prelaunch context."""

    registration = _runner_owned_registration(client)
    try:
        from tests.evals import event_log_contract as contract

        PinnedDirectory.verify(control_pin)
        PinnedDirectory.verify(workspace_pin)
        if (not isinstance(trusted_context, contract.TrustedRunContext)
                or trusted_context.control_root != control_pin.path
                or trusted_context.workspace_root != workspace_pin.path
                or trusted_context.control_identity != control_pin.edges[-1][1][:2]
                or trusted_context.workspace_identity != workspace_pin.edges[-1][1][:2]):
            raise RunnerError("registered live context root mismatch")
        if (expected_execution_ids is not None
                and set(trusted_context.trusted_executables) != set(expected_execution_ids)):
            raise RunnerError("registered live context execution set mismatch")
        trusted = trusted_context.trusted_executables.get(execution_id)
        if (not isinstance(trusted, contract.TrustedExecutable)
                or trusted.execution_id != execution_id or trusted.client != client
                or trusted.resolved_path != registration.resolved_path):
            raise RunnerError("registered live context executable mismatch")
        expected_build_id = trusted_context.supported_builds.get((
            client, registration.expected_version, registration.native_format, trusted.sha256,
        ))
        if expected_build_id != trusted.supported_build_id:
            raise RunnerError("registered live context build mismatch")
    except RunnerError:
        raise
    except Exception as error:
        raise RunnerError("registered live context unavailable") from error
    return registration, trusted


def _launch_registered_live_phase(
    *,
    writer: EvidenceWriter,
    client: str,
    execution_id: str,
    phase: str,
    phase_index: int,
    workspace: Path,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
    argv: Sequence[str],
    environment: Mapping[str, str],
    stdin: bytes,
    trace: ControlTraceWriter,
    transcript_id: str,
    on_native_record: Callable[[bytes, int, int, int], str],
    probe_runner: Callable[[list[str], Path, dict[str, str]], subprocess.CompletedProcess[bytes]] | None = None,
    popen_factory: Callable[..., Any] = subprocess.Popen,
    trusted_context: Any | None = None,
    pre_popen_guard: Callable[[], None] | None = None,
    live_artifact_checkpoint: Callable[[str], None] | None = None,
    live_trace_provider: Callable[[], _ControlTraceSnapshot | None] | None = None,
    after_live_native_trace_append: Callable[[_ControlTraceSnapshot], None] | None = None,
) -> RegisteredLivePhase:
    """Prepare, probe, stream, and seal one closed registered client phase.

    This helper intentionally ends at retained pre-publication evidence.  It
    neither seals the run index nor constructs a public event log; a later
    reviewed route must perform full validation atomically before a pass can
    be written.
    """

    if (type(execution_id) is not str or not execution_id or type(phase) is not str or not phase
            or type(phase_index) is not int or phase_index < 1
            or not isinstance(argv, Sequence) or isinstance(argv, (str, bytes))
            or not argv or argv[0] != client):
        raise RunnerError("registered live phase requires a symbolic client selector")
    if live_artifact_checkpoint is not None and not callable(live_artifact_checkpoint):
        raise RunnerError("registered live artifact checkpoint is invalid")
    if ((live_trace_provider is None) != (after_live_native_trace_append is None)
            or live_trace_provider is not None and (
                not callable(live_trace_provider)
                or not callable(after_live_native_trace_append)
            )):
        raise RunnerError("registered live trace transition checkpoint is invalid")
    if writer.control_root != writer.control_root.resolve() or not workspace.is_absolute():
        raise RunnerError("registered live phase roots unavailable")
    try:
        canonical_workspace = workspace.resolve(strict=True)
    except OSError as error:
        raise RunnerError("registered live phase roots unavailable") from error
    if (workspace != canonical_workspace or not canonical_workspace.is_dir()
            or canonical_workspace != workspace_pin.path):
        raise RunnerError("registered live phase root pin mismatch")
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    expected_execution_ids = frozenset(
        f"execution-{index}" for index in range(1, phase_index + 1)
    )
    if trusted_context is None:
        if phase_index != 1:
            raise RunnerError("registered live phase context must include prior phases")
        registration, trusted = _prepare_registered_live_executable(
            client=client, execution_id=execution_id, control_pin=control_pin,
            workspace_pin=workspace_pin,
        )
        trusted_context = _registered_live_trusted_context(
            control_pin=control_pin, workspace_pin=workspace_pin,
            trusted_executables={execution_id: trusted},
        )
    else:
        registration, trusted = _registered_live_context_phase(
            client=client, execution_id=execution_id, control_pin=control_pin,
            workspace_pin=workspace_pin, trusted_context=trusted_context,
            expected_execution_ids=expected_execution_ids,
        )
    executable_path = os.fspath(registration.resolved_path)
    supported_build_id = trusted.supported_build_id

    # Every probe is bracketed by fresh descriptor reads.  A changed file or
    # ancestor is a phase failure, never an opportunity to rediscover it.
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    _registered_executable_observation(trusted)
    version = _registered_probe(
        argv=[executable_path, "--version"], cwd=workspace_pin.path, environment=environment,
        probe_runner=probe_runner,
    )
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    _registered_executable_observation(trusted)
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    _registered_executable_observation(trusted)
    help_output = _registered_probe(
        argv=[executable_path, "--help"], cwd=workspace_pin.path, environment=environment,
        probe_runner=probe_runner,
    )
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    _registered_executable_observation(trusted)
    reported_version = _version_text(version.stdout)
    if reported_version != registration.expected_version:
        raise RunnerError("registered executable version does not match closed build")

    version_id = f"version-{phase_index}"
    help_id = f"help-{phase_index}"
    executable_id = f"client-executable-{phase_index}"
    writer.add_bytes(version_id, "version", version.stdout)
    if live_artifact_checkpoint is not None:
        live_artifact_checkpoint("version")
    writer.add_bytes(help_id, "help", help_output.stdout)
    if live_artifact_checkpoint is not None:
        live_artifact_checkpoint("help")
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    launch_identity, launch_sha256 = _registered_executable_observation(trusted)
    final_argv = (executable_path, *tuple(argv[1:]))
    streamed = _stream_live_phase(
        argv=final_argv, cwd=workspace_pin.path, environment=environment, stdin=stdin,
        trace=trace, transcript_id=transcript_id, on_native_record=on_native_record,
        popen_factory=popen_factory, pre_popen_guard=pre_popen_guard,
        after_native_snapshot=(
            None if live_artifact_checkpoint is None
            else lambda _snapshot_id: live_artifact_checkpoint("native_snapshot")
        ),
        after_native_record=(
            None if live_artifact_checkpoint is None or live_trace_provider is not None
            else lambda: live_artifact_checkpoint("native_record")
        ),
        expected_trace_provider=live_trace_provider,
        after_native_trace_append=after_live_native_trace_append,
    )
    if live_artifact_checkpoint is not None:
        live_artifact_checkpoint("stream")
    _verify_registered_phase_roots(
        writer=writer, workspace=canonical_workspace, control_pin=control_pin,
        workspace_pin=workspace_pin, trace=trace,
    )
    seal_identity, seal_sha256 = _registered_executable_observation(trusted)
    writer.add_json(executable_id, "client_executable", {
        "schema_version": 1,
        "run_id": writer.run_id,
        "execution_id": execution_id,
        "phase": phase,
        "client": client,
        "resolved_path": executable_path,
        "launch_identity": launch_identity,
        "launch_sha256": launch_sha256,
        "seal_identity": seal_identity,
        "seal_sha256": seal_sha256,
        "reported_version": reported_version,
        "version_probe": {
            "argv": [executable_path, "--version"],
            "exit_code": version.returncode,
            "output_id": version_id,
            "output_sha256": _sha256(version.stdout),
        },
        "help_probe": {
            "argv": [executable_path, "--help"],
            "exit_code": help_output.returncode,
            "output_id": help_id,
            "output_sha256": _sha256(help_output.stdout),
        },
        "supported_build_id": supported_build_id,
    })
    if live_artifact_checkpoint is not None:
        live_artifact_checkpoint("client_executable")
    return RegisteredLivePhase(
        capture=ProcessCapture(
            streamed.exit_code, streamed.stdout, streamed.stderr, version.stdout, help_output.stdout,
        ),
        trusted_executable=trusted,
        trusted_context=trusted_context,
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        executable_id=executable_id,
        version_id=version_id,
        help_id=help_id,
        argv=final_argv,
        reported_version=reported_version,
        native_format=registration.native_format,
        supported_build_id=supported_build_id,
        launch_identity=MappingProxyType(dict(launch_identity)),
        launch_sha256=launch_sha256,
        seal_identity=MappingProxyType(dict(seal_identity)),
        seal_sha256=seal_sha256,
    )


class RunnerHostRecorder:
    """7b recorder implementation backed by the runner's shared trace clock."""

    def __init__(
        self,
        config: Any,
        *,
        writer: ControlTraceWriter,
        raw_receipt_sidecar: _PrivateReceiptLedgerSink | None = None,
        raw_write_root_fd: int | None = None,
    ) -> None:
        # Inheritance keeps 7b's command-bound source/receipt capture logic.
        from tests.evals import brain_shim

        if raw_receipt_sidecar is not None and type(raw_receipt_sidecar) is not _PrivateReceiptLedgerSink:
            raise RunnerError("runner raw receipt sidecar is invalid")
        if raw_receipt_sidecar is None:
            if raw_write_root_fd is not None:
                raise RunnerError("runner raw write root is invalid")
        elif type(raw_write_root_fd) is not int or raw_write_root_fd < 0:
            raise RunnerError("runner raw write root is invalid")
        self._raw_receipt_sidecar = raw_receipt_sidecar
        self._base = brain_shim.Recorder(
            config,
            raw_write_receipt_sink=(
                None if raw_receipt_sidecar is None else self._record_raw_write_receipt
            ),
            raw_append_preflight=(
                None if raw_receipt_sidecar is None else raw_receipt_sidecar.prepare_raw_append
            ),
            raw_write_root_fd=raw_write_root_fd,
        )
        self.config = config
        self.writer = writer
        self.command_id: str | None = None
        self.start_sequence: int | None = None
        self._preapply_manifest_argv: tuple[str, ...] | None = None

    def _record_raw_write_receipt(self, receipt: object) -> None:
        """Forward a shim FD-time receipt while its producer fd is still open."""

        sidecar = self._raw_receipt_sidecar
        if sidecar is None or self.command_id is None:
            raise RunnerError("runner raw receipt arrived outside a command")
        sidecar.append_raw(receipt, command_id=self.command_id)

    def _capture_preapply_manifest(self, command_id: str) -> None:
        """Copy a candidate wiki manifest before the product can apply it.

        Task 7b intentionally owns only its closed raw bridge.  A wiki apply
        manifest is a runner-normalizer concern because reading it after the
        command would let a client replace the bytes that controlled the
        transaction.  This private, runner-owned side capture is deliberately
        separate from the accepted 7b capture-index schema.
        """

        child_args = tuple(sys.argv[1:])
        if (len(child_args) != 5
                or child_args[:4] != ("--json", "wiki", "apply", "--manifest")):
            return
        relative = child_args[-1]
        path = PurePosixPath(relative)
        if (path.is_absolute() or path.as_posix() != relative
                or len(path.parts) != 4
                or path.parts[:2] != (".brain", "wiki-staging")
                or not path.parts[2].startswith("wstg_")
                or path.parts[-1] != "manifest.json"):
            # Let the shim produce its normal observed failure; an unsafe
            # spelling can never become semantic manifest evidence.
            return
        workspace = Path(self.config.workspace).resolve()
        pin = PinnedDirectory.pin(workspace, private=False)
        try:
            raw = pin.read_relative(relative)
        finally:
            pin.close()
        capture = (
            Path(self.config.root) / "runner-preapply-manifests" / command_id / "manifest.bin"
        )
        if self._raw_receipt_sidecar is None:
            _write_private(capture, raw)
        else:
            # The armed helper emits its metadata-only receipt after fsync and
            # fd/path equality while the manifest producer descriptor remains
            # open.  Keep the historical path untouched when unarmed.
            self._base._write_bytes(capture, raw, exclusive=True, mode=0o600)
        row = {
            "command_id": command_id,
            "argv": ["./brain", *child_args],
            "argv_sha256": _sha256(_canonical_json(["./brain", *child_args])),
            "path": relative,
            "capture_path": capture.relative_to(self.config.root).as_posix(),
            "sha256": _sha256(raw),
            "bytes": len(raw),
        }
        # Use the shim's already-locked append primitive only for this
        # runner-owned raw handoff record; its public 7b schemas remain
        # unchanged.  Conversion later treats it as immutable capture input.
        self._base._append("runner-preapply-manifests.jsonl", row)
        self._preapply_manifest_argv = ("./brain", *child_args)

    def __getattr__(self, name: str) -> Any:
        return getattr(self._base, name)

    def start(self) -> str:
        # A random lower-case ID never relies on how native output happened to
        # interleave with shim calls, while the sequence remains the ordering
        # authority in the shared trace.
        command_id = "shim-command-" + uuid.uuid4().hex
        sequence = self.writer.append("command_start", command_id=command_id)
        self.command_id = command_id
        self.start_sequence = sequence
        self._base.command_id = command_id
        self._base.start_sequence = sequence
        self._capture_preapply_manifest(command_id)
        return command_id

    def finish(
        self,
        *,
        argv: list[str],
        code: int,
        raw_result: bytes,
        result: dict[str, object],
        command: tuple[str, ...],
    ) -> None:
        if self.command_id is None or self.start_sequence is None:
            raise RuntimeError("recorder start was not called")
        if self._preapply_manifest_argv is not None and tuple(argv) != self._preapply_manifest_argv:
            raise RuntimeError("preapply manifest argv changed before dispatch")
        result_sha = _sha256(raw_result)
        state_path = self._base._capture_state(result, command)
        receipt_path = self._base._capture_receipt_artifacts(result, command)
        if state_path is not None:
            self.writer.append("source_state", command_id=self.command_id, capture_path=state_path)
        end_sequence = self.writer.append("command_end", command_id=self.command_id)
        result_directory = self.config.root / "brain-shim-captures" / self.command_id
        if self._raw_receipt_sidecar is None:
            result_directory.mkdir(mode=0o700, parents=True, exist_ok=True)
        result_path = result_directory / "result.json"
        if self._raw_receipt_sidecar is None:
            result_path.write_bytes(raw_result)
        else:
            self._base._write_bytes(result_path, raw_result, mode=0o600)
        timestamp = self._base._timestamp()
        self._base._append(
            "brain-shim-capture-index.jsonl",
            {
                "command_id": self.command_id,
                "argv": argv,
                "argv_sha256": _sha256(_canonical_json(argv)),
                "exit_code": code,
                "result_path": result_path.relative_to(self.config.root).as_posix(),
                "result_sha256": result_sha,
                "source_state_path": state_path,
                "receipt_artifacts_path": receipt_path,
                "start_sequence": self.start_sequence,
                "end_sequence": end_sequence,
                "phase": self.config.phase,
                "timestamp": timestamp,
            },
        )
        self._base._append(
            "brain-shim-command-log.jsonl",
            {"argv": argv, "exit_code": code, "result_sha256": result_sha, "timestamp": timestamp},
        )


def _runner_state(control: Path) -> dict[str, Any]:
    path = control / "runner-state.json"
    value = _strict_json(_safe_read(path), label="runner state")
    expected = {"schema_version", "control_root", "workspace", "run_id", "execution_id", "phase"}
    if type(value) is not dict or set(value) != expected or value.get("schema_version") != 1:
        raise RunnerError("invalid runner state")
    if Path(value["control_root"]).resolve() != control.resolve():
        raise RunnerError("runner state control mismatch")
    return value


def shim_entrypoint() -> int:
    """Entry point installed in a copied fixture's root ``./brain`` wrapper."""

    from tests.evals import brain_shim

    child_control_pin: PinnedDirectory | None = None
    try:
        control = Path(os.environ[CONTROL_ENV]).resolve()
        state_path = Path(os.environ[RUNNER_STATE_ENV]).resolve()
        if state_path != control / "runner-state.json":
            raise RunnerError("runner state locator mismatch")
        state = _runner_state(control)
        raw_receipt_sidecar: _PrivateReceiptLedgerSink | None = None
        trace_receipt_sidecar: _PrivateReceiptLedgerSink | None = None
        if (state.get("execution_id") == "execution-2"
                and state.get("phase") == "approved_capture"):
            # The state schema deliberately stays unchanged.  Both private
            # headers must be present together to arm this child; two absent
            # files retain the historical direct-shim behavior, while a
            # partial/private collision is fail closed.
            child_control_pin = PinnedDirectory.pin(control, private=True)
            raw_absent = _pinned_control_capture_is_absent(
                child_control_pin, _PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER,
            )
            trace_absent = _pinned_control_capture_is_absent(
                child_control_pin, _PHASE_TWO_TRACE_RECEIPT_LEDGER,
            )
            if raw_absent != trace_absent:
                raise RunnerError("private child receipt ledgers are incomplete")
            if not raw_absent:
                raw_receipt_sidecar, trace_receipt_sidecar = (
                    _load_registered_actual_phase_two_child_receipt_ledgers(
                        child_control_pin,
                        run_id=state["run_id"],
                        execution_id=state["execution_id"],
                    )
                )
            else:
                # Do not even retain a new control descriptor in the
                # unarmed branch: its trace writer follows the exact legacy
                # constructor and I/O path.
                child_control_pin.close()
                child_control_pin = None

        def factory(config: Any) -> RunnerHostRecorder:
            if (config.root.resolve() != control or config.workspace.resolve() != Path(state["workspace"]).resolve()
                    or config.phase != state["phase"]):
                raise RunnerError("shim control state mismatch")
            return RunnerHostRecorder(
                config,
                writer=ControlTraceWriter(
                    control,
                    state["execution_id"],
                    control_pin=child_control_pin,
                    trace_receipt_sink=(
                        None if trace_receipt_sidecar is None else trace_receipt_sidecar.append_trace
                    ),
                ),
                raw_receipt_sidecar=raw_receipt_sidecar,
                raw_write_root_fd=(
                    None if raw_receipt_sidecar is None else child_control_pin.root_fd
                ),
            )

        return brain_shim.main(recorder_factory=factory)
    except (KeyError, RunnerError) as error:
        sys.stderr.write(f"cross-client runner shim denied: {error}\n")
        return 2
    finally:
        if child_control_pin is not None:
            child_control_pin.close()


@dataclass
class EvidenceWriter:
    control_root: Path
    run_id: str
    run_root: Path = field(init=False)
    entries: list[dict[str, Any]] = field(default_factory=list)
    # Every normal evidence write retains the exact descriptor identity seen
    # while its exclusive producer fd was still open.  Most routes only need
    # the entry/hash fields, but the disconnected phase-two diagnostic uses
    # these receipts to reject a same-byte replacement before its first
    # post-write checkpoint can adopt it as a baseline.
    write_identities: dict[str, tuple[int, int, int, int, int, int, int, int]] = field(
        default_factory=dict,
    )

    def __post_init__(self) -> None:
        self.run_root = self.control_root / "runs" / self.run_id
        self.run_root.mkdir(mode=0o700, parents=True, exist_ok=False)

    def add_bytes(
        self,
        artifact_id: str,
        artifact_type: str,
        raw: bytes,
        *,
        suffix: str = ".bin",
        fixed_name: str | None = None,
    ) -> str:
        if not artifact_id or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789._-" for c in artifact_id):
            raise RunnerError("invalid artifact identity")
        if any(entry["id"] == artifact_id for entry in self.entries):
            raise RunnerError("duplicate artifact identity")
        if fixed_name is None:
            relative = PurePosixPath("artifacts", artifact_id + suffix).as_posix()
        else:
            if type(fixed_name) is not str:
                raise RunnerError("invalid fixed artifact path")
            fixed = PurePosixPath(fixed_name)
            if (fixed.is_absolute()
                    or len(fixed.parts) != 1 or fixed.as_posix() != fixed_name):
                raise RunnerError("invalid fixed artifact path")
            relative = fixed_name
        identity = _write_private(self.run_root / relative, raw)
        if relative in self.write_identities:
            raise RunnerError("duplicate evidence artifact path")
        self.write_identities[relative] = identity
        self.entries.append({
            "id": artifact_id, "type": artifact_type, "relative_path": relative,
            "sha256": _sha256(raw), "bytes": len(raw),
        })
        return artifact_id

    def add_json(self, artifact_id: str, artifact_type: str, value: Any) -> str:
        return self.add_bytes(artifact_id, artifact_type, _canonical_json(value), suffix=".json")

    def add_fixed_json(
        self, artifact_id: str, artifact_type: str, fixed_name: str, value: Any,
    ) -> str:
        """Index a contract-fixed root file without duplicating its bytes."""

        return self.add_bytes(
            artifact_id, artifact_type, _canonical_json(value), suffix=".json",
            fixed_name=fixed_name,
        )

    def seal(self) -> str:
        index = {
            "schema_version": 1,
            "run_id": self.run_id,
            "entries": sorted(self.entries, key=lambda item: item["id"]),
        }
        raw = _canonical_json(index)
        _write_private(self.run_root / "evidence-index.json", raw)
        return _sha256(raw)


@dataclass(frozen=True)
class _RegisteredActualPreparedRun:
    """The bridge's empty, isolated evidence allocation.

    This token intentionally stops before phase-control construction.  It
    retains only a closed actual authority, its freshly copied/pinned
    workspace, and an empty private evidence writer.  The closed bridge may
    consume it for the one approval-phase diagnostic path, but it grants no
    phase-two or pass authority by itself.
    """

    authority: _RegisteredActualAuthority
    prepared: PreparedWorkspace
    writer: EvidenceWriter
    run_id: str
    metadata: _RegisteredActualScenarioFixtureMetadata

    def __post_init__(self) -> None:
        if (type(self.authority) is not _RegisteredActualAuthority
                or type(self.prepared) is not PreparedWorkspace
                or type(self.writer) is not EvidenceWriter
                or type(self.metadata) is not _RegisteredActualScenarioFixtureMetadata
                or type(self.run_id) is not str
                or len(self.run_id) != 64
                or any(character not in _SHA for character in self.run_id)
                or not isinstance(self.prepared.run_root, Path)
                or not isinstance(self.prepared.workspace, Path)
                or not isinstance(self.prepared.control_root, Path)
                or type(self.prepared.scenario) is not dict
                or not isinstance(self.prepared.control_pin, PinnedDirectory)
                or not isinstance(self.prepared.workspace_pin, PinnedDirectory)
                or not isinstance(self.writer.control_root, Path)
                or not isinstance(self.writer.run_root, Path)):
            raise RunnerError("registered actual prepared run is invalid")
        plan = self.authority.plan
        self.metadata.__post_init__()
        if (type(plan) is not RegisteredActualScenarioPlan
                or self.metadata.scenario_id != plan.scenario_id
                or self.metadata.fixture_id != _FIXTURE_IDS.get(plan.scenario_id)
                or self.prepared.control_root == self.prepared.workspace
                or self.prepared.control_root.is_relative_to(self.prepared.workspace)
                or self.prepared.workspace.is_relative_to(self.prepared.control_root)
                or self.prepared.control_root.parent != self.prepared.run_root
                or self.prepared.workspace.parent != self.prepared.run_root
                or self.prepared.control_pin.path != self.prepared.control_root
                or self.prepared.workspace_pin.path != self.prepared.workspace
                or not self.prepared.control_pin.private
                or self.prepared.workspace_pin.private
                or self.writer.control_root != self.prepared.control_root
                or self.writer.run_id != self.run_id
                or self.writer.run_root != self.prepared.control_root / "runs" / self.run_id
                or self.writer.entries):
            raise RunnerError("registered actual prepared run binding is invalid")


def _registered_actual_scenario_fixture_metadata(
    prepared_run: _RegisteredActualPreparedRun,
    plan: RegisteredActualScenarioPlan,
) -> _RegisteredActualScenarioFixtureMetadata:
    """Return the one retained scenario/fixture identity for an actual plan.

    Later registered-actual phases deliberately cannot revalidate against a
    mutable ``PreparedWorkspace`` dictionary or the source scenario tree.
    They must bind their plan to this pre-side-effect facade instead.
    """

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(plan) is not RegisteredActualScenarioPlan
            or type(prepared_run.metadata) is not _RegisteredActualScenarioFixtureMetadata):
        raise RunnerError("registered actual scenario/fixture metadata is invalid")
    metadata = prepared_run.metadata
    metadata.__post_init__()
    if (metadata.scenario_id != plan.scenario_id
            or metadata.fixture_id != _FIXTURE_IDS.get(plan.scenario_id)):
        raise RunnerError("registered actual scenario/fixture metadata is invalid")
    return metadata


def _prepare_registered_actual_run(
    authority: _RegisteredActualAuthority,
) -> _RegisteredActualPreparedRun:
    """Allocate only isolated roots and an empty writer for a closed authority.

    The closed bridge calls this first for its exact Claude/web plan.  This
    narrow construction seam validates the runner-owned plan again, repeats
    the test-adapter rejection before workspace creation, and makes no phase,
    probe, process, semantic, phase-two, log, or pass-publication artifact.
    """

    if type(authority) is not _RegisteredActualAuthority:
        raise RunnerError("registered actual authority is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual execution")
    plan = authority.plan
    if (type(plan) is not RegisteredActualScenarioPlan
            or type(plan.client) is not str
            or type(plan.scenario_id) is not str
            or plan.scratch_root is not None and not isinstance(plan.scratch_root, Path)):
        raise RunnerError("registered actual authority is invalid")
    # Re-establish the complete closure at the moment side effects become
    # possible.  The registry object itself must still be the exact object
    # captured by planning; an equal caller-constructed replacement is not an
    # authority source.
    _scenario(plan.scenario_id)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    registration = _runner_owned_registration(plan.client)
    if (plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or plan.registration is not registration):
        raise RunnerError("registered actual plan is no longer runner-owned")
    # This repeat is deliberately immediately before the first mutable setup
    # operation.  A test-only seam installed after planning cannot leave a
    # partial private workspace behind.
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual execution")
    prepared = prepare_isolated_workspace(
        plan.scenario_id, scratch_root=plan.scratch_root,
    )
    metadata = _freeze_registered_actual_scenario_fixture_metadata(prepared, plan)
    run_id = _sha256((str(prepared.run_root) + "\0actual-prepared-run\0" + uuid.uuid4().hex).encode())
    writer = EvidenceWriter(prepared.control_root, run_id)
    prepared_run = _RegisteredActualPreparedRun(authority, prepared, writer, run_id, metadata)
    # Recheck the descriptor-backed roots after the writer directory exists;
    # the writer must not turn an initial pin into permission for a later
    # phase to proceed after root replacement.
    PinnedDirectory.verify(prepared.control_pin)
    PinnedDirectory.verify(prepared.workspace_pin)
    return prepared_run


def _canonical_phase_prompt(
    scenario: Mapping[str, Any],
    phase: str,
) -> bytes:
    """Load only the generated, phase-owned prompt bytes for one launch."""

    try:
        raw = canonical_phase_prompt_bytes(scenario, phase)
        raw.decode("utf-8", "strict")
    except (TypeError, UnicodeDecodeError, ValueError) as error:
        raise RunnerError("canonical phase prompt unavailable") from error
    if type(raw) is not bytes:
        raise RunnerError("canonical phase prompt is not bytes")
    return raw


def _phase_prompt_transport(client: str) -> str:
    if client == "codex":
        return "stdin_utf8"
    if client == "claude":
        return "argv_final_utf8"
    raise RunnerError("unsupported phase prompt client")


def _index_phase_prompt(
    writer: EvidenceWriter,
    *,
    scenario: Mapping[str, Any],
    phase: str,
    phase_index: int,
    client: str,
    raw: bytes | None = None,
) -> PhasePromptEvidence:
    """Persist, seal, and bind raw launch bytes before process creation."""

    if type(phase_index) is not int or phase_index < 1:
        raise RunnerError("phase prompt index invalid")
    expected = _canonical_phase_prompt(scenario, phase)
    if raw is not None and raw != expected:
        raise RunnerError("phase prompt bytes do not match canonical contract")
    artifact_id = f"phase-prompt-{phase_index}"
    writer.add_bytes(artifact_id, "phase_prompt", expected, suffix=".txt")
    entry = _writer_entry_map(writer).get(artifact_id)
    if entry is None or entry.get("type") != "phase_prompt":
        raise RunnerError("indexed phase prompt unavailable")
    path = (writer.run_root / str(entry["relative_path"])).resolve()
    if not path.is_relative_to(writer.run_root.resolve()):
        raise RunnerError("indexed phase prompt escaped run root")
    seal = _seal_control_file(path)
    evidence = PhasePromptEvidence(
        artifact_id=artifact_id,
        raw=expected,
        sha256=_sha256(expected),
        transport=_phase_prompt_transport(client),
        seal=seal,
    )
    _verify_phase_prompt(evidence)
    return evidence


_RegisteredActualEvidenceProvenance = tuple[
    str, str, str, int, tuple[int, ...],
]


@dataclass(frozen=True)
class _RegisteredActualPreparedPhase:
    """Sealed internal facts for the disconnected actual-only launch wrapper.

    This is deliberately not a public launch request: the plan is already
    runner-prepared, and the prompt, MCP file, runner state, roots, and trace
    are all retained host facts.  In particular, it has no process, probe,
    Popen, argv, environment, or caller prompt field.
    """

    prepared_run: _RegisteredActualPreparedRun
    authority: _RegisteredActualAuthority
    writer: EvidenceWriter
    execution_id: str
    phase: str
    phase_index: int
    workspace: Path
    control_pin: PinnedDirectory
    workspace_pin: PinnedDirectory
    phase_control: PhaseControlSeals
    phase_prompt: PhasePromptEvidence
    mcp_config: ControlFileSeal | None
    runner_state: ControlFileSeal
    trace: ControlTraceWriter
    transcript_id: str
    initial_workspace_snapshot: WorkspaceSnapshot
    marker_workspace_snapshots: list[WorkspaceSnapshot]
    on_native_record: Callable[[bytes, int, int, int], str]
    trusted_context: Any | None = None
    sealed_evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance] | None = None
    phase_one_raw_predecessor_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot | None = None
    sealed_initial_workspace_inventory: _RegisteredActualPhaseTwoWorkspaceInventory | None = None

    def __post_init__(self) -> None:
        if (type(self.prepared_run) is not _RegisteredActualPreparedRun
                or type(self.authority) is not _RegisteredActualAuthority
                or type(self.writer) is not EvidenceWriter
                or type(self.execution_id) is not str or not self.execution_id
                or type(self.phase) is not str or not self.phase
                or type(self.phase_index) is not int or self.phase_index < 1
                or not isinstance(self.workspace, Path)
                or not isinstance(self.control_pin, PinnedDirectory)
                or not isinstance(self.workspace_pin, PinnedDirectory)
                or not isinstance(self.phase_control, PhaseControlSeals)
                or not isinstance(self.phase_prompt, PhasePromptEvidence)
                or self.mcp_config is not None and not isinstance(self.mcp_config, ControlFileSeal)
                or not isinstance(self.runner_state, ControlFileSeal)
                or not isinstance(self.trace, ControlTraceWriter)
                or type(self.transcript_id) is not str or not self.transcript_id
                or not isinstance(self.initial_workspace_snapshot, WorkspaceSnapshot)
                or type(self.marker_workspace_snapshots) is not list
                or any(not isinstance(snapshot, WorkspaceSnapshot)
                       for snapshot in self.marker_workspace_snapshots)
                or not callable(self.on_native_record)):
            raise RunnerError("registered actual prepared phase is invalid")
        raw_predecessors = self.phase_one_raw_predecessor_snapshot
        if self.execution_id == "execution-2":
            if not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(raw_predecessors):
                raise RunnerError("registered actual phase-two raw predecessor snapshot is invalid")
            if not _registered_actual_phase_two_workspace_inventory_is_valid(
                    self.sealed_initial_workspace_inventory,
            ):
                raise RunnerError("registered actual phase-two workspace baseline is invalid")
        elif raw_predecessors is not None:
            raise RunnerError("registered actual phase-one raw predecessor snapshot is invalid")
        elif self.sealed_initial_workspace_inventory is not None:
            raise RunnerError("registered actual phase-two workspace baseline is invalid")
        provenance = self.sealed_evidence_provenance
        if provenance is not None:
            if not isinstance(provenance, Mapping):
                raise RunnerError("registered actual evidence provenance is invalid")
            frozen: dict[str, _RegisteredActualEvidenceProvenance] = {}
            for artifact_id, record in provenance.items():
                if (type(artifact_id) is not str or not artifact_id
                        or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                               for character in artifact_id)
                        or type(record) is not tuple or len(record) != 5):
                    raise RunnerError("registered actual evidence provenance is invalid")
                artifact_type, relative, digest, byte_count, identity = record
                path = PurePosixPath(relative) if type(relative) is str else None
                if (type(artifact_type) is not str or not artifact_type
                        or type(relative) is not str or path is None
                        or path.is_absolute() or path.as_posix() != relative or not path.parts
                        or any(part in {"", ".", ".."} for part in path.parts)
                        or not _is_hex64(digest)
                        or type(byte_count) is not int or byte_count < 0
                        or type(identity) is not tuple or len(identity) != 8
                        or any(type(item) is not int for item in identity)):
                    raise RunnerError("registered actual evidence provenance is invalid")
                frozen[artifact_id] = (
                    artifact_type, relative, digest, byte_count, tuple(identity),
                )
            object.__setattr__(
                self, "sealed_evidence_provenance", MappingProxyType(frozen),
            )


_RegisteredActualPhaseTwoControlTree = Mapping[
    str, tuple[int, int, int, int, int, int, int, int],
]
_RegisteredActualPhaseTwoSealRecord = tuple[
    str, tuple[int, int, int, int, int, int, int, int], str,
]
_REGISTERED_ACTUAL_PHASE_TWO_BINDING_UNSET = object()


def _registered_actual_phase_two_static_control_tree(
    snapshot: _RegisteredActualPhaseTwoControlTree,
) -> Mapping[str, tuple[int, int, int, int, int, int, int, int]]:
    """Detach the root controls that may not change before phase-two Popen.

    The evidence run directory deliberately grows as the fixed version/help
    probes execute.  Everything outside it remains a phase-two launch input,
    including the shim, fixture controls, runner state, root journals, and
    trace namespace.  This helper consumes an already-captured tree: it must
    never turn a fresh descriptor walk into the returned token's baseline.
    """

    if not isinstance(snapshot, Mapping) or "runs/" not in snapshot:
        raise RunnerError("registered actual phase-two static control tree is invalid")
    static_tree: dict[str, tuple[int, int, int, int, int, int, int, int]] = {}
    for relative, identity in snapshot.items():
        if (type(relative) is not str or not relative
                or type(identity) is not tuple or len(identity) != 8
                or any(type(value) is not int for value in identity)):
            raise RunnerError("registered actual phase-two static control tree is invalid")
        path_text = relative[:-1] if relative.endswith("/") else relative
        path = PurePosixPath(path_text)
        if (path.is_absolute() or path.as_posix() != path_text or not path.parts
                or any(part in {"", ".", ".."} for part in path.parts)):
            raise RunnerError("registered actual phase-two static control tree is invalid")
        if relative == "runs":
            raise RunnerError("registered actual phase-two static control tree is invalid")
        if relative == "runs/" or relative.startswith("runs/"):
            continue
        static_tree[relative] = tuple(identity)
    return MappingProxyType(static_tree)


def _registered_actual_phase_two_seal_record(
    seal: ControlFileSeal,
) -> _RegisteredActualPhaseTwoSealRecord:
    """Copy a mutable legacy seal into a primitive retained comparison form."""

    labels = (
        "device", "inode", "mode", "uid", "nlink", "bytes", "mtime_ns", "ctime_ns",
    )
    if (type(seal) is not ControlFileSeal or not isinstance(seal.path, Path)
            or not seal.path.is_absolute() or type(seal.identity) is not dict
            or set(seal.identity) != set(labels) or not _is_hex64(seal.sha256)
            or any(type(seal.identity.get(label)) is not int for label in labels)):
        raise RunnerError("registered actual phase-two control seal is invalid")
    identity = tuple(seal.identity[label] for label in labels)
    if not _valid_regular_identity(identity):
        raise RunnerError("registered actual phase-two control seal is invalid")
    return str(seal.path), identity, seal.sha256


def _registered_actual_phase_two_binding_relative(
    control_pin: PinnedDirectory,
    seal: ControlFileSeal,
) -> str:
    """Return one frozen control-relative locator without resolving a path."""

    if (not isinstance(control_pin, PinnedDirectory)
            or type(seal) is not ControlFileSeal or not isinstance(seal.path, Path)):
        raise RunnerError("registered actual phase-two control seal is invalid")
    try:
        relative = seal.path.relative_to(control_pin.path).as_posix()
    except ValueError as error:
        raise RunnerError("registered actual phase-two control seal escaped root") from error
    PinnedDirectory._relative_parts(relative)
    return relative


@dataclass(frozen=True)
class _RegisteredActualPhaseOnePrivateLaunchBridge:
    """Detached phase-one facts retained for the phase-two private boundary.

    The original phase-one diagnostic remains an intentionally public-shaped
    host facade.  Once phase two has been prepared, it must not be consulted
    for descriptor authority: the returned phase-two token aliases its pins.
    This bridge owns copied phase-one host facts whose readers instead use the
    binding's duplicate descriptor pair.
    """

    run_id: str
    live_phase: RegisteredLivePhase
    conversion: "ShimCaptureConversion"
    raw_predecessors: _RegisteredActualPhaseOneRawPredecessors
    receipt_artifacts: "_FrozenActualPhaseOneReceiptArtifacts"
    policy_id: str
    process_id: str
    transcript_id: str
    stderr_id: str
    trace_id: str
    trace_sha256: str

    def __post_init__(self) -> None:
        live_phase = self.live_phase
        capture = live_phase.capture if type(live_phase) is RegisteredLivePhase else None
        try:
            launch_identity = dict(live_phase.launch_identity)
            seal_identity = dict(live_phase.seal_identity)
        except (AttributeError, TypeError, ValueError) as error:
            raise RunnerError("registered actual private phase-one bridge is invalid") from error
        expected_ids = {
            "policy_id": "policy-1",
            "process_id": "process-1",
            "transcript_id": "transcript-1",
            "stderr_id": "stderr-1",
            "trace_id": "trace-execution-1",
        }
        actual_ids = {
            "policy_id": self.policy_id,
            "process_id": self.process_id,
            "transcript_id": self.transcript_id,
            "stderr_id": self.stderr_id,
            "trace_id": self.trace_id,
        }
        if (not _is_hex64(self.run_id)
                or capture is None
                or type(capture.exit_code) is not int
                or any(type(raw) is not bytes for raw in (
                    capture.stdout, capture.stderr, capture.version, capture.help,
                ))
                or capture.stdout_chunks is not None
                or not isinstance(live_phase.control_pin, PinnedDirectory)
                or not isinstance(live_phase.workspace_pin, PinnedDirectory)
                or live_phase.executable_id != "client-executable-1"
                or live_phase.version_id != "version-1"
                or live_phase.help_id != "help-1"
                or type(live_phase.argv) is not tuple
                or not live_phase.argv
                or any(type(value) is not str for value in live_phase.argv)
                or type(live_phase.reported_version) is not str
                or type(live_phase.native_format) is not str
                or type(live_phase.supported_build_id) is not str
                or not _is_hex64(live_phase.launch_sha256)
                or not _is_hex64(live_phase.seal_sha256)
                or not launch_identity
                or launch_identity != seal_identity
                or any(type(key) is not str or type(value) is not int
                       for identity in (launch_identity, seal_identity)
                       for key, value in identity.items())
                or type(self.conversion) is not ShimCaptureConversion
                or type(self.raw_predecessors) is not _RegisteredActualPhaseOneRawPredecessors
                or type(self.receipt_artifacts) is not _FrozenActualPhaseOneReceiptArtifacts
                or self.receipt_artifacts.run_id != self.run_id
                or actual_ids != expected_ids
                or type(self.trace_sha256) is not str
                or not _is_hex64(self.trace_sha256)
                or self.trace_id != self.conversion.trace_id
                or self.trace_sha256 != self.conversion.trace_sha256
                or any(type(raw) is not bytes for raw in (
                    self.conversion.raw_index,
                    self.conversion.raw_command_log,
                    self.conversion.raw_preapply_manifests,
                ))):
            raise RunnerError("registered actual private phase-one bridge is invalid")
        self.conversion.__post_init__()
        self.raw_predecessors.__post_init__()
        self.receipt_artifacts.__post_init__()

    def assert_current(
        self,
        *,
        control_pin: PinnedDirectory,
        workspace_pin: PinnedDirectory,
        trusted_context: Any,
    ) -> None:
        """Recheck private phase-one readers without touching token pins."""

        self.__post_init__()
        if (type(control_pin) is not PinnedDirectory
                or type(workspace_pin) is not PinnedDirectory
                or not isinstance(control_pin.path, Path)
                or not isinstance(workspace_pin.path, Path)):
            raise RunnerError("registered actual private phase-one bridge changed")
        live_phase = self.live_phase
        if (live_phase.control_pin is not control_pin
                or live_phase.workspace_pin is not workspace_pin
                or self.receipt_artifacts.control_pin is not control_pin
                or control_pin.path == workspace_pin.path
                or control_pin.path in workspace_pin.path.parents
                or workspace_pin.path in control_pin.path.parents
                or not control_pin.private
                or workspace_pin.private):
            raise RunnerError("registered actual private phase-one bridge changed")
        try:
            PinnedDirectory.verify(control_pin)
            PinnedDirectory.verify(workspace_pin)
        except RunnerError:
            raise
        except OSError as error:
            raise RunnerError("registered actual private phase-one bridge changed") from error
        registration, trusted = _registered_live_context_phase(
            client="claude",
            execution_id="execution-1",
            control_pin=control_pin,
            workspace_pin=workspace_pin,
            trusted_context=trusted_context,
            expected_execution_ids=frozenset({"execution-1", "execution-2"}),
        )
        observed_identity, observed_sha256 = _registered_executable_observation(trusted)
        if (registration is not _runner_owned_registration("claude")
                or live_phase.trusted_context is not trusted_context
                or live_phase.trusted_executable is not trusted
                or live_phase.reported_version != registration.expected_version
                or live_phase.native_format != registration.native_format
                or live_phase.supported_build_id != trusted.supported_build_id
                or dict(live_phase.launch_identity) != observed_identity
                or dict(live_phase.seal_identity) != observed_identity
                or live_phase.launch_sha256 != observed_sha256
                or live_phase.seal_sha256 != observed_sha256):
            raise RunnerError("registered actual private phase-one bridge changed")
        # These journals are immutable only through the pre-Popen boundary.
        # Phase two legitimately appends receipt-bound rows afterwards, so
        # every generic bridge revalidation cannot require their phase-one
        # byte prefix to still be the complete file.  The pre-launch gate
        # checks that invariant explicitly; after allocation the retained
        # receipt-ledger/raw-handoff closure owns append-only verification.
        self.receipt_artifacts.verify()


def _freeze_registered_actual_phase_one_private_launch_bridge(
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    *,
    control_pin: PinnedDirectory,
    workspace_pin: PinnedDirectory,
    trusted_context: Any,
) -> _RegisteredActualPhaseOnePrivateLaunchBridge:
    """Copy phase-one launch facts onto the binding-owned descriptor pair.

    This performs only structural copying.  The caller has already captured
    the final phase-two setup tree; later ``assert_current`` calls reverify
    these copied snapshots through the duplicate descriptors rather than
    allowing this construction to establish a fresh post-return baseline.
    """

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(control_pin) is not PinnedDirectory
            or type(workspace_pin) is not PinnedDirectory
            or not control_pin.private
            or workspace_pin.private):
        raise RunnerError("registered actual private phase-one bridge is invalid")
    source_phase = phase_one_diagnostic.prepared_phase
    source_live = phase_one_diagnostic.live_phase
    source_capture = source_live.capture if type(source_live) is RegisteredLivePhase else None
    source_artifacts = phase_one_diagnostic.receipt_artifacts
    source_conversion = phase_one_diagnostic.conversion
    source_predecessors = phase_one_diagnostic.raw_predecessors
    if (type(source_phase) is not _RegisteredActualPreparedPhase
            or source_phase.execution_id != "execution-1"
            or source_phase.phase != "approval"
            or source_phase.phase_index != 1
            or source_live.control_pin is not source_phase.control_pin
            or source_live.workspace_pin is not source_phase.workspace_pin
            or source_artifacts.control_pin is not source_phase.control_pin
            or source_capture is None
            or type(source_capture.exit_code) is not int
            or any(type(raw) is not bytes for raw in (
                source_capture.stdout,
                source_capture.stderr,
                source_capture.version,
                source_capture.help,
            ))
            or source_capture.stdout_chunks is not None
            or type(source_conversion) is not ShimCaptureConversion
            or type(source_predecessors) is not _RegisteredActualPhaseOneRawPredecessors
            or type(source_artifacts) is not _FrozenActualPhaseOneReceiptArtifacts):
        raise RunnerError("registered actual private phase-one bridge is invalid")
    try:
        launch_identity = dict(source_live.launch_identity)
        seal_identity = dict(source_live.seal_identity)
        conversion_manifests = dict(source_conversion.manifest_ids)
        conversion_receipts = {
            command_id: dict(artifacts)
            for command_id, artifacts in source_conversion.receipt_artifact_ids.items()
        }
        artifact_entries = {
            artifact_id: dict(entry)
            for artifact_id, entry in source_artifacts.entries.items()
        }
        artifact_snapshots = {
            artifact_id: (bytes(snapshot[0]), tuple(snapshot[1]))
            for artifact_id, snapshot in source_artifacts.snapshots.items()
        }
    except (AttributeError, TypeError, ValueError) as error:
        raise RunnerError("registered actual private phase-one bridge is invalid") from error
    if (not isinstance(source_live.argv, tuple)
            or any(type(value) is not str for value in source_live.argv)
            or type(source_live.reported_version) is not str
            or type(source_live.native_format) is not str
            or type(source_live.supported_build_id) is not str
            or type(source_live.launch_sha256) is not str
            or type(source_live.seal_sha256) is not str
            or any(type(key) is not str or type(value) is not int
                   for identity in (launch_identity, seal_identity)
                   for key, value in identity.items())
            or type(source_conversion.raw_index) is not bytes
            or type(source_conversion.raw_command_log) is not bytes
            or type(source_conversion.raw_preapply_manifests) is not bytes):
        raise RunnerError("registered actual private phase-one bridge is invalid")
    copied_predecessors: dict[str, _PrivateRawFileBaseline | None] = {}
    for relative in _PHASE_ONE_RAW_PREDECESSOR_TARGETS:
        baseline = source_predecessors.values.get(relative)
        if baseline is None:
            copied_predecessors[relative] = None
            continue
        if type(baseline) is not _PrivateRawFileBaseline:
            raise RunnerError("registered actual private phase-one bridge is invalid")
        copied_predecessors[relative] = _PrivateRawFileBaseline(
            baseline.relative_path,
            baseline.sha256,
            baseline.byte_count,
            tuple(baseline.identity),
            baseline.rows,
        )
    copied_conversion = ShimCaptureConversion(
        tuple(source_conversion.observation_ids),
        conversion_manifests,
        source_conversion.trace_id,
        source_conversion.trace_sha256,
        bytes(source_conversion.raw_index),
        bytes(source_conversion.raw_command_log),
        bytes(source_conversion.raw_preapply_manifests),
        conversion_receipts,
    )
    copied_artifacts = _FrozenActualPhaseOneReceiptArtifacts(
        source_artifacts.run_id,
        control_pin,
        artifact_entries,
        artifact_snapshots,
    )
    try:
        private_trusted = trusted_context.trusted_executables.get("execution-1")
    except (AttributeError, TypeError, ValueError) as error:
        raise RunnerError("registered actual private phase-one bridge is invalid") from error
    copied_live = RegisteredLivePhase(
        capture=ProcessCapture(
            source_capture.exit_code,
            bytes(source_capture.stdout),
            bytes(source_capture.stderr),
            bytes(source_capture.version),
            bytes(source_capture.help),
        ),
        trusted_executable=private_trusted,
        trusted_context=trusted_context,
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        executable_id=source_live.executable_id,
        version_id=source_live.version_id,
        help_id=source_live.help_id,
        argv=tuple(source_live.argv),
        reported_version=source_live.reported_version,
        native_format=source_live.native_format,
        supported_build_id=source_live.supported_build_id,
        launch_identity=MappingProxyType(launch_identity),
        launch_sha256=source_live.launch_sha256,
        seal_identity=MappingProxyType(seal_identity),
        seal_sha256=source_live.seal_sha256,
    )
    bridge = _RegisteredActualPhaseOnePrivateLaunchBridge(
        run_id=source_artifacts.run_id,
        live_phase=copied_live,
        conversion=copied_conversion,
        raw_predecessors=_RegisteredActualPhaseOneRawPredecessors(copied_predecessors),
        receipt_artifacts=copied_artifacts,
        policy_id=phase_one_diagnostic.policy_id,
        process_id=phase_one_diagnostic.process_id,
        transcript_id=phase_one_diagnostic.transcript_id,
        stderr_id=phase_one_diagnostic.stderr_id,
        trace_id=phase_one_diagnostic.trace_id,
        trace_sha256=phase_one_diagnostic.trace_sha256,
    )
    bridge.__post_init__()
    return bridge


def _registered_actual_phase_two_private_phase_one_receipt_control(
    bridge: _RegisteredActualPhaseOnePrivateLaunchBridge,
    receipt_gate: "PhaseOneReceiptGate",
) -> "_FrozenActualPhaseOneReceiptControl":
    """Build one phase-one receipt reader on the binding-owned artifact pin."""

    if (type(bridge) is not _RegisteredActualPhaseOnePrivateLaunchBridge
            or type(receipt_gate) is not PhaseOneReceiptGate
            or receipt_gate.execution_id != "execution-1"):
        raise RunnerError("registered actual private phase-one receipt control is invalid")
    bridge.__post_init__()
    receipt_gate.__post_init__()
    return _FrozenActualPhaseOneReceiptControl(
        artifacts=bridge.receipt_artifacts,
        selection=receipt_gate.selection,
        workspace_path=str(bridge.live_phase.workspace_pin.path),
        transcript_id=bridge.transcript_id,
        trace_id=bridge.trace_id,
    )


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoLaunchBinding:
    """Non-token baseline retained only by the private phase-two launcher.

    ``_RegisteredActualPreparedPhase`` is deliberately a convenient frozen
    aggregate, but Python callers can still use ``object.__setattr__`` and
    mutate its nested fixture map.  This binding is never attached to that
    aggregate.  It copies the original object identities and primitive control
    facts before the aggregate escapes, then the weak registry below recovers
    it only for the exact original token object.
    """

    prepared_run: _RegisteredActualPreparedRun
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic"
    authority: _RegisteredActualAuthority
    writer: EvidenceWriter
    control_root: Path
    client: str
    symbolic_template: tuple[str, ...]
    workspace: Path
    token_control_pin: PinnedDirectory
    token_workspace_pin: PinnedDirectory
    control_pin: PinnedDirectory
    workspace_pin: PinnedDirectory
    phase_control: PhaseControlSeals
    phase_control_config_seal: ControlFileSeal
    phase_control_config_record: _RegisteredActualPhaseTwoSealRecord
    fixture_assets: Mapping[
        str, tuple[ControlFileSeal, bytes, _RegisteredActualPhaseTwoSealRecord],
    ]
    phase_prompt: PhasePromptEvidence
    phase_prompt_seal: ControlFileSeal
    phase_prompt_record: _RegisteredActualPhaseTwoSealRecord
    mcp_config: ControlFileSeal
    mcp_path: Path
    mcp_config_record: _RegisteredActualPhaseTwoSealRecord
    runner_state: ControlFileSeal
    runner_state_path: Path
    runner_state_record: _RegisteredActualPhaseTwoSealRecord
    token_trace: ControlTraceWriter
    trace: ControlTraceWriter
    initial_workspace_snapshot: WorkspaceSnapshot
    marker_workspace_snapshots: list[WorkspaceSnapshot]
    on_native_record: Callable[[bytes, int, int, int], str]
    private_on_native_record: Callable[[bytes, int, int, int], str]
    token_trusted_context: Any
    trusted_context: Any
    phase_one_bridge: _RegisteredActualPhaseOnePrivateLaunchBridge
    execution_id: str
    phase: str
    phase_index: int
    transcript_id: str
    raw_predecessor_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot
    evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance]
    workspace_inventory: _RegisteredActualPhaseTwoWorkspaceInventory
    expected_config_raw: bytes
    expected_runner_state_raw: bytes
    expected_prompt_raw: bytes
    static_control_tree: _RegisteredActualPhaseTwoControlTree

    def _assert_token_fields(
        self,
        phase: _RegisteredActualPreparedPhase,
        *,
        trace_receipt_sink: _PrivateReceiptLedgerSink | None | object = (
            _REGISTERED_ACTUAL_PHASE_TWO_BINDING_UNSET
        ),
        allow_marker_snapshots: bool = False,
    ) -> None:
        """Reject a substituted token field without taking a new baseline."""

        if (type(phase) is not _RegisteredActualPreparedPhase
                or phase.prepared_run is not self.prepared_run
                or phase.authority is not self.authority
                or phase.writer is not self.writer
                or phase.execution_id != self.execution_id
                or phase.phase != self.phase
                or phase.phase_index != self.phase_index
                or phase.workspace is not self.workspace
                or phase.control_pin is not self.token_control_pin
                or phase.workspace_pin is not self.token_workspace_pin
                or phase.phase_control is not self.phase_control
                or phase.phase_prompt is not self.phase_prompt
                or phase.mcp_config is not self.mcp_config
                or phase.runner_state is not self.runner_state
                or phase.trace is not self.token_trace
                or phase.transcript_id != self.transcript_id
                or phase.initial_workspace_snapshot is not self.initial_workspace_snapshot
                or phase.marker_workspace_snapshots is not self.marker_workspace_snapshots
                or phase.on_native_record is not self.on_native_record
                or phase.trusted_context is not self.token_trusted_context
                or phase.phase_one_raw_predecessor_snapshot != self.raw_predecessor_snapshot
                or phase.sealed_evidence_provenance != self.evidence_provenance
                or phase.sealed_initial_workspace_inventory != self.workspace_inventory
                or self.writer.control_root != self.control_root
                or self.writer.run_id != self.prepared_run.run_id
                or self.writer.run_root != (
                    self.control_root / "runs" / self.prepared_run.run_id
                )
                or not allow_marker_snapshots and self.marker_workspace_snapshots):
            raise RunnerError("registered actual phase-two retained launch token changed")

        for token_pin, retained_pin, expected_private in (
                (self.token_control_pin, self.control_pin, True),
                (self.token_workspace_pin, self.workspace_pin, False)):
            if (type(token_pin) is not PinnedDirectory
                    or type(retained_pin) is not PinnedDirectory
                    or token_pin is retained_pin
                    or token_pin.path != retained_pin.path
                    or token_pin.edges != retained_pin.edges
                    or token_pin.private is not expected_private
                    or retained_pin.private is not expected_private):
                raise RunnerError("registered actual phase-two retained root changed")
            try:
                PinnedDirectory.verify(token_pin)
                PinnedDirectory.verify(retained_pin)
            except RunnerError:
                raise
            except OSError as error:
                raise RunnerError("registered actual phase-two retained root changed") from error

        trace = self.trace
        if (trace.control_root != self.control_pin.path
                or trace.control_pin is not self.control_pin
                or trace.execution_id != self.execution_id
                or trace.path != self.control_pin.path / "runner-trace-execution-2.jsonl"
                or trace.lock_path != self.control_pin.path / ".runner-trace.lock"):
            raise RunnerError("registered actual phase-two retained trace changed")
        for execution_id in ("execution-1", "execution-2"):
            registration, trusted = _registered_live_context_phase(
                client=self.client,
                execution_id=execution_id,
                control_pin=self.control_pin,
                workspace_pin=self.workspace_pin,
                trusted_context=self.trusted_context,
                expected_execution_ids=frozenset({"execution-1", "execution-2"}),
            )
            if (registration is not _runner_owned_registration(self.client)
                    or trusted is not self.trusted_context.trusted_executables.get(execution_id)):
                raise RunnerError("registered actual phase-two retained context changed")
            _registered_executable_observation(trusted)
        self.phase_one_bridge.assert_current(
            control_pin=self.control_pin,
            workspace_pin=self.workspace_pin,
            trusted_context=self.trusted_context,
        )
        if trace_receipt_sink is _REGISTERED_ACTUAL_PHASE_TWO_BINDING_UNSET:
            return
        if trace_receipt_sink is None:
            if (trace._trace_receipt_sink is not None
                    or trace._armed_native_trace_receipt_context is not None):
                raise RunnerError("registered actual phase-two trace was armed early")
            return
        if type(trace_receipt_sink) is not _PrivateReceiptLedgerSink:
            raise RunnerError("registered actual phase-two trace receipt sink is invalid")
        sink = trace._trace_receipt_sink
        if (getattr(sink, "__self__", None) is not trace_receipt_sink
                or getattr(sink, "__func__", None) is not _PrivateReceiptLedgerSink.append_trace):
            raise RunnerError("registered actual phase-two trace receipt sink changed")

    def _verify_phase_controls(self) -> None:
        """Recheck copied fixture/control values through the original pin."""

        phase_control = self.phase_control
        if (phase_control.config is not self.phase_control_config_seal
                or _registered_actual_phase_two_seal_record(phase_control.config)
                != self.phase_control_config_record
                or set(phase_control.fixture_assets) != set(self.fixture_assets)):
            raise RunnerError("registered actual phase-two retained controls changed")
        controls: list[tuple[ControlFileSeal, _RegisteredActualPhaseTwoSealRecord, bytes]] = [
            (
                self.phase_control_config_seal,
                self.phase_control_config_record,
                self.expected_config_raw,
            ),
            (self.runner_state, self.runner_state_record, self.expected_runner_state_raw),
            (self.mcp_config, self.mcp_config_record, EMPTY_MCP_BYTES),
            (self.phase_prompt_seal, self.phase_prompt_record, self.expected_prompt_raw),
        ]
        for name, retained in self.fixture_assets.items():
            seal, expected_raw, record = retained
            current = phase_control.fixture_assets.get(name)
            if (type(current) is not tuple or len(current) != 2
                    or current[0] is not seal or current[1] != expected_raw
                    or _registered_actual_phase_two_seal_record(seal) != record):
                raise RunnerError("registered actual phase-two retained controls changed")
            controls.append((seal, record, expected_raw))
        prompt = self.phase_prompt
        if (prompt.seal is not self.phase_prompt_seal
                or prompt.artifact_id != "phase-prompt-2"
                or prompt.raw != self.expected_prompt_raw
                or prompt.sha256 != _sha256(self.expected_prompt_raw)
                or prompt.transport != "argv_final_utf8"):
            raise RunnerError("registered actual phase-two retained prompt changed")
        for seal, record, expected_raw in controls:
            if _registered_actual_phase_two_seal_record(seal) != record:
                raise RunnerError("registered actual phase-two retained controls changed")
            relative = _registered_actual_phase_two_binding_relative(self.control_pin, seal)
            raw, identity = PinnedDirectory.snapshot_relative(self.control_pin, relative)
            if (identity != record[1] or raw != expected_raw
                    or _sha256(raw) != record[2]):
                raise RunnerError("registered actual phase-two retained controls changed")

    def assert_current(
        self,
        phase: _RegisteredActualPreparedPhase,
        *,
        receipt_ledgers: _RegisteredActualPhaseTwoReceiptLedgers | None = None,
        trace_receipt_sink: _PrivateReceiptLedgerSink | None | object = (
            _REGISTERED_ACTUAL_PHASE_TWO_BINDING_UNSET
        ),
    ) -> None:
        """Replay the original private baseline without adopting a new one."""

        self._assert_token_fields(
            phase,
            trace_receipt_sink=trace_receipt_sink,
        )
        expected_static = dict(self.static_control_tree)
        if receipt_ledgers is not None:
            if type(receipt_ledgers) is not _RegisteredActualPhaseTwoReceiptLedgers:
                raise RunnerError("registered actual phase-two receipt binding is invalid")
            for baseline in (receipt_ledgers.raw_ledger, receipt_ledgers.trace_ledger):
                if (baseline.relative_path in expected_static
                        or not _valid_regular_identity(baseline.identity)):
                    raise RunnerError("registered actual phase-two receipt binding is invalid")
                expected_static[baseline.relative_path] = baseline.identity
        observed_static = _registered_actual_phase_two_static_control_tree(
            PinnedDirectory.snapshot_tree(self.control_pin),
        )
        if observed_static != expected_static:
            raise RunnerError("registered actual phase-two static control tree changed")
        self._verify_phase_controls()
        # The individual descriptor reads above are helper boundaries.  Replay
        # the same detached static map after them so none can establish a
        # replacement as a fresh pre-Popen control state.
        if (_registered_actual_phase_two_static_control_tree(
                PinnedDirectory.snapshot_tree(self.control_pin))
                != expected_static):
            raise RunnerError("registered actual phase-two static control tree changed")


def _freeze_registered_actual_phase_two_launch_binding(
    phase_two: _RegisteredActualPreparedPhase,
    *,
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    metadata: _RegisteredActualScenarioFixtureMetadata,
    control_tree_snapshot: _RegisteredActualPhaseTwoControlTree,
    private_trace: ControlTraceWriter,
    private_on_native_record: Callable[[bytes, int, int, int], str],
    private_trusted_context: Any,
    private_control_pin: PinnedDirectory,
    private_workspace_pin: PinnedDirectory,
) -> _RegisteredActualPhaseTwoLaunchBinding:
    """Copy phase-two launch facts before the returned aggregate can escape.

    This function intentionally does no filesystem I/O.  Its tree argument
    is the exact full-tree snapshot captured immediately after construction;
    adding a fresh read here would let an in-between mutation become trusted.
    """

    if (type(phase_two) is not _RegisteredActualPreparedPhase
            or type(prepared_run) is not _RegisteredActualPreparedRun
            or type(metadata) is not _RegisteredActualScenarioFixtureMetadata
            or phase_two.prepared_run is not prepared_run
            or phase_two.authority is not prepared_run.authority
            or phase_two.writer is not prepared_run.writer
            or phase_two.execution_id != "execution-2"
            or phase_two.phase != "approved_capture"
            or phase_two.phase_index != 2
            or phase_two.mcp_config is None
            or phase_two.marker_workspace_snapshots
            or type(private_trace) is not ControlTraceWriter
            or private_trace is phase_two.trace
            or not callable(private_on_native_record)
            or private_trusted_context is phase_two.trusted_context
            or type(private_control_pin) is not PinnedDirectory
            or type(private_workspace_pin) is not PinnedDirectory
            or private_control_pin is phase_two.control_pin
            or private_workspace_pin is phase_two.workspace_pin):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    prepared = prepared_run.prepared
    if (type(prepared) is not PreparedWorkspace
            or phase_two.workspace is not prepared.workspace
            or phase_two.control_pin is not prepared.control_pin
            or phase_two.workspace_pin is not prepared.workspace_pin
            or phase_two.trusted_context is None):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    try:
        PinnedDirectory.verify(phase_two.control_pin)
        PinnedDirectory.verify(phase_two.workspace_pin)
        PinnedDirectory.verify(private_control_pin)
        PinnedDirectory.verify(private_workspace_pin)
    except RunnerError:
        raise
    except OSError as error:
        raise RunnerError("registered actual phase-two private root binding is invalid") from error
    if (private_control_pin.path != phase_two.control_pin.path
            or private_control_pin.edges != phase_two.control_pin.edges
            or private_control_pin.private is not True
            or phase_two.control_pin.private is not True
            or private_workspace_pin.path != phase_two.workspace_pin.path
            or private_workspace_pin.edges != phase_two.workspace_pin.edges
            or private_workspace_pin.private is not False
            or phase_two.workspace_pin.private is not False):
        raise RunnerError("registered actual phase-two private root binding is invalid")
    if (private_trace.control_root != prepared.control_root
            or private_trace.control_pin is not private_control_pin
            or private_trace.execution_id != "execution-2"
            or private_trace.path != prepared.control_root / "runner-trace-execution-2.jsonl"
            or private_trace.lock_path != prepared.control_root / ".runner-trace.lock"
            or private_trace._trace_receipt_sink is not None
            or private_trace._armed_native_trace_receipt_context is not None):
        raise RunnerError("registered actual phase-two private trace binding is invalid")
    try:
        private_executables = private_trusted_context.trusted_executables
        private_supported_builds = private_trusted_context.supported_builds
        private_phase_one = private_executables.get("execution-1")
        private_phase_two = private_executables.get("execution-2")
    except (AttributeError, TypeError, ValueError) as error:
        raise RunnerError("registered actual phase-two private context binding is invalid") from error
    if (private_trusted_context.control_root != prepared.control_root
            or private_trusted_context.workspace_root != prepared.workspace
            or set(private_executables) != {"execution-1", "execution-2"}
            or private_phase_one is None
            or private_phase_two is None
            or private_phase_one is private_phase_two
            or private_phase_one.execution_id != "execution-1"
            or private_phase_two.execution_id != "execution-2"
            or private_phase_one.client != "claude"
            or private_phase_two.client != "claude"
            or private_phase_one.resolved_path != _runner_owned_registration("claude").resolved_path
            or private_phase_two.resolved_path != _runner_owned_registration("claude").resolved_path
            or not isinstance(private_supported_builds, Mapping)):
        raise RunnerError("registered actual phase-two private context binding is invalid")
    metadata.__post_init__()
    if (metadata.scenario_id != "web-approval-and-capture"
            or metadata.fixture_id != "web-approval-and-capture"):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    source_assets = prepared.fixture_control_assets
    required_sources = {
        "static-shell.html", "rendered-dom.html", "unused-candidate.html",
    }
    if (not isinstance(source_assets, Mapping) or set(source_assets) != required_sources
            or any(type(raw) is not bytes for raw in source_assets.values())):
        raise RunnerError("registered actual phase-two fixture source binding is invalid")
    copied_sources = {name: bytes(source_assets[name]) for name in sorted(required_sources)}
    expected_descriptor = _canonical_json({
        "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256,
        "static_sha256": _sha256(copied_sources["static-shell.html"]),
        "rendered_sha256": _sha256(copied_sources["rendered-dom.html"]),
        "unused_sha256": _sha256(copied_sources["unused-candidate.html"]),
        "final_url": "https://example.test/standard",
        "media_type": "text/html",
        "retrieved_at": "2026-09-04T12:00:00Z",
        "redirect_urls": [],
    })
    expected_config = _canonical_json({
        "schema_version": 1,
        "workspace": str(prepared.workspace),
        "scenario_id": metadata.scenario_id,
        "phase": "approved_capture",
        "approval": _registered_actual_phase_two_approval(),
        "fixture": {
            "descriptor_path": "fixture-descriptor.json",
            "static_shell_path": "static-shell.html",
            "rendered_dom_path": "rendered-dom.html",
        },
    })
    expected_state = _canonical_json({
        "schema_version": 1,
        "control_root": str(prepared.control_root),
        "workspace": str(prepared.workspace),
        "run_id": prepared_run.run_id,
        "execution_id": "execution-2",
        "phase": "approved_capture",
    })
    expected_prompt = _canonical_phase_prompt(metadata.scenario(), "approved_capture")
    phase_control = phase_two.phase_control
    if type(phase_control) is not PhaseControlSeals:
        raise RunnerError("registered actual phase-two launch binding is invalid")
    config_seal = phase_control.config
    config_record = _registered_actual_phase_two_seal_record(config_seal)
    if (config_seal.path != prepared.control_root / "brain-shim.json"
            or config_record[2] != _sha256(expected_config)):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    expected_assets = {
        "fixture-descriptor.json": expected_descriptor,
        "static-shell.html": copied_sources["static-shell.html"],
        "rendered-dom.html": copied_sources["rendered-dom.html"],
    }
    if set(phase_control.fixture_assets) != set(expected_assets):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    frozen_assets: dict[
        str, tuple[ControlFileSeal, bytes, _RegisteredActualPhaseTwoSealRecord],
    ] = {}
    for name, expected_raw in expected_assets.items():
        item = phase_control.fixture_assets.get(name)
        if type(item) is not tuple or len(item) != 2:
            raise RunnerError("registered actual phase-two launch binding is invalid")
        seal, raw = item
        record = _registered_actual_phase_two_seal_record(seal)
        if (raw != expected_raw or seal.path != prepared.control_root / name
                or record[2] != _sha256(expected_raw)):
            raise RunnerError("registered actual phase-two launch binding is invalid")
        frozen_assets[name] = (seal, expected_raw, record)
    runner_state = phase_two.runner_state
    runner_state_record = _registered_actual_phase_two_seal_record(runner_state)
    mcp_config = phase_two.mcp_config
    if type(mcp_config) is not ControlFileSeal:
        raise RunnerError("registered actual phase-two launch binding is invalid")
    mcp_record = _registered_actual_phase_two_seal_record(mcp_config)
    prompt = phase_two.phase_prompt
    prompt_seal = prompt.seal
    prompt_record = _registered_actual_phase_two_seal_record(prompt_seal)
    if (runner_state.path != prepared.control_root / "runner-state.json"
            or runner_state_record[2] != _sha256(expected_state)
            or mcp_record[2] != _sha256(EMPTY_MCP_BYTES)
            or prompt.artifact_id != "phase-prompt-2"
            or prompt.raw != expected_prompt
            or prompt.sha256 != _sha256(expected_prompt)
            or prompt.transport != "argv_final_utf8"
            or prompt_record[2] != _sha256(expected_prompt)):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    static_tree = _registered_actual_phase_two_static_control_tree(control_tree_snapshot)
    expected_static_seals = {
        "brain-shim.json": config_record,
        "runner-state.json": runner_state_record,
        **{name: record for name, (_seal, _raw, record) in frozen_assets.items()},
    }
    if any(static_tree.get(relative) != record[1]
           for relative, record in expected_static_seals.items()):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    provenance = phase_two.sealed_evidence_provenance
    raw_predecessor = phase_two.phase_one_raw_predecessor_snapshot
    workspace_inventory = phase_two.sealed_initial_workspace_inventory
    if (not isinstance(provenance, Mapping) or not provenance
            or not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(raw_predecessor)
            or not _registered_actual_phase_two_workspace_inventory_is_valid(workspace_inventory)):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    phase_one_bridge = _freeze_registered_actual_phase_one_private_launch_bridge(
        phase_one_diagnostic,
        control_pin=private_control_pin,
        workspace_pin=private_workspace_pin,
        trusted_context=private_trusted_context,
    )
    if (phase_one_bridge.raw_predecessors.values != phase_one_diagnostic.raw_predecessors.values
            or phase_one_bridge.conversion.trace_id != phase_one_diagnostic.conversion.trace_id
            or phase_one_bridge.conversion.trace_sha256
            != phase_one_diagnostic.conversion.trace_sha256):
        raise RunnerError("registered actual phase-two private phase-one bridge is invalid")
    return _RegisteredActualPhaseTwoLaunchBinding(
        prepared_run=prepared_run,
        phase_one_diagnostic=phase_one_diagnostic,
        authority=phase_two.authority,
        writer=phase_two.writer,
        control_root=prepared.control_root,
        client="claude",
        symbolic_template=tuple(_CLAUDE_TEMPLATE),
        workspace=phase_two.workspace,
        token_control_pin=phase_two.control_pin,
        token_workspace_pin=phase_two.workspace_pin,
        control_pin=private_control_pin,
        workspace_pin=private_workspace_pin,
        phase_control=phase_control,
        phase_control_config_seal=config_seal,
        phase_control_config_record=config_record,
        fixture_assets=MappingProxyType(frozen_assets),
        phase_prompt=prompt,
        phase_prompt_seal=prompt_seal,
        phase_prompt_record=prompt_record,
        mcp_config=mcp_config,
        mcp_path=mcp_config.path,
        mcp_config_record=mcp_record,
        runner_state=runner_state,
        runner_state_path=runner_state.path,
        runner_state_record=runner_state_record,
        token_trace=phase_two.trace,
        trace=private_trace,
        initial_workspace_snapshot=phase_two.initial_workspace_snapshot,
        marker_workspace_snapshots=phase_two.marker_workspace_snapshots,
        on_native_record=phase_two.on_native_record,
        private_on_native_record=private_on_native_record,
        token_trusted_context=phase_two.trusted_context,
        trusted_context=private_trusted_context,
        phase_one_bridge=phase_one_bridge,
        execution_id=phase_two.execution_id,
        phase=phase_two.phase,
        phase_index=phase_two.phase_index,
        transcript_id=phase_two.transcript_id,
        raw_predecessor_snapshot=raw_predecessor,
        evidence_provenance=MappingProxyType(dict(provenance)),
        workspace_inventory=workspace_inventory,
        expected_config_raw=expected_config,
        expected_runner_state_raw=expected_state,
        expected_prompt_raw=expected_prompt,
        static_control_tree=static_tree,
    )


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoLaunchBindingEntry:
    reference: weakref.ReferenceType[_RegisteredActualPreparedPhase]
    binding: _RegisteredActualPhaseTwoLaunchBinding
    state: str


_REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS: dict[
    int, _RegisteredActualPhaseTwoLaunchBindingEntry,
] = {}
_REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS_LOCK = threading.RLock()


def _register_registered_actual_phase_two_launch_binding(
    phase: _RegisteredActualPreparedPhase,
    binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> None:
    """Make one successfully prepared token resolvable without retaining it."""

    if (type(phase) is not _RegisteredActualPreparedPhase
            or type(binding) is not _RegisteredActualPhaseTwoLaunchBinding):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    # This is intentionally local-only: the terminal setup closure has just
    # replayed the filesystem baseline, and registration must be its literal
    # final non-I/O operation before returning the token.
    binding._assert_token_fields(phase, trace_receipt_sink=None)
    token_id = id(phase)

    def discard(reference: weakref.ReferenceType[_RegisteredActualPreparedPhase]) -> None:
        with _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS_LOCK:
            entry = _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.get(token_id)
            if entry is not None and entry.reference is reference:
                _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.pop(token_id, None)

    reference = weakref.ref(phase, discard)
    entry = _RegisteredActualPhaseTwoLaunchBindingEntry(reference, binding, "active")
    with _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS_LOCK:
        current = _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.get(token_id)
        if current is not None and current.reference() is not None:
            raise RunnerError("registered actual phase-two launch binding already exists")
        _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS[token_id] = entry


def _registered_actual_phase_two_launch_binding_for(
    phase: _RegisteredActualPreparedPhase,
) -> _RegisteredActualPhaseTwoLaunchBinding:
    """Resolve only the live, original prepared token's private baseline."""

    if type(phase) is not _RegisteredActualPreparedPhase:
        raise RunnerError("registered actual phase-two launch binding is invalid")
    with _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS_LOCK:
        entry = _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.get(id(phase))
        if (entry is None or entry.state != "active"
                or entry.reference() is not phase):
            raise RunnerError("registered actual phase-two launch binding is unavailable")
        return entry.binding


def _begin_registered_actual_phase_two_launch_consumption(
    phase: _RegisteredActualPreparedPhase,
    binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> None:
    """Atomically reserve a token after the final no-write gate succeeds."""

    binding.assert_current(phase, trace_receipt_sink=None)
    with _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS_LOCK:
        entry = _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.get(id(phase))
        if (entry is None or entry.state != "active"
                or entry.reference() is not phase or entry.binding is not binding):
            raise RunnerError("registered actual phase-two launch binding is unavailable")
        _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS[id(phase)] = (
            _RegisteredActualPhaseTwoLaunchBindingEntry(
                entry.reference, binding, "consuming",
            )
        )


def _revoke_registered_actual_phase_two_launch_binding(
    phase: _RegisteredActualPreparedPhase,
    binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> None:
    """Retire a consumed token; a partial allocation is never retryable."""

    with _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS_LOCK:
        entry = _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.get(id(phase))
        if (entry is not None and entry.reference() is phase
                and entry.binding is binding):
            _REGISTERED_ACTUAL_PHASE_TWO_LAUNCH_BINDINGS.pop(id(phase), None)


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoRawControlHandoff:
    """One strict, non-serializable frozen input surface for phase two.

    This is intentionally narrower than a generic control pin facade.  It
    retains only the raw journals, receipt-bound capture files, completed
    phase-two trace, and sealed phase-two controls that a later reviewed
    indexer may need.  Unknown paths fail closed; this object never falls
    back to a pathname read from the mutable control tree.
    """

    raw_snapshots: Mapping[str, _ControlTraceSnapshot]
    raw_absent_paths: frozenset[str]
    raw_append_command_ids: Mapping[str, tuple[str, ...]]
    trace_snapshot: _ControlTraceSnapshot
    control_snapshots: Mapping[str, _ControlTraceSnapshot]
    phase_one_raw_index: bytes
    phase_one_raw_command_log: bytes
    phase_one_raw_preapply_manifests: bytes

    def __post_init__(self) -> None:
        if not isinstance(self.raw_snapshots, Mapping):
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        raw: dict[str, _ControlTraceSnapshot] = {}
        for relative, snapshot in self.raw_snapshots.items():
            relative = _private_receipt_relative_path(relative)
            if not _private_raw_receipt_target_is_allowed(relative):
                raise RunnerError("registered actual phase-two raw/control handoff is invalid")
            snapshot = _validated_control_trace_snapshot(snapshot)
            if (snapshot is None
                    or not _valid_regular_identity(snapshot[1])
                    or snapshot[1][5] != len(snapshot[0])
                    or relative in raw):
                raise RunnerError("registered actual phase-two raw/control handoff is invalid")
            raw[relative] = snapshot
        if type(self.raw_absent_paths) is not frozenset:
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        absent: set[str] = set()
        for relative in self.raw_absent_paths:
            relative = _private_receipt_relative_path(relative)
            if relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS:
                raise RunnerError("registered actual phase-two raw/control handoff is invalid")
            absent.add(relative)
        required_raw = {
            "brain-shim-capture-index.jsonl",
            "brain-shim-command-log.jsonl",
        }
        if (len(absent) != len(self.raw_absent_paths)
                or set(raw) & absent
                or not required_raw.issubset(raw)
                or any(
                    relative not in raw and relative not in absent
                    for relative in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                )):
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        if not isinstance(self.raw_append_command_ids, Mapping):
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        append_command_ids: dict[str, tuple[str, ...]] = {}
        for relative, command_ids in self.raw_append_command_ids.items():
            relative = _private_receipt_relative_path(relative)
            if (relative not in _PHASE_TWO_RAW_APPEND_RECEIPT_TARGETS
                    or relative not in raw
                    or type(command_ids) is not tuple):
                raise RunnerError("registered actual phase-two raw/control handoff is invalid")
            for command_id in command_ids:
                _private_receipt_command_id(command_id)
            append_command_ids[relative] = command_ids
        trace = _validated_control_trace_snapshot(self.trace_snapshot)
        if (trace is None
                or not _valid_regular_identity(trace[1])
                or trace[1][5] != len(trace[0])):
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        if not isinstance(self.control_snapshots, Mapping):
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        controls: dict[str, _ControlTraceSnapshot] = {}
        for relative, snapshot in self.control_snapshots.items():
            if type(relative) is not str:
                raise RunnerError("registered actual phase-two raw/control handoff is invalid")
            PinnedDirectory._relative_parts(relative)
            snapshot = _validated_control_trace_snapshot(snapshot)
            if (snapshot is None
                    or not _valid_regular_identity(snapshot[1])
                    or snapshot[1][5] != len(snapshot[0])
                    or relative in controls
                    or relative in raw
                    or relative == "runner-trace-execution-2.jsonl"):
                raise RunnerError("registered actual phase-two raw/control handoff is invalid")
            controls[relative] = snapshot
        if not controls or any(type(value) is not bytes for value in (
                self.phase_one_raw_index,
                self.phase_one_raw_command_log,
                self.phase_one_raw_preapply_manifests,
        )):
            raise RunnerError("registered actual phase-two raw/control handoff is invalid")
        object.__setattr__(self, "raw_snapshots", MappingProxyType(raw))
        object.__setattr__(self, "raw_absent_paths", frozenset(absent))
        object.__setattr__(self, "raw_append_command_ids", MappingProxyType(append_command_ids))
        object.__setattr__(self, "trace_snapshot", trace)
        object.__setattr__(self, "control_snapshots", MappingProxyType(controls))

    def verify(self, control_pin: PinnedDirectory) -> None:
        """Recheck every frozen path without permitting a live fallback."""

        self.__post_init__()
        if (not isinstance(control_pin, PinnedDirectory)
                or not control_pin.private):
            raise RunnerError("registered actual phase-two raw/control pin is invalid")
        PinnedDirectory.verify(control_pin)
        for relative, snapshot in self.raw_snapshots.items():
            PinnedDirectory.reverify_snapshot(control_pin, relative, snapshot)
        for relative, snapshot in self.control_snapshots.items():
            PinnedDirectory.reverify_snapshot(control_pin, relative, snapshot)
        PinnedDirectory.reverify_snapshot(
            control_pin, "runner-trace-execution-2.jsonl", self.trace_snapshot,
        )
        for relative in self.raw_absent_paths:
            if not _pinned_control_capture_is_absent(control_pin, relative):
                raise RunnerError("frozen optional raw control artifact appeared")
        PinnedDirectory.verify(control_pin)

    def read_relative(
        self,
        control_pin: PinnedDirectory,
        relative: str,
        *,
        maximum: int = _MAX_CAPTURE_BYTES,
    ) -> bytes:
        """Read only one retained snapshot after exact revalidation."""

        if type(maximum) is not int or maximum < 0:
            raise RunnerError("invalid frozen handoff read bound")
        if type(relative) is not str:
            raise RunnerError("unknown frozen handoff control path")
        PinnedDirectory._relative_parts(relative)
        if relative == "runner-trace-execution-2.jsonl":
            snapshot = self.trace_snapshot
        else:
            snapshot = self.raw_snapshots.get(relative)
            if snapshot is None:
                snapshot = self.control_snapshots.get(relative)
        if snapshot is None:
            raise RunnerError("unknown frozen handoff control path")
        PinnedDirectory.reverify_snapshot(control_pin, relative, snapshot)
        if len(snapshot[0]) > maximum:
            raise RunnerError("frozen handoff control artifact exceeds size limit")
        return snapshot[0]

    def __reduce__(self) -> object:
        raise TypeError("registered actual phase-two raw/control handoff is not serializable")


@dataclass(frozen=True)
class _PhaseTwoFrozenCaptureSource:
    """Converter-only facade over one receipt-authenticated raw handoff.

    This deliberately is not a ``PinnedDirectory`` subclass.  The generic
    phase-one diagnostic facade permits a snapshot miss to reread the mutable
    control root; that convenience is incompatible with a phase-two handoff,
    whose complete capture closure was already selected at post-launch time.
    """

    handoff: _RegisteredActualPhaseTwoRawControlHandoff
    control_pin: PinnedDirectory

    def __post_init__(self) -> None:
        if (type(self.handoff) is not _RegisteredActualPhaseTwoRawControlHandoff
                or not isinstance(self.control_pin, PinnedDirectory)
                or not self.control_pin.private):
            raise RunnerError("frozen phase-two capture source is invalid")
        self.handoff.verify(self.control_pin)

    @property
    def path(self) -> Path:
        return self.control_pin.path

    def verify(self) -> None:
        self.__post_init__()

    def read_relative(self, relative: str, *, maximum: int = _MAX_CAPTURE_BYTES) -> bytes:
        if type(relative) is not str:
            raise RunnerError("frozen phase-two capture path is invalid")
        return self.handoff.read_relative(self.control_pin, relative, maximum=maximum)

    def optional_relative(self, relative: str) -> bytes | None:
        """Read the one optional conversion journal without a live stat."""

        if relative != "runner-preapply-manifests.jsonl":
            raise RunnerError("frozen phase-two optional capture path is invalid")
        self.verify()
        if relative in self.handoff.raw_absent_paths:
            return None
        return self.read_relative(relative)


@dataclass(frozen=True)
class _PhaseTwoFrozenHandoffTrace:
    """Return defensive trace rows from the retained handoff, never a path."""

    source: _PhaseTwoFrozenCaptureSource
    rows: tuple[Mapping[str, Any], ...] = field(init=False)

    def __post_init__(self) -> None:
        if type(self.source) is not _PhaseTwoFrozenCaptureSource:
            raise RunnerError("frozen phase-two trace source is invalid")
        self.source.verify()
        rows = tuple(
            _strict_json(line, label="frozen phase-two handoff trace")
            for line in self.source.handoff.trace_snapshot[0].splitlines()
        )
        validate_trace_records(rows)
        frozen: list[Mapping[str, Any]] = []
        for row in rows:
            value = _freeze_private_trace_value(row)
            if not isinstance(value, Mapping):
                raise RunnerError("frozen phase-two trace row is invalid")
            frozen.append(value)
        object.__setattr__(self, "rows", tuple(frozen))

    def records(self) -> list[dict[str, Any]]:
        self.source.verify()
        return [dict(row) for row in self.rows]


def _registered_actual_phase_two_live_roots(
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
) -> tuple[PinnedDirectory, PinnedDirectory]:
    """Return the detached phase-two roots retained by the live launch.

    The prepared aggregate deliberately continues to expose its original
    pins as token-shape sentinels.  Once generic launch begins, the live
    phase is the owner of the duplicate private descriptors; all phase-two
    post-launch reads must continue through those descriptors rather than
    recovering authority from the returned aggregate.
    """

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase):
        raise RunnerError("registered actual phase-two live roots are invalid")
    token_control = prepared_phase.control_pin
    token_workspace = prepared_phase.workspace_pin
    control_pin = live_phase.control_pin
    workspace_pin = live_phase.workspace_pin
    if (type(token_control) is not PinnedDirectory
            or type(token_workspace) is not PinnedDirectory
            or type(control_pin) is not PinnedDirectory
            or type(workspace_pin) is not PinnedDirectory
            or control_pin is token_control
            or workspace_pin is token_workspace
            or control_pin.path != token_control.path
            or workspace_pin.path != token_workspace.path
            or control_pin.edges != token_control.edges
            or workspace_pin.edges != token_workspace.edges
            or control_pin.private is not True
            or token_control.private is not True
            or workspace_pin.private is not False
            or token_workspace.private is not False):
        raise RunnerError("registered actual phase-two live roots are invalid")
    try:
        PinnedDirectory.verify(token_control)
        PinnedDirectory.verify(token_workspace)
        PinnedDirectory.verify(control_pin)
        PinnedDirectory.verify(workspace_pin)
    except RunnerError:
        raise
    except OSError as error:
        raise RunnerError("registered actual phase-two live roots are unavailable") from error
    return control_pin, workspace_pin


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoPostLaunchToken:
    """Private, non-serializable retention of phase-two host evidence.

    This is intentionally an in-memory diagnostic token, not an index or
    release object.  It records descriptor-backed identities only after the
    disconnected phase-two process has exited; it does not copy a receipt
    gate, trusted context, or provenance into evidence JSON.  Its exact
    expected artifact-type map is captured only after the full post-launch
    inventory closes, so later readers never infer a phase-two set from a
    required subset.
    """

    run_id: str
    execution_id: str
    prepared_phase: _RegisteredActualPreparedPhase
    live_phase: RegisteredLivePhase
    receipt_gate: "PhaseOneReceiptGate"
    receipt_control: "_FrozenActualPhaseOneReceiptControl"
    phase_one_bridge: _RegisteredActualPhaseOnePrivateLaunchBridge
    artifact_provenance: Mapping[str, _RegisteredActualEvidenceProvenance]
    expected_artifact_types: Mapping[str, str]
    trace_identity: tuple[int, int, int, int, int, int, int, int]
    trace_sha256: str
    snapshot_artifact_ids: tuple[str, ...]
    raw_control_handoff: _RegisteredActualPhaseTwoRawControlHandoff
    receipt_ledgers: _RegisteredActualPhaseTwoReceiptLedgers

    def __post_init__(self) -> None:
        if (type(self.run_id) is not str
                or len(self.run_id) != 64
                or any(character not in _SHA for character in self.run_id)
                or self.execution_id != "execution-2"
                or type(self.prepared_phase) is not _RegisteredActualPreparedPhase
                or type(self.live_phase) is not RegisteredLivePhase
                or type(self.receipt_gate) is not PhaseOneReceiptGate
                or type(self.receipt_control) is not _FrozenActualPhaseOneReceiptControl
                or type(self.phase_one_bridge) is not _RegisteredActualPhaseOnePrivateLaunchBridge
                or self.prepared_phase.execution_id != "execution-2"
                or self.prepared_phase.phase_index != 2
                or self.prepared_phase.phase != "approved_capture"
                or self.prepared_phase.writer.run_id != self.run_id
                or self.live_phase.executable_id != "client-executable-2"
                or self.live_phase.version_id != "version-2"
                or self.live_phase.help_id != "help-2"
                or self.receipt_gate.execution_id != "execution-1"
                or self.receipt_control.run_id != self.run_id
                or self.receipt_control.selection != self.receipt_gate.selection
                or not isinstance(self.artifact_provenance, Mapping)
                or not isinstance(self.expected_artifact_types, Mapping)
                or type(self.trace_identity) is not tuple
                or len(self.trace_identity) != 8
                or any(type(item) is not int for item in self.trace_identity)
                or not _is_hex64(self.trace_sha256)
                or type(self.snapshot_artifact_ids) is not tuple
                or not self.snapshot_artifact_ids
                or self.snapshot_artifact_ids[0] != _workspace_snapshot_artifact_id(
                    "execution-2", "initial", 0,
                )
                or len(set(self.snapshot_artifact_ids)) != len(self.snapshot_artifact_ids)
                or any(type(artifact_id) is not str or not artifact_id
                       for artifact_id in self.snapshot_artifact_ids)
                or type(self.raw_control_handoff)
                is not _RegisteredActualPhaseTwoRawControlHandoff
                or type(self.receipt_ledgers) is not _RegisteredActualPhaseTwoReceiptLedgers):
            raise RunnerError("registered actual phase-two post-launch token is invalid")
        control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
            self.prepared_phase, self.live_phase,
        )
        if (self.receipt_control.control_pin is not control_pin
                or self.receipt_control.artifacts is not self.phase_one_bridge.receipt_artifacts
                or self.phase_one_bridge.live_phase.control_pin is not control_pin
                or self.phase_one_bridge.live_phase.workspace_pin is not workspace_pin):
            raise RunnerError("registered actual phase-two post-launch token is invalid")
        self.phase_one_bridge.assert_current(
            control_pin=control_pin,
            workspace_pin=workspace_pin,
            trusted_context=self.live_phase.trusted_context,
        )
        frozen: dict[str, _RegisteredActualEvidenceProvenance] = {}
        for artifact_id, record in self.artifact_provenance.items():
            if (type(artifact_id) is not str or not artifact_id
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in artifact_id)
                    or type(record) is not tuple or len(record) != 5):
                raise RunnerError("registered actual phase-two post-launch token is invalid")
            artifact_type, relative, digest, byte_count, identity = record
            path = PurePosixPath(relative) if type(relative) is str else None
            if (type(artifact_type) is not str or not artifact_type
                    or type(relative) is not str or path is None
                    or path.is_absolute() or path.as_posix() != relative or not path.parts
                    or any(part in {"", ".", ".."} for part in path.parts)
                    or not _is_hex64(digest)
                    or type(byte_count) is not int or byte_count < 0
                    or type(identity) is not tuple or len(identity) != 8
                    or any(type(item) is not int for item in identity)):
                raise RunnerError("registered actual phase-two post-launch token is invalid")
            frozen[artifact_id] = (
                artifact_type, relative, digest, byte_count, tuple(identity),
            )
        frozen_expected_types: dict[str, str] = {}
        for artifact_id, artifact_type in self.expected_artifact_types.items():
            if (type(artifact_id) is not str or not artifact_id
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in artifact_id)
                    or type(artifact_type) is not str or not artifact_type
                    or artifact_id in frozen_expected_types):
                raise RunnerError("registered actual phase-two post-launch token is invalid")
            frozen_expected_types[artifact_id] = artifact_type
        if (not frozen
                or not frozen_expected_types
                or set(frozen) != set(frozen_expected_types)
                or any(frozen[artifact_id][0] != artifact_type
                       for artifact_id, artifact_type in frozen_expected_types.items())
                or any(artifact_id not in frozen
                       or frozen[artifact_id][0] != "workspace_snapshot"
                       for artifact_id in self.snapshot_artifact_ids)):
            raise RunnerError("registered actual phase-two post-launch token is invalid")
        self.raw_control_handoff.__post_init__()
        self.receipt_ledgers.__post_init__()
        self.receipt_control.verify()
        if (self.receipt_ledgers.run_id != self.run_id
                or self.receipt_ledgers.execution_id != self.execution_id):
            raise RunnerError("registered actual phase-two post-launch token is invalid")
        object.__setattr__(self, "artifact_provenance", MappingProxyType(frozen))
        object.__setattr__(self, "expected_artifact_types", MappingProxyType(frozen_expected_types))

    def __reduce__(self) -> object:
        """Prevent this private retained-host token from becoming a payload."""

        raise TypeError("registered actual phase-two post-launch token is not serializable")


@dataclass(frozen=True)
class _RegisteredActualTwoPhaseHostJoin:
    """Frozen descriptor view of the still-open two-phase host graph.

    This intentionally retains only descriptor-derived rows and the complete
    run-tree shape.  It is neither an eligibility object nor a serialization
    surface: callers must re-read it through its retained private control pin
    before crossing another diagnostic boundary.
    """

    run_id: str
    control_pin: PinnedDirectory
    artifact_provenance: Mapping[str, _RegisteredActualEvidenceProvenance]
    directories: frozenset[str]

    def __post_init__(self) -> None:
        if (type(self.run_id) is not str
                or len(self.run_id) != 64
                or any(character not in _SHA for character in self.run_id)
                or not isinstance(self.control_pin, PinnedDirectory)
                or not self.control_pin.private
                or not isinstance(self.artifact_provenance, Mapping)
                or type(self.directories) is not frozenset):
            raise RunnerError("registered actual two-phase host join is invalid")
        frozen: dict[str, _RegisteredActualEvidenceProvenance] = {}
        paths: set[str] = set()
        expected_directories: set[str] = set()
        for artifact_id, record in self.artifact_provenance.items():
            if (type(artifact_id) is not str or not artifact_id
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in artifact_id)
                    or type(record) is not tuple or len(record) != 5):
                raise RunnerError("registered actual two-phase host join is invalid")
            artifact_type, relative, digest, byte_count, identity = record
            path = PurePosixPath(relative) if type(relative) is str else None
            if (type(artifact_type) is not str or not artifact_type
                    or path is None or path.is_absolute() or path.as_posix() != relative
                    or not path.parts or any(part in {"", ".", ".."} for part in path.parts)
                    or not _is_hex64(digest)
                    or type(byte_count) is not int or byte_count < 0
                    or not _valid_regular_identity(identity)
                    or identity[5] != byte_count
                    or relative in paths):
                raise RunnerError("registered actual two-phase host join is invalid")
            paths.add(relative)
            expected_directories.update(
                parent.as_posix()
                for parent in path.parents
                if parent != PurePosixPath(".")
            )
            frozen[artifact_id] = (
                artifact_type, relative, digest, byte_count, tuple(identity),
            )
        if not frozen:
            raise RunnerError("registered actual two-phase host join is invalid")
        for directory in self.directories:
            try:
                PinnedDirectory._relative_parts(directory)
            except RunnerError as error:
                raise RunnerError("registered actual two-phase host join is invalid") from error
        if set(self.directories) != expected_directories:
            raise RunnerError("registered actual two-phase host join is invalid")
        object.__setattr__(self, "artifact_provenance", MappingProxyType(frozen))

    def verify(self) -> None:
        """Re-read only the retained descriptor graph; no writer lookup exists."""

        self.__post_init__()
        PinnedDirectory.verify(self.control_pin)
        expected_files: set[str] = set()
        for artifact_id, record in self.artifact_provenance.items():
            _artifact_type, relative, digest, byte_count, identity = record
            raw, observed = PinnedDirectory.snapshot_relative(
                self.control_pin,
                PurePosixPath("runs", self.run_id, relative).as_posix(),
            )
            if (observed != identity
                    or len(raw) != byte_count
                    or _sha256(raw) != digest):
                raise RunnerError("registered actual two-phase host join changed")
            expected_files.add(relative)
        directories, files = _pinned_control_tree_inventory(
            self.control_pin,
            PurePosixPath("runs", self.run_id).as_posix(),
        )
        if set(directories) != set(self.directories) or set(files) != expected_files:
            raise RunnerError("registered actual two-phase host tree changed")
        PinnedDirectory.verify(self.control_pin)

    def __reduce__(self) -> object:
        raise TypeError("registered actual two-phase host join is not serializable")


def _registered_actual_phase_one_fixture_metadata_binding(
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    metadata: _RegisteredActualScenarioFixtureMetadata,
) -> tuple[str, str]:
    """Bind the retained facade to phase one's descriptor-pinned host rows.

    The scenario/fixture facade is intentionally detached from mutable
    workspace dictionaries.  Before it can seed phase-two staging, make its
    fixture identity agree with both already-adopted phase-one host records.
    This also makes a direct replacement of the frozen Python object fail
    before the phase-two stage directory exists.
    """

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(metadata) is not _RegisteredActualScenarioFixtureMetadata):
        raise RunnerError("registered actual phase-one fixture binding is invalid")
    phase_one_diagnostic.__post_init__()
    metadata.__post_init__()
    artifacts = phase_one_diagnostic.receipt_artifacts
    expected = (
        (phase_one_diagnostic.policy_id, "policy"),
        (phase_one_diagnostic.process_id, "process"),
    )
    for artifact_id, artifact_type in expected:
        value = _strict_json(
            artifacts.read(artifact_id, artifact_type),
            label="registered actual phase-one fixture binding",
        )
        fixture_id = value.get("fixture_id") if type(value) is dict else None
        fixture_sha256 = value.get("fixture_sha256") if type(value) is dict else None
        if (type(value) is not dict
                or value.get("run_id") != artifacts.run_id
                or value.get("execution_id") != "execution-1"
                or value.get("phase") != "approval"
                or value.get("client") != "claude"
                or fixture_id != metadata.fixture_id
                or fixture_sha256 != metadata.fixture_sha256):
            raise RunnerError("registered actual phase-one fixture binding changed")
    return metadata.fixture_id, metadata.fixture_sha256


def _registered_actual_phase_one_private_fixture_metadata_binding(
    bridge: _RegisteredActualPhaseOnePrivateLaunchBridge,
    metadata: _RegisteredActualScenarioFixtureMetadata,
) -> tuple[str, str]:
    """Bind fixture facts through the detached phase-one artifact facade."""

    if (type(bridge) is not _RegisteredActualPhaseOnePrivateLaunchBridge
            or type(metadata) is not _RegisteredActualScenarioFixtureMetadata):
        raise RunnerError("registered actual private phase-one fixture binding is invalid")
    bridge.__post_init__()
    metadata.__post_init__()
    artifacts = bridge.receipt_artifacts
    for artifact_id, artifact_type in (
            (bridge.policy_id, "policy"),
            (bridge.process_id, "process")):
        value = _strict_json(
            artifacts.read(artifact_id, artifact_type),
            label="registered actual private phase-one fixture binding",
        )
        fixture_id = value.get("fixture_id") if type(value) is dict else None
        fixture_sha256 = value.get("fixture_sha256") if type(value) is dict else None
        if (type(value) is not dict
                or value.get("run_id") != artifacts.run_id
                or value.get("execution_id") != "execution-1"
                or value.get("phase") != "approval"
                or value.get("client") != "claude"
                or fixture_id != metadata.fixture_id
                or fixture_sha256 != metadata.fixture_sha256):
            raise RunnerError("registered actual private phase-one fixture binding changed")
    return metadata.fixture_id, metadata.fixture_sha256


def _read_registered_actual_two_phase_host_join(
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    provenance: _RegisteredActualPhaseTwoPostLaunchToken,
    *,
    stage: "_RegisteredActualPhaseTwoDiagnosticStage | None" = None,
) -> _RegisteredActualTwoPhaseHostJoin:
    """Rebuild the complete open or staged host graph from frozen inputs.

    The reader deliberately never inspects ``writer.entries``.  The retained
    phase-one artifact snapshot and the token's exact post-launch type map
    together own the one-to-one base artifact map.  When supplied, the
    retained stage snapshot contributes its separately descriptor-pinned
    rows; every current byte and identity is re-read via the original
    control-root descriptor before a join is returned.
    """

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(provenance) is not _RegisteredActualPhaseTwoPostLaunchToken
            or stage is not None and type(stage) is not _RegisteredActualPhaseTwoDiagnosticStage):
        raise RunnerError("registered actual two-phase host join inputs are invalid")
    provenance.__post_init__()
    phase_one = phase_one_diagnostic.prepared_phase
    source_phase_one_live = phase_one_diagnostic.live_phase
    phase_one_bridge = provenance.phase_one_bridge
    phase_one_live = phase_one_bridge.live_phase
    phase_two = provenance.prepared_phase
    phase_two_live = provenance.live_phase
    prepared_run = phase_two.prepared_run
    prepared = prepared_run.prepared
    control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
        phase_two, phase_two_live,
    )
    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(prepared) is not PreparedWorkspace
            or phase_one.prepared_run is not prepared_run
            or source_phase_one_live.control_pin is not phase_two.control_pin
            or source_phase_one_live.workspace_pin is not phase_two.workspace_pin
            or phase_two.writer is not prepared_run.writer
            or phase_two.writer.run_id != provenance.run_id
            or phase_two.writer.control_root != control_pin.path
            or phase_two.writer.run_root != control_pin.path / "runs" / provenance.run_id
            or phase_one_live.control_pin is not control_pin
            or phase_one_live.workspace_pin is not workspace_pin
            or provenance.receipt_control.artifacts is not phase_one_bridge.receipt_artifacts
            or provenance.receipt_control.control_pin is not control_pin
            or provenance.receipt_control.selection != provenance.receipt_gate.selection
            or phase_two.mcp_config is None):
        raise RunnerError("registered actual two-phase host join is invalid")

    phase_one_artifacts = phase_one_bridge.receipt_artifacts
    phase_one_artifacts.verify()
    frozen = provenance.artifact_provenance
    expected_artifact_types = provenance.expected_artifact_types
    if (set(frozen) != set(expected_artifact_types)
            or any(frozen[artifact_id][0] != artifact_type
                   for artifact_id, artifact_type in expected_artifact_types.items())):
        raise RunnerError("registered actual two-phase host join is incomplete")
    for artifact_id, entry in phase_one_artifacts.entries.items():
        snapshot = phase_one_artifacts.snapshots.get(artifact_id)
        if snapshot is None:
            raise RunnerError("registered actual two-phase host join is incomplete")
        raw, identity = snapshot
        expected = (
            entry["type"], entry["relative_path"], entry["sha256"], entry["bytes"], identity,
        )
        if frozen.get(artifact_id) != expected or len(raw) != entry["bytes"]:
            raise RunnerError("registered actual two-phase host join changed")

    setup_provenance = phase_two.sealed_evidence_provenance
    if (not isinstance(setup_provenance, Mapping)
            or not setup_provenance
            or any(frozen.get(artifact_id) != record
                   for artifact_id, record in setup_provenance.items())):
        raise RunnerError("registered actual two-phase setup provenance changed")

    required_phase_two_ids = {
        phase_two.phase_prompt.artifact_id,
        "mcp-2",
        phase_two_live.version_id,
        phase_two_live.help_id,
        phase_two_live.executable_id,
        phase_two.initial_workspace_snapshot.artifact_id,
        *provenance.snapshot_artifact_ids,
    }
    if (any(type(artifact_id) is not str or not artifact_id for artifact_id in required_phase_two_ids)
            or not required_phase_two_ids.issubset(frozen)):
        raise RunnerError("registered actual two-phase host join is incomplete")

    authority = prepared_run.authority
    plan = authority.plan
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    registration = _runner_owned_registration(plan.client)
    scenario = metadata.scenario()
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phase_plan(plan.scenario_id) != ("approval", "approved_capture")
            or metadata.scenario_id != plan.scenario_id
            or phase_two.workspace != prepared.workspace):
        raise RunnerError("registered actual two-phase host join is invalid")
    _registered_actual_phase_one_private_fixture_metadata_binding(
        phase_one_bridge,
        metadata,
    )
    reconstructed_gate = _reconstruct_frozen_actual_phase_one_receipt_gate(
        control=provenance.receipt_control,
        phase_one=phase_one_live,
        scenario=scenario,
        conversion=phase_one_bridge.conversion,
        workspace=workspace_pin.path,
        execution_id="execution-1",
    )
    if not _phase_one_receipt_gate_matches(provenance.receipt_gate, reconstructed_gate):
        raise RunnerError("registered actual two-phase receipt gate changed")
    private_trusted_context = phase_two_live.trusted_context
    phase_one_registration, phase_one_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-1",
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        trusted_context=private_trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    phase_two_registration, phase_two_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-2",
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        trusted_context=private_trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    if (phase_one_registration is not registration
            or phase_two_registration is not registration
            or phase_two_trusted is not phase_two_live.trusted_executable
            or phase_two_trusted is phase_one_trusted
            or private_trusted_context.trusted_executables.get("execution-1")
            is not phase_one_trusted
            or private_trusted_context.trusted_executables.get("execution-2")
            is not phase_two_trusted):
        raise RunnerError("registered actual two-phase host context changed")
    _registered_executable_observation(phase_one_trusted)
    _registered_executable_observation(phase_two_trusted)
    provenance.raw_control_handoff.verify(control_pin)

    joined_provenance: dict[str, _RegisteredActualEvidenceProvenance] = dict(frozen)
    if stage is not None:
        if (stage.run_id != provenance.run_id
                or stage.control_pin is not control_pin
                or stage.stage_name in {"", "."}):
            raise RunnerError("registered actual two-phase diagnostic stage is invalid")
        stage.verify()
        occupied_paths = {record[1] for record in joined_provenance.values()}
        for artifact_id, entry in stage.entries.items():
            relative = str(entry["relative_path"])
            identity = stage.tree.get(relative)
            adopted_relative = PurePosixPath(stage.stage_name, relative).as_posix()
            if (identity is None
                    or artifact_id in joined_provenance
                    or adopted_relative in occupied_paths):
                raise RunnerError("registered actual two-phase host join stage is ambiguous")
            joined_provenance[artifact_id] = (
                str(entry["type"]), adopted_relative, str(entry["sha256"]),
                int(entry["bytes"]), identity,
            )
            occupied_paths.add(adopted_relative)

    directories = {
        parent.as_posix()
        for _artifact_type, relative, _digest, _byte_count, _identity in joined_provenance.values()
        for parent in PurePosixPath(relative).parents
        if parent != PurePosixPath(".")
    }
    joined = _RegisteredActualTwoPhaseHostJoin(
        provenance.run_id,
        control_pin,
        joined_provenance,
        frozenset(directories),
    )
    joined.verify()
    return joined


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoLiveLaunch:
    """The disconnected phase-two result plus its private retention token."""

    live_phase: RegisteredLivePhase
    post_launch_token: _RegisteredActualPhaseTwoPostLaunchToken

    def __post_init__(self) -> None:
        if (type(self.live_phase) is not RegisteredLivePhase
                or type(self.post_launch_token) is not _RegisteredActualPhaseTwoPostLaunchToken
                or self.post_launch_token.execution_id != "execution-2"
                or self.live_phase.executable_id != "client-executable-2"
                or self.live_phase.version_id != "version-2"
                or self.live_phase.help_id != "help-2"):
            raise RunnerError("registered actual phase-two live launch is invalid")


def _verify_registered_actual_phase_control(
    prepared_phase: _RegisteredActualPreparedPhase,
    *,
    scenario: Mapping[str, Any],
    control_pin: PinnedDirectory | None = None,
) -> None:
    """Reload the exact first-phase control/snapshot facts without writing."""

    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != prepared_phase.writer.control_root):
        raise RunnerError("registered actual phase control pin is invalid")
    phase_control = prepared_phase.phase_control
    expected_config_path = prepared_phase.writer.control_root / "brain-shim.json"
    if phase_control.config.path != expected_config_path:
        raise RunnerError("registered actual phase control locator mismatch")
    verify_phase_control(phase_control)
    fixture: dict[str, str] | None = None
    expected_assets: set[str] = set()
    if scenario.get("network_mode") == "mock_only":
        fixture = {
            "descriptor_path": "fixture-descriptor.json",
            "static_shell_path": "static-shell.html",
            "rendered_dom_path": "rendered-dom.html",
        }
        expected_assets = {
            "fixture-descriptor.json", "static-shell.html", "rendered-dom.html",
        }
    if set(phase_control.fixture_assets) != expected_assets:
        raise RunnerError("registered actual phase control assets mismatch")
    approval = (
        _registered_actual_phase_two_approval()
        if (prepared_phase.execution_id == "execution-2"
                and prepared_phase.phase == "approved_capture")
        else _phase_approval(scenario)
    )
    expected = {
        "schema_version": 1,
        "workspace": str(prepared_phase.workspace),
        "scenario_id": scenario.get("id"),
        "phase": prepared_phase.phase,
        "approval": approval,
        "fixture": fixture,
    }
    raw = PinnedDirectory.read_relative(control_pin, "brain-shim.json")
    value = _strict_json(raw, label="registered actual phase control")
    if type(value) is not dict or value != expected or raw != _canonical_json(value):
        raise RunnerError("registered actual phase control binding mismatch")
    snapshot = _indexed_workspace_snapshot(
        prepared_phase.writer,
        prepared_phase.initial_workspace_snapshot,
        control_pin=control_pin,
    )
    expected_snapshot_id = _workspace_snapshot_artifact_id(
        prepared_phase.execution_id, "initial", 0,
    )
    if (snapshot.execution_id != prepared_phase.execution_id
            or snapshot.role != "initial"
            or snapshot.trace_sequence != 0
            or snapshot.artifact_id != expected_snapshot_id):
        raise RunnerError("registered actual initial workspace snapshot mismatch")


def _launch_actual_registered_live_phase(
    prepared_phase: _RegisteredActualPreparedPhase,
) -> RegisteredLivePhase:
    """Launch one sealed actual phase with production probe and Popen defaults.

    The closed Claude/web phase-one bridge calls this private seam after
    setup, so it cannot receive a test process/probe adapter.  It derives all
    variable launch data from already-sealed internal facts and performs no
    phase-two, semantic, or pass emission.
    """

    if type(prepared_phase) is not _RegisteredActualPreparedPhase:
        raise RunnerError("registered actual prepared phase is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot execute actual launch")

    authority = prepared_phase.authority
    plan = authority.plan
    if type(authority) is not _RegisteredActualAuthority or type(plan) is not RegisteredActualScenarioPlan:
        raise RunnerError("registered actual authority is invalid")
    registration = _runner_owned_registration(plan.client)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    if (registration is not plan.registration
            or symbolic_template != plan.symbolic_template
            or network_attestation != plan.network_attestation):
        raise RunnerError("registered actual plan is no longer runner-owned")

    phases = phase_plan(plan.scenario_id)
    if (prepared_phase.phase_index != 1
            or prepared_phase.phase != phases[0]
            or prepared_phase.execution_id != "execution-1"):
        raise RunnerError("registered actual wrapper supports phase one only")
    # The phase-one setup token deliberately has no executable/context fact.
    # Supplying one here would bypass the low-level launcher's fresh
    # descriptor/read + build-registry preparation path.
    if prepared_phase.trusted_context is not None:
        raise RunnerError("registered actual phase-one trusted context must be absent")
    if (not prepared_phase.control_pin.private
            or prepared_phase.workspace_pin.private
            or prepared_phase.workspace != prepared_phase.workspace_pin.path
            or prepared_phase.writer.control_root != prepared_phase.control_pin.path
            or prepared_phase.trace.control_root != prepared_phase.control_pin.path
            or prepared_phase.trace.control_pin is not prepared_phase.control_pin):
        raise RunnerError("registered actual phase root pin mismatch")
    if (prepared_phase.prepared_run.authority is not authority
            or prepared_phase.prepared_run.writer is not prepared_phase.writer
            or prepared_phase.prepared_run.prepared.workspace != prepared_phase.workspace
            or prepared_phase.prepared_run.prepared.control_pin is not prepared_phase.control_pin
            or prepared_phase.prepared_run.prepared.workspace_pin is not prepared_phase.workspace_pin):
        raise RunnerError("registered actual prepared run binding mismatch")
    if (prepared_phase.trace.path != (
                prepared_phase.control_pin.path
                / f"runner-trace-{prepared_phase.execution_id}.jsonl"
            )
            or prepared_phase.trace.lock_path != prepared_phase.control_pin.path / ".runner-trace.lock"):
        raise RunnerError("registered actual phase trace mismatch")
    if prepared_phase.transcript_id != f"transcript-{prepared_phase.phase_index}":
        raise RunnerError("registered actual phase transcript mismatch")

    metadata = _registered_actual_scenario_fixture_metadata(prepared_phase.prepared_run, plan)
    scenario = metadata.scenario()
    _verify_registered_actual_phase_control(prepared_phase, scenario=scenario)

    prompt = prepared_phase.phase_prompt
    expected_prompt = _canonical_phase_prompt(scenario, prepared_phase.phase)
    expected_prompt_id = f"phase-prompt-{prepared_phase.phase_index}"
    prompt_entry = next(
        (entry for entry in prepared_phase.writer.entries if entry.get("id") == expected_prompt_id),
        None,
    )
    if (prompt.artifact_id != expected_prompt_id
            or prompt.raw != expected_prompt
            or prompt.sha256 != _sha256(expected_prompt)
            or prompt.transport != _phase_prompt_transport(plan.client)
            or not isinstance(prompt_entry, Mapping)
            or prompt_entry.get("type") != "phase_prompt"
            or prompt_entry.get("sha256") != prompt.sha256
            or prompt_entry.get("bytes") != len(prompt.raw)
            or prompt.seal.path != (
                prepared_phase.writer.run_root / str(prompt_entry.get("relative_path", ""))
            ).resolve()):
        raise RunnerError("registered actual phase prompt is not sealed canonical evidence")

    mcp_path = prepared_phase.writer.control_root / "mcp-unused"
    if plan.client == "claude":
        mcp_config = prepared_phase.mcp_config
        expected_mcp_id = f"mcp-{prepared_phase.phase_index}"
        mcp_entry = next(
            (entry for entry in prepared_phase.writer.entries if entry.get("id") == expected_mcp_id),
            None,
        )
        if (not isinstance(mcp_config, ControlFileSeal)
                or not isinstance(mcp_entry, Mapping)
                or mcp_entry.get("type") != "mcp_config"
                or mcp_entry.get("sha256") != _sha256(EMPTY_MCP_BYTES)
                or mcp_entry.get("bytes") != len(EMPTY_MCP_BYTES)
                or mcp_config.path != (
                    prepared_phase.writer.run_root / str(mcp_entry.get("relative_path", ""))
                ).resolve()):
            raise RunnerError("registered actual MCP config is not sealed evidence")
        verify_control_file(mcp_config)
        if _safe_read(mcp_config.path) != EMPTY_MCP_BYTES:
            raise RunnerError("runner-owned MCP config bytes changed before actual launch")
        mcp_path = mcp_config.path
    elif prepared_phase.mcp_config is not None:
        raise RunnerError("registered actual Codex phase cannot receive MCP config")

    expected_runner_state_path = prepared_phase.writer.control_root / "runner-state.json"
    if prepared_phase.runner_state.path != expected_runner_state_path:
        raise RunnerError("registered actual runner state locator mismatch")
    verify_control_file(prepared_phase.runner_state)
    state_raw = _safe_read(prepared_phase.runner_state.path)
    state_value = _strict_json(state_raw, label="registered actual runner state")
    expected_state = {
        "schema_version": 1,
        "control_root": str(prepared_phase.writer.control_root),
        "workspace": str(prepared_phase.workspace),
        "run_id": prepared_phase.writer.run_id,
        "execution_id": prepared_phase.execution_id,
        "phase": prepared_phase.phase,
    }
    if (type(state_value) is not dict
            or set(state_value) != set(expected_state)
            or type(state_value.get("schema_version")) is not int
            or any(type(state_value.get(key)) is not str for key in expected_state if key != "schema_version")
            or state_value != expected_state
            or state_raw != _canonical_json(state_value)):
        raise RunnerError("registered actual runner state binding mismatch")
    _verify_phase_prompt(prompt)
    phase_argv = build_effective_argv(
        plan.client,
        plan.symbolic_template,
        prepared_phase.workspace,
        mcp_path,
        prompt.raw.decode("utf-8", "strict"),
    )
    environment = {
        "PATH": "/usr/bin:/bin",
        "HOME": str(prepared_phase.writer.control_root / "home"),
        "LANG": "C.UTF-8",
        CONTROL_ENV: str(prepared_phase.writer.control_root),
        RUNNER_STATE_ENV: str(prepared_phase.runner_state.path),
    }
    stdin = prompt.raw if plan.client == "codex" else b""
    try:
        return _launch_registered_live_phase(
            writer=prepared_phase.writer,
            client=plan.client,
            execution_id=prepared_phase.execution_id,
            phase=prepared_phase.phase,
            phase_index=prepared_phase.phase_index,
            workspace=prepared_phase.workspace,
            control_pin=prepared_phase.control_pin,
            workspace_pin=prepared_phase.workspace_pin,
            argv=phase_argv,
            environment=environment,
            stdin=stdin,
            trace=prepared_phase.trace,
            transcript_id=prepared_phase.transcript_id,
            on_native_record=prepared_phase.on_native_record,
            probe_runner=None,
            popen_factory=subprocess.Popen,
            trusted_context=prepared_phase.trusted_context,
        )
    finally:
        _verify_phase_prompt(prompt)
        verify_control_file(prepared_phase.runner_state)
        if prepared_phase.mcp_config is not None:
            verify_control_file(prepared_phase.mcp_config)
        _verify_registered_actual_phase_control(prepared_phase, scenario=scenario)


def _verify_phase_prompt(prompt: PhasePromptEvidence) -> None:
    """Recheck the exact raw indexed prompt before and after a spawn."""

    verify_control_file(prompt.seal)
    raw = _safe_read(prompt.seal.path)
    if raw != prompt.raw or _sha256(raw) != prompt.sha256:
        raise RunnerError("runner-owned phase prompt bytes changed during evaluation")


@dataclass(frozen=True)
class WorkspaceSnapshot:
    """A runner-local handle to one retained workspace snapshot artifact.

    The repeated fields are conveniences for capture-time callers only.  No
    projection may trust them: it reloads ``artifact_id`` through
    ``_indexed_workspace_snapshot`` before using the identity, inventory, or
    staged paths.  This prevents a later Python object from relabelling a
    marker-time capture without changing sealed evidence bytes.
    """

    execution_id: str
    trace_sequence: int
    inventory: tuple[Mapping[str, Any], ...]
    staged_paths: tuple[str, ...]
    artifact_id: str = ""
    role: str = "unsealed"
    native_record: Mapping[str, Any] | None = None


def _workspace_snapshot_artifact_id(
    execution_id: str, role: str, trace_sequence: int,
) -> str:
    return f"workspace-snapshot-{execution_id}-{role}-{trace_sequence}"


def _persist_workspace_snapshot(
    writer: EvidenceWriter,
    *,
    execution_id: str,
    trace_sequence: int,
    inventory: Sequence[Mapping[str, Any]],
    staged_paths: Sequence[str],
    role: str,
    native_record: Mapping[str, Any] | None,
    artifact_id: str | None = None,
) -> WorkspaceSnapshot:
    """Persist the full marker/baseline inventory before it is projected.

    Initial and marker views use the Task 7a snapshot wire shape now; the
    public contract amendment owns making them pass-facing.  A final view is
    retained only for an incomplete fallback diff and deliberately uses a
    separate assertion envelope so it cannot masquerade as an event anchor.
    """

    if artifact_id is None:
        artifact_id = _workspace_snapshot_artifact_id(execution_id, role, trace_sequence)
    if role == "initial":
        if trace_sequence != 0 or native_record is not None:
            raise RunnerError("initial workspace snapshot provenance invalid")
        record = {
            "schema_version": 1,
            "run_id": writer.run_id,
            "execution_id": execution_id,
            "anchor_kind": "phase_initial",
            "trace_sequence": 0,
            "inventory": [dict(item) for item in inventory],
            "staged_paths": list(staged_paths),
        }
        writer.add_json(artifact_id, "workspace_snapshot", record)
    elif role == "marker":
        if (trace_sequence <= 0 or not isinstance(native_record, Mapping)
                or set(native_record) != {"transcript_id", "byte_start", "byte_end", "sha256"}):
            raise RunnerError("marker workspace snapshot provenance invalid")
        record = {
            "schema_version": 1,
            "run_id": writer.run_id,
            "execution_id": execution_id,
            "anchor_kind": "native_record",
            "trace_sequence": trace_sequence,
            "transcript_id": native_record["transcript_id"],
            "native_record_start": native_record["byte_start"],
            "native_record_end": native_record["byte_end"],
            "native_record_sha256": native_record["sha256"],
            "inventory": [dict(item) for item in inventory],
            "staged_paths": list(staged_paths),
        }
        writer.add_json(artifact_id, "workspace_snapshot", record)
    elif role == "final":
        if trace_sequence != 0 or native_record is not None:
            raise RunnerError("final workspace snapshot provenance invalid")
        record = {
            "schema_version": 1,
            "kind": "workspace_snapshot_fallback",
            "run_id": writer.run_id,
            "snapshot_id": artifact_id,
            "execution_id": execution_id,
            "inventory": [dict(item) for item in inventory],
            "staged_paths": list(staged_paths),
        }
        writer.add_json(artifact_id, "assertion", record)
    else:
        raise RunnerError("invalid workspace snapshot role")
    return WorkspaceSnapshot(
        execution_id=execution_id,
        trace_sequence=trace_sequence,
        inventory=tuple(dict(item) for item in inventory),
        staged_paths=tuple(staged_paths),
        artifact_id=artifact_id,
        role=role,
        native_record=None if native_record is None else dict(native_record),
    )


def _indexed_workspace_snapshot(
    writer: EvidenceWriter,
    snapshot: WorkspaceSnapshot,
    *,
    control_pin: PinnedDirectory | None = None,
) -> WorkspaceSnapshot:
    """Reload and validate a snapshot solely from its indexed artifact."""

    if type(snapshot.artifact_id) is not str or not snapshot.artifact_id:
        raise RunnerError("workspace snapshot has no indexed identity")
    entry = _writer_entry_map(writer).get(snapshot.artifact_id)
    if entry is None or entry.get("type") not in {"workspace_snapshot", "assertion"}:
        raise RunnerError("workspace snapshot artifact unavailable")
    value = _strict_json(
        _writer_artifact_bytes(
            writer, snapshot.artifact_id, str(entry["type"]), control_pin=control_pin,
        ),
        label="workspace snapshot",
    )
    role: str
    native: Mapping[str, Any] | None
    trace_sequence: int
    if entry["type"] == "workspace_snapshot":
        initial_keys = {
            "schema_version", "run_id", "execution_id", "anchor_kind", "trace_sequence",
            "inventory", "staged_paths",
        }
        native_keys = initial_keys | {
            "transcript_id", "native_record_start", "native_record_end", "native_record_sha256",
        }
        if (type(value) is not dict or value.get("schema_version") != 1
                or value.get("run_id") != writer.run_id
                or type(value.get("execution_id")) is not str or not value["execution_id"]
                or type(value.get("trace_sequence")) is not int
                or type(value.get("inventory")) is not list
                or type(value.get("staged_paths")) is not list):
            raise RunnerError("workspace snapshot artifact invalid")
        if value.get("anchor_kind") == "phase_initial":
            if set(value) != initial_keys or value["trace_sequence"] != 0:
                raise RunnerError("initial workspace snapshot artifact invalid")
            role, native, trace_sequence = "initial", None, 0
        elif value.get("anchor_kind") == "native_record":
            if (set(value) != native_keys or value["trace_sequence"] <= 0
                    or type(value.get("transcript_id")) is not str or not value["transcript_id"]
                    or type(value.get("native_record_start")) is not int
                    or value["native_record_start"] < 0
                    or type(value.get("native_record_end")) is not int
                    or value["native_record_end"] <= value["native_record_start"]
                    or not _is_hex64(value.get("native_record_sha256", ""))):
                raise RunnerError("marker workspace snapshot provenance invalid")
            role = "marker"
            trace_sequence = value["trace_sequence"]
            native = {
                "transcript_id": value["transcript_id"],
                "byte_start": value["native_record_start"],
                "byte_end": value["native_record_end"],
                "sha256": value["native_record_sha256"],
            }
        else:
            raise RunnerError("workspace snapshot anchor kind invalid")
    else:
        fallback_keys = {
            "schema_version", "kind", "run_id", "snapshot_id", "execution_id",
            "inventory", "staged_paths",
        }
        if (type(value) is not dict or set(value) != fallback_keys
                or value.get("schema_version") != 1
                or value.get("kind") != "workspace_snapshot_fallback"
                or value.get("run_id") != writer.run_id
                or value.get("snapshot_id") != snapshot.artifact_id
                or type(value.get("execution_id")) is not str or not value["execution_id"]
                or type(value.get("inventory")) is not list
                or type(value.get("staged_paths")) is not list):
            raise RunnerError("fallback workspace snapshot artifact invalid")
        role, native, trace_sequence = "final", None, 0

    inventory: list[dict[str, Any]] = []
    previous_path = ""
    for entry in value["inventory"]:
        if (type(entry) is not dict or set(entry) != {"path", "sha256", "bytes", "content_id"}
                or type(entry.get("path")) is not str or entry["path"] <= previous_path
                or not _is_hex64(entry.get("sha256", ""))
                or type(entry.get("bytes")) is not int or entry["bytes"] < 0
                or type(entry.get("content_id")) is not str or not entry["content_id"]):
            raise RunnerError("workspace snapshot inventory invalid")
        pure = PurePosixPath(entry["path"])
        if (pure.is_absolute() or pure.as_posix() != entry["path"]
                or any(part in {"", ".", ".."} for part in pure.parts)):
            raise RunnerError("workspace snapshot inventory path invalid")
        raw = _writer_artifact_bytes(
            writer, entry["content_id"], "file_capture", control_pin=control_pin,
        )
        if len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]:
            raise RunnerError("workspace snapshot inventory bytes invalid")
        inventory.append(dict(entry))
        previous_path = entry["path"]
    staged: list[str] = []
    for path in value["staged_paths"]:
        pure = PurePosixPath(path) if type(path) is str else None
        if (type(path) is not str or not path or pure is None or pure.is_absolute()
                or pure.as_posix() != path or any(part in {"", ".", ".."} for part in pure.parts)):
            raise RunnerError("workspace snapshot staged path invalid")
        staged.append(path)
    if staged != sorted(set(staged)):
        raise RunnerError("workspace snapshot staged paths unordered")
    return WorkspaceSnapshot(
        execution_id=value["execution_id"], trace_sequence=trace_sequence,
        inventory=tuple(inventory), staged_paths=tuple(staged),
        artifact_id=snapshot.artifact_id, role=role,
        native_record=None if native is None else dict(native),
    )


def _indexed_marker_workspace_snapshot(
    writer: EvidenceWriter,
    snapshot: WorkspaceSnapshot,
    marker: SemanticMarkerEvidence,
) -> WorkspaceSnapshot:
    """Require one persisted marker snapshot to match its exact native row."""

    loaded = _indexed_workspace_snapshot(writer, snapshot)
    native = loaded.native_record
    candidate = marker.candidate
    if (loaded.role != "marker" or loaded.execution_id != marker.execution_id
            or loaded.trace_sequence != candidate.trace_sequence
            or not isinstance(native, Mapping)
            or native.get("transcript_id") != marker.transcript_id
            or native.get("byte_start") != candidate.native_record_start
            or native.get("byte_end") != candidate.native_record_end
            or native.get("sha256") != candidate.native_record_sha256):
        raise RunnerError("marker workspace snapshot does not match native evidence")
    return loaded


def _indexed_trace_workspace_snapshot(
    writer: EvidenceWriter,
    *,
    execution_id: str,
    native_row: Mapping[str, Any],
    control_pin: PinnedDirectory | None = None,
) -> WorkspaceSnapshot:
    """Resolve one trace-native row's immutable marker-time snapshot.

    This is intentionally independent of the in-memory snapshot collection.
    A trace row is sealed evidence only when its own indexed ID resolves to a
    native-record snapshot with the same execution, sequence, transcript
    span, and digest.  It also makes one snapshot per native row mandatory,
    rather than allowing a later marker planner to reuse a convenient view.
    """

    snapshot_id = native_row.get("workspace_snapshot_id")
    if type(snapshot_id) is not str or not snapshot_id:
        raise RunnerError("native trace workspace snapshot identity invalid")
    loaded = _indexed_workspace_snapshot(
        writer,
        WorkspaceSnapshot(
            execution_id="", trace_sequence=0, inventory=(), staged_paths=(),
            artifact_id=snapshot_id,
        ),
        control_pin=control_pin,
    )
    native = loaded.native_record
    if (loaded.role != "marker" or loaded.execution_id != execution_id
            or loaded.trace_sequence != native_row.get("sequence")
            or not isinstance(native, Mapping)
            or native.get("transcript_id") != native_row.get("transcript_id")
            or native.get("byte_start") != native_row.get("byte_start")
            or native.get("byte_end") != native_row.get("byte_end")
            or native.get("sha256") != native_row.get("sha256")):
        raise RunnerError("native trace workspace snapshot binding invalid")
    return loaded


def _trace_owned_marker_workspace_snapshot(
    writer: EvidenceWriter,
    snapshot: WorkspaceSnapshot,
    marker: SemanticMarkerEvidence,
    *,
    trace_snapshot_ids: Mapping[tuple[str, int], str] | None,
) -> WorkspaceSnapshot:
    """Return a marker snapshot only when its ID is the sealed trace ID.

    Focused pure projection tests may omit ``trace_snapshot_ids`` because
    they do not construct a run/process trace.  Every runner path supplies
    it, and then there is no fallback from a trace-owned snapshot to a
    provenance-lookalike artifact.
    """

    loaded = _indexed_marker_workspace_snapshot(writer, snapshot, marker)
    if trace_snapshot_ids is not None:
        expected = trace_snapshot_ids.get((
            marker.execution_id, marker.candidate.trace_sequence,
        ))
        if expected != loaded.artifact_id:
            raise RunnerError("marker workspace snapshot is not trace-owned")
    return loaded


class WorkspaceSnapshotter:
    """Capture deduplicated regular-file inventories through a pinned root.

    Snapshots are taken before a phase and when a native record contains a
    possible event marker.  The native parser decides later whether that
    candidate is admissible; the snapshotter never treats raw client text as
    semantic authority.  File content is retained once by digest, so adjacent
    marker snapshots do not multiply archive bytes.
    """

    _IGNORED_DIRECTORIES = frozenset({
        ".git", "__pycache__", ".pytest_cache", ".ruff_cache", ".mypy_cache",
        ".hypothesis", ".tox", ".nox", "htmlcov", ".claude",
    })
    # ``CLAUDE.md`` is deliberately the canonical relative symlink to
    # ``AGENTS.md``.  It is evaluator/runtime instruction metadata, not a
    # mutable brain artifact, so preserve it in the copied checkout without
    # weakening the no-symlink rule for captured workspace evidence.
    _IGNORED_FILES = frozenset({"CLAUDE.md"})

    def __init__(
        self,
        *,
        workspace: Path,
        workspace_pin: PinnedDirectory,
        writer: EvidenceWriter,
        control_pin: PinnedDirectory | None = None,
        reusable_snapshots: Sequence[WorkspaceSnapshot] = (),
    ) -> None:
        self.workspace = workspace.resolve()
        if workspace_pin.path != self.workspace:
            raise RunnerError("workspace snapshot pin mismatch")
        self.workspace_pin = workspace_pin
        self.writer = writer
        if control_pin is not None:
            if (not isinstance(control_pin, PinnedDirectory)
                    or not control_pin.private
                    or control_pin.path != writer.control_root.resolve()
                    or writer.run_root != control_pin.path / "runs" / writer.run_id):
                raise RunnerError("workspace snapshot control pin mismatch")
            PinnedDirectory.verify(control_pin)
        if (not isinstance(reusable_snapshots, Sequence)
                or isinstance(reusable_snapshots, (str, bytes))):
            raise RunnerError("workspace snapshot reusable evidence is invalid")
        self.control_pin = control_pin
        self._content_ids: dict[tuple[str, int], str] = {}
        # A phase-two baseline may legitimately contain unchanged files
        # retained by phase one.  Reuse is deliberately opt-in and derives
        # only from caller-supplied snapshots that reload as indexed evidence;
        # scanning arbitrary ``file_capture`` rows would let an injected row
        # acquire workspace-snapshot authority.  Still reject malformed
        # workspace-content rows even when no prior snapshot consumes them,
        # because their reserved IDs belong exclusively to this protocol.
        content_entries: dict[str, Mapping[str, Any]] = {}
        for entry in writer.entries:
            artifact_id = entry.get("id") if isinstance(entry, Mapping) else None
            if type(artifact_id) is not str or not artifact_id.startswith("workspace-content-"):
                continue
            digest = artifact_id.removeprefix("workspace-content-")
            if (not _is_hex64(digest)
                    or entry.get("type") != "file_capture"
                    or entry.get("relative_path") != f"artifacts/{artifact_id}.bin"
                    or entry.get("sha256") != digest
                    or type(entry.get("bytes")) is not int
                    or entry["bytes"] < 0
                    or artifact_id in content_entries):
                raise RunnerError("workspace snapshot content artifact is invalid")
            raw = _writer_artifact_bytes(
                writer, artifact_id, "file_capture", control_pin=control_pin,
            )
            if _sha256(raw) != digest or len(raw) != entry["bytes"]:
                raise RunnerError("workspace snapshot content artifact is invalid")
            content_entries[artifact_id] = entry
        for snapshot in reusable_snapshots:
            if not isinstance(snapshot, WorkspaceSnapshot):
                raise RunnerError("workspace snapshot reusable evidence is invalid")
            loaded = _indexed_workspace_snapshot(
                writer, snapshot, control_pin=control_pin,
            )
            for item in loaded.inventory:
                artifact_id = item["content_id"]
                digest = item["sha256"]
                if (artifact_id != "workspace-content-" + digest
                        or artifact_id not in content_entries):
                    raise RunnerError("workspace snapshot content artifact is unproven")
                raw = _writer_artifact_bytes(
                    writer, artifact_id, "file_capture", control_pin=control_pin,
                )
                if _sha256(raw) != digest or len(raw) != item["bytes"]:
                    raise RunnerError("workspace snapshot content artifact is invalid")
                key = (digest, len(raw))
                existing = self._content_ids.setdefault(key, artifact_id)
                if existing != artifact_id:
                    raise RunnerError("workspace snapshot content artifact is ambiguous")

    @staticmethod
    def _relative(value: Path, root: Path) -> str:
        try:
            relative = value.relative_to(root).as_posix()
        except ValueError as error:
            raise RunnerError("workspace snapshot escapes root") from error
        if not relative or relative == "." or relative.startswith("../"):
            raise RunnerError("invalid workspace snapshot path")
        return relative

    def _staged_paths(self) -> tuple[str, ...]:
        git_dir = self.workspace / ".git"
        if not git_dir.is_dir() or git_dir.is_symlink():
            return ()
        try:
            completed = subprocess.run(
                [str(_runner_git_binary()), "-c", "core.hooksPath=", "diff", "--cached", "--name-only", "-z"],
                cwd=self.workspace,
                env={
                    "HOME": str(self.writer.control_root / "git-home"), "LANG": "C.UTF-8",
                    "LC_ALL": "C.UTF-8", "PATH": "/usr/bin:/bin",
                    "GIT_CONFIG_NOSYSTEM": "1", "GIT_CONFIG_GLOBAL": os.devnull,
                },
                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                check=False,
            )
        except OSError as error:
            raise RunnerError("workspace staged inventory unavailable") from error
        if completed.returncode != 0:
            raise RunnerError("workspace staged inventory failed")
        paths: list[str] = []
        for raw in completed.stdout.split(b"\0"):
            if not raw:
                continue
            try:
                value = raw.decode("utf-8")
            except UnicodeDecodeError as error:
                raise RunnerError("workspace staged path encoding") from error
            pure = PurePosixPath(value)
            if (not value or pure.is_absolute() or pure.as_posix() != value
                    or any(part in {"", ".", ".."} for part in pure.parts)):
                raise RunnerError("workspace staged path invalid")
            paths.append(value)
        if paths != sorted(set(paths)):
            raise RunnerError("workspace staged paths are not canonical")
        return tuple(paths)

    def _require_fresh_unstaged_initial_workspace(self) -> None:
        """Prove a just-prepared phase-one workspace has no Git index.

        The disconnected actual phase-one setup has no client/process authority
        yet, so it must not spawn Git merely to rediscover a fact established
        by ``prepare_isolated_workspace``: the private ``git init`` created no
        index and nothing has staged a path.  An existing, unsafe, or replaced
        index is therefore a fail-closed setup error.  Marker/final snapshots
        keep using ``_staged_paths`` after an actual phase is authorized.
        """

        PinnedDirectory.verify(self.workspace_pin)
        git_dir = self.workspace / ".git"
        try:
            git_info = git_dir.lstat()
        except OSError as error:
            raise RunnerError("fresh phase-one Git metadata unavailable") from error
        if git_dir.is_symlink() or not stat.S_ISDIR(git_info.st_mode):
            raise RunnerError("fresh phase-one Git metadata unsafe")
        index = git_dir / "index"
        try:
            index.lstat()
        except FileNotFoundError:
            PinnedDirectory.verify(self.workspace_pin)
            return
        except OSError as error:
            raise RunnerError("fresh phase-one Git index unavailable") from error
        raise RunnerError("fresh phase-one workspace has a staged Git index")

    def _capture(
        self,
        *,
        execution_id: str,
        trace_sequence: int,
        role: str | None,
        native_record: Mapping[str, Any] | None,
        staged_paths: tuple[str, ...] | None,
    ) -> WorkspaceSnapshot:
        """Capture one snapshot, optionally with caller-proven staged paths."""

        if (not execution_id or type(trace_sequence) is not int or trace_sequence < 0):
            raise RunnerError("invalid workspace snapshot identity")
        if role is None:
            role = "marker" if trace_sequence > 0 else "initial"
        if role not in {"initial", "marker", "final"}:
            raise RunnerError("invalid workspace snapshot role")
        if role == "marker":
            if trace_sequence <= 0 or native_record is None:
                raise RunnerError("marker workspace snapshot needs native provenance")
        elif trace_sequence != 0 or native_record is not None:
            raise RunnerError("baseline workspace snapshot has native provenance")
        if staged_paths is not None and staged_paths != tuple(sorted(set(staged_paths))):
            raise RunnerError("workspace staged paths are not canonical")
        PinnedDirectory.verify(self.workspace_pin)
        inventory: list[dict[str, Any]] = []
        for directory, directories, files in os.walk(self.workspace, topdown=True, followlinks=False):
            directory_path = Path(directory)
            directory_info = directory_path.lstat()
            if directory_path.is_symlink() or not stat.S_ISDIR(directory_info.st_mode):
                raise RunnerError("unsafe workspace snapshot directory")
            directories[:] = sorted(
                name for name in directories
                if name not in self._IGNORED_DIRECTORIES and not name.endswith((".pyc", ".pyo"))
            )
            for name in directories:
                child = directory_path / name
                info = child.lstat()
                if child.is_symlink() or not stat.S_ISDIR(info.st_mode):
                    raise RunnerError("unsafe workspace snapshot directory")
            for name in sorted(files):
                if name in self._IGNORED_FILES or name.endswith((".pyc", ".pyo")):
                    continue
                path = directory_path / name
                info = path.lstat()
                if path.is_symlink() or not stat.S_ISREG(info.st_mode):
                    raise RunnerError("unsafe workspace snapshot file")
                relative = self._relative(path, self.workspace)
                raw = PinnedDirectory.read_relative(self.workspace_pin, relative)
                digest = _sha256(raw)
                key = (digest, len(raw))
                artifact_id = self._content_ids.get(key)
                if artifact_id is None:
                    artifact_id = "workspace-content-" + digest
                    self.writer.add_bytes(artifact_id, "file_capture", raw)
                    self._content_ids[key] = artifact_id
                inventory.append({
                    "path": relative, "sha256": digest, "bytes": len(raw), "content_id": artifact_id,
                })
        inventory.sort(key=lambda item: item["path"])
        if len({item["path"] for item in inventory}) != len(inventory):
            raise RunnerError("duplicate workspace snapshot path")
        if staged_paths is None:
            staged_paths = self._staged_paths()
        PinnedDirectory.verify(self.workspace_pin)
        return _persist_workspace_snapshot(
            self.writer,
            execution_id=execution_id,
            trace_sequence=trace_sequence,
            inventory=inventory,
            staged_paths=staged_paths,
            role=role,
            native_record=native_record,
        )

    def capture(
        self,
        *,
        execution_id: str,
        trace_sequence: int,
        role: str | None = None,
        native_record: Mapping[str, Any] | None = None,
    ) -> WorkspaceSnapshot:
        return self._capture(
            execution_id=execution_id,
            trace_sequence=trace_sequence,
            role=role,
            native_record=native_record,
            staged_paths=None,
        )

    def capture_fresh_unstaged_initial(self, *, execution_id: str) -> WorkspaceSnapshot:
        """Capture a fresh phase-one baseline without launching Git or a client."""

        self._require_fresh_unstaged_initial_workspace()
        return self._capture(
            execution_id=execution_id,
            trace_sequence=0,
            role="initial",
            native_record=None,
            staged_paths=(),
        )


_RegisteredActualPhaseTwoWorkspaceInventory = tuple[tuple[str, str, int], ...]


def _registered_actual_phase_two_workspace_inventory_is_valid(value: object) -> bool:
    """Validate the immutable regular-file surface sealed for phase two."""

    if type(value) is not tuple:
        return False
    previous = ""
    for item in value:
        if type(item) is not tuple or len(item) != 3:
            return False
        relative, digest, byte_count = item
        if (type(relative) is not str or relative <= previous
                or not _is_hex64(digest)
                or type(byte_count) is not int or byte_count < 0):
            return False
        previous = relative
    return True


def _registered_actual_phase_two_initial_workspace_inventory(
    writer: EvidenceWriter,
    *,
    control_pin: PinnedDirectory,
    initial_workspace_snapshot: WorkspaceSnapshot,
) -> _RegisteredActualPhaseTwoWorkspaceInventory:
    """Reload one sealed phase-two inventory without inspecting the workspace."""

    expected_id = _workspace_snapshot_artifact_id("execution-2", "initial", 0)
    if (type(writer) is not EvidenceWriter
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or not isinstance(initial_workspace_snapshot, WorkspaceSnapshot)
            or initial_workspace_snapshot.artifact_id != expected_id
            or control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id):
        raise RunnerError("registered actual phase-two workspace baseline is invalid")
    snapshot = _indexed_workspace_snapshot(
        writer,
        initial_workspace_snapshot,
        control_pin=control_pin,
    )
    if (snapshot.artifact_id != expected_id
            or snapshot.execution_id != "execution-2"
            or snapshot.role != "initial"
            or snapshot.trace_sequence != 0):
        raise RunnerError("registered actual phase-two workspace baseline is invalid")
    expected: list[tuple[str, str, int]] = []
    previous = ""
    for item in snapshot.inventory:
        relative = item.get("path")
        digest = item.get("sha256")
        byte_count = item.get("bytes")
        if (type(relative) is not str or relative <= previous
                or not _is_hex64(digest)
                or type(byte_count) is not int or byte_count < 0):
            raise RunnerError("registered actual phase-two workspace baseline is invalid")
        expected.append((relative, digest, byte_count))
        previous = relative
    inventory = tuple(expected)
    if not _registered_actual_phase_two_workspace_inventory_is_valid(inventory):
        raise RunnerError("registered actual phase-two workspace baseline is invalid")
    return inventory


def _verify_registered_actual_phase_two_workspace_inventory_is_current(
    workspace_pin: PinnedDirectory,
    expected_inventory: _RegisteredActualPhaseTwoWorkspaceInventory,
) -> None:
    """Require a workspace to retain one sealed regular-file inventory.

    This is deliberately a read-only counterpart to ``WorkspaceSnapshotter``.
    Re-capturing through that class would append evidence and invoke Git for
    staged paths, neither of which is permitted at the terminal setup
    boundary.  It preserves the snapshotter's file/ignore semantics and
    compares only the regular-file inventory the initial snapshot can prove.
    """

    if (not isinstance(workspace_pin, PinnedDirectory)
            or workspace_pin.private
            or not _registered_actual_phase_two_workspace_inventory_is_valid(
                expected_inventory,
            )):
        raise RunnerError("registered actual phase-two workspace baseline is invalid")
    expected: dict[str, tuple[str, int]] = {}
    for item in expected_inventory:
        relative, digest, byte_count = item
        if relative in expected:
            raise RunnerError("registered actual phase-two workspace baseline is invalid")
        expected[relative] = (digest, byte_count)

    workspace = workspace_pin.path
    PinnedDirectory.verify(workspace_pin)
    observed: set[str] = set()
    for directory, directories, files in os.walk(
            workspace, topdown=True, followlinks=False,
    ):
        directory_path = Path(directory)
        directory_info = directory_path.lstat()
        if directory_path.is_symlink() or not stat.S_ISDIR(directory_info.st_mode):
            raise RunnerError("unsafe registered actual phase-two workspace directory")
        directories[:] = sorted(
            name for name in directories
            if name not in WorkspaceSnapshotter._IGNORED_DIRECTORIES
            and not name.endswith((".pyc", ".pyo"))
        )
        for name in directories:
            child = directory_path / name
            info = child.lstat()
            if child.is_symlink() or not stat.S_ISDIR(info.st_mode):
                raise RunnerError("unsafe registered actual phase-two workspace directory")
        for name in sorted(files):
            if (name in WorkspaceSnapshotter._IGNORED_FILES
                    or name.endswith((".pyc", ".pyo"))):
                continue
            path = directory_path / name
            info = path.lstat()
            if path.is_symlink() or not stat.S_ISREG(info.st_mode):
                raise RunnerError("unsafe registered actual phase-two workspace file")
            relative = WorkspaceSnapshotter._relative(path, workspace)
            expected_record = expected.get(relative)
            if expected_record is None or relative in observed:
                raise RunnerError("registered actual phase-two workspace changed before launch")
            raw = PinnedDirectory.read_relative(workspace_pin, relative)
            if (_sha256(raw), len(raw)) != expected_record:
                raise RunnerError("registered actual phase-two workspace changed before launch")
            observed.add(relative)
    if observed != set(expected):
        raise RunnerError("registered actual phase-two workspace changed before launch")
    PinnedDirectory.verify(workspace_pin)


def _sealed_phase_one_reusable_snapshots(
    writer: EvidenceWriter,
    phase_one: _RegisteredActualPreparedPhase,
    *,
    control_pin: PinnedDirectory,
    trace_id: str,
) -> tuple[WorkspaceSnapshot, ...]:
    """Derive phase-two content reuse solely from phase one's sealed graph.

    The prepared-phase snapshot handles are convenient capture-time objects,
    not provenance on their own: the marker collection is mutable and can be
    replaced after phase one.  The only reusable views are the canonical
    initial artifact and the exact native-row snapshot IDs in the indexed
    execution trace.  This helper reads every byte through the retained
    private control root before phase two is allowed to write anything.
    """

    execution_id = "execution-1"
    expected_initial_id = _workspace_snapshot_artifact_id(
        execution_id, "initial", 0,
    )
    if (type(phase_one) is not _RegisteredActualPreparedPhase
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id
            or phase_one.control_pin is not control_pin
            or phase_one.trace.control_pin is not control_pin
            or phase_one.trace.control_root != control_pin.path
            or phase_one.trace.path != control_pin.path / "runner-trace-execution-1.jsonl"
            or phase_one.trace.lock_path != control_pin.path / ".runner-trace.lock"
            or type(trace_id) is not str or trace_id != "trace-execution-1"
            or phase_one.initial_workspace_snapshot.artifact_id != expected_initial_id
            or type(phase_one.marker_workspace_snapshots) is not list):
        raise RunnerError("registered actual phase-one snapshot reuse is invalid")
    PinnedDirectory.verify(control_pin)
    initial = _indexed_workspace_snapshot(
        writer,
        WorkspaceSnapshot(
            execution_id="", trace_sequence=0, inventory=(), staged_paths=(),
            artifact_id=expected_initial_id,
        ),
        control_pin=control_pin,
    )
    if (initial.execution_id != execution_id
            or initial.role != "initial" or initial.trace_sequence != 0):
        raise RunnerError("registered actual phase-one initial snapshot is invalid")
    trace_value = _strict_json(
        _writer_artifact_bytes(
            writer, trace_id, "execution_trace", control_pin=control_pin,
        ),
        label="registered actual phase-one indexed trace",
    )
    if (type(trace_value) is not dict
            or set(trace_value) != {"schema_version", "run_id", "execution_id", "records"}
            or trace_value.get("schema_version") != 1
            or trace_value.get("run_id") != writer.run_id
            or trace_value.get("execution_id") != execution_id
            or type(trace_value.get("records")) is not list):
        raise RunnerError("registered actual phase-one indexed trace is invalid")
    trace_rows = trace_value["records"]
    validate_trace_records(trace_rows)
    native_rows = [row for row in trace_rows if row.get("kind") == "native_record"]
    if not native_rows:
        raise RunnerError("registered actual phase-one indexed trace is incomplete")
    markers = tuple(
        _indexed_trace_workspace_snapshot(
            writer,
            execution_id=execution_id,
            native_row=row,
            control_pin=control_pin,
        )
        for row in native_rows
    )
    marker_ids = tuple(snapshot.artifact_id for snapshot in markers)
    retained_marker_ids: list[str] = []
    for snapshot in phase_one.marker_workspace_snapshots:
        if not isinstance(snapshot, WorkspaceSnapshot):
            raise RunnerError("registered actual phase-one snapshot reuse is invalid")
        retained_marker_ids.append(snapshot.artifact_id)
    if (len(marker_ids) != len(set(marker_ids))
            or tuple(retained_marker_ids) != marker_ids):
        raise RunnerError("registered actual phase-one marker snapshots are not trace-owned")
    return (initial, *markers)


def _registered_actual_phase_two_pretransition_is_open(
    writer: EvidenceWriter,
    *,
    control_pin: PinnedDirectory,
) -> None:
    """Reject terminal or future-phase residue before phase-two setup writes.

    ``EvidenceWriter.seal()`` is intentionally usable by incomplete
    diagnostics, so its existence alone cannot be treated as a phase-two
    permission.  This private constructor instead requires the pretransition
    writer namespace to remain open and phase-one-only.  A later dispatcher
    may choose a different terminal lifecycle, but it must not append to a
    sealed phase-one diagnostic through this setup seam.
    """

    if (not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id):
        raise RunnerError("registered actual phase-two transition roots are invalid")
    run_relative = PurePosixPath("runs", writer.run_id).as_posix()
    directories, files = _pinned_control_tree_inventory(control_pin, run_relative)
    terminal_files = {
        "evidence-index.json", "log-attestation.json", "event-log.json", "run-manifest.json",
    }
    if terminal_files & set(files):
        raise RunnerError("registered actual phase-two transition is already sealed")
    PinnedDirectory.verify(control_pin)
    try:
        trace_names = [
            name for name in os.listdir(control_pin.root_fd)
            if name.startswith("runner-trace-")
        ]
    except OSError as error:
        raise RunnerError("registered actual phase-two trace namespace is unavailable") from error
    if set(trace_names) != {"runner-trace-execution-1.jsonl"}:
        raise RunnerError("registered actual phase-two trace namespace is invalid")

    prefixes = (
        "policy-", "process-", "transcript-", "stderr-", "phase-prompt-", "mcp-",
        "version-", "help-", "client-executable-", "trace-execution-",
        "raw-capture-index-execution-", "raw-command-log-execution-",
        "raw-preapply-manifests-execution-", "workspace-snapshot-execution-",
    )

    def is_future_phase_artifact(artifact_id: str) -> bool:
        for prefix in prefixes:
            if artifact_id.startswith(prefix):
                suffix = artifact_id.removeprefix(prefix).split("-", 1)[0]
                return suffix.isdecimal() and int(suffix) > 1
        return False

    prohibited_types = {
        "marker", "event_record", "interpretation_decision", "approval",
        "fixture_capability", "run_manifest", "assertion",
    }
    prohibited_ids = {
        "web-approval", "fixture-capability", "fixture-descriptor",
        "fixture-static-shell", "fixture-rendered-dom",
    }
    expected_files: set[str] = set()
    expected_directories: set[str] = set()
    for entry in writer.entries:
        if (type(entry) is not dict or set(entry) != {
                "id", "type", "relative_path", "sha256", "bytes",
        }):
            raise RunnerError("registered actual phase-two transition evidence is invalid")
        artifact_id = entry["id"]
        artifact_type = entry["type"]
        relative = entry["relative_path"]
        if (type(artifact_id) is not str or not artifact_id
                or type(artifact_type) is not str
                or type(relative) is not str
                or not _is_hex64(entry["sha256"])
                or type(entry["bytes"]) is not int or entry["bytes"] < 0):
            raise RunnerError("registered actual phase-two transition evidence is invalid")
        path = PurePosixPath(relative)
        if (path.is_absolute() or path.as_posix() != relative or not path.parts
                or any(part in {"", ".", ".."} for part in path.parts)
                or relative in expected_files):
            raise RunnerError("registered actual phase-two transition evidence is invalid")
        expected_files.add(relative)
        expected_directories.update(
            parent.as_posix() for parent in path.parents if parent != PurePosixPath(".")
        )
        if (is_future_phase_artifact(artifact_id)
                or artifact_id in prohibited_ids
                or artifact_type in prohibited_types):
            raise RunnerError("registered actual phase-two transition has future evidence")
    if set(files) != expected_files or set(directories) != expected_directories:
        raise RunnerError("registered actual phase-two transition output inventory is invalid")


def _capture_registered_actual_phase_two_evidence_provenance(
    writer: EvidenceWriter,
    *,
    control_pin: PinnedDirectory,
) -> Mapping[str, _RegisteredActualEvidenceProvenance]:
    """Freeze the setup-time identity of every pre-spawn evidence artifact.

    Writer hashes prove content, but a same-byte ``os.replace`` changes the
    provenance of an otherwise valid-looking phase-one policy or receipt
    artifact.  Retaining descriptor-derived identities after phase-two setup
    lets the final launch guard reject that replacement before process spawn.
    """

    if (not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id):
        raise RunnerError("registered actual phase-two provenance roots are invalid")
    _require_unique_writer_entry_ids(writer)
    receipts = writer.write_identities
    if type(receipts) is not dict:
        raise RunnerError("registered actual phase-two write receipts are invalid")
    captured: dict[str, _RegisteredActualEvidenceProvenance] = {}
    expected_paths: set[str] = set()
    for entry in writer.entries:
        if (type(entry) is not dict or set(entry) != {
                "id", "type", "relative_path", "sha256", "bytes",
        }):
            raise RunnerError("registered actual phase-two provenance is invalid")
        artifact_id = entry["id"]
        artifact_type = entry["type"]
        relative = entry["relative_path"]
        if (type(artifact_id) is not str or not artifact_id
                or type(artifact_type) is not str or not artifact_type
                or type(relative) is not str
                or not _is_hex64(entry["sha256"])
                or type(entry["bytes"]) is not int or entry["bytes"] < 0):
            raise RunnerError("registered actual phase-two provenance is invalid")
        path = PurePosixPath(relative)
        if (path.is_absolute() or path.as_posix() != relative or not path.parts
                or any(part in {"", ".", ".."} for part in path.parts)
                or relative in expected_paths):
            raise RunnerError("registered actual phase-two provenance is invalid")
        expected_paths.add(relative)
        raw = _writer_artifact_bytes(
            writer, artifact_id, artifact_type, control_pin=control_pin,
        )
        retained, identity = PinnedDirectory.snapshot_relative(control_pin,
            PurePosixPath("runs", writer.run_id, *path.parts).as_posix(),
        )
        if retained != raw or receipts.get(relative) != identity:
            raise RunnerError("registered actual phase-two provenance changed while captured")
        captured[artifact_id] = (
            artifact_type, relative, entry["sha256"], entry["bytes"], identity,
        )
    if not captured or set(receipts) != expected_paths:
        raise RunnerError("registered actual phase-two provenance is empty")
    return MappingProxyType(captured)


def _verify_registered_actual_phase_two_expected_evidence_provenance(
    writer: EvidenceWriter,
    *,
    control_pin: PinnedDirectory,
    expected: Mapping[str, _RegisteredActualEvidenceProvenance],
) -> None:
    """Require setup evidence to retain the caller's original descriptors.

    A phase-two token's provenance map is itself mutable Python state at a
    hostile helper seam.  Refreshing the tree against this independently
    retained map, plus the writer's producer-fd receipts, prevents a
    same-byte replacement from being adopted as a new launch baseline.
    """

    if not isinstance(expected, Mapping) or not expected:
        raise RunnerError("registered actual phase-two expected provenance is invalid")
    current = _capture_registered_actual_phase_two_evidence_provenance(
        writer, control_pin=control_pin,
    )
    # Pre-Popen probes legitimately append version/help rows after the setup
    # baseline.  This helper anchors every retained setup row; the caller's
    # exact launch-tree inventory check separately constrains that permitted
    # live delta.
    if any(current.get(artifact_id) != record for artifact_id, record in expected.items()):
        raise RunnerError("registered actual phase-two setup provenance changed")


def _revalidate_registered_actual_phase_two_setup_authority(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    *,
    authority: _RegisteredActualAuthority,
    plan: RegisteredActualScenarioPlan,
    metadata: _RegisteredActualScenarioFixtureMetadata,
    writer: EvidenceWriter,
    prepared: PreparedWorkspace,
    phase_one: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
) -> dict[str, Any]:
    """Rebind the closed setup route before another phase-two side effect.

    Setup crosses several private helpers that can read retained host state.
    Each continuation must retain the original pinned roots and Claude-only
    plan before it writes its next control or evidence file; checking only at
    the constructor entry would let a mutated retained object redirect a
    later write beneath an otherwise valid phase-one diagnostic.
    """

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or type(metadata) is not _RegisteredActualScenarioFixtureMetadata
            or type(writer) is not EvidenceWriter
            or type(prepared) is not PreparedWorkspace
            or type(phase_one) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase
            or type(phase_one.trace) is not ControlTraceWriter
            or prepared_run.authority is not authority
            or authority.plan is not plan
            or prepared_run.prepared is not prepared
            or prepared_run.writer is not writer
            or prepared_run.metadata is not metadata
            or phase_one_diagnostic.prepared_phase is not phase_one
            or phase_one_diagnostic.live_phase is not live_phase
            or not isinstance(prepared.control_pin, PinnedDirectory)
            or not isinstance(prepared.workspace_pin, PinnedDirectory)
            or not prepared.control_pin.private
            or prepared.workspace_pin.private
            or prepared.control_root != prepared.control_pin.path
            or prepared.workspace != prepared.workspace_pin.path
            or writer.control_root != prepared.control_pin.path
            or writer.run_id != prepared_run.run_id
            or writer.run_root != prepared.control_pin.path / "runs" / writer.run_id
            or phase_one.prepared_run is not prepared_run
            or phase_one.authority is not authority
            or phase_one.writer is not writer
            or phase_one.execution_id != "execution-1"
            or phase_one.phase_index != 1
            or phase_one.phase != "approval"
            or phase_one.workspace != prepared.workspace
            or phase_one.control_pin is not prepared.control_pin
            or phase_one.workspace_pin is not prepared.workspace_pin
            or phase_one.trace.control_root != prepared.control_pin.path
            or phase_one.trace.control_pin is not prepared.control_pin
            or phase_one.trace.path != prepared.control_pin.path / "runner-trace-execution-1.jsonl"
            or phase_one.trace.lock_path != prepared.control_pin.path / ".runner-trace.lock"
            or live_phase.control_pin is not prepared.control_pin
            or live_phase.workspace_pin is not prepared.workspace_pin):
        raise RunnerError("registered actual phase-two binding is invalid")
    _verify_registered_phase_roots(
        writer=writer,
        workspace=prepared.workspace,
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        trace=phase_one.trace,
    )
    if _registered_actual_scenario_fixture_metadata(prepared_run, plan) is not metadata:
        raise RunnerError("registered actual phase-two binding is invalid")
    scenario = metadata.scenario()
    phases = phase_plan(metadata.scenario_id)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    registration = _runner_owned_registration(plan.client)
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phases != ("approval", "approved_capture")
            or plan.registration is not registration
            or plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or metadata.scenario_id != plan.scenario_id):
        raise RunnerError("registered actual phase-two binding is invalid")
    return scenario


def _revalidate_registered_actual_phase_two_setup_continuation(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    *,
    authority: _RegisteredActualAuthority,
    plan: RegisteredActualScenarioPlan,
    metadata: _RegisteredActualScenarioFixtureMetadata,
    writer: EvidenceWriter,
    prepared: PreparedWorkspace,
    phase_one: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    phase_one_evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
    phase_one_raw_predecessor_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot,
    phase_control: PhaseControlSeals,
    runner_state: ControlFileSeal | None = None,
    mcp_config: ControlFileSeal | None = None,
    phase_prompt: PhasePromptEvidence | None = None,
    trace: ControlTraceWriter | None = None,
    initial_workspace_snapshot: WorkspaceSnapshot | None = None,
) -> dict[str, Any]:
    """Revalidate setup state after a private helper returns, before reuse.

    Phase two intentionally replaces only the phase-one config and runner
    state.  Every surviving phase-one fact, every produced phase-two control,
    and every producer-fd evidence receipt must still bind before the next
    setup write or before a prepared token may escape.
    """

    scenario = _revalidate_registered_actual_phase_two_setup_authority(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
    )
    if (not isinstance(phase_control, PhaseControlSeals)
            or not isinstance(phase_one.phase_control, PhaseControlSeals)
            or not isinstance(phase_one.mcp_config, ControlFileSeal)
            or not isinstance(phase_one.phase_prompt, PhasePromptEvidence)
            or not isinstance(phase_one_evidence_provenance, Mapping)):
        raise RunnerError("registered actual phase-two setup continuation is invalid")
    verify_wrapper(prepared.wrapper_seal)
    _verify_phase_fixture_assets(phase_one.phase_control)
    verify_control_file(phase_one.mcp_config)
    _verify_phase_prompt(phase_one.phase_prompt)
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        phase_one_raw_predecessor_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(prepared.control_pin)
    _registered_actual_phase_one_fixture_metadata_binding(
        phase_one_diagnostic,
        metadata,
    )
    _require_unique_writer_entry_ids(writer)
    current = _capture_registered_actual_phase_two_evidence_provenance(
        writer, control_pin=prepared.control_pin,
    )
    # The capture performs a descriptor walk over mutable runner state.  Bind
    # roots and the closed plan again after it returns, before the caller can
    # use any verified output to make its next setup write.
    scenario = _revalidate_registered_actual_phase_two_setup_authority(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
    )
    if any(
            current.get(artifact_id) != record
            for artifact_id, record in phase_one_evidence_provenance.items()
    ):
        raise RunnerError("registered actual phase-one evidence changed during phase-two setup")
    verify_phase_control(phase_control)
    if runner_state is not None:
        if not isinstance(runner_state, ControlFileSeal):
            raise RunnerError("registered actual phase-two setup continuation is invalid")
        verify_control_file(runner_state)
    if mcp_config is not None:
        if not isinstance(mcp_config, ControlFileSeal):
            raise RunnerError("registered actual phase-two setup continuation is invalid")
        verify_control_file(mcp_config)
        if _safe_read(mcp_config.path) != EMPTY_MCP_BYTES:
            raise RunnerError("runner-owned phase-two MCP bytes changed during setup")
    if phase_prompt is not None:
        if not isinstance(phase_prompt, PhasePromptEvidence):
            raise RunnerError("registered actual phase-two setup continuation is invalid")
        _verify_phase_prompt(phase_prompt)
    if trace is not None:
        if (not isinstance(trace, ControlTraceWriter)
                or trace.control_root != prepared.control_pin.path
                or trace.control_pin is not prepared.control_pin
                or trace.path != prepared.control_pin.path / "runner-trace-execution-2.jsonl"
                or trace.lock_path != prepared.control_pin.path / ".runner-trace.lock"
                or trace.records()):
            raise RunnerError("registered actual phase-two setup trace is invalid")
    if initial_workspace_snapshot is not None:
        if not isinstance(initial_workspace_snapshot, WorkspaceSnapshot):
            raise RunnerError("registered actual phase-two setup snapshot is invalid")
        snapshot = _indexed_workspace_snapshot(
            writer,
            initial_workspace_snapshot,
            control_pin=prepared.control_pin,
        )
        if (snapshot.execution_id != "execution-2"
                or snapshot.role != "initial"
                or snapshot.trace_sequence != 0
                or snapshot.artifact_id != _workspace_snapshot_artifact_id(
                    "execution-2", "initial", 0,
                )):
            raise RunnerError("registered actual phase-two setup snapshot is invalid")
    return scenario


def _revalidate_registered_actual_phase_two_setup_return_closure(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    *,
    authority: _RegisteredActualAuthority,
    plan: RegisteredActualScenarioPlan,
    metadata: _RegisteredActualScenarioFixtureMetadata,
    writer: EvidenceWriter,
    prepared: PreparedWorkspace,
    phase_one: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    phase_one_evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
    phase_one_raw_predecessor_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot,
    phase_two: _RegisteredActualPreparedPhase,
    phase_control: PhaseControlSeals,
    runner_state: ControlFileSeal,
    mcp_config: ControlFileSeal,
    phase_prompt: PhasePromptEvidence,
    trace: ControlTraceWriter,
    initial_workspace_snapshot: WorkspaceSnapshot,
    marker_workspace_snapshots: list[WorkspaceSnapshot],
    on_native_record: Callable[[bytes, int, int, int], str],
    trusted_context: Any,
    sealed_evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
    sealed_initial_workspace_inventory: _RegisteredActualPhaseTwoWorkspaceInventory,
    control_tree_snapshot: Mapping[str, tuple[int, int, int, int, int, int, int, int]],
    launch_binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> None:
    """Make the prepared phase-two return boundary one terminal closure.

    The final launch admissibility gate is necessarily a broad no-write read.
    Its return cannot become the constructor's implicit new baseline: the
    original setup locals, exact run-tree shape, producer-fd receipts, raw
    journals, and phase-two controls must still bind before the token escapes.
    This function is deliberately terminal in ``_prepare...``; callers must
    return immediately after it succeeds rather than reuse any of its reads.
    """

    if (not isinstance(control_tree_snapshot, Mapping)
            or type(launch_binding) is not _RegisteredActualPhaseTwoLaunchBinding):
        raise RunnerError("registered actual phase-two control tree snapshot is invalid")
    _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
        phase_prompt=phase_prompt,
        trace=trace,
        initial_workspace_snapshot=initial_workspace_snapshot,
    )

    def verify_token_locals() -> None:
        if (type(phase_two) is not _RegisteredActualPreparedPhase
                or phase_two.prepared_run is not prepared_run
                or phase_two.authority is not authority
                or phase_two.writer is not writer
                or phase_two.execution_id != "execution-2"
                or phase_two.phase != "approved_capture"
                or phase_two.phase_index != 2
                or phase_two.workspace is not prepared.workspace
                or phase_two.control_pin is not prepared.control_pin
                or phase_two.workspace_pin is not prepared.workspace_pin
                or phase_two.phase_control is not phase_control
                or phase_two.runner_state is not runner_state
                or phase_two.mcp_config is not mcp_config
                or phase_two.phase_prompt is not phase_prompt
                or phase_two.trace is not trace
                or phase_two.transcript_id != "transcript-2"
                or phase_two.initial_workspace_snapshot is not initial_workspace_snapshot
                or phase_two.marker_workspace_snapshots is not marker_workspace_snapshots
                or marker_workspace_snapshots
                or phase_two.on_native_record is not on_native_record
                or phase_two.trusted_context is not trusted_context
                or phase_two.phase_one_raw_predecessor_snapshot
                != phase_one_raw_predecessor_snapshot
                or phase_two.sealed_evidence_provenance
                != sealed_evidence_provenance
                or phase_two.sealed_initial_workspace_inventory
                != sealed_initial_workspace_inventory):
            raise RunnerError("registered actual phase-two retained setup state changed")

    # Bind the just-built aggregate to the locals retained across setup before
    # any of the remaining closure readers consume it.
    verify_token_locals()
    _verify_registered_actual_phase_two_expected_evidence_provenance(
        writer,
        control_pin=prepared.control_pin,
        expected=sealed_evidence_provenance,
    )
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        phase_one_raw_predecessor_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(prepared.control_pin)
    verify_wrapper(prepared.wrapper_seal)
    verify_phase_control(phase_control)
    verify_control_file(runner_state)
    verify_control_file(mcp_config)
    if _safe_read(mcp_config.path) != EMPTY_MCP_BYTES:
        raise RunnerError("runner-owned phase-two MCP bytes changed during setup")
    _verify_phase_prompt(phase_prompt)
    if (trace.control_root != prepared.control_pin.path
            or trace.control_pin is not prepared.control_pin
            or trace.path != prepared.control_pin.path / "runner-trace-execution-2.jsonl"
            or trace.lock_path != prepared.control_pin.path / ".runner-trace.lock"
            or trace.records()):
        raise RunnerError("registered actual phase-two setup trace is invalid")
    # Establish the exact semantic run-tree inventory before extracting the
    # detached workspace expectation below.  The subsequent whole-control
    # replay catches any run-tree residue that this or a later reader leaves.
    verify_token_locals()
    _revalidate_registered_actual_phase_two_setup_authority(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
    )
    _registered_actual_phase_two_launch_tree_is_open(phase_two, pre_popen=False)
    # The semantic run-tree check intentionally reads only the state that is
    # admissible for launch.  Reverify the frozen *whole* control tree after
    # it so same-byte replacements of root controls, raw journals, fixture
    # assets, or private ledgers made by any preceding reader cannot escape
    # merely because they are outside ``runs/<id>``.
    PinnedDirectory.reverify_tree(prepared.control_pin, control_tree_snapshot)
    # The expected tuple was detached from indexed snapshot evidence before
    # the token and whole-control-tree baseline were built.  This is the last
    # filesystem read before the local-only token comparison.
    _verify_registered_actual_phase_two_workspace_inventory_is_current(
        prepared.workspace_pin,
        sealed_initial_workspace_inventory,
    )
    # This local-only check completes the terminal closure by rejecting a
    # tree-reader seam that replaced a retained token field itself.
    verify_token_locals()
    # The detached launch binding also retains copied fixture bytes and the
    # root static tree.  It must be the final reader in this closure: a token
    # field or nested fixture-map substitution cannot become the baseline
    # that is registered immediately before the return below.
    launch_binding.assert_current(phase_two, trace_receipt_sink=None)


@dataclass
class _RegisteredActualPhaseTwoLiveIdentityTracker:
    """Retain live phase-two identities before a later token can observe them.

    A post-launch token alone cannot distinguish an artifact written by the
    live process from a same-byte replacement made while that process is
    still draining or waiting.  This private tracker checkpoints the pinned
    control tree at each production boundary and only admits the exact next
    class of runner-owned artifact.
    """

    prepared_phase: _RegisteredActualPreparedPhase
    launch_binding: _RegisteredActualPhaseTwoLaunchBinding
    artifact_provenance: Mapping[str, _RegisteredActualEvidenceProvenance] = field(
        default_factory=dict,
    )
    trace_snapshot: _ControlTraceSnapshot | None = None
    receipt_ledgers: _RegisteredActualPhaseTwoReceiptLedgers | None = None
    _stage: str = field(default="new", init=False)
    _trace_receipt_sink: _PrivateReceiptLedgerSink | None = field(
        default=None, init=False, repr=False,
    )
    _pending_native_trace: _ControlTraceSnapshot | None = field(
        default=None, init=False, repr=False,
    )

    def __post_init__(self) -> None:
        phase = self.prepared_phase
        binding = self.launch_binding
        if (type(phase) is not _RegisteredActualPreparedPhase
                or type(binding) is not _RegisteredActualPhaseTwoLaunchBinding
                or phase.execution_id != "execution-2"
                or phase.phase_index != 2
                or phase.phase != "approved_capture"
                or not isinstance(phase.control_pin, PinnedDirectory)
                or not phase.control_pin.private
                or phase.control_pin.path != phase.writer.control_root.resolve()
                or phase.writer.run_root != (
                    phase.control_pin.path / "runs" / phase.writer.run_id
                )
                or binding.trace.control_pin is not binding.control_pin
                or binding.trace.path != (
                    binding.control_pin.path / "runner-trace-execution-2.jsonl"
                )):
            raise RunnerError("registered actual phase-two live identity tracker is invalid")
        binding.assert_current(phase, trace_receipt_sink=None)
        PinnedDirectory.verify(binding.control_pin)

    def arm_private_receipt_ledgers(
        self,
        ledgers: _RegisteredActualPhaseTwoReceiptLedgers,
        *,
        trace_receipt_sink: _PrivateReceiptLedgerSink,
    ) -> None:
        """Switch the live tracker to ledger-backed trace retention at Popen."""

        if (type(ledgers) is not _RegisteredActualPhaseTwoReceiptLedgers
                or type(trace_receipt_sink) is not _PrivateReceiptLedgerSink
                or self.receipt_ledgers is not None
                or self._stage != "help"
                or self.trace_snapshot is not None):
            raise RunnerError("registered actual phase-two receipt tracker is invalid")
        verified = _verify_registered_actual_phase_two_receipt_ledgers(
            self.prepared_phase, ledgers, control_pin=self._control_pin,
        )
        if verified.trace_snapshot is not None:
            raise RunnerError("registered actual phase-two receipt trace is premature")
        self.launch_binding.assert_current(
            self.prepared_phase,
            receipt_ledgers=ledgers,
            trace_receipt_sink=trace_receipt_sink,
        )
        self.receipt_ledgers = ledgers
        self._trace_receipt_sink = trace_receipt_sink

    @property
    def _writer(self) -> EvidenceWriter:
        return self.launch_binding.writer

    @property
    def _control_pin(self) -> PinnedDirectory:
        return self.launch_binding.control_pin

    @property
    def _trace(self) -> ControlTraceWriter:
        return self.launch_binding.trace

    def _assert_bound_token(self, *, allow_marker_snapshots: bool) -> None:
        """Keep post-Popen callbacks on original objects, not token fields."""

        self.launch_binding._assert_token_fields(
            self.prepared_phase,
            trace_receipt_sink=(
                self._trace_receipt_sink
                if self.receipt_ledgers is not None else None
            ),
            allow_marker_snapshots=allow_marker_snapshots,
        )

    def _verify_writer_write_receipts(
        self,
        provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
    ) -> None:
        """Require every artifact to retain its producer-fd identity.

        The pinned capture below proves the file we can read *now*.  The
        writer receipt is the complementary fact that it is still the file
        which the runner created, rather than a same-byte replacement placed
        after the exclusive write returned and before this checkpoint began.
        """

        receipts = self._writer.write_identities
        if type(receipts) is not dict:
            raise RunnerError("registered actual phase-two write receipts are invalid")
        expected_paths: set[str] = set()
        for artifact_id, record in provenance.items():
            if type(artifact_id) is not str or type(record) is not tuple or len(record) != 5:
                raise RunnerError("registered actual phase-two write receipts are invalid")
            relative = record[1]
            identity = record[4]
            if (type(relative) is not str or relative in expected_paths
                    or type(identity) is not tuple or len(identity) != 8
                    or any(type(value) is not int for value in identity)
                    or receipts.get(relative) != identity):
                raise RunnerError("registered actual phase-two live evidence changed")
            expected_paths.add(relative)
        if set(receipts) != expected_paths:
            raise RunnerError("registered actual phase-two write receipts are invalid")

    def _current_trace_snapshot(
        self,
    ) -> _ControlTraceSnapshot | None:
        try:
            return PinnedDirectory.snapshot_relative(self._control_pin, self._trace.path.name)
        except RunnerError:
            if _pinned_control_capture_is_absent(
                    self._control_pin, self._trace.path.name,
            ):
                return None
            raise

    def trace_append_expectation(self) -> _ControlTraceSnapshot | None:
        """Return the exact trace predecessor for one locked native append."""

        if self._stage not in {"help", "native_record", "native_snapshot"}:
            raise RunnerError("registered actual phase-two trace transition is invalid")
        self._assert_bound_token(
            allow_marker_snapshots=self._stage in {"native_record", "native_snapshot"},
        )
        # This is called once before marker capture and again while the trace
        # lock remains held after the snapshot checkpoint.  Both calls verify
        # the retained predecessor, so the writer can require that exact
        # identity rather than re-discovering a path-selected trace.
        self._reverify_retained()
        return self.trace_snapshot

    def accept_native_trace_append(self, receipt: _ControlTraceSnapshot) -> None:
        """Adopt only the writer's just-produced, pinned trace receipt."""

        receipt = _validated_control_trace_snapshot(receipt)
        if receipt is None or self._stage != "native_snapshot" or self._pending_native_trace is not None:
            raise RunnerError("registered actual phase-two trace transition is invalid")
        self._assert_bound_token(allow_marker_snapshots=True)
        if self.receipt_ledgers is not None:
            verified = _verify_registered_actual_phase_two_receipt_ledgers(
                self.prepared_phase, self.receipt_ledgers, control_pin=self._control_pin,
            )
            if verified.trace_snapshot != receipt:
                raise RunnerError("registered actual phase-two trace receipt is invalid")
        # This call runs directly from ControlTraceWriter while it still holds
        # the shared trace lock.  Re-read through the private pin before
        # retaining anything, so a replacement after its producer fd closed
        # cannot become this checkpoint's new baseline.
        PinnedDirectory.reverify_snapshot(
            self._control_pin, self._trace.path.name, receipt,
        )
        prior = self.trace_snapshot
        raw, identity = receipt
        prior_rows: list[dict[str, Any]] = []
        if prior is not None:
            prior_raw, prior_identity = prior
            if (not raw.startswith(prior_raw)
                    or identity[:5] != prior_identity[:5]):
                raise RunnerError("registered actual phase-two trace append is invalid")
            prior_rows = [
                _strict_json(line, label="registered actual phase-two trace")
                for line in prior_raw.splitlines()
            ]
        rows = [
            _strict_json(line, label="registered actual phase-two trace")
            for line in raw.splitlines()
        ]
        if (len(rows) != len(prior_rows) + 1
                or not rows
                or rows[-1].get("kind") != "native_record"):
            raise RunnerError("registered actual phase-two trace append is invalid")
        validate_trace_records(rows, complete=False)
        self._pending_native_trace = receipt
        self.checkpoint("native_record")

    def _reverify_retained(
        self,
        *,
        allow_new_trace: bool = False,
        allow_marker_snapshots: bool | None = None,
    ) -> None:
        if allow_marker_snapshots is None:
            allow_marker_snapshots = self._stage not in {
                "new", "initial", "version", "help",
            }
        self._assert_bound_token(allow_marker_snapshots=allow_marker_snapshots)
        if self._stage == "new":
            return
        receipt_ledgers = self.receipt_ledgers
        if receipt_ledgers is not None:
            # A child shim may append valid command rows between parent
            # checkpoints.  Its retained ledger chain—not a fresh path read—
            # is the only authority allowed to advance this trace baseline.
            self.trace_snapshot = _verify_registered_actual_phase_two_receipt_ledgers(
                self.prepared_phase, receipt_ledgers, control_pin=self._control_pin,
            ).trace_snapshot
        entries = _writer_entry_map(self._writer)
        _require_unique_writer_entry_ids(self._writer)
        # The next checkpoint deliberately observes newly-created evidence;
        # only previously retained entries must already be present here.  The
        # exact permitted delta is checked by ``_validate_new_artifacts``
        # after its descriptor-backed provenance is captured.
        if not set(self.artifact_provenance).issubset(entries):
            raise RunnerError("registered actual phase-two live evidence inventory changed")
        for artifact_id, record in self.artifact_provenance.items():
            artifact_type, relative, digest, byte_count, identity = record
            entry = entries.get(artifact_id)
            if (not isinstance(entry, Mapping)
                    or (entry.get("type"), entry.get("relative_path"), entry.get("sha256"), entry.get("bytes"))
                    != (artifact_type, relative, digest, byte_count)):
                raise RunnerError("registered actual phase-two live evidence changed")
            raw = _writer_artifact_bytes(
                self._writer,
                artifact_id,
                artifact_type,
                control_pin=self._control_pin,
            )
            retained, observed_identity = PinnedDirectory.snapshot_relative(self._control_pin,
                PurePosixPath("runs", self._writer.run_id, *PurePosixPath(relative).parts).as_posix(),
            )
            if retained != raw or observed_identity != identity:
                raise RunnerError("registered actual phase-two live evidence changed")
        if receipt_ledgers is not None:
            return
        if self.trace_snapshot is None:
            if (not allow_new_trace
                    and not _pinned_control_capture_is_absent(
                    self._control_pin, self._trace.path.name,
            )):
                raise RunnerError("registered actual phase-two live trace changed")
        elif not allow_new_trace:
            PinnedDirectory.reverify_snapshot(
                self._control_pin, self._trace.path.name, self.trace_snapshot,
            )

    @staticmethod
    def _record_is(
        provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
        artifact_id: str,
        artifact_type: str,
        relative: str,
    ) -> bool:
        record = provenance.get(artifact_id)
        return bool(record is not None and record[:2] == (artifact_type, relative))

    def _validate_new_artifacts(
        self,
        stage: str,
        current: Mapping[str, _RegisteredActualEvidenceProvenance],
    ) -> None:
        prior_ids = set(self.artifact_provenance)
        new_ids = set(current) - prior_ids
        if self._stage == "new":
            if stage != "initial" or any(
                    artifact_id in current
                    for artifact_id in ("version-2", "help-2", "client-executable-2")
            ):
                raise RunnerError("registered actual phase-two live identity order is invalid")
            return
        if stage == "version":
            if (self._stage != "initial"
                    or new_ids != {"version-2"}
                    or not self._record_is(
                        current, "version-2", "version", "artifacts/version-2.bin",
                    )):
                raise RunnerError("registered actual phase-two version provenance is invalid")
            return
        if stage == "help":
            if (self._stage != "version"
                    or new_ids != {"help-2"}
                    or not self._record_is(
                        current, "help-2", "help", "artifacts/help-2.bin",
                    )):
                raise RunnerError("registered actual phase-two help provenance is invalid")
            return
        if stage == "native_snapshot":
            if self._stage not in {"help", "native_record"} or not new_ids:
                raise RunnerError("registered actual phase-two snapshot provenance is invalid")
            markers = []
            for artifact_id in new_ids:
                record = current[artifact_id]
                artifact_type, relative, digest, byte_count, _identity = record
                if artifact_id.startswith("workspace-snapshot-execution-2-marker-"):
                    sequence = artifact_id.removeprefix(
                        "workspace-snapshot-execution-2-marker-",
                    )
                    if (not sequence.isdecimal() or int(sequence) <= 0
                            or artifact_type != "workspace_snapshot"
                            or relative != "artifacts/" + artifact_id + ".json"):
                        raise RunnerError("registered actual phase-two snapshot provenance is invalid")
                    markers.append(artifact_id)
                elif artifact_id.startswith("workspace-content-"):
                    content_digest = artifact_id.removeprefix("workspace-content-")
                    if (not _is_hex64(content_digest)
                            or artifact_type != "file_capture"
                            or relative != "artifacts/" + artifact_id + ".bin"
                            or digest != content_digest
                            or type(byte_count) is not int or byte_count < 0):
                        raise RunnerError("registered actual phase-two snapshot content is invalid")
                else:
                    raise RunnerError("registered actual phase-two snapshot provenance is invalid")
            if len(markers) != 1:
                raise RunnerError("registered actual phase-two snapshot provenance is invalid")
            return
        if stage == "native_record":
            if self._stage != "native_snapshot" or new_ids:
                raise RunnerError("registered actual phase-two trace provenance is invalid")
            return
        if stage == "stream":
            if self._stage not in {"help", "native_record"} or new_ids:
                raise RunnerError("registered actual phase-two stream provenance is invalid")
            return
        if stage == "client_executable":
            if (self._stage != "stream"
                    or new_ids != {"client-executable-2"}
                    or not self._record_is(
                        current,
                        "client-executable-2",
                        "client_executable",
                        "artifacts/client-executable-2.json",
                    )):
                raise RunnerError("registered actual phase-two executable provenance is invalid")
            return
        raise RunnerError("registered actual phase-two live identity checkpoint is invalid")

    def _validate_trace_transition(
        self,
        stage: str,
        current: _ControlTraceSnapshot | None,
    ) -> None:
        prior = self.trace_snapshot
        if stage in {"initial", "version", "help"}:
            if current is not None:
                raise RunnerError("registered actual phase-two live trace is premature")
            return
        if stage == "native_snapshot":
            if current != prior:
                raise RunnerError("registered actual phase-two live trace changed before append")
            return
        if stage == "native_record":
            if current is None or current != self._pending_native_trace:
                raise RunnerError("registered actual phase-two live trace append is invalid")
            return
        if stage in {"stream", "client_executable"}:
            if current != prior:
                raise RunnerError("registered actual phase-two live trace changed")
            return
        raise RunnerError("registered actual phase-two live trace checkpoint is invalid")

    def checkpoint(self, stage: str) -> None:
        """Verify every prior identity, then admit exactly one next artifact step."""

        if type(stage) is not str:
            raise RunnerError("registered actual phase-two live identity checkpoint is invalid")
        self._assert_bound_token(allow_marker_snapshots=stage in {
            "native_snapshot", "native_record", "stream", "client_executable",
        })
        if (stage == "native_record") != (self._pending_native_trace is not None):
            raise RunnerError("registered actual phase-two trace transition is invalid")
        self._reverify_retained(
            allow_new_trace=stage == "native_record",
            allow_marker_snapshots=stage in {
                "native_snapshot", "native_record", "stream", "client_executable",
            },
        )
        current = _capture_registered_actual_phase_two_evidence_provenance(
            self._writer, control_pin=self._control_pin,
        )
        self._verify_writer_write_receipts(current)
        # Do not let the second descriptor walk silently rebaseline a
        # same-byte replacement that landed after ``_reverify_retained``.
        # New IDs are admitted below; every prior record, including its
        # exact file identity, must remain the retained one.
        if (self._stage != "new"
                and any(current.get(artifact_id) != record
                        for artifact_id, record in self.artifact_provenance.items())):
            raise RunnerError("registered actual phase-two live evidence changed")
        trace = (
            self.trace_snapshot if self.receipt_ledgers is not None
            else self._current_trace_snapshot()
        )
        self._validate_new_artifacts(stage, current)
        self._validate_trace_transition(stage, trace)
        self.artifact_provenance = current
        self.trace_snapshot = trace
        self._stage = stage
        if stage == "native_record":
            self._pending_native_trace = None

    def finalize(self) -> None:
        if self._stage != "client_executable":
            raise RunnerError("registered actual phase-two live identity is incomplete")
        if self._pending_native_trace is not None:
            raise RunnerError("registered actual phase-two trace transition is incomplete")
        self._assert_bound_token(allow_marker_snapshots=True)
        self._reverify_retained()


def _registered_actual_phase_two_marker_snapshot_callback(
    snapshotter: WorkspaceSnapshotter,
    marker_workspace_snapshots: list[WorkspaceSnapshot],
) -> Callable[[bytes, int, int, int], str]:
    """Create the non-token marker capture closure used by private launch.

    The returned callback closes over the snapshotter only in the private
    registry binding.  The caller-visible prepared token receives a distinct
    inert callable, so changing its function code or closure cannot redirect
    marker-time capture after Popen.
    """

    if type(snapshotter) is not WorkspaceSnapshotter or type(marker_workspace_snapshots) is not list:
        raise RunnerError("registered actual phase-two marker callback is invalid")

    def capture_marker_snapshot(
        raw: bytes,
        byte_start: int,
        byte_end: int,
        sequence: int,
    ) -> str:
        if (type(raw) is not bytes
                or type(byte_start) is not int or byte_start < 0
                or type(byte_end) is not int or byte_end < byte_start
                or byte_end - byte_start != len(raw)
                or type(sequence) is not int or sequence <= 0):
            raise RunnerError("actual phase-two marker snapshot input invalid")
        snapshot = snapshotter.capture(
            execution_id="execution-2",
            trace_sequence=sequence,
            role="marker",
            native_record={
                "transcript_id": "transcript-2",
                "byte_start": byte_start,
                "byte_end": byte_end,
                "sha256": _sha256(raw),
            },
        )
        marker_workspace_snapshots.append(snapshot)
        return snapshot.artifact_id

    return capture_marker_snapshot


def _registered_actual_phase_two_token_marker_callback(
    _raw: bytes,
    _byte_start: int,
    _byte_end: int,
    _sequence: int,
) -> str:
    """Keep a shaped but intentionally non-authoritative token callback."""

    raise RunnerError("registered actual phase-two token callback is not launch authority")


def _prepare_registered_actual_phase_one(
    prepared_run: _RegisteredActualPreparedRun,
) -> _RegisteredActualPreparedPhase:
    """Seal only the generated first phase of one disconnected actual run.

    This deliberately performs no executable preparation, probe, process
    creation, semantic conversion, log finalization, or phase-two activation.
    It is a concrete phase-one-only constructor; a separate reviewed authority
    would be required before any phase-two web capture can be prepared.
    """

    if type(prepared_run) is not _RegisteredActualPreparedRun:
        raise RunnerError("registered actual prepared run is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual phase")
    # Recheck the shallow-frozen container and all authority closure before
    # writing even the first control file.  A direct Python replacement of a
    # retained plan or root cannot acquire setup authority.
    prepared_run.__post_init__()
    authority = prepared_run.authority
    plan = authority.plan
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or type(plan.client) is not str
            or type(plan.scenario_id) is not str
            or plan.scratch_root is not None and not isinstance(plan.scratch_root, Path)):
        raise RunnerError("registered actual prepared run is invalid")
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    registration = _runner_owned_registration(plan.client)
    if (plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or plan.registration is not registration):
        raise RunnerError("registered actual plan is no longer runner-owned")
    prepared = prepared_run.prepared
    writer = prepared_run.writer
    if (metadata.scenario_id != plan.scenario_id
            or writer.entries
            or writer.control_root != prepared.control_root
            or writer.run_id != prepared_run.run_id
            or writer.run_root != prepared.control_root / "runs" / prepared_run.run_id):
        raise RunnerError("registered actual prepared run binding is invalid")
    PinnedDirectory.verify(prepared.control_pin)
    PinnedDirectory.verify(prepared.workspace_pin)
    verify_wrapper(prepared.wrapper_seal)
    # Repeat immediately before the first write: a test-only seam installed
    # after run allocation may not leave phase control/prompt evidence behind.
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual phase")

    execution_id = "execution-1"
    phase_index = 1
    phase = phase_plan(metadata.scenario_id)[0]
    snapshotter = WorkspaceSnapshotter(
        workspace=prepared.workspace, workspace_pin=prepared.workspace_pin, writer=writer,
    )
    # This immutable workspace preflight must precede every phase-control or
    # evidence write.  ``capture_fresh_unstaged_initial`` repeats it after
    # setup, so an index introduced between preflight and capture still fails
    # closed without giving the initial snapshot Git/process authority.
    snapshotter._require_fresh_unstaged_initial_workspace()
    phase_control = _phase_control(
        prepared,
        phase=phase,
        approval=_phase_approval(scenario),
        metadata=metadata,
    )
    runner_state = _write_runner_state(
        prepared, run_id=prepared_run.run_id, execution_id=execution_id, phase=phase,
    )
    mcp_config: ControlFileSeal | None = None
    if plan.client == "claude":
        mcp_id = "mcp-1"
        writer.add_bytes(mcp_id, "mcp_config", EMPTY_MCP_BYTES, suffix=".json")
        entry = _writer_entry_map(writer).get(mcp_id)
        if entry is None or entry.get("type") != "mcp_config":
            raise RunnerError("indexed actual MCP config unavailable")
        mcp_path = (writer.run_root / str(entry["relative_path"])).resolve()
        if not mcp_path.is_relative_to(writer.run_root.resolve()):
            raise RunnerError("indexed actual MCP config escaped run root")
        mcp_config = _seal_control_file(mcp_path)
        verify_control_file(mcp_config)
        if _safe_read(mcp_path) != EMPTY_MCP_BYTES:
            raise RunnerError("runner-owned MCP config bytes changed during setup")
    elif plan.client != "codex":
        raise RunnerError("unsupported client")
    phase_prompt = _index_phase_prompt(
        writer,
        scenario=scenario,
        phase=phase,
        phase_index=phase_index,
        client=plan.client,
        raw=_canonical_phase_prompt(scenario, phase),
    )
    transcript_id = "transcript-1"
    trace = ControlTraceWriter(
        prepared.control_root, execution_id, control_pin=prepared.control_pin,
    )
    initial_workspace_snapshot = snapshotter.capture_fresh_unstaged_initial(
        execution_id=execution_id,
    )
    marker_workspace_snapshots: list[WorkspaceSnapshot] = []

    def capture_marker_snapshot(
        raw: bytes,
        byte_start: int,
        byte_end: int,
        sequence: int,
    ) -> str:
        if (type(raw) is not bytes
                or type(byte_start) is not int or byte_start < 0
                or type(byte_end) is not int or byte_end < byte_start
                or byte_end - byte_start != len(raw)
                or type(sequence) is not int or sequence <= 0):
            raise RunnerError("actual phase-one marker snapshot input invalid")
        snapshot = snapshotter.capture(
            execution_id=execution_id,
            trace_sequence=sequence,
            role="marker",
            native_record={
                "transcript_id": transcript_id,
                "byte_start": byte_start,
                "byte_end": byte_end,
                "sha256": _sha256(raw),
            },
        )
        marker_workspace_snapshots.append(snapshot)
        return snapshot.artifact_id

    PinnedDirectory.verify(prepared.control_pin)
    PinnedDirectory.verify(prepared.workspace_pin)
    verify_wrapper(prepared.wrapper_seal)
    verify_phase_control(phase_control)
    verify_control_file(runner_state)
    if mcp_config is not None:
        verify_control_file(mcp_config)
    _verify_phase_prompt(phase_prompt)
    return _RegisteredActualPreparedPhase(
        prepared_run=prepared_run,
        authority=authority,
        writer=writer,
        execution_id=execution_id,
        phase=phase,
        phase_index=phase_index,
        workspace=prepared.workspace,
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        phase_control=phase_control,
        phase_prompt=phase_prompt,
        mcp_config=mcp_config,
        runner_state=runner_state,
        trace=trace,
        transcript_id=transcript_id,
        initial_workspace_snapshot=initial_workspace_snapshot,
        marker_workspace_snapshots=marker_workspace_snapshots,
        on_native_record=capture_marker_snapshot,
        trusted_context=None,
    )


def _prepare_registered_actual_phase_two(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: "PhaseOneReceiptGate",
) -> _RegisteredActualPreparedPhase:
    """Prepare, but never launch, the sealed approved web-capture phase.

    This is deliberately a narrow continuation of the actual-only phase-one
    diagnostic route.  It accepts no client/process/probe/argv/environment
    input, replays the sealed receipt gate before its first phase-two write,
    and leaves semantic projection and pass publication unavailable.  A later
    reviewed launcher may consume the returned aggregate trusted context; this
    constructor itself cannot spawn a client.
    """

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(receipt_gate) is not PhaseOneReceiptGate):
        raise RunnerError("registered actual phase-two inputs are invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual phase")

    authority = prepared_run.authority
    plan = authority.plan
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or phase_one_diagnostic.prepared_phase.prepared_run is not prepared_run
            or phase_one_diagnostic.prepared_phase.authority is not authority
            or phase_one_diagnostic.prepared_phase.writer is not prepared_run.writer):
        raise RunnerError("registered actual phase-two binding is invalid")

    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    phases = phase_plan(metadata.scenario_id)
    registration = _runner_owned_registration(plan.client)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    phase_one = phase_one_diagnostic.prepared_phase
    live_phase = phase_one_diagnostic.live_phase
    writer = prepared_run.writer
    prepared = prepared_run.prepared
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phases != ("approval", "approved_capture")
            or plan.registration is not registration
            or plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or metadata.scenario_id != plan.scenario_id
            or writer.control_root != prepared.control_root
            or writer.run_id != prepared_run.run_id
            or writer.run_root != prepared.control_root / "runs" / prepared_run.run_id
            or phase_one.execution_id != "execution-1"
            or phase_one.phase_index != 1
            or phase_one.phase != "approval"
            or phase_one.workspace != prepared.workspace
            or phase_one.control_pin is not prepared.control_pin
            or phase_one.workspace_pin is not prepared.workspace_pin
            or phase_one.trace.control_root != prepared.control_pin.path
            or phase_one.trace.control_pin is not prepared.control_pin
            or phase_one.trace.path != prepared.control_pin.path / "runner-trace-execution-1.jsonl"
            or phase_one.trace.lock_path != prepared.control_pin.path / ".runner-trace.lock"
            or phase_one.transcript_id != "transcript-1"
            or live_phase.control_pin is not phase_one.control_pin
            or live_phase.workspace_pin is not phase_one.workspace_pin
            or receipt_gate.execution_id != "execution-1"):
        raise RunnerError("registered actual phase-two binding is invalid")

    # The future phase-two journal must begin from the exact files phase one
    # converted, not merely byte-equal replacements installed after its
    # diagnostic stage was adopted.  Check before any phase-two setup write;
    # allocation repeats the join immediately before it creates headers.
    phase_one_diagnostic.raw_predecessors.verify_current(prepared.control_pin)
    phase_one_raw_predecessor_snapshot = (
        _freeze_registered_actual_phase_one_raw_predecessor_snapshot(
            phase_one_diagnostic.raw_predecessors,
        )
    )

    # ``entries`` remains an in-memory list until final sealing.  Do not let
    # a duplicate row change which bytes an indexed reader selects while the
    # phase-two gate is making its first write/no-write decision.
    _require_unique_writer_entry_ids(writer)
    _registered_actual_phase_two_pretransition_is_open(
        writer, control_pin=prepared.control_pin,
    )

    # Bind the retained host launch before reading the receipt gate, then bind
    # it again immediately before deriving phase-two executable trust below.
    # The gate validates receipt/order facts; it is not a substitute for the
    # registered executable, policy, and process join.
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")

    # Revalidate the immutable phase-one receipt from the indexed host facts.
    # A shaped, caller-created token is not sufficient to rewrite control
    # files for phase two.
    reconstructed_gate = _reconstruct_actual_phase_one_receipt_gate(
        writer=writer,
        phase_one=live_phase,
        scenario=scenario,
        conversion=phase_one_diagnostic.conversion,
        workspace=prepared.workspace,
        execution_id="execution-1",
    )
    if not _phase_one_receipt_gate_matches(receipt_gate, reconstructed_gate):
        raise RunnerError("registered actual phase-one receipt gate is no longer valid")

    # All phase-one host facts must still bind before the intentional control
    # rewrite below.  In particular, verify the old config and state while
    # they are still current, then recheck the retained executable immediately
    # before a fresh phase-two executable is prepared.
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    phase_one_registration, phase_one_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-1",
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        trusted_context=live_phase.trusted_context,
        expected_execution_ids=frozenset({"execution-1"}),
    )
    if phase_one_registration is not registration or phase_one_trusted is not live_phase.trusted_executable:
        raise RunnerError("registered actual phase-one context is invalid")
    _registered_executable_observation(phase_one_trusted)
    PinnedDirectory.verify(prepared.control_pin)
    PinnedDirectory.verify(prepared.workspace_pin)
    verify_wrapper(prepared.wrapper_seal)
    verify_phase_control(phase_one.phase_control)
    verify_control_file(phase_one.runner_state)
    if phase_one.mcp_config is None:
        raise RunnerError("registered actual phase-one MCP config is invalid")
    verify_control_file(phase_one.mcp_config)
    _verify_phase_prompt(phase_one.phase_prompt)
    # Record the phase-one artifact identities before phase-two setup makes
    # any write.  The closing setup snapshot below must retain these exact
    # identities, not merely their hashes, before it can become the launch
    # guard's baseline.
    phase_one_evidence_provenance = _capture_registered_actual_phase_two_evidence_provenance(
        writer, control_pin=prepared.control_pin,
    )
    # Compute the one runner-owned approval before the hydration/composite
    # gate sequence.  Calling this helper as an argument immediately after
    # the final receipt match would create an unguarded pre-write seam.
    phase_two_approval = _phase_approval(scenario)
    expected_phase_two_approval = _registered_actual_phase_two_approval()
    if (type(phase_two_approval) is not dict
            or phase_two_approval != expected_phase_two_approval):
        raise RunnerError("registered actual phase-two approval is invalid")
    # Do not retain a mutable alias supplied by the helper across the later
    # receipt/read gates; only this runner-created local copy reaches the
    # phase-control write.
    phase_two_approval = dict(expected_phase_two_approval)

    next_ids = {
        "mcp-2", "phase-prompt-2", "workspace-snapshot-execution-2-initial-0",
    }
    if (next_ids & {entry.get("id") for entry in writer.entries}
            or (prepared.control_root / "runner-trace-execution-2.jsonl").exists()):
        raise RunnerError("registered actual phase-two setup already exists")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare actual phase")
    reusable_phase_one_snapshots = _sealed_phase_one_reusable_snapshots(
        writer,
        phase_one,
        control_pin=prepared.control_pin,
        trace_id=phase_one_diagnostic.trace_id,
    )
    # The returned phase token keeps the public pins for diagnostic shape
    # compatibility, but no phase-two launch authority may share their
    # descriptor fields.  Retain duplicate descriptors before any phase-two
    # setup object can close over them; this preserves the existing verified
    # root baseline instead of reopening a path and adopting a later state.
    private_control_pin = PinnedDirectory.retain(prepared.control_pin)
    private_workspace_pin = PinnedDirectory.retain(prepared.workspace_pin)
    # This read-only hydration is intentionally complete before a phase-two
    # control/state/artifact write.  A malformed or injected phase-one
    # snapshot graph therefore leaves no phase-two setup residue behind.
    snapshotter = WorkspaceSnapshotter(
        workspace=prepared.workspace,
        workspace_pin=prepared.workspace_pin,
        writer=writer,
        control_pin=prepared.control_pin,
        reusable_snapshots=reusable_phase_one_snapshots,
    )

    execution_id = "execution-2"
    phase_index = 2
    phase = "approved_capture"
    # Snapshot hydration above is intentionally read-only, but it is still a
    # mutable in-process seam between the first receipt reconstruction and
    # the phase-two control rewrite below.  First make the reconstruction
    # reader safe, then rebind the whole route after it returns.  This catches
    # a retained-object or same-byte file replacement made by a hydration or
    # reconstruction seam before ``_phase_control`` intentionally replaces
    # phase one's brain-shim config and runner state.
    scenario = _revalidate_registered_actual_phase_two_setup_authority(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
    )
    reconstructed_gate = _reconstruct_actual_phase_one_receipt_gate(
        writer=writer,
        phase_one=live_phase,
        scenario=scenario,
        conversion=phase_one_diagnostic.conversion,
        workspace=prepared.workspace,
        execution_id="execution-1",
    )
    scenario = _revalidate_registered_actual_phase_two_setup_authority(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
    )
    registration = _runner_owned_registration(plan.client)

    # Recheck every phase-one raw and run-tree predecessor after the gate
    # reader, before the first phase-two setup write.  The provenance
    # comparison rejects same-byte replacement of any indexed phase-one
    # artifact; the following control seals cover the non-indexed config and
    # state files about to be replaced.
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        phase_one_raw_predecessor_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(prepared.control_pin)
    _require_unique_writer_entry_ids(writer)
    _registered_actual_phase_two_pretransition_is_open(
        writer, control_pin=prepared.control_pin,
    )
    _registered_actual_phase_one_fixture_metadata_binding(
        phase_one_diagnostic,
        metadata,
    )
    verify_wrapper(prepared.wrapper_seal)
    verify_phase_control(phase_one.phase_control)
    verify_control_file(phase_one.runner_state)
    if phase_one.mcp_config is None:
        raise RunnerError("registered actual phase-one MCP config is invalid")
    verify_control_file(phase_one.mcp_config)
    _verify_phase_prompt(phase_one.phase_prompt)
    if (_capture_registered_actual_phase_two_evidence_provenance(
            writer, control_pin=prepared.control_pin,
    ) != phase_one_evidence_provenance):
        raise RunnerError("registered actual phase-one evidence changed during phase-two setup")
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace_pin.path,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
        control_pin=prepared.control_pin,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    # The token match is the final read-only decision before phase-two setup.
    # A structurally valid caller-token mutation during the composite checks
    # above therefore fails before control replacement or evidence indexing.
    receipt_gate.__post_init__()
    if not _phase_one_receipt_gate_matches(receipt_gate, reconstructed_gate):
        raise RunnerError("registered actual phase-one receipt gate is no longer valid")
    phase_control = _phase_control(
        prepared,
        phase=phase,
        approval=phase_two_approval,
        metadata=metadata,
    )
    # ``_phase_control`` has just made the intentional config replacement,
    # but the old runner state remains phase-one evidence until the next
    # write.  Verify it before continuing, then rebind roots and the new
    # control seal so a helper-return replacement cannot reach state/MCP.
    verify_control_file(phase_one.runner_state)
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
    )
    runner_state = _write_runner_state(
        prepared, run_id=prepared_run.run_id, execution_id=execution_id, phase=phase,
    )
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
    )
    mcp_id = "mcp-2"
    writer.add_bytes(mcp_id, "mcp_config", EMPTY_MCP_BYTES, suffix=".json")
    mcp_entry = _writer_entry_map(writer).get(mcp_id)
    if mcp_entry is None or mcp_entry.get("type") != "mcp_config":
        raise RunnerError("indexed actual phase-two MCP config unavailable")
    mcp_path = (writer.run_root / str(mcp_entry["relative_path"])).resolve()
    if not mcp_path.is_relative_to(writer.run_root.resolve()):
        raise RunnerError("indexed actual phase-two MCP config escaped run root")
    mcp_config = _seal_control_file(mcp_path)
    verify_control_file(mcp_config)
    if _safe_read(mcp_path) != EMPTY_MCP_BYTES:
        raise RunnerError("runner-owned phase-two MCP bytes changed during setup")
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
    )
    phase_prompt = _index_phase_prompt(
        writer,
        scenario=scenario,
        phase=phase,
        phase_index=phase_index,
        client=plan.client,
        raw=_canonical_phase_prompt(scenario, phase),
    )
    trace = ControlTraceWriter(
        prepared.control_root, execution_id, control_pin=prepared.control_pin,
    )
    # Retain a second trace object only in the private launch binding.  Both
    # facades name the same fixed file, but token-side method shadowing cannot
    # affect the object used for receipt arming or live native trace writes.
    private_trace = ControlTraceWriter(
        prepared.control_root, execution_id, control_pin=private_control_pin,
    )
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
        phase_prompt=phase_prompt,
        trace=trace,
    )
    initial_workspace_snapshot = snapshotter.capture(
        execution_id=execution_id, trace_sequence=0,
    )
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
        phase_prompt=phase_prompt,
        trace=trace,
        initial_workspace_snapshot=initial_workspace_snapshot,
    )
    marker_workspace_snapshots: list[WorkspaceSnapshot] = []
    transcript_id = "transcript-2"
    private_snapshotter = WorkspaceSnapshotter(
        workspace=prepared.workspace,
        workspace_pin=private_workspace_pin,
        writer=writer,
        control_pin=private_control_pin,
        reusable_snapshots=(*reusable_phase_one_snapshots, initial_workspace_snapshot),
    )
    private_on_native_record = _registered_actual_phase_two_marker_snapshot_callback(
        private_snapshotter, marker_workspace_snapshots,
    )
    on_native_record = _registered_actual_phase_two_token_marker_callback

    # The config/state rewrite above is intentional.  Revalidate the retained
    # phase-one host evidence and fixture assets before deriving fresh phase-two
    # executable trust, so a same-byte replacement cannot slip between gates.
    PinnedDirectory.verify(prepared.control_pin)
    PinnedDirectory.verify(prepared.workspace_pin)
    _verify_phase_fixture_assets(phase_one.phase_control)
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-1",
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        trusted_context=live_phase.trusted_context,
        expected_execution_ids=frozenset({"execution-1"}),
    )
    _registered_executable_observation(phase_one_trusted)
    _registration, phase_two_trusted = _prepare_registered_live_executable(
        client=plan.client,
        execution_id=execution_id,
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
    )
    if _registration is not registration or phase_two_trusted is phase_one_trusted:
        raise RunnerError("registered actual phase-two executable is invalid")
    trusted_context = _registered_live_trusted_context(
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        trusted_executables={
            "execution-1": phase_one_trusted,
            execution_id: phase_two_trusted,
        },
    )
    _registration, selected_phase_two = _registered_live_context_phase(
        client=plan.client,
        execution_id=execution_id,
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        trusted_context=trusted_context,
        expected_execution_ids=frozenset({"execution-1", execution_id}),
    )
    if _registration is not registration or selected_phase_two is not phase_two_trusted:
        raise RunnerError("registered actual phase-two context is invalid")
    private_trusted_context = _registered_actual_phase_two_private_trusted_context(
        control_pin=private_control_pin,
        workspace_pin=private_workspace_pin,
        phase_one_trusted=phase_one_trusted,
        phase_two_trusted=phase_two_trusted,
    )
    if (private_trusted_context is trusted_context
            or private_trusted_context.trusted_executables.get("execution-1")
            is phase_one_trusted
            or private_trusted_context.trusted_executables.get("execution-2")
            is phase_two_trusted):
        raise RunnerError("registered actual phase-two private context is invalid")
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
        phase_prompt=phase_prompt,
        trace=trace,
        initial_workspace_snapshot=initial_workspace_snapshot,
    )
    sealed_evidence_provenance = _capture_registered_actual_phase_two_evidence_provenance(
        writer, control_pin=prepared.control_pin,
    )
    if any(
            sealed_evidence_provenance.get(artifact_id) != record
            for artifact_id, record in phase_one_evidence_provenance.items()):
        raise RunnerError("registered actual phase-one evidence changed during phase-two setup")
    # The setup capture itself is a return boundary: re-read every retained
    # input after it, rather than allowing a same-byte replacement to become
    # this prepared token's baseline.
    scenario = _revalidate_registered_actual_phase_two_setup_continuation(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
        phase_prompt=phase_prompt,
        trace=trace,
        initial_workspace_snapshot=initial_workspace_snapshot,
    )
    # Retain the phase-two initial content baseline as an immutable primitive.
    # Later launch gates reconcile this local value with the same indexed
    # snapshot evidence; the immediate comparison also rejects workspace drift
    # that occurred while phase-two setup was binding its control inputs.
    sealed_initial_workspace_inventory = (
        _registered_actual_phase_two_initial_workspace_inventory(
            writer,
            control_pin=prepared.control_pin,
            initial_workspace_snapshot=initial_workspace_snapshot,
        )
    )
    _verify_registered_actual_phase_two_workspace_inventory_is_current(
        prepared.workspace_pin,
        sealed_initial_workspace_inventory,
    )
    phase_two = _RegisteredActualPreparedPhase(
        prepared_run=prepared_run,
        authority=authority,
        writer=writer,
        execution_id=execution_id,
        phase=phase,
        phase_index=phase_index,
        workspace=prepared.workspace,
        control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
        phase_control=phase_control,
        phase_prompt=phase_prompt,
        mcp_config=mcp_config,
        runner_state=runner_state,
        trace=trace,
        transcript_id=transcript_id,
        initial_workspace_snapshot=initial_workspace_snapshot,
        marker_workspace_snapshots=marker_workspace_snapshots,
        on_native_record=on_native_record,
        trusted_context=trusted_context,
        sealed_evidence_provenance=sealed_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        sealed_initial_workspace_inventory=sealed_initial_workspace_inventory,
    )
    # Freeze every control-root pathname and identity before any post-build
    # checkpoint or launch-gate reader runs.  The terminal return closure
    # replays this exact map rather than allowing a later descriptor walk to
    # become a new baseline for root controls or raw journals.
    phase_two_control_tree_snapshot = PinnedDirectory.snapshot_tree(private_control_pin)
    # Retain a non-token launch baseline before any checkpoint/gate reader can
    # run.  This is deliberately derived only from the just-captured tree and
    # setup locals; it takes no new filesystem snapshot that could adopt a
    # post-construction mutation.
    launch_binding = _freeze_registered_actual_phase_two_launch_binding(
        phase_two,
        prepared_run=prepared_run,
        phase_one_diagnostic=phase_one_diagnostic,
        metadata=metadata,
        control_tree_snapshot=phase_two_control_tree_snapshot,
        private_trace=private_trace,
        private_on_native_record=private_on_native_record,
        private_trusted_context=private_trusted_context,
        private_control_pin=private_control_pin,
        private_workspace_pin=private_workspace_pin,
    )
    # Do not let the just-built token carry a capture baseline that was
    # replaced between the final setup read and construction.  The tracker
    # admits no new artifact at ``initial``; it only reconciles producer-fd
    # receipts with a fresh descriptor capture.
    _RegisteredActualPhaseTwoLiveIdentityTracker(
        phase_two, launch_binding,
    ).checkpoint("initial")
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_diagnostic.raw_predecessors,
        phase_one_raw_predecessor_snapshot,
    )
    phase_one_diagnostic.raw_predecessors.verify_current(prepared.control_pin)
    _revalidate_registered_actual_phase_two_launch_gate(
        prepared_run=prepared_run,
        phase_one_diagnostic=phase_one_diagnostic,
        receipt_gate=receipt_gate,
        prepared_phase=phase_two,
        pre_popen=False,
        expected_raw_snapshot=phase_one_raw_predecessor_snapshot,
        expected_evidence_provenance=sealed_evidence_provenance,
        expected_workspace_inventory=sealed_initial_workspace_inventory,
        launch_binding=launch_binding,
    )
    # The final launch gate uses the prepared token to prove launch
    # admissibility.  Its return must not become a new setup baseline: make
    # one terminal closure over the original locals, then return immediately.
    _revalidate_registered_actual_phase_two_setup_return_closure(
        prepared_run,
        phase_one_diagnostic,
        authority=authority,
        plan=plan,
        metadata=metadata,
        writer=writer,
        prepared=prepared,
        phase_one=phase_one,
        live_phase=live_phase,
        phase_one_evidence_provenance=phase_one_evidence_provenance,
        phase_one_raw_predecessor_snapshot=phase_one_raw_predecessor_snapshot,
        phase_two=phase_two,
        phase_control=phase_control,
        runner_state=runner_state,
        mcp_config=mcp_config,
        phase_prompt=phase_prompt,
        trace=trace,
        initial_workspace_snapshot=initial_workspace_snapshot,
        marker_workspace_snapshots=marker_workspace_snapshots,
        on_native_record=on_native_record,
        trusted_context=trusted_context,
        sealed_evidence_provenance=sealed_evidence_provenance,
        sealed_initial_workspace_inventory=sealed_initial_workspace_inventory,
        control_tree_snapshot=phase_two_control_tree_snapshot,
        launch_binding=launch_binding,
    )
    _register_registered_actual_phase_two_launch_binding(phase_two, launch_binding)
    return phase_two


def _phase_one_receipt_gate_matches(
    expected: "PhaseOneReceiptGate",
    reconstructed: "PhaseOneReceiptGate | None",
) -> bool:
    """Require a fresh sealed receipt reconstruction to equal its release token."""

    return bool(
        type(expected) is PhaseOneReceiptGate
        and type(reconstructed) is PhaseOneReceiptGate
        and reconstructed.execution_id == expected.execution_id == "execution-1"
        and reconstructed.receipt_facts == expected.receipt_facts
        and reconstructed.acknowledgement_position == expected.acknowledgement_position
        and reconstructed.report_gap_position == expected.report_gap_position
        and reconstructed.approval_position == expected.approval_position
    )


def _pinned_registered_actual_control_bytes(
    prepared_phase: _RegisteredActualPreparedPhase,
    path: Path,
    *,
    control_pin: PinnedDirectory | None = None,
) -> bytes:
    """Read one already-sealed control file through this phase's root pin."""

    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or not isinstance(path, Path)
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != prepared_phase.writer.control_root):
        raise RunnerError("registered actual control pin is invalid")
    try:
        relative = path.relative_to(control_pin.path).as_posix()
    except ValueError as error:
        raise RunnerError("registered actual control file escaped root") from error
    if relative in {"", "."}:
        raise RunnerError("registered actual control file locator is invalid")
    return PinnedDirectory.read_relative(control_pin, relative)


def _verify_registered_actual_phase_two_control_bindings(
    prepared_phase: _RegisteredActualPreparedPhase,
    *,
    plan: RegisteredActualScenarioPlan,
    scenario: Mapping[str, Any],
    control_pin: PinnedDirectory | None = None,
) -> Path:
    """Reload phase-two control bytes without accepting a caller launch input."""

    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(plan) is not RegisteredActualScenarioPlan
            or plan.client != "claude"
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase_index != 2
            or prepared_phase.phase != "approved_capture"
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != prepared_phase.writer.control_root):
        raise RunnerError("registered actual phase-two control binding is invalid")
    _verify_registered_actual_phase_control(
        prepared_phase, scenario=scenario, control_pin=control_pin,
    )

    prompt = prepared_phase.phase_prompt
    prompt_entry = _writer_entry_map(prepared_phase.writer).get("phase-prompt-2")
    expected_prompt = _canonical_phase_prompt(scenario, "approved_capture")
    if (prompt.artifact_id != "phase-prompt-2"
            or prompt.raw != expected_prompt
            or prompt.sha256 != _sha256(expected_prompt)
            or prompt.transport != _phase_prompt_transport(plan.client)
            or not isinstance(prompt_entry, Mapping)
            or prompt_entry.get("type") != "phase_prompt"
            or prompt_entry.get("sha256") != prompt.sha256
            or prompt_entry.get("bytes") != len(prompt.raw)
            or prompt.seal.path != (
                prepared_phase.writer.run_root / str(prompt_entry.get("relative_path", ""))
            ).resolve()):
        raise RunnerError("registered actual phase-two prompt binding is invalid")
    _verify_phase_prompt(prompt)
    if (_pinned_registered_actual_control_bytes(
            prepared_phase, prompt.seal.path, control_pin=control_pin,
    ) != prompt.raw):
        raise RunnerError("runner-owned phase-two prompt bytes changed before actual launch")

    mcp_config = prepared_phase.mcp_config
    mcp_entry = _writer_entry_map(prepared_phase.writer).get("mcp-2")
    if (not isinstance(mcp_config, ControlFileSeal)
            or not isinstance(mcp_entry, Mapping)
            or mcp_entry.get("type") != "mcp_config"
            or mcp_entry.get("sha256") != _sha256(EMPTY_MCP_BYTES)
            or mcp_entry.get("bytes") != len(EMPTY_MCP_BYTES)
            or mcp_config.path != (
                prepared_phase.writer.run_root / str(mcp_entry.get("relative_path", ""))
            ).resolve()):
        raise RunnerError("registered actual phase-two MCP binding is invalid")
    verify_control_file(mcp_config)
    if (_safe_read(mcp_config.path) != EMPTY_MCP_BYTES
            or _pinned_registered_actual_control_bytes(
                prepared_phase, mcp_config.path, control_pin=control_pin,
            )
            != EMPTY_MCP_BYTES):
        raise RunnerError("runner-owned phase-two MCP bytes changed before actual launch")

    expected_state = {
        "schema_version": 1,
        "control_root": str(prepared_phase.writer.control_root),
        "workspace": str(prepared_phase.workspace),
        "run_id": prepared_phase.writer.run_id,
        "execution_id": "execution-2",
        "phase": "approved_capture",
    }
    if prepared_phase.runner_state.path != prepared_phase.writer.control_root / "runner-state.json":
        raise RunnerError("registered actual phase-two runner state locator mismatch")
    verify_control_file(prepared_phase.runner_state)
    state_raw = _pinned_registered_actual_control_bytes(
        prepared_phase, prepared_phase.runner_state.path, control_pin=control_pin,
    )
    state = _strict_json(state_raw, label="registered actual phase-two runner state")
    if (type(state) is not dict
            or set(state) != set(expected_state)
            or type(state.get("schema_version")) is not int
            or any(type(state.get(key)) is not str for key in expected_state if key != "schema_version")
            or state != expected_state
            or state_raw != _canonical_json(state)):
        raise RunnerError("registered actual phase-two runner state binding is invalid")
    return mcp_config.path


def _registered_actual_phase_two_launch_tree_is_open(
    prepared_phase: _RegisteredActualPreparedPhase,
    *,
    pre_popen: bool,
    control_pin: PinnedDirectory | None = None,
) -> None:
    """Require the exact pre-spawn run tree and runner-trace namespace.

    Phase-two setup legitimately adds its prompt, MCP, and initial snapshot;
    phase-two probes legitimately add only version/help evidence.  Everything
    else is either terminal output, a future execution, or unindexed/orphan
    residue and must stop before the process boundary.
    """

    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(pre_popen) is not bool
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private):
        raise RunnerError("registered actual phase-two launch tree inputs are invalid")
    writer = prepared_phase.writer
    provenance = prepared_phase.sealed_evidence_provenance
    if (control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id
            or not isinstance(provenance, Mapping)
            or not provenance):
        raise RunnerError("registered actual phase-two launch tree provenance is invalid")
    _require_unique_writer_entry_ids(writer)

    entries: dict[str, Mapping[str, Any]] = {}
    for entry in writer.entries:
        if (type(entry) is not dict or set(entry) != {
                "id", "type", "relative_path", "sha256", "bytes",
        }):
            raise RunnerError("registered actual phase-two launch evidence is invalid")
        artifact_id = entry["id"]
        artifact_type = entry["type"]
        relative = entry["relative_path"]
        path = PurePosixPath(relative) if type(relative) is str else None
        if (type(artifact_id) is not str or not artifact_id
                or type(artifact_type) is not str or not artifact_type
                or type(relative) is not str or path is None
                or path.is_absolute() or path.as_posix() != relative or not path.parts
                or any(part in {"", ".", ".."} for part in path.parts)
                or not _is_hex64(entry["sha256"])
                or type(entry["bytes"]) is not int or entry["bytes"] < 0
                or artifact_id in entries):
            raise RunnerError("registered actual phase-two launch evidence is invalid")
        entries[artifact_id] = entry

    expected_types: dict[str, str] = {}

    def expect(artifact_id: object, artifact_type: str) -> None:
        if type(artifact_id) is not str or not artifact_id:
            raise RunnerError("registered actual phase-two launch evidence is invalid")
        prior = expected_types.setdefault(artifact_id, artifact_type)
        if prior != artifact_type:
            raise RunnerError("registered actual phase-two launch evidence is invalid")

    forbidden_setup_ids = {
        "version-2", "help-2", "client-executable-2", "policy-2", "process-2",
        "transcript-2", "stderr-2", "trace-execution-2",
    }
    for artifact_id, record in provenance.items():
        if (type(artifact_id) is not str or type(record) is not tuple or len(record) != 5):
            raise RunnerError("registered actual phase-two launch tree provenance is invalid")
        artifact_type, relative, digest, byte_count, identity = record
        entry = entries.get(artifact_id)
        if (artifact_id in forbidden_setup_ids
                or not isinstance(entry, Mapping)
                or (entry.get("type"), entry.get("relative_path"), entry.get("sha256"), entry.get("bytes"))
                != (artifact_type, relative, digest, byte_count)):
            raise RunnerError("registered actual phase-two launch evidence provenance changed")
        path = PurePosixPath(relative)
        raw = _writer_artifact_bytes(
            writer, artifact_id, artifact_type, control_pin=control_pin,
        )
        retained, observed_identity = PinnedDirectory.snapshot_relative(
            control_pin,
            PurePosixPath("runs", writer.run_id, *path.parts).as_posix(),
        )
        if retained != raw or observed_identity != identity:
            raise RunnerError("registered actual phase-two launch evidence provenance changed")
        expect(artifact_id, artifact_type)

    phase_two_snapshot_id = _workspace_snapshot_artifact_id("execution-2", "initial", 0)
    snapshot = _indexed_workspace_snapshot(
        writer,
        prepared_phase.initial_workspace_snapshot,
        control_pin=control_pin,
    )
    if (snapshot.artifact_id != phase_two_snapshot_id
            or snapshot.execution_id != "execution-2"
            or snapshot.role != "initial"
            or snapshot.trace_sequence != 0):
        raise RunnerError("registered actual phase-two launch snapshot is invalid")
    expect("mcp-2", "mcp_config")
    expect("phase-prompt-2", "phase_prompt")
    expect(phase_two_snapshot_id, "workspace_snapshot")
    for item in snapshot.inventory:
        expect(item.get("content_id"), "file_capture")
    if pre_popen:
        expect("version-2", "version")
        expect("help-2", "help")
    if set(entries) != set(expected_types):
        raise RunnerError("registered actual phase-two launch evidence inventory is invalid")

    expected_files: set[str] = set()
    expected_directories: set[str] = set()
    for artifact_id, artifact_type in expected_types.items():
        entry = entries[artifact_id]
        relative = str(entry["relative_path"])
        path = PurePosixPath(relative)
        if artifact_id not in provenance:
            expected_relative = PurePosixPath("artifacts", artifact_id + ".bin").as_posix()
            if relative != expected_relative:
                raise RunnerError("registered actual phase-two launch evidence locator is invalid")
        _writer_artifact_bytes(
            writer, artifact_id, artifact_type, control_pin=control_pin,
        )
        expected_files.add(relative)
        expected_directories.update(
            parent.as_posix() for parent in path.parents if parent != PurePosixPath(".")
        )

    run_relative = PurePosixPath("runs", writer.run_id).as_posix()
    directories, files = _pinned_control_tree_inventory(control_pin, run_relative)
    terminal_files = {
        "evidence-index.json", "log-attestation.json", "event-log.json", "run-manifest.json",
    }
    if terminal_files & set(files):
        raise RunnerError("registered actual phase-two launch is already sealed")
    if set(directories) != expected_directories or set(files) != expected_files:
        raise RunnerError("registered actual phase-two launch output inventory is invalid")
    PinnedDirectory.verify(control_pin)
    try:
        trace_names = {
            name for name in os.listdir(control_pin.root_fd)
            if name.startswith("runner-trace-")
        }
    except OSError as error:
        raise RunnerError("registered actual phase-two launch trace namespace is unavailable") from error
    if trace_names != {"runner-trace-execution-1.jsonl"}:
        raise RunnerError("registered actual phase-two launch trace namespace is invalid")
    # Receipt ledgers belong exclusively to the adjacent pre-Popen allocator.
    # They live at the control root rather than beneath the evidence run tree,
    # so check them only after every prior tree/provenance reader has returned.
    for relative in (
            _PHASE_TWO_RAW_WRITE_RECEIPT_LEDGER,
            _PHASE_TWO_TRACE_RECEIPT_LEDGER,
    ):
        if not _pinned_control_capture_is_absent(control_pin, relative):
            raise RunnerError("registered actual phase-two receipt ledger already exists")
    PinnedDirectory.verify(control_pin)


def _revalidate_registered_actual_phase_two_launch_gate(
    *,
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: "PhaseOneReceiptGate",
    prepared_phase: _RegisteredActualPreparedPhase,
    pre_popen: bool = False,
    expected_raw_snapshot: _RegisteredActualPhaseOneRawPredecessorSnapshot,
    expected_evidence_provenance: Mapping[str, _RegisteredActualEvidenceProvenance],
    expected_workspace_inventory: _RegisteredActualPhaseTwoWorkspaceInventory,
    launch_binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> Mapping[str, tuple[int, int, int, int, int, int, int, int]]:
    """Repeat every sealed phase transition check immediately before spawn.

    The phase-two setup token deliberately is not a launch authority by
    itself.  This no-write guard reloads the receipt from indexed phase-one
    facts and rechecks the phase-two control/context closure after probes but
    directly before the one process-creation boundary.
    """

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(receipt_gate) is not PhaseOneReceiptGate
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(pre_popen) is not bool
            or type(launch_binding) is not _RegisteredActualPhaseTwoLaunchBinding):
        raise RunnerError("registered actual phase-two launch inputs are invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot execute actual launch")
    if (launch_binding.prepared_run is not prepared_run
            or launch_binding.phase_one_diagnostic is not phase_one_diagnostic):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    prepared_phase.__post_init__()
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    receipt_gate.__post_init__()
    if (not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(expected_raw_snapshot)
            or prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot
            or not isinstance(expected_evidence_provenance, Mapping)
            or not expected_evidence_provenance
            or prepared_phase.sealed_evidence_provenance != expected_evidence_provenance
            or not _registered_actual_phase_two_workspace_inventory_is_valid(
                expected_workspace_inventory,
            )
            or prepared_phase.sealed_initial_workspace_inventory
            != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained setup state changed")

    authority = prepared_run.authority
    plan = authority.plan
    writer = prepared_run.writer
    prepared = prepared_run.prepared
    phase_one = phase_one_diagnostic.prepared_phase
    source_live_phase = phase_one_diagnostic.live_phase
    phase_one_bridge = launch_binding.phase_one_bridge
    live_phase = phase_one_bridge.live_phase
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or type(writer) is not EvidenceWriter
            or type(prepared) is not PreparedWorkspace
            or prepared_run.authority is not authority
            or prepared_run.writer is not writer
            or prepared_run.run_id != writer.run_id
            or prepared_run.prepared is not prepared
            or phase_one.prepared_run is not prepared_run
            or phase_one.authority is not authority
            or phase_one.writer is not writer
            or phase_one_diagnostic.prepared_phase is not phase_one
            or phase_one_diagnostic.live_phase is not source_live_phase
            or prepared_phase.prepared_run is not prepared_run
            or prepared_phase.authority is not authority
            or prepared_phase.writer is not writer):
        raise RunnerError("registered actual phase-two launch binding is invalid")

    registration = _runner_owned_registration(plan.client)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    phases = phase_plan(plan.scenario_id)
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phases != ("approval", "approved_capture")
            or plan.registration is not registration
            or plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or metadata.scenario_id != plan.scenario_id
            or writer.control_root != prepared.control_root
            or writer.run_id != prepared_run.run_id
            or writer.run_root != prepared.control_root / "runs" / prepared_run.run_id
            or phase_one.execution_id != "execution-1"
            or phase_one.phase_index != 1
            or phase_one.phase != "approval"
            or source_live_phase.control_pin is not phase_one.control_pin
            or source_live_phase.workspace_pin is not phase_one.workspace_pin
            or live_phase.control_pin is not launch_binding.control_pin
            or live_phase.workspace_pin is not launch_binding.workspace_pin
            or receipt_gate.execution_id != "execution-1"
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase_index != 2
            or prepared_phase.phase != "approved_capture"
            or prepared_phase.marker_workspace_snapshots
            or prepared_phase.control_pin is not prepared.control_pin
            or prepared_phase.workspace_pin is not prepared.workspace_pin
            or prepared_phase.workspace != prepared.workspace
            or prepared_phase.control_pin is not phase_one.control_pin
            or prepared_phase.workspace_pin is not phase_one.workspace_pin):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    if (not prepared_phase.control_pin.private
            or prepared_phase.workspace_pin.private
            or prepared_phase.writer.control_root != prepared_phase.control_pin.path
            or launch_binding.trace.control_root != launch_binding.control_pin.path
            or launch_binding.trace.control_pin is not launch_binding.control_pin
            or launch_binding.trace.path != (
                launch_binding.control_pin.path / "runner-trace-execution-2.jsonl"
            )
            or launch_binding.trace.lock_path != launch_binding.control_pin.path / ".runner-trace.lock"
            or prepared_phase.transcript_id != "transcript-2"):
        raise RunnerError("registered actual phase-two launch roots are invalid")
    _require_unique_writer_entry_ids(writer)
    _verify_registered_phase_roots(
        writer=writer,
        workspace=prepared_phase.workspace,
        control_pin=launch_binding.control_pin,
        workspace_pin=launch_binding.workspace_pin,
        trace=launch_binding.trace,
    )
    if launch_binding.trace.records():
        raise RunnerError("registered actual phase-two trace exists before launch")
    verify_wrapper(prepared.wrapper_seal)
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_bridge.raw_predecessors,
        expected_raw_snapshot,
    )
    phase_one_bridge.raw_predecessors.verify_current(launch_binding.control_pin)

    # First reread phase one before reconstructing the exact receipt.  The
    # old phase-one config/state are intentionally superseded by phase two,
    # but its indexed process/policy/trace join remains immutable authority.
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
        control_pin=launch_binding.control_pin,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    reconstructed_gate = _reconstruct_actual_phase_one_receipt_gate(
        writer=writer,
        phase_one=live_phase,
        scenario=scenario,
        conversion=phase_one_bridge.conversion,
        workspace=launch_binding.workspace,
        execution_id="execution-1",
        control_pin=launch_binding.control_pin,
    )
    if not _phase_one_receipt_gate_matches(receipt_gate, reconstructed_gate):
        raise RunnerError("registered actual phase-one receipt gate is no longer valid")
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
        control_pin=launch_binding.control_pin,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")

    _verify_registered_actual_phase_two_control_bindings(
        prepared_phase,
        plan=plan,
        scenario=scenario,
        control_pin=launch_binding.control_pin,
    )
    private_trusted_context = launch_binding.trusted_context
    phase_one_registration, phase_one_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-1",
        control_pin=launch_binding.control_pin,
        workspace_pin=launch_binding.workspace_pin,
        trusted_context=private_trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    phase_two_registration, phase_two_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-2",
        control_pin=launch_binding.control_pin,
        workspace_pin=launch_binding.workspace_pin,
        trusted_context=private_trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    if (phase_one_registration is not registration
            or phase_two_registration is not registration
            or phase_two_trusted is phase_one_trusted
            or private_trusted_context is prepared_phase.trusted_context
            or private_trusted_context.trusted_executables.get("execution-1")
            is not phase_one_trusted
            or private_trusted_context.trusted_executables.get("execution-2")
            is not phase_two_trusted):
        raise RunnerError("registered actual phase-two trusted context is invalid")
    _registered_executable_observation(phase_one_trusted)
    _registered_executable_observation(phase_two_trusted)

    # The preceding phase-two control/context/executable reads are required
    # before a launch can be considered.  Recheck phase-one evidence, then
    # make the pinned run-tree/provenance inventory and receipt reconstruction
    # the final no-write checks before the adjacent pre-Popen allocation.
    # This prevents a probe-time or late control-read mutation from relying on
    # an earlier receipt/tree observation.
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
        control_pin=launch_binding.control_pin,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    _registered_actual_phase_two_launch_tree_is_open(
        prepared_phase,
        pre_popen=pre_popen,
        control_pin=launch_binding.control_pin,
    )
    # The launch-tree inventory is the last read-only callback before the
    # pre-Popen guard allocates private receipt ledgers.  Reconstruct the
    # gate after it, rather than before it, so a valid-shaped in-memory gate
    # mutation cannot reach either ledger allocation or process creation.
    receipt_gate.__post_init__()
    reconstructed_gate = _reconstruct_actual_phase_one_receipt_gate(
        writer=writer,
        phase_one=live_phase,
        scenario=scenario,
        conversion=phase_one_bridge.conversion,
        workspace=launch_binding.workspace,
        execution_id="execution-1",
        control_pin=launch_binding.control_pin,
    )
    if not _phase_one_receipt_gate_matches(receipt_gate, reconstructed_gate):
        raise RunnerError("registered actual phase-one receipt gate is no longer valid")
    # The final tree read does not cover root raw journals.  Rebind their
    # primitive phase-one snapshot after the receipt reconstruction so a
    # same-byte journal replacement cannot escape this no-write gate and be
    # considered later by receipt-ledger allocation.
    _verify_registered_actual_phase_one_raw_predecessor_snapshot(
        phase_one_bridge.raw_predecessors,
        expected_raw_snapshot,
    )
    phase_one_bridge.raw_predecessors.verify_current(launch_binding.control_pin)
    # The launch-tree inventory does not carry identity seals for phase-two
    # root controls.  Recheck them after that final tree/read boundary before
    # returning a prepared token or allocating the private pre-Popen ledgers.
    _verify_registered_actual_phase_two_control_bindings(
        prepared_phase,
        plan=plan,
        scenario=scenario,
        control_pin=launch_binding.control_pin,
    )
    _verify_registered_actual_phase_two_expected_evidence_provenance(
        writer,
        control_pin=launch_binding.control_pin,
        expected=expected_evidence_provenance,
    )
    # Keep an immutable exact pre-allocation control-tree baseline for the
    # adjacent receipt-ledger allocator.  The allocator must not treat its
    # own fresh descriptor walk as a new authority after this gate returns.
    pre_allocation_control_tree = MappingProxyType(
        dict(PinnedDirectory.snapshot_tree(launch_binding.control_pin)),
    )
    # ``expected_workspace_inventory`` originated from the private prepared
    # token at the launch boundary, so shape validation alone is insufficient.
    # Reconstruct the canonical tuple from the sealed indexed initial snapshot
    # before using it to inspect the live workspace.  This makes a forged
    # frozen-token field fail closed rather than become a caller-selected
    # workspace baseline.
    # Use a canonical handle rather than the caller-visible snapshot object:
    # the indexed reader intentionally treats only this fixed artifact ID as
    # authority, and no mutable convenience fields can affect the reload.
    canonical_initial_workspace_snapshot = WorkspaceSnapshot(
        execution_id="execution-2",
        trace_sequence=0,
        inventory=(),
        staged_paths=(),
        artifact_id=_workspace_snapshot_artifact_id("execution-2", "initial", 0),
        role="initial",
    )
    sealed_workspace_inventory = _registered_actual_phase_two_initial_workspace_inventory(
        writer,
        control_pin=launch_binding.control_pin,
        initial_workspace_snapshot=canonical_initial_workspace_snapshot,
    )
    if sealed_workspace_inventory != expected_workspace_inventory:
        raise RunnerError("registered actual phase-two retained setup state changed")
    # The snapshot reload above is itself a reader boundary.  Replay the
    # identity-bound evidence check before the content scan so it cannot
    # replace the sealed snapshot bytes with a matching forged tuple.
    _verify_registered_actual_phase_two_expected_evidence_provenance(
        writer,
        control_pin=launch_binding.control_pin,
        expected=expected_evidence_provenance,
    )
    if (prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot
            or prepared_phase.sealed_evidence_provenance != expected_evidence_provenance
            or prepared_phase.sealed_initial_workspace_inventory
            != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained setup state changed")
    if (launch_binding.raw_predecessor_snapshot != expected_raw_snapshot
            or launch_binding.evidence_provenance != expected_evidence_provenance
            or launch_binding.workspace_inventory != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained launch token changed")
    # Snapshot construction and the preceding re-read helpers are all
    # hostile-reader boundaries.  Make them replay the exact tree captured
    # above before the terminal workspace scan hands the baseline forward to
    # receipt-ledger allocation.
    PinnedDirectory.reverify_tree(launch_binding.control_pin, pre_allocation_control_tree)
    # This must remain the final filesystem check in the no-write gate: no
    # preceding receipt, control, or provenance reader may establish a later
    # workspace state as the baseline before process creation.
    _verify_registered_actual_phase_two_workspace_inventory_is_current(
        launch_binding.workspace_pin,
        expected_workspace_inventory,
    )
    # The scanner is intentionally the final filesystem read, but it is
    # still a helper boundary.  Finish with a local-only replay so it cannot
    # replace a retained launch input after the preceding comparison.
    if (prepared_phase.phase_one_raw_predecessor_snapshot != expected_raw_snapshot
            or prepared_phase.sealed_evidence_provenance != expected_evidence_provenance
            or prepared_phase.sealed_initial_workspace_inventory
            != expected_workspace_inventory):
        raise RunnerError("registered actual phase-two retained setup state changed")
    # The workspace scanner is a hostile helper boundary too.  Replay the
    # detached phase/token/root baseline after it, rather than leaving a
    # mutable returned field or fixture map as the final launch authority.
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    return pre_allocation_control_tree


def _registered_actual_phase_two_pinned_entry_map(
    writer: EvidenceWriter,
    *,
    control_pin: PinnedDirectory,
) -> dict[str, dict[str, Any]]:
    """Reload every mutable writer row through the retained private root."""

    if (type(writer) is not EvidenceWriter
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id):
        raise RunnerError("registered actual phase-two post-launch evidence roots are invalid")
    _require_unique_writer_entry_ids(writer)
    entries: dict[str, dict[str, Any]] = {}
    relative_paths: set[str] = set()
    for entry in writer.entries:
        if (type(entry) is not dict or set(entry) != {
                "id", "type", "relative_path", "sha256", "bytes",
        }):
            raise RunnerError("registered actual phase-two post-launch evidence is invalid")
        artifact_id = entry["id"]
        artifact_type = entry["type"]
        relative = entry["relative_path"]
        path = PurePosixPath(relative) if type(relative) is str else None
        if (type(artifact_id) is not str or not artifact_id
                or type(artifact_type) is not str or not artifact_type
                or type(relative) is not str or path is None
                or path.is_absolute() or path.as_posix() != relative or not path.parts
                or any(part in {"", ".", ".."} for part in path.parts)
                or not _is_hex64(entry["sha256"])
                or type(entry["bytes"]) is not int or entry["bytes"] < 0
                or artifact_id in entries or relative in relative_paths):
            raise RunnerError("registered actual phase-two post-launch evidence is invalid")
        _writer_artifact_bytes(
            writer, artifact_id, artifact_type, control_pin=control_pin,
        )
        entries[artifact_id] = dict(entry)
        relative_paths.add(relative)
    if not entries:
        raise RunnerError("registered actual phase-two post-launch evidence is empty")
    return entries


def _verify_registered_actual_phase_two_setup_provenance(
    prepared_phase: _RegisteredActualPreparedPhase,
    *,
    entries: Mapping[str, Mapping[str, Any]],
    control_pin: PinnedDirectory | None = None,
) -> Mapping[str, _RegisteredActualEvidenceProvenance]:
    """Recheck the descriptor identities frozen at phase-two setup.

    The phase-one receipt and aggregate trusted context must be re-read only
    after this check: they are allowed to rely on setup facts whose bytes *and*
    exact inodes have survived the live phase.  This remains a read-only
    retention guard, not evidence indexing.
    """

    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or not isinstance(entries, Mapping)
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private):
        raise RunnerError("registered actual phase-two post-launch provenance is invalid")
    writer = prepared_phase.writer
    provenance = prepared_phase.sealed_evidence_provenance
    if (not isinstance(provenance, Mapping)
            or not provenance
            or control_pin.path != writer.control_root.resolve()
            or writer.run_root != control_pin.path / "runs" / writer.run_id):
        raise RunnerError("registered actual phase-two post-launch provenance is invalid")
    for artifact_id, record in provenance.items():
        if (type(artifact_id) is not str or type(record) is not tuple or len(record) != 5):
            raise RunnerError("registered actual phase-two post-launch provenance is invalid")
        artifact_type, relative, digest, byte_count, identity = record
        entry = entries.get(artifact_id)
        if (not isinstance(entry, Mapping)
                or (entry.get("type"), entry.get("relative_path"), entry.get("sha256"), entry.get("bytes"))
                != (artifact_type, relative, digest, byte_count)):
            raise RunnerError("registered actual phase-two setup provenance changed")
        raw = _writer_artifact_bytes(
            writer, artifact_id, artifact_type, control_pin=control_pin,
        )
        retained, observed_identity = PinnedDirectory.snapshot_relative(
            control_pin,
            PurePosixPath("runs", writer.run_id, *PurePosixPath(relative).parts).as_posix(),
        )
        if retained != raw or observed_identity != identity:
            raise RunnerError("registered actual phase-two setup provenance changed")
    return provenance


def _registered_actual_phase_two_live_artifact_join(
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    *,
    plan: RegisteredActualScenarioPlan,
    registration: RunnerOwnedExecutableRegistration,
    trusted_context: Any,
    phase_two_trusted: Any,
    entries: Mapping[str, Mapping[str, Any]],
) -> None:
    """Bind phase two's in-memory launch result to its retained host rows."""

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase
            or type(plan) is not RegisteredActualScenarioPlan
            or type(registration) is not RunnerOwnedExecutableRegistration
            or not isinstance(entries, Mapping)
            or type(live_phase.capture) is not ProcessCapture
            or live_phase.trusted_context is not trusted_context
            or live_phase.trusted_executable is not phase_two_trusted
            or live_phase.executable_id != "client-executable-2"
            or live_phase.version_id != "version-2"
            or live_phase.help_id != "help-2"
            or live_phase.reported_version != registration.expected_version
            or live_phase.native_format != registration.native_format
            or live_phase.supported_build_id != phase_two_trusted.supported_build_id
            or type(live_phase.capture.exit_code) is not int
            or type(live_phase.capture.stdout) is not bytes
            or type(live_phase.capture.stderr) is not bytes
            or type(live_phase.capture.version) is not bytes
            or type(live_phase.capture.help) is not bytes
            or live_phase.capture.stdout_chunks is not None):
        raise RunnerError("registered actual phase-two live host join is invalid")
    control_pin, _workspace_pin = _registered_actual_phase_two_live_roots(
        prepared_phase, live_phase,
    )
    try:
        launch_identity = dict(live_phase.launch_identity)
        seal_identity = dict(live_phase.seal_identity)
    except (TypeError, ValueError) as error:
        raise RunnerError("registered actual phase-two live host join is invalid") from error
    if (any(type(key) is not str or type(value) is not int
            for identity in (launch_identity, seal_identity)
            for key, value in identity.items())
            or not launch_identity or not seal_identity):
        raise RunnerError("registered actual phase-two live host join is invalid")
    observed_identity, observed_sha256 = _registered_executable_observation(phase_two_trusted)
    if (launch_identity != observed_identity
            or seal_identity != observed_identity
            or live_phase.launch_sha256 != observed_sha256
            or live_phase.seal_sha256 != observed_sha256):
        raise RunnerError("registered actual phase-two executable join changed")

    metadata = _registered_actual_scenario_fixture_metadata(prepared_phase.prepared_run, plan)
    expected_argv = build_effective_argv(
        plan.client,
        plan.symbolic_template,
        prepared_phase.workspace,
        _verify_registered_actual_phase_two_control_bindings(
            prepared_phase,
            plan=plan,
            scenario=metadata.scenario(),
            control_pin=control_pin,
        ),
        prepared_phase.phase_prompt.raw.decode("utf-8", "strict"),
    )
    final_argv = (str(registration.resolved_path), *tuple(expected_argv[1:]))
    if (live_phase.argv != final_argv
            or _version_text(live_phase.capture.version) != live_phase.reported_version):
        raise RunnerError("registered actual phase-two launch argv is invalid")
    version = _writer_artifact_bytes(
        prepared_phase.writer, "version-2", "version", control_pin=control_pin,
    )
    help_output = _writer_artifact_bytes(
        prepared_phase.writer, "help-2", "help", control_pin=control_pin,
    )
    if version != live_phase.capture.version or help_output != live_phase.capture.help:
        raise RunnerError("registered actual phase-two probe evidence changed")

    executable_entry = entries.get("client-executable-2")
    if not isinstance(executable_entry, Mapping) or executable_entry.get("type") != "client_executable":
        raise RunnerError("registered actual phase-two executable evidence is invalid")
    executable = _strict_json(
        _writer_artifact_bytes(
            prepared_phase.writer,
            "client-executable-2",
            "client_executable",
            control_pin=control_pin,
        ),
        label="registered actual phase-two executable",
    )
    expected_keys = {
        "schema_version", "run_id", "execution_id", "phase", "client", "resolved_path",
        "launch_identity", "launch_sha256", "seal_identity", "seal_sha256", "reported_version",
        "version_probe", "help_probe", "supported_build_id",
    }
    if type(executable) is not dict or set(executable) != expected_keys:
        raise RunnerError("registered actual phase-two executable evidence is invalid")
    version_probe = executable["version_probe"]
    help_probe = executable["help_probe"]
    if (type(version_probe) is not dict
            or type(help_probe) is not dict
            or set(version_probe) != {"argv", "exit_code", "output_id", "output_sha256"}
            or set(help_probe) != {"argv", "exit_code", "output_id", "output_sha256"}
            or executable.get("schema_version") != 1
            or executable.get("run_id") != prepared_phase.writer.run_id
            or executable.get("execution_id") != "execution-2"
            or executable.get("phase") != "approved_capture"
            or executable.get("client") != "claude"
            or executable.get("resolved_path") != str(registration.resolved_path)
            or executable.get("launch_identity") != launch_identity
            or executable.get("launch_sha256") != live_phase.launch_sha256
            or executable.get("seal_identity") != seal_identity
            or executable.get("seal_sha256") != live_phase.seal_sha256
            or executable.get("reported_version") != live_phase.reported_version
            or executable.get("supported_build_id") != live_phase.supported_build_id
            or version_probe.get("argv") != [str(registration.resolved_path), "--version"]
            or version_probe.get("output_id") != "version-2"
            or version_probe.get("output_sha256") != _sha256(version)
            or type(version_probe.get("exit_code")) is not int
            or help_probe.get("argv") != [str(registration.resolved_path), "--help"]
            or help_probe.get("output_id") != "help-2"
            or help_probe.get("output_sha256") != _sha256(help_output)
            or type(help_probe.get("exit_code")) is not int):
        raise RunnerError("registered actual phase-two executable evidence is invalid")


def _registered_actual_phase_two_post_launch_trace(
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    *,
    trace: ControlTraceWriter,
) -> tuple[tuple[int, int, int, int, int, int, int, int], str, tuple[WorkspaceSnapshot, ...]]:
    """Pin the completed private phase-two trace and its trace-owned snapshots."""

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase
            or type(trace) is not ControlTraceWriter
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase_index != 2
            or prepared_phase.phase != "approved_capture"
            or prepared_phase.transcript_id != "transcript-2"
            or type(live_phase.capture.stdout) is not bytes):
        raise RunnerError("registered actual phase-two post-launch trace is invalid")
    control_pin, _workspace_pin = _registered_actual_phase_two_live_roots(
        prepared_phase, live_phase,
    )
    if (trace.control_pin is not control_pin
            or trace.control_root != control_pin.path
            or trace.path != control_pin.path / "runner-trace-execution-2.jsonl"
            or trace.lock_path != control_pin.path / ".runner-trace.lock"):
        raise RunnerError("registered actual phase-two post-launch trace is invalid")
    raw, identity = PinnedDirectory.snapshot_relative(control_pin, trace.path.name)
    try:
        rows = tuple(_strict_json(line, label="registered actual phase-two trace") for line in raw.splitlines())
    except RunnerError:
        raise
    if rows:
        validate_trace_records(rows)
    marker_snapshots: list[WorkspaceSnapshot] = []
    offset = 0
    for row in rows:
        # Shim command rows are still trace-validated and ledger-bound above,
        # but only native transcript records consume stdout offsets or own a
        # marker-time workspace snapshot.
        if row.get("kind") != "native_record":
            continue
        if (type(row) is not dict
                or row.get("transcript_id") != "transcript-2"
                or row.get("byte_start") != offset
                or type(row.get("byte_end")) is not int
                or row["byte_end"] <= offset
                or row["byte_end"] > len(live_phase.capture.stdout)
                or _sha256(live_phase.capture.stdout[offset:row["byte_end"]]) != row.get("sha256")):
            raise RunnerError("registered actual phase-two trace is not host-bound")
        snapshot = _indexed_trace_workspace_snapshot(
            prepared_phase.writer,
            execution_id="execution-2",
            native_row=row,
            control_pin=control_pin,
        )
        marker_snapshots.append(snapshot)
        offset = row["byte_end"]
    if offset != len(live_phase.capture.stdout):
        raise RunnerError("registered actual phase-two trace is incomplete")
    retained_ids = tuple(
        snapshot.artifact_id for snapshot in prepared_phase.marker_workspace_snapshots
    )
    marker_ids = tuple(snapshot.artifact_id for snapshot in marker_snapshots)
    if (len(marker_ids) != len(set(marker_ids))
            or retained_ids != marker_ids):
        raise RunnerError("registered actual phase-two trace snapshots are not trace-owned")
    initial = _indexed_workspace_snapshot(
        prepared_phase.writer,
        prepared_phase.initial_workspace_snapshot,
        control_pin=control_pin,
    )
    initial_id = _workspace_snapshot_artifact_id("execution-2", "initial", 0)
    if (initial.artifact_id != initial_id
            or initial.execution_id != "execution-2"
            or initial.role != "initial"
            or initial.trace_sequence != 0):
        raise RunnerError("registered actual phase-two initial snapshot is invalid")
    return identity, _sha256(raw), (initial, *marker_snapshots)


def _registered_actual_phase_two_canonical_retained_trace(
    prepared_phase: _RegisteredActualPreparedPhase,
    *,
    live_phase: RegisteredLivePhase | None = None,
) -> ControlTraceWriter:
    """Build the fixed phase-two trace facade without consulting the token one.

    The launch binding is intentionally revoked as soon as its one live
    process finishes.  Later diagnostic reads still need the fixed physical
    trace name, but must not regain authority from the caller-visible trace
    object retained on ``prepared_phase``.
    """

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase_index != 2
            or prepared_phase.phase != "approved_capture"
            or not isinstance(prepared_phase.control_pin, PinnedDirectory)
            or not prepared_phase.control_pin.private):
        raise RunnerError("registered actual phase-two retained trace is invalid")
    if live_phase is None:
        control_pin = prepared_phase.control_pin
    else:
        control_pin, _workspace_pin = _registered_actual_phase_two_live_roots(
            prepared_phase, live_phase,
        )
    trace = ControlTraceWriter(
        control_pin.path,
        "execution-2",
        control_pin=control_pin,
    )
    if (trace.control_root != control_pin.path
            or trace.control_pin is not control_pin
            or trace.execution_id != "execution-2"
            or trace.path != control_pin.path / "runner-trace-execution-2.jsonl"
            or trace.lock_path != control_pin.path / ".runner-trace.lock"):
        raise RunnerError("registered actual phase-two retained trace is invalid")
    return trace


def _registered_actual_phase_two_post_launch_facts(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: "PhaseOneReceiptGate",
    receipt_control: "_FrozenActualPhaseOneReceiptControl",
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    *,
    trace: ControlTraceWriter,
    trusted_context: Any,
    phase_one_bridge: _RegisteredActualPhaseOnePrivateLaunchBridge | None = None,
) -> tuple[
    Mapping[str, _RegisteredActualEvidenceProvenance],
    Mapping[str, str],
    tuple[int, int, int, int, int, int, int, int],
    str,
    tuple[str, ...],
]:
    """Rebuild the post-launch host closure without indexing or emitting.

    This is deliberately a read-only counterpart to the pre-Popen gate.  It
    checks the completed phase-two trace and live artifacts while preserving
    the exact sealed phase-one receipt join.  No future indexer, semantic
    converter, capability artifact, or finalizer is reachable here.
    """

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(receipt_gate) is not PhaseOneReceiptGate
            or type(receipt_control) is not _FrozenActualPhaseOneReceiptControl
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase
            or type(trace) is not ControlTraceWriter
            or trusted_context is None
            or phase_one_bridge is not None
            and type(phase_one_bridge) is not _RegisteredActualPhaseOnePrivateLaunchBridge):
        raise RunnerError("registered actual phase-two post-launch inputs are invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot retain actual phase evidence")
    # ``_RegisteredActualPreparedRun.__post_init__`` is deliberately a
    # creation-time invariant and requires an empty writer.  At this point
    # the completed phase owns retained evidence, so re-establish its exact
    # nonempty binding below instead of replaying that allocator-only check.
    receipt_gate.__post_init__()
    prepared_phase.__post_init__()
    control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
        prepared_phase, live_phase,
    )
    if phase_one_bridge is None:
        phase_one_diagnostic.__post_init__()
        phase_one_live = phase_one_diagnostic.live_phase
    else:
        phase_one_bridge.assert_current(
            control_pin=control_pin,
            workspace_pin=workspace_pin,
            trusted_context=trusted_context,
        )
        phase_one_live = phase_one_bridge.live_phase
    receipt_control.verify()

    authority = prepared_run.authority
    plan = authority.plan
    writer = prepared_run.writer
    prepared = prepared_run.prepared
    phase_one = phase_one_diagnostic.prepared_phase
    source_phase_one_live = phase_one_diagnostic.live_phase
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or type(writer) is not EvidenceWriter
            or type(prepared) is not PreparedWorkspace
            or prepared_run.authority is not authority
            or prepared_run.prepared is not prepared
            or prepared_run.writer is not writer
            or prepared_run.run_id != writer.run_id
            or phase_one.prepared_run is not prepared_run
            or phase_one.authority is not authority
            or phase_one.writer is not writer
            or phase_one_diagnostic.prepared_phase is not phase_one
            or phase_one_diagnostic.live_phase is not source_phase_one_live
            or prepared_phase.prepared_run is not prepared_run
            or prepared_phase.authority is not authority
            or prepared_phase.writer is not writer
            or prepared_phase.control_pin is not prepared.control_pin
            or prepared_phase.workspace_pin is not prepared.workspace_pin
            or prepared_phase.workspace != prepared.workspace
            or phase_one.control_pin is not prepared_phase.control_pin
            or phase_one.workspace_pin is not prepared_phase.workspace_pin
            or receipt_gate.execution_id != "execution-1"
            or receipt_control.run_id != writer.run_id
            or receipt_control.selection != receipt_gate.selection
            or phase_one_bridge is None and (
                phase_one_live.control_pin is not prepared_phase.control_pin
                or phase_one_live.workspace_pin is not prepared_phase.workspace_pin
                or receipt_control.control_pin is not prepared_phase.control_pin
                or receipt_control.artifacts is not phase_one_diagnostic.receipt_artifacts
                or receipt_control.transcript_id != phase_one_diagnostic.transcript_id
                or receipt_control.trace_id != phase_one_diagnostic.trace_id
            )
            or phase_one_bridge is not None and (
                phase_one_live.control_pin is not control_pin
                or phase_one_live.workspace_pin is not workspace_pin
                or receipt_control.control_pin is not control_pin
                or receipt_control.artifacts is not phase_one_bridge.receipt_artifacts
                or receipt_control.transcript_id != phase_one_bridge.transcript_id
                or receipt_control.trace_id != phase_one_bridge.trace_id
            )):
        raise RunnerError("registered actual phase-two post-launch binding is invalid")
    registration = _runner_owned_registration(plan.client)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phase_plan(plan.scenario_id) != ("approval", "approved_capture")
            or plan.registration is not registration
            or plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or metadata.scenario_id != plan.scenario_id
            or writer.control_root != prepared.control_root
            or writer.run_root != prepared.control_root / "runs" / prepared_run.run_id
            or phase_one.execution_id != "execution-1"
            or phase_one.phase_index != 1
            or phase_one.phase != "approval"
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase_index != 2
            or prepared_phase.phase != "approved_capture"):
        raise RunnerError("registered actual phase-two post-launch binding is invalid")
    _verify_registered_phase_roots(
        writer=writer,
        workspace=prepared_phase.workspace,
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        trace=trace,
    )
    verify_wrapper(prepared.wrapper_seal)
    entries = _registered_actual_phase_two_pinned_entry_map(
        writer, control_pin=control_pin,
    )
    setup_provenance = _verify_registered_actual_phase_two_setup_provenance(
        prepared_phase, entries=entries, control_pin=control_pin,
    )
    phase_one_conversion = (
        phase_one_diagnostic.conversion
        if phase_one_bridge is None else phase_one_bridge.conversion
    )
    phase_one_expected_execution_ids = (
        None if phase_one_bridge is None else frozenset({"execution-1", "execution-2"})
    )

    # Reconstruct the sealed phase-one release after the pre-launch setup
    # provenance is pinned, then repeat its host join before touching phase
    # two's live context.  This retains the gate as an authority check rather
    # than a payload carried by the post-launch token.
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=phase_one_live,
        control_pin=control_pin,
        expected_execution_ids=phase_one_expected_execution_ids,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")
    reconstructed_gate = _reconstruct_frozen_actual_phase_one_receipt_gate(
        control=receipt_control,
        phase_one=phase_one_live,
        scenario=scenario,
        conversion=phase_one_conversion,
        workspace=workspace_pin.path,
        execution_id="execution-1",
    )
    if not _phase_one_receipt_gate_matches(receipt_gate, reconstructed_gate):
        raise RunnerError("registered actual phase-one receipt gate is no longer valid")
    if not _registered_phase_evidence_is_bound(
        writer=writer,
        workspace=prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=phase_one_live,
        control_pin=control_pin,
        expected_execution_ids=phase_one_expected_execution_ids,
    ):
        raise RunnerError("registered actual phase-one evidence is no longer bound")

    _verify_registered_actual_phase_two_control_bindings(
        prepared_phase, plan=plan, scenario=scenario, control_pin=control_pin,
    )
    phase_one_registration, phase_one_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-1",
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        trusted_context=trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    phase_two_registration, phase_two_trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-2",
        control_pin=control_pin,
        workspace_pin=workspace_pin,
        trusted_context=trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    if (phase_one_registration is not registration
            or phase_two_registration is not registration
            or phase_two_trusted is phase_one_trusted
            or trusted_context.trusted_executables.get("execution-1")
            is not phase_one_trusted
            or trusted_context.trusted_executables.get("execution-2")
            is not phase_two_trusted):
        raise RunnerError("registered actual phase-two post-launch context is invalid")
    _registered_executable_observation(phase_one_trusted)
    _registered_actual_phase_two_live_artifact_join(
        prepared_phase,
        live_phase,
        plan=plan,
        registration=registration,
        trusted_context=trusted_context,
        phase_two_trusted=phase_two_trusted,
        entries=entries,
    )
    trace_identity, trace_sha256, snapshots = _registered_actual_phase_two_post_launch_trace(
        prepared_phase, live_phase, trace=trace,
    )

    expected_types = {
        artifact_id: record[0]
        for artifact_id, record in setup_provenance.items()
    }

    def expect(artifact_id: object, artifact_type: str) -> None:
        if type(artifact_id) is not str or not artifact_id:
            raise RunnerError("registered actual phase-two post-launch inventory is invalid")
        prior = expected_types.setdefault(artifact_id, artifact_type)
        if prior != artifact_type:
            raise RunnerError("registered actual phase-two post-launch inventory is invalid")

    expect("version-2", "version")
    expect("help-2", "help")
    expect("client-executable-2", "client_executable")
    snapshot_ids: list[str] = []
    for snapshot in snapshots:
        if (snapshot.execution_id != "execution-2"
                or snapshot.artifact_id in snapshot_ids
                or snapshot.role not in {"initial", "marker"}):
            raise RunnerError("registered actual phase-two post-launch snapshot is invalid")
        expect(snapshot.artifact_id, "workspace_snapshot")
        snapshot_ids.append(snapshot.artifact_id)
        for item in snapshot.inventory:
            content_id = item.get("content_id")
            digest = item.get("sha256")
            if content_id != "workspace-content-" + str(digest):
                raise RunnerError("registered actual phase-two snapshot content is invalid")
            expect(content_id, "file_capture")
    if set(entries) != set(expected_types):
        raise RunnerError("registered actual phase-two post-launch inventory is invalid")
    suffixes = {
        "version": ".bin",
        "help": ".bin",
        "client_executable": ".json",
        "workspace_snapshot": ".json",
        "file_capture": ".bin",
    }
    for artifact_id, artifact_type in expected_types.items():
        entry = entries.get(artifact_id)
        if not isinstance(entry, Mapping) or entry.get("type") != artifact_type:
            raise RunnerError("registered actual phase-two post-launch inventory is invalid")
        if artifact_id not in setup_provenance:
            suffix = suffixes.get(artifact_type)
            if (suffix is None
                    or entry.get("relative_path") != f"artifacts/{artifact_id}{suffix}"):
                raise RunnerError("registered actual phase-two post-launch locator is invalid")
        _writer_artifact_bytes(
            writer, artifact_id, artifact_type, control_pin=control_pin,
        )
    expected_files = {str(entry["relative_path"]) for entry in entries.values()}
    expected_directories = {
        parent.as_posix()
        for relative in expected_files
        for parent in PurePosixPath(relative).parents
        if parent != PurePosixPath(".")
    }
    directories, files = _pinned_control_tree_inventory(
        control_pin,
        PurePosixPath("runs", writer.run_id).as_posix(),
    )
    terminal_files = {
        "evidence-index.json", "log-attestation.json", "event-log.json", "run-manifest.json",
    }
    if (terminal_files & set(files)
            or set(directories) != expected_directories
            or set(files) != expected_files):
        raise RunnerError("registered actual phase-two post-launch output inventory is invalid")
    PinnedDirectory.verify(control_pin)
    try:
        trace_names = {
            name for name in os.listdir(control_pin.root_fd)
            if name.startswith("runner-trace-")
        }
    except OSError as error:
        raise RunnerError("registered actual phase-two post-launch trace namespace is unavailable") from error
    if trace_names != {"runner-trace-execution-1.jsonl", "runner-trace-execution-2.jsonl"}:
        raise RunnerError("registered actual phase-two post-launch trace namespace is invalid")
    PinnedDirectory.verify(control_pin)
    PinnedDirectory.verify(workspace_pin)
    artifact_provenance = _capture_registered_actual_phase_two_evidence_provenance(
        writer, control_pin=control_pin,
    )
    if (set(artifact_provenance) != set(expected_types)
            or any(artifact_provenance.get(artifact_id) != record
                   for artifact_id, record in setup_provenance.items())):
        raise RunnerError("registered actual phase-two post-launch provenance changed")
    return (
        artifact_provenance,
        MappingProxyType(dict(expected_types)),
        trace_identity,
        trace_sha256,
        tuple(snapshot_ids),
    )


def _registered_actual_phase_two_handoff_relative(
    control_pin: PinnedDirectory,
    path: Path,
) -> str:
    """Derive one sealed control-relative spelling without resolving it again."""

    if not isinstance(control_pin, PinnedDirectory) or not isinstance(path, Path) or not path.is_absolute():
        raise RunnerError("registered actual phase-two handoff control locator is invalid")
    try:
        relative = path.relative_to(control_pin.path).as_posix()
    except ValueError as error:
        raise RunnerError("registered actual phase-two handoff control escaped root") from error
    PinnedDirectory._relative_parts(relative)
    return relative


def _registered_actual_phase_two_handoff_seal_identity(
    seal: ControlFileSeal,
) -> tuple[int, int, int, int, int, int, int, int]:
    """Translate the legacy seal shape into the descriptor snapshot shape."""

    if not isinstance(seal, ControlFileSeal) or type(seal.identity) is not dict:
        raise RunnerError("registered actual phase-two handoff control seal is invalid")
    labels = (
        "device", "inode", "mode", "uid", "nlink", "bytes", "mtime_ns", "ctime_ns",
    )
    identity = tuple(seal.identity.get(label) for label in labels)
    if not _valid_regular_identity(identity):
        raise RunnerError("registered actual phase-two handoff control seal is invalid")
    return identity


def _registered_actual_phase_two_handoff_sealed_controls(
    prepared_phase: _RegisteredActualPreparedPhase,
) -> tuple[tuple[ControlFileSeal, bytes | None], ...]:
    """Return the exact phase-two files that may enter the frozen handoff."""

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or not isinstance(prepared_phase.mcp_config, ControlFileSeal)):
        raise RunnerError("registered actual phase-two handoff controls are invalid")
    controls: list[tuple[ControlFileSeal, bytes | None]] = [
        (prepared_phase.phase_control.config, None),
        (prepared_phase.runner_state, None),
        (prepared_phase.mcp_config, EMPTY_MCP_BYTES),
        (prepared_phase.phase_prompt.seal, prepared_phase.phase_prompt.raw),
    ]
    for seal, raw in prepared_phase.phase_control.fixture_assets.values():
        controls.append((seal, raw))
    if any(not isinstance(seal, ControlFileSeal) or raw is not None and type(raw) is not bytes
           for seal, raw in controls):
        raise RunnerError("registered actual phase-two handoff controls are invalid")
    return tuple(controls)


def _registered_actual_phase_two_handoff_snapshot_seal(
    control_pin: PinnedDirectory,
    seal: ControlFileSeal,
    *,
    expected_raw: bytes | None,
) -> tuple[str, _ControlTraceSnapshot]:
    """Snapshot one already-sealed control file without accepting a new identity."""

    relative = _registered_actual_phase_two_handoff_relative(control_pin, seal.path)
    snapshot = PinnedDirectory.snapshot_relative(control_pin, relative)
    raw, identity = snapshot
    if (identity != _registered_actual_phase_two_handoff_seal_identity(seal)
            or _sha256(raw) != seal.sha256
            or expected_raw is not None and raw != expected_raw):
        raise RunnerError("registered actual phase-two handoff control changed")
    return relative, snapshot


def _registered_actual_phase_two_handoff_delta(
    current: bytes,
    previous: bytes,
    *,
    label: str,
) -> bytes:
    """Retain an append-only raw phase suffix while allowing no phase-two rows."""

    if (type(current) is not bytes
            or type(previous) is not bytes
            or not current.endswith(b"\n")
            or previous and (
                not previous.endswith(b"\n") or not current.startswith(previous)
            )):
        raise RunnerError(f"{label} was replaced or is incomplete")
    return current[len(previous):]


def _registered_actual_phase_two_handoff_capture(
    snapshots: Mapping[str, _ControlTraceSnapshot],
    owners: dict[str, str],
    relative: object,
    command_id: str,
    *,
    root: str,
    label: str,
) -> bytes:
    """Select one receipt-bound capture named by a frozen raw row."""

    relative = _private_receipt_relative_path(relative)
    path = PurePosixPath(relative)
    if (len(path.parts) < 3
            or path.parts[0] != root
            or path.parts[1] != command_id):
        raise RunnerError(f"invalid registered actual phase-two {label} capture path")
    snapshot = snapshots.get(relative)
    if snapshot is None:
        raise RunnerError(f"registered actual phase-two {label} capture lacks a receipt")
    owner = command_id + ":" + label
    if relative in owners:
        raise RunnerError("registered actual phase-two raw capture path is reused")
    owners[relative] = owner
    return snapshot[0]


def _registered_actual_phase_two_handoff_capture_entry(
    snapshots: Mapping[str, _ControlTraceSnapshot],
    owners: dict[str, str],
    entry: object,
    command_id: str,
    *,
    root: str,
    label: str,
) -> None:
    """Validate and retain one nested source/receipt/preapply capture row."""

    if (type(entry) is not dict
            or set(entry) != {"path", "capture_path", "sha256", "bytes"}
            or type(entry.get("path")) is not str
            or not entry["path"]
            or not _is_hex64(entry.get("sha256"))
            or type(entry.get("bytes")) is not int
            or entry["bytes"] < 0):
        raise RunnerError(f"invalid registered actual phase-two {label} capture")
    raw = _registered_actual_phase_two_handoff_capture(
        snapshots,
        owners,
        entry["capture_path"],
        command_id,
        root=root,
        label=label,
    )
    if len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]:
        raise RunnerError(f"registered actual phase-two {label} capture digest mismatch")


def _registered_actual_phase_two_handoff_requires_preapply(argv: list[str]) -> bool:
    """Recognize the one apply grammar that must have a pre-dispatch capture."""

    if len(argv) < 4 or argv[:4] != ["./brain", "--json", "wiki", "apply"]:
        return False
    if len(argv) != 6 or argv[4] != "--manifest" or type(argv[-1]) is not str:
        raise RunnerError("registered actual phase-two wiki apply command is invalid")
    relative = argv[-1]
    path = PurePosixPath(relative)
    if (path.is_absolute()
            or path.as_posix() != relative
            or len(path.parts) != 4
            or path.parts[:2] != (".brain", "wiki-staging")
            or not path.parts[2].startswith("wstg_")
            or path.parts[-1] != "manifest.json"):
        raise RunnerError("registered actual phase-two wiki apply command is invalid")
    return True


def _freeze_registered_actual_phase_two_raw_control_handoff(
    phase_one_diagnostic: _RegisteredActualPhaseOneDiagnostic,
    prepared_phase: _RegisteredActualPreparedPhase,
    receipt_verification: _RegisteredActualPhaseTwoReceiptLedgerVerification,
    *,
    trace: ControlTraceWriter,
    control_pin: PinnedDirectory | None = None,
    phase_one_bridge: _RegisteredActualPhaseOnePrivateLaunchBridge | None = None,
    expected_trace_identity: tuple[int, int, int, int, int, int, int, int],
    expected_trace_sha256: str,
) -> _RegisteredActualPhaseTwoRawControlHandoff:
    """Freeze the complete private raw/control input closure for later indexing.

    Receipt-bound raw files are deliberately consumed from
    ``receipt_verification`` rather than reread here.  The verifier has
    already bound their bytes and identities to FD-time producer receipts.
    """

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(receipt_verification)
            is not _RegisteredActualPhaseTwoReceiptLedgerVerification
            or type(trace) is not ControlTraceWriter
            or phase_one_bridge is not None
            and type(phase_one_bridge) is not _RegisteredActualPhaseOnePrivateLaunchBridge
            or prepared_phase.execution_id != "execution-2"
            or prepared_phase.phase != "approved_capture"):
        raise RunnerError("registered actual phase-two raw/control handoff inputs are invalid")
    prepared_phase.__post_init__()
    receipt_verification.__post_init__()
    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != prepared_phase.writer.control_root):
        raise RunnerError("registered actual phase-two raw/control handoff pin is invalid")
    if phase_one_bridge is None:
        phase_one_diagnostic.__post_init__()
        conversion = phase_one_diagnostic.conversion
    else:
        phase_one_bridge.assert_current(
            control_pin=control_pin,
            workspace_pin=phase_one_bridge.live_phase.workspace_pin,
            trusted_context=phase_one_bridge.live_phase.trusted_context,
        )
        conversion = phase_one_bridge.conversion
    raw_snapshots = dict(receipt_verification.raw_snapshots)
    raw_absent_paths = receipt_verification.raw_absent_paths
    raw_append_command_ids = receipt_verification.raw_append_command_ids
    # Phase two owns the runner trace, not the legacy generic shim trace.  A
    # receipt for that retained phase-one journal would otherwise be a
    # validated-but-uninterpreted delta outside this handoff's closed surface.
    if "brain-shim-trace.jsonl" in receipt_verification.raw_receipt_paths:
        raise RunnerError("registered actual phase-two generic shim trace is unsupported")
    trace_snapshot = receipt_verification.trace_snapshot
    if (trace_snapshot is None
            or trace_snapshot[1] != expected_trace_identity
            or _sha256(trace_snapshot[0]) != expected_trace_sha256
            or trace.control_pin is not control_pin
            or trace.control_root != control_pin.path
            or trace.path != control_pin.path / "runner-trace-execution-2.jsonl"
            or trace.lock_path != control_pin.path / ".runner-trace.lock"):
        raise RunnerError("registered actual phase-two handoff trace changed")
    trace_rows = tuple(
        _strict_json(line, label="registered actual phase-two handoff trace")
        for line in trace_snapshot[0].splitlines()
    )
    validate_trace_records(trace_rows)
    _reject_native_inside_command_interval(trace_rows)
    trace_by_sequence = {row["sequence"]: row for row in trace_rows}
    index_snapshot = raw_snapshots.get("brain-shim-capture-index.jsonl")
    command_snapshot = raw_snapshots.get("brain-shim-command-log.jsonl")
    if index_snapshot is None or command_snapshot is None:
        raise RunnerError("registered actual phase-two raw journals are unavailable")
    phase_index = _registered_actual_phase_two_handoff_delta(
        index_snapshot[0], conversion.raw_index, label="registered actual phase-two capture index",
    )
    phase_commands = _registered_actual_phase_two_handoff_delta(
        command_snapshot[0], conversion.raw_command_log,
        label="registered actual phase-two command log",
    )
    preapply_snapshot = raw_snapshots.get("runner-preapply-manifests.jsonl")
    if preapply_snapshot is None:
        if conversion.raw_preapply_manifests:
            raise RunnerError("registered actual phase-two preapply journal disappeared")
        phase_preapply = b""
    else:
        phase_preapply = _registered_actual_phase_two_handoff_delta(
            preapply_snapshot[0], conversion.raw_preapply_manifests,
            label="registered actual phase-two preapply journal",
        )
    try:
        index_rows = tuple(
            _strict_json(line, label="registered actual phase-two capture index")
            for line in phase_index.splitlines()
        )
        command_rows = tuple(
            _strict_json(line, label="registered actual phase-two command log")
            for line in phase_commands.splitlines()
        )
    except RunnerError:
        raise
    if len(index_rows) != len(command_rows):
        raise RunnerError("registered actual phase-two raw journal row count mismatch")
    capture_owners: dict[str, str] = {}
    command_ids: set[str] = set()
    index_command_order: list[str] = []
    argv_by_command: dict[str, list[str]] = {}
    expected_preapply_ids: set[str] = set()
    for position, (row, command_row) in enumerate(zip(index_rows, command_rows), start=1):
        expected_row = {
            "command_id", "argv", "argv_sha256", "exit_code", "result_path", "result_sha256",
            "source_state_path", "receipt_artifacts_path", "start_sequence", "end_sequence", "phase", "timestamp",
        }
        if type(row) is not dict or set(row) != expected_row:
            raise RunnerError("invalid registered actual phase-two capture index row")
        command_id = _private_receipt_command_id(row.get("command_id"))
        argv = row.get("argv")
        if (command_id in command_ids
                or type(argv) is not list
                or any(type(value) is not str for value in argv)
                or _sha256(_canonical_json(argv)) != row.get("argv_sha256")
                or type(row.get("exit_code")) is not int
                or not _is_hex64(row.get("result_sha256"))
                or type(row.get("timestamp")) is not str
                or type(row.get("start_sequence")) is not int
                or type(row.get("end_sequence")) is not int
                or row["start_sequence"] <= 0
                or row["end_sequence"] <= row["start_sequence"]
                or row.get("phase") != "approved_capture"):
            raise RunnerError("invalid registered actual phase-two capture index row")
        start_trace = trace_by_sequence.get(row["start_sequence"])
        end_trace = trace_by_sequence.get(row["end_sequence"])
        if (start_trace != {
                    "sequence": row["start_sequence"],
                    "kind": "command_start",
                    "command_id": command_id,
                }
                or end_trace != {
                    "sequence": row["end_sequence"],
                    "kind": "command_end",
                    "command_id": command_id,
                }):
            raise RunnerError("registered actual phase-two trace command interval is invalid")
        source_trace_rows = tuple(
            trace_row
            for trace_row in trace_rows
            if (row["start_sequence"] < trace_row["sequence"] < row["end_sequence"]
                and trace_row.get("kind") == "source_state")
        )
        source_state_path = row["source_state_path"]
        if source_state_path is None:
            if source_trace_rows:
                raise RunnerError("registered actual phase-two trace source state is invalid")
        elif (len(source_trace_rows) != 1
                or type(source_trace_rows[0]) is not dict
                or set(source_trace_rows[0]) != {
                    "sequence", "kind", "command_id", "capture_path",
                }
                or source_trace_rows[0].get("command_id") != command_id
                or source_trace_rows[0].get("capture_path") != source_state_path):
            raise RunnerError("registered actual phase-two trace source state is invalid")
        command_ids.add(command_id)
        index_command_order.append(command_id)
        argv_by_command[command_id] = argv
        if _registered_actual_phase_two_handoff_requires_preapply(argv):
            expected_preapply_ids.add(command_id)
        expected_command = {
            "argv": argv,
            "exit_code": row["exit_code"],
            "result_sha256": row["result_sha256"],
            "timestamp": row["timestamp"],
        }
        if type(command_row) is not dict or command_row != expected_command:
            raise RunnerError("registered actual phase-two raw journal mismatch")
        result_raw = _registered_actual_phase_two_handoff_capture(
            raw_snapshots, capture_owners, row["result_path"], command_id,
            root="brain-shim-captures", label="result",
        )
        if _sha256(result_raw) != row["result_sha256"]:
            raise RunnerError("registered actual phase-two result digest mismatch")
        state_path = source_state_path
        if state_path is not None:
            state_raw = _registered_actual_phase_two_handoff_capture(
                raw_snapshots, capture_owners, state_path, command_id,
                root="brain-shim-captures", label="source-state",
            )
            state = _strict_json(state_raw, label="registered actual phase-two source state")
            expected_state = {
                "schema_version", "command_id", "command", "capture_point", "result_id", "corpus_revision",
                "records", "files", "pending",
            }
            if (type(state) is not dict
                    or set(state) != expected_state
                    or state.get("schema_version") != 1
                    or state.get("command_id") != command_id
                    or state.get("capture_point") != "after_command_before_return"
                    or type(state.get("records")) is not list
                    or type(state.get("files")) is not list):
                raise RunnerError("invalid registered actual phase-two source state")
            for entry in state["records"]:
                _registered_actual_phase_two_handoff_capture_entry(
                    raw_snapshots, capture_owners, entry, command_id,
                    root="brain-shim-captures", label="source record",
                )
            for entry in state["files"]:
                _registered_actual_phase_two_handoff_capture_entry(
                    raw_snapshots, capture_owners, entry, command_id,
                    root="brain-shim-captures", label="source file",
                )
            if state["pending"] is not None:
                _registered_actual_phase_two_handoff_capture_entry(
                    raw_snapshots, capture_owners, state["pending"], command_id,
                    root="brain-shim-captures", label="pending source",
                )
        receipt_path = row["receipt_artifacts_path"]
        if receipt_path is not None:
            receipt_raw = _registered_actual_phase_two_handoff_capture(
                raw_snapshots, capture_owners, receipt_path, command_id,
                root="brain-shim-captures", label="receipt-artifacts",
            )
            receipt = _strict_json(receipt_raw, label="registered actual phase-two receipt artifacts")
            expected_receipt = {
                "schema_version", "command_id", "capture_point", "result_id", "stream", "durable", "delivery",
            }
            if (type(receipt) is not dict
                    or set(receipt) != expected_receipt
                    or receipt.get("schema_version") != 1
                    or receipt.get("command_id") != command_id
                    or receipt.get("capture_point") != "after_command_before_return"):
                raise RunnerError("invalid registered actual phase-two receipt artifacts")
            for label in ("stream", "durable", "delivery"):
                if receipt[label] is not None:
                    _registered_actual_phase_two_handoff_capture_entry(
                        raw_snapshots, capture_owners, receipt[label], command_id,
                        root="brain-shim-captures", label=label,
                    )
    trace_command_starts = {
        row.get("command_id") for row in trace_rows if row.get("kind") == "command_start"
    }
    trace_command_ends = {
        row.get("command_id") for row in trace_rows if row.get("kind") == "command_end"
    }
    if trace_command_starts != command_ids or trace_command_ends != command_ids:
        raise RunnerError("registered actual phase-two trace command closure is invalid")
    if (tuple(index_command_order)
            != raw_append_command_ids.get("brain-shim-capture-index.jsonl", ())
            or tuple(index_command_order)
            != raw_append_command_ids.get("brain-shim-command-log.jsonl", ())):
        raise RunnerError("registered actual phase-two raw journal ownership is invalid")
    preapply_ids: set[str] = set()
    preapply_command_order: list[str] = []
    if phase_preapply:
        for line in phase_preapply.splitlines():
            row = _strict_json(line, label="registered actual phase-two preapply journal")
            expected_preapply = {
                "command_id", "argv", "argv_sha256", "path", "capture_path", "sha256", "bytes",
            }
            if type(row) is not dict or set(row) != expected_preapply:
                raise RunnerError("invalid registered actual phase-two preapply journal")
            command_id = _private_receipt_command_id(row.get("command_id"))
            argv = row.get("argv")
            if (command_id not in expected_preapply_ids
                    or command_id in preapply_ids
                    or type(argv) is not list
                    or any(type(value) is not str for value in argv)
                    or _sha256(_canonical_json(argv)) != row.get("argv_sha256")
                    or argv_by_command.get(command_id) != argv
                    or len(argv) != 6
                    or argv[:5] != ["./brain", "--json", "wiki", "apply", "--manifest"]
                    or type(row.get("path")) is not str
                    or not row["path"]
                    or row["path"] != argv[-1]
                    or not _is_hex64(row.get("sha256"))
                    or type(row.get("bytes")) is not int
                    or row["bytes"] < 0):
                raise RunnerError("invalid registered actual phase-two preapply journal")
            preapply_ids.add(command_id)
            preapply_command_order.append(command_id)
            capture_raw = _registered_actual_phase_two_handoff_capture(
                raw_snapshots, capture_owners, row["capture_path"], command_id,
                root="runner-preapply-manifests", label="preapply",
            )
            if len(capture_raw) != row["bytes"] or _sha256(capture_raw) != row["sha256"]:
                raise RunnerError("registered actual phase-two preapply capture digest mismatch")
    if preapply_ids != expected_preapply_ids:
        raise RunnerError("registered actual phase-two preapply capture closure is incomplete")
    if (tuple(preapply_command_order)
            != raw_append_command_ids.get("runner-preapply-manifests.jsonl", ())):
        raise RunnerError("registered actual phase-two preapply ownership is invalid")
    dynamic_paths = {
        relative for relative in raw_snapshots
        if relative.startswith("brain-shim-captures/")
        or relative.startswith("runner-preapply-manifests/")
    }
    if dynamic_paths != set(capture_owners):
        raise RunnerError("registered actual phase-two raw capture closure is incomplete")
    controls: dict[str, _ControlTraceSnapshot] = {}
    for seal, expected_raw in _registered_actual_phase_two_handoff_sealed_controls(prepared_phase):
        relative, snapshot = _registered_actual_phase_two_handoff_snapshot_seal(
            control_pin, seal, expected_raw=expected_raw,
        )
        if relative in controls:
            raise RunnerError("registered actual phase-two handoff control paths collide")
        controls[relative] = snapshot
    handoff = _RegisteredActualPhaseTwoRawControlHandoff(
        raw_snapshots=raw_snapshots,
        raw_absent_paths=raw_absent_paths,
        raw_append_command_ids=raw_append_command_ids,
        trace_snapshot=trace_snapshot,
        control_snapshots=controls,
        phase_one_raw_index=conversion.raw_index,
        phase_one_raw_command_log=conversion.raw_command_log,
        phase_one_raw_preapply_manifests=conversion.raw_preapply_manifests,
    )
    handoff.verify(control_pin)
    return handoff


def _verify_registered_actual_phase_two_raw_control_handoff(
    phase_one_diagnostic: _RegisteredActualPhaseOneDiagnostic,
    prepared_phase: _RegisteredActualPreparedPhase,
    handoff: _RegisteredActualPhaseTwoRawControlHandoff,
    receipt_verification: _RegisteredActualPhaseTwoReceiptLedgerVerification,
    *,
    control_pin: PinnedDirectory | None = None,
    phase_one_bridge: _RegisteredActualPhaseOnePrivateLaunchBridge | None = None,
) -> None:
    """Require one retained handoff to remain exact without taking a baseline."""

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(handoff) is not _RegisteredActualPhaseTwoRawControlHandoff
            or type(receipt_verification)
            is not _RegisteredActualPhaseTwoReceiptLedgerVerification
            or phase_one_bridge is not None
            and type(phase_one_bridge) is not _RegisteredActualPhaseOnePrivateLaunchBridge):
        raise RunnerError("registered actual phase-two raw/control handoff is invalid")
    handoff.__post_init__()
    receipt_verification.__post_init__()
    conversion = (
        phase_one_diagnostic.conversion
        if phase_one_bridge is None else phase_one_bridge.conversion
    )
    if (handoff.phase_one_raw_index != conversion.raw_index
            or handoff.phase_one_raw_command_log != conversion.raw_command_log
            or handoff.phase_one_raw_preapply_manifests != conversion.raw_preapply_manifests
            or handoff.raw_snapshots != receipt_verification.raw_snapshots
            or handoff.raw_absent_paths != receipt_verification.raw_absent_paths
            or handoff.raw_append_command_ids != receipt_verification.raw_append_command_ids
            or handoff.trace_snapshot != receipt_verification.trace_snapshot):
        raise RunnerError("registered actual phase-two raw/control handoff changed")
    if control_pin is None:
        control_pin = prepared_phase.control_pin
    if (not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or control_pin.path != prepared_phase.writer.control_root):
        raise RunnerError("registered actual phase-two raw/control handoff pin is invalid")
    expected_controls: dict[str, _ControlTraceSnapshot] = {}
    for seal, expected_raw in _registered_actual_phase_two_handoff_sealed_controls(prepared_phase):
        relative = _registered_actual_phase_two_handoff_relative(control_pin, seal.path)
        snapshot = handoff.control_snapshots.get(relative)
        if snapshot is None:
            raise RunnerError("registered actual phase-two handoff control is missing")
        raw, identity = snapshot
        if (identity != _registered_actual_phase_two_handoff_seal_identity(seal)
                or _sha256(raw) != seal.sha256
                or expected_raw is not None and raw != expected_raw):
            raise RunnerError("registered actual phase-two handoff control changed")
        expected_controls[relative] = snapshot
    if handoff.control_snapshots != expected_controls:
        raise RunnerError("registered actual phase-two handoff control closure changed")
    handoff.verify(control_pin)


def _capture_registered_actual_phase_two_post_launch_provenance(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: "PhaseOneReceiptGate",
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    *,
    receipt_ledgers: _RegisteredActualPhaseTwoReceiptLedgers,
    launch_binding: _RegisteredActualPhaseTwoLaunchBinding,
) -> _RegisteredActualPhaseTwoPostLaunchToken:
    """Create one private, frozen phase-two retention token without writes."""

    if (type(receipt_ledgers) is not _RegisteredActualPhaseTwoReceiptLedgers
            or type(launch_binding) is not _RegisteredActualPhaseTwoLaunchBinding
            or launch_binding.prepared_run is not prepared_run
            or launch_binding.phase_one_diagnostic is not phase_one_diagnostic):
        raise RunnerError("registered actual phase-two receipt ledgers are required")
    launch_binding._assert_token_fields(
        prepared_phase,
        allow_marker_snapshots=True,
    )
    phase_one_bridge = launch_binding.phase_one_bridge
    phase_one_bridge.raw_predecessors.require_prelaunch_match(
        receipt_ledgers.raw_prelaunch,
    )
    _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, receipt_ledgers, control_pin=launch_binding.control_pin,
    )
    receipt_control = _registered_actual_phase_two_private_phase_one_receipt_control(
        phase_one_bridge,
        receipt_gate,
    )
    artifact_provenance, expected_artifact_types, trace_identity, trace_sha256, snapshot_ids = (
        _registered_actual_phase_two_post_launch_facts(
            prepared_run,
            phase_one_diagnostic,
            receipt_gate,
            receipt_control,
            prepared_phase,
            live_phase,
            trace=launch_binding.trace,
            trusted_context=launch_binding.trusted_context,
            phase_one_bridge=phase_one_bridge,
        )
    )
    receipt_verification = _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, receipt_ledgers, control_pin=launch_binding.control_pin,
    )
    handoff = _freeze_registered_actual_phase_two_raw_control_handoff(
        phase_one_diagnostic,
        prepared_phase,
        receipt_verification,
        trace=launch_binding.trace,
        control_pin=launch_binding.control_pin,
        phase_one_bridge=phase_one_bridge,
        expected_trace_identity=trace_identity,
        expected_trace_sha256=trace_sha256,
    )
    closing_verification = _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, receipt_ledgers, control_pin=launch_binding.control_pin,
    )
    _verify_registered_actual_phase_two_raw_control_handoff(
        phase_one_diagnostic,
        prepared_phase,
        handoff,
        closing_verification,
        control_pin=launch_binding.control_pin,
        phase_one_bridge=phase_one_bridge,
    )
    token = _RegisteredActualPhaseTwoPostLaunchToken(
        run_id=prepared_run.run_id,
        execution_id="execution-2",
        prepared_phase=prepared_phase,
        live_phase=live_phase,
        receipt_gate=receipt_gate,
        receipt_control=receipt_control,
        phase_one_bridge=phase_one_bridge,
        artifact_provenance=artifact_provenance,
        expected_artifact_types=expected_artifact_types,
        trace_identity=trace_identity,
        trace_sha256=trace_sha256,
        snapshot_artifact_ids=snapshot_ids,
        raw_control_handoff=handoff,
        receipt_ledgers=receipt_ledgers,
    )
    _read_registered_actual_two_phase_host_join(phase_one_diagnostic, token)
    return token


def _verify_registered_actual_phase_two_post_launch_provenance(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: "PhaseOneReceiptGate",
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    token: _RegisteredActualPhaseTwoPostLaunchToken,
) -> None:
    """Require the retained post-launch host closure before any future use.

    The verifier intentionally returns no index-ready value and performs no
    evidence write.  A later reviewed indexer must invoke it before it does
    anything else, but this disconnected slice does not provide that indexer.
    """

    if (type(token) is not _RegisteredActualPhaseTwoPostLaunchToken
            or token.prepared_phase is not prepared_phase
            or token.live_phase is not live_phase
            or token.receipt_gate is not receipt_gate
            or token.receipt_control.selection != receipt_gate.selection
            or token.receipt_control.artifacts is not token.phase_one_bridge.receipt_artifacts
            or token.receipt_control.transcript_id != token.phase_one_bridge.transcript_id
            or token.receipt_control.trace_id != token.phase_one_bridge.trace_id):
        raise RunnerError("registered actual phase-two post-launch token is invalid")
    token.__post_init__()
    control_pin, _workspace_pin = _registered_actual_phase_two_live_roots(
        prepared_phase, live_phase,
    )
    phase_one_bridge = token.phase_one_bridge
    phase_one_bridge.raw_predecessors.require_prelaunch_match(
        token.receipt_ledgers.raw_prelaunch,
    )
    receipt_verification = _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, token.receipt_ledgers, control_pin=control_pin,
    )
    _verify_registered_actual_phase_two_raw_control_handoff(
        phase_one_diagnostic,
        prepared_phase,
        token.raw_control_handoff,
        receipt_verification,
        control_pin=control_pin,
        phase_one_bridge=phase_one_bridge,
    )
    retained_trace = _registered_actual_phase_two_canonical_retained_trace(
        prepared_phase, live_phase=live_phase,
    )
    artifact_provenance, expected_artifact_types, trace_identity, trace_sha256, snapshot_ids = (
        _registered_actual_phase_two_post_launch_facts(
            prepared_run,
            phase_one_diagnostic,
            receipt_gate,
            token.receipt_control,
            prepared_phase,
            live_phase,
            trace=retained_trace,
            trusted_context=live_phase.trusted_context,
            phase_one_bridge=phase_one_bridge,
        )
    )
    closing_verification = _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, token.receipt_ledgers, control_pin=control_pin,
    )
    _verify_registered_actual_phase_two_raw_control_handoff(
        phase_one_diagnostic,
        prepared_phase,
        token.raw_control_handoff,
        closing_verification,
        control_pin=control_pin,
        phase_one_bridge=phase_one_bridge,
    )
    if (token.run_id != prepared_run.run_id
            or token.execution_id != "execution-2"
            or artifact_provenance != token.artifact_provenance
            or expected_artifact_types != token.expected_artifact_types
            or trace_identity != token.trace_identity
            or trace_sha256 != token.trace_sha256
            or snapshot_ids != token.snapshot_artifact_ids):
        raise RunnerError("registered actual phase-two post-launch provenance changed")
    _read_registered_actual_two_phase_host_join(phase_one_diagnostic, token)


def _launch_registered_actual_phase_two(
    prepared_run: _RegisteredActualPreparedRun,
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: "PhaseOneReceiptGate",
    prepared_phase: _RegisteredActualPreparedPhase,
) -> _RegisteredActualPhaseTwoLiveLaunch:
    """Privately launch a sealed phase two without wiring it into any route.

    This wrapper owns every launch value and accepts neither client adapters
    nor argv/environment/Popen inputs.  It remains disconnected from the
    actual dispatcher, CLI, semantic projection, capability artifacts, and
    pass construction until their complete reviewed lifecycle exists.
    """

    if type(prepared_phase) is not _RegisteredActualPreparedPhase:
        raise RunnerError("registered actual phase-two launch inputs are invalid")
    launch_binding = _registered_actual_phase_two_launch_binding_for(prepared_phase)
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    prepared_phase.__post_init__()
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    if (launch_binding.prepared_run is not prepared_run
            or launch_binding.phase_one_diagnostic is not phase_one_diagnostic):
        raise RunnerError("registered actual phase-two launch binding is invalid")
    launch_raw_snapshot = launch_binding.raw_predecessor_snapshot
    launch_evidence_provenance = launch_binding.evidence_provenance
    launch_workspace_inventory = launch_binding.workspace_inventory
    if (not _registered_actual_phase_one_raw_predecessor_snapshot_is_valid(launch_raw_snapshot)
            or not isinstance(launch_evidence_provenance, Mapping)
            or not launch_evidence_provenance
            or not _registered_actual_phase_two_workspace_inventory_is_valid(
                launch_workspace_inventory,
            )):
        raise RunnerError("registered actual phase-two retained setup state is invalid")
    _revalidate_registered_actual_phase_two_launch_gate(
        prepared_run=prepared_run,
        phase_one_diagnostic=phase_one_diagnostic,
        receipt_gate=receipt_gate,
        prepared_phase=prepared_phase,
        pre_popen=False,
        expected_raw_snapshot=launch_raw_snapshot,
        expected_evidence_provenance=launch_evidence_provenance,
        expected_workspace_inventory=launch_workspace_inventory,
        launch_binding=launch_binding,
    )
    authority = launch_binding.authority
    plan = authority.plan
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    _verify_registered_actual_phase_two_control_bindings(
        prepared_phase,
        plan=plan,
        scenario=scenario,
        control_pin=launch_binding.control_pin,
    )
    launch_binding.assert_current(prepared_phase, trace_receipt_sink=None)
    phase_argv = build_effective_argv(
        launch_binding.client,
        launch_binding.symbolic_template,
        launch_binding.workspace,
        launch_binding.mcp_path,
        launch_binding.expected_prompt_raw.decode("utf-8", "strict"),
    )
    environment = {
        "PATH": "/usr/bin:/bin",
        "HOME": str(launch_binding.control_root / "home"),
        "LANG": "C.UTF-8",
        CONTROL_ENV: str(launch_binding.control_root),
        RUNNER_STATE_ENV: str(launch_binding.runner_state_path),
    }

    receipt_ledgers: _RegisteredActualPhaseTwoReceiptLedgers | None = None
    trace_receipt_sink: _PrivateReceiptLedgerSink | None = None
    launch_consumed = False

    def pre_popen_guard() -> None:
        nonlocal receipt_ledgers, trace_receipt_sink, launch_consumed
        pre_allocation_control_tree = _revalidate_registered_actual_phase_two_launch_gate(
            prepared_run=prepared_run,
            phase_one_diagnostic=phase_one_diagnostic,
            receipt_gate=receipt_gate,
            prepared_phase=prepared_phase,
            pre_popen=True,
            expected_raw_snapshot=launch_raw_snapshot,
            expected_evidence_provenance=launch_evidence_provenance,
            expected_workspace_inventory=launch_workspace_inventory,
            launch_binding=launch_binding,
        )
        if receipt_ledgers is not None:
            raise RunnerError("registered actual phase-two receipt ledgers were allocated twice")
        _begin_registered_actual_phase_two_launch_consumption(
            prepared_phase, launch_binding,
        )
        launch_consumed = True
        # Allocation follows the final no-write launch revalidation and
        # precedes the sole Popen boundary.  Both sinks are private closures;
        # no state, environment, evidence, capability, or public schema is
        # widened to carry their names or contents.
        receipt_ledgers = _allocate_registered_actual_phase_two_receipt_ledgers(
            prepared_run,
            phase_one_diagnostic,
            prepared_phase,
            expected_raw_snapshot=launch_raw_snapshot,
            expected_pre_allocation_control_tree=pre_allocation_control_tree,
            expected_workspace_inventory=launch_workspace_inventory,
            launch_binding=launch_binding,
        )
        trace_receipt_sink = _PrivateReceiptLedgerSink(
            launch_binding.control_pin, receipt_ledgers.trace_ledger,
        )
        launch_binding.assert_current(
            prepared_phase,
            receipt_ledgers=receipt_ledgers,
            trace_receipt_sink=None,
        )
        launch_binding.trace._arm_private_trace_receipts(trace_receipt_sink.append_trace)
        live_identity_tracker.arm_private_receipt_ledgers(
            receipt_ledgers,
            trace_receipt_sink=trace_receipt_sink,
        )
        _revalidate_registered_actual_phase_two_post_allocation_boundary(
            phase_one_diagnostic,
            prepared_phase,
            receipt_ledgers,
            expected_pre_allocation_control_tree=pre_allocation_control_tree,
            expected_raw_snapshot=launch_raw_snapshot,
            expected_evidence_provenance=launch_evidence_provenance,
            expected_workspace_inventory=launch_workspace_inventory,
            launch_binding=launch_binding,
            trace_receipt_sink=trace_receipt_sink,
        )

    # Retain the setup closure before the generic live launcher begins
    # creating phase-two evidence.  Each private callback below verifies all
    # previously retained identities before admitting the one next live
    # production step, so a same-byte replacement during process drain/wait
    # cannot become the first identity observed by the eventual token.
    live_identity_tracker = _RegisteredActualPhaseTwoLiveIdentityTracker(
        prepared_phase, launch_binding,
    )
    live_identity_tracker.checkpoint("initial")
    live_phase: RegisteredLivePhase | None = None
    try:
        live_phase = _launch_registered_live_phase(
            writer=launch_binding.writer,
            client=launch_binding.client,
            execution_id="execution-2",
            phase="approved_capture",
            phase_index=2,
            workspace=launch_binding.workspace,
            control_pin=launch_binding.control_pin,
            workspace_pin=launch_binding.workspace_pin,
            argv=phase_argv,
            environment=environment,
            stdin=b"",
            trace=launch_binding.trace,
            transcript_id="transcript-2",
            on_native_record=launch_binding.private_on_native_record,
            probe_runner=None,
            popen_factory=subprocess.Popen,
            trusted_context=launch_binding.trusted_context,
            pre_popen_guard=pre_popen_guard,
            live_artifact_checkpoint=live_identity_tracker.checkpoint,
            live_trace_provider=live_identity_tracker.trace_append_expectation,
            after_live_native_trace_append=live_identity_tracker.accept_native_trace_append,
        )
    finally:
        try:
            launch_binding._assert_token_fields(
                prepared_phase,
                trace_receipt_sink=(
                    trace_receipt_sink if receipt_ledgers is not None else None
                ),
                allow_marker_snapshots=True,
            )
            _verify_registered_actual_phase_two_control_bindings(
                prepared_phase,
                plan=plan,
                scenario=scenario,
                control_pin=launch_binding.control_pin,
            )
            _verify_registered_phase_roots(
                writer=launch_binding.writer,
                workspace=launch_binding.workspace,
                control_pin=launch_binding.control_pin,
                workspace_pin=launch_binding.workspace_pin,
                trace=launch_binding.trace,
            )
        finally:
            if launch_consumed:
                _revoke_registered_actual_phase_two_launch_binding(
                    prepared_phase, launch_binding,
                )
    if type(live_phase) is not RegisteredLivePhase:
        raise RunnerError("registered actual phase-two live launch is invalid")
    if receipt_ledgers is None:
        raise RunnerError("registered actual phase-two receipt ledgers were not allocated")
    if trace_receipt_sink is None:
        raise RunnerError("registered actual phase-two trace receipt sink was not armed")
    launch_binding._assert_token_fields(
        prepared_phase,
        trace_receipt_sink=trace_receipt_sink,
        allow_marker_snapshots=True,
    )
    live_identity_tracker.finalize()
    _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase, receipt_ledgers, control_pin=launch_binding.control_pin,
    )
    post_launch_token = _capture_registered_actual_phase_two_post_launch_provenance(
        prepared_run,
        phase_one_diagnostic,
        receipt_gate,
        prepared_phase,
        live_phase,
        receipt_ledgers=receipt_ledgers,
        launch_binding=launch_binding,
    )
    retained_trace = live_identity_tracker.trace_snapshot
    if (retained_trace is None
            or post_launch_token.artifact_provenance != live_identity_tracker.artifact_provenance
            or post_launch_token.trace_identity != retained_trace[1]
            or post_launch_token.trace_sha256 != _sha256(retained_trace[0])):
        raise RunnerError("registered actual phase-two live provenance changed")
    # The post-launch closure is itself a sequence of hostile-host reads.
    # Recheck the live baselines once more before letting the private wrapper
    # escape, rather than relying on a later verifier to notice a final race.
    live_identity_tracker.finalize()
    return _RegisteredActualPhaseTwoLiveLaunch(live_phase, post_launch_token)


def _build_marker_diff_references(
    writer: EvidenceWriter,
    *,
    run_id: str,
    required_events: Sequence[str],
    markers: Sequence[SemanticMarkerEvidence],
    initial_snapshots: Mapping[str, WorkspaceSnapshot],
    snapshots: Sequence[WorkspaceSnapshot],
    execution_order: Mapping[str, int],
    trace_snapshot_ids: Mapping[tuple[str, int], str] | None = None,
) -> dict[str, dict[str, str]]:
    """Create diff references only from paired marker-time host snapshots."""

    try:
        from tests.evals import event_log_contract as contract
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("event contract unavailable for diff capture") from error
    required = set(required_events)
    initial: dict[str, WorkspaceSnapshot] = {}
    for execution_id, snapshot in initial_snapshots.items():
        if type(execution_id) is not str or execution_id in initial:
            raise RunnerError("initial workspace snapshot key invalid")
        loaded = _indexed_workspace_snapshot(writer, snapshot)
        if (loaded.role != "initial" or loaded.execution_id != execution_id
                or loaded.trace_sequence != 0):
            raise RunnerError("initial workspace snapshot binding invalid")
        initial[execution_id] = loaded
    by_marker: dict[tuple[str, int], WorkspaceSnapshot] = {}
    for snapshot in snapshots:
        loaded = _indexed_workspace_snapshot(writer, snapshot)
        key = (loaded.execution_id, loaded.trace_sequence)
        if (loaded.role != "marker" or loaded.trace_sequence <= 0
                or key in by_marker):
            raise RunnerError("invalid marker workspace snapshot")
        by_marker[key] = loaded
    sortable_markers: list[tuple[tuple[int, int, int, int], SemanticMarkerEvidence]] = []
    for marker in markers:
        if marker.candidate.event_name not in required:
            continue
        position = _semantic_marker_order_position(execution_order, marker)
        if position is None:
            raise RunnerError("marker diff has invalid semantic marker ordering")
        sortable_markers.append((position, marker))
    ordered_markers = [marker for _position, marker in sorted(sortable_markers)]
    prior: dict[str, WorkspaceSnapshot] = dict(initial)
    # Multiple exact markers may live in one parsed native record.  They all
    # observe the same post-record workspace instant, so each diff must retain
    # the snapshot preceding that record.  Advancing ``prior`` after the first
    # marker would turn every later same-record proof into an empty delta.
    group_baselines: dict[tuple[str, int], WorkspaceSnapshot] = {}
    references: dict[str, dict[str, str]] = {}
    for marker in ordered_markers:
        name = marker.candidate.event_name
        snapshot_key = (marker.execution_id, marker.candidate.trace_sequence)
        current = by_marker.get(snapshot_key)
        before = group_baselines.get(snapshot_key)
        if current is None:
            continue
        current = _trace_owned_marker_workspace_snapshot(
            writer, current, marker, trace_snapshot_ids=trace_snapshot_ids,
        )
        if before is None:
            before = prior.get(marker.execution_id)
            if before is not None:
                group_baselines[snapshot_key] = before
        rule = contract.EVENT_RULES.get(name)
        if rule is not None and any(key == "diff_id" for key, _kind in rule.references):
            if before is None:
                raise RunnerError("marker diff lacks initial workspace snapshot")
            before_map = {str(item["path"]): item for item in before.inventory}
            after_map = {str(item["path"]): item for item in current.inventory}
            changed = sorted(
                path for path in before_map.keys() | after_map.keys()
                if (before_map.get(path, {}).get("sha256"), before_map.get(path, {}).get("bytes"))
                != (after_map.get(path, {}).get("sha256"), after_map.get(path, {}).get("bytes"))
            )
            artifact_id = "diff-" + marker.marker_id
            writer.add_json(artifact_id, "diff", {
                "run_id": run_id, "execution_id": marker.execution_id,
                "before_snapshot_id": before.artifact_id,
                "after_snapshot_id": current.artifact_id,
                "before": [dict(item) for item in before.inventory],
                "after": [dict(item) for item in current.inventory],
                "changed_paths": changed, "staged_paths": list(current.staged_paths),
            })
            references[name] = {"diff_id": artifact_id}
        prior[marker.execution_id] = current
    return references


_REPOSITORY_DEVELOPMENT_SOFTWARE_PATHS = (
    # This is a runner-owned request policy, not a client-supplied glob.  The
    # scenario asks for a sync CLI flag and its tests, so the only eligible
    # production surface is the CLI/command implementation and its focused
    # unit coverage.  Adding a path requires a reviewed runner policy change;
    # a marker, prompt, or client-created file can never widen it.
    "brainlib/cli.py",
    "brainlib/commands.py",
    "tests/unit/test_cli.py",
    "tests/unit/test_sync.py",
)


def _software_paths_for_scenario(scenario: Mapping[str, Any]) -> tuple[str, ...]:
    """Return the closed runner policy for repository-development diffs."""

    scenario_id = scenario.get("id") if isinstance(scenario, Mapping) else None
    if type(scenario_id) is not str:
        raise RunnerError("invalid scenario software scope")
    if scenario_id == "repository-development-not-archived":
        return _REPOSITORY_DEVELOPMENT_SOFTWARE_PATHS
    return ()


def _repository_assertion_scope_facts(
    scenario: Mapping[str, Any], changed_paths: Iterable[str],
) -> list[bool]:
    """Evaluate the three fixed repository assertions from one parsed diff.

    This is intentionally a narrow, deterministic policy predicate rather
    than a semantic-lifecycle validator.  Callers must establish their own
    indexed marker/trace binding before using its facts.  Keeping the path
    rule separate lets focused tests mutate only a parsed immutable diff
    without whitelisting a failed public-contract replay.
    """

    if scenario.get("id") != "repository-development-not-archived":
        raise RunnerError("repository assertion scope scenario invalid")
    changed = set(changed_paths)
    if any(type(path) is not str for path in changed):
        raise RunnerError("repository assertion changed path invalid")
    allowed = set(_software_paths_for_scenario(scenario))
    return [
        not any(path.startswith("wiki/questions/") for path in changed),
        not any(path.startswith("wiki/pages/") for path in changed),
        not any(
            path.startswith(("wiki/", "sources/", ".brain/")) or path not in allowed
            for path in changed
        ),
    ]


@dataclass(frozen=True)
class RepositoryAssertionProjection:
    """Host-owned assertion projection for an incomplete or future live run.

    ``rules_satisfied`` deliberately describes only the immutable diff facts;
    it is not a pass signal.  The Task 7c injected path always writes
    ``passed: false`` because no registered executable may establish an
    actual-client result here.
    """

    assertions: tuple[dict[str, Any], ...]
    marker_time_available: bool
    rules_satisfied: bool
    # These are runner-local diagnostics, not public assertion fields.  A
    # test-injected client is still incomplete even when every deterministic
    # assertion fact is corroborated, but callers need to distinguish that
    # intentional provenance gate from missing semantic evidence.
    incomplete_reasons: tuple[str, ...] = ()


@dataclass(frozen=True)
class RepositoryAssertionFacts:
    """Pure, indexed assertion facts for the future registered public route.

    This is intentionally distinct from ``RepositoryAssertionProjection``:
    the latter retains Task 7c's incomplete fallback-diff behavior and writes
    assertion artifacts.  A public candidate must first establish all facts
    without creating a false artifact that a later pass path would need to
    rewrite.
    """

    texts: tuple[str, ...]
    facts: tuple[bool, ...]
    diff_id: str | None
    marker_id: str | None
    snapshot_id: str | None
    marker_time_available: bool
    incomplete_reasons: tuple[str, ...]

    def __post_init__(self) -> None:
        """Keep public pass facts a closed, immutable value.

        These facts are an authority boundary, not merely a convenience
        return value.  In particular, an emitter must not be able to receive
        a shaped object containing an extra assertion or a false fact that was
        silently omitted from ``incomplete_reasons``.
        """

        if (type(self.texts) is not tuple
                or type(self.facts) is not tuple
                or len(self.texts) != len(self.facts)
                or not self.texts
                or any(type(text) is not str or not text for text in self.texts)
                or any(type(fact) is not bool for fact in self.facts)
                or self.diff_id is not None and not isinstance(self.diff_id, str)
                or self.marker_id is not None and not isinstance(self.marker_id, str)
                or self.snapshot_id is not None and not isinstance(self.snapshot_id, str)
                or type(self.marker_time_available) is not bool
                or type(self.incomplete_reasons) is not tuple
                or any(type(reason) is not str or not reason
                       for reason in self.incomplete_reasons)
                or len(set(self.incomplete_reasons)) != len(self.incomplete_reasons)):
            raise RunnerError("public repository assertion facts are invalid")
        if (self.marker_time_available
                and (self.diff_id is None or self.marker_id is None or self.snapshot_id is None)):
            raise RunnerError("public repository assertion facts lack marker-time provenance")
        if (not self.marker_time_available
                and any(value is not None for value in (
                    self.diff_id, self.marker_id, self.snapshot_id,
                ))):
            raise RunnerError("public repository assertion facts have incomplete provenance")

    @property
    def complete(self) -> bool:
        return (
            self.marker_time_available
            and self.diff_id is not None
            and len(self.texts) == len(self.facts)
            and bool(self.texts)
            and all(self.facts)
            and not self.incomplete_reasons
        )


@dataclass(frozen=True)
class _RepositoryDiffEvidence:
    artifact_id: str
    changed_paths: tuple[str, ...]
    execution_id: str
    before: Mapping[str, Mapping[str, Any]]
    after: Mapping[str, Mapping[str, Any]]
    staged_paths: tuple[str, ...]
    before_snapshot_id: str | None
    after_snapshot_id: str | None


@dataclass(frozen=True)
class _IndexedAssertionPlan:
    """A semantic plan whose relevant rows remain backed by runner artifacts.

    ``SemanticEventPlan`` is an in-memory convenience object.  It is not
    evidence on its own: the assertion projector may only use it after every
    required marker/event row has been copied to the private evidence index
    and every command referenced by that row is tied back to an indexed
    command observation/result pair.  This narrow adapter makes that
    distinction explicit before any scenario-specific semantic fact is
    evaluated.
    """

    events: Mapping[str, Mapping[str, Any]]
    records: Mapping[str, Mapping[str, Any]]
    commands: Mapping[str, SemanticCommandEvidence]


@dataclass(frozen=True)
class _VirtualSemanticArtifact:
    """An ephemeral marker/event row used only by injected-client replay.

    The bytes are canonical JSON and live exclusively in memory.  This type
    deliberately has no path or writer method: a test-injected process may
    exercise the normalizer, but it must never add pass-facing evidence to the
    immutable control directory.
    """

    artifact_type: str
    raw: bytes


def _freeze_private_trace_value(value: object) -> object:
    """Copy a JSON-shaped trace value without retaining caller mutability."""

    if isinstance(value, Mapping):
        frozen: dict[object, object] = {}
        for key, nested in value.items():
            if type(key) not in {str, int}:
                raise RunnerError("private native trace key is invalid")
            frozen[key] = _freeze_private_trace_value(nested)
        return MappingProxyType(frozen)
    if isinstance(value, (list, tuple)):
        return tuple(_freeze_private_trace_value(item) for item in value)
    if value is None or type(value) in {str, int, float, bool}:
        return value
    raise RunnerError("private native trace value is invalid")


class _IndexedSemanticControl:
    """Read only sealed writer artifacts through Task 7a's semantic checks.

    This intentionally has the small ``read``/``obj``/``entries`` surface
    used by the contract's receipt, special-event, and global-command audit.
    It is not a replacement for the descriptor-backed public pass validator:
    this runner-side replay only decides whether incomplete-path assertions may
    consume evidence at all.  Every byte still comes from ``EvidenceWriter``'s
    immutable private copy rather than the evaluated workspace.
    """

    def __init__(
        self,
        writer: EvidenceWriter,
        *,
        run_id: str,
        workspace: Path,
        overlay: Mapping[str, _VirtualSemanticArtifact] | None = None,
        native_records: Mapping[str, Mapping[int, Mapping[str, Any]]] | None = None,
        control_pin: PinnedDirectory | None = None,
    ) -> None:
        if control_pin is not None:
            if (not isinstance(control_pin, PinnedDirectory)
                    or not control_pin.private
                    or control_pin.path != writer.control_root.resolve()
                    or writer.run_root != control_pin.path / "runs" / writer.run_id):
                raise RunnerError("indexed semantic control pin is invalid")
            PinnedDirectory.verify(control_pin)
        self.writer = writer
        self.run_id = run_id
        self.workspace_path = str(workspace.resolve())
        self.control_pin = control_pin
        writer_entries = _writer_entry_map(writer)
        virtual: dict[str, _VirtualSemanticArtifact] = {}
        for artifact_id, artifact in ({} if overlay is None else overlay).items():
            if (type(artifact_id) is not str or not artifact_id
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in artifact_id)
                    or artifact_id in writer_entries
                    or not isinstance(artifact, _VirtualSemanticArtifact)
                    or artifact.artifact_type not in {
                        "marker", "event_record", "interpretation_decision",
                    }
                    or type(artifact.raw) is not bytes):
                raise RunnerError("invalid private semantic overlay")
            value = _strict_json(artifact.raw, label="private semantic overlay")
            if type(value) is not dict or _canonical_json(value) != artifact.raw:
                raise RunnerError("private semantic overlay is not canonical JSON")
            virtual[artifact_id] = artifact
        self._overlay = MappingProxyType(dict(virtual))
        entries: dict[str, Mapping[str, Any]] = {
            artifact_id: MappingProxyType(dict(entry))
            for artifact_id, entry in writer_entries.items()
        }
        for artifact_id, artifact in virtual.items():
            entries[artifact_id] = MappingProxyType({
                "id": artifact_id,
                "type": artifact.artifact_type,
                # A virtual row has no filesystem authority.  `read` below
                # intercepts it before any relative path can be consulted.
                "relative_path": "virtual/" + artifact_id + ".json",
                "sha256": _sha256(artifact.raw),
                "bytes": len(artifact.raw),
            })
        self.entries: Mapping[str, Mapping[str, Any]] = MappingProxyType(entries)
        if native_records is None:
            # Contract trace parsing populates this writer-only base control.
            self.native_records: Mapping[str, Mapping[int, Mapping[str, Any]]] = {}
        else:
            frozen_records: dict[str, Mapping[int, Mapping[str, Any]]] = {}
            for execution_id, rows in native_records.items():
                if type(execution_id) is not str or not execution_id or not isinstance(rows, Mapping):
                    raise RunnerError("private native trace execution is invalid")
                frozen_rows: dict[int, Mapping[str, Any]] = {}
                for start, row in rows.items():
                    if type(start) is not int or not isinstance(row, Mapping):
                        raise RunnerError("private native trace row is invalid")
                    frozen_row = _freeze_private_trace_value(row)
                    if not isinstance(frozen_row, Mapping):  # defensive type boundary
                        raise RunnerError("private native trace row is invalid")
                    frozen_rows[start] = frozen_row
                frozen_records[execution_id] = MappingProxyType(frozen_rows)
            self.native_records = MappingProxyType(frozen_records)

    def read(self, artifact_id: str, artifact_type: str) -> bytes:
        artifact = self._overlay.get(artifact_id)
        if artifact is not None:
            if artifact.artifact_type != artifact_type:
                raise RunnerError("private semantic overlay type mismatch")
            if _sha256(artifact.raw) != self.entries[artifact_id]["sha256"]:
                raise RunnerError("private semantic overlay digest mismatch")
            return artifact.raw
        return _writer_artifact_bytes(
            self.writer,
            artifact_id,
            artifact_type,
            control_pin=self.control_pin,
        )

    def obj(self, artifact_id: str, artifact_type: str) -> dict[str, Any]:
        value = _strict_json(
            self.read(artifact_id, artifact_type),
            label="indexed semantic artifact",
        )
        if type(value) is not dict:
            raise RunnerError("indexed semantic artifact is not an object")
        return value

    def with_private_semantic_overlay(
        self,
        overlay: Mapping[str, _VirtualSemanticArtifact],
    ) -> _IndexedSemanticControl:
        """Clone the writer-only trace view with a non-persistent overlay."""

        control = _IndexedSemanticControl(
            self.writer, run_id=self.run_id, workspace=Path(self.workspace_path),
            overlay=overlay, native_records=self.native_records, control_pin=self.control_pin,
        )
        # The binding phase has already populated this from writer-owned trace
        # rows.  Preserve it only as immutable replay context; virtual marker
        # rows are never allowed to modify trace/snapshot ownership.
        if hasattr(self, "native_snapshot_bindings"):
            control.native_snapshot_bindings = MappingProxyType(dict(self.native_snapshot_bindings))
        return control


def _indexed_commands_from_writer(
    writer: EvidenceWriter,
    *,
    run_id: str,
) -> tuple[SemanticCommandEvidence, ...]:
    """Reconstruct every indexed command rather than trusting a plan subset."""

    entries = _writer_entry_map(writer)
    command_ids = sorted(
        artifact_id for artifact_id, entry in entries.items()
        if entry.get("type") == "command_observation"
    )
    commands: list[SemanticCommandEvidence] = []
    for command_id in command_ids:
        observation = _strict_json(
            _writer_artifact_bytes(writer, command_id, "command_observation"),
            label="indexed semantic command observation",
        )
        required = {
            "run_id", "execution_id", "argv", "exit_code", "result_id", "result_sha256",
            "timestamp", "start_sequence", "end_sequence", "source_state_id",
        }
        if (type(observation) is not dict or set(observation) != required
                or observation.get("run_id") != run_id
                or type(observation.get("execution_id")) is not str
                or not observation["execution_id"]
                or type(observation.get("argv")) is not list
                or any(type(item) is not str for item in observation["argv"])
                or type(observation.get("exit_code")) is not int
                or observation["exit_code"] not in {0, 1}
                or type(observation.get("result_id")) is not str
                or type(observation.get("result_sha256")) is not str
                or not _is_hex64(observation["result_sha256"])
                or type(observation.get("start_sequence")) is not int
                or type(observation.get("end_sequence")) is not int
                or not 0 < observation["start_sequence"] < observation["end_sequence"]
                or observation.get("source_state_id") is not None
                and type(observation["source_state_id"]) is not str):
            raise RunnerError("indexed semantic command observation invalid")
        result_raw = _writer_artifact_bytes(
            writer, observation["result_id"], "command_result",
        )
        if _sha256(result_raw) != observation["result_sha256"]:
            raise RunnerError("indexed semantic command result digest mismatch")
        result = _strict_json(result_raw, label="indexed semantic command result")
        if type(result) is not dict:
            raise RunnerError("indexed semantic command result is not an object")
        artifacts: dict[str, str] = {}
        for label, artifact_type, suffix in (
            ("sync_stream", "sync_stream", "stream"),
            ("consumption_receipt", "consumption_receipt", "durable"),
            ("delivery", "delivery", "delivery"),
            ("wiki_manifest", "wiki_manifest", "wiki-manifest"),
        ):
            artifact_id = f"{command_id}-{suffix}"
            if entries.get(artifact_id, {}).get("type") == artifact_type:
                artifacts[label] = artifact_id
        source_state_id = observation["source_state_id"]
        if source_state_id is not None:
            if entries.get(source_state_id, {}).get("type") != "source_state":
                raise RunnerError("indexed semantic command source state missing")
            artifacts["source_state"] = source_state_id
        commands.append(SemanticCommandEvidence(
            command_id=command_id,
            execution_id=observation["execution_id"],
            argv=tuple(observation["argv"]),
            result=result,
            result_raw=result_raw,
            result_sha256=observation["result_sha256"],
            start_sequence=observation["start_sequence"],
            end_sequence=observation["end_sequence"],
            exit_code=observation["exit_code"],
            artifact_ids=artifacts,
        ))
    return tuple(commands)


def _indexed_run_manifest(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    workspace: Path,
    client: str,
    fixture_sha256: str,
    fixture_capability_id: str | None,
    approval: Mapping[str, str] | None,
) -> dict[str, Any]:
    """Require the fixed manifest to equal prep-time runner expectations.

    This deliberately receives the fixture digest/capability/approval values
    from the already prepared run instead of rediscovering them from a mutable
    fixture source tree during replay.
    """

    manifest = _strict_json(
        _writer_artifact_bytes(writer, "run-manifest", "run_manifest"),
        label="indexed run manifest",
    )
    required = {
        "schema_version", "run_id", "client", "scenario_id", "fixture_id", "fixture_sha256",
        "workspace", "phases", "policy_profiles", "fixture_capability_id", "approval",
        "software_paths", "scenario_sha256", "phase_prompt_protocol", "phase_prompts",
    }
    scenario_id = scenario.get("id")
    fixture_id = scenario.get("fixture_id")
    phases = list(phase_plan(str(scenario_id)))
    if client not in {"claude", "codex"} or not _is_hex64(fixture_sha256):
        raise RunnerError("indexed run manifest expectation invalid")
    profile = (
        "codex-workspace-egress-denied-v1"
        if client == "codex" else "claude-restricted-tool-surface-v1"
    )
    try:
        expected_scenario_sha256 = scenario_sha256(scenario)
        expected_phase_prompts = [
            {
                "execution_id": f"execution-{position}",
                "phase": phase,
                "phase_prompt_id": f"phase-prompt-{position}",
                "phase_prompt_sha256": _sha256(_canonical_phase_prompt(scenario, phase)),
                "phase_prompt_transport": _phase_prompt_transport(client),
            }
            for position, phase in enumerate(phases, 1)
        ]
    except (RunnerError, TypeError, ValueError) as error:
        raise RunnerError("indexed run manifest phase prompt invalid") from error
    expected_paths = list(_software_paths_for_scenario(scenario))
    if (type(manifest) is not dict or set(manifest) != required
            or manifest.get("schema_version") != 1 or manifest.get("run_id") != run_id
            or manifest.get("client") != client
            or manifest.get("scenario_id") != scenario_id
            or manifest.get("fixture_id") != fixture_id
            or manifest.get("fixture_sha256") != fixture_sha256
            or manifest.get("workspace") != str(workspace.resolve())
            or manifest.get("phases") != phases
            or manifest.get("policy_profiles") != [profile] * len(phases)
            or manifest.get("software_paths") != expected_paths
            or manifest.get("fixture_capability_id") != fixture_capability_id
            or manifest.get("approval") != approval
            or manifest.get("scenario_sha256") != expected_scenario_sha256
            or manifest.get("phase_prompt_protocol") != PROMPT_PROTOCOL
            or manifest.get("phase_prompts") != expected_phase_prompts):
        raise RunnerError("indexed run manifest invalid")
    manifest_approval = manifest["approval"]
    if manifest_approval is not None and (
            type(manifest_approval) is not dict
            or set(manifest_approval) != {"event_id", "scope", "note", "decision"}
            or any(type(value) is not str or not value for value in manifest_approval.values())):
        raise RunnerError("indexed run manifest approval invalid")
    return manifest


def _reject_native_inside_command_interval(
    trace_records: Sequence[Mapping[str, Any]],
) -> None:
    """A shim invocation is one atomic shared-trace boundary.

    The stdout reader may append records between invocations, but a native row
    inside an outer ``./brain`` start/end interval would make a later marker
    ordering claim ambiguous.  Reject it rather than reconstructing order
    after the fact.
    """

    active: str | None = None
    for row in trace_records:
        kind = row.get("kind")
        if kind == "command_start":
            if active is not None:
                raise RunnerError("indexed trace has overlapping commands")
            active = row.get("command_id")
        elif kind == "command_end":
            if row.get("command_id") != active:
                raise RunnerError("indexed trace command interval invalid")
            active = None
        elif kind == "native_record" and active is not None:
            raise RunnerError("indexed trace native row inside command interval")
    if active is not None:
        raise RunnerError("indexed trace command did not close")


@dataclass(frozen=True)
class _IndexedExecutionBinding:
    """The closed runner facts shared by pre- and post-emission replay."""

    manifest: Mapping[str, Any]
    processes: Mapping[str, Mapping[str, Any]]
    executions: Mapping[str, Mapping[str, Any]]
    control: _IndexedSemanticControl
    client_version: str


def _indexed_web_phase_authority(
    *,
    control: _IndexedSemanticControl,
    manifest: Mapping[str, Any],
    entries: Mapping[str, Mapping[str, Any]],
    run_id: str,
    scenario: Mapping[str, Any],
    fixture_sha256: str,
) -> bool:
    """Validate web approval/capture authority before event artifacts exist.

    Task 7a normally runs these checks while validating event references.  The
    runner has a stricter sequencing obligation: a malformed approval,
    capability, descriptor, or retained fixture capture must not reach
    ``_emit_semantic_plan`` simply because an in-memory planner says complete.
    """

    if scenario.get("id") != "web-approval-and-capture":
        return True
    if (manifest.get("fixture_capability_id") != "fixture-capability"
            or type(manifest.get("approval")) is not dict):
        return False
    expected_types = {
        "approval": {"web-approval"},
        "fixture_capability": {"fixture-capability"},
        "fixture_descriptor": {"fixture-descriptor"},
    }
    for artifact_type, expected_ids in expected_types.items():
        if {artifact_id for artifact_id, entry in entries.items()
                if entry.get("type") == artifact_type} != expected_ids:
            return False
    if (entries.get("fixture-static-shell", {}).get("type") != "file_capture"
            or entries.get("fixture-rendered-dom", {}).get("type") != "file_capture"):
        return False
    try:
        from tests.evals import event_log_contract as contract

        replay_log = {
            "run_id": run_id,
            "scenario_id": "web-approval-and-capture",
            "network_mode": "mock_only",
            "fixture_sha256": fixture_sha256,
            "_manifest": manifest,
        }
        approved = contract._approval(
            control, "web-approval",
            {"name": "ask_web_approval", "execution_id": "execution-1"},
            replay_log,
        )
        descriptor = contract._capability(
            control, "fixture-capability",
            {"name": "public_web_access", "execution_id": "execution-2"},
            replay_log, approved,
        )
        if (_sha256(control.read("fixture-static-shell", "file_capture"))
                    != descriptor["static_sha256"]
                or _sha256(control.read("fixture-rendered-dom", "file_capture"))
                    != descriptor["rendered_sha256"]):
            return False
    except (KeyError, RunnerError, ValueError, TypeError):
        return False
    return True


def _indexed_execution_binding(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    execution_order: Mapping[str, int],
    workspace: Path,
    client: str,
    fixture_sha256: str,
    fixture_capability_id: str | None,
    approval: Mapping[str, str] | None,
) -> _IndexedExecutionBinding | None:
    """Validate the runner-owned launch surface before semantic emission.

    This is intentionally an incomplete-path adapter, not executable
    registration.  It accepts an injected fake only to test exact policy,
    probes, trace, and snapshot mechanics; the public log still carries the
    separate ``test_process_not_actual`` reason.  A future registered client
    must satisfy Task 7a's stronger executable/context join as well.
    """

    try:
        from tests.evals import event_log_contract as contract

        manifest = _indexed_run_manifest(
            writer, run_id=run_id, scenario=scenario, workspace=workspace,
            client=client, fixture_sha256=fixture_sha256,
            fixture_capability_id=fixture_capability_id, approval=approval,
        )
        phases = phase_plan(str(scenario["id"]))
        ordered = sorted(execution_order.items(), key=lambda item: item[1])
        expected_execution_ids = [f"execution-{index}" for index in range(1, len(phases) + 1)]
        if (len(ordered) != len(phases)
                or [index for _execution_id, index in ordered] != list(range(len(phases)))
                or [execution_id for execution_id, _index in ordered] != expected_execution_ids):
            return None

        entries = _writer_entry_map(writer)
        expected_policy_ids = {f"policy-{index}" for index in range(1, len(phases) + 1)}
        expected_process_ids = {f"process-{index}" for index in range(1, len(phases) + 1)}
        expected_phase_prompt_ids = {
            f"phase-prompt-{index}" for index in range(1, len(phases) + 1)
        }
        if ({artifact_id for artifact_id, entry in entries.items() if entry.get("type") == "policy"}
                != expected_policy_ids
                or {artifact_id for artifact_id, entry in entries.items() if entry.get("type") == "process"}
                != expected_process_ids
                or {artifact_id for artifact_id, entry in entries.items()
                    if entry.get("type") == "phase_prompt"} != expected_phase_prompt_ids):
            return None
        # An injected ProcessRunner has no executable provenance and remains
        # incomplete; it therefore carries no client-executable artifacts.
        # Once any such artifact exists, however, this is a registered-launch
        # shape and every phase must bind one exact executable ID.  Do not let
        # a partially registered multi-phase run silently fall back to the
        # symbolic argv behavior used only by the fake seam.
        expected_executable_ids = {
            f"client-executable-{index}" for index in range(1, len(phases) + 1)
        }
        registered_executable_ids = {
            artifact_id for artifact_id, entry in entries.items()
            if entry.get("type") == "client_executable"
        }
        registered_launch = bool(registered_executable_ids)
        if registered_launch and registered_executable_ids != expected_executable_ids:
            return None
        expected_mcp_ids = {f"mcp-{index}" for index in range(1, len(phases) + 1)}
        if client == "claude" and {
                artifact_id for artifact_id, entry in entries.items()
                if entry.get("type") == "mcp_config"
        } != expected_mcp_ids:
            # A runner-created, phase-specific MCP artifact is part of the
            # launch identity.  Do not let a policy point to a same-byte
            # alternate config that the actual argv never consumed.
            return None

        profile = (
            "codex-workspace-egress-denied-v1"
            if client == "codex" else "claude-restricted-tool-surface-v1"
        )
        attestation = "workspace-egress-denied" if client == "codex" else "mock-only"
        native_format = (
            "codex-jsonl-unverified-v1" if client == "codex"
            else "claude-stream-json-2.1.251-v1"
        )
        policy_keys = {
            "run_id", "execution_id", "phase", "client", "profile",
            "network_attestation", "argv", "argv_sha256", "version_id", "help_id",
            "fixture_id", "fixture_sha256", "fixture_capability_id", "approval",
            "phase_prompt_id", "phase_prompt_sha256", "phase_prompt_transport",
        }
        process_keys = {
            "run_id", "execution_id", "phase", "client", "client_version", "argv",
            "argv_sha256", "exit_code", "transcript_id", "transcript_sha256", "trace_id",
            "trace_sha256", "native_format", "fixture_id", "fixture_sha256",
            "fixture_capability_id", "approval",
            "phase_prompt_id", "phase_prompt_sha256", "phase_prompt_transport",
        }
        if client == "claude":
            policy_keys |= {"mcp_config_id", "mcp_config_sha256", "mcp_path", "mcp_identity"}
            process_keys |= {"mcp_identity"}

        processes: dict[str, Mapping[str, Any]] = {}
        executions: dict[str, Mapping[str, Any]] = {}
        version: str | None = None
        for position, (execution_id, index) in enumerate(ordered, 1):
            phase = phases[index]
            policy_id = f"policy-{position}"
            process_id = f"process-{position}"
            policy = _strict_json(
                _writer_artifact_bytes(writer, policy_id, "policy"),
                label="indexed execution policy",
            )
            process = _strict_json(
                _writer_artifact_bytes(writer, process_id, "process"),
                label="indexed execution process",
            )
            if type(policy) is not dict or type(process) is not dict:
                return None
            policy_optional = {"executable_id"}
            process_optional = {"executable_id"}
            if (set(policy) - policy_keys - policy_optional
                    or set(process) - process_keys - process_optional
                    or not policy_keys <= set(policy) or not process_keys <= set(process)
                    or ("executable_id" in policy) != ("executable_id" in process)):
                return None
            registered_path: str | None = None
            if "executable_id" in policy:
                executable_id = policy["executable_id"]
                if (type(executable_id) is not str or not executable_id
                        or executable_id != process["executable_id"]
                        or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                               for character in executable_id)
                        or entries.get(executable_id, {}).get("type") != "client_executable"):
                    return None
                try:
                    executable = _strict_json(
                        _writer_artifact_bytes(writer, executable_id, "client_executable"),
                        label="indexed registered executable",
                    )
                    if (type(executable) is not dict
                            or executable.get("schema_version") != 1
                            or executable.get("run_id") != run_id
                            or executable.get("execution_id") != execution_id
                            or executable.get("phase") != phase
                            or executable.get("client") != client
                            or type(executable.get("resolved_path")) is not str):
                        return None
                    registered_path = str(_absolute_executable_path(executable["resolved_path"]))
                except RunnerError:
                    return None
            elif registered_launch:
                return None

            phase_capability = fixture_capability_id if phase == "approved_capture" else None
            phase_approval = approval if phase == "approved_capture" else None
            phase_fields = {
                "fixture_id": scenario["fixture_id"],
                "fixture_sha256": fixture_sha256,
                "fixture_capability_id": phase_capability,
                "approval": phase_approval,
            }
            if (policy.get("run_id") != run_id or policy.get("execution_id") != execution_id
                    or policy.get("phase") != phase or policy.get("client") != client
                    or policy.get("profile") != profile
                    or policy.get("network_attestation") != attestation
                    or any(policy.get(key) != value for key, value in phase_fields.items())
                    or any(process.get(key) != value for key, value in phase_fields.items())
                    or process.get("run_id") != run_id or process.get("execution_id") != execution_id
                    or process.get("phase") != phase or process.get("client") != client
                    or process.get("exit_code") != 0 or process.get("native_format") != native_format):
                return None

            try:
                prompt_raw = _canonical_phase_prompt(scenario, phase)
                prompt_text = prompt_raw.decode("utf-8", "strict")
            except RunnerError:
                return None
            prompt_id = f"phase-prompt-{position}"
            prompt_entry = entries.get(prompt_id)
            prompt_binding = {
                "phase_prompt_id": prompt_id,
                "phase_prompt_sha256": _sha256(prompt_raw),
                "phase_prompt_transport": _phase_prompt_transport(client),
            }
            if (prompt_entry is None or prompt_entry.get("type") != "phase_prompt"
                    or prompt_entry.get("relative_path") != f"artifacts/{prompt_id}.txt"
                    or _writer_artifact_bytes(writer, prompt_id, "phase_prompt") != prompt_raw
                    or any(policy.get(key) != value for key, value in prompt_binding.items())
                    or any(process.get(key) != value for key, value in prompt_binding.items())):
                return None

            version_id, help_id = f"version-{position}", f"help-{position}"
            if policy.get("version_id") != version_id or policy.get("help_id") != help_id:
                return None
            version_raw = _writer_artifact_bytes(writer, version_id, "version")
            help_raw = _writer_artifact_bytes(writer, help_id, "help")
            if not version_raw or not help_raw:
                return None
            reported_version = contract._reported_version(version_raw)
            if (type(process.get("client_version")) is not str
                    or process["client_version"] != reported_version):
                return None
            if registered_path is not None:
                executable = _strict_json(
                    _writer_artifact_bytes(writer, policy["executable_id"], "client_executable"),
                    label="indexed registered executable",
                )
                if executable.get("reported_version") != reported_version:
                    return None
            if version is None:
                version = reported_version
            elif version != reported_version:
                return None

            mcp_path = writer.run_root / "mcp-unused"
            if client == "claude":
                mcp_id = policy.get("mcp_config_id")
                expected_mcp_id = f"mcp-{position}"
                mcp_entry = entries.get(mcp_id) if type(mcp_id) is str else None
                expected_relative_path = f"artifacts/{expected_mcp_id}.json"
                expected_path = (writer.run_root / expected_relative_path).resolve()
                if (mcp_id != expected_mcp_id or mcp_entry is None
                        or mcp_entry.get("type") != "mcp_config"
                        or mcp_entry.get("relative_path") != expected_relative_path):
                    return None
                candidate = (writer.run_root / mcp_entry["relative_path"]).resolve()
                if (candidate != expected_path
                        or not candidate.is_relative_to(writer.run_root.resolve())):
                    return None
                mcp_path = candidate
                mcp_raw = _writer_artifact_bytes(writer, mcp_id, "mcp_config")
                identity = _identity(mcp_path)
                if (mcp_raw != EMPTY_MCP_BYTES
                        or policy.get("mcp_config_sha256") != _sha256(mcp_raw)
                        or policy.get("mcp_path") != str(mcp_path)
                        or policy.get("mcp_identity") != identity
                        or process.get("mcp_identity") != identity):
                    return None

            expected_argv = build_effective_argv(
                client,
                _CODEX_TEMPLATE if client == "codex" else _CLAUDE_TEMPLATE,
                workspace, mcp_path, prompt_text,
            )
            if registered_path is not None:
                expected_argv[0] = registered_path
            argv_sha256 = _sha256(_canonical_json(expected_argv))
            if (policy.get("argv") != expected_argv or policy.get("argv_sha256") != argv_sha256
                    or process.get("argv") != expected_argv
                    or process.get("argv_sha256") != argv_sha256):
                return None
            transcript_id = f"transcript-{position}"
            trace_id = f"trace-{execution_id}"
            if (process.get("transcript_id") != transcript_id or process.get("trace_id") != trace_id
                    or not _is_hex64(process.get("transcript_sha256", ""))
                    or not _is_hex64(process.get("trace_sha256", ""))):
                return None
            transcript_raw = _writer_artifact_bytes(writer, transcript_id, "transcript")
            if _sha256(transcript_raw) != process["transcript_sha256"]:
                return None
            processes[execution_id] = process
            executions[execution_id] = {
                "id": execution_id,
                "phase": phase,
                "transcript_id": transcript_id,
                # Private full-contract replay must retain the exact sealed
                # process identity for validators that traverse an execution
                # back to its trace.  This remains an in-memory binding; it
                # does not change the incomplete public log.
                "process_id": process_id,
            }

        if version is None:
            return None
        control = _IndexedSemanticControl(writer, run_id=run_id, workspace=workspace)
        trace_log = {
            "run_id": run_id,
            "scenario_id": scenario["id"],
            "client": client,
            "client_version": version,
            "fixture_sha256": fixture_sha256,
            "network_mode": scenario["network_mode"],
            "events": [], "receipts": [], "deliveries": [],
        }
        for execution_id, _index in ordered:
            process = processes[execution_id]
            execution = executions[execution_id]
            contract._execution_trace(control, execution, process, trace_log)
            trace = control.obj(process["trace_id"], "execution_trace")
            _reject_native_inside_command_interval(trace["records"])
        # Marker selection is not enough: require the indexed snapshot graph
        # to contain exactly one initial and every trace-owned native snapshot.
        contract._audit_workspace_snapshots(control, executions)
        if not _indexed_web_phase_authority(
                control=control, manifest=manifest, entries=entries,
                run_id=run_id, scenario=scenario, fixture_sha256=fixture_sha256,
        ):
            return None
        return _IndexedExecutionBinding(
            manifest=manifest, processes=processes, executions=executions,
            control=control, client_version=version,
        )
    except (OSError, RunnerError, ValueError, TypeError, KeyError, AttributeError, IndexError):
        return None


def _private_semantic_overlay(
    writer: EvidenceWriter,
    *,
    run_id: str,
    plan: SemanticEventPlan,
    markers: Sequence[SemanticMarkerEvidence],
    interpretation_decision: Mapping[str, Any] | None = None,
) -> Mapping[str, _VirtualSemanticArtifact] | None:
    """Build a strictly ephemeral marker/event view for an injected process.

    An injected ``process_runner`` is useful only for exercising conversion
    and normalization.  Its semantic rows must therefore be replayable
    without appearing in ``EvidenceWriter`` or the sealed evidence index.
    The virtual map is intentionally a closed derivation of the supplied
    plan/marker values; it rejects every persistent row, collision, orphan,
    or noncanonical payload before a contract helper can read it.
    """

    try:
        if not plan.complete:
            return None
        writer_entries = _writer_entry_map(writer)
        if any(entry.get("type") in {
            "marker", "event_record", "interpretation_decision",
        }
               for entry in writer_entries.values()):
            return None
        if not isinstance(plan.marker_records, Mapping) or not isinstance(plan.event_records, Mapping):
            return None
        marker_by_id = {marker.marker_id: marker for marker in markers}
        if len(marker_by_id) != len(markers):
            return None
        events = tuple(plan.events)
        event_ids: list[str] = []
        event_marker_ids: list[str] = []
        for event in events:
            if type(event) is not dict:
                return None
            event_id = event.get("event_record_id")
            marker_id = event.get("transcript_marker_id")
            if type(event_id) is not str or type(marker_id) is not str:
                return None
            event_ids.append(event_id)
            event_marker_ids.append(marker_id)
        if (len(set(event_ids)) != len(event_ids)
                or len(set(event_marker_ids)) != len(event_marker_ids)
                or set(plan.marker_records) != set(marker_by_id)
                or set(marker_by_id) != set(event_marker_ids)
                or set(plan.event_records) != set(event_ids)):
            return None

        decision_uses = [
            value.get("interpretation_decision_id")
            for value in plan.event_records.values()
            if isinstance(value, Mapping) and "interpretation_decision_id" in value
        ]
        if decision_uses:
            if (decision_uses != [_PRIVATE_INTERPRETATION_DECISION_ID]
                    or interpretation_decision is None
                    or not isinstance(interpretation_decision, Mapping)):
                return None
        elif interpretation_decision is not None:
            return None

        overlay: dict[str, _VirtualSemanticArtifact] = {}

        def add(artifact_id: str, artifact_type: str, value: object) -> bool:
            if (type(artifact_id) is not str or not artifact_id
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in artifact_id)
                    or artifact_id in writer_entries or artifact_id in overlay
                    or type(value) is not dict):
                return False
            raw = _canonical_json(value)
            if _strict_json(raw, label="private semantic overlay") != value:
                return False
            overlay[artifact_id] = _VirtualSemanticArtifact(artifact_type, raw)
            return True

        for marker_id, marker in marker_by_id.items():
            value = plan.marker_records.get(marker_id)
            if value != _semantic_marker_record(run_id, marker):
                return None
            if not add(marker_id, "marker", value):
                return None
        for event in events:
            event_id = event["event_record_id"]
            marker_id = event["transcript_marker_id"]
            value = plan.event_records.get(event_id)
            if (type(value) is not dict or value.get("marker_id") != marker_id
                    or not add(event_id, "event_record", value)):
                return None
        if decision_uses:
            if not add(
                _PRIVATE_INTERPRETATION_DECISION_ID,
                "interpretation_decision",
                dict(interpretation_decision),
            ):
                return None
        return MappingProxyType(overlay)
    except (RunnerError, TypeError, ValueError, KeyError):
        return None


def _rebuild_indexed_semantic_candidate(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    plan: SemanticEventPlan,
    markers: Sequence[SemanticMarkerEvidence],
    commands: Sequence[SemanticCommandEvidence],
    execution_order: Mapping[str, int],
) -> SemanticEventPlan | None:
    """Require a plan to be reproducible from indexed nonsemantic evidence.

    Marker/event values are deliberately excluded from this reconstruction:
    they may be virtual for a fake process.  Every command, cursor proof,
    delivery, and referenced support artifact comes from the writer instead.
    """

    try:
        from tests.evals import event_log_contract as contract

        required = scenario.get("required_events")
        receipt_operations = scenario.get("receipt_operations")
        if (not plan.complete or type(required) is not list or not required
                or any(type(name) is not str or name not in contract.EVENT_RULES for name in required)
                or len(required) != len(set(required))
                or type(receipt_operations) is not list
                or any(type(operation) is not str for operation in receipt_operations)
                or len(plan.events) != len(required)
                or not isinstance(plan.event_records, Mapping)):
            return None
        artifact_types = {
            str(entry["id"]): str(entry["type"])
            for entry in writer.entries
            if isinstance(entry, Mapping) and type(entry.get("id")) is str
            and type(entry.get("type")) is str
        }
        private_decision_id = _private_interpretation_decision_id(
            writer, scenario=scenario, plan=plan,
        )
        if private_decision_id is not None:
            # This type map is intentionally reconstruction-local.  The
            # writer index remains free of pass-facing decision artifacts on
            # every injected-process route.
            artifact_types[private_decision_id] = "interpretation_decision"
        event_references: dict[str, dict[str, str]] = {}
        proof_ids: set[str] = set()
        for sequence, name in enumerate(required, 1):
            event = plan.events[sequence - 1]
            if (type(event) is not dict or event.get("sequence") != sequence
                    or event.get("name") != name
                    or type(event.get("event_record_id")) is not str):
                return None
            record = plan.event_records.get(event["event_record_id"])
            if type(record) is not dict:
                return None
            references: dict[str, str] = {}
            for key, artifact_type in contract.EVENT_RULES[name].references:
                artifact_id = record.get(key)
                if type(artifact_id) is not str or artifact_types.get(artifact_id) != artifact_type:
                    return None
                references[key] = artifact_id
                if key == "cursor_proof_id":
                    proof_ids.add(artifact_id)
            event_references[name] = references

        cursor_proofs: list[SemanticCursorProofEvidence] = []
        for proof_id in sorted(proof_ids):
            proof = _strict_json(
                _writer_artifact_bytes(writer, proof_id, "cursor_proof"),
                label="private replay cursor proof",
            )
            if (type(proof) is not dict
                    or set(proof) != {"run_id", "execution_id", "family", "command_ids"}
                    or proof.get("run_id") != run_id
                    or type(proof.get("execution_id")) is not str
                    or type(proof.get("family")) is not str
                    or type(proof.get("command_ids")) is not list
                    or not proof["command_ids"]
                    or any(type(command_id) is not str for command_id in proof["command_ids"])
                    or len(set(proof["command_ids"])) != len(proof["command_ids"])):
                return None
            cursor_proofs.append(SemanticCursorProofEvidence(
                proof_id=proof_id, execution_id=proof["execution_id"],
                family=proof["family"], command_ids=tuple(proof["command_ids"]),
            ))
        deliveries = _semantic_deliveries_from_commands(
            writer, commands, tuple(receipt_operations),
        )
        rebuilt = plan_semantic_events(SemanticNormalizationInput(
            run_id=run_id, scenario=scenario, execution_order=execution_order,
            markers=tuple(markers), commands=tuple(commands),
            artifact_types=artifact_types, event_references=event_references,
            deliveries=deliveries, cursor_proofs=tuple(cursor_proofs),
        ))
        if (not rebuilt.complete
                or rebuilt.events != plan.events
                or rebuilt.event_records != plan.event_records
                or rebuilt.marker_records != plan.marker_records
                or rebuilt.receipts != plan.receipts
                or rebuilt.deliveries != plan.deliveries):
            return None
        return rebuilt
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError, IndexError):
        return None


def _reconstruct_private_trace_control(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    binding: _IndexedExecutionBinding,
    execution_order: Mapping[str, int],
    workspace: Path,
    client: str,
    fixture_sha256: str,
) -> _IndexedSemanticControl | None:
    """Reparse the sealed writer trace for an ephemeral replay control.

    The pre-emission binding has already validated the same trace, but its
    parser-owned native dictionaries are mutable Python objects.  A private
    overlay must never inherit those dictionaries: rebuild them from the
    indexed transcript/trace bytes, then freeze them when the overlay control
    is created.  This is deliberately not a cache or a shallow copy.
    """

    try:
        from tests.evals import event_log_contract as contract

        control = _IndexedSemanticControl(writer, run_id=run_id, workspace=workspace)
        replay_log = {
            "run_id": run_id,
            "scenario_id": scenario["id"],
            "client": client,
            "client_version": binding.client_version,
            "fixture_sha256": fixture_sha256,
            "network_mode": scenario["network_mode"],
            "events": [], "receipts": [], "deliveries": [],
        }
        ordered = sorted(execution_order.items(), key=lambda item: item[1])
        if [execution_id for execution_id, _index in ordered] != list(binding.executions):
            return None
        for execution_id, _index in ordered:
            execution = binding.executions.get(execution_id)
            process = binding.processes.get(execution_id)
            if execution is None or process is None:
                return None
            contract._execution_trace(control, execution, process, replay_log)
            trace = control.obj(process["trace_id"], "execution_trace")
            _reject_native_inside_command_interval(trace["records"])
        contract._audit_workspace_snapshots(control, binding.executions)
        return control
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError, IndexError):
        return None


def _private_interpretation_decision_projection(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    plan: SemanticEventPlan,
    markers: Sequence[SemanticMarkerEvidence],
    control: _IndexedSemanticControl,
) -> dict[str, Any] | None:
    """Derive the contradictory decision witness from sealed private inputs.

    This deliberately runs only after planning/reconstruction has fixed the
    opaque decision reference and the native trace/snapshot graph.  It never
    reads the evaluated workspace or writes an artifact: the returned value
    is supplied only to the private overlay and is subsequently checked by
    Task 7a's own full decision validator.
    """

    try:
        from brainlib.wiki_models import parse_question
        from tests.evals import event_log_contract as contract
        from tests.evals.generate_scenarios import interpretation_policy_sha256
        from tests.evals.phase_prompt_contract import scenario_sha256

        policy = _frozen_contradictory_interpretation_policy(scenario)
        decision_id = _private_interpretation_decision_id(
            writer, scenario=scenario, plan=plan,
        )
        if policy is None or decision_id != _PRIVATE_INTERPRETATION_DECISION_ID:
            return None
        event_by_name: dict[str, Mapping[str, Any]] = {}
        for event in plan.events:
            if not isinstance(event, Mapping) or type(event.get("name")) is not str:
                return None
            name = event["name"]
            if name in event_by_name:
                return None
            event_by_name[name] = event
        required_names = (
            "ask_interpretation_approval", "write_wiki_question",
            "wiki_apply", "validate",
        )
        if any(name not in event_by_name for name in required_names):
            return None
        approval_event, _write_event, apply_event, terminal_event = (
            event_by_name[name] for name in required_names
        )
        execution_id = approval_event.get("execution_id")
        if (type(execution_id) is not str or not execution_id
                or any(event.get("execution_id") != execution_id
                       for event in (approval_event, _write_event, apply_event, terminal_event))):
            return None
        approval_record_id = approval_event.get("event_record_id")
        apply_record_id = apply_event.get("event_record_id")
        terminal_record_id = terminal_event.get("event_record_id")
        approval_marker_id = approval_event.get("transcript_marker_id")
        terminal_marker_id = terminal_event.get("transcript_marker_id")
        if any(type(value) is not str or not value for value in (
            approval_record_id, apply_record_id, terminal_record_id,
            approval_marker_id, terminal_marker_id,
        )):
            return None
        approval_record = plan.event_records.get(approval_record_id)
        apply_record = plan.event_records.get(apply_record_id)
        if not isinstance(approval_record, Mapping) or not isinstance(apply_record, Mapping):
            return None
        approval_id = approval_record.get("approval_id")
        if (approval_record.get("interpretation_decision_id") != decision_id
                or type(approval_id) is not str or not approval_id):
            return None
        approval = control.obj(approval_id, "approval")
        apply_command_id = apply_record.get("command_id")
        manifest_id = apply_record.get("manifest_id")
        if (type(apply_command_id) is not str or not apply_command_id
                or type(manifest_id) is not str or not manifest_id):
            return None
        _capture, manifest = contract._wiki_manifest(control, manifest_id)
        _argv, apply_result = contract._result(control, apply_command_id, execution_id)
        data = apply_result.get("data") if isinstance(apply_result, Mapping) else None
        revision = data.get("corpus_revision") if isinstance(data, Mapping) else None
        if not _is_hex64(revision):
            return None
        command = control.obj(apply_command_id, "command_observation")
        state_id = command.get("source_state_id")
        if type(state_id) is not str or not state_id:
            return None
        state = contract._source_state(
            control, apply_command_id, result_id=None, revision=revision,
        )
        checkpoint = control.obj(state_id, "source_state")
        marker_by_id = {marker.marker_id: marker for marker in markers}
        terminal_marker = marker_by_id.get(terminal_marker_id)
        if terminal_marker is None or terminal_marker.execution_id != execution_id:
            return None
        native = control.native_records.get(execution_id, {}).get(
            terminal_marker.candidate.native_record_start,
        )
        snapshot_id = native.get("workspace_snapshot_id") if isinstance(native, Mapping) else None
        if type(snapshot_id) is not str or not snapshot_id:
            return None
        snapshot = contract._workspace_snapshot(
            control, snapshot_id, execution_id=execution_id,
        )
        path = policy["question_path"]
        capture = next(
            (entry for entry in snapshot["inventory"] if entry.get("path") == path),
            None,
        )
        if (not isinstance(capture, Mapping) or path in snapshot.get("staged_paths", [])
                or type(capture.get("content_id")) is not str
                or not _is_hex64(capture.get("sha256", ""))):
            return None
        body = control.read(capture["content_id"], "file_capture").decode("utf-8", "strict")
        question = parse_question(Path(path), text=body)
        claims = contract._interpretation_claims(
            control, snapshot, path, body, question, state, checkpoint,
        )
        contract._require_interpretation_policy_state(question, policy, approval, manifest)
        return {
            "schema_version": 1,
            "run_id": run_id,
            "execution_id": execution_id,
            "scenario_id": scenario["id"],
            "scenario_sha256": scenario_sha256(scenario),
            "interpretation_policy_sha256": interpretation_policy_sha256(dict(scenario)),
            "approval_event_record_id": approval_record_id,
            "approval_marker_id": approval_marker_id,
            "approval_id": approval_id,
            "approval_event_id": approval["event_id"],
            "approval_decision": approval["decision"],
            "validate_event_record_id": terminal_record_id,
            "validate_marker_id": terminal_marker_id,
            "terminal_snapshot_id": snapshot_id,
            "wiki_apply_event_record_id": apply_record_id,
            "wiki_apply_command_id": apply_command_id,
            "wiki_manifest_id": manifest_id,
            "question_path": path,
            "question_capture_id": capture["content_id"],
            "question_sha256": capture["sha256"],
            "question_id": question.question_id,
            "interpretation": {
                "decision": question.interpretation.decision,
                "preference_citation_id": question.interpretation.preference_citation_id,
                "approval_event_id": question.interpretation.approval_event_id,
            },
            "claim_identities": claims,
        }
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError, IndexError,
            UnicodeDecodeError):
        return None


def _indexed_semantic_replay(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    plan: SemanticEventPlan,
    markers: Sequence[SemanticMarkerEvidence],
    commands: Sequence[SemanticCommandEvidence],
    execution_order: Mapping[str, int],
    workspace: Path,
    client: str,
    fixture_sha256: str,
    fixture_capability_id: str | None,
    approval: Mapping[str, str] | None,
    private_candidate: bool = False,
) -> Mapping[str, SemanticCommandEvidence] | None:
    """Replay Task 7a's semantic/audit gates from indexed runner evidence.

    This is deliberately broader than assertion predicates.  It replays the
    source-backed marker, receipt, cursor, delivery, approval, special-event,
    and global command ownership checks before any Task 7c projection can
    consume a complete in-memory plan.  The caller still emits ``incomplete``
    for injected processes; this gate only prevents their evidence from being
    laundered into a future pass-capable assertion path.  ``private_candidate``
    accepts virtual marker/event rows only for that injected diagnostic path;
    it never writes an artifact or changes the public log.
    """

    try:
        from tests.evals import event_log_contract as contract

        binding = _indexed_execution_binding(
            writer, run_id=run_id, scenario=scenario,
            execution_order=execution_order, workspace=workspace,
            client=client, fixture_sha256=fixture_sha256,
            fixture_capability_id=fixture_capability_id, approval=approval,
        )
        if binding is None:
            return None
        manifest = binding.manifest
        indexed_commands = _indexed_commands_from_writer(writer, run_id=run_id)
        indexed_by_id = {command.command_id: command for command in indexed_commands}
        supplied_by_id = {command.command_id: command for command in commands}
        if (len(indexed_by_id) != len(indexed_commands)
                or len(supplied_by_id) != len(commands)
                or indexed_by_id != supplied_by_id):
            return None

        rebuilt = _rebuild_indexed_semantic_candidate(
            writer, run_id=run_id, scenario=scenario, plan=plan,
            markers=markers, commands=indexed_commands,
            execution_order=execution_order,
        )
        if rebuilt is None:
            return None
        private_decision_id = _private_interpretation_decision_id(
            writer, scenario=scenario, plan=rebuilt,
        )

        control = binding.control
        replay_log = {
            "run_id": run_id,
            "scenario_id": scenario["id"],
            "client": client,
            "client_version": binding.client_version,
            "fixture_sha256": fixture_sha256,
            "network_mode": scenario["network_mode"],
            "executions": [
                {
                    "id": execution_id,
                    "phase": execution["phase"],
                    "transcript_id": execution["transcript_id"],
                    "process_id": execution["process_id"],
                }
                for execution_id, execution in sorted(
                    binding.executions.items(),
                    key=lambda item: execution_order[item[0]],
                )
            ],
            "events": [dict(event) for event in plan.events],
            "receipts": [dict(receipt) for receipt in plan.receipts],
            "deliveries": [dict(delivery) for delivery in plan.deliveries],
        }
        executions = binding.executions

        required_names = tuple(scenario["required_events"])
        if ([event.get("sequence") for event in replay_log["events"]]
                != list(range(1, len(replay_log["events"]) + 1))
                or tuple(event.get("name") for event in replay_log["events"]) != required_names):
            return None
        marker_by_id = {marker.marker_id: marker for marker in markers}
        if len(marker_by_id) != len(markers):
            return None
        if private_candidate:
            reconstructed = _reconstruct_private_trace_control(
                writer, run_id=run_id, scenario=scenario, binding=binding,
                execution_order=execution_order, workspace=workspace,
                client=client, fixture_sha256=fixture_sha256,
            )
            if reconstructed is None:
                return None
            decision = None
            if private_decision_id is not None:
                decision = _private_interpretation_decision_projection(
                    writer, run_id=run_id, scenario=scenario, plan=rebuilt,
                    markers=markers, control=reconstructed,
                )
                if decision is None:
                    return None
            overlay = _private_semantic_overlay(
                writer, run_id=run_id, plan=rebuilt, markers=markers,
                interpretation_decision=decision,
            )
            if overlay is None:
                return None
            control = reconstructed.with_private_semantic_overlay(overlay)
        elif (private_decision_id is not None
                # Task 7c has no public decision-emission route.  Do not let
                # a future phase-two/public-semantic authority publish event records whose
                # required opaque decision was only prepared privately.
                or {str(entry["id"]) for entry in writer.entries if entry.get("type") == "marker"}
                != set(marker_by_id)
                or {str(entry["id"]) for entry in writer.entries if entry.get("type") == "event_record"}
                != set(plan.event_records)):
            return None
        for event in replay_log["events"]:
            execution = executions.get(event["execution_id"])
            marker = marker_by_id.get(event["transcript_marker_id"])
            native_records = control.native_records.get(event["execution_id"])
            if (execution is None or marker is None
                    or marker.execution_id != event["execution_id"]
                    or not isinstance(native_records, Mapping)
                    or not _marker_trace_sequence_matches(marker, native_records)
                    or _semantic_marker_record(run_id, marker)
                    != control.obj(marker.marker_id, "marker")):
                return None
            contract._validate_marker(control, event, execution, run_id)
            contract._validate_event_record(control, event, run_id)
        contract._event_order(control, replay_log, executions)
        if [receipt.get("operation") for receipt in replay_log["receipts"]] != scenario["receipt_operations"]:
            return None
        receipt_log = dict(replay_log)
        receipt_log["_scenario_required_events"] = scenario["required_events"]
        verified_receipts = contract._validate_receipts(
            control, receipt_log, replay_log["events"],
        )
        special_log = dict(replay_log)
        special_log["_manifest"] = manifest
        special_log["_scenario"] = scenario
        contract._validate_special_events(
            control, special_log, replay_log["events"], executions, verified_receipts,
        )
        contract._audit_commands(control, replay_log, executions, verified_receipts)
        interpretation_id = contract._interpretation_artifact_id(control, scenario)
        contract._validate_interpretation_decision(
            control, special_log, scenario, interpretation_id,
        )
        return indexed_by_id
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError, IndexError):
        return None


def _indexed_assertion_plan(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    plan: SemanticEventPlan | None,
    markers: Sequence[SemanticMarkerEvidence],
    commands: Sequence[SemanticCommandEvidence],
    execution_order: Mapping[str, int] | None = None,
    workspace: Path | None = None,
    trace_snapshot_ids: Mapping[tuple[str, int], str] | None = None,
    client: str | None = None,
    fixture_sha256: str | None = None,
    fixture_capability_id: str | None = None,
    approval: Mapping[str, str] | None = None,
) -> _IndexedAssertionPlan | None:
    """Validate the runner-owned evidence needed by assertion projection.

    This deliberately returns ``None`` for an incomplete/missing plan instead
    of treating a Python object supplied by a focused test seam as authority.
    Malformed indexed rows are likewise unavailable to the assertion path;
    the normal run remains incomplete and never turns an integrity problem
    into a passing assertion.
    """

    if (plan is None or not plan.complete or execution_order is None or workspace is None
            or client not in {"claude", "codex"} or not _is_hex64(fixture_sha256)):
        return None
    try:
        from tests.evals import event_log_contract as contract
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("event contract unavailable for assertion projection") from error
    required = scenario.get("required_events")
    if (type(required) is not list or not required
            or any(type(name) is not str or name not in contract.EVENT_RULES for name in required)
            or len(required) != len(set(required))):
        raise RunnerError("invalid assertion projection scenario")
    if len(plan.events) != len(required):
        return None
    marker_by_id = {marker.marker_id: marker for marker in markers}
    if len(marker_by_id) != len(markers):
        return None
    if trace_snapshot_ids is not None and any(
            trace_snapshot_ids.get((marker.execution_id, marker.candidate.trace_sequence)) is None
            for marker in markers
    ):
        return None
    command_by_id = {command.command_id: command for command in commands}
    if (len(command_by_id) != len(commands)
            or any(not command_id for command_id in command_by_id)):
        return None
    entries = _writer_entry_map(writer)
    projected_events: dict[str, Mapping[str, Any]] = {}
    projected_records: dict[str, Mapping[str, Any]] = {}
    selected_marker_ids: set[str] = set()
    previous_marker_position: tuple[int, int, int, int] | None = None
    for sequence, name in enumerate(required, 1):
        event = plan.events[sequence - 1]
        if (type(event) is not dict
                or event.get("sequence") != sequence
                or event.get("name") != name
                or type(event.get("event_record_id")) is not str
                or type(event.get("transcript_marker_id")) is not str
                or type(event.get("execution_id")) is not str
                or event.get("evidence_mode") != contract.EVENT_RULES[name].mode):
            return None
        event_id = event["event_record_id"]
        marker_id = event["transcript_marker_id"]
        marker = marker_by_id.get(marker_id)
        if marker is None or marker.execution_id != event["execution_id"]:
            return None
        marker_position = _semantic_marker_order_position(execution_order, marker)
        if (marker_position is None
                or previous_marker_position is not None
                and marker_position <= previous_marker_position):
            return None
        previous_marker_position = marker_position
        selected_marker_ids.add(marker_id)
        marker_raw = _strict_json(
            _writer_artifact_bytes(writer, marker_id, "marker"),
            label="assertion marker",
        )
        if (marker_raw != _semantic_marker_record(run_id, marker)
                or plan.marker_records.get(marker_id) != marker_raw):
            return None
        expected_references = {
            key: artifact_type
            for key, artifact_type in contract.EVENT_RULES[name].references
        }
        expected_keys = {
            "run_id", "execution_id", "event_name", "marker_id", "evidence_mode",
            *expected_references,
        }
        command_mode = contract.EVENT_RULES[name].mode in {"product_cli", "fixture_eval"}
        if command_mode:
            expected_keys |= {"command_id", "argv_sha256", "result_sha256"}
        record = _strict_json(
            _writer_artifact_bytes(writer, event_id, "event_record"),
            label="assertion event record",
        )
        if (type(record) is not dict or set(record) != expected_keys
                or record != plan.event_records.get(event_id)
                or record.get("run_id") != run_id
                or record.get("execution_id") != event["execution_id"]
                or record.get("event_name") != name
                or record.get("marker_id") != marker_id
                or record.get("evidence_mode") != contract.EVENT_RULES[name].mode):
            return None
        if any(
            type(record.get(key)) is not str
            or entries.get(record[key], {}).get("type") != artifact_type
            for key, artifact_type in expected_references.items()
        ):
            return None
        corroboration = event.get("corroboration_ids")
        if type(corroboration) is not list:
            return None
        if command_mode:
            command_id = record.get("command_id")
            command = command_by_id.get(command_id)
            if (command is None or corroboration != [command_id]
                    or record.get("argv_sha256") != _sha256(_canonical_json(list(command.argv)))
                    or record.get("result_sha256") != _sha256(_canonical_json(command.result))
                    # An event-shaped row cannot choose a generic successful
                    # command.  Re-run the exact Task 7a per-event argv/result
                    # validator here before a later assertion projector sees
                    # the evidence; otherwise a hand-built plan could turn
                    # `eval placeholder` into a claimed validate/apply event.
                    or not _semantic_command_matches(name, command)):
                return None
            observation = _strict_json(
                _writer_artifact_bytes(writer, command_id, "command_observation"),
                label="assertion command observation",
            )
            expected_observation = {
                "run_id", "execution_id", "argv", "exit_code", "result_id", "result_sha256",
                "timestamp", "start_sequence", "end_sequence", "source_state_id",
            }
            if (type(observation) is not dict or set(observation) != expected_observation
                    or observation.get("run_id") != run_id
                    or observation.get("execution_id") != command.execution_id
                    or observation.get("argv") != list(command.argv)
                    or observation.get("exit_code") != command.exit_code
                    or observation.get("result_sha256") != command.result_sha256
                    or observation.get("start_sequence") != command.start_sequence
                    or observation.get("end_sequence") != command.end_sequence
                    or not isinstance(observation.get("result_id"), str)
                    or _writer_artifact_bytes(writer, observation["result_id"], "command_result")
                    != command.result_raw
                    or _strict_json(command.result_raw, label="assertion command result") != command.result):
                return None
            state_id = command.artifact_ids.get("source_state")
            if observation.get("source_state_id") != state_id:
                return None
            if state_id is not None and entries.get(state_id, {}).get("type") != "source_state":
                return None
        elif corroboration:
            return None
        projected_events[name] = event
        projected_records[name] = record
    if (set(plan.marker_records) != selected_marker_ids
            or set(plan.event_records) != {
                str(event["event_record_id"]) for event in plan.events
            }
            or set(marker_by_id) != selected_marker_ids):
        return None

    # A complete plan is only an in-memory convenience.  Rebuild it from the
    # indexed marker/command/artifact rows before an assertion can consume it.
    # This closes lifecycle, delivery, cursor, ordering, and global-command
    # audit gaps that a hand-built ``SemanticEventPlan`` could otherwise hide.
    try:
        receipt_operations = scenario.get("receipt_operations")
        if (type(receipt_operations) is not list
                or any(type(operation) is not str for operation in receipt_operations)):
            return None
        artifact_types = {
            str(entry["id"]): str(entry["type"])
            for entry in writer.entries
            if isinstance(entry, Mapping) and type(entry.get("id")) is str
            and type(entry.get("type")) is str
        }
        event_references = {
            name: {
                key: str(projected_records[name][key])
                for key, _artifact_type in contract.EVENT_RULES[name].references
            }
            for name in required
        }
        proof_ids = {
            references["cursor_proof_id"]
            for references in event_references.values()
            if "cursor_proof_id" in references
        }
        cursor_proofs: list[SemanticCursorProofEvidence] = []
        for proof_id in sorted(proof_ids):
            proof = _strict_json(
                _writer_artifact_bytes(writer, proof_id, "cursor_proof"),
                label="assertion cursor proof",
            )
            if (type(proof) is not dict
                    or set(proof) != {"run_id", "execution_id", "family", "command_ids"}
                    or proof.get("run_id") != run_id
                    or type(proof.get("execution_id")) is not str
                    or type(proof.get("family")) is not str
                    or type(proof.get("command_ids")) is not list
                    or not proof["command_ids"]
                    or any(type(command_id) is not str for command_id in proof["command_ids"])
                    or len(set(proof["command_ids"])) != len(proof["command_ids"])):
                return None
            cursor_proofs.append(SemanticCursorProofEvidence(
                proof_id=proof_id, execution_id=proof["execution_id"],
                family=proof["family"], command_ids=tuple(proof["command_ids"]),
            ))
        deliveries = _semantic_deliveries_from_commands(
            writer, commands, tuple(receipt_operations),
        )
        rebuilt = plan_semantic_events(SemanticNormalizationInput(
            run_id=run_id, scenario=scenario, execution_order=execution_order,
            markers=tuple(markers), commands=tuple(commands),
            artifact_types=artifact_types, event_references=event_references,
            deliveries=deliveries, cursor_proofs=tuple(cursor_proofs),
        ))
    except (RunnerError, KeyError, TypeError, ValueError):
        return None
    if (not rebuilt.complete
            or rebuilt.events != plan.events
            or rebuilt.event_records != plan.event_records
            or rebuilt.marker_records != plan.marker_records
            or rebuilt.receipts != plan.receipts
            or rebuilt.deliveries != plan.deliveries):
        return None
    indexed_commands = _indexed_semantic_replay(
        writer, run_id=run_id, scenario=scenario, plan=plan, markers=markers,
        commands=commands, execution_order=execution_order, workspace=workspace,
        client=client, fixture_sha256=fixture_sha256,
        fixture_capability_id=fixture_capability_id, approval=approval,
    )
    if indexed_commands is None:
        return None
    return _IndexedAssertionPlan(projected_events, projected_records, indexed_commands)


def _read_repository_diff(
    writer: EvidenceWriter, *, run_id: str, diff_id: str,
) -> _RepositoryDiffEvidence:
    """Recheck an indexed diff before it can support an assertion.

    The public Task 7a contract performs this same inventory/hash check at
    pass validation.  Do it before projection too, so a writable workspace or
    an altered private artifact cannot quietly turn into a locally plausible
    assertion source.
    """

    raw = _writer_artifact_bytes(writer, diff_id, "diff")
    value = _strict_json(raw, label="repository assertion diff")
    required = {
        "run_id", "execution_id", "before", "after", "changed_paths", "staged_paths",
    }
    snapshot_keys = {"before_snapshot_id", "after_snapshot_id"}
    if (type(value) is not dict
            or (set(value) != required and set(value) != required | snapshot_keys)
            or value.get("run_id") != run_id
            or type(value.get("execution_id")) is not str or not value["execution_id"]):
        raise RunnerError("repository assertion diff shape invalid")
    snapshot_bound = set(value) == required | snapshot_keys
    inventories: list[dict[str, Mapping[str, Any]]] = []
    for side in ("before", "after"):
        entries = value.get(side)
        if type(entries) is not list:
            raise RunnerError("repository assertion diff inventory invalid")
        inventory: dict[str, Mapping[str, Any]] = {}
        prior = ""
        for entry in entries:
            if (type(entry) is not dict
                    or set(entry) != {"path", "sha256", "bytes", "content_id"}
                    or type(entry.get("path")) is not str
                    or not entry["path"]
                    or type(entry.get("sha256")) is not str
                    or not _is_hex64(entry["sha256"])
                    or type(entry.get("bytes")) is not int or entry["bytes"] < 0
                    or type(entry.get("content_id")) is not str
                    or entry["path"] in inventory or entry["path"] <= prior):
                raise RunnerError("repository assertion inventory entry invalid")
            pure = PurePosixPath(entry["path"])
            if (pure.is_absolute() or pure.as_posix() != entry["path"]
                    or any(part in {"", ".", ".."} for part in pure.parts)):
                raise RunnerError("repository assertion inventory path invalid")
            content = _writer_artifact_bytes(writer, entry["content_id"], "file_capture")
            if len(content) != entry["bytes"] or _sha256(content) != entry["sha256"]:
                raise RunnerError("repository assertion inventory bytes invalid")
            inventory[entry["path"]] = entry
            prior = entry["path"]
        inventories.append(inventory)
    before, after = inventories
    changed = tuple(sorted(
        path for path in before.keys() | after.keys()
        if (before.get(path, {}).get("sha256"), before.get(path, {}).get("bytes"))
        != (after.get(path, {}).get("sha256"), after.get(path, {}).get("bytes"))
    ))
    staged = value.get("staged_paths")
    if (type(value.get("changed_paths")) is not list
            or value["changed_paths"] != list(changed)
            or type(staged) is not list or staged != sorted(set(staged))
            or any(type(path) is not str for path in staged)):
        raise RunnerError("repository assertion changed-path inventory invalid")
    before_snapshot_id: str | None = None
    after_snapshot_id: str | None = None
    if snapshot_bound:
        before_snapshot_id = value["before_snapshot_id"]
        after_snapshot_id = value["after_snapshot_id"]
        if (type(before_snapshot_id) is not str or not before_snapshot_id
                or type(after_snapshot_id) is not str or not after_snapshot_id
                or before_snapshot_id == after_snapshot_id):
            raise RunnerError("repository assertion snapshot diff identity invalid")
        before_snapshot = _indexed_workspace_snapshot(
            writer,
            WorkspaceSnapshot("", 0, (), (), artifact_id=before_snapshot_id),
        )
        after_snapshot = _indexed_workspace_snapshot(
            writer,
            WorkspaceSnapshot("", 0, (), (), artifact_id=after_snapshot_id),
        )
        if (before_snapshot.execution_id != value["execution_id"]
                or after_snapshot.execution_id != value["execution_id"]
                or before_snapshot.role not in {"initial", "marker"}
                or after_snapshot.role != "marker"
                or [dict(entry) for entry in before_snapshot.inventory] != value["before"]
                or [dict(entry) for entry in after_snapshot.inventory] != value["after"]
                or list(after_snapshot.staged_paths) != staged):
            raise RunnerError("repository assertion snapshot diff binding invalid")
    elif not set(staged) <= set(changed):
        # The visibly incomplete fallback remains intentionally unanchored;
        # preserve its narrower legacy staged-path form without letting it
        # imitate a marker-time snapshot diff.
        raise RunnerError("repository assertion changed-path inventory invalid")
    return _RepositoryDiffEvidence(
        diff_id, changed, value["execution_id"], before, after, tuple(staged),
        before_snapshot_id, after_snapshot_id,
    )


def _fallback_repository_assertion_diff(
    writer: EvidenceWriter,
    *,
    run_id: str,
    before: WorkspaceSnapshot | None,
    after: WorkspaceSnapshot | None,
) -> str:
    """Retain an explicit non-authoritative diff when marker evidence is absent.

    This is only for a visibly incomplete log.  It is never marked as a
    marker-time source, so it cannot help a later registered-client path turn
    an uncorroborated failure into a pass.
    """

    artifact_id = "repository-assertion-fallback-diff"
    if before is None or after is None:
        writer.add_json(artifact_id, "diff", {
            "run_id": run_id, "execution_id": "runner-incomplete",
            "before": [], "after": [], "changed_paths": [], "staged_paths": [],
        })
        return artifact_id
    try:
        before = _indexed_workspace_snapshot(writer, before)
        after = _indexed_workspace_snapshot(writer, after)
    except RunnerError:
        writer.add_json(artifact_id, "diff", {
            "run_id": run_id, "execution_id": "runner-incomplete",
            "before": [], "after": [], "changed_paths": [], "staged_paths": [],
        })
        return artifact_id
    if (before.role != "initial" or after.role != "final"
            or before.execution_id != after.execution_id):
        writer.add_json(artifact_id, "diff", {
            "run_id": run_id, "execution_id": "runner-incomplete",
            "before": [], "after": [], "changed_paths": [], "staged_paths": [],
        })
        return artifact_id
    # Re-read all captured content before incorporating it into the immutable
    # projection.  A final workspace pathname is not consulted here.
    _semantic_snapshot_inventory(writer, before)
    _semantic_snapshot_inventory(writer, after)
    before_map = {str(item["path"]): item for item in before.inventory}
    after_map = {str(item["path"]): item for item in after.inventory}
    changed = sorted(
        path for path in before_map.keys() | after_map.keys()
        if (before_map.get(path, {}).get("sha256"), before_map.get(path, {}).get("bytes"))
        != (after_map.get(path, {}).get("sha256"), after_map.get(path, {}).get("bytes"))
    )
    writer.add_json(artifact_id, "diff", {
        "run_id": run_id, "execution_id": after.execution_id,
        "before": [dict(item) for item in before.inventory],
        "after": [dict(item) for item in after.inventory],
        "changed_paths": changed,
        "staged_paths": sorted(set(after.staged_paths) & set(changed)),
    })
    return artifact_id


_ASSERTION_TERMINAL_EVENTS = {
    "empty-wiki-first-question": "validate",
    "current-wiki-fast-path": "validate",
    "new-binary-before-question": "validate",
    "web-approval-and-capture": "persist_claim",
    "contradictory-evidence": "validate",
}

# A terminal snapshot is not itself a source checkpoint.  Each scenario maps
# assertion facts to the command that produced the corpus/published document
# those facts describe.  Never select the newest arbitrary source-state row:
# an unrelated later capture could otherwise launder a stale publication.
_ASSERTION_STATE_EVENTS = {
    "empty-wiki-first-question": "wiki_apply",
    "current-wiki-fast-path": "wiki_apply",
    "new-binary-before-question": "register_extraction_handoff",
    "web-approval-and-capture": "persist_claim",
    "contradictory-evidence": "wiki_apply",
}

_ASSERTION_TEXTS = {
    "empty-wiki-first-question": (
        "Exactly one evolving Alpha question record exists.",
        "Every factual answer passage has an exact resolving source-version-derivation citation.",
        "Every qualifying Alpha or Beta page relationship is reciprocal.",
    ),
    "current-wiki-fast-path": (
        "The existing question ID remains unique and its same file records the new risk-review phrasing.",
        "The Q&A update is published by one wiki transaction while source and ledger content stay unchanged.",
        "Every underlying citation is revalidated against the current ledger before WikiEvidencePacket sufficiency.",
    ),
    "new-binary-before-question": (
        "The new PDF has a ledgered content version and Markdown derivation before sufficiency judgment.",
        "Registration activation is proved by data.registration.active_representation and its corpus revision.",
        "The freshness probe is scoped to the newly active source ID.",
    ),
    "web-approval-and-capture": (
        "Used page has an immutable local sources/raw/_web version.",
        "Unused candidate has no source record.",
        "Claim citation resolves to the local source version and derivation.",
        "The question record stores the post-capture corpus revision and three pass terms.",
    ),
    "contradictory-evidence": (
        "The evolving question has conflicted status.",
        "Both dated claims retain exact resolving citations.",
        "The terminal canonical v2 QuestionRecord stores the policy's typed unresolved decision with null preference and approval IDs.",
    ),
    "repository-development-not-archived": (
        "No wiki question file is added or changed.",
        "No wiki page file is added or changed.",
        "Only requested software-development paths may differ.",
    ),
}


@dataclass(frozen=True)
class _AssertionSemanticContext:
    """One marker-time, source-state-bound view for closed assertion rules."""

    plan: _IndexedAssertionPlan
    terminal_marker: SemanticMarkerEvidence
    event_markers: Mapping[str, SemanticMarkerEvidence]
    marker_snapshot_ids: Mapping[str, str]
    marker_inventories: Mapping[str, Mapping[str, Mapping[str, Any]]]
    initial_inventory: Mapping[str, Mapping[str, Any]]
    terminal_inventory: Mapping[str, Mapping[str, Any]]
    states: tuple[_SemanticPacketState, ...]
    state: _SemanticPacketState
    diff: _RepositoryDiffEvidence


def _assertion_texts_for_scenario(
    scenario: Mapping[str, Any], raw_assertions: Sequence[str],
) -> tuple[str, ...]:
    """Keep assertion semantics closed to the six generator-owned scenarios."""

    scenario_id = scenario.get("id")
    expected = _ASSERTION_TEXTS.get(scenario_id)
    if expected is None or tuple(raw_assertions) != expected:
        raise RunnerError("repository assertion contract changed")
    return expected


def _state_files_match_snapshot(
    state: _SemanticPacketState,
    inventory: Mapping[str, Mapping[str, Any]],
) -> bool:
    """Require the full retained source/config view at one marker instant.

    Ledger records establish corpus identity, but they cannot establish that
    the raw bytes, extracted representations, and extractor registry still
    match the checkpoint that made a packet ``current``.  Compare the whole
    allowed source-state namespace, including absence of newly added files.
    """

    snapshot_files = {
        path: entry
        for path, entry in inventory.items()
        if path == "config/extractors.toml"
        or path.startswith(("sources/raw/", "sources/extracted/"))
    }
    if set(snapshot_files) != set(state.files):
        return False
    return all(
        snapshot_files[path].get("bytes") == len(raw)
        and snapshot_files[path].get("sha256") == _sha256(raw)
        for path, raw in state.files.items()
    )


def _snapshot_handoff_manifests_are_valid(
    writer: EvidenceWriter,
    inventory: Mapping[str, Mapping[str, Any]],
    state: _SemanticPacketState,
) -> bool:
    """Allow only canonical durable handoffs outside source-record identity.

    The source-state format intentionally records canonical ``src_`` records,
    raw bytes, extracted bytes, and the registry—not durable handoff
    manifests.  A real extraction workflow legitimately retains those
    manifests under ``sources/ledger/handoffs`` after registration.  They are
    not citation authority, so a marker-time packet may coexist with them only
    after re-parsing their immutable captures against the selected source
    checkpoint.  Every other auxiliary ledger path remains forbidden.
    """

    prefix = "sources/ledger/handoffs/"
    handoff_entries = [
        (path, entry)
        for path, entry in inventory.items()
        if path.startswith(prefix)
    ]
    if not handoff_entries:
        return True
    try:
        from datetime import datetime

        from brainlib.extractors.handoff import (
            _decode_item,
            _validate_item,
            handoff_to_dict,
        )

        seen: dict[str, bytes] = {}
        for path, entry in sorted(handoff_entries):
            name = path.removeprefix(prefix)
            if ("/" in name
                    or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}\.json", name) is None):
                return False
            raw = _writer_artifact_bytes(writer, entry["content_id"], "file_capture")
            document = _strict_json(raw, label="snapshot handoff manifest")
            if (type(document) is not dict
                    or set(document) != {"schema_version", "run_id", "created_at", "items"}
                    or document.get("schema_version") != 1
                    or document.get("run_id") != name.removesuffix(".json")
                    or type(document.get("created_at")) is not str
                    or type(document.get("items")) is not list
                    or not document["items"]
                    or _canonical_json(document) + b"\n" != raw):
                return False
            timestamp = datetime.fromisoformat(document["created_at"].replace("Z", "+00:00"))
            if timestamp.tzinfo is None or timestamp.utcoffset() is None:
                return False
            for fields in document["items"]:
                item = _decode_item(fields)
                _validate_item(item)
                canonical = _canonical_json(handoff_to_dict(item))
                prior = seen.get(item.handoff_id)
                if prior is not None and prior != canonical:
                    return False
                seen[item.handoff_id] = canonical
                record = state.sources.get(item.source_id)
                if record is None or item.content_sha256 not in record.versions:
                    return False
    except (AttributeError, KeyError, TypeError, ValueError, RunnerError):
        return False
    return True


def _snapshot_matches_semantic_state(
    writer: EvidenceWriter,
    *,
    snapshot: WorkspaceSnapshot,
    state: _SemanticPacketState,
) -> Mapping[str, Mapping[str, Any]] | None:
    """Require the marker-time ledger to equal its selected host checkpoint."""

    inventory = _semantic_snapshot_inventory(writer, snapshot)
    raw_state = _strict_json(
        _writer_artifact_bytes(writer, state.command.artifact_ids["source_state"], "source_state"),
        label="assertion source state",
    )
    records = raw_state.get("records") if type(raw_state) is dict else None
    if type(records) is not list:
        return None
    expected_ledger: dict[str, str] = {}
    previous = ""
    for item in records:
        if (type(item) is not dict or set(item) != {"path", "artifact_id"}
                or type(item.get("path")) is not str
                or type(item.get("artifact_id")) is not str
                or item["path"] <= previous
                or not item["path"].startswith("sources/ledger/src_")
                or not item["path"].endswith(".json")
                or item["path"] in expected_ledger):
            return None
        previous = item["path"]
        expected_ledger[item["path"]] = item["artifact_id"]
    if not expected_ledger:
        return None
    all_ledger = {
        path: entry for path, entry in inventory.items()
        if path.startswith("sources/ledger/")
    }
    snapshot_ledger = {
        path: entry for path, entry in all_ledger.items()
        if path.removeprefix("sources/ledger/").startswith("src_") and path.endswith(".json")
    }
    auxiliary = set(all_ledger) - set(snapshot_ledger)
    gitkeep = all_ledger.get("sources/ledger/.gitkeep")
    handoff_paths = {
        path for path in auxiliary
        if path.startswith("sources/ledger/handoffs/")
    }
    if (set(snapshot_ledger) != set(expected_ledger)
            or auxiliary - {"sources/ledger/.gitkeep"} - handoff_paths
            or gitkeep is not None and (
                gitkeep["bytes"] != 0 or gitkeep["sha256"] != _sha256(b"")
            )
            or not _snapshot_handoff_manifests_are_valid(writer, inventory, state)):
        return None
    for path, artifact_id in expected_ledger.items():
        raw_record = _writer_artifact_bytes(writer, artifact_id, "source_record")
        entry = snapshot_ledger[path]
        if entry["bytes"] != len(raw_record) or entry["sha256"] != _sha256(raw_record):
            return None
    # The checkpoint's complete retained-source capture must also match this
    # marker-time workspace view.  SourceRecord metadata alone is not a
    # substitute for raw/extracted bytes or the registry recipe.
    if not _state_files_match_snapshot(state, inventory):
        return None
    return inventory


def _assertion_marker_diff(
    writer: EvidenceWriter,
    *,
    run_id: str,
    before: WorkspaceSnapshot,
    after: WorkspaceSnapshot,
) -> _RepositoryDiffEvidence:
    """Write the one immutable assertion diff from two marker-owned views."""

    before = _indexed_workspace_snapshot(writer, before)
    after = _indexed_workspace_snapshot(writer, after)
    if (before.execution_id != after.execution_id or before.trace_sequence != 0
            or after.trace_sequence <= 0 or before.role != "initial"
            or after.role != "marker"):
        raise RunnerError("assertion marker snapshot identity invalid")
    _semantic_snapshot_inventory(writer, before)
    _semantic_snapshot_inventory(writer, after)
    before_map = {str(item["path"]): item for item in before.inventory}
    after_map = {str(item["path"]): item for item in after.inventory}
    changed = sorted(
        path for path in before_map.keys() | after_map.keys()
        if (before_map.get(path, {}).get("sha256"), before_map.get(path, {}).get("bytes"))
        != (after_map.get(path, {}).get("sha256"), after_map.get(path, {}).get("bytes"))
    )
    artifact_id = "repository-assertion-semantic-diff"
    writer.add_json(artifact_id, "diff", {
        "run_id": run_id, "execution_id": after.execution_id,
        "before_snapshot_id": before.artifact_id,
        "after_snapshot_id": after.artifact_id,
        "before": [dict(item) for item in before.inventory],
        "after": [dict(item) for item in after.inventory],
        "changed_paths": changed,
        "staged_paths": list(after.staged_paths),
    })
    return _read_repository_diff(writer, run_id=run_id, diff_id=artifact_id)


def _assertion_semantic_context(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    plan: _IndexedAssertionPlan,
    markers: Sequence[SemanticMarkerEvidence],
    marker_snapshots: Sequence[WorkspaceSnapshot],
    initial_snapshots: Mapping[str, WorkspaceSnapshot] | None,
    commands: Sequence[SemanticCommandEvidence],
    trace_snapshot_ids: Mapping[tuple[str, int], str] | None = None,
) -> _AssertionSemanticContext | None:
    """Build a closed terminal view without consulting the live workspace."""

    scenario_id = scenario.get("id")
    terminal_name = _ASSERTION_TERMINAL_EVENTS.get(scenario_id)
    if terminal_name is None or initial_snapshots is None:
        return None
    event = plan.events.get(terminal_name)
    if event is None:
        return None
    marker_id = event.get("transcript_marker_id")
    marker_matches = [marker for marker in markers if marker.marker_id == marker_id]
    if len(marker_matches) != 1:
        return None
    marker = marker_matches[0]
    if marker.candidate.event_name != terminal_name:
        return None
    try:
        snapshots: dict[tuple[str, int], WorkspaceSnapshot] = {}
        for snapshot in marker_snapshots:
            loaded = _indexed_workspace_snapshot(writer, snapshot)
            key = (loaded.execution_id, loaded.trace_sequence)
            if (loaded.role != "marker" or loaded.trace_sequence <= 0
                    or key in snapshots):
                return None
            snapshots[key] = loaded
        terminal = snapshots.get((marker.execution_id, marker.candidate.trace_sequence))
        raw_initial = initial_snapshots.get(marker.execution_id)
        if terminal is None or raw_initial is None:
            return None
        initial = _indexed_workspace_snapshot(writer, raw_initial)
        if (initial.role != "initial" or initial.execution_id != marker.execution_id
                or initial.trace_sequence != 0):
            return None
        terminal = _trace_owned_marker_workspace_snapshot(
            writer, terminal, marker, trace_snapshot_ids=trace_snapshot_ids,
        )
        initial_inventory = _semantic_snapshot_inventory(writer, initial)
        event_markers: dict[str, SemanticMarkerEvidence] = {}
        marker_snapshot_ids: dict[str, str] = {}
        marker_inventories: dict[str, Mapping[str, Mapping[str, Any]]] = {}
        for name, event_row in plan.events.items():
            event_marker_id = event_row.get("transcript_marker_id")
            matches = [candidate for candidate in markers if candidate.marker_id == event_marker_id]
            if len(matches) != 1 or matches[0].candidate.event_name != name:
                return None
            event_marker = matches[0]
            event_snapshot = snapshots.get((
                event_marker.execution_id, event_marker.candidate.trace_sequence,
            ))
            if event_snapshot is None:
                return None
            event_snapshot = _trace_owned_marker_workspace_snapshot(
                writer, event_snapshot, event_marker,
                trace_snapshot_ids=trace_snapshot_ids,
            )
            event_markers[name] = event_marker
            marker_snapshot_ids[name] = event_snapshot.artifact_id
            marker_inventories[name] = _semantic_snapshot_inventory(writer, event_snapshot)
        state_event = _ASSERTION_STATE_EVENTS.get(scenario_id)
        if state_event is None:
            return None
        state_record = plan.records.get(state_event)
        state_command_id = state_record.get("command_id") if state_record is not None else None
        if type(state_command_id) is not str:
            return None
        states = _semantic_packet_states(writer, commands, run_id=run_id)
        state_matches = [state for state in states if state.command.command_id == state_command_id]
        if len(state_matches) != 1:
            return None
        state = state_matches[0]
        if (state.command.execution_id != marker.execution_id
                or state.command.end_sequence >= marker.candidate.trace_sequence):
            return None
        terminal_inventory = _snapshot_matches_semantic_state(
            writer, snapshot=terminal, state=state,
        )
        if terminal_inventory is None:
            return None
        diff = _assertion_marker_diff(
            writer, run_id=run_id, before=initial, after=terminal,
        )
    except RunnerError:
        return None
    return _AssertionSemanticContext(
        plan, marker, event_markers, marker_snapshot_ids, marker_inventories, initial_inventory,
        terminal_inventory, tuple(states), state, diff,
    )


@dataclass(frozen=True)
class _CapturedWikiDocument:
    path: str
    model: Any
    citations: tuple[Any, ...]
    # These are the exact immutable ``file_capture`` bytes decoded once by
    # `_snapshot_wiki_documents`, never a later read from the fixture tree.
    # Assertion predicates use the production CommonMark scan to define their
    # deliberately closed, syntactic scope of visible answer passages.
    text: str
    scan: Any


def _inventory_capture_bytes(
    writer: EvidenceWriter,
    inventory: Mapping[str, Mapping[str, Any]],
    path: str,
) -> bytes:
    entry = inventory.get(path)
    if entry is None:
        raise RunnerError("assertion capture path unavailable")
    raw = _writer_artifact_bytes(writer, str(entry["content_id"]), "file_capture")
    if raw and (len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]):
        raise RunnerError("assertion capture bytes invalid")
    if not raw and (entry["bytes"] != 0 or entry["sha256"] != _sha256(b"")):
        raise RunnerError("assertion empty capture bytes invalid")
    return raw


def _snapshot_wiki_documents(
    writer: EvidenceWriter,
    inventory: Mapping[str, Mapping[str, Any]],
) -> Mapping[str, _CapturedWikiDocument]:
    """Parse only marker-captured wiki bytes with the production parsers."""

    try:
        from brainlib.citations import parse_citation_definitions
        from brainlib.markdown import scan_markdown
        from brainlib.wiki_models import parse_page, parse_question
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("wiki assertion parsers unavailable") from error
    documents: dict[str, _CapturedWikiDocument] = {}
    for path in sorted(inventory):
        family = "question" if path.startswith("wiki/questions/") else (
            "page" if path.startswith("wiki/pages/") else None
        )
        if family is None or not path.endswith(".md"):
            continue
        try:
            text = _inventory_capture_bytes(writer, inventory, path).decode("utf-8")
            scan = scan_markdown(text)
            if scan.diagnostics:
                raise ValueError("ambiguous markdown")
            citations = parse_citation_definitions(text, path=Path(path))
            definition_lines = {item.line for item in scan.citation_definitions}
            definition_counts: dict[str, int] = {}
            for item in scan.citation_definitions:
                definition_counts[item.citation_id] = definition_counts.get(item.citation_id, 0) + 1
            reference_counts: dict[str, int] = {}
            for item in scan.citation_markers:
                if item.line not in definition_lines:
                    reference_counts[item.citation_id] = reference_counts.get(item.citation_id, 0) + 1
            if (len(citations) != len(definition_counts)
                    or any(definition_counts.get(citation.citation_id) != 1
                           or reference_counts.get(citation.citation_id, 0) < 1
                           for citation in citations)
                    or any(citation_id not in definition_counts for citation_id in reference_counts)):
                raise ValueError("citation definition/use mismatch")
            model = (
                parse_question(Path(path), text=text)
                if family == "question" else parse_page(Path(path), text=text)
            )
        except (UnicodeDecodeError, ValueError, TypeError) as error:
            raise RunnerError("assertion wiki capture invalid") from error
        documents[path] = _CapturedWikiDocument(path, model, citations, text, scan)
    return documents


_FACTUAL_ANSWER_SECTIONS = (
    "Current answer",
    "Supporting evidence",
    "Contradictory evidence",
)


def _captured_answer_passages_are_exactly_cited(
    document: _CapturedWikiDocument,
    current_identities: frozenset[tuple[str, str, str, str, str, str, str]],
) -> bool:
    """Require a current citation for every visible answer-prose block.

    The scenario's English word ``factual`` cannot be decided from arbitrary
    prose without an LLM judgment.  The runner consequently uses a stricter,
    deterministic definition: every CommonMark-proven visible text block in
    the three answer-evidence sections must carry a current, exact resolving
    citation.  Hidden code, link destinations, front matter, relationship
    lists, and citation definitions are outside this closed scope.  This may
    fail a future run that an agent considers acceptable, but can never turn
    uncited visible prose into a passing assertion.
    """

    try:
        headings = tuple(document.scan.headings)
        required: dict[str, Any] = {}
        for heading in headings:
            if heading.level == 2 and heading.text in _FACTUAL_ANSWER_SECTIONS:
                if heading.text in required:
                    return False
                required[heading.text] = heading
        if set(required) != set(_FACTUAL_ANSWER_SECTIONS):
            return False
        citation_ids = {citation.citation_id for citation in document.citations}
        current_ids = {
            citation_id
            for path, citation_id, _source_id, _content, _derivation, _kind, _value
            in current_identities
            if path == document.path
        }
        if not citation_ids or current_ids != citation_ids:
            return False
        marker_lines: dict[int, set[str]] = {}
        for marker in document.scan.citation_markers:
            if marker.citation_id in current_ids:
                marker_lines.setdefault(marker.line, set()).add(marker.citation_id)
        if not marker_lines:
            return False

        # ``MarkdownVisibleText`` intentionally preserves raw inline chunks,
        # not block identities.  Adjacent physical lines can nevertheless be
        # different CommonMark blocks (for example, a paragraph followed
        # immediately by a list item), so reconstruct the parser's inline
        # block maps from precisely the captured model body.  The full-document
        # scan has frontmatter-inclusive coordinates while MarkdownIt maps are
        # body-relative; derive the exact physical offset from the immutable
        # captured text and reject any unreconciled span or parser map.
        body = document.model.body
        if not isinstance(body, str) or not document.text.endswith(body):
            return False
        frontmatter = document.text[:len(document.text) - len(body)]
        line_offset = len(re.findall(r"\r\n|\r|\n", frontmatter))
        body_line_count = len(re.findall(r"\r\n|\r|\n", body))
        if body and not body.endswith(("\n", "\r")):
            body_line_count += 1
        if body_line_count < 1:
            return False
        parser = MarkdownIt("commonmark", {"maxNesting": len(body) + 1})
        blocks: set[tuple[int, int]] = set()
        for token in parser.parse(body):
            if getattr(token, "type", None) != "inline":
                continue
            source_map = getattr(token, "map", None)
            if (
                not isinstance(source_map, (list, tuple))
                or len(source_map) != 2
                or type(source_map[0]) is not int
                or type(source_map[1]) is not int
            ):
                return False
            body_start, body_end = source_map
            if not 0 <= body_start < body_end <= body_line_count:
                return False
            block = (line_offset + body_start + 1, line_offset + body_end)
            if block in blocks:
                # A visible raw span must have exactly one authoritative
                # parser block owner; duplicate maps are ambiguous here.
                return False
            blocks.add(block)
        if not blocks:
            return False

        def block_for_visible_span(start_line: int, end_line: int) -> tuple[int, int] | None:
            owners = [
                block for block in blocks
                if block[0] <= start_line <= end_line <= block[1]
            ]
            return owners[0] if len(owners) == 1 else None

        for name in _FACTUAL_ANSWER_SECTIONS:
            heading = required[name]
            start = (heading.end_line if heading.end_line is not None else heading.line) + 1
            ending = len(document.text.splitlines())
            for candidate in headings:
                if candidate.line > heading.line and candidate.level <= heading.level:
                    ending = candidate.line - 1
                    break
            visible_blocks: set[tuple[int, int]] = set()
            for visible in document.scan.visible_text_spans:
                span = visible.source_span
                if not visible.text.strip():
                    continue
                overlaps = span.line <= ending and start <= span.end_line
                if not overlaps:
                    continue
                if not start <= span.line <= span.end_line <= ending:
                    return False
                block = block_for_visible_span(span.line, span.end_line)
                if block is None:
                    return False
                visible_blocks.add(block)
            if not visible_blocks:
                return False
            if any(
                not set().union(*(
                    marker_lines.get(line, set())
                    for line in range(block[0], block[1] + 1)
                ))
                for block in visible_blocks
            ):
                return False
        return True
    except (AttributeError, TypeError, ValueError):
        return False


def _captured_wiki_graph_is_valid(
    writer: EvidenceWriter,
    inventory: Mapping[str, Mapping[str, Any]],
    documents: Mapping[str, _CapturedWikiDocument],
    corpus_revision: str,
) -> bool:
    """Run the production graph validator over only retained capture bytes.

    ``validate_graph`` intentionally checks canonical logical paths through
    pinned directories.  Create empty private directories solely for that
    parser boundary; document text and index content remain the immutable
    indexed captures passed directly to it, and the temporary directory is
    removed before any evidence index is sealed.
    """

    try:
        from brainlib.graph import validate_graph

        index_text = _inventory_capture_bytes(writer, inventory, "wiki/index.md").decode("utf-8")
        # Do not let a caller pair this terminal inventory with parsed records
        # from a different workspace/capture.  Reparse every eligible wiki
        # file from the indexed bytes and use that reconstruction as the sole
        # graph input; the supplied map is only a convenient prior parse and
        # must be byte-for-byte identical to it.
        captured = _snapshot_wiki_documents(writer, inventory)
        if set(documents) != set(captured):
            return False
        for path, rebuilt in captured.items():
            supplied = documents.get(path)
            if (not isinstance(supplied, _CapturedWikiDocument)
                    or supplied.path != path
                    or supplied.text != rebuilt.text):
                return False
        with tempfile.TemporaryDirectory(prefix=".assertion-graph-", dir=writer.run_root) as raw_root:
            root = Path(raw_root).resolve()
            (root / "wiki/pages").mkdir(mode=0o700, parents=True)
            (root / "wiki/questions").mkdir(mode=0o700, parents=True)
            paths = RepoPaths(
                root=root,
                raw=root / "sources/raw",
                extracted=root / "sources/extracted",
                ledger_dir=root / "sources/ledger",
                ledger_summary=root / "sources/ledger.md",
                wiki_pages=root / "wiki/pages",
                wiki_questions=root / "wiki/questions",
                registry=root / "config/extractors.toml",
                lock=root / ".brain/source-write.lock",
            )
            captured_documents = {
                root / path: document.text
                for path, document in captured.items()
            }
            report = validate_graph(
                paths,
                documents=captured_documents,
                index_text=index_text,
                corpus_revision=corpus_revision,
            )
        return bool(report.ok)
    except (OSError, RunnerError, UnicodeDecodeError, ValueError, TypeError, AttributeError):
        return False


def _current_citation_identities(
    writer: EvidenceWriter,
    *,
    context: _AssertionSemanticContext,
    documents: Mapping[str, _CapturedWikiDocument],
) -> frozenset[tuple[str, str, str, str, str, str, str]]:
    """Resolve each captured citation against exact state and retained bytes."""

    try:
        from brainlib.citations import encode_markdown_path
        from brainlib.ledger import representation_for
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("citation assertion codecs unavailable") from error
    identities: set[tuple[str, str, str, str, str, str, str]] = set()
    logical_root = Path("/assertion-capture-root")
    for path, document in documents.items():
        for citation in document.citations:
            source = context.state.sources.get(citation.source_id)
            if (source is None
                    or source.active_content_sha256 != citation.content_sha256
                    or source.active_derivation_id != citation.derivation_id):
                raise RunnerError("assertion citation is not current")
            representation = representation_for(
                source, citation.content_sha256, citation.derivation_id,
            )
            if representation is None or citation.anchor not in representation.anchors:
                raise RunnerError("assertion citation representation missing")
            version = source.versions[citation.content_sha256]
            derivation = source.derivations[citation.derivation_id]
            raw_path = "sources/raw/" + representation.raw_path.as_posix()
            extracted_path = representation.extracted_path.as_posix()
            raw = _inventory_capture_bytes(writer, context.terminal_inventory, raw_path)
            extracted = _inventory_capture_bytes(writer, context.terminal_inventory, extracted_path)
            if (len(raw) != version.byte_size or _sha256(raw) != citation.content_sha256
                    or len(extracted) != derivation.output_byte_size
                    or _sha256(extracted) != representation.output_sha256):
                raise RunnerError("assertion cited source capture mismatch")
            logical_document = logical_root / path
            expected_original = encode_markdown_path(
                logical_document, logical_root / raw_path,
            )
            expected_extracted = encode_markdown_path(
                logical_document, logical_root / extracted_path,
            ) + f"#{citation.anchor.kind}:{citation.anchor.value}"
            if (citation.original_destination != expected_original
                    or citation.extracted_destination != expected_extracted):
                raise RunnerError("assertion citation destination mismatch")
            identity = (
                path, citation.citation_id, citation.source_id,
                citation.content_sha256, citation.derivation_id,
                citation.anchor.kind, citation.anchor.value,
            )
            if identity in identities:
                raise RunnerError("assertion duplicate citation identity")
            identities.add(identity)
    return frozenset(identities)


def _assertion_event_command(
    context: _AssertionSemanticContext, name: str,
) -> SemanticCommandEvidence | None:
    """Return a strict Task 7a command selected by one indexed event."""

    record = context.plan.records.get(name)
    if record is None:
        return None
    command_id = record.get("command_id")
    command = context.plan.commands.get(command_id)
    if command is None or not _semantic_command_matches(name, command):
        return None
    return command


def _assertion_event_position(context: _AssertionSemanticContext, name: str) -> int | None:
    event = context.plan.events.get(name)
    sequence = event.get("sequence") if event is not None else None
    return sequence if type(sequence) is int and sequence > 0 else None


def _assertion_event_diff(
    writer: EvidenceWriter,
    *,
    context: _AssertionSemanticContext,
    run_id: str,
    name: str,
) -> _RepositoryDiffEvidence | None:
    record = context.plan.records.get(name)
    diff_id = record.get("diff_id") if record is not None else None
    if type(diff_id) is not str:
        return None
    try:
        evidence = _read_repository_diff(writer, run_id=run_id, diff_id=diff_id)
    except RunnerError:
        return None
    if evidence.execution_id != context.terminal_marker.execution_id:
        return None
    return evidence


def _assertion_packet_citations(
    writer: EvidenceWriter,
    *,
    context: _AssertionSemanticContext,
    run_id: str,
    name: str,
) -> frozenset[tuple[str, str, str, str, str, str, str]] | None:
    """Read a current wiki packet and compare its captured document citations."""

    record = context.plan.records.get(name)
    packet_id = record.get("packet_id") if record is not None else None
    packet_marker = context.event_markers.get(name)
    marker_inventory = context.marker_inventories.get(name)
    if (type(packet_id) is not str or packet_marker is None
            or marker_inventory is None):
        return None
    try:
        # WikiEvidencePacket sufficiency is meaningful only after the exact
        # closed wiki-search cursor chain has drained.  The packet cannot
        # self-select an unrelated proof ID or omit it entirely.
        search_proof = _assertion_cursor_proof_identity(
            writer, context=context, name="wiki_search_drained", family="wiki_search",
        )
        if (search_proof is None
                or not _assertion_positions_in_order(
                    context, "wiki_search_drained", name,
                )):
            return None
        search_proof_id, search_command_ids = search_proof
        packet = _strict_json(
            _writer_artifact_bytes(writer, packet_id, "evidence_packet"),
            label="assertion evidence packet",
        )
        expected = {
            "run_id", "execution_id", "snapshot_id", "kind", "corpus_revision", "cursor_proof_ids",
            "ledger_ids", "citations", "complete", "current", "reason",
        }
        if (type(packet) is not dict or set(packet) != expected
                or packet.get("run_id") != run_id
                or packet.get("execution_id") != packet_marker.execution_id
                or packet.get("snapshot_id") != context.marker_snapshot_ids.get(name)
                or packet.get("kind") != "wiki"
                or packet.get("corpus_revision") != context.state.corpus_revision
                or packet.get("cursor_proof_ids") != [search_proof_id]
                or packet.get("complete") is not True or packet.get("current") is not True
                or packet.get("reason") is not None or type(packet.get("citations")) is not list):
            return None
        # The packet must use the exact source checkpoint that was latest at
        # *its* marker, not a later terminal checkpoint or an arbitrary
        # source-record artifact with a coincidentally matching revision.
        eligible_states = [
            state for state in context.states
            if state.command.execution_id == packet_marker.execution_id
            and state.command.end_sequence < packet_marker.candidate.trace_sequence
            and state.corpus_revision == packet["corpus_revision"]
        ]
        if not eligible_states:
            return None
        packet_state = max(
            eligible_states,
            key=lambda state: (state.command.end_sequence, state.command.command_id),
        )
        if (packet.get("ledger_ids") != list(packet_state.ledger_ids)
                or not _state_files_match_snapshot(packet_state, marker_inventory)):
            return None
        packet_documents: dict[str, _CapturedWikiDocument] = {}
        document_ids: dict[str, str] = {}
        for item in packet["citations"]:
            if (type(item) is not dict
                    or set(item) != {"document_path", "citation_id", "document_id"}
                    or any(type(item.get(key)) is not str or not item[key]
                           for key in ("document_path", "citation_id", "document_id"))):
                return None
            path = item["document_path"]
            if path in packet_documents:
                if document_ids[path] != item["document_id"]:
                    return None
                continue
            snapshot_entry = marker_inventory.get(path)
            if (snapshot_entry is None
                    or snapshot_entry.get("content_id") != item["document_id"]):
                return None
            raw = _writer_artifact_bytes(writer, item["document_id"], "file_capture")
            # Reconstruct only an immutable logical document capture; the
            # parser never opens the evaluated workspace.
            entry = {
                "path": path, "sha256": _sha256(raw), "bytes": len(raw),
                "content_id": item["document_id"],
            }
            packet_documents |= _snapshot_wiki_documents(writer, {path: entry})
            document_ids[path] = item["document_id"]
        citations = _current_citation_identities(
            writer, context=context, documents=packet_documents,
        )
        packet_pairs = {(item["document_path"], item["citation_id"]) for item in packet["citations"]}
        actual_pairs = {(path, citation_id) for path, citation_id, *_rest in citations}
        if packet_pairs != actual_pairs:
            return None
        # The common indexed-plan replay has already established that every
        # proof command closes before its marker.  Keep this local check too,
        # so a future caller cannot use a packet support helper without the
        # same trace-order binding.
        if any(command_id not in context.plan.commands for command_id in search_command_ids):
            return None
        return citations
    except RunnerError:
        return None


def _assertion_wiki_documents(
    writer: EvidenceWriter, context: _AssertionSemanticContext,
) -> Mapping[str, _CapturedWikiDocument] | None:
    try:
        return _snapshot_wiki_documents(writer, context.terminal_inventory)
    except RunnerError:
        return None


def _assertion_manifest(
    writer: EvidenceWriter,
    *,
    context: _AssertionSemanticContext,
    name: str,
) -> tuple[Mapping[str, Any], Mapping[str, Any]] | None:
    """Return one event-bound, pre-dispatch manifest and its exact body."""

    record = context.plan.records.get(name)
    manifest_id = record.get("manifest_id") if record is not None else None
    if type(manifest_id) is not str:
        return None
    try:
        wrapper = _strict_json(
            _writer_artifact_bytes(writer, manifest_id, "wiki_manifest"),
            label="assertion wiki manifest",
        )
        if (type(wrapper) is not dict or set(wrapper) != {"path", "content_id", "sha256"}
                or type(wrapper.get("path")) is not str
                or type(wrapper.get("content_id")) is not str
                or not _is_hex64(wrapper.get("sha256", ""))):
            return None
        raw = _writer_artifact_bytes(writer, wrapper["content_id"], "file_capture")
        if _sha256(raw) != wrapper["sha256"]:
            return None
        body = _strict_json(raw, label="assertion wiki manifest body")
        if type(body) is not dict:
            return None
        return wrapper, body
    except RunnerError:
        return None


def _assertion_cursor_proof_identity(
    writer: EvidenceWriter,
    *,
    context: _AssertionSemanticContext,
    name: str,
    family: str,
) -> tuple[str, tuple[str, ...]] | None:
    """Return an event-owned cursor proof only after exact index revalidation."""

    record = context.plan.records.get(name)
    proof_id = record.get("cursor_proof_id") if record is not None else None
    if type(proof_id) is not str:
        return None
    try:
        proof = _strict_json(
            _writer_artifact_bytes(writer, proof_id, "cursor_proof"),
            label="assertion cursor proof",
        )
    except RunnerError:
        return None
    command_ids = proof.get("command_ids") if type(proof) is dict else None
    if (type(proof) is not dict
            or set(proof) != {"run_id", "execution_id", "family", "command_ids"}
            or proof.get("run_id") != writer.run_id
            or proof.get("execution_id") != context.terminal_marker.execution_id
            or proof.get("family") != family
            or type(command_ids) is not list or not command_ids
            or any(type(command_id) is not str for command_id in command_ids)
            or len(command_ids) != len(set(command_ids))):
        return None
    if any(command_id not in context.plan.commands for command_id in command_ids):
        return None
    return proof_id, tuple(command_ids)


def _assertion_cursor_proof(
    writer: EvidenceWriter,
    *,
    context: _AssertionSemanticContext,
    name: str,
    family: str,
) -> tuple[str, ...] | None:
    """Compatibility projection of an exact cursor proof's command chain."""

    identity = _assertion_cursor_proof_identity(
        writer, context=context, name=name, family=family,
    )
    return None if identity is None else identity[1]


def _assertion_source_paths_unchanged(
    writer: EvidenceWriter, context: _AssertionSemanticContext,
) -> bool:
    """Compare source evidence, allowing only ledger-summary sync timestamp churn."""

    before = {
        path: entry for path, entry in context.initial_inventory.items()
        if path.startswith("sources/")
    }
    after = {
        path: entry for path, entry in context.terminal_inventory.items()
        if path.startswith("sources/")
    }
    if not before or set(before) != set(after):
        return False
    for path in before:
        if path != "sources/ledger.md":
            if (before[path]["sha256"] != after[path]["sha256"]
                    or before[path]["bytes"] != after[path]["bytes"]):
                return False
            continue
        try:
            before_lines = _inventory_capture_bytes(writer, before, path).splitlines(keepends=True)
            after_lines = _inventory_capture_bytes(writer, after, path).splitlines(keepends=True)
        except RunnerError:
            return False
        before_timestamp = [line for line in before_lines if line.startswith(b"Last synchronized: ")]
        after_timestamp = [line for line in after_lines if line.startswith(b"Last synchronized: ")]
        if (len(before_timestamp) != 1 or len(after_timestamp) != 1
                or [line for line in before_lines if line not in before_timestamp]
                != [line for line in after_lines if line not in after_timestamp]):
            return False
    return True


def _assertion_question(
    documents: Mapping[str, _CapturedWikiDocument], path: str,
) -> _CapturedWikiDocument | None:
    document = documents.get(path)
    if document is None or not hasattr(document.model, "question_id"):
        return None
    return document


def _assertion_positions_in_order(
    context: _AssertionSemanticContext, *names: str,
) -> bool:
    positions = [_assertion_event_position(context, name) for name in names]
    return all(position is not None for position in positions) and positions == sorted(positions)


def _current_wiki_assertion_facts(
    writer: EvidenceWriter, *, run_id: str, context: _AssertionSemanticContext,
) -> list[bool]:
    """Project the three fixed current-wiki assertions from immutable facts."""

    terminal_documents = _assertion_wiki_documents(writer, context)
    if terminal_documents is None:
        return [False, False, False]
    try:
        initial_documents = _snapshot_wiki_documents(writer, context.initial_inventory)
        final_question = _assertion_question(terminal_documents, "wiki/questions/what-is-alpha.md")
        initial_question = _assertion_question(initial_documents, "wiki/questions/what-is-alpha.md")
        fact_one = bool(
            final_question is not None and initial_question is not None
            and final_question.model.question_id == "question-alpha"
            and initial_question.model.question_id == "question-alpha"
            and sum(
                1 for document in terminal_documents.values()
                if hasattr(document.model, "question_id") and document.model.question_id == "question-alpha"
            ) == 1
            and "Explain Alpha for a risk review." in final_question.model.prior_phrasings
            and "Explain Alpha for a risk review." not in initial_question.model.prior_phrasings
        )
        stage = _assertion_event_diff(writer, context=context, run_id=run_id, name="stage_existing_question_update")
        apply = _assertion_event_diff(writer, context=context, run_id=run_id, name="wiki_apply")
        manifest = _assertion_manifest(writer, context=context, name="wiki_apply")
        fact_two = False
        if stage is not None and apply is not None and manifest is not None and final_question is not None:
            wrapper, body = manifest
            changes = body.get("changes")
            question_path = "wiki/questions/what-is-alpha.md"
            final_entry = context.terminal_inventory[question_path]
            apply_command = _assertion_event_command(context, "wiki_apply")
            apply_data = apply_command.result.get("data") if apply_command is not None else None
            reported_paths = apply_data.get("changed_paths") if type(apply_data) is dict else None
            if (type(changes) is list and len(changes) == 1 and type(changes[0]) is dict
                    and set(changes[0]) == {"operation", "path", "staging_path", "sha256"}
                    and changes[0].get("operation") == "write"
                    and changes[0].get("path") == question_path
                    and type(changes[0].get("staging_path")) is str
                    and changes[0]["staging_path"].startswith(".brain/wiki-staging/")
                    and changes[0]["staging_path"].endswith("/files/" + question_path)
                    and changes[0].get("sha256") == final_entry["sha256"]
                    and set(stage.changed_paths) == {changes[0]["staging_path"]}
                    and stage.after.get(changes[0]["staging_path"], {}).get("sha256") == changes[0]["sha256"]
                    and apply.after.get(question_path, {}).get("sha256") == changes[0]["sha256"]
                    and type(reported_paths) is list
                    and set(reported_paths) == {
                        path for path in apply.changed_paths if path.startswith("wiki/")
                    }
                    and set(reported_paths) in ({question_path}, {"wiki/index.md", question_path})
                    and all(
                        path == wrapper["path"]
                        or path.startswith(".brain/.wiki-transaction-journal")
                        or path.startswith(".brain/wiki-transaction-claims/.brain-tmp-claim-")
                        for path in apply.changed_paths if not path.startswith("wiki/")
                    )
                    and _assertion_source_paths_unchanged(writer, context)
                    and _assertion_positions_in_order(
                        context, "stage_existing_question_update", "wiki_apply", "validate",
                    )):
                fact_two = True
        final_citations = _current_citation_identities(
            writer, context=context, documents=terminal_documents,
        )
        packet_sets = [
            _assertion_packet_citations(writer, context=context, run_id=run_id, name=name)
            for name in (
                "revalidate_underlying_citations", "build_wiki_evidence_packet", "judge_sufficient",
            )
        ]
        fact_three = bool(
            final_citations and all(packet is not None and packet == final_citations for packet in packet_sets)
            and _assertion_positions_in_order(
                context, "revalidate_underlying_citations", "build_wiki_evidence_packet",
                "judge_sufficient", "stage_existing_question_update", "wiki_apply",
            )
        )
        return [fact_one, fact_two, fact_three]
    except RunnerError:
        return [False, False, False]


def _new_binary_assertion_facts(
    writer: EvidenceWriter, *, context: _AssertionSemanticContext,
) -> list[bool]:
    """Bind extraction/activation/freshness facts to the registration state."""

    try:
        from tests.evals import semantic_evidence as semantic

        registration_command = _assertion_event_command(context, "register_extraction_handoff")
        if registration_command is None:
            return [False, False, False]
        data = registration_command.result.get("data")
        registration = data.get("registration") if type(data) is dict else None
        if type(registration) is not dict:
            return [False, False, False]
        source_id = registration.get("source_id")
        content_sha256 = registration.get("content_sha256")
        derivation_id = registration.get("derivation_id")
        active = registration.get("active_representation")
        source = context.state.sources.get(source_id)
        if (type(source_id) is not str or type(content_sha256) is not str
                or type(derivation_id) is not str or type(active) is not dict
                or source is None):
            return [False, False, False]
        version = source.versions.get(content_sha256)
        derivation = source.derivations.get(derivation_id)
        raw_path = "sources/raw/" + version.raw_path.as_posix() if version is not None else ""
        extracted_path = derivation.output_path.as_posix() if derivation is not None else ""
        represented = (
            source.active_content_sha256 == content_sha256
            and source.active_derivation_id == derivation_id
            and registration.get("corpus_revision") == context.state.corpus_revision
            and active.get("source_id") == source_id
            and active.get("content_sha256") == content_sha256
            and active.get("derivation_id") == derivation_id
            and active.get("raw_path") == "quarterly.pdf"
            and active.get("extracted_path") == extracted_path
            and registration.get("output_path") == extracted_path
        )
        # Do not reduce an active representation to matching IDs and a
        # ``.md`` suffix.  Task 7a's decoder proves the active ledger join,
        # captured raw/extracted bytes, Markdown structure, and declared
        # anchors/quality state against this command-bound checkpoint.
        decoded_state = context.state.decoded_state
        if decoded_state is None:
            return [False, False, False]
        exact_representation = semantic.require_active_representation(active, decoded_state)
        captures = (
            version is not None and derivation is not None and source.media_type == "application/pdf"
            and version.raw_path.as_posix() == "quarterly.pdf"
            and extracted_path.endswith(".md")
            and raw_path in context.terminal_inventory
            and extracted_path in context.terminal_inventory
            and context.terminal_inventory[raw_path]["sha256"] == content_sha256
            and context.terminal_inventory[extracted_path]["sha256"] == derivation.output_sha256
            and active.get("output_sha256") == derivation.output_sha256
            and active.get("quality_state") == derivation.quality_state
            and tuple(active.get("anchors", ())) == tuple(
                {"kind": anchor.kind, "value": anchor.value}
                for anchor in derivation.anchors
            )
            and exact_representation.source_id == source_id
        )
        fact_one = bool(
            represented and captures
            and _assertion_positions_in_order(
                context, "register_extraction_handoff", "verify_registration_active_representation",
                "judge_insufficient",
            )
        )
        fact_two = bool(represented and captures and context.state.command.command_id == registration_command.command_id)
        freshness = _assertion_event_command(context, "freshness_search_batched")
        proof_ids = _assertion_cursor_proof(
            writer, context=context, name="freshness_search_drained", family="freshness_search_batched",
        )
        freshness_data = freshness.result.get("data") if freshness is not None else None
        fact_three = bool(
            freshness is not None and type(freshness_data) is dict
            and freshness_data.get("searched_source_ids") == [source_id]
            and proof_ids is not None and proof_ids[0] == freshness.command_id
            and _assertion_positions_in_order(
                context, "register_extraction_handoff", "freshness_search_batched", "freshness_search_drained",
            )
        )
        return [fact_one, fact_two, fact_three]
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError):
        return [False, False, False]


def _web_assertion_facts(
    writer: EvidenceWriter, *, run_id: str, context: _AssertionSemanticContext,
) -> list[bool]:
    """Project the approved-fixture web assertions without live URL access."""

    try:
        from tests.evals import semantic_evidence as semantic

        record = context.plan.records.get("select_used_source")
        capability_id = record.get("capability_id") if record is not None else None
        capability = _strict_json(
            _writer_artifact_bytes(writer, capability_id, "fixture_capability"),
            label="assertion fixture capability",
        ) if type(capability_id) is str else None
        descriptor_id = capability.get("descriptor_id") if type(capability) is dict else None
        descriptor = _strict_json(
            _writer_artifact_bytes(writer, descriptor_id, "fixture_descriptor"),
            label="assertion fixture descriptor",
        ) if type(descriptor_id) is str else None
        if (type(descriptor) is not dict
                or not _is_hex64(descriptor.get("static_sha256", ""))
                or not _is_hex64(descriptor.get("rendered_sha256", ""))
                or not _is_hex64(descriptor.get("unused_sha256", ""))):
            return [False, False, False, False]
        selected = _assertion_event_diff(writer, context=context, run_id=run_id, name="select_used_source")
        static_sha = descriptor["static_sha256"]
        rendered_sha = descriptor["rendered_sha256"]
        unused_sha = descriptor["unused_sha256"]
        static_versions = [
            (source, version) for source in context.state.sources.values()
            for version in source.versions.values()
            if version.sha256 == static_sha and version.raw_path.as_posix().startswith("_web/")
        ]
        # Workspace snapshots retain the immutable fixture tree.  An unused
        # fixture asset can therefore be present in every snapshot without a
        # client ever capturing it.  Only a changed-path diff entry proves a
        # candidate was persisted into the evaluated repository.
        selected_after = (
            tuple(selected.after[path] for path in selected.changed_paths
                  if path in selected.after)
            if selected is not None else ()
        )
        fact_one = bool(
            len(static_versions) == 1 and selected is not None
            and any(
                item["path"].startswith("sources/raw/_web/") and item["sha256"] == static_sha
                for item in selected_after
            )
            and all(item["sha256"] != unused_sha for item in selected_after)
            and _assertion_positions_in_order(
                context, "public_web_access", "select_used_source",
                "snapshot_used_source", "persist_claim",
            )
        )
        all_versions = [version.sha256 for source in context.state.sources.values()
                        for version in source.versions.values()]
        terminal_changed_after = tuple(
            context.diff.after[path] for path in context.diff.changed_paths
            if path in context.diff.after
        )
        fact_two = bool(
            unused_sha not in all_versions
            and all(entry["sha256"] != unused_sha for entry in terminal_changed_after)
        )
        documents = _assertion_wiki_documents(writer, context)
        rendered = _assertion_event_command(context, "verify_snapshot_active_representation")
        snapshot = rendered.result.get("data", {}).get("snapshot") if rendered is not None else None
        active = snapshot.get("active_representation") if type(snapshot) is dict else None
        identities = _current_citation_identities(writer, context=context, documents=documents) if documents is not None else frozenset()
        decoded_state = context.state.decoded_state
        exact_rendered = (
            decoded_state is not None and type(active) is dict
            and semantic.require_active_representation(active, decoded_state)
        )
        fact_three = bool(
            exact_rendered and active.get("content_sha256") == rendered_sha
            and any(
                source_id == active.get("source_id") and content == rendered_sha
                and derivation == active.get("derivation_id")
                for _path, _citation, source_id, content, derivation, _kind, _value in identities
            )
        )
        question = _assertion_question(documents or {}, "wiki/questions/external-standard.md")
        fact_four = bool(
            question is not None and question.model.corpus_revision == context.state.corpus_revision
            and question.model.search_terms.discovery == ("standard",)
            and question.model.search_terms.expansion == ("limit",)
            and question.model.search_terms.verification == ("12",)
            and _assertion_positions_in_order(
                context, "source_pass_discovery", "source_pass_expansion",
                "source_pass_verification", "link_candidates_drained", "persist_claim",
            )
        )
        return [fact_one, fact_two, fact_three, fact_four]
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError):
        return [False, False, False, False]


def _contradictory_typed_terminal_interpretation_fact(
    writer: EvidenceWriter,
    *,
    run_id: str,
    context: _AssertionSemanticContext,
    question: _CapturedWikiDocument | None,
    final_identities: set[tuple[str, str, str]],
) -> bool:
    """Prove the frozen v2 terminal interpretation without reading prose.

    This is intentionally stronger than a status-string or approval-note
    check.  It binds the parsed terminal QuestionRecord, policy identities,
    final apply state/manifest, terminal marker snapshot, approval event, and
    the exact decision witness.  A phrase such as ``Prefer 2025`` is neither
    an input nor a substitute for any typed field below.
    """

    try:
        policy = _frozen_contradictory_interpretation_policy(
            _scenario("contradictory-evidence"),
        )
        if policy is None or question is None:
            return False
        model = question.model
        interpretation = getattr(model, "interpretation", None)
        if (question.path != policy["question_path"]
                or model.question_id != policy["question_id"]
                or model.answer_status != "conflicted"
                or interpretation is None
                or interpretation.decision != policy["expected_decision"]
                or interpretation.preference_citation_id is not None
                or interpretation.approval_event_id is not None):
            return False
        expected_claims = [dict(item) for item in policy["claim_identities"]]
        expected_identities = {
            (item["source_id"], item["content_sha256"], item["derivation_id"])
            for item in expected_claims
        }
        if final_identities != expected_identities:
            return False
        terminal_entry = context.terminal_inventory.get(policy["question_path"])
        if (not isinstance(terminal_entry, Mapping)
                or type(terminal_entry.get("content_id")) is not str
                or not _is_hex64(terminal_entry.get("sha256", ""))):
            return False
        terminal_raw = _inventory_capture_bytes(
            writer, context.terminal_inventory, policy["question_path"],
        )
        if (terminal_raw.decode("utf-8", "strict") != question.text
                or _sha256(terminal_raw) != terminal_entry["sha256"]
                or model.corpus_revision != context.state.corpus_revision):
            return False
        approval_event = context.plan.events.get("ask_interpretation_approval")
        apply_event = context.plan.events.get("wiki_apply")
        validate_event = context.plan.events.get("validate")
        approval_record = context.plan.records.get("ask_interpretation_approval")
        apply_record = context.plan.records.get("wiki_apply")
        if any(not isinstance(item, Mapping) for item in (
            approval_event, apply_event, validate_event, approval_record, apply_record,
        )):
            return False
        approval_id = approval_record.get("approval_id")
        decision_id = approval_record.get("interpretation_decision_id")
        apply_command_id = apply_record.get("command_id")
        manifest_id = apply_record.get("manifest_id")
        if any(type(item) is not str or not item for item in (
            approval_id, decision_id, apply_command_id, manifest_id,
        )):
            return False
        entries = _writer_entry_map(writer)
        if (entries.get(approval_id, {}).get("type") != "approval"
                or entries.get(decision_id, {}).get("type") != "interpretation_decision"):
            return False
        approval = _strict_json(
            _writer_artifact_bytes(writer, approval_id, "approval"),
            label="contradictory assertion approval",
        )
        decision = _strict_json(
            _writer_artifact_bytes(writer, decision_id, "interpretation_decision"),
            label="contradictory assertion decision",
        )
        if (type(approval) is not dict or type(decision) is not dict
                or set(approval) != {
                    "run_id", "execution_id", "event_id", "scope", "note", "decision",
                    "fixture_id", "capability_id", "manifest_id",
                }
                or approval.get("run_id") != run_id
                or approval.get("execution_id") != approval_event.get("execution_id")
                or approval.get("decision") != policy["expected_approval_decision"]
                or approval.get("fixture_id") is not None
                or approval.get("capability_id") is not None
                or approval.get("manifest_id") != manifest_id):
            return False
        apply_command = _assertion_event_command(context, "wiki_apply")
        manifest = _assertion_manifest(writer, context=context, name="wiki_apply")
        if (apply_command is None or apply_command.command_id != apply_command_id
                or apply_command.artifact_ids.get("source_state") != context.state.state_id
                or context.state.command.command_id != apply_command_id
                or manifest is None):
            return False
        _manifest_capture, manifest_body = manifest
        changes = manifest_body.get("changes") if isinstance(manifest_body, Mapping) else None
        if (manifest_body.get("change_intent") != "routine"
                or manifest_body.get("approval_event_id") is not None
                or not isinstance(changes, list) or len(changes) != 1
                or not isinstance(changes[0], Mapping)
                or changes[0].get("operation") != "write"
                or changes[0].get("path") != policy["question_path"]
                or changes[0].get("sha256") != terminal_entry["sha256"]):
            return False
        terminal_snapshot_id = context.marker_snapshot_ids.get("validate")
        expected_decision = {
            "schema_version": 1,
            "run_id": run_id,
            "execution_id": validate_event.get("execution_id"),
            "scenario_id": "contradictory-evidence",
            "scenario_sha256": _FROZEN_CONTRADICTORY_SCENARIO_SHA256,
            "interpretation_policy_sha256": _FROZEN_INTERPRETATION_POLICY_SHA256,
            "approval_event_record_id": approval_event.get("event_record_id"),
            "approval_marker_id": approval_event.get("transcript_marker_id"),
            "approval_id": approval_id,
            "approval_event_id": approval.get("event_id"),
            "approval_decision": approval.get("decision"),
            "validate_event_record_id": validate_event.get("event_record_id"),
            "validate_marker_id": validate_event.get("transcript_marker_id"),
            "terminal_snapshot_id": terminal_snapshot_id,
            "wiki_apply_event_record_id": apply_event.get("event_record_id"),
            "wiki_apply_command_id": apply_command_id,
            "wiki_manifest_id": manifest_id,
            "question_path": policy["question_path"],
            "question_capture_id": terminal_entry["content_id"],
            "question_sha256": terminal_entry["sha256"],
            "question_id": policy["question_id"],
            "interpretation": {
                "decision": interpretation.decision,
                "preference_citation_id": interpretation.preference_citation_id,
                "approval_event_id": interpretation.approval_event_id,
            },
            "claim_identities": expected_claims,
        }
        return (decision == expected_decision
                and _assertion_positions_in_order(
                    context, "preserve_both_claims", "cite_both_sides",
                    "ask_interpretation_approval", "write_wiki_question",
                    "wiki_apply", "validate",
                ))
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError, UnicodeDecodeError):
        return False


def _contradictory_assertion_facts(
    writer: EvidenceWriter, *, run_id: str, context: _AssertionSemanticContext,
) -> list[bool]:
    """Prove only the factually observable contradictory-evidence claims."""

    try:
        documents = _assertion_wiki_documents(writer, context)
        initial_documents = _snapshot_wiki_documents(writer, context.initial_inventory)
        question = _assertion_question(documents or {}, "wiki/questions/what-is-alpha.md")
        initial_question = _assertion_question(
            initial_documents, "wiki/questions/what-is-alpha.md",
        )
        fact_one = bool(
            question is not None and initial_question is not None
            and initial_question.model.question_id == "question-what-is-alpha"
            and question.model.question_id == initial_question.model.question_id
            and question.model.answer_status == "conflicted"
            and _assertion_positions_in_order(
                context, "preserve_both_claims", "cite_both_sides",
                "ask_interpretation_approval", "wiki_apply", "validate",
            )
        )
        citations = _current_citation_identities(writer, context=context, documents=documents) if documents is not None else frozenset()
        initial_citations = _current_citation_identities(
            writer, context=context, documents=initial_documents,
        )
        expected = {
            (source.source_id, source.active_content_sha256, source.active_derivation_id)
            for source in context.state.sources.values()
            if source.current_raw_path.as_posix() in {"alpha-2024.txt", "alpha-2025.txt"}
        }
        expected_by_path = {
            source.current_raw_path.as_posix(): (
                source.source_id, source.active_content_sha256, source.active_derivation_id,
            )
            for source in context.state.sources.values()
            if source.current_raw_path.as_posix() in {"alpha-2024.txt", "alpha-2025.txt"}
        }
        source_claims = {
            "alpha-2024.txt": b"2024 Alpha limit is 10.",
            "alpha-2025.txt": b"2025 Alpha limit is 12.",
        }
        raw_claims_match = all(
            path in expected_by_path
            and _inventory_capture_bytes(
                writer, context.terminal_inventory, "sources/raw/" + path,
            ) == claim
            for path, claim in source_claims.items()
        )
        final_identities = {
            (source_id, content, derivation)
            for _path, _citation, source_id, content, derivation, _kind, _value in citations
        }
        initial_identities = {
            (source_id, content, derivation)
            for _path, _citation, source_id, content, derivation, _kind, _value in initial_citations
        }
        preserve = _assertion_event_diff(
            writer, context=context, run_id=run_id, name="preserve_both_claims",
        )
        cite = _assertion_event_diff(
            writer, context=context, run_id=run_id, name="cite_both_sides",
        )
        applied = _assertion_event_diff(
            writer, context=context, run_id=run_id, name="wiki_apply",
        )
        staged_question = "wiki/questions/what-is-alpha.md"
        body = question.model.body if question is not None else ""
        fact_two = bool(
            len(expected) == 2
            and expected <= final_identities
            and expected_by_path["alpha-2024.txt"] in initial_identities
            and raw_claims_match
            and all(token in body for token in ("2024", "2025", "10", "12"))
            and preserve is not None and cite is not None and applied is not None
            and all(
                len(diff.changed_paths) == 1
                and diff.changed_paths[0].startswith(".brain/wiki-staging/")
                and diff.changed_paths[0].endswith("/files/" + staged_question)
                for diff in (preserve, cite)
            )
            and set(applied.changed_paths) == {"wiki/index.md", staged_question}
            and _assertion_positions_in_order(
                context, "preserve_both_claims", "cite_both_sides", "ask_interpretation_approval", "wiki_apply",
            )
        )
        fact_three = _contradictory_typed_terminal_interpretation_fact(
            writer, run_id=run_id, context=context, question=question,
            final_identities=final_identities,
        )
        return [fact_one, fact_two, fact_three]
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError):
        return [False, False, False]


def _empty_wiki_assertion_facts(
    writer: EvidenceWriter, *, run_id: str, context: _AssertionSemanticContext,
) -> list[bool]:
    """Project closed empty-wiki facts from immutable terminal captures."""

    try:
        documents = _assertion_wiki_documents(writer, context)
        initial = _snapshot_wiki_documents(writer, context.initial_inventory)
        questions = [document for document in (documents or {}).values() if hasattr(document.model, "question_id")]
        initial_questions = [document for document in initial.values() if hasattr(document.model, "question_id")]
        stage = _assertion_event_diff(
            writer, context=context, run_id=run_id, name="write_wiki_question",
        )
        applied = _assertion_event_diff(
            writer, context=context, run_id=run_id, name="wiki_apply",
        )
        manifest = _assertion_manifest(writer, context=context, name="wiki_apply")
        final_entry = (context.terminal_inventory.get("wiki/questions/what-is-alpha-beta.md")
                       or context.terminal_inventory.get("wiki/questions/alpha-beta.md"))
        # The fixture's question filename is generator-owned.  Bind it from
        # the only final question rather than letting arbitrary terminal text
        # choose an unrelated pre-existing record.
        final_path = questions[0].path if len(questions) == 1 else ""
        final_entry = context.terminal_inventory.get(final_path)
        staged_path = (
            stage.changed_paths[0]
            if stage is not None and len(stage.changed_paths) == 1 else ""
        )
        manifest_changes = manifest[1].get("changes") if manifest is not None else None
        fact_one = bool(
            len(questions) == 1 and not initial_questions
            and questions[0].model.question_id == "question-alpha-beta"
            and "Alpha" in questions[0].model.canonical_question
            and stage is not None and staged_path.startswith(".brain/wiki-staging/")
            and staged_path.endswith("/files/" + final_path)
            and applied is not None
            and set(applied.changed_paths) == {"wiki/index.md", final_path}
            and final_entry is not None
            and type(manifest_changes) is list and len(manifest_changes) == 1
            and type(manifest_changes[0]) is dict
            and set(manifest_changes[0]) == {"operation", "path", "staging_path", "sha256"}
            and manifest_changes[0].get("operation") == "write"
            and manifest_changes[0].get("path") == final_path
            and manifest_changes[0].get("staging_path") == staged_path
            and manifest_changes[0].get("sha256") == final_entry["sha256"]
            and _assertion_positions_in_order(context, "write_wiki_question", "wiki_apply", "validate")
        )
        # Do not promote a generic successful citation parse into coverage for
        # answer prose.  Every visible CommonMark block in the closed answer
        # sections must instead carry a current exact citation.  This is
        # deliberately stricter than an LLM's potentially subjective
        # classification of a phrase as "factual".
        identities = _current_citation_identities(
            writer, context=context, documents=documents or {},
        ) if documents is not None else frozenset()
        fact_two = bool(
            fact_one
            and _captured_answer_passages_are_exactly_cited(questions[0], identities)
            and _assertion_positions_in_order(
                context, "write_wiki_question", "wiki_apply", "validate",
            )
        )
        # The graph predicate sees only retained terminal file captures.  It
        # feeds those exact bytes into the production validator, including the
        # generated index, rather than trusting a later live workspace or an
        # agent-declared relationship decision.  It is stronger than the
        # scenario's Alpha/Beta-only wording: no declared captured relation
        # may be nonreciprocal.
        links_check = _assertion_event_command(context, "links_check")
        report = (
            links_check.result.get("data", {}).get("report")
            if links_check is not None and type(links_check.result.get("data")) is dict
            else None
        )
        fact_three = bool(
            fact_one
            and links_check is not None
            and links_check.exit_code == 0
            and links_check.result.get("ok") is True
            and links_check.result.get("command") == "links check"
            and links_check.result.get("warnings") == []
            and links_check.result.get("errors") == []
            and type(report) is dict and report.get("issues") == []
            and _captured_wiki_graph_is_valid(
                writer, context.terminal_inventory, documents or {}, context.state.corpus_revision,
            )
            and _assertion_positions_in_order(
                context, "write_wiki_question", "link_candidates_drained", "wiki_apply",
                "links_check", "validate",
            )
        )
        return [fact_one, fact_two, fact_three]
    except (RunnerError, ValueError, TypeError, KeyError, AttributeError):
        return [False, False, False]


def _semantic_assertion_facts(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario_id: str,
    context: _AssertionSemanticContext,
) -> list[bool]:
    if scenario_id == "current-wiki-fast-path":
        return _current_wiki_assertion_facts(writer, run_id=run_id, context=context)
    if scenario_id == "new-binary-before-question":
        return _new_binary_assertion_facts(writer, context=context)
    if scenario_id == "web-approval-and-capture":
        return _web_assertion_facts(writer, run_id=run_id, context=context)
    if scenario_id == "contradictory-evidence":
        return _contradictory_assertion_facts(writer, run_id=run_id, context=context)
    if scenario_id == "empty-wiki-first-question":
        return _empty_wiki_assertion_facts(writer, run_id=run_id, context=context)
    raise RunnerError("unsupported semantic assertion scenario")


def _project_repository_assertions(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    marker_diff_references: Mapping[str, Mapping[str, str]],
    fallback_before: WorkspaceSnapshot | None,
    fallback_after: WorkspaceSnapshot | None,
    actual_client_verified: bool,
    semantic_plan: SemanticEventPlan | None = None,
    markers: Sequence[SemanticMarkerEvidence] = (),
    marker_snapshots: Sequence[WorkspaceSnapshot] = (),
    initial_snapshots: Mapping[str, WorkspaceSnapshot] | None = None,
    commands: Sequence[SemanticCommandEvidence] = (),
    execution_order: Mapping[str, int] | None = None,
    workspace: Path | None = None,
    trace_snapshot_ids: Mapping[tuple[str, int], str] | None = None,
    client: str | None = None,
    fixture_sha256: str | None = None,
    fixture_capability_id: str | None = None,
    approval: Mapping[str, str] | None = None,
) -> RepositoryAssertionProjection:
    """Write exact assertion artifacts from a closed, indexed diff source.

    Repository-development assertions must use the `use_software_workflow`
    marker's immutable workspace snapshot.  Knowledge-work assertions will
    additionally require an indexed semantic plan, marker-time snapshots, and
    command-bound source state before their closed scenario rules may be
    evaluated.  Every missing-evidence case receives a clearly
    non-authoritative fallback diff and false assertions; that keeps
    incomplete logs schema-shaped without inventing pass evidence.
    """

    if type(actual_client_verified) is not bool:
        raise RunnerError("invalid repository assertion execution status")
    raw_assertions = scenario.get("repository_assertions") if isinstance(scenario, Mapping) else None
    if (type(raw_assertions) is not list or not raw_assertions
            or any(type(text) is not str or not text for text in raw_assertions)):
        raise RunnerError("invalid scenario repository assertions")
    scenario_id = scenario.get("id")
    if type(scenario_id) is not str:
        raise RunnerError("invalid assertion projection scenario id")
    _assertion_texts_for_scenario(scenario, raw_assertions)
    marker_time_available = False
    evidence: _RepositoryDiffEvidence | None = None
    indexed_plan: _IndexedAssertionPlan | None = None
    try:
        # Repository-development uses a simpler marker/diff rule, but is not
        # exempt from the indexed lifecycle replay.  Otherwise a future real
        # executable flag could turn a hand-written diff into a pass.
        indexed_plan = _indexed_assertion_plan(
            writer, run_id=run_id, scenario=scenario, plan=semantic_plan,
            markers=markers, commands=commands, execution_order=execution_order,
            workspace=workspace, trace_snapshot_ids=trace_snapshot_ids,
            client=client, fixture_sha256=fixture_sha256,
            fixture_capability_id=fixture_capability_id, approval=approval,
        )
    except RunnerError:
        indexed_plan = None

    assertion_marker_id: str | None = None
    assertion_snapshot_id: str | None = None
    if scenario_id == "repository-development-not-archived" and indexed_plan is not None:
        reference = marker_diff_references.get("use_software_workflow")
        diff_id = reference.get("diff_id") if isinstance(reference, Mapping) else None
        event = indexed_plan.events.get("use_software_workflow")
        marker_id = event.get("transcript_marker_id") if event is not None else None
        marker = next((item for item in markers if item.marker_id == marker_id), None)
        expected_snapshot_id = (
            trace_snapshot_ids.get((marker.execution_id, marker.candidate.trace_sequence))
            if trace_snapshot_ids is not None and marker is not None else None
        )
        if (isinstance(reference, Mapping) and set(reference) == {"diff_id"}
                and type(diff_id) is str and type(marker_id) is str
                and marker is not None and type(expected_snapshot_id) is str):
            try:
                candidate = _read_repository_diff(writer, run_id=run_id, diff_id=diff_id)
            except RunnerError:
                candidate = None
            if (candidate is not None
                    and candidate.execution_id == marker.execution_id
                    and candidate.after_snapshot_id == expected_snapshot_id):
                evidence = candidate
                marker_time_available = True
                assertion_marker_id = marker_id
                assertion_snapshot_id = expected_snapshot_id
    if evidence is None:
        fallback_id = _fallback_repository_assertion_diff(
            writer, run_id=run_id, before=fallback_before, after=fallback_after,
        )
        evidence = _read_repository_diff(writer, run_id=run_id, diff_id=fallback_id)

    facts = [False] * len(raw_assertions)
    incomplete_reasons: list[str] = []
    if scenario_id == "repository-development-not-archived":
        if not marker_time_available:
            incomplete_reasons.append("semantic_assertion_index_unavailable")
        else:
            # The scenario's stable ordered assertion text intentionally maps
            # to these three closed checks; a changed scenario cannot smuggle
            # a new semantic claim into this generic repository-diff mechanism.
            facts = _repository_assertion_scope_facts(scenario, evidence.changed_paths)
    elif indexed_plan is None:
        incomplete_reasons.append("semantic_assertion_index_unavailable")
    else:
        context = _assertion_semantic_context(
            writer, run_id=run_id, scenario=scenario, plan=indexed_plan,
            markers=markers, marker_snapshots=marker_snapshots,
            initial_snapshots=initial_snapshots, commands=commands,
            trace_snapshot_ids=trace_snapshot_ids,
        )
        if context is None:
            incomplete_reasons.append("semantic_assertion_anchor_unavailable")
        else:
            evidence = context.diff
            marker_time_available = True
            assertion_marker_id = context.terminal_marker.marker_id
            assertion_snapshot_id = context.marker_snapshot_ids.get(
                context.terminal_marker.candidate.event_name,
            )
            try:
                facts = _semantic_assertion_facts(
                    writer, run_id=run_id, scenario_id=scenario_id, context=context,
                )
            except RunnerError:
                facts = [False] * len(raw_assertions)
            if len(facts) != len(raw_assertions) or any(type(fact) is not bool for fact in facts):
                facts = [False] * len(raw_assertions)
                incomplete_reasons.append("semantic_assertion_evaluator_invalid")
            for index, fact in enumerate(facts, 1):
                if not fact:
                    incomplete_reasons.append(
                        f"semantic_assertion_unproven:{scenario_id}:{index}"
                    )
    rules_satisfied = marker_time_available and all(facts)
    assertions: list[dict[str, Any]] = []
    for index, text in enumerate(raw_assertions, 1):
        # No current Task 7c route has a registered executable, so even an
        # otherwise complete injected fixture cannot make this true.  Retain
        # the parameter for a later registered path, but it remains false in
        # every Task 7c call site.
        passed = bool(actual_client_verified and marker_time_available and facts[index - 1])
        assertion_id = f"repository-assertion-{index}"
        proof: dict[str, Any] = {
            "run_id": run_id, "text": text, "passed": passed,
            "diff_id": evidence.artifact_id,
        }
        if (assertion_marker_id is not None and assertion_snapshot_id is not None
                and evidence.after_snapshot_id == assertion_snapshot_id):
            proof["marker_id"] = assertion_marker_id
            proof["snapshot_id"] = assertion_snapshot_id
        writer.add_json(assertion_id, "assertion", proof)
        assertions.append({
            "text": text, "assertion_id": assertion_id,
            "diff_id": evidence.artifact_id, "passed": passed,
        })
    return RepositoryAssertionProjection(
        tuple(assertions), marker_time_available, rules_satisfied,
        tuple(sorted(set(incomplete_reasons))),
    )


def _derive_repository_assertion_facts(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    marker_diff_references: Mapping[str, Mapping[str, str]],
    semantic_plan: SemanticEventPlan,
    markers: Sequence[SemanticMarkerEvidence],
    marker_snapshots: Sequence[WorkspaceSnapshot],
    initial_snapshots: Mapping[str, WorkspaceSnapshot],
    commands: Sequence[SemanticCommandEvidence],
    execution_order: Mapping[str, int],
    workspace: Path,
    trace_snapshot_ids: Mapping[tuple[str, int], str],
    client: str,
    fixture_sha256: str,
    fixture_capability_id: str | None,
    approval: Mapping[str, str] | None,
) -> RepositoryAssertionFacts:
    """Compute public assertion facts without writing fallback or assertion rows.

    The public route calls this only after it has adopted a complete candidate
    semantic graph.  Unlike the legacy incomplete projector, unavailable
    evidence is not papered over by a newly written fallback diff: it remains
    an explicit failed fact set and the candidate cannot become pass-shaped.
    """

    raw_assertions = scenario.get("repository_assertions") if isinstance(scenario, Mapping) else None
    if (type(raw_assertions) is not list or not raw_assertions
            or any(type(text) is not str or not text for text in raw_assertions)):
        raise RunnerError("invalid public assertion scenario")
    scenario_id = scenario.get("id")
    if type(scenario_id) is not str:
        raise RunnerError("invalid public assertion scenario")
    _assertion_texts_for_scenario(scenario, raw_assertions)
    texts = tuple(raw_assertions)
    facts = [False] * len(texts)
    incomplete_reasons: list[str] = []
    marker_time_available = False
    evidence: _RepositoryDiffEvidence | None = None
    assertion_marker_id: str | None = None
    assertion_snapshot_id: str | None = None
    try:
        indexed_plan = _indexed_assertion_plan(
            writer, run_id=run_id, scenario=scenario, plan=semantic_plan,
            markers=markers, commands=commands, execution_order=execution_order,
            workspace=workspace, trace_snapshot_ids=trace_snapshot_ids,
            client=client, fixture_sha256=fixture_sha256,
            fixture_capability_id=fixture_capability_id, approval=approval,
        )
    except RunnerError:
        indexed_plan = None
    if indexed_plan is None:
        incomplete_reasons.append("semantic_assertion_index_unavailable")
    elif scenario_id == "repository-development-not-archived":
        reference = marker_diff_references.get("use_software_workflow")
        diff_id = reference.get("diff_id") if isinstance(reference, Mapping) else None
        event = indexed_plan.events.get("use_software_workflow")
        marker_id = event.get("transcript_marker_id") if event is not None else None
        marker = next((item for item in markers if item.marker_id == marker_id), None)
        expected_snapshot_id = (
            trace_snapshot_ids.get((marker.execution_id, marker.candidate.trace_sequence))
            if marker is not None else None
        )
        if (isinstance(reference, Mapping) and set(reference) == {"diff_id"}
                and type(diff_id) is str and type(marker_id) is str
                and marker is not None and type(expected_snapshot_id) is str):
            try:
                candidate = _read_repository_diff(writer, run_id=run_id, diff_id=diff_id)
            except RunnerError:
                candidate = None
            if (candidate is not None and candidate.execution_id == marker.execution_id
                    and candidate.after_snapshot_id == expected_snapshot_id):
                evidence = candidate
                marker_time_available = True
                assertion_marker_id = marker_id
                assertion_snapshot_id = expected_snapshot_id
        if evidence is None:
            incomplete_reasons.append("semantic_assertion_index_unavailable")
        else:
            facts = _repository_assertion_scope_facts(scenario, evidence.changed_paths)
    elif indexed_plan is not None:
        context = _assertion_semantic_context(
            writer, run_id=run_id, scenario=scenario, plan=indexed_plan,
            markers=markers, marker_snapshots=marker_snapshots,
            initial_snapshots=initial_snapshots, commands=commands,
            trace_snapshot_ids=trace_snapshot_ids,
        )
        if context is None:
            incomplete_reasons.append("semantic_assertion_anchor_unavailable")
        else:
            evidence = context.diff
            marker_time_available = True
            assertion_marker_id = context.terminal_marker.marker_id
            assertion_snapshot_id = context.marker_snapshot_ids.get(
                context.terminal_marker.candidate.event_name,
            )
            try:
                facts = _semantic_assertion_facts(
                    writer, run_id=run_id, scenario_id=scenario_id, context=context,
                )
            except RunnerError:
                facts = [False] * len(texts)
            if (len(facts) != len(texts)
                    or any(type(fact) is not bool for fact in facts)):
                facts = [False] * len(texts)
                incomplete_reasons.append("semantic_assertion_evaluator_invalid")
    if len(facts) != len(texts) or any(type(fact) is not bool for fact in facts):
        facts = [False] * len(texts)
        incomplete_reasons.append("semantic_assertion_evaluator_invalid")
    for index, fact in enumerate(facts, 1):
        if not fact:
            incomplete_reasons.append(f"semantic_assertion_unproven:{scenario_id}:{index}")
    # Preserve an unavailable marker/snapshot join as an ordinary incomplete
    # result.  Raising here would turn a failed public candidate into a
    # control-flow error before the caller can retain its diagnostic stage.
    if (marker_time_available
            and (evidence is None or assertion_marker_id is None
                 or assertion_snapshot_id is None)):
        marker_time_available = False
        evidence = None
        assertion_marker_id = None
        assertion_snapshot_id = None
        incomplete_reasons.append("semantic_assertion_anchor_unavailable")
    return RepositoryAssertionFacts(
        texts=texts,
        facts=tuple(facts),
        diff_id=evidence.artifact_id if evidence is not None else None,
        marker_id=assertion_marker_id,
        snapshot_id=assertion_snapshot_id,
        marker_time_available=marker_time_available,
        incomplete_reasons=tuple(sorted(set(incomplete_reasons))),
    )


def _emit_public_repository_assertions(
    writer: EvidenceWriter,
    *,
    run_id: str,
    facts: RepositoryAssertionFacts,
) -> tuple[dict[str, Any], ...]:
    """Write pass-shaped assertion rows only from complete pure facts."""

    if (type(writer) is not EvidenceWriter
            or type(run_id) is not str
            or writer.run_id != run_id
            or type(facts) is not RepositoryAssertionFacts
            or not facts.complete):
        raise RunnerError("public assertion facts are incomplete")
    facts.__post_init__()
    if (facts.diff_id is None or facts.marker_id is None or facts.snapshot_id is None
            or any(entry.get("type") == "assertion" for entry in writer.entries)):
        raise RunnerError("public assertion facts lack a diff")
    assertions: list[dict[str, Any]] = []
    for index, text in enumerate(facts.texts, 1):
        assertion_id = f"repository-assertion-{index}"
        proof: dict[str, Any] = {
            "run_id": run_id,
            "text": text,
            "passed": True,
            "diff_id": facts.diff_id,
        }
        proof["marker_id"] = facts.marker_id
        proof["snapshot_id"] = facts.snapshot_id
        writer.add_json(assertion_id, "assertion", proof)
        assertions.append({
            "text": text,
            "assertion_id": assertion_id,
            "diff_id": facts.diff_id,
            "passed": True,
        })
    return tuple(assertions)


@dataclass(frozen=True)
class _SemanticPacketState:
    """One immutable source-state checkpoint eligible for a packet."""

    command: SemanticCommandEvidence
    state_id: str
    corpus_revision: str
    ledger_ids: tuple[str, ...]
    sources: Mapping[str, Any]
    files: Mapping[str, bytes]
    # The Task 7a source-state decoder is the authority for active
    # representation/Markdown-anchor claims.  Keep the decoded object beside
    # the defensive local projection so scenario evaluators do not re-create
    # a weaker parallel parser.
    decoded_state: Any | None = None


class _WriterSourceStateControl:
    """The narrow descriptor-like interface used by Task 7a's state codec.

    The runner has already copied every byte into ``EvidenceWriter``.  This
    adapter deliberately exposes only those indexed copies to the production
    semantic decoder; it has no workspace pathname API, so assertion facts
    cannot accidentally consult a mutated fixture tree.
    """

    def __init__(self, writer: EvidenceWriter, run_id: str) -> None:
        self.writer = writer
        self.run_id = run_id

    def read(self, artifact_id: str, artifact_type: str) -> bytes:
        return _writer_artifact_bytes(self.writer, artifact_id, artifact_type)

    def obj(self, artifact_id: str, artifact_type: str) -> dict[str, Any]:
        value = _strict_json(self.read(artifact_id, artifact_type), label="assertion typed artifact")
        if type(value) is not dict:
            raise RunnerError("assertion typed artifact is not an object")
        return value


def _source_state_expectation(command: SemanticCommandEvidence) -> tuple[str | None, str]:
    """Derive the one command-bound identity a captured state may claim."""

    try:
        from tests.evals import semantic_evidence as semantic

        suffix = list(command.argv[2:])
        if suffix in (["sync"], ["init"]) or suffix[:2] == ["source", "snapshot-url"] or (
                suffix[:2] == ["eval", "mock-web-capture"]
                and suffix[2:4] == ["--fixture-id", "web-approval-and-capture.initial"]):
            parsed = semantic.parse_manifest_response(
                dict(command.result), observed_exit_code=command.exit_code,
            )
            return parsed.reference.result_id, parsed.reference.corpus_revision
        data = command.result.get("data")
        if type(data) is not dict:
            raise RunnerError("source-state command data unavailable")
        if suffix[:2] == ["source", "consume-sync-result"]:
            result_id = data.get("result_id")
            revision = data.get("corpus_revision")
            if (type(result_id) is not str or not result_id.startswith("sync_")
                    or not _is_hex64(result_id.removeprefix("sync_"))
                    or not _is_hex64(revision)):
                raise RunnerError("source-state consumption identity invalid")
            return result_id, revision
        if suffix[:2] == ["source", "register-extraction"]:
            registration = data.get("registration")
            revision = registration.get("corpus_revision") if type(registration) is dict else None
            if not _is_hex64(revision):
                raise RunnerError("source-state registration identity invalid")
            return None, revision
        if suffix[:2] == ["wiki", "apply"]:
            revision = data.get("corpus_revision")
            if not _is_hex64(revision):
                raise RunnerError("source-state publication identity invalid")
            return None, revision
    except (ImportError, ValueError, TypeError, KeyError) as error:
        raise RunnerError("source-state command identity invalid") from error
    raise RunnerError("source-state command has no closed checkpoint role")


def _semantic_packet_states(
    writer: EvidenceWriter,
    commands: Sequence[SemanticCommandEvidence],
    *,
    run_id: str | None = None,
) -> tuple[_SemanticPacketState, ...]:
    """Parse complete source checkpoints from indexed conversion artifacts."""

    try:
        from brainlib.contracts import SourceRecord, compute_corpus_revision
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("source record codec unavailable for packet projection") from error

    if run_id is not None and not _is_hex64(run_id):
        raise RunnerError("invalid source-state run identity")
    entries = _writer_entry_map(writer)
    states: list[_SemanticPacketState] = []
    seen_state_ids: set[str] = set()
    semantic_control = _WriterSourceStateControl(writer, run_id) if run_id is not None else None
    for command in commands:
        state_id = command.artifact_ids.get("source_state")
        if state_id is None:
            continue
        if state_id in seen_state_ids or entries.get(state_id, {}).get("type") != "source_state":
            raise RunnerError("packet source-state ownership invalid")
        seen_state_ids.add(state_id)
        state = _strict_json(
            _writer_artifact_bytes(writer, state_id, "source_state"),
            label="packet source state",
        )
        expected = {
            "schema_version", "run_id", "execution_id", "command_id", "capture_point",
            "result_id", "corpus_revision", "records", "files", "pending_result_id",
        }
        if (type(state) is not dict or set(state) != expected
                or state.get("schema_version") != 1
                or run_id is not None and state.get("run_id") != run_id
                or state.get("command_id") != command.command_id
                or state.get("execution_id") != command.execution_id
                or state.get("capture_point") != "after_command_before_return"
                or not _is_hex64(state.get("corpus_revision", ""))
                or type(state.get("records")) is not list
                or type(state.get("files")) is not list
                or state.get("result_id") is not None and type(state.get("result_id")) is not str
                or state.get("pending_result_id") is not None and type(state.get("pending_result_id")) is not str):
            raise RunnerError("packet source-state shape invalid")
        if semantic_control is not None:
            observation = semantic_control.obj(command.command_id, "command_observation")
            expected_observation = {
                "run_id", "execution_id", "argv", "exit_code", "result_id", "result_sha256",
                "timestamp", "start_sequence", "end_sequence", "source_state_id",
            }
            if (set(observation) != expected_observation
                    or observation.get("run_id") != run_id
                    or observation.get("execution_id") != command.execution_id
                    or observation.get("argv") != list(command.argv)
                    or observation.get("exit_code") != command.exit_code
                    or observation.get("result_sha256") != command.result_sha256
                    or observation.get("start_sequence") != command.start_sequence
                    or observation.get("end_sequence") != command.end_sequence
                    or observation.get("source_state_id") != state_id
                    or type(observation.get("result_id")) is not str
                    or _writer_artifact_bytes(writer, observation["result_id"], "command_result")
                    != command.result_raw):
                raise RunnerError("packet source-state observation binding invalid")
            try:
                from tests.evals import semantic_evidence as semantic

                result_id, revision = _source_state_expectation(command)
                decoded_state = semantic.read_source_state(
                    semantic_control, command.command_id, result_id=result_id,
                    revision=revision, execution_id=command.execution_id,
                )
            except Exception as error:
                raise RunnerError("packet source-state semantic validation failed") from error
        else:
            decoded_state = None
        sources: dict[str, Any] = {}
        ledger_ids: list[str] = []
        prior_path = ""
        for record_entry in state["records"]:
            if (type(record_entry) is not dict or set(record_entry) != {"path", "artifact_id"}
                    or type(record_entry["path"]) is not str
                    or type(record_entry["artifact_id"]) is not str
                    or entries.get(record_entry["artifact_id"], {}).get("type") != "source_record"
                    or record_entry["path"] <= prior_path
                    or not record_entry["path"].startswith("sources/ledger/src_")
                    or not record_entry["path"].endswith(".json")):
                raise RunnerError("packet source-state records invalid")
            prior_path = record_entry["path"]
            try:
                parsed = SourceRecord.from_dict(_strict_json(
                    _writer_artifact_bytes(writer, record_entry["artifact_id"], "source_record"),
                    label="packet source record",
                ))
            except (TypeError, ValueError, KeyError) as error:
                raise RunnerError("packet source record codec invalid") from error
            if parsed.source_id in sources:
                raise RunnerError("packet source record duplicated")
            if record_entry["path"] != f"sources/ledger/{parsed.source_id}.json":
                raise RunnerError("packet source record path invalid")
            sources[parsed.source_id] = parsed
            ledger_ids.append(record_entry["artifact_id"])
        if (not ledger_ids
                or compute_corpus_revision(sources.values()) != state["corpus_revision"]):
            raise RunnerError("packet source-state corpus revision invalid")
        files: dict[str, bytes] = {}
        previous_file_path = ""
        for file_entry in state["files"]:
            if (type(file_entry) is not dict or set(file_entry) != {"path", "artifact_id"}
                    or type(file_entry.get("path")) is not str
                    or type(file_entry.get("artifact_id")) is not str
                    or file_entry["path"] <= previous_file_path
                    or file_entry["path"] in files
                    or entries.get(file_entry["artifact_id"], {}).get("type") != "file_capture"):
                raise RunnerError("packet source-state files invalid")
            path = file_entry["path"]
            pure = PurePosixPath(path)
            if (pure.is_absolute() or pure.as_posix() != path
                    or any(part in {"", ".", ".."} for part in pure.parts)
                    or not (path == "config/extractors.toml"
                            or path.startswith("sources/raw/")
                            or path.startswith("sources/extracted/"))):
                raise RunnerError("packet source-state file namespace invalid")
            previous_file_path = path
            files[path] = _writer_artifact_bytes(writer, file_entry["artifact_id"], "file_capture")
        if "config/extractors.toml" not in files:
            raise RunnerError("packet source-state registry capture unavailable")
        for source in sources.values():
            for version in source.versions.values():
                path = "sources/raw/" + version.raw_path.as_posix()
                raw = files.get(path)
                if raw is None or len(raw) != version.byte_size or _sha256(raw) != version.sha256:
                    raise RunnerError("packet source-state raw capture invalid")
            for derivation in source.derivations.values():
                path = derivation.output_path.as_posix()
                raw = files.get(path)
                if raw is None or len(raw) != derivation.output_byte_size or _sha256(raw) != derivation.output_sha256:
                    raise RunnerError("packet source-state extraction capture invalid")
        if decoded_state is not None:
            if (decoded_state.corpus_revision != state["corpus_revision"]
                    or {source_id: value.to_dict() for source_id, value in decoded_state.records.items()}
                    != {source_id: value.to_dict() for source_id, value in sources.items()}
                    or dict(decoded_state.files) != files):
                raise RunnerError("packet source-state decoder mismatch")
        states.append(_SemanticPacketState(
            command=command, state_id=state_id, corpus_revision=state["corpus_revision"],
            ledger_ids=tuple(ledger_ids), sources=sources, files=files,
            decoded_state=decoded_state,
        ))
    return tuple(states)


def _semantic_packet_drain_event(family: str) -> str | None:
    return {
        "wiki_search": "wiki_search_drained",
        "freshness_search_batched": "freshness_search_drained",
        "source_pass_discovery": "source_pass_discovery_drained",
        "source_pass_expansion": "source_pass_expansion_drained",
        "source_pass_verification": "source_pass_verification_drained",
        "link_candidates": "link_candidates_drained",
    }.get(family)


def _semantic_packet_proof(
    writer: EvidenceWriter,
    proof: SemanticCursorProofEvidence,
    command_by_id: Mapping[str, SemanticCommandEvidence],
) -> tuple[str, tuple[Mapping[str, Any], ...], int]:
    """Recheck one cursor proof before using its records in an evidence packet."""

    if _writer_entry_map(writer).get(proof.proof_id, {}).get("type") != "cursor_proof":
        raise RunnerError("packet cursor proof artifact unavailable")
    commands = [command_by_id.get(command_id) for command_id in proof.command_ids]
    if (not commands or any(command is None for command in commands)
            or any(command.execution_id != proof.execution_id for command in commands if command)):
        raise RunnerError("packet cursor proof command binding invalid")
    typed_commands = [command for command in commands if command is not None]
    if _cursor_start_family(typed_commands[0]) != proof.family:
        raise RunnerError("packet cursor proof family invalid")
    links = proof.family == "link_candidates"
    pages: list[Mapping[str, Any]] = []
    prior_end = 0
    for index, command in enumerate(typed_commands):
        if command.start_sequence <= prior_end:
            raise RunnerError("packet cursor proof command ordering invalid")
        page = _cursor_page(command, links=links)
        if (page["page_index"] != index
                or page["complete"] != (index == len(typed_commands) - 1)):
            raise RunnerError("packet cursor proof pagination invalid")
        if index:
            prior = pages[-1]
            expected = (
                ["./brain", "--json", "links", "candidates", "--cursor", prior["next_cursor"]]
                if links else ["./brain", "--json", "search", "--cursor", prior["next_cursor"]]
            )
            stable = [
                "run_id", "corpus_revision", "terms", "candidate_count",
                "candidate_manifest_sha256", "result_sha256",
            ]
            stable.extend(("page_path",) if links else (
                "scope", "mode", "pass_name", "searched_source_ids", "candidate_manifest",
            ))
            if (list(command.argv) != expected or prior["complete"]
                    or page["request_cursor"] != prior["next_cursor"]
                    or any(page[key] != pages[0][key] for key in stable)):
                raise RunnerError("packet cursor proof chain invalid")
        pages.append(page)
        prior_end = command.end_sequence
    records = tuple(
        item for page in pages for item in page["candidates" if links else "matches"]
    )
    return str(pages[0]["corpus_revision"]), records, typed_commands[-1].end_sequence


def _semantic_snapshot_inventory(
    writer: EvidenceWriter, snapshot: WorkspaceSnapshot,
) -> Mapping[str, Mapping[str, Any]]:
    """Validate one marker-time snapshot's immutable file-capture inventory."""

    snapshot = _indexed_workspace_snapshot(writer, snapshot)
    inventory: dict[str, Mapping[str, Any]] = {}
    for entry in snapshot.inventory:
        if (not isinstance(entry, Mapping) or set(entry) != {"path", "sha256", "bytes", "content_id"}
                or type(entry["path"]) is not str or entry["path"] in inventory
                or not _is_hex64(entry["sha256"])
                or type(entry["bytes"]) is not int or entry["bytes"] < 0
                or type(entry["content_id"]) is not str):
            raise RunnerError("packet workspace snapshot inventory invalid")
        raw = _writer_artifact_bytes(writer, entry["content_id"], "file_capture")
        if len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]:
            raise RunnerError("packet workspace snapshot bytes invalid")
        inventory[entry["path"]] = entry
    if list(inventory) != sorted(inventory):
        raise RunnerError("packet workspace snapshot inventory unordered")
    return inventory


def _build_semantic_packet_references(
    writer: EvidenceWriter,
    *,
    run_id: str,
    required_events: Sequence[str],
    markers: Sequence[SemanticMarkerEvidence],
    commands: Sequence[SemanticCommandEvidence],
    cursor_proofs: Sequence[SemanticCursorProofEvidence],
    marker_snapshots: Sequence[WorkspaceSnapshot],
    execution_order: Mapping[str, int],
    trace_snapshot_ids: Mapping[tuple[str, int], str] | None = None,
) -> dict[str, dict[str, str]]:
    """Project exact evidence packets from source-state and marker-time bytes.

    The builder deliberately has no workspace argument.  Every ledger record,
    citation document, search result, and cursor chain must already be an
    indexed raw capture or snapshot.  Missing/bad support simply remains
    absent for the planner to report as incomplete; malformed claimed support
    raises a named runner failure instead of being repaired from live files.
    """

    try:
        from brainlib.citations import parse_citation_definitions
        from tests.evals import event_log_contract as contract
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("packet projection dependencies unavailable") from error

    required = tuple(required_events)
    if (len(required) != len(set(required))
            or any(type(name) is not str or name not in contract.EVENT_RULES for name in required)):
        raise RunnerError("packet projection scenario invalid")
    positions = {name: index for index, name in enumerate(required)}
    command_by_id = {command.command_id: command for command in commands}
    if len(command_by_id) != len(commands):
        raise RunnerError("packet projection duplicate command")
    snapshots: dict[tuple[str, int], WorkspaceSnapshot] = {}
    for snapshot in marker_snapshots:
        loaded = _indexed_workspace_snapshot(writer, snapshot)
        key = (loaded.execution_id, loaded.trace_sequence)
        if (loaded.role != "marker" or loaded.trace_sequence <= 0
                or key in snapshots):
            raise RunnerError("packet projection marker snapshot invalid")
        snapshots[key] = loaded
    marker_by_name: dict[str, SemanticMarkerEvidence] = {}
    for marker in markers:
        name = marker.candidate.event_name
        if name in marker_by_name:
            raise RunnerError("packet projection duplicate marker")
        marker_by_name[name] = marker

    proof_data: dict[str, tuple[str, tuple[Mapping[str, Any], ...], int]] = {}
    for proof in cursor_proofs:
        if proof.proof_id in proof_data:
            raise RunnerError("packet projection duplicate cursor proof")
        proof_data[proof.proof_id] = _semantic_packet_proof(writer, proof, command_by_id)
    # Packet claims are pass-capable support evidence.  They therefore use
    # the same Task 7a decoder and run/observation binding as assertion
    # projection, never the compatibility path used by isolated helper tests.
    states = _semantic_packet_states(writer, commands, run_id=run_id)
    references: dict[str, dict[str, str]] = {}
    packet_names = {
        name for name in required
        if any(key == "packet_id" for key, _kind in contract.EVENT_RULES[name].references)
    }
    for name in required:
        if name not in packet_names:
            continue
        marker = marker_by_name.get(name)
        if marker is None:
            continue
        snapshot = snapshots.get((marker.execution_id, marker.candidate.trace_sequence))
        if snapshot is None:
            continue
        snapshot = _trace_owned_marker_workspace_snapshot(
            writer, snapshot, marker, trace_snapshot_ids=trace_snapshot_ids,
        )
        current_index = positions[name]
        available_proofs: list[tuple[int, SemanticCursorProofEvidence, str, tuple[Mapping[str, Any], ...], int]] = []
        for proof in cursor_proofs:
            drain = _semantic_packet_drain_event(proof.family)
            data = proof_data.get(proof.proof_id)
            if (drain is None or drain not in positions or positions[drain] >= current_index
                    or proof.execution_id != marker.execution_id or data is None
                    or data[2] >= marker.candidate.trace_sequence):
                continue
            available_proofs.append((positions[drain], proof, data[0], data[1], data[2]))
        if not available_proofs:
            continue
        revisions = {item[2] for item in available_proofs}
        if len(revisions) != 1:
            continue
        revision = next(iter(revisions))
        eligible_states = [
            state for state in states
            if state.command.execution_id == marker.execution_id
            and state.command.end_sequence < marker.candidate.trace_sequence
            and state.corpus_revision == revision
        ]
        if not eligible_states:
            continue
        state = max(eligible_states, key=lambda item: (item.command.end_sequence, item.command.command_id))
        inventory = _semantic_snapshot_inventory(writer, snapshot)
        # A packet marked current must prove the marker-time ledger equals the
        # command-bound checkpoint exactly, not merely contain its prior
        # records.  An added/deleted ledger record changes the corpus even if
        # all old capture bytes still match.
        captured_state = _strict_json(
            _writer_artifact_bytes(
                writer, state.command.artifact_ids["source_state"], "source_state",
            ),
            label="packet source state",
        )
        expected_ledger = {
            str(entry["path"]): str(entry["artifact_id"])
            for entry in captured_state["records"]
        }
        all_snapshot_ledger = {
            path: entry for path, entry in inventory.items()
            if path.startswith("sources/ledger/")
        }
        snapshot_ledger = {
            path: entry for path, entry in all_snapshot_ledger.items()
            if path.removeprefix("sources/ledger/").startswith("src_") and path.endswith(".json")
        }
        auxiliary_ledger_paths = set(all_snapshot_ledger) - set(snapshot_ledger)
        gitkeep = all_snapshot_ledger.get("sources/ledger/.gitkeep")
        handoff_paths = {
            path for path in auxiliary_ledger_paths
            if path.startswith("sources/ledger/handoffs/")
        }
        if (set(snapshot_ledger) != set(expected_ledger)
                or auxiliary_ledger_paths - {"sources/ledger/.gitkeep"} - handoff_paths
                or (gitkeep is not None and (gitkeep["bytes"] != 0 or gitkeep["sha256"] != _sha256(b"")))
                or any(
                    snapshot_ledger[path]["sha256"]
                    != _sha256(_writer_artifact_bytes(writer, artifact_id, "source_record"))
                    for path, artifact_id in expected_ledger.items()
                )
                or not _snapshot_handoff_manifests_are_valid(writer, inventory, state)
                or not _state_files_match_snapshot(state, inventory)):
            continue
        proof_ids = [proof.proof_id for _index, proof, _revision, _records, _end in sorted(available_proofs)]
        proof_paths = {
            str(item["path"])
            for _index, _proof, _revision, records, _end in available_proofs
            for item in records
            if isinstance(item, Mapping) and type(item.get("path")) is str
        }
        citations: list[dict[str, str]] = []
        for path in sorted(proof_paths):
            inventory_entry = inventory.get(path)
            if (inventory_entry is None or not path.startswith("wiki/")
                    or not path.endswith(".md")):
                continue
            raw = _writer_artifact_bytes(writer, inventory_entry["content_id"], "file_capture")
            try:
                parsed_citations = parse_citation_definitions(raw.decode("utf-8"), path=Path(path))
            except (UnicodeDecodeError, ValueError, TypeError) as error:
                raise RunnerError("packet citation document invalid") from error
            for citation in parsed_citations:
                try:
                    source = state.sources[citation.source_id]
                    derivation = source.derivations[citation.derivation_id]
                    valid = (
                        source.active_content_sha256 == citation.content_sha256
                        and source.active_derivation_id == citation.derivation_id
                        and derivation.source_sha256 == citation.content_sha256
                        and citation.anchor in derivation.anchors
                    )
                except (KeyError, AttributeError):
                    valid = False
                if not valid:
                    raise RunnerError("packet citation is not current")
                citations.append({
                    "document_path": path, "citation_id": citation.citation_id,
                    "document_id": str(inventory_entry["content_id"]),
                })
        citations.sort(key=lambda item: (item["document_path"], item["citation_id"]))
        if name in {"build_wiki_evidence_packet", "judge_sufficient", "revalidate_underlying_citations"}:
            if not citations:
                continue
            kind, complete, current, reason = "wiki", True, True, None
        elif name == "judge_insufficient":
            kind, complete, current = "insufficiency", True, True
            reason = (
                "no_supported_evidence" if "wiki_no_supported_evidence" in positions
                else "contradiction" if "ask_interpretation_approval" in positions
                else "incomplete"
            )
        else:  # closed EVENT_RULES currently has no other packet mode.
            raise RunnerError("packet projection unsupported event")
        artifact_id = "packet-" + marker.marker_id
        writer.add_json(artifact_id, "evidence_packet", {
            "run_id": run_id, "execution_id": marker.execution_id,
            "snapshot_id": snapshot.artifact_id,
            "kind": kind, "corpus_revision": revision,
            "cursor_proof_ids": proof_ids, "ledger_ids": list(state.ledger_ids),
            "citations": citations, "complete": complete, "current": current,
            "reason": reason,
        })
        references[name] = {"packet_id": artifact_id}
    return references


_INTERPRETATION_APPROVAL_NOTE = (
    "Do not approve a preferred interpretation; preserve both sourced limits."
)

# This identifier is deliberately runner-owned and never written to the
# EvidenceWriter.  It exists only in the in-memory private replay overlay so
# that Task 7a's exact EventRule can bind the approval marker before the
# terminal decision payload is derived from sealed command/snapshot evidence.
_PRIVATE_INTERPRETATION_DECISION_ID = "private-interpretation-decision"
_FROZEN_CONTRADICTORY_SCENARIO_SHA256 = (
    "4d2534394e4f6835df34c4184c7a319dcf2bb3eeaa93128033ced41483ef87c3"
)
_FROZEN_INTERPRETATION_POLICY_SHA256 = (
    "cb17a42a7ed14502ec7a65e5b4495596091af51cfafc13bff40e1cccd3383f8a"
)


def _frozen_contradictory_interpretation_policy(
    scenario: Mapping[str, Any],
) -> Mapping[str, Any] | None:
    """Return only Task 3's exact generated contradictory policy.

    The private runner normalizer is intentionally not a compatibility layer
    for arbitrary QuestionRecord text or scenario-shaped mappings.  It may
    consume exactly the accepted generated policy and its canonical scenario
    bytes; any fixture/policy drift must leave the semantic candidate
    incomplete until the evaluator and runner are deliberately updated
    together.
    """

    try:
        from tests.evals.generate_scenarios import (
            interpretation_policy_sha256,
            validate_interpretation_policy,
        )
        from tests.evals.phase_prompt_contract import scenario_sha256

        if scenario.get("id") != "contradictory-evidence":
            return None
        # Both helpers independently reject non-generated/foreign mappings;
        # the pinned digests additionally make this runner's accepted bridge
        # explicit rather than silently widening as fixtures evolve.
        validate_interpretation_policy(dict(scenario))
        if (scenario_sha256(scenario) != _FROZEN_CONTRADICTORY_SCENARIO_SHA256
                or interpretation_policy_sha256(dict(scenario))
                != _FROZEN_INTERPRETATION_POLICY_SHA256):
            return None
        policy = scenario.get("interpretation_policy")
        if (not isinstance(policy, Mapping)
                or policy.get("question_path") != "wiki/questions/what-is-alpha.md"
                or policy.get("question_id") != "question-what-is-alpha"
                or policy.get("expected_decision") != "unresolved"
                or policy.get("expected_approval_decision") != "withheld"
                or policy.get("preserve_both") is not True):
            return None
        claims = policy.get("claim_identities")
        if (not isinstance(claims, list) or len(claims) != 2
                or any(
                    not isinstance(claim, Mapping)
                    or set(claim) != {"source_id", "content_sha256", "derivation_id"}
                    or any(type(claim.get(key)) is not str or not claim[key]
                           for key in claim)
                    for claim in claims)
                or claims != sorted(
                    (dict(claim) for claim in claims),
                    key=lambda claim: (
                        claim["source_id"], claim["content_sha256"], claim["derivation_id"],
                    ),
                )):
            return None
        return dict(policy)
    except (ImportError, ValueError, TypeError, KeyError, AttributeError):
        return None


def _private_interpretation_decision_id(
    writer: EvidenceWriter,
    *,
    scenario: Mapping[str, Any],
    plan: SemanticEventPlan,
) -> str | None:
    """Validate the one ephemeral decision reference admitted by private replay.

    ``interpretation_decision`` is a public-proof artifact type, so the
    incomplete injected-process route is allowed only one runner-chosen
    virtual identity.  It cannot borrow a writer ID, occur in another event,
    or exist for a non-contradictory scenario.  The payload itself is derived
    later, after the command and snapshot joins are available.
    """

    try:
        if not plan.complete:
            raise RunnerError("private interpretation decision plan incomplete")
        entries = _writer_entry_map(writer)
        if (_PRIVATE_INTERPRETATION_DECISION_ID in entries
                or any(entry.get("type") == "interpretation_decision"
                       for entry in entries.values())):
            raise RunnerError("private interpretation decision is persisted or collides")
        required = scenario.get("required_events")
        if (type(required) is not list or not required
                or any(type(name) is not str for name in required)
                or tuple(event.get("name") if isinstance(event, Mapping) else None
                         for event in plan.events) != tuple(required)
                or len(plan.events) != len(required)
                or not isinstance(plan.event_records, Mapping)):
            raise RunnerError("private interpretation decision plan shape")
        seen_records: set[str] = set()
        uses: list[tuple[str, str]] = []
        for event in plan.events:
            if not isinstance(event, Mapping):
                raise RunnerError("private interpretation decision plan shape")
            name = event.get("name")
            record_id = event.get("event_record_id")
            if (type(name) is not str or type(record_id) is not str
                    or not record_id or record_id in seen_records):
                raise RunnerError("private interpretation decision plan shape")
            seen_records.add(record_id)
            record = plan.event_records.get(record_id)
            if not isinstance(record, Mapping):
                raise RunnerError("private interpretation decision plan shape")
            if "interpretation_decision_id" in record:
                value = record.get("interpretation_decision_id")
                if type(value) is not str or not value:
                    raise RunnerError("private interpretation decision reference")
                uses.append((name, value))
        if set(plan.event_records) != seen_records:
            raise RunnerError("private interpretation decision plan shape")
        if scenario.get("id") != "contradictory-evidence":
            if uses:
                raise RunnerError("private interpretation decision outside contradictory scenario")
            return None
        if _frozen_contradictory_interpretation_policy(scenario) is None:
            raise RunnerError("private interpretation decision policy")
        if uses != [("ask_interpretation_approval", _PRIVATE_INTERPRETATION_DECISION_ID)]:
            raise RunnerError("private interpretation decision reference")
        ask_event = next(
            event for event in plan.events
            if event.get("name") == "ask_interpretation_approval"
        )
        ask_record = plan.event_records[ask_event["event_record_id"]]
        if (type(ask_record.get("approval_id")) is not str
                or not ask_record["approval_id"]):
            raise RunnerError("private interpretation decision approval reference")
        return _PRIVATE_INTERPRETATION_DECISION_ID
    except (AttributeError, KeyError, TypeError, ValueError) as error:
        raise RunnerError("private interpretation decision plan shape") from error


def _scripted_interpretation_approval(
    scenario: Mapping[str, Any],
) -> dict[str, str] | None:
    """Return the one closed fixture decision the runner may project.

    This is intentionally not a general approval interface.  A client cannot
    manufacture an interpretation decision from transcript prose or an
    arbitrary scenario value: the evaluator owns one exact contradictory
    fixture script and projects its deliberately non-authorizing outcome.
    """

    required = scenario.get("required_events")
    if (_frozen_contradictory_interpretation_policy(scenario) is None
            or type(required) is not list
            or len(required) != len(set(required))
            or not {"ask_interpretation_approval", "wiki_apply"} <= set(required)
            or scenario.get("approval_script") != [_INTERPRETATION_APPROVAL_NOTE]):
        return None
    return {
        "event_id": "interpretation-withheld",
        "scope": "preserve both sourced limits",
        "note": _INTERPRETATION_APPROVAL_NOTE,
        "decision": "withheld",
    }


def _build_interpretation_approval_reference(
    writer: EvidenceWriter,
    *,
    run_id: str,
    scenario: Mapping[str, Any],
    markers: Sequence[SemanticMarkerEvidence],
    commands: Sequence[SemanticCommandEvidence],
    execution_order: Mapping[str, int],
) -> tuple[dict[str, dict[str, str]], dict[str, str] | None]:
    """Bind the fixture's withheld decision to one post-marker final apply.

    The final semantic planner independently selects the command that
    corroborates ``wiki_apply``.  This narrow preprojection admits a manifest
    only when there is exactly one same-execution, parser-valid apply command
    after the interpretation marker (and before its final apply marker when
    present).  Ambiguity deliberately leaves the event unsupported.
    """

    approval = _scripted_interpretation_approval(scenario)
    if approval is None:
        return {}, None
    interpretation_markers = [
        marker for marker in markers
        if marker.candidate.event_name == "ask_interpretation_approval"
    ]
    if len(interpretation_markers) != 1:
        return {}, None
    interpretation_marker = interpretation_markers[0]
    marker_position = _semantic_position(
        execution_order, interpretation_marker.execution_id,
        interpretation_marker.candidate.trace_sequence,
    )
    if marker_position is None:
        return {}, None
    apply_markers = [
        marker for marker in markers
        if marker.candidate.event_name == "wiki_apply"
    ]
    if len(apply_markers) > 1:
        return {}, None
    final_marker_position: tuple[int, int] | None = None
    if apply_markers:
        final_marker = apply_markers[0]
        if final_marker.execution_id != interpretation_marker.execution_id:
            return {}, None
        final_marker_position = _semantic_position(
            execution_order, final_marker.execution_id,
            final_marker.candidate.trace_sequence,
        )
        if final_marker_position is None or final_marker_position <= marker_position:
            return {}, None
    entries = _writer_entry_map(writer)
    if (_PRIVATE_INTERPRETATION_DECISION_ID in entries
            or any(entry.get("type") == "interpretation_decision"
                   for entry in entries.values())):
        return {}, None
    candidates: list[SemanticCommandEvidence] = []
    for command in commands:
        start = _semantic_position(execution_order, command.execution_id, command.start_sequence)
        end = _semantic_position(execution_order, command.execution_id, command.end_sequence)
        manifest_id = command.artifact_ids.get("wiki_manifest")
        if (command.execution_id != interpretation_marker.execution_id
                or start is None or end is None or not marker_position < start < end
                or final_marker_position is not None and not end < final_marker_position
                or not _semantic_command_matches("wiki_apply", command)
                or type(manifest_id) is not str
                or entries.get(manifest_id, {}).get("type") != "wiki_manifest"):
            continue
        candidates.append(command)
    if len(candidates) != 1:
        return {}, None
    manifest_id = candidates[0].artifact_ids["wiki_manifest"]
    writer.add_json("interpretation-approval", "approval", {
        "run_id": run_id,
        "execution_id": interpretation_marker.execution_id,
        **approval,
        "fixture_id": None,
        "capability_id": None,
        "manifest_id": manifest_id,
    })
    return {
        "ask_interpretation_approval": {
            "approval_id": "interpretation-approval",
            "interpretation_decision_id": _PRIVATE_INTERPRETATION_DECISION_ID,
        },
    }, approval


def _writer_entry_map(writer: EvidenceWriter) -> dict[str, dict[str, Any]]:
    return {str(entry["id"]): dict(entry) for entry in writer.entries}


def _require_unique_writer_entry_ids(writer: EvidenceWriter) -> None:
    """Fail closed before a mutable evidence list can exploit last-row wins."""

    seen: set[str] = set()
    for entry in writer.entries:
        artifact_id = entry.get("id") if isinstance(entry, Mapping) else None
        if (type(artifact_id) is not str or not artifact_id or artifact_id in seen):
            raise RunnerError("runner evidence entry identities are invalid")
        seen.add(artifact_id)


def _writer_artifact_bytes(
    writer: EvidenceWriter,
    artifact_id: str,
    expected_type: str,
    *,
    control_pin: PinnedDirectory | None = None,
) -> bytes:
    entry = _writer_entry_map(writer).get(artifact_id)
    if entry is None or entry.get("type") != expected_type:
        raise RunnerError("missing typed runner artifact")
    relative = entry.get("relative_path")
    if type(relative) is not str:
        raise RunnerError("runner artifact path is invalid")
    path = PurePosixPath(relative)
    if (path.is_absolute() or path.as_posix() != relative
            or not path.parts or any(part in {"", ".", ".."} for part in path.parts)):
        raise RunnerError("runner artifact path is invalid")
    if control_pin is None:
        try:
            run_root = writer.run_root.resolve(strict=True)
            candidate = run_root.joinpath(*path.parts)
            resolved = candidate.resolve(strict=True)
            if not resolved.is_relative_to(run_root):
                raise RunnerError("runner artifact escaped run root")
        except RunnerError:
            raise
        except (OSError, ValueError) as error:
            raise RunnerError("runner artifact path is unavailable") from error
        raw = _safe_read(candidate)
    else:
        if (not isinstance(control_pin, PinnedDirectory)
                or not control_pin.private
                or control_pin.path != writer.control_root.resolve()
                or writer.run_root != control_pin.path / "runs" / writer.run_id):
            raise RunnerError("runner artifact control pin mismatch")
        raw = PinnedDirectory.read_relative(
            control_pin,
            PurePosixPath("runs", writer.run_id, *path.parts).as_posix(),
        )
    if len(raw) != entry.get("bytes") or _sha256(raw) != entry.get("sha256"):
        raise RunnerError("runner artifact changed before semantic planning")
    return raw


def _semantic_commands_from_conversion(
    writer: EvidenceWriter,
    conversion: ShimCaptureConversion,
) -> tuple[SemanticCommandEvidence, ...]:
    """Read command facts only from the immutable copied Task 7b artifacts."""

    entries = _writer_entry_map(writer)
    commands: list[SemanticCommandEvidence] = []
    for command_id in conversion.observation_ids:
        observation = _strict_json(
            _writer_artifact_bytes(writer, command_id, "command_observation"),
            label="semantic command observation",
        )
        required = {
            "run_id", "execution_id", "argv", "exit_code", "result_id", "result_sha256",
            "timestamp", "start_sequence", "end_sequence", "source_state_id",
        }
        if (type(observation) is not dict or set(observation) != required
                or observation.get("execution_id") is None
                or type(observation["argv"]) is not list
                or any(type(item) is not str for item in observation["argv"])):
            raise RunnerError("invalid semantic command observation")
        result_raw = _writer_artifact_bytes(
            writer, str(observation["result_id"]), "command_result",
        )
        if _sha256(result_raw) != observation["result_sha256"]:
            raise RunnerError("semantic command result digest mismatch")
        result = _strict_json(result_raw, label="semantic command result")
        if type(result) is not dict:
            raise RunnerError("semantic command result is not an object")
        artifacts: dict[str, str] = {}
        for label, artifact_type, suffix in (
            ("sync_stream", "sync_stream", "stream"),
            ("consumption_receipt", "consumption_receipt", "durable"),
            ("delivery", "delivery", "delivery"),
            ("wiki_manifest", "wiki_manifest", "wiki-manifest"),
        ):
            artifact_id = f"{command_id}-{suffix}"
            entry = entries.get(artifact_id)
            if entry is not None and entry.get("type") == artifact_type:
                artifacts[label] = artifact_id
        source_state_id = observation.get("source_state_id")
        if (type(source_state_id) is str
                and entries.get(source_state_id, {}).get("type") == "source_state"):
            artifacts["source_state"] = source_state_id
        commands.append(SemanticCommandEvidence(
            command_id=command_id,
            execution_id=observation["execution_id"],
            argv=tuple(observation["argv"]),
            result=result,
            result_raw=result_raw,
            result_sha256=observation["result_sha256"],
            start_sequence=observation["start_sequence"],
            end_sequence=observation["end_sequence"],
            exit_code=observation["exit_code"],
            artifact_ids=artifacts,
        ))
    return tuple(commands)


def _receipt_verified_result_id(
    operation: str,
    command: SemanticCommandEvidence,
) -> str | None:
    """Read one receipt origin only from its sealed verification result.

    Several receipt operations deliberately share the same `sync` command
    grammar.  A consume command's argv alone therefore cannot say whether it
    belongs to the initial or post-registration lifecycle.  The manifest
    result ID from its ordered verification command is the closed origin.
    """

    if not _semantic_command_matches(operation + "_receipt_verified", command):
        return None
    try:
        from tests.evals import event_log_contract as contract

        result = command.result
        if operation == "initial_snapshot":
            result = contract._snapshot_product(result)
        manifest = contract._manifest(result)
    except Exception as error:
        raise RunnerError("invalid receipt verification origin") from error
    result_id = manifest.get("result_id")
    if type(result_id) is not str or re.fullmatch(r"sync_[0-9a-f]{64}", result_id) is None:
        raise RunnerError("invalid receipt verification result identity")
    return result_id


def _receipt_lifecycle_result_id(command: SemanticCommandEvidence) -> str | None:
    """Return an exact consume/replay result ID only when both joins agree."""

    args = list(command.argv[2:])
    data = command.result.get("data") if type(command.result) is dict else None
    if (len(args) != 4 or args[:2] != ["source", "consume-sync-result"]
            or args[2] != "--result-id" or type(data) is not dict
            or data.get("result_id") != args[3]
            or re.fullmatch(r"sync_[0-9a-f]{64}", args[3]) is None):
        return None
    return args[3]


def _receipt_operation_origins(
    commands: Sequence[SemanticCommandEvidence],
    receipt_operations: Sequence[str],
) -> dict[str, str]:
    """Bind each operation to one ordered, non-reusable verification origin."""

    origins: dict[str, str] = {}
    claimed_commands: set[str] = set()
    claimed_result_ids: set[str] = set()
    ordered = sorted(
        commands,
        key=lambda command: (
            command.execution_id, command.start_sequence,
            command.end_sequence, command.command_id,
        ),
    )
    for operation in receipt_operations:
        candidates: list[tuple[SemanticCommandEvidence, str]] = []
        for command in ordered:
            if command.command_id in claimed_commands:
                continue
            result_id = _receipt_verified_result_id(operation, command)
            if result_id is not None:
                candidates.append((command, result_id))
        if not candidates:
            # The planner will name the missing lifecycle.  There is no
            # delivery authority to project in the meantime.
            continue
        command, result_id = candidates[0]
        if result_id in claimed_result_ids:
            raise RunnerError("receipt verification result identity reused")
        claimed_commands.add(command.command_id)
        claimed_result_ids.add(result_id)
        origins[operation] = result_id
    return origins


def _semantic_deliveries_from_commands(
    writer: EvidenceWriter,
    commands: Sequence[SemanticCommandEvidence],
    receipt_operations: Sequence[str],
) -> tuple[SemanticDeliveryEvidence, ...]:
    """Project immutable Task 7b delivery bytes onto first receipt consumes.

    The shim captures the same durable delivery again when the client performs
    the required ``already_consumed`` replay.  That replay is useful receipt
    evidence but is *not* authority for a delivery branch.  Select exactly
    one ``status=consumed`` command per operation, validate the captured
    immutable delivery with the production codecs, and leave no command with
    a delivery artifact unaccounted for.
    """

    try:
        from brainlib.extractors.handoff import _decode_item, _validate_item, handoff_to_dict
        from brainlib.sync_results import HandoffDeliveryReference, SyncResultReference
        from tests.evals import event_log_contract as contract
    except ImportError as error:  # pragma: no cover - repository invariant
        raise RunnerError("delivery codecs unavailable") from error

    if (any(type(operation) is not str or not operation for operation in receipt_operations)
            or len(set(receipt_operations)) != len(receipt_operations)):
        raise RunnerError("invalid receipt operations for delivery projection")
    known_operations = tuple(receipt_operations)
    origins = _receipt_operation_origins(commands, known_operations)
    origin_operations = {result_id: operation for operation, result_id in origins.items()}
    artifact_owners: dict[str, tuple[str, SemanticCommandEvidence]] = {}
    projected: list[SemanticDeliveryEvidence] = []

    for operation in known_operations:
        origin_result_id = origins.get(operation)
        if origin_result_id is None:
            continue
        candidates: list[SemanticCommandEvidence] = []
        for command in commands:
            artifact_id = command.artifact_ids.get("delivery")
            if artifact_id is None:
                continue
            data = command.result.get("data") if type(command.result) is dict else None
            if (_semantic_command_matches(f"{operation}_receipt_consumed", command)
                    and _receipt_lifecycle_result_id(command) == origin_result_id
                    and type(data) is dict and data.get("status") == "consumed"):
                candidates.append(command)
        if not candidates:
            continue
        if len(candidates) != 1:
            raise RunnerError("ambiguous first consumption delivery")
        command = candidates[0]
        artifact_id = command.artifact_ids["delivery"]
        if artifact_id in artifact_owners:
            raise RunnerError("delivery artifact reused across receipt operations")
        artifact_owners[artifact_id] = (operation, command)
        raw = _writer_artifact_bytes(writer, artifact_id, "delivery")
        value = _strict_json(raw, label="immutable handoff delivery")
        expected = {"schema_version", "result_id", "reference", "items"}
        data = command.result["data"]
        if (type(value) is not dict or set(value) != expected
                or type(value.get("schema_version")) is not int or value["schema_version"] != 1
                or type(value.get("result_id")) is not str or type(value.get("items")) is not list
                or type(data) is not dict or value["result_id"] != data.get("result_id")):
            raise RunnerError("invalid first consumption delivery")
        try:
            reference = SyncResultReference.from_dict(value["reference"])
            delivery_reference = HandoffDeliveryReference.from_dict(data.get("handoff_delivery"))
        except (TypeError, ValueError) as error:
            raise RunnerError("invalid first consumption delivery reference") from error
        if (reference.result_id != value["result_id"]
                or delivery_reference.result_id != value["result_id"]
                or delivery_reference.sha256 != _sha256(raw)
                or delivery_reference.item_count != len(value["items"])):
            raise RunnerError("first consumption delivery identity mismatch")
        items: list[dict[str, str]] = []
        try:
            for raw_item in value["items"]:
                typed = _decode_item(raw_item)
                _validate_item(typed)
                if handoff_to_dict(typed) != raw_item:
                    raise ValueError("handoff item canonicalization")
                items.append({
                    "item_id": typed.handoff_id,
                    "kind": typed.kind,
                    "handoff_id": typed.handoff_id,
                    "handoff_source_id": typed.source_id,
                    "payload_sha256": contract._canon(raw_item),
                })
        except (TypeError, ValueError, AttributeError) as error:
            raise RunnerError("invalid typed first consumption delivery") from error
        if not items or len({item["item_id"] for item in items}) != len(items):
            raise RunnerError("invalid first consumption delivery items")
        delivery_id = "delivery-" + command.command_id
        if any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-" for character in delivery_id):
            raise RunnerError("invalid delivery identity")
        projected.append(SemanticDeliveryEvidence(
            delivery_id=delivery_id, operation=operation,
            artifact_id=artifact_id, items=tuple(items),
        ))

    # If a delivery capture was present, it must belong to a known operation's
    # exact manifest result.  Durable replay copies cannot become substitutes
    # for the first consume, and a generic `sync` operation cannot steal a
    # prior lifecycle's delivery merely because their argv grammars match.
    for command in commands:
        artifact_id = command.artifact_ids.get("delivery")
        if artifact_id is None:
            continue
        if artifact_id not in artifact_owners:
            data = command.result.get("data") if type(command.result) is dict else None
            result_id = _receipt_lifecycle_result_id(command)
            operation = origin_operations.get(result_id)
            if (type(data) is not dict or data.get("status") != "already_consumed"
                    or operation is None
                    or not _semantic_command_matches(
                        f"{operation}_receipt_durable", command,
                    )):
                raise RunnerError("unowned receipt delivery")
            if not any(owner_operation == operation for owner_operation, _owner in artifact_owners.values()):
                raise RunnerError("durable receipt delivery lacks first consumption")
    return tuple(projected)


def _cursor_start_family(command: SemanticCommandEvidence) -> str | None:
    """Recognize a closed first cursor-page command through Task 7a helpers."""

    try:
        from tests.evals import event_log_contract as contract

        if type(command.result) is not dict or _strict_json(
                command.result_raw, label="cursor command result") != command.result:
            return None
        if _sha256(command.result_raw) != command.result_sha256:
            return None
        argv = list(command.argv)
        for family in (
            "wiki_search", "freshness_search_batched", "source_pass_discovery",
            "source_pass_expansion", "source_pass_verification", "link_candidates",
        ):
            try:
                contract._envelope(
                    command.result, "links candidates" if family == "link_candidates" else "search",
                )
                contract._search_start(family, argv, command.result["data"])
            except Exception:
                continue
            return family
    except Exception:
        return None
    return None


def _cursor_page(
    command: SemanticCommandEvidence, *, links: bool,
) -> Mapping[str, Any]:
    """Parse one typed cursor result with the closed Task 7a implementation."""

    try:
        from tests.evals import event_log_contract as contract

        if (type(command.result) is not dict
                or _strict_json(command.result_raw, label="cursor command result") != command.result
                or _sha256(command.result_raw) != command.result_sha256):
            raise RunnerError("cursor command result integrity")
        contract._envelope(command.result, "links candidates" if links else "search")
        result = contract._search_page(command.result["data"], links=links)
    except RunnerError:
        raise
    except Exception as error:
        raise RunnerError("invalid cursor command result") from error
    if not isinstance(result, Mapping):  # defensive against a changed private helper
        raise RunnerError("invalid cursor command result")
    return result


def _build_semantic_cursor_proofs(
    writer: EvidenceWriter,
    *,
    run_id: str,
    commands: Sequence[SemanticCommandEvidence],
) -> tuple[SemanticCursorProofEvidence, ...]:
    """Build each complete cursor proof from exact indexed command artifacts.

    The output mirrors the Task 7a cursor-proof artifact and delegates every
    page/continuation grammar check to its sourced contract helpers.  It does
    not look at markers or mutable workspace state.  Incomplete chains are
    deliberately left unproved; their observed commands later make the plan
    incomplete through the global command audit.
    """

    grouped: dict[str, list[SemanticCommandEvidence]] = {}
    for command in commands:
        if (not command.command_id or not command.execution_id
                or type(command.start_sequence) is not int
                or type(command.end_sequence) is not int
                or not 0 < command.start_sequence < command.end_sequence):
            raise RunnerError("invalid cursor command observation")
        grouped.setdefault(command.execution_id, []).append(command)
    proofs: list[SemanticCursorProofEvidence] = []
    claimed: set[str] = set()
    for execution_id, observations in grouped.items():
        ordered = sorted(observations, key=lambda item: (item.start_sequence, item.end_sequence, item.command_id))
        for start_index, first in enumerate(ordered):
            if first.command_id in claimed:
                continue
            family = _cursor_start_family(first)
            if family is None:
                continue
            links = family == "link_candidates"
            try:
                first_page = _cursor_page(first, links=links)
            except RunnerError:
                continue
            chain = [first]
            pages = [first_page]
            previous = first
            while not pages[-1]["complete"]:
                expected = (
                    ["./brain", "--json", "links", "candidates", "--cursor", pages[-1]["next_cursor"]]
                    if links else ["./brain", "--json", "search", "--cursor", pages[-1]["next_cursor"]]
                )
                candidates = [
                    possible for possible in ordered[start_index + 1:]
                    if possible.command_id not in claimed
                    and possible.start_sequence > previous.end_sequence
                    and list(possible.argv) == expected
                ]
                if len(candidates) != 1:
                    # Do not turn a partial/ambiguous continuation into an
                    # evidence packet.  The raw command remains visible and
                    # will cause a named incomplete audit outcome.
                    chain = []
                    break
                continuation = candidates[0]
                try:
                    data = _cursor_page(continuation, links=links)
                except RunnerError:
                    chain = []
                    break
                stable = [
                    "run_id", "corpus_revision", "terms", "candidate_count",
                    "candidate_manifest_sha256", "result_sha256",
                ]
                if links:
                    stable.append("page_path")
                else:
                    stable.extend(("scope", "mode", "pass_name", "searched_source_ids", "candidate_manifest"))
                if (pages[-1]["complete"] or data["request_cursor"] != pages[-1]["next_cursor"]
                        or any(data[key] != pages[0][key] for key in stable)
                        or data["page_index"] != len(pages)):
                    chain = []
                    break
                chain.append(continuation)
                pages.append(data)
                previous = continuation
            if not chain:
                continue
            # The first-page helper and the loop above require exact index
            # ordering, and the loop stops only on the terminal complete page.
            if not pages[-1]["complete"]:
                continue
            proof_id = "cursor-" + family.replace("_", "-") + "-" + first.command_id
            if any(char not in "abcdefghijklmnopqrstuvwxyz0123456789._-" for char in proof_id):
                raise RunnerError("invalid cursor proof identity")
            writer.add_json(proof_id, "cursor_proof", {
                "run_id": run_id, "execution_id": execution_id, "family": family,
                "command_ids": [command.command_id for command in chain],
            })
            proofs.append(SemanticCursorProofEvidence(
                proof_id=proof_id, execution_id=execution_id, family=family,
                command_ids=tuple(command.command_id for command in chain),
            ))
            claimed.update(command.command_id for command in chain)
    return tuple(proofs)


def _emit_semantic_plan(writer: EvidenceWriter, plan: SemanticEventPlan) -> None:
    """Persist an already-complete plan through the same immutable index."""

    if not plan.complete:
        raise RunnerError("cannot emit incomplete semantic plan")
    for marker_id, value in plan.marker_records.items():
        writer.add_json(marker_id, "marker", value)
    for event_id, value in plan.event_records.items():
        writer.add_json(event_id, "event_record", value)


def _control_capture_relative(relative: object) -> str:
    """Validate one control-root-relative capture spelling without opening it."""

    if type(relative) is not str or not relative:
        raise RunnerError("invalid shim capture path")
    path = PurePosixPath(relative)
    if path.is_absolute() or path.as_posix() != relative or ".." in path.parts or not path.parts:
        raise RunnerError("invalid shim capture path")
    return relative


def _control_capture_path(control_root: Path, relative: object) -> Path:
    """Resolve one legacy control capture only after lexical validation."""

    relative = _control_capture_relative(relative)
    path = PurePosixPath(relative)
    current = control_root
    for part in path.parts[:-1]:
        current /= part
        info = current.lstat()
        if current.is_symlink() or not stat.S_ISDIR(info.st_mode):
            raise RunnerError("unsafe shim capture ancestor")
    target = current / path.parts[-1]
    if not target.is_relative_to(control_root):
        raise RunnerError("shim capture escapes control root")
    return target


def _read_control_capture(
    control_root: Path,
    relative: object,
    *,
    control_pin: PinnedDirectory | "_PhaseTwoFrozenCaptureSource" | "_FrozenDiagnosticControlPin" | None = None,
) -> bytes:
    """Read a Task 7b raw capture from the retained host root when supplied."""

    relative = _control_capture_relative(relative)
    # The staged execution-two converter receives only a frozen handoff.  Do
    # not construct or stat a pathname before dispatching this branch: doing
    # so would turn an unknown mutable capture into an implicit fallback
    # surface outside the retained raw/control closure.
    if type(control_pin) in (_PhaseTwoFrozenCaptureSource, _FrozenDiagnosticControlPin):
        if control_pin.path != control_root:
            raise RunnerError("control capture frozen source mismatch")
        return control_pin.read_relative(relative)
    target = _control_capture_path(control_root, relative)
    if control_pin is None:
        return _safe_read(target)
    if control_pin.path != control_root.resolve():
        raise RunnerError("control capture pin mismatch")
    return PinnedDirectory.read_relative(
        control_pin, target.relative_to(control_root).as_posix(),
    )


def _optional_control_capture(
    control_root: Path,
    relative: str,
    *,
    control_pin: PinnedDirectory | "_PhaseTwoFrozenCaptureSource" | None = None,
) -> bytes:
    """Read an optional runner-owned raw capture without masking corruption."""

    if type(control_pin) is _PhaseTwoFrozenCaptureSource:
        relative = _control_capture_relative(relative)
        if control_pin.path != control_root:
            raise RunnerError("control capture frozen source mismatch")
        optional = control_pin.optional_relative(relative)
        return b"" if optional is None else optional
    try:
        return _read_control_capture(
            control_root, relative, control_pin=control_pin,
        )
    except (FileNotFoundError, RunnerError) as error:
        try:
            target = _control_capture_path(control_root, relative)
            target.lstat()
        except FileNotFoundError:
            return b""
        # A present but unsafe/replaced capture is never equivalent to an
        # absent optional capture.  Preserve the original fail-closed cause.
        raise error


def _capture_bytes(
    control_root: Path,
    entry: object,
    *,
    label: str,
    control_pin: PinnedDirectory | None = None,
) -> tuple[str, bytes]:
    if type(entry) is not dict or set(entry) != {"path", "capture_path", "sha256", "bytes"}:
        raise RunnerError(f"invalid {label} capture entry")
    logical = entry["path"]
    if type(logical) is not str or not logical or type(entry["bytes"]) is not int or entry["bytes"] < 0:
        raise RunnerError(f"invalid {label} capture entry")
    raw = _read_control_capture(
        control_root, entry["capture_path"], control_pin=control_pin,
    )
    if len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]:
        raise RunnerError(f"{label} capture digest mismatch")
    return logical, raw


def _phase_capture_delta(current: bytes, previous: bytes, *, label: str) -> bytes:
    """Return one append-only phase slice, rejecting a rewritten raw bridge."""

    if (not current.endswith(b"\n")
            or previous and (
                not previous.endswith(b"\n") or not current.startswith(previous)
            )):
        raise RunnerError(f"{label} was replaced or is incomplete")
    delta = current[len(previous):]
    if not delta:
        raise RunnerError(f"{label} is empty")
    return delta


def _phase_optional_capture_delta(current: bytes, previous: bytes, *, label: str) -> bytes:
    """Verify an append-only optional stream while permitting an empty phase."""

    if (not current.endswith(b"\n")
            or previous and (
                not previous.endswith(b"\n") or not current.startswith(previous)
            )):
        raise RunnerError(f"{label} was replaced or is incomplete")
    return current[len(previous):]


def _preserve_transcript(control_root: Path, transcript_id: str, raw: bytes) -> bytes:
    """Retain the exact client stream under the private control layout."""

    if (not transcript_id
            or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789.-_" for character in transcript_id)):
        raise RunnerError("invalid transcript identity")
    path = control_root / ".brain" / "eval-transcripts" / f"{transcript_id}.jsonl"
    _write_private(path, raw)
    retained = _safe_read(path)
    if retained != raw:
        raise RunnerError("private transcript retention mismatch")
    return retained


@dataclass(frozen=True)
class ShimCaptureConversion:
    observation_ids: tuple[str, ...]
    manifest_ids: Mapping[str, str]
    trace_id: str
    trace_sha256: str
    raw_index: bytes
    raw_command_log: bytes
    raw_preapply_manifests: bytes
    # The conversion is the only phase-one component that observes the raw
    # receipt-capture document.  Retain its selected typed outputs explicitly
    # so a later sealed reader never recreates artifact identities from a
    # command-ID naming convention.
    receipt_artifact_ids: Mapping[str, Mapping[str, str]] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if (type(self.observation_ids) is not tuple
                or any(type(command_id) is not str or not command_id
                       for command_id in self.observation_ids)
                or len(set(self.observation_ids)) != len(self.observation_ids)):
            raise RunnerError("invalid converted receipt observation ids")
        if not isinstance(self.manifest_ids, Mapping):
            raise RunnerError("invalid converted manifest mapping")
        frozen_manifests: dict[str, str] = {}
        for command_id, manifest_id in self.manifest_ids.items():
            if (type(command_id) is not str
                    or command_id not in self.observation_ids
                    or type(manifest_id) is not str
                    or not manifest_id
                    or any(character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                           for character in manifest_id)):
                raise RunnerError("invalid converted manifest mapping")
            frozen_manifests[command_id] = manifest_id
        if not isinstance(self.receipt_artifact_ids, Mapping):
            raise RunnerError("invalid converted receipt artifact mapping")
        frozen: dict[str, Mapping[str, str]] = {}
        for command_id, artifacts in self.receipt_artifact_ids.items():
            if (type(command_id) is not str
                    or command_id not in self.observation_ids
                    or not isinstance(artifacts, Mapping)):
                raise RunnerError("invalid converted receipt artifact mapping")
            selected: dict[str, str] = {}
            for label, artifact_id in artifacts.items():
                if (label not in {"stream", "durable", "delivery"}
                        or type(artifact_id) is not str or not artifact_id):
                    raise RunnerError("invalid converted receipt artifact mapping")
                selected[label] = artifact_id
            frozen[command_id] = MappingProxyType(selected)
        object.__setattr__(self, "manifest_ids", MappingProxyType(frozen_manifests))
        object.__setattr__(self, "receipt_artifact_ids", MappingProxyType(frozen))


@dataclass(frozen=True)
class PhaseOneReceiptGate:
    """The non-serializable phase-one receipt facts that may release phase two.

    This contains no writer, log, marker artifact, event artifact, semantic
    plan, or overlay.  ``receipt_facts`` itself carries the immutable explicit
    six-ID selection that the sealed Task 7a reader validated.
    """

    execution_id: str
    receipt_facts: Any
    acknowledgement_position: tuple[int, int, int, int]
    report_gap_position: tuple[int, int, int, int]
    approval_position: tuple[int, int, int, int]

    def __post_init__(self) -> None:
        try:
            from tests.evals import event_log_contract as contract
        except ImportError as error:  # pragma: no cover - evaluator module invariant
            raise RunnerError("invalid phase-one receipt gate facts") from error
        positions = (
            self.acknowledgement_position,
            self.report_gap_position,
            self.approval_position,
        )
        if (type(self.execution_id) is not str
                or re.fullmatch(r"execution-[1-9][0-9]*", self.execution_id) is None
                or type(self.receipt_facts) is not contract.InitialSyncReceiptFacts
                or type(self.receipt_facts.selection) is not contract.InitialSyncReceiptSelection
                or any(type(position) is not tuple or len(position) != 4
                       or any(type(item) is not int or item < 0 for item in position)
                       for position in positions)
                or not self.acknowledgement_position < self.report_gap_position < self.approval_position):
            raise RunnerError("invalid phase-one receipt gate facts")

    @property
    def selection(self) -> Any:
        """Expose the exact immutable receipt selection without duplicating it."""

        return self.receipt_facts.selection

    def __reduce__(self) -> object:
        raise TypeError("phase-one receipt gate is not serializable")


@dataclass(frozen=True)
class _RegisteredActualPublicPhaseOne:
    """Directly indexed phase-one host facts for the separate public route.

    The existing phase-one diagnostic adopts rows beneath a private stage and
    is intentionally not a public manifest input.  This sibling value uses
    the same sealed setup and registered launch facts, but indexes a distinct
    direct host graph before any public approval/capability row is possible.
    """

    prepared_phase: "_RegisteredActualPreparedPhase"
    live_phase: RegisteredLivePhase
    normalized: NativeNormalization
    conversion: ShimCaptureConversion
    receipt_gate: PhaseOneReceiptGate
    policy_id: str
    process_id: str
    transcript_id: str
    stderr_id: str
    trace_id: str
    trace_sha256: str

    def __post_init__(self) -> None:
        expected = {
            "policy_id": "policy-1", "process_id": "process-1",
            "transcript_id": "transcript-1", "stderr_id": "stderr-1",
            "trace_id": "trace-execution-1",
        }
        values = {
            "policy_id": self.policy_id, "process_id": self.process_id,
            "transcript_id": self.transcript_id, "stderr_id": self.stderr_id,
            "trace_id": self.trace_id,
        }
        if (type(self.prepared_phase) is not _RegisteredActualPreparedPhase
                or type(self.live_phase) is not RegisteredLivePhase
                or type(self.normalized) is not NativeNormalization
                or type(self.conversion) is not ShimCaptureConversion
                or type(self.receipt_gate) is not PhaseOneReceiptGate
                or values != expected or not _is_hex64(self.trace_sha256)
                or not self.normalized.complete or self.normalized.reason is not None
                or self.live_phase.executable_id != "client-executable-1"
                or self.live_phase.capture.exit_code != 0):
            raise RunnerError("registered actual public phase-one evidence is invalid")

    def __reduce__(self) -> object:
        raise TypeError("registered actual public phase-one evidence is not serializable")


@dataclass(frozen=True)
class _RegisteredActualPublicWebAuthorization:
    """Frozen pre-launch authority for a distinct public phase-two route.

    This is not a fixture capability artifact and cannot launch a process on
    its own.  It only holds the sealed phase-one receipt proof and exact local
    fixture bytes that a later public-only phase-two preparer must bind before
    it writes its own capability, approval, control, policy, or process rows.
    The disconnected private phase-two diagnostic has no path to this type.
    """

    prepared_run: "_RegisteredActualPreparedRun"
    phase_one: _RegisteredActualPublicPhaseOne
    approval: Mapping[str, str]
    fixture_assets: Mapping[str, bytes]

    def __post_init__(self) -> None:
        if (type(self.prepared_run) is not _RegisteredActualPreparedRun
                or type(self.phase_one) is not _RegisteredActualPublicPhaseOne
                or self.phase_one.prepared_phase.prepared_run is not self.prepared_run
                or self.phase_one.live_phase.control_pin
                is not self.prepared_run.prepared.control_pin
                or self.phase_one.live_phase.workspace_pin
                is not self.prepared_run.prepared.workspace_pin
                or self.phase_one.receipt_gate.execution_id != "execution-1"
                or not isinstance(self.approval, Mapping)
                or not isinstance(self.fixture_assets, Mapping)):
            raise RunnerError("registered actual public web authorization is invalid")
        expected_approval = _registered_actual_phase_two_approval()
        if dict(self.approval) != expected_approval:
            raise RunnerError("registered actual public web authorization is invalid")
        expected_asset_names = {
            "fixture-descriptor.json", "static-shell.html", "rendered-dom.html",
        }
        if (set(self.fixture_assets) != expected_asset_names
                or any(type(raw) is not bytes for raw in self.fixture_assets.values())):
            raise RunnerError("registered actual public web authorization is invalid")
        frozen_assets = MappingProxyType({
            name: bytes(self.fixture_assets[name]) for name in sorted(expected_asset_names)
        })
        object.__setattr__(self, "approval", MappingProxyType(dict(expected_approval)))
        object.__setattr__(self, "fixture_assets", frozen_assets)

    def __reduce__(self) -> object:
        raise TypeError("registered actual public web authorization is not serializable")


@dataclass(frozen=True)
class _FrozenActualPhaseOneReceiptControl:
    """Selection-bound phase-one bytes for post-launch private receipt checks.

    This object has no writer, artifact path, overlay, or mutator surface.
    Its short-lived replay views may hold parser caches, but every artifact
    byte they expose originates in ``artifacts`` and is reverified against the
    descriptor snapshot before use.
    """

    artifacts: _FrozenActualPhaseOneReceiptArtifacts
    selection: Any
    workspace_path: str
    transcript_id: str
    trace_id: str

    def __post_init__(self) -> None:
        try:
            from tests.evals import event_log_contract as contract
        except ImportError as error:  # pragma: no cover - evaluator module invariant
            raise RunnerError("frozen phase-one receipt control is invalid") from error
        if (type(self.artifacts) is not _FrozenActualPhaseOneReceiptArtifacts
                or type(self.selection) is not contract.InitialSyncReceiptSelection
                or type(self.workspace_path) is not str
                or not self.workspace_path.startswith("/")
                or type(self.transcript_id) is not str
                or type(self.trace_id) is not str
                or self.transcript_id != "transcript-1"
                or self.trace_id != "trace-execution-1"):
            raise RunnerError("frozen phase-one receipt control is invalid")
        required_types = {
            "policy-1": "policy",
            "process-1": "process",
            self.transcript_id: "transcript",
            self.trace_id: "execution_trace",
            **{
                artifact_id: "command_observation"
                for artifact_id in self.selection.command_observation_ids
            },
            self.selection.stream_artifact_id: "sync_stream",
            self.selection.durable_artifact_id: "consumption_receipt",
        }
        if any(
                self.artifacts.entries.get(artifact_id, {}).get("type") != artifact_type
                for artifact_id, artifact_type in required_types.items()
        ):
            raise RunnerError("frozen phase-one receipt control is incomplete")
        self.artifacts.verify()

    @property
    def run_id(self) -> str:
        return self.artifacts.run_id

    @property
    def control_pin(self) -> PinnedDirectory:
        return self.artifacts.control_pin

    def verify(self) -> None:
        self.artifacts.verify()

    def replay(self) -> "_FrozenActualPhaseOneReceiptReplay":
        self.verify()
        return _FrozenActualPhaseOneReceiptReplay(self)

    def __reduce__(self) -> object:
        raise TypeError("frozen phase-one receipt control is not serializable")


class _FrozenActualPhaseOneReceiptReplay:
    """Ephemeral parser cache over a frozen receipt-control facade."""

    def __init__(self, control: _FrozenActualPhaseOneReceiptControl) -> None:
        if type(control) is not _FrozenActualPhaseOneReceiptControl:
            raise RunnerError("frozen phase-one receipt replay is invalid")
        control.verify()
        self._control = control
        self.run_id = control.run_id
        self.workspace_path = control.workspace_path
        self.entries = control.artifacts.entries
        # Task 7a's pure parser populates these cache attributes.  They are
        # isolated to this replay object and never modify retained evidence.
        self.native_records: dict[str, dict[int, dict[str, Any]]] = {}

    def read(self, artifact_id: str, artifact_type: str) -> bytes:
        return self._control.artifacts.read(artifact_id, artifact_type)

    def obj(self, artifact_id: str, artifact_type: str) -> dict[str, Any]:
        value = _strict_json(
            self.read(artifact_id, artifact_type),
            label="frozen phase-one receipt artifact",
        )
        if type(value) is not dict:
            raise RunnerError("frozen phase-one receipt artifact is not an object")
        return value


@dataclass(frozen=True)
class _FrozenReceiptNativeMarker:
    """One parser-bound native receipt marker, without semantic evidence."""

    event_name: str
    position: tuple[int, int, int, int]
    trace_sequence: int
    text: str


def _frozen_phase_one_receipt_native_markers(
    *,
    transcript: bytes,
    trace_records: Sequence[Mapping[str, Any]],
    transcript_id: str,
    allowed_event_names: Sequence[str],
) -> tuple[_FrozenReceiptNativeMarker, ...]:
    """Parse receipt ordering from frozen native bytes without semantic helpers."""

    if (type(transcript) is not bytes
            or type(transcript_id) is not str or not transcript_id
            or type(allowed_event_names) is not tuple
            or not allowed_event_names
            or any(type(name) is not str or not name for name in allowed_event_names)):
        raise RunnerError("frozen receipt native marker inputs are invalid")
    allowed = frozenset(allowed_event_names)
    if len(allowed) != len(allowed_event_names):
        raise RunnerError("frozen receipt native marker inputs are invalid")
    try:
        from tests.evals import event_log_contract as contract

        parsed = contract._native_transcript(
            transcript, "claude", "2.1.251", "claude-stream-json-2.1.251-v1",
        )
    except Exception as error:
        raise RunnerError("frozen receipt native transcript is unsupported") from error
    validate_trace_records(trace_records)
    traced: dict[int, tuple[int, Mapping[str, Any]]] = {}
    trace_offsets: list[int] = []
    for row in trace_records:
        if row.get("kind") != "native_record":
            continue
        if set(row) != {
                "sequence", "kind", "transcript_id", "byte_start", "byte_end", "sha256",
                "workspace_snapshot_id",
        }:
            raise RunnerError("frozen receipt native trace is invalid")
        start = row["byte_start"]
        sequence = row["sequence"]
        if (row["transcript_id"] != transcript_id
                or type(start) is not int or start in traced
                or type(sequence) is not int or sequence < 1):
            raise RunnerError("frozen receipt native trace is invalid")
        traced[start] = (sequence, row)
        trace_offsets.append(start)
    ordered_starts = sorted(parsed)
    if trace_offsets != ordered_starts or set(traced) != set(parsed):
        raise RunnerError("frozen receipt native trace does not partition transcript")
    previous_end = 0
    for start in ordered_starts:
        record = parsed[start]
        end = record.get("end")
        digest = record.get("sha256")
        sequence, trace = traced[start]
        raw = transcript[start:end] if type(end) is int else b""
        if (start != previous_end or type(end) is not int or end <= start
                or type(digest) is not str or end > len(transcript)
                or _sha256(raw) != digest or trace["byte_end"] != end
                or trace["sha256"] != digest or type(sequence) is not int):
            raise RunnerError("frozen receipt native transcript trace mismatch")
        previous_end = end
    if previous_end != len(transcript):
        raise RunnerError("frozen receipt native transcript is incomplete")

    markers: list[_FrozenReceiptNativeMarker] = []
    seen_names: set[str] = set()
    for start in ordered_starts:
        record = parsed[start]
        texts = record.get("texts")
        if type(texts) is not dict:
            raise RunnerError("frozen receipt native text projection is invalid")
        ordered_texts: list[tuple[int, str, str]] = []
        for pointer, text in texts.items():
            prefix = "/message/content/"
            suffix = "/text"
            index_text = pointer.removeprefix(prefix).removesuffix(suffix) if type(pointer) is str else ""
            if (type(pointer) is not str or type(text) is not str
                    or not pointer.startswith(prefix) or not pointer.endswith(suffix)
                    or not index_text.isdecimal()
                    or pointer != f"{prefix}{int(index_text)}{suffix}"):
                raise RunnerError("frozen receipt native marker pointer is invalid")
            ordered_texts.append((int(index_text), pointer, text))
        for index, _pointer, text in sorted(ordered_texts):
            raw_text = text.encode("utf-8")
            try:
                code_lines = contract._native_markdown_code_coverage(text, raw_text)
                line_spans = contract._native_text_line_spans(raw_text)
            except Exception as error:
                raise RunnerError("frozen receipt native markdown classification failed") from error
            for line_index, (line_start, line_end) in enumerate(line_spans):
                if line_index in code_lines:
                    continue
                line = raw_text[line_start:line_end]
                marker = contract._NATIVE_EVENT_LINE.fullmatch(line)
                if marker is not None:
                    event_name = marker.group(1).decode("ascii")
                    if event_name not in allowed or event_name in seen_names:
                        raise RunnerError("frozen receipt native marker is invalid")
                    seen_names.add(event_name)
                    sequence, _trace = traced[start]
                    markers.append(_FrozenReceiptNativeMarker(
                        event_name=event_name,
                        position=(0, start, index, line_start),
                        trace_sequence=sequence,
                        text=text,
                    ))
                elif line.startswith(b"EVENT:"):
                    raise RunnerError("frozen receipt native marker line is malformed")
    return tuple(markers)


def _freeze_actual_phase_one_receipt_control(
    phase_one_diagnostic: "_RegisteredActualPhaseOneDiagnostic",
    receipt_gate: PhaseOneReceiptGate,
) -> _FrozenActualPhaseOneReceiptControl:
    """Bind one selection to the phase-one graph frozen at diagnostic adoption."""

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(receipt_gate) is not PhaseOneReceiptGate):
        raise RunnerError("frozen phase-one receipt control inputs are invalid")
    phase_one_diagnostic.__post_init__()
    receipt_gate.__post_init__()
    conversion = phase_one_diagnostic.conversion
    selection = receipt_gate.selection
    verify_id, consume_id, durable_id, acknowledge_id = conversion.observation_ids
    verify_receipt = conversion.receipt_artifact_ids.get(verify_id)
    durable_receipt = conversion.receipt_artifact_ids.get(durable_id)
    if (selection.command_observation_ids != conversion.observation_ids
            or not isinstance(verify_receipt, Mapping)
            or not isinstance(durable_receipt, Mapping)
            or selection.stream_artifact_id != verify_receipt.get("stream")
            or selection.durable_artifact_id != durable_receipt.get("durable")
            or receipt_gate.execution_id != "execution-1"
            or phase_one_diagnostic.transcript_id != "transcript-1"
            or phase_one_diagnostic.trace_id != conversion.trace_id):
        raise RunnerError("frozen phase-one receipt control binding is invalid")
    artifacts = phase_one_diagnostic.receipt_artifacts
    control = _FrozenActualPhaseOneReceiptControl(
        artifacts=artifacts,
        selection=selection,
        workspace_path=str(phase_one_diagnostic.live_phase.workspace_pin.path),
        transcript_id=phase_one_diagnostic.transcript_id,
        trace_id=phase_one_diagnostic.trace_id,
    )
    control.verify()
    return control


def _reconstruct_frozen_actual_phase_one_receipt_gate(
    *,
    control: _FrozenActualPhaseOneReceiptControl,
    phase_one: RegisteredLivePhase,
    scenario: Mapping[str, Any],
    conversion: ShimCaptureConversion,
    workspace: Path,
    execution_id: str,
) -> PhaseOneReceiptGate | None:
    """Reconstruct the receipt gate from only the frozen receipt facade."""

    try:
        from tests.evals import event_log_contract as contract
        from tests.evals.phase_prompt_contract import required_events_for_phase

        receipt_events = (
            "initial_sync_receipt_verified",
            "initial_sync_receipt_consumed",
            "initial_sync_receipt_durable",
            "initial_sync_receipt_acknowledged",
        )
        approval_events = (*receipt_events, "report_local_evidence_gap", "ask_web_approval")
        if (
            type(control) is not _FrozenActualPhaseOneReceiptControl
            or type(phase_one) is not RegisteredLivePhase
            or type(conversion) is not ShimCaptureConversion
            or type(execution_id) is not str or execution_id != "execution-1"
            or not isinstance(scenario, Mapping)
            or scenario.get("id") != "web-approval-and-capture"
            or tuple(required_events_for_phase(scenario, "approval")) != approval_events
            or len(conversion.observation_ids) != len(receipt_events)
            or control.selection.command_observation_ids != conversion.observation_ids
            or not isinstance(workspace, Path)
        ):
            return None
        if (workspace != phase_one.workspace_pin.path
                or str(phase_one.workspace_pin.path) != control.workspace_path
                or phase_one.control_pin is not control.control_pin
                or phase_one.capture.exit_code != 0):
            return None
        control.verify()
        PinnedDirectory.verify(phase_one.workspace_pin)
        replay = control.replay()
        process_rows: list[dict[str, Any]] = []
        for artifact_id, entry in replay.entries.items():
            if entry.get("type") != "process":
                continue
            process = replay.obj(artifact_id, "process")
            if process.get("execution_id") == execution_id:
                process_rows.append(process)
        if len(process_rows) != 1:
            return None
        process = process_rows[0]
        required_process = {
            "run_id", "execution_id", "phase", "client", "client_version", "argv", "argv_sha256",
            "exit_code", "transcript_id", "transcript_sha256", "trace_id", "trace_sha256",
            "native_format", "fixture_id", "fixture_sha256", "fixture_capability_id", "approval",
            "phase_prompt_id", "phase_prompt_sha256", "phase_prompt_transport", "executable_id",
            "mcp_identity",
        }
        if (set(process) != required_process
                or process["run_id"] != control.run_id
                or process["execution_id"] != execution_id
                or process["phase"] != "approval"
                or process["client"] != "claude"
                or process["exit_code"] != 0
                or process.get("transcript_id") != control.transcript_id
                or process.get("trace_id") != control.trace_id
                or process.get("trace_id") != conversion.trace_id
                or process.get("trace_sha256") != conversion.trace_sha256
                or type(process.get("transcript_sha256")) is not str
                or type(process.get("trace_sha256")) is not str
                or type(process.get("executable_id")) is not str
                or process["executable_id"] != phase_one.executable_id
                or not isinstance(process.get("mcp_identity"), Mapping)
                or tuple(process["argv"]) != phase_one.argv
                or process["client_version"] != phase_one.reported_version
                or process["native_format"] != phase_one.native_format
                or _version_text(phase_one.capture.version) != phase_one.reported_version):
            return None
        transcript = replay.read(control.transcript_id, "transcript")
        if (_sha256(transcript) != process["transcript_sha256"]
                or transcript != phase_one.capture.stdout):
            return None
        execution = {
            "id": execution_id,
            "phase": "approval",
            "transcript_id": control.transcript_id,
        }
        phase_log = {
            "run_id": control.run_id,
            "scenario_id": "web-approval-and-capture",
            "client": "claude",
            "client_version": process["client_version"],
            "fixture_sha256": process["fixture_sha256"],
            "network_mode": "mock_only",
            "events": [],
            "receipts": [],
            "deliveries": [],
        }
        contract._execution_trace(replay, execution, process, phase_log)
        contract._audit_workspace_snapshots(replay, {execution_id: execution})
        trace = replay.obj(control.trace_id, "execution_trace")
        if (type(trace.get("records")) is not list
                or trace.get("run_id") != control.run_id
                or trace.get("execution_id") != execution_id):
            return None
        _reject_native_inside_command_interval(trace["records"])
        markers = _frozen_phase_one_receipt_native_markers(
            transcript=transcript,
            trace_records=trace["records"],
            transcript_id=control.transcript_id,
            allowed_event_names=approval_events,
        )
        if tuple(marker.event_name for marker in markers) != approval_events:
            return None
        acknowledgement_position = markers[3].position
        report_gap_position = markers[4].position
        approval_position = markers[5].position
        if ("prior standard" not in markers[4].text
                or acknowledgement_position >= report_gap_position
                or report_gap_position >= approval_position
                or any(marker.position >= report_gap_position for marker in markers[:4])):
            return None
        boundaries = tuple(
            contract.InitialSyncReceiptStageBoundary(
                stage=stage,
                trace_sequence=marker.trace_sequence,
            )
            for stage, marker in zip(
                ("verified", "consumed", "durable", "acknowledged"), markers[:4],
            )
        )
        facts = contract.validate_initial_sync_receipt_from_sealed_artifacts(
            replay,
            execution_id=execution_id,
            stage_boundaries=boundaries,
            selection=control.selection,
        )
        return PhaseOneReceiptGate(
            execution_id=execution_id,
            receipt_facts=facts,
            acknowledgement_position=acknowledgement_position,
            report_gap_position=report_gap_position,
            approval_position=approval_position,
        )
    except (ImportError, KeyError, IndexError, OSError, RunnerError, TypeError, UnicodeError, ValueError):
        return None


def _reconstruct_actual_phase_one_receipt_gate(
    *,
    writer: EvidenceWriter,
    phase_one: RegisteredLivePhase,
    scenario: Mapping[str, Any],
    conversion: ShimCaptureConversion,
    workspace: Path,
    execution_id: str,
    control_pin: PinnedDirectory | None = None,
) -> PhaseOneReceiptGate | None:
    """Re-read one phase-one receipt from sealed artifacts without emission.

    This narrow authority check is deliberately separate from the legacy
    incomplete-path normalizer.  It opens an overlay-free indexed reader,
    revalidates the trace/snapshot graph and parser-issued approval markers,
    then delegates receipt ownership and durable semantics to Task 7a's pure
    sealed reader.  It creates no artifacts and has no phase-two inputs.
    """

    try:
        from tests.evals import event_log_contract as contract
        from tests.evals.phase_prompt_contract import required_events_for_phase

        receipt_events = (
            "initial_sync_receipt_verified",
            "initial_sync_receipt_consumed",
            "initial_sync_receipt_durable",
            "initial_sync_receipt_acknowledged",
        )
        approval_events = (*receipt_events, "report_local_evidence_gap", "ask_web_approval")
        if (
            type(writer.run_id) is not str
            or type(phase_one) is not RegisteredLivePhase
            or type(conversion) is not ShimCaptureConversion
            or type(execution_id) is not str
            or execution_id != "execution-1"
            or not isinstance(scenario, Mapping)
            or scenario.get("id") != "web-approval-and-capture"
            or tuple(required_events_for_phase(scenario, "approval")) != approval_events
            or len(conversion.observation_ids) != len(receipt_events)
            or len(set(conversion.observation_ids)) != len(conversion.observation_ids)
            or any(type(command_id) is not str or not command_id
                   for command_id in conversion.observation_ids)
            or control_pin is not None and not isinstance(control_pin, PinnedDirectory)
        ):
            return None

        canonical_workspace = workspace.resolve(strict=True)
        control_root = getattr(writer, "control_root", None)
        run_root = getattr(writer, "run_root", None)
        if (not isinstance(control_root, Path)
                or not isinstance(run_root, Path)
                or not isinstance(phase_one.control_pin, PinnedDirectory)
                or not isinstance(phase_one.workspace_pin, PinnedDirectory)):
            return None
        canonical_control_root = control_root.resolve(strict=True)
        expected_run_root = canonical_control_root / "runs" / writer.run_id
        if (run_root.resolve(strict=True) != expected_run_root
                or not phase_one.control_pin.private
                or phase_one.control_pin.path != canonical_control_root
                or phase_one.workspace_pin.private
                or phase_one.workspace_pin.path != canonical_workspace
                or control_pin is not None and (
                    not control_pin.private
                    or control_pin is not phase_one.control_pin
                    or control_pin.path != canonical_control_root
                )):
            return None
        PinnedDirectory.verify(phase_one.control_pin)
        PinnedDirectory.verify(phase_one.workspace_pin)
        if control_pin is not None:
            PinnedDirectory.verify(control_pin)
        control = _IndexedSemanticControl(
            writer,
            run_id=writer.run_id,
            workspace=canonical_workspace,
            control_pin=control_pin,
        )
        process_rows: list[dict[str, Any]] = []
        for artifact_id, entry in control.entries.items():
            if entry.get("type") != "process":
                continue
            process = control.obj(artifact_id, "process")
            if process.get("execution_id") == execution_id:
                process_rows.append(process)
        if len(process_rows) != 1:
            return None
        process = process_rows[0]
        required_process = {
            "run_id", "execution_id", "phase", "client", "client_version", "argv", "argv_sha256",
            "exit_code", "transcript_id", "transcript_sha256", "trace_id", "trace_sha256",
            "native_format", "fixture_id", "fixture_sha256", "fixture_capability_id", "approval",
            "phase_prompt_id", "phase_prompt_sha256", "phase_prompt_transport", "executable_id",
            "mcp_identity",
        }
        if (set(process) != required_process
                or process["run_id"] != writer.run_id
                or process["execution_id"] != execution_id
                or process["phase"] != "approval"
                or process["client"] != "claude"
                or process["exit_code"] != 0
                or type(process["transcript_id"]) is not str
                or type(process["trace_id"]) is not str
                or type(process["transcript_sha256"]) is not str
                or type(process["trace_sha256"]) is not str
                or type(process["executable_id"]) is not str
                or process["executable_id"] != phase_one.executable_id
                or not isinstance(process["mcp_identity"], Mapping)
                or process["trace_id"] != conversion.trace_id
                or process["trace_sha256"] != conversion.trace_sha256
                or phase_one.capture.exit_code != 0
                or tuple(process["argv"]) != phase_one.argv
                or process["client_version"] != phase_one.reported_version
                or process["native_format"] != phase_one.native_format
                or _version_text(phase_one.capture.version) != phase_one.reported_version):
            return None
        transcript = control.read(process["transcript_id"], "transcript")
        if (_sha256(transcript) != process["transcript_sha256"]
                or transcript != phase_one.capture.stdout):
            return None

        execution = {
            "id": execution_id,
            "phase": "approval",
            "transcript_id": process["transcript_id"],
        }
        phase_log = {
            "run_id": writer.run_id,
            "scenario_id": "web-approval-and-capture",
            "client": "claude",
            "client_version": process["client_version"],
            "fixture_sha256": process["fixture_sha256"],
            "network_mode": "mock_only",
            "events": [],
            "receipts": [],
            "deliveries": [],
        }
        # These sourced readers populate only the ephemeral indexed control's
        # parser/trace view; neither has a writer or public-event side effect.
        contract._execution_trace(control, execution, process, phase_log)
        contract._audit_workspace_snapshots(control, {execution_id: execution})
        normalized = normalize_native_transcript(
            client=process["client"],
            version=process["client_version"],
            transcript=transcript,
        )
        if not normalized.complete:
            return None
        trace = control.obj(conversion.trace_id, "execution_trace")
        if (type(trace.get("records")) is not list
                or trace.get("run_id") != writer.run_id
                or trace.get("execution_id") != execution_id):
            return None
        _reject_native_inside_command_interval(trace["records"])
        candidates = extract_event_markers(
            transcript=transcript,
            native_records=normalized.records,
            trace_records=trace["records"],
            transcript_id=process["transcript_id"],
            allowed_event_names=approval_events,
        )
        if tuple(candidate.event_name for candidate in candidates) != approval_events:
            return None
        markers = tuple(
            SemanticMarkerEvidence(
                marker_id=f"actual-phase-one-marker-{index}",
                execution_id=execution_id,
                candidate=candidate,
                transcript_id=process["transcript_id"],
            )
            for index, candidate in enumerate(candidates, 1)
        )
        positions = tuple(
            _semantic_marker_order_position({execution_id: 0}, marker)
            for marker in markers
        )
        if any(position is None for position in positions):
            return None
        marker_positions = tuple(positions)
        acknowledgement_position = marker_positions[3]
        report_gap_position = marker_positions[4]
        approval_position = marker_positions[5]
        report_candidate = candidates[4]
        report_text = control.native_records[execution_id][report_candidate.native_record_start]["texts"].get(
            report_candidate.text_pointer,
        )
        if (type(report_text) is not str or "prior standard" not in report_text
                or acknowledgement_position >= report_gap_position
                or report_gap_position >= approval_position
                or any(position >= report_gap_position for position in marker_positions[:4])):
            return None

        verify_id, consume_id, durable_id, acknowledge_id = conversion.observation_ids
        verify_receipt = conversion.receipt_artifact_ids.get(verify_id)
        durable_receipt = conversion.receipt_artifact_ids.get(durable_id)
        if (not isinstance(verify_receipt, Mapping)
                or not isinstance(durable_receipt, Mapping)
                or type(verify_receipt.get("stream")) is not str
                or type(durable_receipt.get("durable")) is not str):
            return None
        selection = contract.InitialSyncReceiptSelection(
            verify_command_id=verify_id,
            consume_command_id=consume_id,
            durable_command_id=durable_id,
            acknowledge_command_id=acknowledge_id,
            stream_artifact_id=verify_receipt["stream"],
            durable_artifact_id=durable_receipt["durable"],
        )
        boundaries = tuple(
            contract.InitialSyncReceiptStageBoundary(
                stage=stage,
                trace_sequence=candidate.trace_sequence,
            )
            for stage, candidate in zip(
                ("verified", "consumed", "durable", "acknowledged"), candidates[:4],
            )
        )
        facts = contract.validate_initial_sync_receipt_from_sealed_artifacts(
            control,
            execution_id=execution_id,
            stage_boundaries=boundaries,
            selection=selection,
        )
        return PhaseOneReceiptGate(
            execution_id=execution_id,
            receipt_facts=facts,
            acknowledgement_position=acknowledgement_position,
            report_gap_position=report_gap_position,
            approval_position=approval_position,
        )
    except (ImportError, KeyError, IndexError, OSError, RunnerError, TypeError, UnicodeError, ValueError):
        return None


def _registered_phase_evidence_is_bound(
    *,
    writer: EvidenceWriter,
    workspace: Path,
    execution_id: str,
    phase: str,
    live_phase: RegisteredLivePhase,
    control_pin: PinnedDirectory | None = None,
    expected_execution_ids: frozenset[str] | None = None,
) -> bool:
    """Recheck one registered phase's sealed host/probe/policy/process join.

    This is a transition guard, not a replacement for final public
    validation.  It lets a phase-one web transcript release phase two only
    after the exact prelaunch TrustedRunContext, executable observations, and
    final absolute policy/process argv have all been made mutually visible in
    indexed evidence.
    """

    try:
        from tests.evals import event_log_contract as contract

        if (type(execution_id) is not str
                or re.fullmatch(r"execution-[1-9][0-9]*", execution_id) is None
                or type(phase) is not str or not phase
                or live_phase.executable_id != "client-executable-" + execution_id.removeprefix("execution-")
                or live_phase.version_id != "version-" + execution_id.removeprefix("execution-")
                or live_phase.help_id != "help-" + execution_id.removeprefix("execution-")
                or not live_phase.argv or not isinstance(live_phase.trusted_context, contract.TrustedRunContext)
                or workspace != live_phase.workspace_pin.path
                or expected_execution_ids is not None and (
                    type(expected_execution_ids) is not frozenset
                    or not expected_execution_ids
                    or any(type(value) is not str for value in expected_execution_ids)
                    or execution_id not in expected_execution_ids
                )
                or control_pin is not None and (
                    not isinstance(control_pin, PinnedDirectory)
                    or not control_pin.private
                    or control_pin is not live_phase.control_pin
                    or control_pin.path != writer.control_root.resolve()
                    or writer.run_root != control_pin.path / "runs" / writer.run_id
                )):
            return False
        PinnedDirectory.verify(live_phase.control_pin)
        PinnedDirectory.verify(live_phase.workspace_pin)
        if control_pin is not None:
            PinnedDirectory.verify(control_pin)
        _registration, trusted = _registered_live_context_phase(
            client=live_phase.trusted_executable.client,
            execution_id=execution_id,
            control_pin=live_phase.control_pin,
            workspace_pin=live_phase.workspace_pin,
            trusted_context=live_phase.trusted_context,
            expected_execution_ids=(
                expected_execution_ids
                if expected_execution_ids is not None
                else frozenset(
                    f"execution-{index}"
                    for index in range(1, int(execution_id.removeprefix("execution-")) + 1)
                )
            ),
        )
        if trusted is not live_phase.trusted_executable:
            return False
        position = execution_id.removeprefix("execution-")
        expected_argv = list(live_phase.argv)
        expected_argv_sha256 = _sha256(_canonical_json(expected_argv))
        _absolute_executable_path(expected_argv[0])
        control = _IndexedSemanticControl(
            writer,
            run_id=writer.run_id,
            workspace=workspace,
            control_pin=control_pin,
        )
        policy = control.obj("policy-" + position, "policy")
        process = control.obj("process-" + position, "process")
        transcript_id = "transcript-" + position
        trace_id = "trace-" + execution_id
        transcript_raw = _writer_artifact_bytes(
            writer, transcript_id, "transcript", control_pin=control_pin,
        )
        trace_raw = _writer_artifact_bytes(
            writer, trace_id, "execution_trace", control_pin=control_pin,
        )
        if (policy.get("run_id") != writer.run_id
                or policy.get("execution_id") != execution_id
                or policy.get("phase") != phase
                or policy.get("client") != trusted.client
                or policy.get("argv") != expected_argv
                or policy.get("argv_sha256") != expected_argv_sha256
                or policy.get("version_id") != live_phase.version_id
                or policy.get("help_id") != live_phase.help_id
                or policy.get("executable_id") != live_phase.executable_id
                or process.get("run_id") != writer.run_id
                or process.get("execution_id") != execution_id
                or process.get("phase") != phase
                or process.get("client") != trusted.client
                or process.get("argv") != expected_argv
                or process.get("argv_sha256") != expected_argv_sha256
                or process.get("client_version") != live_phase.reported_version
                or process.get("native_format") != live_phase.native_format
                or process.get("executable_id") != live_phase.executable_id
                or process.get("exit_code") != live_phase.capture.exit_code
                or process.get("exit_code") != 0
                or process.get("transcript_id") != transcript_id
                or process.get("transcript_sha256") != _sha256(transcript_raw)
                or transcript_raw != live_phase.capture.stdout
                or process.get("trace_id") != trace_id
                or process.get("trace_sha256") != _sha256(trace_raw)
                or _writer_artifact_bytes(
                    writer, live_phase.version_id, "version", control_pin=control_pin,
                )
                != live_phase.capture.version
                or _writer_artifact_bytes(
                    writer, live_phase.help_id, "help", control_pin=control_pin,
                )
                != live_phase.capture.help):
            return False
        contract._validate_client_executable(
            control,
            {"id": execution_id, "phase": phase},
            {
                "run_id": writer.run_id,
                "client": trusted.client,
                "client_version": live_phase.reported_version,
            },
            live_phase.trusted_context,
            policy,
            process,
            seen_artifacts=set(),
            seen_probe_artifacts=set(),
        )
    except (AttributeError, KeyError, OSError, RunnerError, TypeError, ValueError):
        return False
    except Exception:
        # Task 7a's sourced contract raises its own validation subtype.  This
        # transition guard is fail-closed without importing that type into the
        # runner's public surface.
        return False
    return True


def _index_registered_actual_public_phase_one(
    prepared_phase: "_RegisteredActualPreparedPhase",
    live_phase: RegisteredLivePhase,
) -> _RegisteredActualPublicPhaseOne:
    """Index a direct phase-one host graph for the separate public route.

    This must be called instead of the diagnostic indexer.  It never adopts a
    private stage, emits no capability/approval/semantic rows, and leaves the
    receipt proof as the only value that can release public phase-two setup.
    """

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase):
        raise RunnerError("registered actual public phase-one index inputs are invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot index public execution")
    prepared_phase.__post_init__()
    prepared_run = prepared_phase.prepared_run
    plan = prepared_run.authority.plan
    writer = prepared_phase.writer
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    mcp_config = prepared_phase.mcp_config
    if (plan.client != "claude" or plan.scenario_id != "web-approval-and-capture"
            or prepared_phase.execution_id != "execution-1"
            or prepared_phase.phase != "approval" or prepared_phase.phase_index != 1
            or not isinstance(mcp_config, ControlFileSeal)
            or live_phase.control_pin is not prepared_phase.control_pin
            or live_phase.workspace_pin is not prepared_phase.workspace_pin
            or live_phase.executable_id != "client-executable-1"
            or live_phase.version_id != "version-1" or live_phase.help_id != "help-1"
            or live_phase.capture.exit_code != 0
            or {"policy-1", "process-1", "transcript-1", "stderr-1",
                "trace-execution-1"} & {str(entry.get("id")) for entry in writer.entries}):
        raise RunnerError("registered actual public phase-one index is invalid")
    _registration, trusted = _registered_live_context_phase(
        client="claude", execution_id="execution-1", control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin, trusted_context=live_phase.trusted_context,
        expected_execution_ids=frozenset({"execution-1"}),
    )
    if _registration is not plan.registration or trusted is not live_phase.trusted_executable:
        raise RunnerError("registered actual public phase-one context is invalid")
    normalized = normalize_native_transcript(
        client="claude", version=live_phase.reported_version,
        transcript=live_phase.capture.stdout,
    )
    if not normalized.complete:
        raise RunnerError("registered actual public phase-one native transcript is unsupported")
    verify_phase_control(prepared_phase.phase_control)
    verify_control_file(prepared_phase.runner_state)
    verify_control_file(mcp_config)
    _verify_phase_prompt(prepared_phase.phase_prompt)
    trace_rows = prepared_phase.trace.records()
    if not trace_rows:
        raise RunnerError("registered actual public phase-one trace is missing")
    validate_trace_records(trace_rows)
    transcript_raw = _preserve_transcript(
        writer.control_root, "transcript-1", live_phase.capture.stdout,
    )
    policy_id = writer.add_json("policy-1", "policy", {
        "run_id": writer.run_id, "execution_id": "execution-1", "phase": "approval",
        "client": "claude", "profile": "claude-restricted-tool-surface-v1",
        "network_attestation": "mock-only", "argv": list(live_phase.argv),
        "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
        "version_id": "version-1", "help_id": "help-1", "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256, "fixture_capability_id": None,
        "approval": None, "phase_prompt_id": "phase-prompt-1",
        "phase_prompt_sha256": prepared_phase.phase_prompt.sha256,
        "phase_prompt_transport": prepared_phase.phase_prompt.transport,
        "executable_id": "client-executable-1", "mcp_config_id": "mcp-1",
        "mcp_config_sha256": mcp_config.sha256, "mcp_path": str(mcp_config.path),
        "mcp_identity": dict(mcp_config.identity),
    })
    transcript_id = writer.add_bytes("transcript-1", "transcript", transcript_raw)
    stderr_id = writer.add_bytes("stderr-1", "file_capture", live_phase.capture.stderr)
    conversion = convert_shim_captures(
        writer, control_root=writer.control_root, run_id=writer.run_id,
        execution_id="execution-1", phase="approval", transcript_id=transcript_id,
        trace=prepared_phase.trace, control_pin=prepared_phase.control_pin,
    )
    process_id = writer.add_json("process-1", "process", {
        "run_id": writer.run_id, "execution_id": "execution-1", "phase": "approval",
        "client": "claude", "client_version": live_phase.reported_version,
        "argv": list(live_phase.argv), "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
        "exit_code": live_phase.capture.exit_code, "transcript_id": transcript_id,
        "transcript_sha256": _sha256(transcript_raw), "trace_id": conversion.trace_id,
        "trace_sha256": conversion.trace_sha256, "native_format": live_phase.native_format,
        "fixture_id": metadata.fixture_id, "fixture_sha256": metadata.fixture_sha256,
        "fixture_capability_id": None, "approval": None,
        "phase_prompt_id": "phase-prompt-1", "phase_prompt_sha256": prepared_phase.phase_prompt.sha256,
        "phase_prompt_transport": prepared_phase.phase_prompt.transport,
        "executable_id": "client-executable-1", "mcp_identity": dict(mcp_config.identity),
    })
    _registered_executable_observation(trusted)
    if not _registered_phase_evidence_is_bound(
            writer=writer, workspace=prepared_run.prepared.workspace,
            execution_id="execution-1", phase="approval", live_phase=live_phase,
            control_pin=prepared_phase.control_pin,
            expected_execution_ids=frozenset({"execution-1"})):
        raise RunnerError("registered actual public phase-one evidence is not bound")
    receipt_gate = _reconstruct_actual_phase_one_receipt_gate(
        writer=writer, phase_one=live_phase, scenario=scenario, conversion=conversion,
        workspace=prepared_run.prepared.workspace, execution_id="execution-1",
        control_pin=prepared_phase.control_pin,
    )
    if receipt_gate is None:
        raise RunnerError("registered actual public phase-one receipt gate is unavailable")
    return _RegisteredActualPublicPhaseOne(
        prepared_phase=prepared_phase, live_phase=live_phase, normalized=normalized,
        conversion=conversion, receipt_gate=receipt_gate, policy_id=policy_id,
        process_id=process_id, transcript_id=transcript_id, stderr_id=stderr_id,
        trace_id=conversion.trace_id, trace_sha256=conversion.trace_sha256,
    )


def _authorize_registered_actual_public_web_phase_two(
    prepared_run: "_RegisteredActualPreparedRun",
    phase_one: _RegisteredActualPublicPhaseOne,
) -> _RegisteredActualPublicWebAuthorization:
    """Freeze exact phase-one authority before public phase-two setup writes.

    The caller cannot supply approval text, fixture bytes, or a phase-two
    launch adapter.  This retains only values already selected by the
    generated Claude/web plan and replays the sealed receipt gate immediately
    before returning.  The actual public phase-two builder remains a separate
    boundary; the private diagnostic launcher never calls this helper.
    """

    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(phase_one) is not _RegisteredActualPublicPhaseOne):
        raise RunnerError("registered actual public web authorization inputs are invalid")
    authority = prepared_run.authority
    plan = authority.plan
    prepared_phase = phase_one.prepared_phase
    live_phase = phase_one.live_phase
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phase_plan(plan.scenario_id) != ("approval", "approved_capture")
            or prepared_phase.prepared_run is not prepared_run
            or prepared_phase.execution_id != "execution-1"
            or prepared_phase.phase != "approval"
            or phase_one.receipt_gate.execution_id != "execution-1"):
        raise RunnerError("registered actual public web authorization is invalid")
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    if not _registered_phase_evidence_is_bound(
        writer=prepared_run.writer,
        workspace=prepared_run.prepared.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
    ):
        raise RunnerError("registered actual public phase-one evidence is no longer bound")
    reconstructed = _reconstruct_actual_phase_one_receipt_gate(
        writer=prepared_run.writer,
        phase_one=live_phase,
        scenario=scenario,
        conversion=phase_one.conversion,
        workspace=prepared_run.prepared.workspace,
        execution_id="execution-1",
        control_pin=prepared_run.prepared.control_pin,
    )
    if not _phase_one_receipt_gate_matches(phase_one.receipt_gate, reconstructed):
        raise RunnerError("registered actual public phase-one receipt gate is invalid")
    sources = prepared_run.prepared.fixture_control_assets
    required_sources = {
        "static-shell.html", "rendered-dom.html", "unused-candidate.html",
    }
    if (not isinstance(sources, Mapping) or set(sources) != required_sources
            or any(type(raw) is not bytes for raw in sources.values())):
        raise RunnerError("registered actual public fixture sources are invalid")
    static = bytes(sources["static-shell.html"])
    rendered = bytes(sources["rendered-dom.html"])
    descriptor = _canonical_json({
        "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256,
        "static_sha256": _sha256(static),
        "rendered_sha256": _sha256(rendered),
        "unused_sha256": _sha256(sources["unused-candidate.html"]),
        "final_url": "https://example.test/standard",
        "media_type": "text/html",
        "retrieved_at": "2026-09-04T12:00:00Z",
        "redirect_urls": [],
    })
    authorization = _RegisteredActualPublicWebAuthorization(
        prepared_run=prepared_run,
        phase_one=phase_one,
        approval=_registered_actual_phase_two_approval(),
        fixture_assets=MappingProxyType({
            "fixture-descriptor.json": descriptor,
            "static-shell.html": static,
            "rendered-dom.html": rendered,
        }),
    )
    authorization.__post_init__()
    return authorization


def _emit_registered_actual_public_web_authorization(
    authorization: _RegisteredActualPublicWebAuthorization,
) -> tuple[str, str]:
    """Index the one sealed public fixture grant before phase-two setup.

    This write boundary is intentionally not reachable from the private
    diagnostic chain.  The capability is runner-owned fixture metadata, not
    an external-network authority, and it is emitted before phase two so its
    exact IDs can be part of that phase's policy/process evidence.
    """

    if type(authorization) is not _RegisteredActualPublicWebAuthorization:
        raise RunnerError("registered actual public web authorization is invalid")
    authorization.__post_init__()
    prepared_run = authorization.prepared_run
    writer = prepared_run.writer
    phase_one = authorization.phase_one.prepared_phase
    metadata = _registered_actual_scenario_fixture_metadata(
        prepared_run, prepared_run.authority.plan,
    )
    if (phase_one.execution_id != "execution-1"
            or phase_one.phase != "approval"
            or writer.entries is not phase_one.writer.entries
            or {entry.get("id") for entry in writer.entries} & {
                "web-approval", "fixture-capability", "fixture-descriptor",
                "fixture-static-shell", "fixture-rendered-dom",
            }):
        raise RunnerError("registered actual public web authorization is already emitted")
    descriptor_id = writer.add_bytes(
        "fixture-descriptor", "fixture_descriptor",
        authorization.fixture_assets["fixture-descriptor.json"], suffix=".json",
    )
    static_id = writer.add_bytes(
        "fixture-static-shell", "file_capture",
        authorization.fixture_assets["static-shell.html"], suffix=".html",
    )
    rendered_id = writer.add_bytes(
        "fixture-rendered-dom", "file_capture",
        authorization.fixture_assets["rendered-dom.html"], suffix=".html",
    )
    approval_id = writer.add_json("web-approval", "approval", {
        "run_id": writer.run_id,
        "execution_id": "execution-1",
        **dict(authorization.approval),
        "decision": "approved",
        "fixture_id": "web-approval-and-capture.initial",
        "capability_id": "fixture-capability",
        "manifest_id": None,
    })
    capability_id = writer.add_json("fixture-capability", "fixture_capability", {
        "run_id": writer.run_id,
        "execution_id": "execution-2",
        "phase": "approved_capture",
        "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256,
        "capability_id": "fixture-capability",
        "approval_event_id": authorization.approval["event_id"],
        "scope": authorization.approval["scope"],
        "note": authorization.approval["note"],
        "enabled_fixture_ids": [
            "web-approval-and-capture.initial",
            "web-approval-and-capture.rendered",
        ],
        "descriptor_id": descriptor_id,
    })
    if (static_id != "fixture-static-shell" or rendered_id != "fixture-rendered-dom"
            or approval_id != "web-approval" or capability_id != "fixture-capability"):
        raise RunnerError("registered actual public web authorization emission is invalid")
    return approval_id, capability_id


@dataclass(frozen=True)
class _RegisteredActualPublicPhaseTwo:
    """Closed, public-capable setup for Claude's second web phase.

    This deliberately is not ``_RegisteredActualPreparedPhase``.  The latter
    is the private diagnostic token and carries phase-two raw-provenance
    controls whose null capability/approval policy is intentionally
    non-promotable.  This value is constructed only after the distinct public
    approval/capability records have been emitted.
    """

    authorization: _RegisteredActualPublicWebAuthorization
    writer: EvidenceWriter
    control_pin: PinnedDirectory
    workspace_pin: PinnedDirectory
    phase_control: PhaseControlSeals
    phase_prompt: PhasePromptEvidence
    mcp_config: ControlFileSeal
    runner_state: ControlFileSeal
    trace: ControlTraceWriter
    initial_workspace_snapshot: WorkspaceSnapshot
    marker_workspace_snapshots: list[WorkspaceSnapshot]
    on_native_record: Callable[[bytes, int, int, int], str]
    trusted_context: Any

    def __post_init__(self) -> None:
        if (type(self.authorization) is not _RegisteredActualPublicWebAuthorization
                or type(self.writer) is not EvidenceWriter
                or not isinstance(self.control_pin, PinnedDirectory)
                or not isinstance(self.workspace_pin, PinnedDirectory)
                or not isinstance(self.phase_control, PhaseControlSeals)
                or not isinstance(self.phase_prompt, PhasePromptEvidence)
                or not isinstance(self.mcp_config, ControlFileSeal)
                or not isinstance(self.runner_state, ControlFileSeal)
                or not isinstance(self.trace, ControlTraceWriter)
                or not isinstance(self.initial_workspace_snapshot, WorkspaceSnapshot)
                or type(self.marker_workspace_snapshots) is not list
                or any(not isinstance(snapshot, WorkspaceSnapshot)
                       for snapshot in self.marker_workspace_snapshots)
                or not callable(self.on_native_record)):
            raise RunnerError("registered actual public phase-two setup is invalid")
        prepared_run = self.authorization.prepared_run
        if (self.writer is not prepared_run.writer
                or self.control_pin is not prepared_run.prepared.control_pin
                or self.workspace_pin is not prepared_run.prepared.workspace_pin
                or not self.control_pin.private or self.workspace_pin.private
                or self.trace.control_root != self.control_pin.path
                or self.trace.control_pin is not self.control_pin
                or self.trace.path != self.control_pin.path / "runner-trace-execution-2.jsonl"
                or self.trace.lock_path != self.control_pin.path / ".runner-trace.lock"
                or self.phase_prompt.artifact_id != "phase-prompt-2"
                or self.initial_workspace_snapshot.execution_id != "execution-2"
                or self.initial_workspace_snapshot.role != "initial"
                or self.initial_workspace_snapshot.trace_sequence != 0):
            raise RunnerError("registered actual public phase-two setup is invalid")
        try:
            from tests.evals import event_log_contract as contract

            if (type(self.trusted_context) is not contract.TrustedRunContext
                    or set(self.trusted_context.trusted_executables)
                    != {"execution-1", "execution-2"}):
                raise RunnerError("registered actual public phase-two context is invalid")
        except ImportError as error:  # pragma: no cover - evaluator invariant
            raise RunnerError("registered actual public phase-two context is unavailable") from error

    def __reduce__(self) -> object:
        raise TypeError("registered actual public phase-two setup is not serializable")


def _prepare_registered_actual_public_phase_two(
    authorization: _RegisteredActualPublicWebAuthorization,
) -> _RegisteredActualPublicPhaseTwo:
    """Prepare a public second phase without touching the private diagnostic path.

    The capability and approval are indexed first and must remain exact inputs
    to this phase's control, policy, and process joins.  No process is spawned
    here; launch remains a separate production-default-only boundary.
    """

    if type(authorization) is not _RegisteredActualPublicWebAuthorization:
        raise RunnerError("registered actual public phase-two authorization is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot prepare public execution")
    authorization.__post_init__()
    prepared_run = authorization.prepared_run
    authority = prepared_run.authority
    plan = authority.plan
    phase_one = authorization.phase_one
    phase_one_live = phase_one.live_phase
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    if (type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phase_plan(plan.scenario_id) != ("approval", "approved_capture")
            or phase_one.prepared_phase.prepared_run is not prepared_run
            or phase_one_live.trusted_context is None):
        raise RunnerError("registered actual public phase-two authorization is invalid")
    writer = prepared_run.writer
    required_authority_ids = {
        "fixture-descriptor", "fixture-static-shell", "fixture-rendered-dom",
        "web-approval", "fixture-capability",
    }
    indexed_ids = {str(entry.get("id")) for entry in writer.entries}
    if not required_authority_ids <= indexed_ids:
        _emit_registered_actual_public_web_authorization(authorization)
        indexed_ids = {str(entry.get("id")) for entry in writer.entries}
    if (not required_authority_ids <= indexed_ids
            or {"phase-prompt-2", "mcp-2", "policy-2", "process-2"} & indexed_ids):
        raise RunnerError("registered actual public phase-two setup is already started")
    if not _registered_phase_evidence_is_bound(
            writer=writer, workspace=prepared_run.prepared.workspace,
            execution_id="execution-1", phase="approval", live_phase=phase_one_live,
            control_pin=prepared_run.prepared.control_pin,
            expected_execution_ids=frozenset({"execution-1"})):
        raise RunnerError("registered actual public phase-one evidence is no longer bound")
    reconstructed = _reconstruct_actual_phase_one_receipt_gate(
        writer=writer, phase_one=phase_one_live, scenario=scenario,
        conversion=phase_one.conversion, workspace=prepared_run.prepared.workspace,
        execution_id="execution-1", control_pin=prepared_run.prepared.control_pin,
    )
    if not _phase_one_receipt_gate_matches(authorization.phase_one.receipt_gate, reconstructed):
        raise RunnerError("registered actual public phase-one receipt gate is invalid")

    prepared = prepared_run.prepared
    PinnedDirectory.verify(prepared.control_pin)
    PinnedDirectory.verify(prepared.workspace_pin)
    verify_wrapper(prepared.wrapper_seal)
    phase_control = _phase_control(
        prepared, phase="approved_capture", approval=dict(authorization.approval),
        metadata=metadata,
    )
    runner_state = _write_runner_state(
        prepared, run_id=writer.run_id, execution_id="execution-2", phase="approved_capture",
    )
    writer.add_bytes("mcp-2", "mcp_config", EMPTY_MCP_BYTES, suffix=".json")
    entry = _writer_entry_map(writer).get("mcp-2")
    if entry is None or entry.get("type") != "mcp_config":
        raise RunnerError("registered actual public phase-two MCP config is unavailable")
    mcp_path = (writer.run_root / str(entry["relative_path"])).resolve()
    if not mcp_path.is_relative_to(writer.run_root.resolve()):
        raise RunnerError("registered actual public phase-two MCP config escaped run root")
    mcp_config = _seal_control_file(mcp_path)
    verify_control_file(mcp_config)
    if _safe_read(mcp_path) != EMPTY_MCP_BYTES:
        raise RunnerError("registered actual public phase-two MCP config changed")
    prompt = _index_phase_prompt(
        writer, scenario=scenario, phase="approved_capture", phase_index=2,
        client="claude",
    )
    trace = ControlTraceWriter(
        prepared.control_root, "execution-2", control_pin=prepared.control_pin,
    )
    snapshotter = WorkspaceSnapshotter(
        workspace=prepared.workspace, workspace_pin=prepared.workspace_pin, writer=writer,
    )
    # A phase-local snapshotter must reuse the phase-one writer's immutable
    # content rows.  Starting with an empty cache would try to add the same
    # digest-named file capture again when an unchanged workspace file appears
    # in phase two's baseline.
    for artifact_id, entry in _writer_entry_map(writer).items():
        if not artifact_id.startswith("workspace-content-"):
            continue
        digest = artifact_id.removeprefix("workspace-content-")
        if (entry.get("type") != "file_capture" or not _is_hex64(digest)
                or entry.get("sha256") != digest or type(entry.get("bytes")) is not int):
            raise RunnerError("registered public phase-two workspace content is invalid")
        raw = _writer_artifact_bytes(writer, artifact_id, "file_capture")
        if len(raw) != entry["bytes"] or _sha256(raw) != digest:
            raise RunnerError("registered public phase-two workspace content changed")
        snapshotter._content_ids[(digest, len(raw))] = artifact_id
    initial_snapshot = snapshotter.capture(execution_id="execution-2", trace_sequence=0)
    marker_snapshots: list[WorkspaceSnapshot] = []

    def capture_marker_snapshot(
        raw: bytes, byte_start: int, byte_end: int, sequence: int,
    ) -> str:
        if (type(raw) is not bytes or type(byte_start) is not int or byte_start < 0
                or type(byte_end) is not int or byte_end - byte_start != len(raw)
                or type(sequence) is not int or sequence <= 0):
            raise RunnerError("actual public phase-two marker snapshot input invalid")
        snapshot = snapshotter.capture(
            execution_id="execution-2", trace_sequence=sequence, role="marker",
            native_record={
                "transcript_id": "transcript-2", "byte_start": byte_start,
                "byte_end": byte_end, "sha256": _sha256(raw),
            },
        )
        marker_snapshots.append(snapshot)
        return snapshot.artifact_id

    _registration, phase_one_trusted = _registered_live_context_phase(
        client="claude", execution_id="execution-1", control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin, trusted_context=phase_one_live.trusted_context,
        expected_execution_ids=frozenset({"execution-1"}),
    )
    _registration_two, phase_two_trusted = _prepare_registered_live_executable(
        client="claude", execution_id="execution-2", control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin,
    )
    if (_registration is not plan.registration or _registration_two is not plan.registration
            or phase_one_trusted is not phase_one_live.trusted_executable):
        raise RunnerError("registered actual public executable registration changed")
    trusted_context = _registered_live_trusted_context(
        control_pin=prepared.control_pin, workspace_pin=prepared.workspace_pin,
        trusted_executables={
            "execution-1": phase_one_trusted,
            "execution-2": phase_two_trusted,
        },
    )
    _verify_registered_phase_roots(
        writer=writer, workspace=prepared.workspace, control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin, trace=trace,
    )
    verify_phase_control(phase_control)
    verify_control_file(runner_state)
    verify_control_file(mcp_config)
    _verify_phase_prompt(prompt)
    return _RegisteredActualPublicPhaseTwo(
        authorization=authorization, writer=writer, control_pin=prepared.control_pin,
        workspace_pin=prepared.workspace_pin, phase_control=phase_control,
        phase_prompt=prompt, mcp_config=mcp_config, runner_state=runner_state,
        trace=trace, initial_workspace_snapshot=initial_snapshot,
        marker_workspace_snapshots=marker_snapshots,
        on_native_record=capture_marker_snapshot, trusted_context=trusted_context,
    )


def _launch_registered_actual_public_phase_two(
    prepared_phase: _RegisteredActualPublicPhaseTwo,
) -> RegisteredLivePhase:
    """Launch only a previously sealed public second phase with host defaults."""

    if type(prepared_phase) is not _RegisteredActualPublicPhaseTwo:
        raise RunnerError("registered actual public phase-two setup is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot execute public execution")
    prepared_phase.__post_init__()
    authorization = prepared_phase.authorization
    prepared_run = authorization.prepared_run
    plan = prepared_run.authority.plan
    phase_one_live = authorization.phase_one.live_phase
    if not _registered_phase_evidence_is_bound(
            writer=prepared_phase.writer, workspace=prepared_run.prepared.workspace,
            execution_id="execution-1", phase="approval", live_phase=phase_one_live,
            control_pin=prepared_phase.control_pin,
            expected_execution_ids=frozenset({"execution-1"})):
        raise RunnerError("registered actual public phase-one evidence is no longer bound")
    _registered_live_context_phase(
        client="claude", execution_id="execution-2", control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin, trusted_context=prepared_phase.trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    verify_phase_control(prepared_phase.phase_control)
    verify_control_file(prepared_phase.runner_state)
    verify_control_file(prepared_phase.mcp_config)
    _verify_phase_prompt(prepared_phase.phase_prompt)
    argv = build_effective_argv(
        "claude", plan.symbolic_template, prepared_run.prepared.workspace,
        prepared_phase.mcp_config.path,
        prepared_phase.phase_prompt.raw.decode("utf-8", "strict"),
    )
    environment = {
        "PATH": "/usr/bin:/bin",
        "HOME": str(prepared_phase.writer.control_root / "home"),
        "LANG": "C.UTF-8",
        CONTROL_ENV: str(prepared_phase.writer.control_root),
        RUNNER_STATE_ENV: str(prepared_phase.runner_state.path),
    }
    try:
        live = _launch_registered_live_phase(
            writer=prepared_phase.writer, client="claude", execution_id="execution-2",
            phase="approved_capture", phase_index=2, workspace=prepared_run.prepared.workspace,
            control_pin=prepared_phase.control_pin, workspace_pin=prepared_phase.workspace_pin,
            argv=argv, environment=environment, stdin=b"", trace=prepared_phase.trace,
            transcript_id="transcript-2", on_native_record=prepared_phase.on_native_record,
            probe_runner=None, popen_factory=subprocess.Popen,
            trusted_context=prepared_phase.trusted_context,
        )
    finally:
        verify_phase_control(prepared_phase.phase_control)
        verify_control_file(prepared_phase.runner_state)
        verify_control_file(prepared_phase.mcp_config)
        _verify_phase_prompt(prepared_phase.phase_prompt)
    return live


@dataclass(frozen=True)
class _RegisteredActualPublicPhaseTwoEvidence:
    """The indexed, non-semantic host facts from the public second phase."""

    prepared_phase: _RegisteredActualPublicPhaseTwo
    live_phase: RegisteredLivePhase
    normalized: NativeNormalization
    conversion: ShimCaptureConversion
    policy_id: str
    process_id: str
    transcript_id: str
    stderr_id: str
    trace_id: str
    trace_sha256: str

    def __post_init__(self) -> None:
        expected = {
            "policy_id": "policy-2", "process_id": "process-2",
            "transcript_id": "transcript-2", "stderr_id": "stderr-2",
            "trace_id": "trace-execution-2",
        }
        values = {
            "policy_id": self.policy_id, "process_id": self.process_id,
            "transcript_id": self.transcript_id, "stderr_id": self.stderr_id,
            "trace_id": self.trace_id,
        }
        if (type(self.prepared_phase) is not _RegisteredActualPublicPhaseTwo
                or type(self.live_phase) is not RegisteredLivePhase
                or type(self.normalized) is not NativeNormalization
                or type(self.conversion) is not ShimCaptureConversion
                or values != expected or not _is_hex64(self.trace_sha256)
                or not self.normalized.complete or self.normalized.reason is not None
                or self.live_phase.executable_id != "client-executable-2"
                or self.live_phase.capture.exit_code != 0):
            raise RunnerError("registered actual public phase-two evidence is invalid")

    def __reduce__(self) -> object:
        raise TypeError("registered actual public phase-two evidence is not serializable")


def _index_registered_actual_public_phase_two(
    prepared_phase: _RegisteredActualPublicPhaseTwo,
    live_phase: RegisteredLivePhase,
) -> _RegisteredActualPublicPhaseTwoEvidence:
    """Index public phase-two host evidence with its pre-existing authority.

    This is deliberately before any marker, event, assertion, manifest, or
    pass artifact.  Its policy/process rows bind the pre-launch public grant
    exactly, so later semantic work has no opportunity to authorize capture
    retrospectively.
    """

    if (type(prepared_phase) is not _RegisteredActualPublicPhaseTwo
            or type(live_phase) is not RegisteredLivePhase):
        raise RunnerError("registered actual public phase-two index inputs are invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot index public execution")
    prepared_phase.__post_init__()
    authorization = prepared_phase.authorization
    prepared_run = authorization.prepared_run
    plan = prepared_run.authority.plan
    phase_one = authorization.phase_one
    phase_one_live = phase_one.live_phase
    writer = prepared_phase.writer
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    expected_approval = {**dict(authorization.approval), "decision": "approved"}
    if (plan.client != "claude" or plan.scenario_id != "web-approval-and-capture"
            or live_phase.control_pin is not prepared_phase.control_pin
            or live_phase.workspace_pin is not prepared_phase.workspace_pin
            or live_phase.executable_id != "client-executable-2"
            or live_phase.version_id != "version-2" or live_phase.help_id != "help-2"
            or live_phase.capture.exit_code != 0
            or {"web-approval", "fixture-capability", "fixture-descriptor",
                "fixture-static-shell", "fixture-rendered-dom"}
            - {str(entry.get("id")) for entry in writer.entries}
            or {"policy-2", "process-2", "transcript-2", "stderr-2",
                "trace-execution-2"} & {str(entry.get("id")) for entry in writer.entries}):
        raise RunnerError("registered actual public phase-two index is invalid")
    if not _registered_phase_evidence_is_bound(
            writer=writer, workspace=prepared_run.prepared.workspace,
            execution_id="execution-1", phase="approval", live_phase=phase_one_live,
            control_pin=prepared_phase.control_pin,
            expected_execution_ids=frozenset({"execution-1"})):
        raise RunnerError("registered actual public phase-one evidence is no longer bound")
    _registration, trusted = _registered_live_context_phase(
        client="claude", execution_id="execution-2", control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin, trusted_context=live_phase.trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    if _registration is not plan.registration or trusted is not live_phase.trusted_executable:
        raise RunnerError("registered actual public phase-two live context is invalid")
    normalized = normalize_native_transcript(
        client="claude", version=live_phase.reported_version,
        transcript=live_phase.capture.stdout,
    )
    if not normalized.complete:
        raise RunnerError("registered actual public phase-two native transcript is unsupported")
    verify_phase_control(prepared_phase.phase_control)
    verify_control_file(prepared_phase.runner_state)
    verify_control_file(prepared_phase.mcp_config)
    _verify_phase_prompt(prepared_phase.phase_prompt)
    trace_rows = prepared_phase.trace.records()
    if not trace_rows:
        raise RunnerError("registered actual public phase-two trace is missing")
    validate_trace_records(trace_rows)
    transcript_raw = _preserve_transcript(
        writer.control_root, "transcript-2", live_phase.capture.stdout,
    )
    policy_id = writer.add_json("policy-2", "policy", {
        "run_id": writer.run_id, "execution_id": "execution-2",
        "phase": "approved_capture", "client": "claude",
        "profile": "claude-restricted-tool-surface-v1", "network_attestation": "mock-only",
        "argv": list(live_phase.argv), "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
        "version_id": "version-2", "help_id": "help-2",
        "fixture_id": metadata.fixture_id, "fixture_sha256": metadata.fixture_sha256,
        "fixture_capability_id": "fixture-capability", "approval": expected_approval,
        "phase_prompt_id": "phase-prompt-2", "phase_prompt_sha256": prepared_phase.phase_prompt.sha256,
        "phase_prompt_transport": prepared_phase.phase_prompt.transport,
        "executable_id": "client-executable-2", "mcp_config_id": "mcp-2",
        "mcp_config_sha256": prepared_phase.mcp_config.sha256,
        "mcp_path": str(prepared_phase.mcp_config.path),
        "mcp_identity": dict(prepared_phase.mcp_config.identity),
    })
    transcript_id = writer.add_bytes("transcript-2", "transcript", transcript_raw)
    stderr_id = writer.add_bytes("stderr-2", "file_capture", live_phase.capture.stderr)
    conversion = convert_shim_captures(
        writer, control_root=writer.control_root, run_id=writer.run_id,
        execution_id="execution-2", phase="approved_capture", transcript_id=transcript_id,
        trace=prepared_phase.trace, control_pin=prepared_phase.control_pin,
        prior_raw_index=phase_one.conversion.raw_index,
        prior_raw_command_log=phase_one.conversion.raw_command_log,
        prior_raw_preapply_manifests=phase_one.conversion.raw_preapply_manifests,
    )
    process_id = writer.add_json("process-2", "process", {
        "run_id": writer.run_id, "execution_id": "execution-2",
        "phase": "approved_capture", "client": "claude",
        "client_version": live_phase.reported_version,
        "argv": list(live_phase.argv), "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
        "exit_code": live_phase.capture.exit_code, "transcript_id": transcript_id,
        "transcript_sha256": _sha256(transcript_raw), "trace_id": conversion.trace_id,
        "trace_sha256": conversion.trace_sha256, "native_format": live_phase.native_format,
        "fixture_id": metadata.fixture_id, "fixture_sha256": metadata.fixture_sha256,
        "fixture_capability_id": "fixture-capability", "approval": expected_approval,
        "phase_prompt_id": "phase-prompt-2", "phase_prompt_sha256": prepared_phase.phase_prompt.sha256,
        "phase_prompt_transport": prepared_phase.phase_prompt.transport,
        "executable_id": "client-executable-2",
        "mcp_identity": dict(prepared_phase.mcp_config.identity),
    })
    _registered_executable_observation(trusted)
    if not _registered_phase_evidence_is_bound(
            writer=writer, workspace=prepared_run.prepared.workspace,
            execution_id="execution-2", phase="approved_capture", live_phase=live_phase,
            control_pin=prepared_phase.control_pin,
            expected_execution_ids=frozenset({"execution-1", "execution-2"})):
        raise RunnerError("registered actual public phase-two evidence is not bound")
    return _RegisteredActualPublicPhaseTwoEvidence(
        prepared_phase=prepared_phase, live_phase=live_phase, normalized=normalized,
        conversion=conversion, policy_id=policy_id, process_id=process_id,
        transcript_id=transcript_id, stderr_id=stderr_id, trace_id=conversion.trace_id,
        trace_sha256=conversion.trace_sha256,
    )


@dataclass(frozen=True)
class RegisteredHostExecutionEligibility:
    """Non-serializable aggregate host proof for the closed public web route.

    It contains no semantic plan, assertion result, or boolean claiming a
    client pass.  Those are deliberately derived only after this object has
    revalidated the two registered launches and their already-indexed public
    capability/approval joins.
    """

    authorization: _RegisteredActualPublicWebAuthorization
    phase_two: _RegisteredActualPublicPhaseTwoEvidence
    execution_order: tuple[tuple[str, int], ...]
    entry_snapshot: Mapping[str, tuple[str, str, str, int, tuple[int, ...]]]

    def __post_init__(self) -> None:
        if (type(self.authorization) is not _RegisteredActualPublicWebAuthorization
                or type(self.phase_two) is not _RegisteredActualPublicPhaseTwoEvidence
                or self.phase_two.prepared_phase.authorization is not self.authorization
                or self.execution_order != (("execution-1", 0), ("execution-2", 1))
                or not isinstance(self.entry_snapshot, Mapping)):
            raise RunnerError("registered host execution eligibility is invalid")
        frozen: dict[str, tuple[str, str, str, int, tuple[int, ...]]] = {}
        for artifact_id, record in self.entry_snapshot.items():
            if (type(artifact_id) is not str or not artifact_id
                    or type(record) is not tuple or len(record) != 5
                    or type(record[0]) is not str or type(record[1]) is not str
                    or not _is_hex64(record[2]) or type(record[3]) is not int or record[3] < 0
                    or type(record[4]) is not tuple or len(record[4]) != 8
                    or any(type(value) is not int for value in record[4])):
                raise RunnerError("registered host execution eligibility is invalid")
            frozen[artifact_id] = record
        if not frozen:
            raise RunnerError("registered host execution eligibility is invalid")
        object.__setattr__(self, "entry_snapshot", MappingProxyType(frozen))

    def verify(self) -> _IndexedExecutionBinding:
        """Re-read every retained host row before semantic candidate writes."""

        self.__post_init__()
        authorization = self.authorization
        prepared_run = authorization.prepared_run
        phase_one = authorization.phase_one
        phase_two = self.phase_two
        writer = prepared_run.writer
        metadata = _registered_actual_scenario_fixture_metadata(
            prepared_run, prepared_run.authority.plan,
        )
        scenario = metadata.scenario()
        expected_approval = {**dict(authorization.approval), "decision": "approved"}
        current_entries = _writer_entry_map(writer)
        current_snapshot: dict[str, tuple[str, str, str, int, tuple[int, ...]]] = {}
        for artifact_id, entry in current_entries.items():
            relative = entry.get("relative_path")
            identity = writer.write_identities.get(relative) if isinstance(relative, str) else None
            if (type(entry.get("type")) is not str or type(relative) is not str
                    or not _is_hex64(entry.get("sha256"))
                    or type(entry.get("bytes")) is not int or identity is None):
                raise RunnerError("registered host evidence inventory is invalid")
            raw = _writer_artifact_bytes(writer, artifact_id, str(entry["type"]),
                                         control_pin=prepared_run.prepared.control_pin)
            if len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]:
                raise RunnerError("registered host evidence changed")
            path = writer.run_root / relative
            if PinnedDirectory._regular_identity(path.lstat()) != identity:
                raise RunnerError("registered host evidence identity changed")
            current_snapshot[artifact_id] = (
                entry["type"], relative, entry["sha256"], entry["bytes"], identity,
            )
        # Candidate semantic rows are intentionally appended after this host
        # proof exists.  They may grow the writer, but they cannot replace,
        # remove, or rebaseline one retained host row.
        if any(current_snapshot.get(artifact_id) != record
               for artifact_id, record in self.entry_snapshot.items()):
            raise RunnerError("registered host evidence inventory changed")
        # Public projection is a closed two-execution route.  Semantic rows
        # may be appended after this receipt, but a third phase's host-shaped
        # residue must never be ignored merely because it was not present in
        # the original receipt snapshot.
        phase_artifact_ids = {
            "policy-1", "policy-2", "process-1", "process-2",
            "client-executable-1", "client-executable-2", "version-1",
            "version-2", "help-1", "help-2", "transcript-1", "transcript-2",
            "stderr-1", "stderr-2", "trace-execution-1", "trace-execution-2",
            "mcp-1", "mcp-2", "phase-prompt-1", "phase-prompt-2",
        }
        phase_prefixes = (
            "policy-", "process-", "client-executable-", "version-", "help-",
            "transcript-", "stderr-", "trace-execution-", "mcp-", "phase-prompt-",
        )
        if any(
                artifact_id.startswith(phase_prefixes) and artifact_id not in phase_artifact_ids
                for artifact_id in current_entries
        ):
            raise RunnerError("registered host evidence contains an extra execution")
        if not _registered_phase_evidence_is_bound(
                writer=writer, workspace=prepared_run.prepared.workspace,
                execution_id="execution-1", phase="approval", live_phase=phase_one.live_phase,
                control_pin=prepared_run.prepared.control_pin,
                expected_execution_ids=frozenset({"execution-1"})):
            raise RunnerError("registered host phase-one evidence is no longer bound")
        if not _registered_phase_evidence_is_bound(
                writer=writer, workspace=prepared_run.prepared.workspace,
                execution_id="execution-2", phase="approved_capture",
                live_phase=phase_two.live_phase, control_pin=prepared_run.prepared.control_pin,
                expected_execution_ids=frozenset({"execution-1", "execution-2"})):
            raise RunnerError("registered host phase-two evidence is no longer bound")
        binding = _indexed_execution_binding(
            writer, run_id=writer.run_id, scenario=scenario,
            execution_order=dict(self.execution_order), workspace=prepared_run.prepared.workspace,
            client="claude", fixture_sha256=metadata.fixture_sha256,
            fixture_capability_id="fixture-capability", approval=expected_approval,
        )
        if binding is None:
            raise RunnerError("registered host execution binding is unavailable")
        return binding

    def __reduce__(self) -> object:
        raise TypeError("registered host execution eligibility is not serializable")


def _registered_host_execution_eligibility(
    authorization: _RegisteredActualPublicWebAuthorization,
    phase_two: _RegisteredActualPublicPhaseTwoEvidence,
) -> RegisteredHostExecutionEligibility:
    """Fix the public two-phase host graph before any semantic projection."""

    if (type(authorization) is not _RegisteredActualPublicWebAuthorization
            or type(phase_two) is not _RegisteredActualPublicPhaseTwoEvidence
            or phase_two.prepared_phase.authorization is not authorization):
        raise RunnerError("registered host execution eligibility inputs are invalid")
    authorization.__post_init__()
    phase_two.__post_init__()
    prepared_run = authorization.prepared_run
    writer = prepared_run.writer
    metadata = _registered_actual_scenario_fixture_metadata(
        prepared_run, prepared_run.authority.plan,
    )
    scenario = metadata.scenario()
    expected_approval = {**dict(authorization.approval), "decision": "approved"}
    if "run-manifest" in _writer_entry_map(writer):
        raise RunnerError("registered public run manifest is already indexed")
    run_manifest = {
        "schema_version": 1, "run_id": writer.run_id, "client": "claude",
        "scenario_id": scenario["id"], "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256,
        "workspace": str(prepared_run.prepared.workspace),
        "phases": ["approval", "approved_capture"],
        "policy_profiles": ["claude-restricted-tool-surface-v1"] * 2,
        "fixture_capability_id": "fixture-capability", "approval": expected_approval,
        "software_paths": list(_software_paths_for_scenario(scenario)),
        "scenario_sha256": scenario_sha256(scenario),
        "phase_prompt_protocol": PROMPT_PROTOCOL,
        "phase_prompts": [
            {
                "execution_id": "execution-1", "phase": "approval",
                "phase_prompt_id": "phase-prompt-1",
                "phase_prompt_sha256": phase_two.prepared_phase.authorization.phase_one.prepared_phase.phase_prompt.sha256,
                "phase_prompt_transport": "argv_final_utf8",
            },
            {
                "execution_id": "execution-2", "phase": "approved_capture",
                "phase_prompt_id": "phase-prompt-2",
                "phase_prompt_sha256": phase_two.prepared_phase.phase_prompt.sha256,
                "phase_prompt_transport": "argv_final_utf8",
            },
        ],
    }
    writer.add_fixed_json("run-manifest", "run_manifest", "run-manifest.json", run_manifest)
    snapshot: dict[str, tuple[str, str, str, int, tuple[int, ...]]] = {}
    for artifact_id, entry in _writer_entry_map(writer).items():
        relative = entry["relative_path"]
        identity = writer.write_identities.get(relative)
        if identity is None:
            raise RunnerError("registered host evidence receipt is unavailable")
        snapshot[artifact_id] = (
            str(entry["type"]), str(relative), str(entry["sha256"]), int(entry["bytes"]), identity,
        )
    eligibility = RegisteredHostExecutionEligibility(
        authorization=authorization, phase_two=phase_two,
        execution_order=(("execution-1", 0), ("execution-2", 1)),
        entry_snapshot=MappingProxyType(snapshot),
    )
    eligibility.verify()
    return eligibility


@dataclass(frozen=True)
class PublicPassEligibility:
    """The sole internal proof permitted to form a public pass candidate."""

    host: RegisteredHostExecutionEligibility
    semantic_plan: SemanticEventPlan
    repository_facts: RepositoryAssertionFacts
    candidate_log: Mapping[str, Any]
    candidate_raw: bytes = field(init=False, repr=False)

    def __post_init__(self) -> None:
        if (type(self.host) is not RegisteredHostExecutionEligibility
                or type(self.semantic_plan) is not SemanticEventPlan
                or type(self.repository_facts) is not RepositoryAssertionFacts
                or not self.semantic_plan.complete or not self.repository_facts.complete
                or not isinstance(self.candidate_log, Mapping)):
            raise RunnerError("public pass eligibility is invalid")
        raw = _canonical_json(dict(self.candidate_log))
        canonical = _strict_json(raw, label="public pass candidate")
        if (type(canonical) is not dict or canonical.get("result") != "pass"
                or canonical.get("incomplete_reasons") != []):
            raise RunnerError("public pass eligibility is invalid")
        object.__setattr__(self, "candidate_log", MappingProxyType(canonical))
        object.__setattr__(self, "candidate_raw", raw)

    def verify(self) -> _IndexedExecutionBinding:
        binding = self.host.verify()
        self.repository_facts.__post_init__()
        if _canonical_json(dict(self.candidate_log)) != self.candidate_raw:
            raise RunnerError("public pass candidate was mutated")
        if not self.repository_facts.complete:
            raise RunnerError("public pass assertions are incomplete")
        expected_events = tuple(self.semantic_plan.events)
        candidate = self.candidate_log
        if (candidate.get("events") != list(expected_events)
                or candidate.get("receipts") != list(self.semantic_plan.receipts)
                or candidate.get("deliveries") != list(self.semantic_plan.deliveries)):
            raise RunnerError("public pass candidate semantic rows changed")
        return binding

    def __reduce__(self) -> object:
        raise TypeError("public pass eligibility is not serializable")


def _project_registered_actual_public_web_candidate(
    host: RegisteredHostExecutionEligibility,
) -> PublicPassEligibility:
    """Derive one public semantic candidate from a sealed two-phase host proof."""

    if type(host) is not RegisteredHostExecutionEligibility:
        raise RunnerError("registered public candidate host eligibility is invalid")
    binding = host.verify()
    authorization = host.authorization
    prepared_run = authorization.prepared_run
    phase_one = authorization.phase_one
    phase_two = host.phase_two
    writer = prepared_run.writer
    metadata = _registered_actual_scenario_fixture_metadata(
        prepared_run, prepared_run.authority.plan,
    )
    scenario = metadata.scenario()
    expected_approval = {**dict(authorization.approval), "decision": "approved"}
    # No old or private semantic projection can be extended into this stage.
    if any(entry.get("type") in {"marker", "event_record", "assertion", "interpretation_decision"}
           for entry in writer.entries):
        raise RunnerError("registered public candidate semantic stage is not empty")

    phases = (
        ("execution-1", "approval", phase_one.normalized,
         phase_one.prepared_phase.trace.records(), phase_one.transcript_id,
         phase_one.conversion, phase_one.prepared_phase.marker_workspace_snapshots,
         phase_one.prepared_phase.initial_workspace_snapshot),
        ("execution-2", "approved_capture", phase_two.normalized,
         phase_two.prepared_phase.trace.records(), phase_two.transcript_id,
         phase_two.conversion, phase_two.prepared_phase.marker_workspace_snapshots,
         phase_two.prepared_phase.initial_workspace_snapshot),
    )
    markers: list[SemanticMarkerEvidence] = []
    commands: list[SemanticCommandEvidence] = []
    marker_snapshots: list[WorkspaceSnapshot] = []
    initial_snapshots: dict[str, WorkspaceSnapshot] = {}
    execution_order = dict(host.execution_order)
    for execution_id, phase, normalized, trace_rows, transcript_id, conversion, snapshots, initial in phases:
        if (type(normalized) is not NativeNormalization or not normalized.complete
                or not trace_rows or not isinstance(conversion, ShimCaptureConversion)):
            raise RunnerError("registered public candidate phase evidence is unavailable")
        transcript = _writer_artifact_bytes(writer, transcript_id, "transcript")
        phase_markers = extract_event_markers(
            transcript=transcript, native_records=normalized.records, trace_records=trace_rows,
            transcript_id=transcript_id,
            allowed_event_names=_semantic_events_for_phase(scenario, phase),
        )
        for candidate in phase_markers:
            markers.append(SemanticMarkerEvidence(
                marker_id=f"marker-{len(markers) + 1}", execution_id=execution_id,
                candidate=candidate, transcript_id=transcript_id,
            ))
        commands.extend(_semantic_commands_from_conversion(writer, conversion))
        marker_snapshots.extend(snapshots)
        initial_snapshots[execution_id] = initial
    verified_markers = _verified_marker_trace_evidence(writer, tuple(markers))
    trace_snapshot_ids = _indexed_native_snapshot_ids(writer)
    receipt_operations = scenario.get("receipt_operations")
    if type(receipt_operations) is not list:
        raise RunnerError("registered public candidate receipt operations are invalid")
    deliveries = _semantic_deliveries_from_commands(writer, tuple(commands), tuple(receipt_operations))
    cursor_proofs = _build_semantic_cursor_proofs(
        writer, run_id=writer.run_id, commands=tuple(commands),
    )
    diff_references = _build_marker_diff_references(
        writer, run_id=writer.run_id, required_events=tuple(scenario["required_events"]),
        markers=verified_markers, initial_snapshots=initial_snapshots,
        snapshots=tuple(marker_snapshots), execution_order=execution_order,
        trace_snapshot_ids=trace_snapshot_ids,
    )
    packet_references = _build_semantic_packet_references(
        writer, run_id=writer.run_id, required_events=tuple(scenario["required_events"]),
        markers=verified_markers, commands=tuple(commands), cursor_proofs=cursor_proofs,
        marker_snapshots=tuple(marker_snapshots), execution_order=execution_order,
        trace_snapshot_ids=trace_snapshot_ids,
    )
    artifact_types = {
        str(entry["id"]): str(entry["type"])
        for entry in writer.entries if isinstance(entry, Mapping)
    }
    references = _known_semantic_references(artifact_types, cursor_proofs)
    for generated in (packet_references, diff_references):
        for name, values in generated.items():
            target = references.setdefault(name, {})
            if set(target) & set(values):
                raise RunnerError("registered public candidate references collide")
            target.update(values)
    plan = plan_semantic_events(SemanticNormalizationInput(
        run_id=writer.run_id, scenario=scenario, execution_order=execution_order,
        markers=verified_markers, commands=tuple(commands), artifact_types=artifact_types,
        event_references=references, deliveries=deliveries, cursor_proofs=cursor_proofs,
    ))
    if not plan.complete:
        raise RunnerError("registered public semantic plan is incomplete")
    _emit_semantic_plan(writer, plan)
    if _indexed_semantic_replay(
            writer, run_id=writer.run_id, scenario=scenario, plan=plan,
            markers=verified_markers, commands=tuple(commands), execution_order=execution_order,
            workspace=prepared_run.prepared.workspace, client="claude",
            fixture_sha256=metadata.fixture_sha256, fixture_capability_id="fixture-capability",
            approval=expected_approval, private_candidate=False) is None:
        raise RunnerError("registered public semantic replay is unavailable")
    facts = _derive_repository_assertion_facts(
        writer, run_id=writer.run_id, scenario=scenario, marker_diff_references=diff_references,
        semantic_plan=plan, markers=verified_markers, marker_snapshots=tuple(marker_snapshots),
        initial_snapshots=initial_snapshots, commands=tuple(commands), execution_order=execution_order,
        workspace=prepared_run.prepared.workspace, trace_snapshot_ids=trace_snapshot_ids,
        client="claude", fixture_sha256=metadata.fixture_sha256,
        fixture_capability_id="fixture-capability", approval=expected_approval,
    )
    if not facts.complete:
        raise RunnerError("registered public repository assertions are incomplete")
    assertions = _emit_public_repository_assertions(writer, run_id=writer.run_id, facts=facts)
    candidate = {
        "schema_version": 1, "run_id": writer.run_id, "scenario_id": scenario["id"],
        "client": "claude", "client_version": binding.client_version,
        "fixture_sha256": metadata.fixture_sha256, "network_mode": scenario["network_mode"],
        "evidence_index_sha256": "0" * 64, "log_attestation_sha256": "0" * 64,
        "executions": [
            {"id": execution_id, "phase": binding.executions[execution_id]["phase"],
             "kind": "actual_client_process", "policy_id": f"policy-{index + 1}",
             "process_id": f"process-{index + 1}", "transcript_id": f"transcript-{index + 1}"}
            for execution_id, index in host.execution_order
        ],
        "receipts": list(plan.receipts), "deliveries": list(plan.deliveries),
        "events": list(plan.events), "repository_assertions": list(assertions),
        "result": "pass", "incomplete_reasons": [],
    }
    eligibility = PublicPassEligibility(host, plan, facts, candidate)
    eligibility.verify()
    return eligibility


def _finalize_registered_actual_public_pass(
    eligibility: PublicPassEligibility,
) -> PrepublicationFinalization:
    """Pass through the one existing atomic finalizer after final rechecks."""

    if type(eligibility) is not PublicPassEligibility:
        raise RunnerError("public pass eligibility is invalid")
    binding = eligibility.verify()
    host = eligibility.host
    prepared_run = host.authorization.prepared_run
    phase_two_live = host.phase_two.live_phase
    metadata = _registered_actual_scenario_fixture_metadata(
        prepared_run, prepared_run.authority.plan,
    )
    scenario = metadata.scenario()
    candidate = _strict_json(eligibility.candidate_raw, label="sealed public pass candidate")
    if type(candidate) is not dict:
        raise RunnerError("public pass candidate is invalid")
    if phase_two_live.trusted_context is not host.phase_two.prepared_phase.trusted_context:
        raise RunnerError("public pass trusted context changed")
    # `binding` is intentionally obtained above even though the generic
    # finalizer revalidates the full event-log contract: it closes the host
    # policy/process/probe graph immediately before evidence sealing begins.
    if binding.client_version != candidate.get("client_version"):
        raise RunnerError("public pass client version changed")
    return _atomic_validate_and_publish_candidate(
        writer=prepared_run.writer, candidate_log=candidate, scenario=scenario,
        fixture_sha256=metadata.fixture_sha256,
        trusted_context=phase_two_live.trusted_context,
    )


def _run_registered_actual_public_web_route(
    authority: "_RegisteredActualAuthority",
) -> "RunOutcome":
    """Execute the closed public route without widening a legacy entrypoint.

    This remains an internal route: the CLI, ``run_scenario()``, and the
    existing diagnostic dispatcher do not call it.  Tests exercise its
    private boundaries with local fakes only; an actual client invocation
    remains a separate explicit operational action.
    """

    if type(authority) is not _RegisteredActualAuthority:
        raise RunnerError("registered actual public route authority is invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot execute public route")
    plan = authority.plan
    if (type(plan) is not RegisteredActualScenarioPlan
            or plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or phase_plan(plan.scenario_id) != ("approval", "approved_capture")):
        raise RunnerError("registered actual public route rejects this plan")
    prepared_run = _prepare_registered_actual_run(authority)
    first_setup = _prepare_registered_actual_phase_one(prepared_run)
    first_live = _launch_actual_registered_live_phase(first_setup)
    phase_one = _index_registered_actual_public_phase_one(first_setup, first_live)
    authorization = _authorize_registered_actual_public_web_phase_two(prepared_run, phase_one)
    second_setup = _prepare_registered_actual_public_phase_two(authorization)
    second_live = _launch_registered_actual_public_phase_two(second_setup)
    phase_two = _index_registered_actual_public_phase_two(second_setup, second_live)
    host = _registered_host_execution_eligibility(authorization, phase_two)
    eligibility = _project_registered_actual_public_web_candidate(host)
    finalization = _finalize_registered_actual_public_pass(eligibility)
    return RunOutcome(
        finalization.log, finalization.log_path, prepared_run.prepared.workspace,
        prepared_run.prepared.control_root, trusted_context=None,
    )


def _phase_one_web_capture_authorized(
    *,
    writer: EvidenceWriter,
    scenario: Mapping[str, Any],
    capture: ProcessCapture,
    marker_time_streamed: bool,
    normalized: NativeNormalization,
    transcript: bytes,
    transcript_id: str,
    trace_rows: Sequence[Mapping[str, Any]],
    conversion: ShimCaptureConversion | None,
    workspace: Path,
    execution_id: str,
    registered_phase: RegisteredLivePhase | None = None,
) -> bool:
    """Require a narrow, parser-backed phase-one stop before fixture release.

    This is only a transition guard for the otherwise test-only runner.  It
    never produces an event record or a passing evaluation; the full semantic
    marker-to-command/receipt/diff normalizer remains a separate prerequisite
    for a real registered launch.
    """

    if (not marker_time_streamed or capture.exit_code != 0
            or not normalized.complete or conversion is None):
        return False
    if (registered_phase is not None
            and not _registered_phase_evidence_is_bound(
                writer=writer, workspace=workspace, execution_id=execution_id,
                phase="approval", live_phase=registered_phase,
            )):
        return False
    try:
        from tests.evals import event_log_contract as contract

        # Close Task 7a's exact native/trace/snapshot graph *before* phase two
        # receives fixture authority.  In particular this re-parses the
        # initialization record and rejects a parser-valid transcript whose
        # ``cwd`` is not the isolated runner workspace.  It also reloads every
        # indexed snapshot rather than trusting a Python snapshot handle.
        control = _IndexedSemanticControl(
            writer, run_id=writer.run_id, workspace=workspace,
        )
        execution = {
            "id": execution_id,
            "phase": "approval",
            "transcript_id": transcript_id,
        }
        process = {
            "trace_id": conversion.trace_id,
            "trace_sha256": conversion.trace_sha256,
            "native_format": "claude-stream-json-2.1.251-v1",
        }
        phase_log = {
            "run_id": writer.run_id,
            "scenario_id": "web-approval-and-capture",
            "client": "claude",
            "client_version": _version_text(capture.version),
            "fixture_sha256": "0" * 64,
            "network_mode": "mock_only",
            "events": [], "receipts": [], "deliveries": [],
        }
        contract._execution_trace(control, execution, process, phase_log)
        contract._audit_workspace_snapshots(control, {execution_id: execution})

        # A marker emitted while a shim command owns the trace is ambiguous;
        # a command completed after the marker cannot retroactively authorize
        # it either.  Enforce the sealed approval-phase protocol—including
        # the initial-sync receipt lifecycle—before phase two receives any
        # fixture authority.
        from tests.evals.phase_prompt_contract import required_events_for_phase

        approval_events = required_events_for_phase(scenario, "approval")
        receipt_events = (
            "initial_sync_receipt_verified",
            "initial_sync_receipt_consumed",
            "initial_sync_receipt_durable",
            "initial_sync_receipt_acknowledged",
        )
        if approval_events != (
            *receipt_events,
            "report_local_evidence_gap",
            "ask_web_approval",
        ):
            return False
        _reject_native_inside_command_interval(trace_rows)
        candidates = extract_event_markers(
            transcript=transcript,
            native_records=normalized.records,
            trace_records=trace_rows,
            transcript_id=transcript_id,
            allowed_event_names=approval_events,
        )
        if tuple(candidate.event_name for candidate in candidates) != approval_events:
            return False
        markers = tuple(
            SemanticMarkerEvidence(
                marker_id=f"phase-one-marker-{index}",
                execution_id=execution_id,
                candidate=candidate,
                transcript_id=transcript_id,
            )
            for index, candidate in enumerate(candidates, 1)
        )
        report = candidates[-2]
        approval_marker = candidates[-1]
        report_text = normalized.records[report.native_record_start]["texts"][report.text_pointer]
        if type(report_text) is not str or "prior standard" not in report_text:
            return False
        phase_order = {execution_id: 0}
        acknowledgement_position = _semantic_marker_order_position(
            phase_order, markers[len(receipt_events) - 1],
        )
        report_position = _semantic_marker_order_position(
            phase_order,
            markers[-2],
        )
        approval_position = _semantic_marker_order_position(
            phase_order,
            markers[-1],
        )
        # ``byte_*`` offsets are local to a content block.  The sourced
        # canonical marker position orders native span, content-block index,
        # then local byte offset; comparing local offsets across blocks would
        # reject a valid report in block 0 followed by approval in block 1.
        if (acknowledgement_position is None or report_position is None
                or approval_position is None
                or acknowledgement_position >= report_position
                or report_position >= approval_position
                or (report.native_record_start == approval_marker.native_record_start
                    and report.text_pointer == approval_marker.text_pointer
                    and report.byte_end > approval_marker.byte_start)):
            return False
        # Conversion has already copied and indexed every raw command result.
        # Rebuild the entire first receipt through the same strict planner and
        # Task 7a lifecycle decoder used by final replay.  A lone sync,
        # missing source-state checkpoint, skipped durable read, duplicate
        # role, or an extra command must all block phase two.
        commands = _semantic_commands_from_conversion(writer, conversion)
        if len(commands) != len(receipt_events):
            return False
        artifact_types = {
            str(entry["id"]): str(entry["type"])
            for entry in writer.entries
            if isinstance(entry, Mapping)
            and type(entry.get("id")) is str
            and type(entry.get("type")) is str
        }
        receipt_plan = plan_semantic_events(SemanticNormalizationInput(
            run_id=writer.run_id,
            scenario={
                "id": "phase-one-initial-sync",
                "required_events": list(receipt_events),
                "receipt_operations": ["initial_sync"],
            },
            execution_order=phase_order,
            markers=markers[:len(receipt_events)],
            commands=commands,
            artifact_types=artifact_types,
            event_references={},
            deliveries=(),
        ))
        if (not receipt_plan.complete
                or len(receipt_plan.receipts) != 1
                or receipt_plan.receipts[0].get("operation") != "initial_sync"
                or receipt_plan.deliveries):
            return False
        overlay = _private_semantic_overlay(
            writer, run_id=writer.run_id, plan=receipt_plan,
            markers=markers[:len(receipt_events)],
        )
        if overlay is None:
            return False
        receipt_control = control.with_private_semantic_overlay(overlay)
        receipt_log = {
            **phase_log,
            "events": [dict(event) for event in receipt_plan.events],
            "receipts": [dict(receipt) for receipt in receipt_plan.receipts],
            "deliveries": [],
            "_scenario_required_events": list(receipt_events),
        }
        marker_by_id = {marker.marker_id: marker for marker in markers}
        if len(marker_by_id) != len(markers):
            return False
        for event in receipt_log["events"]:
            marker = marker_by_id.get(event["transcript_marker_id"])
            marker_position = (
                _semantic_marker_order_position(phase_order, marker)
                if marker is not None else None
            )
            if marker_position is None or marker_position >= report_position:
                return False
            contract._validate_marker(receipt_control, event, execution, writer.run_id)
            contract._validate_event_record(receipt_control, event, writer.run_id)
        contract._event_order(receipt_control, receipt_log, {execution_id: execution})
        verified_receipts = contract._validate_receipts(
            receipt_control, receipt_log, receipt_log["events"],
        )
        if set(verified_receipts) != {"receipt-initial-sync"}:
            return False
        contract._audit_commands(
            receipt_control, receipt_log, {execution_id: execution}, verified_receipts,
        )
    except (ImportError, KeyError, RunnerError, ValueError):
        return False
    return True


def convert_shim_captures(
    writer: EvidenceWriter,
    *,
    control_root: Path,
    run_id: str,
    execution_id: str,
    phase: str,
    transcript_id: str,
    trace: ControlTraceWriter,
    control_pin: PinnedDirectory | None = None,
    prior_raw_index: bytes = b"",
    prior_raw_command_log: bytes = b"",
    prior_raw_preapply_manifests: bytes = b"",
) -> ShimCaptureConversion:
    """Convert 7b's command-bound raw captures into immutable typed artifacts.

    The workspace is intentionally never read here.  Every byte comes from
    the runner-owned control tree that the wrapper wrote while it still held
    the command boundary lock.
    """

    if control_pin is not None:
        if control_pin.path != control_root.resolve():
            raise RunnerError("capture conversion control pin mismatch")
        # Phase-one diagnostic conversion can receive the frozen bridge
        # facade below.  Bypass mutable instance dispatch only for the raw
        # descriptor; the facade's verifier is itself the retained-snapshot
        # boundary and deliberately has a different shape.
        if type(control_pin) is PinnedDirectory:
            PinnedDirectory.verify(control_pin)
        else:
            control_pin.verify()
    raw_index = _read_control_capture(
        control_root, "brain-shim-capture-index.jsonl", control_pin=control_pin,
    )
    phase_raw_index = _phase_capture_delta(
        raw_index, prior_raw_index, label="shim capture index"
    )
    writer.add_bytes(f"raw-capture-index-{execution_id}", "file_capture", phase_raw_index)
    rows = [_strict_json(line, label="shim capture index") for line in phase_raw_index.splitlines()]
    if not rows:
        raise RunnerError("trusted shim capture index is empty")
    raw_command_log = _read_control_capture(
        control_root, "brain-shim-command-log.jsonl", control_pin=control_pin,
    )
    phase_raw_command_log = _phase_capture_delta(
        raw_command_log, prior_raw_command_log, label="shim command log"
    )
    writer.add_bytes(
        f"raw-command-log-{execution_id}", "file_capture", phase_raw_command_log
    )
    command_rows = [
        _strict_json(line, label="shim command log")
        for line in phase_raw_command_log.splitlines()
    ]
    if len(command_rows) != len(rows):
        raise RunnerError("shim command log/index row count mismatch")
    raw_preapply_manifests = _optional_control_capture(
        control_root, "runner-preapply-manifests.jsonl", control_pin=control_pin,
    )
    if raw_preapply_manifests:
        phase_raw_preapply_manifests = _phase_optional_capture_delta(
            raw_preapply_manifests, prior_raw_preapply_manifests,
            label="runner preapply manifest capture",
        )
    elif prior_raw_preapply_manifests:
        raise RunnerError("runner preapply manifest capture disappeared")
    else:
        phase_raw_preapply_manifests = b""
    if phase_raw_preapply_manifests:
        writer.add_bytes(
            f"raw-preapply-manifests-{execution_id}", "file_capture",
            phase_raw_preapply_manifests,
        )
    source_states: dict[str, tuple[str, str]] = {}
    row_by_command_id: dict[str, Mapping[str, Any]] = {}
    observations: list[str] = []
    receipt_artifact_ids: dict[str, dict[str, str]] = {}
    for position, row in enumerate(rows, 1):
        required = {
            "command_id", "argv", "argv_sha256", "exit_code", "result_path", "result_sha256",
            "source_state_path", "receipt_artifacts_path", "start_sequence", "end_sequence", "phase", "timestamp",
        }
        if type(row) is not dict or set(row) != required:
            raise RunnerError("invalid shim capture index row")
        command_id = row["command_id"]
        if (type(command_id) is not str or not command_id or command_id in observations
                or type(row["argv"]) is not list or any(type(item) is not str for item in row["argv"])
                or _sha256(_canonical_json(row["argv"])) != row["argv_sha256"]
                or type(row["exit_code"]) is not int or type(row["timestamp"]) is not str
                or type(row["start_sequence"]) is not int or type(row["end_sequence"]) is not int
                or row["start_sequence"] <= 0 or row["end_sequence"] < row["start_sequence"]
                or row["phase"] != phase):
            raise RunnerError("invalid shim capture observation")
        command_row = command_rows[position - 1]
        expected_command_log = {
            "argv": row["argv"], "exit_code": row["exit_code"],
            "result_sha256": row["result_sha256"], "timestamp": row["timestamp"],
        }
        if type(command_row) is not dict or command_row != expected_command_log:
            raise RunnerError("shim command log/index mismatch")
        result_raw = _read_control_capture(
            control_root, row["result_path"], control_pin=control_pin,
        )
        if _sha256(result_raw) != row["result_sha256"]:
            raise RunnerError("shim result capture digest mismatch")
        result_id = command_id + "-result"
        writer.add_bytes(result_id, "command_result", result_raw)

        source_state_id: str | None = None
        state_path = row["source_state_path"]
        if state_path is not None:
            state_raw = _read_control_capture(
                control_root, state_path, control_pin=control_pin,
            )
            state = _strict_json(state_raw, label="shim source state")
            expected_state = {
                "schema_version", "command_id", "command", "capture_point", "result_id", "corpus_revision",
                "records", "files", "pending",
            }
            if (type(state) is not dict or set(state) != expected_state or state.get("schema_version") != 1
                    or state.get("command_id") != command_id or state.get("capture_point") != "after_command_before_return"
                    or type(state.get("records")) is not list or type(state.get("files")) is not list):
                raise RunnerError("invalid shim source state")
            converted_records: list[dict[str, str]] = []
            converted_files: list[dict[str, str]] = []
            for number, entry in enumerate(state["records"], 1):
                logical, raw = _capture_bytes(
                    control_root, entry, label="source record", control_pin=control_pin,
                )
                artifact_id = f"{command_id}-record-{number}"
                writer.add_bytes(artifact_id, "source_record", raw)
                converted_records.append({"path": logical, "artifact_id": artifact_id})
            for number, entry in enumerate(state["files"], 1):
                logical, raw = _capture_bytes(
                    control_root, entry, label="source file", control_pin=control_pin,
                )
                artifact_id = f"{command_id}-file-{number}"
                writer.add_bytes(artifact_id, "file_capture", raw)
                converted_files.append({"path": logical, "artifact_id": artifact_id})
            pending_id: str | None = None
            if state["pending"] is not None:
                _logical, raw = _capture_bytes(
                    control_root, state["pending"], label="pending sync result", control_pin=control_pin,
                )
                pending_id = command_id + "-pending"
                writer.add_bytes(pending_id, "pending_sync_result", raw)
            source_state_id = command_id + "-source-state"
            writer.add_json(source_state_id, "source_state", {
                "schema_version": 1, "run_id": run_id, "execution_id": execution_id,
                "command_id": command_id, "capture_point": "after_command_before_return",
                "result_id": state["result_id"], "corpus_revision": state["corpus_revision"],
                "records": converted_records, "files": converted_files, "pending_result_id": pending_id,
            })
            source_states[command_id] = (source_state_id, str(state_path))

        receipt_path = row["receipt_artifacts_path"]
        if receipt_path is not None:
            receipt_raw = _read_control_capture(
                control_root, receipt_path, control_pin=control_pin,
            )
            receipt = _strict_json(receipt_raw, label="shim receipt artifacts")
            expected_receipt = {"schema_version", "command_id", "capture_point", "result_id", "stream", "durable", "delivery"}
            if (type(receipt) is not dict or set(receipt) != expected_receipt or receipt.get("schema_version") != 1
                    or receipt.get("command_id") != command_id or receipt.get("capture_point") != "after_command_before_return"):
                raise RunnerError("invalid shim receipt artifacts")
            converted_receipt_artifacts: dict[str, str] = {}
            for label, artifact_type in (("stream", "sync_stream"), ("durable", "consumption_receipt"), ("delivery", "delivery")):
                entry = receipt[label]
                if entry is None:
                    continue
                _logical, raw = _capture_bytes(
                    control_root, entry, label=label, control_pin=control_pin,
                )
                artifact_id = writer.add_bytes(f"{command_id}-{label}", artifact_type, raw)
                converted_receipt_artifacts[label] = artifact_id
            receipt_artifact_ids[command_id] = converted_receipt_artifacts

        writer.add_json(command_id, "command_observation", {
            "run_id": run_id, "execution_id": execution_id, "argv": row["argv"],
            "exit_code": row["exit_code"], "result_id": result_id,
            "result_sha256": row["result_sha256"], "timestamp": row["timestamp"],
            "start_sequence": row["start_sequence"], "end_sequence": row["end_sequence"],
            "source_state_id": source_state_id,
        })
        observations.append(command_id)
        row_by_command_id[command_id] = row

    manifest_ids: dict[str, str] = {}
    if phase_raw_preapply_manifests:
        try:
            from brainlib.wiki_transaction import WikiManifest
        except ImportError as error:  # pragma: no cover - repository invariant
            raise RunnerError("wiki manifest codec unavailable") from error
        raw_manifest_rows = [
            _strict_json(line, label="runner preapply manifest capture")
            for line in phase_raw_preapply_manifests.splitlines()
        ]
        for raw_manifest in raw_manifest_rows:
            expected_manifest = {
                "command_id", "argv", "argv_sha256", "path", "capture_path", "sha256", "bytes",
            }
            if type(raw_manifest) is not dict or set(raw_manifest) != expected_manifest:
                raise RunnerError("invalid runner preapply manifest capture")
            command_id = raw_manifest["command_id"]
            source_row = row_by_command_id.get(command_id)
            argv = raw_manifest["argv"]
            if (type(command_id) is not str or command_id in manifest_ids
                    or type(argv) is not list or any(type(item) is not str for item in argv)
                    or _sha256(_canonical_json(argv)) != raw_manifest["argv_sha256"]
                    or source_row is None or source_row["argv"] != argv
                    or len(argv) != 6
                    or argv[:5] != ["./brain", "--json", "wiki", "apply", "--manifest"]
                    or raw_manifest["path"] != argv[-1]):
                raise RunnerError("preapply manifest command binding mismatch")
            logical, raw = _capture_bytes(
                control_root,
                {
                    "path": raw_manifest["path"],
                    "capture_path": raw_manifest["capture_path"],
                    "sha256": raw_manifest["sha256"],
                    "bytes": raw_manifest["bytes"],
                },
                label="preapply wiki manifest", control_pin=control_pin,
            )
            try:
                parsed = WikiManifest.from_json(raw.decode("utf-8"))
            except (UnicodeDecodeError, TypeError, ValueError) as error:
                raise RunnerError("invalid preapply wiki manifest") from error
            # Parsing alone is enough here: the public contract performs the
            # event-specific revision/approval/link-proof joins, while this
            # conversion establishes immutable pre-dispatch byte ownership.
            if parsed.to_dict() != _strict_json(raw, label="preapply wiki manifest"):
                raise RunnerError("preapply wiki manifest is not canonical")
            content_id = command_id + "-preapply-manifest"
            manifest_id = command_id + "-wiki-manifest"
            writer.add_bytes(content_id, "file_capture", raw)
            writer.add_json(manifest_id, "wiki_manifest", {
                "path": logical, "content_id": content_id, "sha256": _sha256(raw),
            })
            manifest_ids[command_id] = manifest_id

    converted_trace: list[dict[str, Any]] = []
    for record in trace.records():
        converted = dict(record)
        if converted["kind"] == "source_state":
            command_id = converted.get("command_id")
            source_state = source_states.get(command_id)
            if source_state is None or converted.get("capture_path") != source_state[1]:
                raise RunnerError("shared trace source-state capture mismatch")
            converted.pop("capture_path")
            converted["source_state_id"] = source_state[0]
        elif converted["kind"] == "native_record" and converted.get("transcript_id") != transcript_id:
            raise RunnerError("shared trace transcript mismatch")
        converted_trace.append(converted)
    validate_trace_records(converted_trace)
    trace_id = f"trace-{execution_id}"
    trace_value = {"schema_version": 1, "run_id": run_id, "execution_id": execution_id, "records": converted_trace}
    trace_sha256 = _sha256(_canonical_json(trace_value))
    writer.add_json(trace_id, "execution_trace", trace_value)
    if control_pin is not None:
        if type(control_pin) is PinnedDirectory:
            PinnedDirectory.verify(control_pin)
        else:
            control_pin.verify()
    return ShimCaptureConversion(
        tuple(observations), dict(manifest_ids), trace_id, trace_sha256,
        raw_index, raw_command_log, raw_preapply_manifests,
        receipt_artifact_ids=receipt_artifact_ids,
    )


@dataclass
class _PrivatePhaseOneDiagnosticWriter:
    """A descriptor-bound, disposable writer for phase-one diagnostic facts."""

    control_root: Path
    run_id: str
    stage_pin: PinnedDirectory
    run_root: Path = field(init=False)
    entries: list[dict[str, Any]] = field(default_factory=list)
    write_identities: dict[str, tuple[int, int, int, int, int, int, int, int]] = field(
        default_factory=dict,
    )

    def __post_init__(self) -> None:
        self.run_root = self.stage_pin.path
        if self.control_root != self.stage_pin.path.parent.parent.parent:
            # Stages live beneath <control>/runs/<run-id>; keep this accidental
            # convenience writer from becoming a general-purpose adapter.
            raise RunnerError("private diagnostic stage root is invalid")

    def add_bytes(
        self,
        artifact_id: str,
        artifact_type: str,
        raw: bytes,
        *,
        suffix: str = ".bin",
        fixed_name: str | None = None,
    ) -> str:
        if (type(artifact_id) is not str or not artifact_id or any(
                character not in "abcdefghijklmnopqrstuvwxyz0123456789._-"
                for character in artifact_id)
                or any(entry["id"] == artifact_id for entry in self.entries)
                or fixed_name is not None):
            raise RunnerError("invalid private diagnostic artifact")
        relative = artifact_id + suffix
        identity = PinnedDirectory.write_relative_exclusive(self.stage_pin, relative, raw)
        retained_raw, retained_identity = PinnedDirectory.snapshot_relative(self.stage_pin, relative)
        if (identity[-3] != len(raw) or retained_raw != raw
                or retained_identity != identity):
            raise RunnerError("private staged artifact changed after write")
        self.write_identities[relative] = identity
        self.entries.append({
            "id": artifact_id, "type": artifact_type, "relative_path": relative,
            "sha256": _sha256(raw), "bytes": len(raw),
        })
        return artifact_id

    def add_json(self, artifact_id: str, artifact_type: str, value: Any) -> str:
        return self.add_bytes(artifact_id, artifact_type, _canonical_json(value), suffix=".json")


@dataclass(frozen=True)
class _FrozenDiagnosticControlPin:
    """Expose only frozen raw bridges to the generic conversion mechanics."""

    pin: PinnedDirectory
    snapshots: Mapping[str, tuple[bytes, tuple[int, int, int, int, int, int, int, int]]]
    absent: frozenset[str]

    @property
    def path(self) -> Path:
        return self.pin.path

    def verify(self) -> None:
        PinnedDirectory.verify(self.pin)
        for relative, snapshot in self.snapshots.items():
            PinnedDirectory.reverify_snapshot(self.pin, relative, snapshot)
        for relative in self.absent:
            if not _pinned_control_capture_is_absent(self.pin, relative):
                raise RunnerError("frozen optional control artifact appeared")

    def read_relative(self, relative: str, *, maximum: int = _MAX_CAPTURE_BYTES) -> bytes:
        snapshot = self.snapshots.get(relative)
        if snapshot is None:
            return PinnedDirectory.read_relative(self.pin, relative, maximum=maximum)
        PinnedDirectory.reverify_snapshot(self.pin, relative, snapshot)
        return snapshot[0]


@dataclass(frozen=True)
class _FrozenDiagnosticTrace:
    """Keep generic conversion from rereading a mutable runner trace."""

    trace: ControlTraceWriter
    snapshot: tuple[bytes, tuple[int, int, int, int, int, int, int, int]]
    rows: tuple[dict[str, Any], ...]

    def records(self) -> list[dict[str, Any]]:
        PinnedDirectory.reverify_snapshot(  # type: ignore[arg-type]
            self.trace.control_pin, self.trace.path.name, self.snapshot,
        )
        return [dict(row) for row in self.rows]


def _frozen_phase_one_diagnostic_controls(
    prepared_phase: _RegisteredActualPreparedPhase,
) -> tuple[_FrozenDiagnosticControlPin, _FrozenDiagnosticTrace]:
    """Freeze the raw phase-one bridge before a private stage is allocated."""

    pin = prepared_phase.control_pin
    required = (
        "brain-shim-capture-index.jsonl",
        "brain-shim-command-log.jsonl",
        prepared_phase.trace.path.name,
    )
    snapshots = {relative: pin.snapshot_relative(relative) for relative in required}
    absent: set[str] = set()
    for optional in ("brain-shim-trace.jsonl", "runner-preapply-manifests.jsonl"):
        try:
            snapshots[optional] = pin.snapshot_relative(optional)
        except RunnerError:
            if not _pinned_control_capture_is_absent(pin, optional):
                raise
            absent.add(optional)
    raw_index = snapshots["brain-shim-capture-index.jsonl"][0]
    for line in raw_index.splitlines():
        try:
            row = _strict_json(line, label="registered actual raw capture index")
        except RunnerError:
            # Malformed JSON is conversion containment, not preflight parsing.
            continue
        if type(row) is not dict or type(row.get("phase")) is not str:
            raise RunnerError("registered actual raw capture phase is invalid")
        if row["phase"] != "approval":
            if row["phase"] in phase_plan(prepared_phase.authority.plan.scenario_id)[1:]:
                raise RunnerError("registered actual phase-two raw capture exists before receipt gate")
            raise RunnerError("registered actual raw capture phase is invalid")
    trace_rows = tuple(
        _strict_json(line, label="registered actual frozen trace")
        for line in snapshots[prepared_phase.trace.path.name][0].splitlines()
    )
    validate_trace_records(trace_rows)
    frozen_pin = _FrozenDiagnosticControlPin(pin, MappingProxyType(snapshots), frozenset(absent))
    frozen_trace = _FrozenDiagnosticTrace(
        prepared_phase.trace, snapshots[prepared_phase.trace.path.name], trace_rows,
    )
    frozen_pin.verify()
    return frozen_pin, frozen_trace


def _freeze_registered_actual_phase_one_raw_predecessors(
    frozen_controls: _FrozenDiagnosticControlPin,
    conversion: ShimCaptureConversion,
) -> _RegisteredActualPhaseOneRawPredecessors:
    """Retain phase-one raw journal identities beside conversion byte prefixes."""

    if (type(frozen_controls) is not _FrozenDiagnosticControlPin
            or type(conversion) is not ShimCaptureConversion):
        raise RunnerError("registered actual phase-one raw predecessors are invalid")
    frozen_controls.verify()
    conversion_raw = {
        "brain-shim-capture-index.jsonl": conversion.raw_index,
        "brain-shim-command-log.jsonl": conversion.raw_command_log,
        "runner-preapply-manifests.jsonl": conversion.raw_preapply_manifests,
    }
    values: dict[str, _PrivateRawFileBaseline | None] = {}
    for relative in _PHASE_ONE_RAW_PREDECESSOR_TARGETS:
        snapshot = frozen_controls.snapshots.get(relative)
        if snapshot is None:
            if (relative not in frozen_controls.absent
                    or (relative in conversion_raw
                        and conversion_raw[relative] != b"")):
                raise RunnerError("registered actual phase-one raw predecessor is incomplete")
            values[relative] = None
            continue
        raw, identity = snapshot
        if (type(raw) is not bytes
                or not _valid_regular_identity(identity)
                or identity[5] != len(raw)
                or not raw.endswith(b"\n")):
            raise RunnerError("registered actual phase-one raw predecessor changed")
        expected = conversion_raw.get(relative)
        if expected is not None and raw != expected:
            raise RunnerError("registered actual phase-one raw predecessor changed")
        values[relative] = _PrivateRawFileBaseline(
            relative, _sha256(raw), len(raw), identity, raw.count(b"\n"),
        )
    predecessors = _RegisteredActualPhaseOneRawPredecessors(values)
    predecessors.verify_current(frozen_controls.pin)
    return predecessors


@dataclass(frozen=True)
class _FrozenActualPhaseOneReceiptArtifacts:
    """A complete descriptor-pinned phase-one view for later receipt checks.

    The value deliberately retains copied entry descriptors and bytes rather
    than an ``EvidenceWriter`` reference.  A later phase-two boundary may
    verify each retained descriptor identity, but it cannot discover an
    artifact through a mutable writer list or fall back to a pathname read.
    """

    run_id: str
    control_pin: PinnedDirectory
    entries: Mapping[str, Mapping[str, Any]]
    snapshots: Mapping[
        str,
        tuple[bytes, tuple[int, int, int, int, int, int, int, int]],
    ]

    def __post_init__(self) -> None:
        if (type(self.run_id) is not str
                or len(self.run_id) != 64
                or any(character not in _SHA for character in self.run_id)
                or not isinstance(self.control_pin, PinnedDirectory)
                or not self.control_pin.private
                or not isinstance(self.entries, Mapping)
                or not isinstance(self.snapshots, Mapping)):
            raise RunnerError("frozen phase-one receipt artifacts are invalid")
        frozen_entries: dict[str, Mapping[str, Any]] = {}
        paths: set[str] = set()
        for artifact_id, entry in self.entries.items():
            if (type(artifact_id) is not str or not artifact_id
                    or not isinstance(entry, Mapping)
                    or set(entry) != {"id", "type", "relative_path", "sha256", "bytes"}
                    or entry.get("id") != artifact_id
                    or type(entry.get("type")) is not str or not entry["type"]
                    or type(entry.get("relative_path")) is not str
                    or type(entry.get("bytes")) is not int or entry["bytes"] < 0
                    or not _is_hex64(entry.get("sha256"))):
                raise RunnerError("frozen phase-one receipt artifacts are invalid")
            relative = entry["relative_path"]
            try:
                PinnedDirectory._relative_parts(relative)
            except RunnerError as error:
                raise RunnerError("frozen phase-one receipt artifacts are invalid") from error
            if relative in paths:
                raise RunnerError("frozen phase-one receipt artifacts are invalid")
            paths.add(relative)
            frozen_entries[artifact_id] = MappingProxyType(dict(entry))
        if not frozen_entries or set(self.snapshots) != set(frozen_entries):
            raise RunnerError("frozen phase-one receipt artifacts are invalid")
        frozen_snapshots: dict[
            str,
            tuple[bytes, tuple[int, int, int, int, int, int, int, int]],
        ] = {}
        for artifact_id, snapshot in self.snapshots.items():
            if (type(snapshot) is not tuple or len(snapshot) != 2
                    or type(snapshot[0]) is not bytes
                    or not _valid_regular_identity(snapshot[1])):
                raise RunnerError("frozen phase-one receipt artifacts are invalid")
            raw, identity = snapshot
            entry = frozen_entries[artifact_id]
            if (len(raw) != entry["bytes"]
                    or _sha256(raw) != entry["sha256"]
                    or identity[5] != len(raw)):
                raise RunnerError("frozen phase-one receipt artifacts are invalid")
            frozen_snapshots[artifact_id] = (raw, tuple(identity))
        object.__setattr__(self, "entries", MappingProxyType(frozen_entries))
        object.__setattr__(self, "snapshots", MappingProxyType(frozen_snapshots))

    def _relative(self, artifact_id: str) -> str:
        entry = self.entries.get(artifact_id)
        if entry is None:
            raise RunnerError("frozen phase-one receipt artifact is unknown")
        return PurePosixPath(
            "runs", self.run_id, str(entry["relative_path"]),
        ).as_posix()

    def verify(self) -> None:
        PinnedDirectory.verify(self.control_pin)
        for artifact_id, snapshot in self.snapshots.items():
            PinnedDirectory.reverify_snapshot(
                self.control_pin, self._relative(artifact_id), snapshot,
            )

    def read(self, artifact_id: str, artifact_type: str) -> bytes:
        if type(artifact_id) is not str or type(artifact_type) is not str:
            raise RunnerError("frozen phase-one receipt artifact type is invalid")
        entry = self.entries.get(artifact_id)
        if entry is None or entry["type"] != artifact_type:
            raise RunnerError("frozen phase-one receipt artifact is unavailable")
        snapshot = self.snapshots.get(artifact_id)
        if snapshot is None:  # defensive: __post_init__ closes this mapping.
            raise RunnerError("frozen phase-one receipt artifact is unavailable")
        PinnedDirectory.reverify_snapshot(
            self.control_pin, self._relative(artifact_id), snapshot,
        )
        return snapshot[0]

    def __reduce__(self) -> object:
        raise TypeError("frozen phase-one receipt artifacts are not serializable")


def _freeze_registered_actual_phase_one_receipt_artifacts(
    prepared_phase: _RegisteredActualPreparedPhase,
) -> _FrozenActualPhaseOneReceiptArtifacts:
    """Freeze the complete adopted phase-one graph before phase-two setup."""

    if type(prepared_phase) is not _RegisteredActualPreparedPhase:
        raise RunnerError("frozen phase-one receipt inputs are invalid")
    writer = prepared_phase.writer
    control_pin = prepared_phase.control_pin
    if (type(writer) is not EvidenceWriter
            or not isinstance(control_pin, PinnedDirectory)
            or not control_pin.private
            or writer.control_root != control_pin.path
            or writer.run_root != control_pin.path / "runs" / writer.run_id):
        raise RunnerError("frozen phase-one receipt inputs are invalid")
    _require_unique_writer_entry_ids(writer)
    entries: dict[str, Mapping[str, Any]] = {}
    paths: set[str] = set()
    snapshots: dict[
        str,
        tuple[bytes, tuple[int, int, int, int, int, int, int, int]],
    ] = {}
    for source in writer.entries:
        if (type(source) is not dict
                or set(source) != {"id", "type", "relative_path", "sha256", "bytes"}
                or type(source.get("id")) is not str
                or source["id"] in entries
                or type(source.get("relative_path")) is not str):
            raise RunnerError("frozen phase-one receipt graph is invalid")
        artifact_id = source["id"]
        relative = source["relative_path"]
        try:
            PinnedDirectory._relative_parts(relative)
        except RunnerError as error:
            raise RunnerError("frozen phase-one receipt graph is invalid") from error
        if relative in paths:
            raise RunnerError("frozen phase-one receipt graph is invalid")
        identity = writer.write_identities.get(relative)
        if identity is None or not _valid_regular_identity(identity):
            raise RunnerError("frozen phase-one receipt graph is invalid")
        raw, observed = PinnedDirectory.snapshot_relative(
            control_pin,
            PurePosixPath("runs", writer.run_id, relative).as_posix(),
        )
        if (observed != identity
                or len(raw) != source.get("bytes")
                or _sha256(raw) != source.get("sha256")):
            raise RunnerError("frozen phase-one receipt graph changed")
        entries[artifact_id] = MappingProxyType(dict(source))
        snapshots[artifact_id] = (raw, observed)
        paths.add(relative)
    frozen = _FrozenActualPhaseOneReceiptArtifacts(
        writer.run_id,
        control_pin,
        MappingProxyType(entries),
        MappingProxyType(snapshots),
    )
    frozen.verify()
    return frozen


@dataclass(frozen=True)
class _RegisteredActualPhaseOneDiagnostic:
    """Private, non-authoritative host facts indexed after actual phase one.

    This is deliberately narrower than a receipt gate: it retains only the
    sealed launch, transcript, conversion, policy, and process join that a
    later reviewed route may re-read.  It neither interprets transcript
    markers nor grants web/phase-two/pass authority.
    """

    prepared_phase: _RegisteredActualPreparedPhase
    live_phase: RegisteredLivePhase
    normalized: NativeNormalization
    conversion: ShimCaptureConversion
    raw_predecessors: _RegisteredActualPhaseOneRawPredecessors
    receipt_artifacts: _FrozenActualPhaseOneReceiptArtifacts
    policy_id: str
    process_id: str
    transcript_id: str
    stderr_id: str
    trace_id: str
    trace_sha256: str

    def __post_init__(self) -> None:
        expected = {
            "policy_id": "policy-1",
            "process_id": "process-1",
            "transcript_id": "transcript-1",
            "stderr_id": "stderr-1",
            "trace_id": "trace-execution-1",
        }
        values = {
            "policy_id": self.policy_id,
            "process_id": self.process_id,
            "transcript_id": self.transcript_id,
            "stderr_id": self.stderr_id,
            "trace_id": self.trace_id,
        }
        if (type(self.prepared_phase) is not _RegisteredActualPreparedPhase
                or type(self.live_phase) is not RegisteredLivePhase
                or type(self.normalized) is not NativeNormalization
                or type(self.conversion) is not ShimCaptureConversion
                or type(self.raw_predecessors) is not _RegisteredActualPhaseOneRawPredecessors
                or type(self.receipt_artifacts) is not _FrozenActualPhaseOneReceiptArtifacts
                or self.prepared_phase.execution_id != "execution-1"
                or self.prepared_phase.phase_index != 1
                or self.prepared_phase.phase != "approval"
                or self.live_phase.control_pin is not self.prepared_phase.control_pin
                or self.live_phase.workspace_pin is not self.prepared_phase.workspace_pin
                or self.receipt_artifacts.run_id != self.prepared_phase.writer.run_id
                or self.receipt_artifacts.control_pin is not self.prepared_phase.control_pin
                or values != expected
                or type(self.trace_sha256) is not str
                or len(self.trace_sha256) != 64
                or any(character not in _SHA for character in self.trace_sha256)
                or self.trace_id != self.conversion.trace_id
                or self.trace_sha256 != self.conversion.trace_sha256
                or self.normalized.complete is not True
                or self.normalized.reason is not None
                or not isinstance(self.normalized.records, Mapping)
                or len(self.conversion.observation_ids) != 4):
            raise RunnerError("registered actual phase-one diagnostic is invalid")
        self.raw_predecessors.__post_init__()
        self.receipt_artifacts.verify()

    def __reduce__(self) -> object:
        raise TypeError("registered actual phase-one diagnostic is not serializable")


def _freeze_diagnostic_normalization(
    normalized: NativeNormalization,
) -> NativeNormalization:
    """Retain parser output without returning a mutable record mapping."""

    if type(normalized) is not NativeNormalization:
        raise RunnerError("registered actual native normalization is invalid")
    records: dict[int, Mapping[str, Any]] = {}
    for offset, record in normalized.records.items():
        if type(offset) is not int or offset < 0 or not isinstance(record, Mapping):
            raise RunnerError("registered actual native normalization is invalid")
        frozen = _freeze_private_trace_value(record)
        if not isinstance(frozen, Mapping):  # defensive type boundary
            raise RunnerError("registered actual native normalization is invalid")
        records[offset] = frozen
    return NativeNormalization(
        normalized.complete,
        normalized.reason,
        MappingProxyType(records),  # type: ignore[arg-type]
    )


def _pinned_control_directory_identity(
    control_pin: PinnedDirectory,
    relative: str,
) -> tuple[int, int, int, int, int, int, int, int]:
    """Read one private directory identity through its retained root fd."""

    if not isinstance(control_pin, PinnedDirectory):
        raise RunnerError("registered actual control directory pin is invalid")
    PinnedDirectory.verify(control_pin)
    parts = PinnedDirectory._relative_parts(relative)
    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    directory = os.dup(control_pin.root_fd)
    try:
        for part in parts:
            before = os.stat(part, dir_fd=directory, follow_symlinks=False)
            if stat.S_ISLNK(before.st_mode) or not stat.S_ISDIR(before.st_mode):
                raise RunnerError("registered actual control directory is unsafe")
            child = os.open(part, flags, dir_fd=directory)
            try:
                opened = os.fstat(child)
                after = os.stat(part, dir_fd=directory, follow_symlinks=False)
                expected = (before.st_dev, before.st_ino, before.st_mode, before.st_uid)
                if ((opened.st_dev, opened.st_ino, opened.st_mode, opened.st_uid) != expected
                        or (after.st_dev, after.st_ino, after.st_mode, after.st_uid)
                        != expected):
                    raise RunnerError("registered actual control directory changed while opened")
            except BaseException:
                os.close(child)
                raise
            os.close(directory)
            directory = child
        identity = PinnedDirectory._regular_identity(os.fstat(directory))
        if not stat.S_ISDIR(identity[2]):
            raise RunnerError("registered actual control directory is unsafe")
        return identity
    except OSError as error:
        raise RunnerError("registered actual control directory is unavailable") from error
    finally:
        os.close(directory)
        PinnedDirectory.verify(control_pin)


def _pinned_control_tree_inventory(
    control_pin: PinnedDirectory,
    relative_root: str,
) -> tuple[frozenset[str], frozenset[str]]:
    """List one private control subtree through the retained root descriptor.

    The diagnostic preflight needs to distinguish the writer's sealed setup
    files from an orphaned output left by a failed/foreign attempt.  Pathname
    walking would reintroduce the replacement gap that the retained control
    descriptor exists to close, so inspect every directory and file through
    descriptor-relative no-follow opens instead.
    """

    if not isinstance(control_pin, PinnedDirectory):
        raise RunnerError("registered actual phase-one control pin is invalid")
    PinnedDirectory.verify(control_pin)
    parts = PinnedDirectory._relative_parts(relative_root)
    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    file_flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)

    def directory_identity(info: os.stat_result) -> tuple[int, int, int, int]:
        return info.st_dev, info.st_ino, info.st_mode, info.st_uid

    directory = os.dup(control_pin.root_fd)
    directories: set[str] = set()
    files: set[str] = set()
    try:
        for part in parts:
            named = os.stat(part, dir_fd=directory, follow_symlinks=False)
            if stat.S_ISLNK(named.st_mode) or not stat.S_ISDIR(named.st_mode):
                raise RunnerError("registered actual phase-one evidence tree is unsafe")
            child = os.open(part, directory_flags, dir_fd=directory)
            try:
                opened = os.fstat(child)
                after = os.stat(part, dir_fd=directory, follow_symlinks=False)
                expected = directory_identity(named)
                if directory_identity(opened) != expected or directory_identity(after) != expected:
                    raise RunnerError("registered actual phase-one evidence tree changed while opened")
            except BaseException:
                os.close(child)
                raise
            os.close(directory)
            directory = child

        def descend(parent_fd: int, prefix: str) -> None:
            for name in sorted(os.listdir(parent_fd)):
                named = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                relative = name if not prefix else prefix + "/" + name
                if stat.S_ISDIR(named.st_mode):
                    child = os.open(name, directory_flags, dir_fd=parent_fd)
                    try:
                        opened = os.fstat(child)
                        after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                        expected = directory_identity(named)
                        if directory_identity(opened) != expected or directory_identity(after) != expected:
                            raise RunnerError(
                                "registered actual phase-one evidence tree changed while opened"
                            )
                        directories.add(relative)
                        descend(child, relative)
                    finally:
                        os.close(child)
                elif stat.S_ISREG(named.st_mode):
                    if named.st_nlink != 1:
                        raise RunnerError("registered actual phase-one evidence tree is unsafe")
                    file_fd = os.open(name, file_flags, dir_fd=parent_fd)
                    try:
                        opened = os.fstat(file_fd)
                        after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                        expected = PinnedDirectory._regular_identity(named)
                        if (PinnedDirectory._regular_identity(opened) != expected
                                or PinnedDirectory._regular_identity(after) != expected):
                            raise RunnerError(
                                "registered actual phase-one evidence tree changed while opened"
                            )
                        files.add(relative)
                    finally:
                        os.close(file_fd)
                else:
                    raise RunnerError("registered actual phase-one evidence tree is unsafe")

        descend(directory, "")
    except OSError as error:
        raise RunnerError("registered actual phase-one evidence tree is unavailable") from error
    finally:
        os.close(directory)
    PinnedDirectory.verify(control_pin)
    return frozenset(directories), frozenset(files)


def _registered_actual_phase_one_setup_inventory(
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
    trace_rows: Sequence[Mapping[str, Any]],
    *,
    stage: _PrivatePhaseOneDiagnosticWriter | None = None,
) -> None:
    """Require exactly the sealed phase-one setup graph before diagnostic writes.

    This is intentionally descriptor/graph based: legitimate setup artifacts
    are derived from the pinned phase, live result, and trace-owned snapshots,
    not from a hand-maintained list of possible stale output filenames.
    """

    writer = prepared_phase.writer
    control_pin = prepared_phase.control_pin
    expected: dict[str, str] = {}

    def expect(artifact_id: object, artifact_type: str) -> None:
        if type(artifact_id) is not str or not artifact_id:
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        prior = expected.setdefault(artifact_id, artifact_type)
        if prior != artifact_type:
            raise RunnerError("registered actual phase-one evidence inventory is invalid")

    expect(prepared_phase.phase_prompt.artifact_id, "phase_prompt")
    if prepared_phase.mcp_config is None:
        raise RunnerError("registered actual phase-one evidence inventory is invalid")
    expect("mcp-1", "mcp_config")
    expect(live_phase.version_id, "version")
    expect(live_phase.help_id, "help")
    expect(live_phase.executable_id, "client_executable")

    def collect_snapshot(snapshot: WorkspaceSnapshot, *, initial: bool) -> None:
        loaded = _indexed_workspace_snapshot(writer, snapshot)
        if (loaded.execution_id != "execution-1"
                or (initial and (loaded.role != "initial" or loaded.trace_sequence != 0))
                or (not initial and loaded.role != "marker")):
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        expect(loaded.artifact_id, "workspace_snapshot")
        for item in loaded.inventory:
            expect(item.get("content_id"), "file_capture")

    initial_id = _workspace_snapshot_artifact_id("execution-1", "initial", 0)
    if prepared_phase.initial_workspace_snapshot.artifact_id != initial_id:
        raise RunnerError("registered actual phase-one evidence inventory is invalid")
    collect_snapshot(prepared_phase.initial_workspace_snapshot, initial=True)

    trace_snapshots = {
        str(row["workspace_snapshot_id"]): row
        for row in trace_rows
        if row.get("kind") == "native_record"
    }
    marker_snapshot_ids = [snapshot.artifact_id for snapshot in prepared_phase.marker_workspace_snapshots]
    if (len(trace_snapshots) != len(marker_snapshot_ids)
            or set(marker_snapshot_ids) != set(trace_snapshots)):
        raise RunnerError("registered actual phase-one evidence inventory is invalid")
    for snapshot_id, row in trace_snapshots.items():
        loaded = _indexed_trace_workspace_snapshot(
            writer, execution_id="execution-1", native_row=row,
        )
        if loaded.artifact_id != snapshot_id:
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        collect_snapshot(loaded, initial=False)

    suffixes = {
        "phase_prompt": ".txt",
        "mcp_config": ".json",
        "workspace_snapshot": ".json",
        "version": ".bin",
        "help": ".bin",
        "client_executable": ".json",
        "file_capture": ".bin",
    }
    observed: dict[str, str] = {}
    paths: set[str] = set()
    for entry in writer.entries:
        if type(entry) is not dict or set(entry) != {
            "id", "type", "relative_path", "sha256", "bytes",
        }:
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        artifact_id = entry["id"]
        artifact_type = entry["type"]
        relative = entry["relative_path"]
        if (type(artifact_id) is not str or type(artifact_type) is not str
                or artifact_type not in suffixes or type(relative) is not str
                or not _is_hex64(entry["sha256"])
                or type(entry["bytes"]) is not int or entry["bytes"] < 0):
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        path = PurePosixPath(relative)
        expected_relative = PurePosixPath("artifacts", artifact_id + suffixes[artifact_type])
        if (path != expected_relative or path.as_posix() != relative
                or artifact_id in observed or relative in paths):
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        raw = PinnedDirectory.read_relative(
            control_pin,
            PurePosixPath("runs", writer.run_id, relative).as_posix(),
        )
        if len(raw) != entry["bytes"] or _sha256(raw) != entry["sha256"]:
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        observed[artifact_id] = artifact_type
        paths.add(relative)
    if observed != expected:
        raise RunnerError("registered actual phase-one evidence inventory is invalid")

    expected_directories = {
        parent.as_posix()
        for relative in paths
        for parent in PurePosixPath(relative).parents
        if parent != PurePosixPath(".")
    }
    directories, files = _pinned_control_tree_inventory(
        control_pin, PurePosixPath("runs", writer.run_id).as_posix(),
    )
    directories = set(directories)
    files = set(files)
    expected_files = set(paths)
    if stage is not None:
        if stage.control_root != writer.control_root or stage.run_id != writer.run_id:
            raise RunnerError("registered actual phase-one diagnostic stage is invalid")
        stage_tree = stage.stage_pin.snapshot_tree()
        stage_paths = {entry["relative_path"] for entry in stage.entries}
        if (set(stage_tree) != stage_paths
                or set(stage.write_identities) != stage_paths
                or any(stage_tree.get(relative) != stage.write_identities.get(relative)
                       for relative in stage_paths)
                or any(type(relative) is not str for relative in stage_paths)):
            raise RunnerError("registered actual phase-one diagnostic stage is invalid")
        stage_name = stage.stage_pin.path.name
        expected_directories.add(stage_name)
        expected_files.update(stage_name + "/" + relative for relative in stage_paths)
    if directories != expected_directories or files != expected_files:
        raise RunnerError("registered actual phase-one output collision")

    future_phases = frozenset(phase_plan(prepared_phase.authority.plan.scenario_id)[1:])
    raw_index = _read_control_capture(
        writer.control_root, "brain-shim-capture-index.jsonl", control_pin=control_pin,
    )
    for line in raw_index.splitlines():
        try:
            row = _strict_json(line, label="registered actual raw capture index")
        except RunnerError:
            # Conversion owns malformed-capture containment.  Only a valid
            # future-phase declaration is an ordering violation at this stage.
            continue
        if type(row) is dict and row.get("phase") in future_phases:
            raise RunnerError("registered actual phase-two raw capture exists before receipt gate")


def _registered_actual_phase_one_has_no_public_or_web_artifacts(
    writer: EvidenceWriter,
    *,
    control_pin: PinnedDirectory,
) -> None:
    """Keep this disconnected indexer before every semantic/public boundary."""

    prohibited_types = {
        "marker", "event_record", "interpretation_decision", "approval",
        "fixture_capability", "run_manifest", "assertion",
    }
    forbidden_ids = {
        "policy-1", "process-1", "transcript-1", "stderr-1", "trace-execution-1",
    }
    phase_indexed_prefixes = (
        "policy-", "process-", "transcript-", "stderr-", "phase-prompt-", "mcp-",
        "version-", "help-", "client-executable-", "trace-execution-",
        "raw-capture-index-execution-", "raw-command-log-execution-",
        "raw-preapply-manifests-execution-", "workspace-snapshot-execution-",
    )

    def future_phase_artifact(artifact_id: object) -> bool:
        if type(artifact_id) is not str:
            return False
        for prefix in phase_indexed_prefixes:
            if artifact_id.startswith(prefix):
                suffix = artifact_id.removeprefix(prefix).split("-", 1)[0]
                return suffix.isdecimal() and int(suffix) > 1
        return False

    PinnedDirectory.verify(control_pin)
    try:
        trace_names = [name for name in os.listdir(control_pin.root_fd) if name.startswith("runner-trace-")]
    except OSError as error:
        raise RunnerError("registered actual runner trace state is unavailable") from error
    if set(trace_names) != {"runner-trace-execution-1.jsonl"}:
        raise RunnerError("registered actual phase-two or foreign runner trace namespace is invalid")
    if any(future_phase_artifact(entry.get("id")) for entry in writer.entries):
        raise RunnerError("registered actual phase-two evidence exists before receipt gate")
    if (any(entry.get("type") in prohibited_types for entry in writer.entries)
            or any(entry.get("id") in forbidden_ids for entry in writer.entries)
            or any(
                entry.get("type") == "workspace_snapshot"
                and "-final-" in str(entry.get("id"))
                for entry in writer.entries
            )
            or any((writer.run_root / name).exists() for name in (
                "run-manifest.json", "evidence-index.json", "log-attestation.json", "event-log.json",
            ))):
        raise RunnerError("registered actual phase-one diagnostic is no longer disconnected")


def _index_registered_actual_phase_one_diagnostic(
    prepared_phase: _RegisteredActualPreparedPhase,
    live_phase: RegisteredLivePhase,
) -> _RegisteredActualPhaseOneDiagnostic:
    """Index only sealed phase-one host evidence after a registered launch.

    This is the final private indexing step of the enabled closed Claude/web
    phase-one bridge.  It has no phase-two, web-capability,
    semantic-overlay/replay, receipt-gate, final-workspace, finalization, or
    pass-publication path.
    """

    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(live_phase) is not RegisteredLivePhase):
        raise RunnerError("registered actual phase-one diagnostic inputs are invalid")
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot index actual phase evidence")

    # Re-establish every setup/plan/root closure before the first evidence
    # addition.  A detached phase or stale live result may never acquire an
    # indexing side effect merely because it resembles the phase-one shape.
    prepared_phase.__post_init__()
    prepared_run = prepared_phase.prepared_run
    authority = prepared_phase.authority
    plan = authority.plan
    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or type(authority) is not _RegisteredActualAuthority
            or type(plan) is not RegisteredActualScenarioPlan
            or type(prepared_run.prepared) is not PreparedWorkspace
            or type(prepared_run.writer) is not EvidenceWriter
            or type(prepared_run.run_id) is not str
            or len(prepared_run.run_id) != 64
            or any(character not in _SHA for character in prepared_run.run_id)
            or prepared_run.authority is not authority
            or prepared_run.writer is not prepared_phase.writer
            or prepared_run.prepared.control_root == prepared_run.prepared.workspace
            or prepared_run.prepared.control_root.is_relative_to(prepared_run.prepared.workspace)
            or prepared_run.prepared.workspace.is_relative_to(prepared_run.prepared.control_root)
            or prepared_run.prepared.control_root.parent != prepared_run.prepared.run_root
            or prepared_run.prepared.workspace.parent != prepared_run.prepared.run_root
            or prepared_run.prepared.workspace != prepared_phase.workspace
            or prepared_run.prepared.control_pin is not prepared_phase.control_pin
            or prepared_run.prepared.workspace_pin is not prepared_phase.workspace_pin
            or prepared_phase.writer.run_id != prepared_run.run_id
            or prepared_phase.writer.control_root != prepared_run.prepared.control_root
            or prepared_phase.writer.run_root != (
                prepared_run.prepared.control_root / "runs" / prepared_run.run_id
            )
            or prepared_phase.trusted_context is not None):
        raise RunnerError("registered actual phase-one diagnostic binding is invalid")
    entry_ids: list[str] = []
    for entry in prepared_phase.writer.entries:
        if type(entry) is not dict or type(entry.get("id")) is not str or not entry["id"]:
            raise RunnerError("registered actual phase-one evidence inventory is invalid")
        entry_ids.append(entry["id"])
    if len(set(entry_ids)) != len(entry_ids):
        raise RunnerError("registered actual phase-one evidence inventory is ambiguous")
    registration = _runner_owned_registration(plan.client)
    symbolic_template, network_attestation = _runner_owned_symbolic_profile(plan.client)
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    phases = phase_plan(plan.scenario_id)
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or plan.registration is not registration
            or plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or metadata.scenario_id != plan.scenario_id
            or prepared_phase.execution_id != "execution-1"
            or prepared_phase.phase_index != 1
            or prepared_phase.phase != phases[0]
            or prepared_phase.phase != "approval"
            or len(phases) != 2
            or not prepared_phase.control_pin.private
            or prepared_phase.workspace_pin.private
            or prepared_phase.workspace != prepared_phase.workspace_pin.path
            or prepared_phase.writer.control_root != prepared_phase.control_pin.path
            or prepared_phase.trace.control_root != prepared_phase.control_pin.path
            or prepared_phase.trace.control_pin is not prepared_phase.control_pin
            or prepared_phase.trace.path != (
                prepared_phase.control_pin.path / "runner-trace-execution-1.jsonl"
            )
            or prepared_phase.trace.lock_path != prepared_phase.control_pin.path / ".runner-trace.lock"
            or prepared_phase.transcript_id != "transcript-1"):
        raise RunnerError("registered actual phase-one diagnostic binding is invalid")
    _verify_registered_phase_roots(
        writer=prepared_phase.writer,
        workspace=prepared_phase.workspace,
        control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin,
        trace=prepared_phase.trace,
    )
    verify_wrapper(prepared_run.prepared.wrapper_seal)
    _verify_registered_actual_phase_control(prepared_phase, scenario=scenario)

    prompt = prepared_phase.phase_prompt
    expected_prompt = _canonical_phase_prompt(scenario, prepared_phase.phase)
    prompt_entry = _writer_entry_map(prepared_phase.writer).get("phase-prompt-1")
    if (prompt.artifact_id != "phase-prompt-1"
            or prompt.raw != expected_prompt
            or prompt.sha256 != _sha256(expected_prompt)
            or prompt.transport != _phase_prompt_transport(plan.client)
            or not isinstance(prompt_entry, Mapping)
            or prompt_entry.get("type") != "phase_prompt"
            or prompt_entry.get("sha256") != prompt.sha256
            or prompt_entry.get("bytes") != len(prompt.raw)
            or prompt.seal.path != (
                prepared_phase.writer.run_root / str(prompt_entry.get("relative_path", ""))
            ).resolve()):
        raise RunnerError("registered actual phase-one prompt binding is invalid")
    _verify_phase_prompt(prompt)

    mcp_config = prepared_phase.mcp_config
    mcp_entry = _writer_entry_map(prepared_phase.writer).get("mcp-1")
    if (not isinstance(mcp_config, ControlFileSeal)
            or not isinstance(mcp_entry, Mapping)
            or mcp_entry.get("type") != "mcp_config"
            or mcp_entry.get("sha256") != _sha256(EMPTY_MCP_BYTES)
            or mcp_entry.get("bytes") != len(EMPTY_MCP_BYTES)
            or mcp_config.path != (
                prepared_phase.writer.run_root / str(mcp_entry.get("relative_path", ""))
            ).resolve()):
        raise RunnerError("registered actual phase-one MCP binding is invalid")
    verify_control_file(mcp_config)
    if _safe_read(mcp_config.path) != EMPTY_MCP_BYTES:
        raise RunnerError("registered actual phase-one MCP bytes changed")

    expected_state = {
        "schema_version": 1,
        "control_root": str(prepared_phase.writer.control_root),
        "workspace": str(prepared_phase.workspace),
        "run_id": prepared_phase.writer.run_id,
        "execution_id": "execution-1",
        "phase": "approval",
    }
    if prepared_phase.runner_state.path != prepared_phase.writer.control_root / "runner-state.json":
        raise RunnerError("registered actual phase-one runner state locator mismatch")
    verify_control_file(prepared_phase.runner_state)
    state_raw = _safe_read(prepared_phase.runner_state.path)
    state = _strict_json(state_raw, label="registered actual phase-one runner state")
    if (type(state) is not dict or state != expected_state or state_raw != _canonical_json(state)):
        raise RunnerError("registered actual phase-one runner state binding is invalid")

    if (live_phase.control_pin is not prepared_phase.control_pin
            or live_phase.workspace_pin is not prepared_phase.workspace_pin
            or type(live_phase.capture) is not ProcessCapture
            or live_phase.capture.stdout_chunks is not None
            or live_phase.capture.exit_code != 0
            or live_phase.executable_id != "client-executable-1"
            or live_phase.version_id != "version-1"
            or live_phase.help_id != "help-1"
            or live_phase.reported_version != registration.expected_version
            or live_phase.native_format != registration.native_format
            or not isinstance(live_phase.argv, tuple)
            or not live_phase.argv):
        raise RunnerError("registered actual phase-one live evidence is invalid")
    _registration, trusted = _registered_live_context_phase(
        client=plan.client,
        execution_id="execution-1",
        control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin,
        trusted_context=live_phase.trusted_context,
        expected_execution_ids=frozenset({"execution-1"}),
    )
    if _registration is not registration or trusted is not live_phase.trusted_executable:
        raise RunnerError("registered actual phase-one live context is invalid")
    expected_argv = build_effective_argv(
        plan.client,
        plan.symbolic_template,
        prepared_phase.workspace,
        mcp_config.path,
        prompt.raw.decode("utf-8", "strict"),
    )
    expected_argv[0] = str(_absolute_executable_path(os.fspath(registration.resolved_path)))
    if tuple(expected_argv) != live_phase.argv:
        raise RunnerError("registered actual phase-one argv is not sealed")
    observed_identity, observed_sha256 = _registered_executable_observation(trusted)
    if (dict(live_phase.launch_identity) != observed_identity
            or dict(live_phase.seal_identity) != observed_identity
            or live_phase.launch_sha256 != observed_sha256
            or live_phase.seal_sha256 != observed_sha256
            or live_phase.supported_build_id != trusted.supported_build_id
            or _version_text(live_phase.capture.version) != live_phase.reported_version
            or not live_phase.capture.help
            or _writer_artifact_bytes(prepared_phase.writer, "version-1", "version")
            != live_phase.capture.version
            or _writer_artifact_bytes(prepared_phase.writer, "help-1", "help")
            != live_phase.capture.help):
        raise RunnerError("registered actual phase-one executable evidence is invalid")

    normalized = normalize_native_transcript(
        client=plan.client,
        version=live_phase.reported_version,
        transcript=live_phase.capture.stdout,
    )
    if not normalized.complete:
        raise RunnerError("registered actual phase-one native transcript is unsupported")
    frozen_controls, frozen_trace = _frozen_phase_one_diagnostic_controls(prepared_phase)
    trace_rows = frozen_trace.records()
    if not trace_rows:
        raise RunnerError("registered actual phase-one shared trace is missing")
    validate_trace_records(trace_rows)
    _registered_actual_phase_one_has_no_public_or_web_artifacts(
        prepared_phase.writer, control_pin=prepared_phase.control_pin,
    )
    _registered_actual_phase_one_setup_inventory(prepared_phase, live_phase, trace_rows)

    # Repeat the closed route/root checks at the final write boundary.  A test
    # hook or root replacement introduced after validation cannot leave even
    # these diagnostic-only host artifacts behind.
    if _TEST_ONLY_REGISTERED_LIVE_LAUNCH is not None:
        raise RunnerError("test-only registered live adapter cannot index actual phase evidence")
    _verify_registered_phase_roots(
        writer=prepared_phase.writer,
        workspace=prepared_phase.workspace,
        control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin,
        trace=prepared_phase.trace,
    )
    verify_wrapper(prepared_run.prepared.wrapper_seal)
    _verify_registered_actual_phase_control(prepared_phase, scenario=scenario)
    _verify_phase_prompt(prompt)
    verify_control_file(prepared_phase.runner_state)
    verify_control_file(mcp_config)
    _registered_actual_phase_one_setup_inventory(prepared_phase, live_phase, trace_rows)
    frozen_controls.verify()
    run_pin = PinnedDirectory.pin(prepared_phase.writer.run_root, private=True)
    stage_pin = run_pin.create_private_child(".phase-one-diagnostic-")
    stage_writer = _PrivatePhaseOneDiagnosticWriter(
        prepared_phase.writer.control_root, prepared_phase.writer.run_id, stage_pin,
    )
    transcript_raw = live_phase.capture.stdout
    policy_id = stage_writer.add_json("policy-1", "policy", {
        "run_id": prepared_phase.writer.run_id,
        "execution_id": "execution-1",
        "phase": "approval",
        "client": plan.client,
        "profile": "claude-restricted-tool-surface-v1",
        "network_attestation": network_attestation,
        "argv": list(live_phase.argv),
        "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
        "version_id": live_phase.version_id,
        "help_id": live_phase.help_id,
        "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256,
        "fixture_capability_id": None,
        "approval": None,
        "phase_prompt_id": prompt.artifact_id,
        "phase_prompt_sha256": prompt.sha256,
        "phase_prompt_transport": prompt.transport,
        "executable_id": live_phase.executable_id,
        "mcp_config_id": "mcp-1",
        "mcp_config_sha256": mcp_config.sha256,
        "mcp_path": str(mcp_config.path),
        "mcp_identity": dict(mcp_config.identity),
    })
    transcript_id = stage_writer.add_bytes(
        "transcript-1", "transcript", transcript_raw,
    )
    stderr_id = stage_writer.add_bytes(
        "stderr-1", "file_capture", live_phase.capture.stderr,
    )
    conversion = convert_shim_captures(
        stage_writer,  # type: ignore[arg-type]
        control_root=prepared_phase.writer.control_root,
        run_id=prepared_phase.writer.run_id,
        execution_id="execution-1",
        phase="approval",
        transcript_id=transcript_id,
        trace=frozen_trace,  # type: ignore[arg-type]
        control_pin=frozen_controls,  # type: ignore[arg-type]
    )
    if len(conversion.observation_ids) != 4:
        raise RunnerError("registered actual phase-one conversion is incomplete")
    raw_predecessors = _freeze_registered_actual_phase_one_raw_predecessors(
        frozen_controls, conversion,
    )
    process_id = stage_writer.add_json("process-1", "process", {
        "run_id": prepared_phase.writer.run_id,
        "execution_id": "execution-1",
        "phase": "approval",
        "client": plan.client,
        "client_version": live_phase.reported_version,
        "argv": list(live_phase.argv),
        "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
        "exit_code": live_phase.capture.exit_code,
        "transcript_id": transcript_id,
        "transcript_sha256": _sha256(transcript_raw),
        "trace_id": conversion.trace_id,
        "trace_sha256": conversion.trace_sha256,
        "native_format": live_phase.native_format,
        "fixture_id": metadata.fixture_id,
        "fixture_sha256": metadata.fixture_sha256,
        "fixture_capability_id": None,
        "approval": None,
        "phase_prompt_id": prompt.artifact_id,
        "phase_prompt_sha256": prompt.sha256,
        "phase_prompt_transport": prompt.transport,
        "executable_id": live_phase.executable_id,
        "mcp_identity": dict(mcp_config.identity),
    })

    stage_snapshot = stage_pin.snapshot_tree()
    _verify_registered_phase_roots(
        writer=prepared_phase.writer,
        workspace=prepared_phase.workspace,
        control_pin=prepared_phase.control_pin,
        workspace_pin=prepared_phase.workspace_pin,
        trace=prepared_phase.trace,
    )
    _verify_registered_actual_phase_control(prepared_phase, scenario=scenario)
    _verify_phase_prompt(prompt)
    verify_control_file(prepared_phase.runner_state)
    verify_control_file(mcp_config)
    frozen_controls.verify()
    trace_rows = frozen_trace.records()
    _registered_actual_phase_one_has_no_public_or_web_artifacts(
        prepared_phase.writer, control_pin=prepared_phase.control_pin,
    )
    stage_pin.reverify_tree(stage_snapshot)
    _registered_actual_phase_one_setup_inventory(
        prepared_phase, live_phase, trace_rows, stage=stage_writer,
    )
    # Adoption is deliberately one in-memory step: no base artifact path is
    # written by this route, and every adopted entry remains beneath the
    # verified private stage directory.
    stage_name = stage_pin.path.name
    adopted = [
        {**entry, "relative_path": stage_name + "/" + entry["relative_path"]}
        for entry in stage_writer.entries
    ]
    if any(entry["id"] in {item["id"] for item in prepared_phase.writer.entries} for entry in adopted):
        raise RunnerError("registered actual phase-one diagnostic adoption is ambiguous")
    adopted_receipts = {
        stage_name + "/" + relative: identity
        for relative, identity in stage_writer.write_identities.items()
    }
    adopted_paths = {str(entry["relative_path"]) for entry in adopted}
    if (set(adopted_receipts) != adopted_paths
            or any(relative in prepared_phase.writer.write_identities
                   for relative in adopted_receipts)):
        raise RunnerError("registered actual phase-one diagnostic adoption is ambiguous")
    prepared_phase.writer.entries.extend(adopted)
    prepared_phase.writer.write_identities.update(adopted_receipts)
    run_pin.close()
    stage_pin.close()
    if not _registered_phase_evidence_is_bound(
        writer=prepared_phase.writer,
        workspace=prepared_phase.workspace,
        execution_id="execution-1",
        phase="approval",
        live_phase=live_phase,
    ):
        raise RunnerError("registered actual phase-one host evidence is not bound")
    if any(
        entry.get("type") in {
            "marker", "event_record", "interpretation_decision", "approval",
            "fixture_capability", "run_manifest", "assertion",
        }
        for entry in prepared_phase.writer.entries
    ):
        raise RunnerError("registered actual phase-one diagnostic crossed a semantic boundary")
    receipt_artifacts = _freeze_registered_actual_phase_one_receipt_artifacts(prepared_phase)
    return _RegisteredActualPhaseOneDiagnostic(
        prepared_phase=prepared_phase,
        live_phase=live_phase,
        normalized=_freeze_diagnostic_normalization(normalized),
        conversion=conversion,
        raw_predecessors=raw_predecessors,
        receipt_artifacts=receipt_artifacts,
        policy_id=policy_id,
        process_id=process_id,
        transcript_id=transcript_id,
        stderr_id=stderr_id,
        trace_id=conversion.trace_id,
        trace_sha256=conversion.trace_sha256,
    )


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoDiagnosticStage:
    """One retained descriptor-pinned phase-two diagnostic stage.

    Adoption only adds the stage rows to the in-memory base writer; it never
    moves the staged files.  This snapshot preserves the stage parent, root,
    every descriptor row, and the complete child tree so a later pure reader
    can reject a same-byte replacement after the transient stage pin closes.
    """

    run_id: str
    control_pin: PinnedDirectory
    stage_name: str
    run_root_identity: tuple[int, int, int, int, int, int, int, int]
    stage_identity: tuple[int, int, int, int, int, int, int, int]
    entries: Mapping[str, Mapping[str, Any]]
    tree: Mapping[str, tuple[int, int, int, int, int, int, int, int]]

    def __post_init__(self) -> None:
        if (type(self.run_id) is not str
                or len(self.run_id) != 64
                or any(character not in _SHA for character in self.run_id)
                or not isinstance(self.control_pin, PinnedDirectory)
                or not self.control_pin.private
                or type(self.stage_name) is not str
                or not self.stage_name.startswith(".phase-two-diagnostic-")
                or "/" in self.stage_name
                or type(self.run_root_identity) is not tuple
                or len(self.run_root_identity) != 8
                or any(type(item) is not int for item in self.run_root_identity)
                or not stat.S_ISDIR(self.run_root_identity[2])
                or type(self.stage_identity) is not tuple
                or len(self.stage_identity) != 8
                or any(type(item) is not int for item in self.stage_identity)
                or not stat.S_ISDIR(self.stage_identity[2])
                or not isinstance(self.entries, Mapping)
                or not isinstance(self.tree, Mapping)):
            raise RunnerError("registered actual phase-two diagnostic stage is invalid")
        try:
            PinnedDirectory._relative_parts(self.stage_name)
        except RunnerError as error:
            raise RunnerError("registered actual phase-two diagnostic stage is invalid") from error
        frozen_entries: dict[str, Mapping[str, Any]] = {}
        expected_files: set[str] = set()
        expected_directories: set[str] = set()
        for artifact_id, entry in self.entries.items():
            if (type(artifact_id) is not str or not artifact_id
                    or not isinstance(entry, Mapping)
                    or set(entry) != {"id", "type", "relative_path", "sha256", "bytes"}
                    or entry.get("id") != artifact_id
                    or type(entry.get("type")) is not str or not entry["type"]
                    or type(entry.get("relative_path")) is not str
                    or not _is_hex64(entry.get("sha256"))
                    or type(entry.get("bytes")) is not int or entry["bytes"] < 0):
                raise RunnerError("registered actual phase-two diagnostic stage is invalid")
            relative = entry["relative_path"]
            try:
                PinnedDirectory._relative_parts(relative)
            except RunnerError as error:
                raise RunnerError("registered actual phase-two diagnostic stage is invalid") from error
            if relative in expected_files:
                raise RunnerError("registered actual phase-two diagnostic stage is invalid")
            expected_files.add(relative)
            expected_directories.update(
                parent.as_posix() + "/"
                for parent in PurePosixPath(relative).parents
                if parent != PurePosixPath(".")
            )
            frozen_entries[artifact_id] = MappingProxyType(dict(entry))
        if not frozen_entries:
            raise RunnerError("registered actual phase-two diagnostic stage is invalid")
        frozen_tree: dict[str, tuple[int, int, int, int, int, int, int, int]] = {}
        files: set[str] = set()
        directories: set[str] = set()
        for relative, identity in self.tree.items():
            if (type(relative) is not str or type(identity) is not tuple
                    or len(identity) != 8 or any(type(item) is not int for item in identity)):
                raise RunnerError("registered actual phase-two diagnostic stage is invalid")
            if relative.endswith("/"):
                directory = relative[:-1]
                try:
                    PinnedDirectory._relative_parts(directory)
                except RunnerError as error:
                    raise RunnerError("registered actual phase-two diagnostic stage is invalid") from error
                if not stat.S_ISDIR(identity[2]) or relative in directories:
                    raise RunnerError("registered actual phase-two diagnostic stage is invalid")
                directories.add(relative)
            else:
                try:
                    PinnedDirectory._relative_parts(relative)
                except RunnerError as error:
                    raise RunnerError("registered actual phase-two diagnostic stage is invalid") from error
                if (not _valid_regular_identity(identity)
                        or relative in files):
                    raise RunnerError("registered actual phase-two diagnostic stage is invalid")
                files.add(relative)
            frozen_tree[relative] = tuple(identity)
        if files != expected_files or directories != expected_directories:
            raise RunnerError("registered actual phase-two diagnostic stage tree is invalid")
        for artifact_id, entry in frozen_entries.items():
            identity = frozen_tree.get(str(entry["relative_path"]))
            if identity is None or identity[5] != entry["bytes"]:
                raise RunnerError("registered actual phase-two diagnostic stage is invalid")
        object.__setattr__(self, "entries", MappingProxyType(frozen_entries))
        object.__setattr__(self, "tree", MappingProxyType(frozen_tree))

    def verify(self, *, allow_run_root_metadata_change: bool = False) -> None:
        """Re-read the stage through the original control pin after adoption.

        The specialized finalizer may add its three permitted root files.  It
        cannot change the run-root descriptor's stable device/inode/mode/UID
        identity, but filesystem implementations may also update its link
        count, size, and timestamps when files are added.  The separate
        descriptor-walked tree inventory below still rejects every unexpected
        directory or file; callers must opt into this narrow allowance.
        """

        self.__post_init__()
        if type(allow_run_root_metadata_change) is not bool:
            raise RunnerError("registered actual phase-two diagnostic stage verification is invalid")
        run_relative = PurePosixPath("runs", self.run_id).as_posix()
        stage_relative = PurePosixPath(run_relative, self.stage_name).as_posix()
        current_run_root = _pinned_control_directory_identity(self.control_pin, run_relative)
        if ((current_run_root[:4] != self.run_root_identity[:4]
             if allow_run_root_metadata_change else current_run_root != self.run_root_identity)
                or _pinned_control_directory_identity(self.control_pin, stage_relative)
                != self.stage_identity):
            raise RunnerError("registered actual phase-two diagnostic stage changed")
        for relative, identity in self.tree.items():
            if not relative.endswith("/"):
                continue
            directory_relative = PurePosixPath(stage_relative, relative[:-1]).as_posix()
            if _pinned_control_directory_identity(self.control_pin, directory_relative) != identity:
                raise RunnerError("registered actual phase-two diagnostic stage changed")
        expected_files: set[str] = set()
        for artifact_id, entry in self.entries.items():
            relative = str(entry["relative_path"])
            raw, identity = PinnedDirectory.snapshot_relative(
                self.control_pin,
                PurePosixPath(stage_relative, relative).as_posix(),
            )
            if (identity != self.tree.get(relative)
                    or len(raw) != entry["bytes"]
                    or _sha256(raw) != entry["sha256"]):
                raise RunnerError("registered actual phase-two diagnostic stage changed")
            expected_files.add(relative)
        directories, files = _pinned_control_tree_inventory(self.control_pin, stage_relative)
        if (set(files) != expected_files
                or {relative + "/" for relative in directories}
                != {relative for relative in self.tree if relative.endswith("/")}):
            raise RunnerError("registered actual phase-two diagnostic stage tree changed")
        PinnedDirectory.verify(self.control_pin)

    def __reduce__(self) -> object:
        raise TypeError("registered actual phase-two diagnostic stage is not serializable")


def _freeze_registered_actual_phase_two_diagnostic_stage(
    stage_writer: _PrivatePhaseOneDiagnosticWriter,
    stage_pin: PinnedDirectory,
    *,
    control_pin: PinnedDirectory,
    run_id: str,
    stage_tree: Mapping[str, tuple[int, int, int, int, int, int, int, int]],
) -> _RegisteredActualPhaseTwoDiagnosticStage:
    """Retain one exact staged graph before its rows are adopted in memory."""

    if (type(stage_writer) is not _PrivatePhaseOneDiagnosticWriter
            or not isinstance(stage_pin, PinnedDirectory)
            or not isinstance(control_pin, PinnedDirectory)
            or stage_writer.stage_pin is not stage_pin
            or stage_writer.control_root != control_pin.path
            or stage_writer.run_id != run_id
            or not isinstance(stage_tree, Mapping)):
        raise RunnerError("registered actual phase-two diagnostic stage is invalid")
    stage_name = stage_pin.path.name
    run_relative = PurePosixPath("runs", run_id).as_posix()
    stage_relative = PurePosixPath(run_relative, stage_name).as_posix()
    if (stage_pin.path != control_pin.path / stage_relative
            or stage_pin.edges[-1][1] != _pinned_control_directory_identity(
                control_pin, stage_relative,
            )[:4]):
        raise RunnerError("registered actual phase-two diagnostic stage changed")
    snapshot = _RegisteredActualPhaseTwoDiagnosticStage(
        run_id=run_id,
        control_pin=control_pin,
        stage_name=stage_name,
        run_root_identity=_pinned_control_directory_identity(control_pin, run_relative),
        stage_identity=_pinned_control_directory_identity(control_pin, stage_relative),
        entries=MappingProxyType({entry["id"]: dict(entry) for entry in stage_writer.entries}),
        tree=MappingProxyType(dict(stage_tree)),
    )
    snapshot.verify()
    return snapshot


@dataclass(frozen=True)
class _RegisteredActualPhaseTwoDiagnostic:
    """Private staged host facts converted from one frozen phase-two handoff.

    This is intentionally a diagnostic transaction result, not an eligibility
    object.  It carries no semantic plan, capability, approval, public pass
    claim, or aggregate trusted context for serialization.
    """

    phase_one_diagnostic: _RegisteredActualPhaseOneDiagnostic
    post_launch_token: _RegisteredActualPhaseTwoPostLaunchToken
    normalized: NativeNormalization
    conversion: ShimCaptureConversion
    stage_name: str
    stage_snapshot: _RegisteredActualPhaseTwoDiagnosticStage
    policy_id: str
    process_id: str
    transcript_id: str
    stderr_id: str
    trace_id: str
    trace_sha256: str

    def __post_init__(self) -> None:
        token = self.post_launch_token
        if type(token) is not _RegisteredActualPhaseTwoPostLaunchToken:
            raise RunnerError("registered actual phase-two diagnostic is invalid")
        try:
            token.__post_init__()
            token_control_pin, token_workspace_pin = _registered_actual_phase_two_live_roots(
                token.prepared_phase,
                token.live_phase,
            )
            phase_one_bridge = token.phase_one_bridge
        except RunnerError:
            raise
        except (AttributeError, TypeError, ValueError, OSError) as error:
            raise RunnerError("registered actual phase-two diagnostic is invalid") from error
        expected = {
            "policy_id": "policy-2",
            "process_id": "process-2",
            "transcript_id": "transcript-2",
            "stderr_id": "stderr-2",
            "trace_id": "trace-execution-2",
        }
        values = {
            "policy_id": self.policy_id,
            "process_id": self.process_id,
            "transcript_id": self.transcript_id,
            "stderr_id": self.stderr_id,
            "trace_id": self.trace_id,
        }
        if (type(self.phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
                or type(self.normalized) is not NativeNormalization
                or type(self.conversion) is not ShimCaptureConversion
                or values != expected
                or type(self.stage_name) is not str
                or not self.stage_name.startswith(".phase-two-diagnostic-")
                or "/" in self.stage_name
                or type(self.stage_snapshot) is not _RegisteredActualPhaseTwoDiagnosticStage
                or self.stage_snapshot.stage_name != self.stage_name
                or self.stage_snapshot.run_id != token.run_id
                or self.stage_snapshot.control_pin
                is not token_control_pin
                or token.prepared_phase.execution_id != "execution-2"
                or token.prepared_phase.phase != "approved_capture"
                or token.receipt_gate.execution_id != "execution-1"
                or self.phase_one_diagnostic.prepared_phase.prepared_run
                is not token.prepared_phase.prepared_run
                or phase_one_bridge.run_id != token.run_id
                or phase_one_bridge.live_phase.control_pin is not token_control_pin
                or phase_one_bridge.live_phase.workspace_pin is not token_workspace_pin
                or self.phase_one_diagnostic.policy_id != phase_one_bridge.policy_id
                or self.phase_one_diagnostic.process_id != phase_one_bridge.process_id
                or self.phase_one_diagnostic.transcript_id != phase_one_bridge.transcript_id
                or self.phase_one_diagnostic.stderr_id != phase_one_bridge.stderr_id
                or self.phase_one_diagnostic.trace_id != phase_one_bridge.trace_id
                or self.phase_one_diagnostic.trace_sha256 != phase_one_bridge.trace_sha256
                or self.trace_id != self.conversion.trace_id
                or self.trace_sha256 != self.conversion.trace_sha256
                or not _is_hex64(self.trace_sha256)
                or self.normalized.complete is not True
                or self.normalized.reason is not None
                or not self.conversion.observation_ids):
            raise RunnerError("registered actual phase-two diagnostic is invalid")
        self.stage_snapshot.verify()

    def __reduce__(self) -> object:
        raise TypeError("registered actual phase-two diagnostic is not serializable")


def _registered_actual_phase_two_stage_tree(
    stage_writer: _PrivatePhaseOneDiagnosticWriter,
    stage_pin: PinnedDirectory,
) -> Mapping[str, tuple[int, int, int, int, int, int, int, int]]:
    """Require one staged phase-two graph to be exact before adoption."""

    if (type(stage_writer) is not _PrivatePhaseOneDiagnosticWriter
            or not isinstance(stage_pin, PinnedDirectory)
            or stage_writer.stage_pin is not stage_pin):
        raise RunnerError("registered actual phase-two diagnostic stage is invalid")
    allowed_types = {
        "policy", "process", "transcript", "file_capture", "command_result",
        "source_record", "pending_sync_result", "source_state", "sync_stream",
        "consumption_receipt", "delivery", "command_observation", "wiki_manifest",
        "execution_trace",
    }
    entries: dict[str, Mapping[str, Any]] = {}
    expected_files: set[str] = set()
    for entry in stage_writer.entries:
        if (type(entry) is not dict or set(entry) != {
                    "id", "type", "relative_path", "sha256", "bytes",
                }
                or type(entry["id"]) is not str or not entry["id"]
                or type(entry["type"]) is not str or entry["type"] not in allowed_types
                or type(entry["relative_path"]) is not str
                or type(entry["bytes"]) is not int or entry["bytes"] < 0
                or not _is_hex64(entry["sha256"])
                or entry["id"] in entries):
            raise RunnerError("registered actual phase-two diagnostic stage is invalid")
        relative = entry["relative_path"]
        PinnedDirectory._relative_parts(relative)
        if relative in expected_files:
            raise RunnerError("registered actual phase-two diagnostic stage is invalid")
        identity = stage_writer.write_identities.get(relative)
        if identity is None:
            raise RunnerError("registered actual phase-two diagnostic stage is invalid")
        raw, observed = PinnedDirectory.snapshot_relative(stage_pin, relative)
        if (observed != identity
                or len(raw) != entry["bytes"]
                or _sha256(raw) != entry["sha256"]):
            raise RunnerError("registered actual phase-two diagnostic stage changed")
        entries[entry["id"]] = MappingProxyType(dict(entry))
        expected_files.add(relative)
    if not entries or set(stage_writer.write_identities) != expected_files:
        raise RunnerError("registered actual phase-two diagnostic stage is invalid")
    tree = PinnedDirectory.snapshot_tree(stage_pin)
    files = {relative for relative in tree if not relative.endswith("/")}
    directories = {relative for relative in tree if relative.endswith("/")}
    expected_directories = {
        parent.as_posix() + "/"
        for relative in expected_files
        for parent in PurePosixPath(relative).parents
        if parent != PurePosixPath(".")
    }
    if files != expected_files or directories != expected_directories:
        raise RunnerError("registered actual phase-two diagnostic stage has orphaned paths")
    PinnedDirectory.reverify_tree(stage_pin, tree)
    return tree


def _index_registered_actual_phase_two_host_diagnostic(
    phase_one_diagnostic: _RegisteredActualPhaseOneDiagnostic,
    provenance: _RegisteredActualPhaseTwoPostLaunchToken,
) -> _RegisteredActualPhaseTwoDiagnostic:
    """Stage one frozen phase-two host graph without public authority.

    The only mutable input surface accepted here is the retained private token.
    Raw conversion reads through its receipt-authenticated handoff facade;
    this function never launches, plans semantics, emits public evidence, or
    seals a log.
    """

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(provenance) is not _RegisteredActualPhaseTwoPostLaunchToken):
        raise RunnerError("registered actual phase-two diagnostic inputs are invalid")
    provenance.__post_init__()
    prepared_phase = provenance.prepared_phase
    live_phase = provenance.live_phase
    control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
        prepared_phase, live_phase,
    )
    phase_one_bridge = provenance.phase_one_bridge
    receipt_gate = provenance.receipt_gate
    prepared_run = prepared_phase.prepared_run
    writer = prepared_phase.writer
    handoff = provenance.raw_control_handoff
    if (type(prepared_run) is not _RegisteredActualPreparedRun
            or prepared_run.writer is not writer
                or prepared_phase.authority is not prepared_run.authority
                or control_pin.path != writer.control_root
                or phase_one_diagnostic.prepared_phase.prepared_run is not prepared_run
                or phase_one_diagnostic.live_phase.control_pin
                is not phase_one_diagnostic.prepared_phase.control_pin
                or phase_one_diagnostic.live_phase.workspace_pin
                is not phase_one_diagnostic.prepared_phase.workspace_pin
                or phase_one_bridge.run_id != provenance.run_id
                or phase_one_bridge.live_phase.control_pin is not control_pin
                or phase_one_bridge.live_phase.workspace_pin is not workspace_pin
                or phase_one_bridge.policy_id != phase_one_diagnostic.policy_id
                or phase_one_bridge.process_id != phase_one_diagnostic.process_id
                or phase_one_bridge.transcript_id != phase_one_diagnostic.transcript_id
                or phase_one_bridge.stderr_id != phase_one_diagnostic.stderr_id
                or phase_one_bridge.trace_id != phase_one_diagnostic.trace_id
                or phase_one_bridge.trace_sha256 != phase_one_diagnostic.trace_sha256
                or provenance.run_id != writer.run_id):
        raise RunnerError("registered actual phase-two diagnostic binding is invalid")

    # This is the final complete pre-stage check.  It still sees the open
    # base graph, then validates the receipt sidecars and exact frozen handoff
    # before the stage directory exists.
    _verify_registered_actual_phase_two_post_launch_provenance(
        prepared_run,
        phase_one_diagnostic,
        receipt_gate,
        prepared_phase,
        live_phase,
        provenance,
    )
    plan = prepared_run.authority.plan
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    _profile, network_attestation = _runner_owned_symbolic_profile(plan.client)
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or prepared_phase.mcp_config is None
            or prepared_phase.phase_prompt.artifact_id != "phase-prompt-2"
            or prepared_phase.transcript_id != "transcript-2"
            or live_phase.capture.exit_code != 0):
        raise RunnerError("registered actual phase-two diagnostic binding is invalid")
    normalized = normalize_native_transcript(
        client=plan.client,
        version=live_phase.reported_version,
        transcript=live_phase.capture.stdout,
    )
    if not normalized.complete:
        raise RunnerError("registered actual phase-two native transcript is unsupported")

    index_snapshot = handoff.raw_snapshots.get("brain-shim-capture-index.jsonl")
    command_snapshot = handoff.raw_snapshots.get("brain-shim-command-log.jsonl")
    if index_snapshot is None or command_snapshot is None:
        raise RunnerError("registered actual phase-two raw journals are unavailable")
    phase_index = _registered_actual_phase_two_handoff_delta(
        index_snapshot[0], handoff.phase_one_raw_index,
        label="registered actual phase-two capture index",
    )
    phase_commands = _registered_actual_phase_two_handoff_delta(
        command_snapshot[0], handoff.phase_one_raw_command_log,
        label="registered actual phase-two command log",
    )
    if (not phase_index
            or not phase_commands
            or len(phase_index.splitlines()) != len(phase_commands.splitlines())):
        raise RunnerError("registered actual phase-two host diagnostic requires a raw command delta")

    before_entries = [dict(entry) for entry in writer.entries]
    before_identities = dict(writer.write_identities)
    run_pin = PinnedDirectory.retain_relative_directory(
        control_pin,
        PurePosixPath("runs", writer.run_id).as_posix(),
        private=True,
    )
    stage_pin: PinnedDirectory | None = None
    try:
        base_tree = PinnedDirectory.snapshot_tree(run_pin)
        if any(
                relative.startswith(".phase-two-diagnostic-")
                for relative in base_tree
        ):
            raise RunnerError("registered actual phase-two diagnostic stage already exists")
        source = _PhaseTwoFrozenCaptureSource(handoff, control_pin)
        trace = _PhaseTwoFrozenHandoffTrace(source)
        fixture_id, fixture_sha256 = _registered_actual_phase_one_private_fixture_metadata_binding(
            phase_one_bridge,
            metadata,
        )
        # This second read is adjacent to stage allocation.  It deliberately
        # sees the exact still-open base graph, rather than relying on the
        # earlier verifier's mutable-writer preliminary checks.
        _read_registered_actual_two_phase_host_join(phase_one_diagnostic, provenance)
        stage_pin = PinnedDirectory.create_private_child(run_pin, ".phase-two-diagnostic-")
        stage_writer = _PrivatePhaseOneDiagnosticWriter(
            writer.control_root, writer.run_id, stage_pin,
        )
        mcp = prepared_phase.mcp_config
        policy_id = stage_writer.add_json("policy-2", "policy", {
            "run_id": writer.run_id,
            "execution_id": "execution-2",
            "phase": "approved_capture",
            "client": plan.client,
            "profile": "claude-restricted-tool-surface-v1",
            "network_attestation": network_attestation,
            "argv": list(live_phase.argv),
            "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
            "version_id": live_phase.version_id,
            "help_id": live_phase.help_id,
            "fixture_id": fixture_id,
            "fixture_sha256": fixture_sha256,
            "fixture_capability_id": None,
            "approval": None,
            "phase_prompt_id": prepared_phase.phase_prompt.artifact_id,
            "phase_prompt_sha256": prepared_phase.phase_prompt.sha256,
            "phase_prompt_transport": prepared_phase.phase_prompt.transport,
            "executable_id": live_phase.executable_id,
            "mcp_config_id": "mcp-2",
            "mcp_config_sha256": mcp.sha256,
            "mcp_path": str(mcp.path),
            "mcp_identity": dict(mcp.identity),
        })
        transcript_id = stage_writer.add_bytes("transcript-2", "transcript", live_phase.capture.stdout)
        stderr_id = stage_writer.add_bytes("stderr-2", "file_capture", live_phase.capture.stderr)
        conversion = convert_shim_captures(
            stage_writer,  # type: ignore[arg-type]
            control_root=writer.control_root,
            run_id=writer.run_id,
            execution_id="execution-2",
            phase="approved_capture",
            transcript_id=transcript_id,
            trace=trace,  # type: ignore[arg-type]
            control_pin=source,
            prior_raw_index=handoff.phase_one_raw_index,
            prior_raw_command_log=handoff.phase_one_raw_command_log,
            prior_raw_preapply_manifests=handoff.phase_one_raw_preapply_manifests,
        )
        expected_command_ids = handoff.raw_append_command_ids.get(
            "brain-shim-capture-index.jsonl", (),
        )
        if (not expected_command_ids
                or conversion.observation_ids != expected_command_ids
                or conversion.observation_ids != handoff.raw_append_command_ids.get(
                    "brain-shim-command-log.jsonl", (),
                )):
            raise RunnerError("registered actual phase-two conversion command closure is invalid")
        process_id = stage_writer.add_json("process-2", "process", {
            "run_id": writer.run_id,
            "execution_id": "execution-2",
            "phase": "approved_capture",
            "client": plan.client,
            "client_version": live_phase.reported_version,
            "argv": list(live_phase.argv),
            "argv_sha256": _sha256(_canonical_json(list(live_phase.argv))),
            "exit_code": live_phase.capture.exit_code,
            "transcript_id": transcript_id,
            "transcript_sha256": _sha256(live_phase.capture.stdout),
            "trace_id": conversion.trace_id,
            "trace_sha256": conversion.trace_sha256,
            "native_format": live_phase.native_format,
            "fixture_id": fixture_id,
            "fixture_sha256": fixture_sha256,
            "fixture_capability_id": None,
            "approval": None,
            "phase_prompt_id": prepared_phase.phase_prompt.artifact_id,
            "phase_prompt_sha256": prepared_phase.phase_prompt.sha256,
            "phase_prompt_transport": prepared_phase.phase_prompt.transport,
            "executable_id": live_phase.executable_id,
            "mcp_identity": dict(mcp.identity),
        })
        stage_tree = _registered_actual_phase_two_stage_tree(stage_writer, stage_pin)
        source.verify()
        receipt_verification = _verify_registered_actual_phase_two_receipt_ledgers(
            prepared_phase, provenance.receipt_ledgers, control_pin=control_pin,
        )
        _verify_registered_actual_phase_two_raw_control_handoff(
            phase_one_diagnostic,
            prepared_phase,
            handoff,
            receipt_verification,
            control_pin=control_pin,
            phase_one_bridge=phase_one_bridge,
        )
        if writer.entries != before_entries or writer.write_identities != before_identities:
            raise RunnerError("registered actual phase-two diagnostic mutated base evidence")
        PinnedDirectory.reverify_tree(stage_pin, stage_tree)
        stage_snapshot = _freeze_registered_actual_phase_two_diagnostic_stage(
            stage_writer,
            stage_pin,
            control_pin=control_pin,
            run_id=writer.run_id,
            stage_tree=stage_tree,
        )
        # Rebuild the whole staged host graph immediately before the sole
        # in-memory adoption step.  Its receipt check is the frozen facade
        # only; it cannot fall back to a writer or semantic helper.
        _read_registered_actual_two_phase_host_join(
            phase_one_diagnostic,
            provenance,
            stage=stage_snapshot,
        )
        existing_ids = {entry["id"] for entry in writer.entries}
        existing_paths = {entry["relative_path"] for entry in writer.entries}
        stage_name = stage_pin.path.name
        adopted: list[dict[str, Any]] = []
        adopted_identities: dict[str, tuple[int, int, int, int, int, int, int, int]] = {}
        for entry in stage_writer.entries:
            relative = entry["relative_path"]
            adopted_relative = stage_name + "/" + relative
            if (entry["id"] in existing_ids
                    or adopted_relative in existing_paths
                    or adopted_relative in writer.write_identities):
                raise RunnerError("registered actual phase-two diagnostic adoption is ambiguous")
            identity = stage_writer.write_identities.get(relative)
            if identity is None:
                raise RunnerError("registered actual phase-two diagnostic adoption is invalid")
            adopted.append({**entry, "relative_path": adopted_relative})
            adopted_identities[adopted_relative] = identity
            existing_ids.add(entry["id"])
            existing_paths.add(adopted_relative)
        if not adopted or set(adopted_identities) != {entry["relative_path"] for entry in adopted}:
            raise RunnerError("registered actual phase-two diagnostic adoption is invalid")
        writer.entries.extend(adopted)
        writer.write_identities.update(adopted_identities)
        after_tree = PinnedDirectory.snapshot_tree(run_pin)
        expected_tree = dict(base_tree)
        stage_root = stage_name + "/"
        stage_identity = after_tree.get(stage_root)
        if stage_identity is None:
            raise RunnerError("registered actual phase-two diagnostic stage disappeared")
        expected_tree[stage_root] = stage_identity
        expected_tree.update({stage_name + "/" + relative: identity for relative, identity in stage_tree.items()})
        if after_tree != expected_tree:
            raise RunnerError("registered actual phase-two diagnostic adoption changed run tree")
        _read_registered_actual_two_phase_host_join(
            phase_one_diagnostic,
            provenance,
            stage=stage_snapshot,
        )
        stage_snapshot.verify()
        return _RegisteredActualPhaseTwoDiagnostic(
            phase_one_diagnostic=phase_one_diagnostic,
            post_launch_token=provenance,
            normalized=_freeze_diagnostic_normalization(normalized),
            conversion=conversion,
            stage_name=stage_name,
            stage_snapshot=stage_snapshot,
            policy_id=policy_id,
            process_id=process_id,
            transcript_id=transcript_id,
            stderr_id=stderr_id,
            trace_id=conversion.trace_id,
            trace_sha256=conversion.trace_sha256,
        )
    finally:
        if stage_pin is not None:
            PinnedDirectory.close(stage_pin)
        PinnedDirectory.close(run_pin)


@dataclass(frozen=True)
class _RegisteredActualTwoPhaseHostPreflight:
    """Private, non-authoritative proof that both retained host graphs agree.

    This remains deliberately narrower than a public eligibility or outcome:
    it retains no semantic projection, approval/capability artifact, or pass
    claim.  ``verify`` is observational only and re-reads the pinned staged
    host join before a later specialized finalizer may use it.
    """

    phase_one_diagnostic: _RegisteredActualPhaseOneDiagnostic
    phase_two_diagnostic: _RegisteredActualPhaseTwoDiagnostic
    receipt_gate: PhaseOneReceiptGate
    host_join: _RegisteredActualTwoPhaseHostJoin

    def __post_init__(self) -> None:
        if (type(self.phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
                or type(self.phase_two_diagnostic) is not _RegisteredActualPhaseTwoDiagnostic
                or type(self.receipt_gate) is not PhaseOneReceiptGate
                or type(self.host_join) is not _RegisteredActualTwoPhaseHostJoin):
            raise RunnerError("registered actual two-phase host preflight is invalid")
        self.phase_two_diagnostic.__post_init__()
        token = self.phase_two_diagnostic.post_launch_token
        if (self.phase_two_diagnostic.phase_one_diagnostic is not self.phase_one_diagnostic
                or token.receipt_gate is not self.receipt_gate
                or self.host_join.run_id != token.run_id):
            raise RunnerError("registered actual two-phase host preflight is invalid")
        self.receipt_gate.__post_init__()
        control_pin, _workspace_pin = _registered_actual_phase_two_live_roots(
            token.prepared_phase,
            token.live_phase,
        )
        if self.host_join.control_pin is not control_pin:
            raise RunnerError("registered actual two-phase host preflight is invalid")
        self.host_join.verify()

    def verify(self) -> None:
        """Reconstruct the frozen receipt and complete staged join without writes."""

        self.__post_init__()
        current = _read_registered_actual_two_phase_host_join(
            self.phase_one_diagnostic,
            self.phase_two_diagnostic.post_launch_token,
            stage=self.phase_two_diagnostic.stage_snapshot,
        )
        if (current.artifact_provenance != self.host_join.artifact_provenance
                or current.directories != self.host_join.directories):
            raise RunnerError("registered actual two-phase host preflight changed")

    def __reduce__(self) -> object:
        raise TypeError("registered actual two-phase host preflight is not serializable")


def _preflight_registered_actual_two_phase_host_diagnostic(
    phase_one_diagnostic: _RegisteredActualPhaseOneDiagnostic,
    phase_two_diagnostic: _RegisteredActualPhaseTwoDiagnostic,
    receipt_gate: PhaseOneReceiptGate,
) -> _RegisteredActualTwoPhaseHostPreflight:
    """Read-only closure for the direct private two-phase diagnostic chain."""

    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(phase_two_diagnostic) is not _RegisteredActualPhaseTwoDiagnostic
            or type(receipt_gate) is not PhaseOneReceiptGate):
        raise RunnerError("registered actual two-phase host preflight inputs are invalid")
    phase_two_diagnostic.__post_init__()
    receipt_gate.__post_init__()
    provenance = phase_two_diagnostic.post_launch_token
    control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
        provenance.prepared_phase, provenance.live_phase,
    )
    phase_one_bridge = provenance.phase_one_bridge
    phase_one = phase_one_diagnostic.prepared_phase
    phase_two = provenance.prepared_phase
    if (phase_two_diagnostic.phase_one_diagnostic is not phase_one_diagnostic
            or provenance.receipt_gate is not receipt_gate
            or provenance.receipt_control.artifacts is not phase_one_bridge.receipt_artifacts
            or provenance.receipt_control.control_pin is not control_pin
            or phase_one.prepared_run is not phase_two.prepared_run
            or phase_one.writer is not phase_two.writer
            or phase_one_bridge.live_phase.control_pin is not control_pin
            or phase_one_bridge.live_phase.workspace_pin is not workspace_pin
            or phase_one.execution_id != "execution-1"
            or phase_one.phase != "approval"
            or phase_two.execution_id != "execution-2"
            or phase_two.phase != "approved_capture"
            or phase_two_diagnostic.policy_id != "policy-2"
            or phase_two_diagnostic.process_id != "process-2"
            or phase_two_diagnostic.transcript_id != "transcript-2"
            or phase_two_diagnostic.trace_id != "trace-execution-2"
            or phase_two_diagnostic.stage_snapshot.stage_name != phase_two_diagnostic.stage_name):
        raise RunnerError("registered actual two-phase host preflight is invalid")
    host_join = _read_registered_actual_two_phase_host_join(
        phase_one_diagnostic,
        provenance,
        stage=phase_two_diagnostic.stage_snapshot,
    )
    proof = _RegisteredActualTwoPhaseHostPreflight(
        phase_one_diagnostic,
        phase_two_diagnostic,
        receipt_gate,
        host_join,
    )
    proof.verify()
    return proof


@dataclass(frozen=True)
class _RegisteredActualTwoPhaseFinalizationFacts:
    """Small immutable host facts allowed into the incomplete terminal log."""

    fixture_id: str
    fixture_sha256: str
    client_version: str

    def __post_init__(self) -> None:
        if (type(self.fixture_id) is not str
                or not self.fixture_id
                or type(self.fixture_sha256) is not str
                or not _is_hex64(self.fixture_sha256)
                or type(self.client_version) is not str
                or not self.client_version):
            raise RunnerError("registered actual two-phase finalization facts are invalid")

    def __reduce__(self) -> object:
        raise TypeError("registered actual two-phase finalization facts are not serializable")


@dataclass(frozen=True)
class _RegisteredActualTwoPhaseFinalizationSnapshot:
    """All canonical terminal bytes derived before the first final write."""

    preflight: _RegisteredActualTwoPhaseHostPreflight
    facts: _RegisteredActualTwoPhaseFinalizationFacts
    provenance: Mapping[str, _RegisteredActualEvidenceProvenance]
    entries: tuple[Mapping[str, Any], ...]
    files: frozenset[str]
    directories: frozenset[str]
    index_raw: bytes
    attestation_raw: bytes
    log_raw: bytes

    def __post_init__(self) -> None:
        if (type(self.preflight) is not _RegisteredActualTwoPhaseHostPreflight
                or type(self.facts) is not _RegisteredActualTwoPhaseFinalizationFacts
                or not isinstance(self.provenance, Mapping)
                or type(self.entries) is not tuple
                or type(self.files) is not frozenset
                or type(self.directories) is not frozenset
                or any(type(raw) is not bytes for raw in (
                    self.index_raw, self.attestation_raw, self.log_raw,
                ))):
            raise RunnerError("registered actual two-phase finalization snapshot is invalid")
        self.facts.__post_init__()
        frozen_provenance: dict[str, _RegisteredActualEvidenceProvenance] = {}
        for artifact_id, record in self.provenance.items():
            if (type(artifact_id) is not str or not artifact_id
                    or type(record) is not tuple or len(record) != 5):
                raise RunnerError("registered actual two-phase finalization snapshot is invalid")
            artifact_type, relative, digest, byte_count, identity = record
            try:
                PinnedDirectory._relative_parts(relative)
            except RunnerError as error:
                raise RunnerError(
                    "registered actual two-phase finalization snapshot is invalid"
                ) from error
            if (type(artifact_type) is not str or not artifact_type
                    or not _is_hex64(digest)
                    or type(byte_count) is not int or byte_count < 0
                    or not _valid_regular_identity(identity)
                    or identity[5] != byte_count):
                raise RunnerError("registered actual two-phase finalization snapshot is invalid")
            frozen_provenance[artifact_id] = (
                artifact_type, relative, digest, byte_count, tuple(identity),
            )
        expected: dict[str, Mapping[str, Any]] = {}
        paths: set[str] = set()
        frozen_entries: list[Mapping[str, Any]] = []
        for entry in self.entries:
            if (not isinstance(entry, Mapping)
                    or set(entry) != {"id", "type", "relative_path", "sha256", "bytes"}
                    or type(entry.get("id")) is not str
                    or type(entry.get("type")) is not str
                    or type(entry.get("relative_path")) is not str
                    or not _is_hex64(entry.get("sha256"))
                    or type(entry.get("bytes")) is not int or entry["bytes"] < 0):
                raise RunnerError("registered actual two-phase finalization snapshot is invalid")
            artifact_id = entry["id"]
            relative = entry["relative_path"]
            try:
                PinnedDirectory._relative_parts(relative)
            except RunnerError as error:
                raise RunnerError("registered actual two-phase finalization snapshot is invalid") from error
            provenance = frozen_provenance.get(artifact_id)
            if (artifact_id in expected or relative in paths
                    or provenance is None
                    or provenance[:4] != (
                        entry["type"], relative, entry["sha256"], entry["bytes"],
                    )):
                raise RunnerError("registered actual two-phase finalization snapshot is invalid")
            expected[artifact_id] = MappingProxyType(dict(entry))
            paths.add(relative)
            frozen_entries.append(expected[artifact_id])
        if (not expected
                or set(frozen_provenance) != set(expected)
                or set(self.files) != paths
                or tuple(entry["id"] for entry in frozen_entries)
                != tuple(sorted(expected))):
            raise RunnerError("registered actual two-phase finalization snapshot is invalid")
        expected_directories = {
            parent.as_posix()
            for relative in paths
            for parent in PurePosixPath(relative).parents
            if parent != PurePosixPath(".")
        }
        if set(self.directories) != expected_directories:
            raise RunnerError("registered actual two-phase finalization snapshot is invalid")
        object.__setattr__(self, "provenance", MappingProxyType(frozen_provenance))
        object.__setattr__(self, "entries", tuple(frozen_entries))

    def __reduce__(self) -> object:
        raise TypeError("registered actual two-phase finalization snapshot is not serializable")


def _registered_actual_two_phase_finalization_entries(
    preflight: _RegisteredActualTwoPhaseHostPreflight,
) -> tuple[Mapping[str, Any], ...]:
    """Derive the exact indexed rows from the descriptor-pinned host join."""

    if type(preflight) is not _RegisteredActualTwoPhaseHostPreflight:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    host_join = preflight.host_join
    expected: dict[str, Mapping[str, Any]] = {}
    paths: set[str] = set()
    for artifact_id, record in host_join.artifact_provenance.items():
        artifact_type, relative, digest, byte_count, identity = record
        if artifact_id in expected or relative in paths:
            raise RunnerError("registered actual two-phase finalization evidence is ambiguous")
        expected[artifact_id] = MappingProxyType({
            "id": artifact_id,
            "type": artifact_type,
            "relative_path": relative,
            "sha256": digest,
            "bytes": byte_count,
        })
        paths.add(relative)
    prohibited = {
        "marker", "event_record", "interpretation_decision", "approval",
        "fixture_capability", "run_manifest", "assertion",
    }
    if any(entry["type"] in prohibited for entry in expected.values()):
        raise RunnerError("registered actual two-phase finalization crossed a public boundary")
    return tuple(expected[artifact_id] for artifact_id in sorted(expected))


def _verify_registered_actual_two_phase_finalization_receipt_gate(
    preflight: _RegisteredActualTwoPhaseHostPreflight,
) -> None:
    """Reconstruct the phase-one release gate at every terminal checkpoint.

    ``preflight.verify`` performs this complete reconstruction before the
    finalization snapshot is frozen.  It cannot be called after a terminal
    file exists because the host-join reader correctly rejects that new root
    file.  Keep this smaller, descriptor-backed replay separate so a mutable
    in-memory gate cannot change its release facts or positions between
    terminal writes.
    """

    if type(preflight) is not _RegisteredActualTwoPhaseHostPreflight:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    phase_one_diagnostic = preflight.phase_one_diagnostic
    phase_two_diagnostic = preflight.phase_two_diagnostic
    receipt_gate = preflight.receipt_gate
    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(phase_two_diagnostic) is not _RegisteredActualPhaseTwoDiagnostic
            or type(receipt_gate) is not PhaseOneReceiptGate
                or phase_two_diagnostic.phase_one_diagnostic is not phase_one_diagnostic):
        raise RunnerError("registered actual two-phase finalization receipt gate is invalid")
    token = phase_two_diagnostic.post_launch_token
    if type(token) is not _RegisteredActualPhaseTwoPostLaunchToken:
        raise RunnerError("registered actual two-phase finalization receipt gate is invalid")
    receipt_gate.__post_init__()
    try:
        token.__post_init__()
        prepared_phase = token.prepared_phase
        control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
            prepared_phase, token.live_phase,
        )
        phase_one_bridge = token.phase_one_bridge
    except RunnerError:
        raise
    except (AttributeError, TypeError, ValueError, OSError) as error:
        raise RunnerError("registered actual two-phase finalization receipt gate is invalid") from error
    prepared_run = prepared_phase.prepared_run
    if (token.receipt_gate is not receipt_gate
            or type(prepared_phase) is not _RegisteredActualPreparedPhase
            or type(prepared_run) is not _RegisteredActualPreparedRun
            or prepared_phase.prepared_run is not prepared_run
            or token.receipt_control.artifacts is not phase_one_bridge.receipt_artifacts
            or token.receipt_control.control_pin is not control_pin
            or phase_one_bridge.live_phase.control_pin is not control_pin
            or phase_one_bridge.live_phase.workspace_pin is not workspace_pin):
        raise RunnerError("registered actual two-phase finalization receipt gate is invalid")
    plan = prepared_run.authority.plan
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    scenario = metadata.scenario()
    if (type(plan) is not RegisteredActualScenarioPlan
            or plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"
            or metadata.scenario_id != plan.scenario_id
            or workspace_pin.path != prepared_run.prepared.workspace):
        raise RunnerError("registered actual two-phase finalization receipt gate is invalid")
    reconstructed = _reconstruct_frozen_actual_phase_one_receipt_gate(
        control=token.receipt_control,
        phase_one=phase_one_bridge.live_phase,
        scenario=scenario,
        conversion=phase_one_bridge.conversion,
        workspace=workspace_pin.path,
        execution_id="execution-1",
    )
    if not _phase_one_receipt_gate_matches(receipt_gate, reconstructed):
        raise RunnerError("registered actual two-phase finalization receipt gate changed")


def _verify_registered_actual_two_phase_finalization_raw_handoff(
    preflight: _RegisteredActualTwoPhaseHostPreflight,
) -> None:
    """Recheck the retained receipt-backed raw/control closure before final writes.

    The raw journals, receipt ledgers, sealed controls, and phase-two trace
    are intentionally outside the indexed run subtree.  Every terminal write
    checkpoint must therefore replay their private receipt closure, rather
    than relying on the one preflight read that produced ``host_join``.
    """

    if type(preflight) is not _RegisteredActualTwoPhaseHostPreflight:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    phase_one_diagnostic = preflight.phase_one_diagnostic
    phase_two_diagnostic = preflight.phase_two_diagnostic
    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(phase_two_diagnostic) is not _RegisteredActualPhaseTwoDiagnostic):
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    token = phase_two_diagnostic.post_launch_token
    if type(token) is not _RegisteredActualPhaseTwoPostLaunchToken:
        raise RunnerError("registered actual two-phase finalization raw handoff is invalid")
    try:
        token.__post_init__()
        prepared_phase = token.prepared_phase
        control_pin, _workspace_pin = _registered_actual_phase_two_live_roots(
            prepared_phase, token.live_phase,
        )
        phase_one_bridge = token.phase_one_bridge
    except RunnerError:
        raise
    except (AttributeError, TypeError, ValueError, OSError) as error:
        raise RunnerError("registered actual two-phase finalization raw handoff is invalid") from error
    if (type(prepared_phase) is not _RegisteredActualPreparedPhase
            or token.receipt_control.artifacts is not phase_one_bridge.receipt_artifacts
            or preflight.host_join.control_pin is not control_pin):
        raise RunnerError("registered actual two-phase finalization raw handoff is invalid")
    phase_one_bridge.raw_predecessors.require_prelaunch_match(
        token.receipt_ledgers.raw_prelaunch,
    )
    receipt_verification = _verify_registered_actual_phase_two_receipt_ledgers(
        prepared_phase,
        token.receipt_ledgers,
        control_pin=control_pin,
    )
    _verify_registered_actual_phase_two_raw_control_handoff(
        phase_one_diagnostic,
        prepared_phase,
        token.raw_control_handoff,
        receipt_verification,
        control_pin=control_pin,
        phase_one_bridge=phase_one_bridge,
    )


def _registered_actual_two_phase_finalization_policy_process_closure(
    preflight: _RegisteredActualTwoPhaseHostPreflight,
) -> _RegisteredActualTwoPhaseFinalizationFacts:
    """Rebuild the narrow host-only policy/process closure for finalization.

    This verifier deliberately reads only descriptor-pinned host artifacts
    already present in the private two-phase join.  It does not open a generic
    indexed reader, reinterpret native output, construct semantic evidence,
    or consult mutable writer maps.  Its sole purpose is to prevent an
    incomplete terminal log from naming policy/process rows whose launch
    bindings disagree with their retained host artifacts.
    """

    if type(preflight) is not _RegisteredActualTwoPhaseHostPreflight:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    phase_one_diagnostic = preflight.phase_one_diagnostic
    phase_two_diagnostic = preflight.phase_two_diagnostic
    host_join = preflight.host_join
    if (type(phase_one_diagnostic) is not _RegisteredActualPhaseOneDiagnostic
            or type(phase_two_diagnostic) is not _RegisteredActualPhaseTwoDiagnostic
            or type(host_join) is not _RegisteredActualTwoPhaseHostJoin):
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    token = phase_two_diagnostic.post_launch_token
    if type(token) is not _RegisteredActualPhaseTwoPostLaunchToken:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    token.__post_init__()
    control_pin, workspace_pin = _registered_actual_phase_two_live_roots(
        token.prepared_phase, token.live_phase,
    )
    phase_one_bridge = token.phase_one_bridge
    prepared_run = token.prepared_phase.prepared_run
    plan = token.prepared_phase.authority.plan
    metadata = _registered_actual_scenario_fixture_metadata(prepared_run, plan)
    if (host_join.control_pin is not control_pin
            or phase_one_bridge.live_phase.control_pin is not control_pin
            or phase_one_bridge.live_phase.workspace_pin is not workspace_pin
            or phase_two_diagnostic.post_launch_token.prepared_phase.prepared_run is not prepared_run
            or plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"):
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    symbolic_template, network_attestation = _runner_owned_symbolic_profile("claude")
    registration = _runner_owned_registration("claude")
    if (symbolic_template != tuple(_CLAUDE_TEMPLATE)
            or plan.symbolic_template != symbolic_template
            or plan.network_attestation != network_attestation
            or plan.registration is not registration):
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    fixture_id, fixture_sha256 = _registered_actual_phase_one_private_fixture_metadata_binding(
        phase_one_bridge,
        metadata,
    )
    phase_two_live = token.live_phase
    private_trusted_context = phase_two_live.trusted_context
    phase_one_registration, phase_one_trusted = _registered_live_context_phase(
        client="claude",
        execution_id="execution-1",
        control_pin=host_join.control_pin,
        workspace_pin=workspace_pin,
        trusted_context=private_trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    phase_two_registration, phase_two_trusted = _registered_live_context_phase(
        client="claude",
        execution_id="execution-2",
        control_pin=host_join.control_pin,
        workspace_pin=workspace_pin,
        trusted_context=private_trusted_context,
        expected_execution_ids=frozenset({"execution-1", "execution-2"}),
    )
    if (phase_one_registration is not registration
            or phase_two_registration is not registration
            or phase_two_trusted is not phase_two_live.trusted_executable
            or phase_two_trusted is phase_one_trusted
            or private_trusted_context.trusted_executables.get("execution-1")
            is not phase_one_trusted
            or private_trusted_context.trusted_executables.get("execution-2")
            is not phase_two_trusted):
        raise RunnerError("registered actual two-phase finalization context is invalid")
    phase_one_identity, phase_one_sha256 = _registered_executable_observation(phase_one_trusted)
    phase_two_identity, phase_two_sha256 = _registered_executable_observation(phase_two_trusted)
    trusted_phase_executables = {
        1: (phase_one_trusted, phase_one_identity, phase_one_sha256),
        2: (phase_two_trusted, phase_two_identity, phase_two_sha256),
    }
    scenario = metadata.scenario()
    identity_keys = (
        "device", "inode", "mode", "uid", "nlink", "bytes", "mtime_ns", "ctime_ns",
    )

    def read(artifact_id: str, artifact_type: str) -> tuple[bytes, _RegisteredActualEvidenceProvenance]:
        record = host_join.artifact_provenance.get(artifact_id)
        if record is None:
            raise RunnerError("registered actual two-phase finalization artifact is missing")
        observed_type, relative, digest, byte_count, identity = record
        if observed_type != artifact_type:
            raise RunnerError("registered actual two-phase finalization artifact is invalid")
        raw, observed_identity = PinnedDirectory.snapshot_relative(
            host_join.control_pin,
            PurePosixPath("runs", host_join.run_id, relative).as_posix(),
        )
        if (observed_identity != identity
                or len(raw) != byte_count
                or _sha256(raw) != digest):
            raise RunnerError("registered actual two-phase finalization artifact changed")
        return raw, record

    def read_json(artifact_id: str, artifact_type: str) -> tuple[dict[str, Any], _RegisteredActualEvidenceProvenance]:
        raw, record = read(artifact_id, artifact_type)
        value = _strict_json(raw, label="registered actual two-phase finalization artifact")
        if type(value) is not dict or _canonical_json(value) != raw:
            raise RunnerError("registered actual two-phase finalization artifact is invalid")
        return value, record

    def identity_dict(record: _RegisteredActualEvidenceProvenance) -> dict[str, int]:
        identity = record[4]
        if (type(identity) is not tuple
                or len(identity) != len(identity_keys)
                or any(type(item) is not int for item in identity)):
            raise RunnerError("registered actual two-phase finalization artifact is invalid")
        return dict(zip(identity_keys, identity))

    policy_keys = {
        "run_id", "execution_id", "phase", "client", "profile",
        "network_attestation", "argv", "argv_sha256", "version_id", "help_id",
        "fixture_id", "fixture_sha256", "fixture_capability_id", "approval",
        "phase_prompt_id", "phase_prompt_sha256", "phase_prompt_transport",
        "executable_id", "mcp_config_id", "mcp_config_sha256", "mcp_path", "mcp_identity",
    }
    process_keys = {
        "run_id", "execution_id", "phase", "client", "client_version", "argv",
        "argv_sha256", "exit_code", "transcript_id", "transcript_sha256", "trace_id",
        "trace_sha256", "native_format", "fixture_id", "fixture_sha256",
        "fixture_capability_id", "approval", "phase_prompt_id", "phase_prompt_sha256",
        "phase_prompt_transport", "executable_id", "mcp_identity",
    }
    executable_keys = {
        "schema_version", "run_id", "execution_id", "phase", "client", "resolved_path",
        "launch_identity", "launch_sha256", "seal_identity", "seal_sha256", "reported_version",
        "version_probe", "help_probe", "supported_build_id",
    }
    probe_keys = {"argv", "exit_code", "output_id", "output_sha256"}
    phase_rows = (
        (
            1,
            "approval",
            phase_one_bridge.policy_id,
            phase_one_bridge.process_id,
            phase_one_bridge.transcript_id,
            phase_one_bridge.trace_id,
            phase_one_bridge.live_phase,
        ),
        (
            2,
            "approved_capture",
            phase_two_diagnostic.policy_id,
            phase_two_diagnostic.process_id,
            phase_two_diagnostic.transcript_id,
            phase_two_diagnostic.trace_id,
            phase_two_live,
        ),
    )
    client_versions: set[str] = set()
    for (
            position, phase, policy_id, process_id, transcript_id, trace_id, live_phase,
    ) in phase_rows:
        execution_id = f"execution-{position}"
        prompt_id = f"phase-prompt-{position}"
        mcp_id = f"mcp-{position}"
        version_id = f"version-{position}"
        help_id = f"help-{position}"
        executable_id = f"client-executable-{position}"
        trusted_executable, trusted_identity, trusted_sha256 = trusted_phase_executables[position]
        if type(live_phase) is not RegisteredLivePhase:
            raise RunnerError("registered actual two-phase finalization execution is invalid")
        try:
            live_launch_identity = dict(live_phase.launch_identity)
            live_seal_identity = dict(live_phase.seal_identity)
        except (TypeError, ValueError) as error:
            raise RunnerError(
                "registered actual two-phase finalization live executable is invalid"
            ) from error
        if (policy_id != f"policy-{position}"
                or process_id != f"process-{position}"
                or transcript_id != f"transcript-{position}"
                or trace_id != f"trace-{execution_id}"
                or live_phase.executable_id != executable_id
                or live_phase.version_id != version_id
                or live_phase.help_id != help_id
                or live_phase.reported_version != registration.expected_version
                or live_phase.native_format != registration.native_format
                or live_phase.trusted_executable is not trusted_executable
                or live_phase.supported_build_id != trusted_executable.supported_build_id
                or live_launch_identity != trusted_identity
                or live_seal_identity != trusted_identity
                or live_phase.launch_sha256 != trusted_sha256
                or live_phase.seal_sha256 != trusted_sha256):
            raise RunnerError("registered actual two-phase finalization execution is invalid")
        policy, _policy_record = read_json(policy_id, "policy")
        process, _process_record = read_json(process_id, "process")
        prompt_raw, prompt_record = read(prompt_id, "phase_prompt")
        mcp_raw, mcp_record = read(mcp_id, "mcp_config")
        version_raw, version_record = read(version_id, "version")
        help_raw, help_record = read(help_id, "help")
        executable, _executable_record = read_json(executable_id, "client_executable")
        transcript_raw, transcript_record = read(transcript_id, "transcript")
        trace_raw, trace_record = read(trace_id, "execution_trace")
        if (set(policy) != policy_keys
                or set(process) != process_keys
                or prompt_raw != _canonical_phase_prompt(scenario, phase)
                or mcp_raw != EMPTY_MCP_BYTES
                or not help_raw):
            raise RunnerError("registered actual two-phase finalization execution is invalid")
        prompt_sha256 = _sha256(prompt_raw)
        mcp_sha256 = _sha256(mcp_raw)
        version = _version_text(version_raw)
        if (version != registration.expected_version
                or prompt_sha256 != prompt_record[2]
                or mcp_sha256 != mcp_record[2]
                or _sha256(transcript_raw) != transcript_record[2]
                or _sha256(trace_raw) != trace_record[2]):
            raise RunnerError("registered actual two-phase finalization execution is invalid")
        mcp_path = str(
            host_join.control_pin.path / "runs" / host_join.run_id / mcp_record[1]
        )
        mcp_identity = identity_dict(mcp_record)
        expected_prompt_binding = {
            "phase_prompt_id": prompt_id,
            "phase_prompt_sha256": prompt_sha256,
            "phase_prompt_transport": _phase_prompt_transport("claude"),
        }
        expected_common = {
            "run_id": host_join.run_id,
            "execution_id": execution_id,
            "phase": phase,
            "client": "claude",
            "fixture_id": fixture_id,
            "fixture_sha256": fixture_sha256,
            "fixture_capability_id": None,
            "approval": None,
            "executable_id": executable_id,
        }
        if (policy.get("profile") != "claude-restricted-tool-surface-v1"
                or policy.get("network_attestation") != network_attestation
                or policy.get("version_id") != version_id
                or policy.get("help_id") != help_id
                or policy.get("mcp_config_id") != mcp_id
                or policy.get("mcp_config_sha256") != mcp_sha256
                or policy.get("mcp_path") != mcp_path
                or policy.get("mcp_identity") != mcp_identity
                or any(policy.get(key) != value for key, value in expected_common.items())
                or any(process.get(key) != value for key, value in expected_common.items())
                or any(policy.get(key) != value for key, value in expected_prompt_binding.items())
                or any(process.get(key) != value for key, value in expected_prompt_binding.items())
                or process.get("mcp_identity") != mcp_identity
                or process.get("exit_code") != 0
                or process.get("native_format") != registration.native_format
                or process.get("client_version") != version
                or process.get("transcript_id") != transcript_id
                or process.get("transcript_sha256") != transcript_record[2]
                or process.get("trace_id") != trace_id
                or process.get("trace_sha256") != trace_record[2]):
            raise RunnerError("registered actual two-phase finalization execution is invalid")
        if (set(executable) != executable_keys
                or executable.get("schema_version") != 1
                or executable.get("run_id") != host_join.run_id
                or executable.get("execution_id") != execution_id
                or executable.get("phase") != phase
                or executable.get("client") != "claude"
                or executable.get("resolved_path") != str(registration.resolved_path)
                or executable.get("reported_version") != version
                or executable.get("supported_build_id") != trusted_executable.supported_build_id
                or executable.get("launch_sha256") != trusted_sha256
                or executable.get("seal_sha256") != trusted_sha256
                or executable.get("launch_identity") != trusted_identity
                or executable.get("seal_identity") != trusted_identity):
            raise RunnerError("registered actual two-phase finalization executable is invalid")
        launch_identity = executable["launch_identity"]
        if (type(launch_identity) is not dict
                or set(launch_identity) != set(identity_keys)
                or any(type(value) is not int for value in launch_identity.values())):
            raise RunnerError("registered actual two-phase finalization executable is invalid")
        version_probe = executable["version_probe"]
        help_probe = executable["help_probe"]
        if (type(version_probe) is not dict
                or type(help_probe) is not dict
                or set(version_probe) != probe_keys
                or set(help_probe) != probe_keys
                or version_probe.get("argv") != [str(registration.resolved_path), "--version"]
                or version_probe.get("exit_code") != 0
                or version_probe.get("output_id") != version_id
                or version_probe.get("output_sha256") != version_record[2]
                or help_probe.get("argv") != [str(registration.resolved_path), "--help"]
                or help_probe.get("exit_code") != 0
                or help_probe.get("output_id") != help_id
                or help_probe.get("output_sha256") != help_record[2]):
            raise RunnerError("registered actual two-phase finalization executable is invalid")
        try:
            prompt_text = prompt_raw.decode("utf-8", "strict")
        except UnicodeDecodeError as error:
            raise RunnerError("registered actual two-phase finalization prompt is invalid") from error
        expected_argv = [
            mcp_path if item == "{mcp_config}" else prompt_text if item == "{prompt}" else item
            for item in _CLAUDE_TEMPLATE
        ]
        expected_argv[0] = str(registration.resolved_path)
        argv_sha256 = _sha256(_canonical_json(expected_argv))
        if (policy.get("argv") != expected_argv
                or process.get("argv") != expected_argv
                or policy.get("argv_sha256") != argv_sha256
                or process.get("argv_sha256") != argv_sha256):
            raise RunnerError("registered actual two-phase finalization argv is invalid")
        client_versions.add(version)
    if client_versions != {registration.expected_version}:
        raise RunnerError("registered actual two-phase finalization version is inconsistent")
    return _RegisteredActualTwoPhaseFinalizationFacts(
        fixture_id=fixture_id,
        fixture_sha256=fixture_sha256,
        client_version=registration.expected_version,
    )


def _freeze_registered_actual_two_phase_finalization_snapshot(
    preflight: _RegisteredActualTwoPhaseHostPreflight,
) -> _RegisteredActualTwoPhaseFinalizationSnapshot:
    """Freeze exact index, attestation, and incomplete-log bytes before writes."""

    if type(preflight) is not _RegisteredActualTwoPhaseHostPreflight:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    preflight.verify()
    _verify_registered_actual_two_phase_finalization_receipt_gate(preflight)
    _verify_registered_actual_two_phase_finalization_raw_handoff(preflight)
    phase_two = preflight.phase_two_diagnostic
    token = phase_two.post_launch_token
    phase_one_bridge = token.phase_one_bridge
    plan = token.prepared_phase.authority.plan
    entries = _registered_actual_two_phase_finalization_entries(preflight)
    facts = _registered_actual_two_phase_finalization_policy_process_closure(preflight)
    fixture_sha256 = facts.fixture_sha256
    run_id = preflight.host_join.run_id
    index_raw = _canonical_json({
        "schema_version": 1,
        "run_id": run_id,
        "entries": [dict(entry) for entry in entries],
    })
    index_sha256 = _sha256(index_raw)
    executions = [
        {
            "id": "execution-1",
            "phase": "approval",
            "kind": "actual_client_process",
            "policy_id": phase_one_bridge.policy_id,
            "process_id": phase_one_bridge.process_id,
            "transcript_id": phase_one_bridge.transcript_id,
        },
        {
            "id": "execution-2",
            "phase": "approved_capture",
            "kind": "actual_client_process",
            "policy_id": phase_two.policy_id,
            "process_id": phase_two.process_id,
            "transcript_id": phase_two.transcript_id,
        },
    ]
    if (plan.client != "claude"
            or plan.scenario_id != "web-approval-and-capture"):
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    log: dict[str, Any] = {
        "schema_version": 1,
        "run_id": run_id,
        "scenario_id": "web-approval-and-capture",
        "client": "claude",
        "client_version": facts.client_version,
        "fixture_sha256": fixture_sha256,
        "network_mode": "mock_only",
        "evidence_index_sha256": index_sha256,
        "log_attestation_sha256": "0" * 64,
        "executions": executions,
        "receipts": [],
        "deliveries": [],
        "events": [],
        "repository_assertions": [],
        "result": "incomplete",
        "incomplete_reasons": ["public_semantic_projection_unavailable"],
    }
    unsigned = dict(log)
    unsigned.pop("log_attestation_sha256")
    attestation_raw = _canonical_json({
        "schema_version": 1,
        "run_id": run_id,
        "client": "claude",
        "scenario_id": "web-approval-and-capture",
        "fixture_sha256": fixture_sha256,
        "evidence_index_sha256": index_sha256,
        "log_sha256": _sha256(_canonical_json(unsigned)),
    })
    log["log_attestation_sha256"] = _sha256(attestation_raw)
    log_raw = _canonical_json(log)
    try:
        from tests.evals.scenario_contract import ScenarioContractError, validate_against_schema

        schema = _strict_json(_safe_read(EVAL_ROOT / "event-log.v1.schema.json"), label="event log schema")
        if type(schema) is not dict:
            raise RunnerError("event log schema is invalid")
        validate_against_schema(log, schema)
    except (ImportError, ScenarioContractError) as error:
        raise RunnerError("registered actual two-phase final log is invalid") from error
    return _RegisteredActualTwoPhaseFinalizationSnapshot(
        preflight=preflight,
        facts=facts,
        provenance=preflight.host_join.artifact_provenance,
        entries=entries,
        files=frozenset(entry["relative_path"] for entry in entries),
        directories=preflight.host_join.directories,
        index_raw=index_raw,
        attestation_raw=attestation_raw,
        log_raw=log_raw,
    )


def _verify_registered_actual_two_phase_finalization_base(
    snapshot: _RegisteredActualTwoPhaseFinalizationSnapshot,
    terminal: Mapping[str, _ControlTraceSnapshot],
) -> None:
    """Ensure terminal writes have not changed retained host evidence or tree shape."""

    if (type(snapshot) is not _RegisteredActualTwoPhaseFinalizationSnapshot
            or not isinstance(terminal, Mapping)):
        raise RunnerError("registered actual two-phase finalization state is invalid")
    preflight = snapshot.preflight
    control_pin = snapshot.preflight.host_join.control_pin
    run_id = snapshot.preflight.host_join.run_id
    _verify_registered_actual_two_phase_finalization_receipt_gate(preflight)
    _verify_registered_actual_two_phase_finalization_raw_handoff(preflight)
    current_entries = _registered_actual_two_phase_finalization_entries(preflight)
    if current_entries != snapshot.entries:
        raise RunnerError("registered actual two-phase finalization evidence changed")
    if _registered_actual_two_phase_finalization_policy_process_closure(preflight) != snapshot.facts:
        raise RunnerError("registered actual two-phase finalization policy/process changed")
    preflight.phase_two_diagnostic.stage_snapshot.verify(
        allow_run_root_metadata_change=bool(terminal),
    )
    for artifact_id, record in snapshot.provenance.items():
        _artifact_type, relative, digest, byte_count, identity = record
        raw, observed = PinnedDirectory.snapshot_relative(
            control_pin,
            PurePosixPath("runs", run_id, relative).as_posix(),
        )
        if (observed != identity
                or len(raw) != byte_count
                or _sha256(raw) != digest):
            raise RunnerError("registered actual two-phase finalization evidence changed")
    expected_terminal = {"evidence-index.json", "log-attestation.json", "event-log.json"}
    if set(terminal) - expected_terminal:
        raise RunnerError("registered actual two-phase finalization terminal set is invalid")
    for relative, retained in terminal.items():
        if type(relative) is not str or relative not in expected_terminal:
            raise RunnerError("registered actual two-phase finalization terminal set is invalid")
        PinnedDirectory.reverify_snapshot(
            control_pin, PurePosixPath("runs", run_id, relative).as_posix(), retained,
        )
    directories, files = _pinned_control_tree_inventory(
        control_pin, PurePosixPath("runs", run_id).as_posix(),
    )
    if (set(directories) != set(snapshot.directories)
            or set(files) != set(snapshot.files) | set(terminal)):
        raise RunnerError("registered actual two-phase finalization tree changed")


def _finalize_registered_actual_two_phase_host_diagnostic(
    preflight: _RegisteredActualTwoPhaseHostPreflight,
) -> Path:
    """Seal only the exact two-execution incomplete private diagnostic log."""

    if type(preflight) is not _RegisteredActualTwoPhaseHostPreflight:
        raise RunnerError("registered actual two-phase finalization inputs are invalid")
    snapshot = _freeze_registered_actual_two_phase_finalization_snapshot(preflight)
    control_pin = snapshot.preflight.host_join.control_pin
    run_id = snapshot.preflight.host_join.run_id
    terminal: dict[str, _ControlTraceSnapshot] = {}
    for relative, raw in (
        ("evidence-index.json", snapshot.index_raw),
        ("log-attestation.json", snapshot.attestation_raw),
        # The event log is written last.  A failed earlier write can leave
        # only support files, which no consumer may interpret as a finalized
        # diagnostic; safe cleanup cannot portably unlink a pathname without
        # racing a hostile replacement.  It is not a substitute for readers
        # validating the whole bundle after any later hostile mutation.
        ("event-log.json", snapshot.log_raw),
    ):
        _verify_registered_actual_two_phase_finalization_base(snapshot, terminal)
        identity = PinnedDirectory.write_relative_exclusive(
            control_pin,
            PurePosixPath("runs", run_id, relative).as_posix(), raw,
        )
        terminal[relative] = (raw, identity)
        _verify_registered_actual_two_phase_finalization_base(snapshot, terminal)
    if set(terminal) != {"evidence-index.json", "log-attestation.json", "event-log.json"}:
        raise RunnerError("registered actual two-phase finalization is incomplete")
    _verify_registered_actual_two_phase_finalization_base(snapshot, terminal)
    return control_pin.path / "runs" / run_id / "event-log.json"


@dataclass(frozen=True)
class RunOutcome:
    log: dict[str, Any]
    log_path: Path
    workspace: Path
    control_root: Path
    trusted_context: Any | None = None


def _phase_control(
    prepared: PreparedWorkspace,
    *, phase: str,
    approval: dict[str, str] | None,
    metadata: _RegisteredActualScenarioFixtureMetadata | None = None,
) -> PhaseControlSeals:
    if metadata is None:
        scenario = prepared.scenario
        fixture_id = scenario.get("fixture_id")
        fixture_sha256 = prepared.fixture.get("tree_sha256")
    else:
        if type(metadata) is not _RegisteredActualScenarioFixtureMetadata:
            raise RunnerError("fixture control metadata is invalid")
        metadata.__post_init__()
        scenario = metadata.scenario()
        fixture_id = metadata.fixture_id
        fixture_sha256 = metadata.fixture_sha256
    if (type(scenario) is not dict
            or type(fixture_id) is not str
            or type(fixture_sha256) is not str
            or not _is_hex64(fixture_sha256)):
        raise RunnerError("fixture control metadata is invalid")
    fixture_config: dict[str, str] | None = None
    fixture_paths: dict[str, Path] = {}
    if scenario["network_mode"] == "mock_only":
        if approval is None:
            raise RunnerError("web phase requires a runner-owned approval script")
        # 7b validates this typed control document before it applies its phase
        # gate.  It is not a fixture capability: phase ``approval`` still
        # rejects every fixture operation before opening these assets.
        expected_assets = prepared.fixture_control_assets
        if set(expected_assets) != {
            "static-shell.html", "rendered-dom.html", "unused-candidate.html",
        } or any(type(raw) is not bytes for raw in expected_assets.values()):
            raise RunnerError("fixture control assets unavailable")
        expected_descriptor = _canonical_json({
            "fixture_id": fixture_id,
            "fixture_sha256": fixture_sha256,
            "static_sha256": _sha256(expected_assets["static-shell.html"]),
            "rendered_sha256": _sha256(expected_assets["rendered-dom.html"]),
            "unused_sha256": _sha256(expected_assets["unused-candidate.html"]),
            "final_url": "https://example.test/standard",
            "media_type": "text/html",
            "retrieved_at": "2026-09-04T12:00:00Z",
            "redirect_urls": [],
        })
        copied: dict[str, Path] = {}
        for source_name, target_name in (("static-shell.html", "static-shell.html"), ("rendered-dom.html", "rendered-dom.html")):
            target = prepared.control_root / target_name
            if target.exists():
                if _safe_read(target) != expected_assets[source_name]:
                    raise RunnerError("fixture control asset changed between phases")
            elif phase == "approved_capture":
                raise RunnerError("fixture control asset disappeared between phases")
            else:
                _write_private(target, expected_assets[source_name])
            copied[source_name] = target
        descriptor_path = prepared.control_root / "fixture-descriptor.json"
        if descriptor_path.exists():
            if _safe_read(descriptor_path) != expected_descriptor:
                raise RunnerError("fixture descriptor changed between phases")
        elif phase == "approved_capture":
            raise RunnerError("fixture descriptor disappeared between phases")
        else:
            _write_private(descriptor_path, expected_descriptor)
        fixture_config = {
            "descriptor_path": "fixture-descriptor.json",
            "static_shell_path": "static-shell.html",
            "rendered_dom_path": "rendered-dom.html",
        }
        fixture_paths = {
            "fixture-descriptor.json": descriptor_path,
            "static-shell.html": copied["static-shell.html"],
            "rendered-dom.html": copied["rendered-dom.html"],
        }
    config = {
        "schema_version": 1,
        "workspace": str(prepared.workspace),
        "scenario_id": scenario["id"],
        "phase": phase,
        "approval": approval,
        "fixture": fixture_config,
    }
    target = prepared.control_root / "brain-shim.json"
    if target.exists():
        target.unlink()
    _write_private(target, _canonical_json(config))
    assets: dict[str, tuple[ControlFileSeal, bytes]] = {}
    for name, path in fixture_paths.items():
        seal = _seal_control_file(path)
        raw = _safe_read(path)
        if _sha256(raw) != seal.sha256:
            raise RunnerError("fixture control asset changed before phase launch")
        verify_control_file(seal)
        assets[name] = (seal, raw)
    return PhaseControlSeals(_seal_control_file(target), assets)


def _write_runner_state(
    prepared: PreparedWorkspace, *, run_id: str, execution_id: str, phase: str
) -> ControlFileSeal:
    path = prepared.control_root / "runner-state.json"
    if path.exists():
        path.unlink()
    _write_private(path, _canonical_json({
        "schema_version": 1,
        "control_root": str(prepared.control_root),
        "workspace": str(prepared.workspace),
        "run_id": run_id,
        "execution_id": execution_id,
        "phase": phase,
    }))
    return _seal_control_file(path)


def _version_text(raw: bytes) -> str:
    text = raw.decode("utf-8", errors="replace").strip()
    if not text:
        return "unavailable"
    # The native adapter needs exact known version, but logs retain the raw
    # probe separately.  Pull the conventional first token conservatively.
    for token in text.replace("\n", " ").split():
        if any(char.isdigit() for char in token):
            return token.removeprefix("v")
    return text.splitlines()[0]


def _incomplete_log(
    *, run_id: str, scenario: Mapping[str, Any], client: str, version: str,
    fixture_sha256: str, executions: list[dict[str, Any]], reasons: Iterable[str],
    receipts: Sequence[dict[str, Any]] = (), deliveries: Sequence[dict[str, Any]] = (),
    events: Sequence[dict[str, Any]] = (),
    repository_assertions: Sequence[dict[str, Any]] = (),
) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "run_id": run_id,
        "scenario_id": scenario["id"],
        "client": client,
        "client_version": version or "unavailable",
        "fixture_sha256": fixture_sha256,
        "network_mode": scenario["network_mode"],
        "evidence_index_sha256": "0" * 64,
        "log_attestation_sha256": "0" * 64,
        "executions": executions,
        "receipts": list(receipts),
        "deliveries": list(deliveries),
        "events": list(events),
        "repository_assertions": list(repository_assertions),
        "result": "incomplete",
        "incomplete_reasons": sorted(set(reasons)) or ["runner_incomplete"],
    }


def _finalize_log(writer: EvidenceWriter, log: dict[str, Any]) -> Path:
    """Seal, attest, and publish one already-incomplete final log.

    A pass has a materially different authority boundary: it may only be
    published by the atomic staging routine after the public validator has
    accepted the sealed evidence.  Keeping this convenience finalizer
    incomplete-only prevents a later caller from accidentally turning a
    candidate-shaped mapping into a public outcome.
    """

    if log.get("result") != "incomplete":
        raise RunnerError("ordinary finalization accepts incomplete logs only")
    _seal_and_attest_log(writer, log)
    return _publish_sealed_log(writer, log)


def _finalize_registered_actual_phase_one_diagnostic(
    writer: EvidenceWriter,
    log: dict[str, Any],
) -> Path:
    """Finalize only the bridge's deliberately non-semantic incomplete log.

    ``_finalize_log`` is intentionally generic for existing incomplete routes.
    This closed bridge needs an additional boundary so a future caller cannot
    add semantic rows to its diagnostic-only evidence and still publish an
    ordinary incomplete event log.
    """

    expected_execution_keys = {
        "id", "phase", "kind", "policy_id", "process_id", "transcript_id",
    }
    executions = log.get("executions") if type(log) is dict else None
    if (type(writer) is not EvidenceWriter
            or type(log) is not dict
            or log.get("result") != "incomplete"
            or log.get("incomplete_reasons") not in (
                ["public_semantic_projection_unavailable"],
                ["web_approval_phase_unverified"],
            )
            or log.get("events") != []
            or log.get("receipts") != []
            or log.get("deliveries") != []
            or log.get("repository_assertions") != []
            or type(executions) is not list
            or len(executions) != 1
            or type(executions[0]) is not dict
            or set(executions[0]) != expected_execution_keys
            or executions[0].get("id") != "execution-1"
            or executions[0].get("phase") != "approval"
            or executions[0].get("kind") != "actual_client_process"
            or any(type(executions[0].get(key)) is not str or not executions[0][key]
                   for key in ("policy_id", "process_id", "transcript_id"))):
        raise RunnerError("registered actual phase-one diagnostic finalization boundary")
    return _finalize_log(writer, log)


def _seal_and_attest_log(writer: EvidenceWriter, log: dict[str, Any]) -> None:
    """Create immutable index/attestation bytes before any event-log publish.

    The public validator consumes a log mapping plus these two sealed control
    files; it deliberately does not need ``event-log.json`` to exist.  Keeping
    this step separate makes a candidate pass validation gate observable and
    prevents a one-shot EvidenceWriter from publishing before validation.
    """

    if ((writer.run_root / "evidence-index.json").exists()
            or (writer.run_root / "log-attestation.json").exists()
            or (writer.run_root / "event-log.json").exists()):
        raise RunnerError("run log finalization was already started")
    index_sha = writer.seal()
    log["evidence_index_sha256"] = index_sha
    unsigned = dict(log)
    unsigned.pop("log_attestation_sha256", None)
    attestation = {
        "schema_version": 1,
        "run_id": log["run_id"],
        "client": log["client"],
        "scenario_id": log["scenario_id"],
        "fixture_sha256": log["fixture_sha256"],
        "evidence_index_sha256": index_sha,
        "log_sha256": _sha256(_canonical_json(unsigned)),
    }
    attestation_raw = _canonical_json(attestation)
    _write_private(writer.run_root / "log-attestation.json", attestation_raw)
    log["log_attestation_sha256"] = _sha256(attestation_raw)


def _publish_sealed_log(
    writer: EvidenceWriter,
    log: Mapping[str, Any],
) -> Path:
    """Write an already-sealed incomplete diagnostic log only.

    Passing logs deliberately have no reusable publisher helper.  The sole
    source-level write of a pass lives inline at the end of
    ``_atomic_validate_and_publish_candidate`` after its detached validator
    view returns and the sealed candidate is rechecked.
    """

    if log.get("result") != "incomplete":
        raise RunnerError("ordinary sealed publication accepts incomplete logs only")

    output = writer.run_root / "event-log.json"
    _write_private(output, _canonical_json(log))
    return output


@dataclass(frozen=True)
class PrepublicationFinalization:
    """The sole outcome of staging a potential public pass."""

    log: dict[str, Any]
    log_path: Path
    published: bool
    stage_run_id: str


def _validate_prepublication_event_log(
    log: dict[str, Any],
    schema: dict[str, Any],
    scenario: dict[str, Any],
    fixture_sha256: str,
    trusted_context: Any,
) -> None:
    """Call the sourced public validator only after staging has sealed bytes."""

    from tests.evals import event_log_contract as contract

    contract.validate_event_log(log, schema, scenario, fixture_sha256, trusted_context)


def _prepublication_diagnostic_outcome(
    *,
    stage_writer: EvidenceWriter,
    candidate_log: Mapping[str, Any],
    scenario: Mapping[str, Any],
    fixture_sha256: str,
    error: Exception,
) -> PrepublicationFinalization:
    """Preserve rejected sealed evidence and publish only a separate diagnostic.

    ``EvidenceWriter`` and private files are deliberately O_EXCL.  Rewriting
    the stage's attestation after rejection would make the already-validated
    candidate bytes ambiguous.  Keep that sealed stage without an event log,
    then make a new, self-attested incomplete diagnostic run instead.
    """

    client = candidate_log.get("client")
    version = candidate_log.get("client_version")
    if client not in {"codex", "claude"} or type(version) is not str or not version:
        raise RunnerError("prepublication candidate identity unavailable")
    diagnostic_run_id = _sha256(
        (stage_writer.run_id + "\0prepublication-validation\0" + uuid.uuid4().hex).encode("utf-8")
    )
    diagnostic_writer = EvidenceWriter(stage_writer.control_root, diagnostic_run_id)
    diagnostic_writer.add_json("prepublication-validation", "assertion", {
        "stage_run_id": stage_writer.run_id,
        "failure_type": type(error).__name__,
    })
    diagnostic_log = _incomplete_log(
        run_id=diagnostic_run_id,
        scenario=scenario,
        client=client,
        version=version,
        fixture_sha256=fixture_sha256,
        executions=[],
        reasons=["prepublication_validation_failed"],
    )
    diagnostic_path = _finalize_log(diagnostic_writer, diagnostic_log)
    return PrepublicationFinalization(
        diagnostic_log, diagnostic_path, False, stage_writer.run_id,
    )


def _atomic_validate_and_publish_candidate(
    *,
    writer: EvidenceWriter,
    candidate_log: Mapping[str, Any],
    scenario: dict[str, Any],
    fixture_sha256: str,
    trusted_context: Any,
) -> PrepublicationFinalization:
    """Stage → validate → publish a pass without an observable unvalidated log.

    This is the only pass-capable finalizer.  An injected ProcessRunner never
    reaches it; a later registered live route must supply the retained trusted
    context and a complete candidate.  A rejected candidate leaves its sealed
    evidence stage intact but no ``event-log.json`` pass, and returns a fresh
    incomplete diagnostic outcome.
    """

    if not isinstance(candidate_log, Mapping):
        raise RunnerError("prepublication candidate log unavailable")
    candidate = _strict_json(_canonical_json(candidate_log), label="prepublication candidate log")
    if (candidate.get("run_id") != writer.run_id
            or candidate.get("scenario_id") != scenario.get("id")
            or candidate.get("fixture_sha256") != fixture_sha256
            or candidate.get("result") != "pass"
            or candidate.get("incomplete_reasons") != []):
        raise RunnerError("prepublication candidate identity invalid")
    _seal_and_attest_log(writer, candidate)
    # Validators are ordinary Python callables in this harness.  Give them a
    # fresh canonical reconstruction, never the mapping whose attestation we
    # will publish.  A validator mutation must therefore either be ignored
    # locally or cause its own validation failure; it cannot alter sealed pass
    # bytes after the fact.
    sealed_candidate_raw = _canonical_json(candidate)
    validation_view = _strict_json(
        sealed_candidate_raw, label="sealed prepublication candidate",
    )
    if type(validation_view) is not dict:
        raise RunnerError("sealed prepublication candidate invalid")
    try:
        schema = _strict_json(
            _safe_read(EVAL_ROOT / "event-log.v1.schema.json"), label="event log schema",
        )
        _validate_prepublication_event_log(
            validation_view, schema, scenario, fixture_sha256, trusted_context,
        )
    except Exception as error:
        return _prepublication_diagnostic_outcome(
            stage_writer=writer, candidate_log=candidate, scenario=scenario,
            fixture_sha256=fixture_sha256, error=error,
        )
    if _canonical_json(candidate) != sealed_candidate_raw:
        raise RunnerError("sealed prepublication candidate changed during validation")
    # There is intentionally no reusable post-validation publisher witness:
    # this is the only pass-capable write in the runner.  ``_write_private``
    # supplies O_EXCL/no-follow publication after validation and the final
    # sealed-byte equality check have both succeeded.
    output = writer.run_root / "event-log.json"
    _write_private(output, sealed_candidate_raw)
    return PrepublicationFinalization(
        candidate,
        output,
        True,
        writer.run_id,
    )


def _registered_actual_phase_two_approval() -> dict[str, str]:
    """Return the one runner-owned approval allowed for private phase two."""

    return {
        "event_id": "approval-standard",
        "scope": "one controlled standard fixture",
        "note": "Approve static and faithful rendered fixture capture",
    }


def _phase_approval(scenario: Mapping[str, Any]) -> dict[str, str] | None:
    if scenario["id"] != "web-approval-and-capture":
        return None
    return _registered_actual_phase_two_approval()


def _semantic_events_for_phase(scenario: Mapping[str, Any], phase: str) -> frozenset[str]:
    """Use the sealed phase contract instead of an ad-hoc marker subset."""

    try:
        from tests.evals.phase_prompt_contract import required_events_for_phase

        return frozenset(required_events_for_phase(scenario, phase))
    except (ImportError, TypeError, ValueError) as error:
        raise RunnerError("scenario has invalid semantic phase events") from error


def _known_semantic_references(
    artifact_types: Mapping[str, str],
    cursor_proofs: Sequence[SemanticCursorProofEvidence] = (),
) -> dict[str, dict[str, str]]:
    """Expose only runner-created typed support; missing kinds stay missing."""

    references: dict[str, dict[str, str]] = {}
    if artifact_types.get("web-approval") == "approval":
        references["ask_web_approval"] = {"approval_id": "web-approval"}
        for name in ("public_web_access", "snapshot_used_source", "stage_faithful_browser_capture"):
            if artifact_types.get("fixture-capability") == "fixture_capability":
                references[name] = {
                    "approval_id": "web-approval", "capability_id": "fixture-capability",
                }
    if artifact_types.get("fixture-capability") == "fixture_capability":
        references["select_used_source"] = {"capability_id": "fixture-capability"}
    by_family: dict[str, list[SemanticCursorProofEvidence]] = {}
    for proof in cursor_proofs:
        if artifact_types.get(proof.proof_id) == "cursor_proof":
            by_family.setdefault(proof.family, []).append(proof)
    for family, proofs in by_family.items():
        # A semantic event cannot silently choose among two otherwise valid
        # search chains.  Leave the reference absent so the plan is named
        # incomplete unless exactly one runner-built proof fits the family.
        if len(proofs) != 1:
            continue
        proof_id = proofs[0].proof_id
        if family == "wiki_search":
            references["wiki_search_drained"] = {"cursor_proof_id": proof_id}
            references["wiki_no_supported_evidence"] = {"cursor_proof_id": proof_id}
        elif family == "freshness_search_batched":
            references["freshness_search_drained"] = {"cursor_proof_id": proof_id}
        elif family in {
            "source_pass_discovery", "source_pass_expansion", "source_pass_verification",
            "link_candidates",
        }:
            references[family + "_drained"] = {"cursor_proof_id": proof_id}
    return references


def _scenario_permits_no_shim_commands(scenario: Mapping[str, Any]) -> bool:
    """Allow an empty bridge only for the reviewed repository workflow."""

    try:
        from tests.evals import event_log_contract as contract

        if scenario.get("id") != "repository-development-not-archived":
            return False
        required = scenario.get("required_events")
        receipts = scenario.get("receipt_operations")
        return (
            type(required) is list and type(receipts) is list and not receipts
            and all(type(name) is str and name in contract.EVENT_RULES
                    and contract.EVENT_RULES[name].mode in {"marker", "marker_diff", "marker_approval"}
                    for name in required)
        )
    except Exception:
        return False


def _pinned_control_capture_is_absent(
    control_pin: PinnedDirectory,
    relative: str,
) -> bool:
    """Check one root-level conversion input without collapsing empty/present.

    The zero-command exception is a pre-conversion classification, so a
    present empty index is just as unclean as a malformed one.  Use the
    retained control descriptor rather than a later pathname ``exists``
    check; the result is intentionally held for this conversion attempt and
    never recomputed after conversion has started.
    """

    parts = PinnedDirectory._relative_parts(relative)
    if len(parts) != 1:
        raise RunnerError("no-command bridge input path invalid")
    PinnedDirectory.verify(control_pin)
    try:
        os.stat(parts[0], dir_fd=control_pin.root_fd, follow_symlinks=False)
    except FileNotFoundError:
        PinnedDirectory.verify(control_pin)
        return True
    except OSError as error:
        raise RunnerError("no-command bridge input inspection failed") from error
    PinnedDirectory.verify(control_pin)
    return False


def _clean_repository_no_command_bridge(
    scenario: Mapping[str, Any],
    trace_rows: Sequence[Mapping[str, Any]],
    *,
    control_pin: PinnedDirectory,
) -> bool:
    """Classify the one reviewed no-command bridge before conversion begins."""

    if (not _scenario_permits_no_shim_commands(scenario)
            or any(row.get("kind") in {"command_start", "source_state", "command_end"}
                   for row in trace_rows)):
        return False
    return all(
        _pinned_control_capture_is_absent(control_pin, name)
        for name in (
            "brain-shim-capture-index.jsonl",
            "brain-shim-command-log.jsonl",
            "runner-preapply-manifests.jsonl",
        )
    )


def _registered_client_process_verified() -> bool:
    """Return executable provenance status for the current runner.

    Task 7c deliberately has no installation-registration route, so ordinary
    execution is permanently false.  Keeping this closed predicate separate
    lets focused tests exercise the future public-emission boundary without
    making a process runner, PATH entry, command flag, or environment value an
    authority source.  Task 7d must replace this atomically with registered
    executable evidence rather than widening this function's inputs.
    """

    return False


def run_scenario(
    *,
    client: str,
    scenario_id: str,
    client_command_json: str,
    network_attestation: str,
    scratch_root: Path | None = None,
    process_runner: ProcessRunner | None = None,
) -> RunOutcome:
    """Run one isolated scenario; fail closed for any unproven pass condition.

    ``process_runner`` exists solely for focused tests.  An injected runner is
    permanently tagged as non-actual and cannot produce a pass, regardless of
    stdout it returns.
    """

    prepared = prepare_isolated_workspace(scenario_id, scratch_root=scratch_root)
    run_id = _sha256((str(prepared.run_root) + "\0" + uuid.uuid4().hex).encode())
    writer = EvidenceWriter(prepared.control_root, run_id)
    scenario = prepared.scenario
    reasons: list[str] = []
    executions: list[dict[str, Any]] = []
    observed_version = "unavailable"
    phase_prompt_bytes: dict[str, bytes] = {}
    try:
        if client not in {"codex", "claude"}:
            raise RunnerError("unsupported client")
        expected_attestation = "workspace-egress-denied" if client == "codex" else "mock-only"
        if network_attestation != expected_attestation:
            raise RunnerError("network attestation does not match closed client profile")
        template = parse_client_command_json(client_command_json)
        # Validate each sealed phase prompt and the closed template before any
        # process seam is reachable. Claude receives an indexed phase-specific
        # MCP file below; this unused path only lets the pure builder check its
        # locked slot. Neither client ever receives the raw scenario request
        # directly.
        for phase in phase_plan(scenario_id):
            raw = _canonical_phase_prompt(scenario, phase)
            phase_prompt_bytes[phase] = raw
            build_effective_argv(
                client, template, prepared.workspace,
                prepared.control_root / "mcp-template-placeholder",
                raw.decode("utf-8", "strict"),
            )
    except RunnerError as error:
        reasons.append("policy_rejected")
        writer.add_json("runner-diagnostic", "assertion", {"reason": str(error)})
        assertion_projection = _project_repository_assertions(
            writer, run_id=run_id, scenario=scenario, marker_diff_references={},
            fallback_before=None, fallback_after=None, actual_client_verified=False,
        )
        if scenario["id"] == "repository-development-not-archived":
            reasons.append("repository_assertion_marker_diff_unavailable")
        log = _incomplete_log(
            run_id=run_id, scenario=scenario, client=client if client in {"codex", "claude"} else "codex",
            version=observed_version, fixture_sha256=prepared.fixture["tree_sha256"], executions=executions, reasons=reasons,
            repository_assertions=assertion_projection.assertions,
        )
        path = _finalize_log(writer, log)
        return RunOutcome(log, path, prepared.workspace, prepared.control_root)

    test_live_launch = _TEST_ONLY_REGISTERED_LIVE_LAUNCH
    if process_runner is not None and test_live_launch is not None:
        # Two test seams would make launch provenance ambiguous.  Neither is
        # user-configurable, but reject their accidental combination rather
        # than choosing one by precedence.
        reasons.append("policy_rejected")
        writer.add_json("runner-diagnostic", "assertion", {
            "reason": "multiple test process seams configured",
        })
        log = _incomplete_log(
            run_id=run_id, scenario=scenario, client=client, version=observed_version,
            fixture_sha256=prepared.fixture["tree_sha256"], executions=[], reasons=reasons,
        )
        path = _finalize_log(writer, log)
        return RunOutcome(log, path, prepared.workspace, prepared.control_root)

    if process_runner is None and test_live_launch is None:
        # Task 7c intentionally has no host-installation registration surface.
        # In particular, never turn an inherited PATH/HOME/config value into
        # executable authority.  Task 7d (or a separately reviewed design)
        # must introduce a runner-owned registration that binds an absolute
        # executable identity and a closed supported-build digest before an
        # actual client can be started.
        reasons.append("client_executable_unregistered")
        writer.add_json("runner-diagnostic", "assertion", {
            "reason": "no_runner_owned_client_installation_registration",
        })
        assertion_projection = _project_repository_assertions(
            writer, run_id=run_id, scenario=scenario, marker_diff_references={},
            fallback_before=None, fallback_after=None, actual_client_verified=False,
        )
        if scenario["id"] == "repository-development-not-archived":
            reasons.append("repository_assertion_marker_diff_unavailable")
        log = _incomplete_log(
            run_id=run_id, scenario=scenario, client=client, version=observed_version,
            fixture_sha256=prepared.fixture["tree_sha256"], executions=[], reasons=reasons,
            repository_assertions=assertion_projection.assertions,
        )
        path = _finalize_log(writer, log)
        return RunOutcome(log, path, prepared.workspace, prepared.control_root)

    # Tests supply their own bytes; do not let them masquerade as a binary
    # that the host independently resolved, probed, and pinned.  The private
    # registered-live seam below is separately host-bound, but stays
    # incomplete-only until a real-client path has an independent review.
    environment = {"PATH": "/usr/bin:/bin", "HOME": str(prepared.control_root / "home"), "LANG": "C.UTF-8"}
    version_raw = b""
    help_raw = b""
    # Both test seams are incapable of a pass.  The registered-live seam can
    # exercise prelaunch trust/streaming, while the legacy ProcessRunner can
    # exercise capture normalization; neither may make a candidate public.
    actual_client_verified = False
    if test_live_launch is None:
        reasons.append("test_process_not_actual")
    else:
        reasons.append("test_registered_live_launch_not_pass_capable")

    approval = _phase_approval(scenario)
    web_approval_authorized = False
    approved_capture_evidence_recorded = False
    prior_raw_capture_index = b""
    prior_raw_command_log = b""
    prior_raw_preapply_manifests = b""
    snapshotter = WorkspaceSnapshotter(
        workspace=prepared.workspace, workspace_pin=prepared.workspace_pin, writer=writer,
    )
    initial_workspace_snapshots: dict[str, WorkspaceSnapshot] = {}
    final_workspace_snapshots: dict[str, WorkspaceSnapshot] = {}
    marker_workspace_snapshots: list[WorkspaceSnapshot] = []
    semantic_markers: list[SemanticMarkerEvidence] = []
    semantic_commands: list[SemanticCommandEvidence] = []
    semantic_delivery_evidence: tuple[SemanticDeliveryEvidence, ...] = ()
    semantic_cursor_proofs: tuple[SemanticCursorProofEvidence, ...] = ()
    semantic_execution_order: dict[str, int] = {}
    semantic_collection_reasons: list[str] = []
    phase_prompt_bindings: dict[str, dict[str, str]] = {}
    prior_phase_control: PhaseControlSeals | None = None
    registered_phase_contexts: dict[str, Any] = {}
    registered_executables: dict[str, Any] = {}
    retained_trusted_context: Any | None = None
    for phase_index, phase in enumerate(phase_plan(scenario_id), 1):
        if phase == "approved_capture" and not web_approval_authorized:
            reasons.append("web_approval_phase_unverified")
            break
        execution_id = f"execution-{phase_index}"
        halt_after_phase = False
        phase_approval = (
            {**approval, "decision": "approved"}
            if phase == "approved_capture" and approval is not None else None
        )
        phase_capability_id: str | None = None
        # These are initialized per iteration.  A phase-two setup failure
        # must never accidentally reuse phase one's sealed control assets.
        phase_control_seal: PhaseControlSeals | None = None
        state_seal: ControlFileSeal | None = None
        phase_process_started = False
        phase_mcp_id: str | None = None
        phase_mcp_path = prepared.control_root / "mcp-unused"
        mcp_seal: ControlFileSeal | None = None
        mcp_raw = b""
        if client == "claude":
            # The client must consume the exact indexed config file, not a
            # same-byte private staging copy.  Its stable evidence path is
            # created before launch, sealed, and used for both the locked argv
            # slot and the policy/process identity join.
            phase_mcp_id = f"mcp-{phase_index}"
            writer.add_bytes(
                phase_mcp_id, "mcp_config", EMPTY_MCP_BYTES, suffix=".json",
            )
            phase_mcp_entry = _writer_entry_map(writer).get(phase_mcp_id)
            if phase_mcp_entry is None:
                raise RunnerError("indexed MCP config entry unavailable")
            phase_mcp_path = (writer.run_root / str(phase_mcp_entry["relative_path"])).resolve()
            mcp_seal = _seal_control_file(phase_mcp_path)
            mcp_raw = _safe_read(phase_mcp_path)
            verify_control_file(mcp_seal)
            if mcp_raw != EMPTY_MCP_BYTES:
                raise RunnerError("runner-owned MCP config bytes changed before launch")
        phase_prompt = _index_phase_prompt(
            writer,
            scenario=scenario,
            phase=phase,
            phase_index=phase_index,
            client=client,
            raw=phase_prompt_bytes[phase],
        )
        phase_prompt_bindings[execution_id] = {
            "execution_id": execution_id,
            "phase": phase,
            "phase_prompt_id": phase_prompt.artifact_id,
            "phase_prompt_sha256": phase_prompt.sha256,
            "phase_prompt_transport": phase_prompt.transport,
        }
        phase_argv = build_effective_argv(
            client, template, prepared.workspace, phase_mcp_path,
            phase_prompt.raw.decode("utf-8", "strict"),
        )
        try:
            prepared.control_pin.verify()
            prepared.workspace_pin.verify()
            # The upcoming control document intentionally replaces
            # brain-shim.json, but every phase-one asset must still retain
            # its original inode and bytes before that rewrite is allowed.
            # This catches a same-byte os.replace that a fresh byte baseline
            # alone would not see.
            if prior_phase_control is not None:
                verify_phase_control(prior_phase_control)
            phase_control_seal = _phase_control(
                prepared, phase=phase,
                approval=approval,
            )
            if prior_phase_control is not None:
                _verify_phase_fixture_assets(prior_phase_control)
            prior_phase_control = phase_control_seal
            state_seal = _write_runner_state(
                prepared, run_id=run_id, execution_id=execution_id, phase=phase
            )
        except RunnerError as error:
            # A phase boundary is itself an integrity boundary.  In
            # particular, never repair a changed phase-one fixture asset and
            # carry on with a newly sealed phase-two baseline.
            reasons.append("execution_integrity_failure")
            writer.add_json(f"diagnostic-{phase_index}", "assertion", {"reason": str(error)})
            break
        phase_environment = dict(environment)
        phase_environment[CONTROL_ENV] = str(prepared.control_root)
        phase_environment[RUNNER_STATE_ENV] = str(state_seal.path)
        transcript_id = f"transcript-{phase_index}"
        trace = ControlTraceWriter(
            prepared.control_root, execution_id, control_pin=prepared.control_pin,
        )
        marker_time_streamed = False

        def capture_marker_snapshot(
            raw: bytes, byte_start: int, byte_end: int, sequence: int,
        ) -> str:
            snapshot = snapshotter.capture(
                execution_id=execution_id,
                trace_sequence=sequence,
                role="marker",
                native_record={
                    "transcript_id": transcript_id,
                    "byte_start": byte_start,
                    "byte_end": byte_end,
                    "sha256": _sha256(raw),
                },
            )
            marker_workspace_snapshots.append(snapshot)
            return snapshot.artifact_id

        live_phase: RegisteredLivePhase | None = None
        try:
            prepared.control_pin.verify()
            prepared.workspace_pin.verify()
            verify_wrapper(prepared.wrapper_seal)
            verify_phase_control(phase_control_seal)
            verify_control_file(state_seal)
            if mcp_seal is not None:
                verify_control_file(mcp_seal)
            _verify_phase_prompt(phase_prompt)
            initial_workspace_snapshots[execution_id] = snapshotter.capture(
                execution_id=execution_id, trace_sequence=0,
            )
            stdin = phase_prompt.raw if client == "codex" else b""
            if test_live_launch is None:
                assert process_runner is not None
                try:
                    capture = process_runner(
                        phase_argv, prepared.workspace, phase_environment, stdin,
                    )
                finally:
                    # A process seam can fail before it returns a capture. Its
                    # prompt artifact must still be sealed after that attempted
                    # spawn, rather than being trusted only on the happy path.
                    _verify_phase_prompt(phase_prompt)
                if type(capture) is not ProcessCapture:
                    raise RunnerError("injected process returned an invalid capture")
                phase_process_started = True
                marker_time_streamed = capture.stdout_chunks is not None
                # Preserve fake native rows through the same arrival-order path the
                # closed registered bridge pipe reader uses.  Test injection remains
                # forced incomplete regardless of what its stream contains.
                capture = ProcessCapture(
                    capture.exit_code,
                    _capture_native_stdout(
                        capture, trace=trace, transcript_id=transcript_id,
                        on_native_record=capture_marker_snapshot,
                    ),
                    capture.stderr, capture.version, capture.help,
                )
            else:
                # A one-phase run constructs its final context immediately
                # before launch.  For web, phase two is not even prepared
                # until phase one has granted the transition; retain/recheck
                # its first executable and then create a fresh phase-two
                # executable before assembling the aggregate context.
                if phase == "approved_capture":
                    phase_one = registered_executables.get("execution-1")
                    phase_one_context = registered_phase_contexts.get("execution-1")
                    if phase_one is None or phase_one_context is None:
                        raise RunnerError("registered phase-one trust unavailable")
                    if set(phase_one_context.trusted_executables) != {"execution-1"}:
                        raise RunnerError("registered phase-one context is not isolated")
                    _registered_live_context_phase(
                        client=client, execution_id="execution-1",
                        control_pin=prepared.control_pin, workspace_pin=prepared.workspace_pin,
                        trusted_context=phase_one_context,
                        expected_execution_ids=frozenset({"execution-1"}),
                    )
                    prepared.control_pin.verify()
                    prepared.workspace_pin.verify()
                    _registered_executable_observation(phase_one)
                _registration, trusted = _prepare_registered_live_executable(
                    client=client, execution_id=execution_id,
                    control_pin=prepared.control_pin, workspace_pin=prepared.workspace_pin,
                )
                if execution_id in registered_executables:
                    raise RunnerError("registered live execution identity reused")
                registered_executables[execution_id] = trusted
                phase_context = _registered_live_trusted_context(
                    control_pin=prepared.control_pin, workspace_pin=prepared.workspace_pin,
                    trusted_executables=registered_executables,
                )
                if phase == "approval" and set(phase_context.trusted_executables) != {execution_id}:
                    raise RunnerError("registered approval context is not phase-local")
                if (phase == "approved_capture"
                        and set(phase_context.trusted_executables) != {"execution-1", execution_id}):
                    raise RunnerError("registered web context is not aggregate")
                registered_phase_contexts[execution_id] = phase_context
                try:
                    live_phase = _launch_registered_live_phase(
                        writer=writer, client=client, execution_id=execution_id,
                        phase=phase, phase_index=phase_index,
                        workspace=prepared.workspace, control_pin=prepared.control_pin,
                        workspace_pin=prepared.workspace_pin, argv=phase_argv,
                        environment=phase_environment, stdin=stdin, trace=trace,
                        transcript_id=transcript_id,
                        on_native_record=capture_marker_snapshot,
                        probe_runner=test_live_launch.probe_runner,
                        popen_factory=test_live_launch.popen_factory,
                        trusted_context=phase_context,
                    )
                finally:
                    _verify_phase_prompt(phase_prompt)
                capture = live_phase.capture
                phase_argv = list(live_phase.argv)
                phase_process_started = True
                marker_time_streamed = True
                retained_trusted_context = phase_context
            version_raw, help_raw = capture.version, capture.help
            observed_version = _version_text(version_raw)
            verify_wrapper(prepared.wrapper_seal)
            verify_phase_control(phase_control_seal)
            verify_control_file(state_seal)
            if mcp_seal is not None:
                verify_control_file(mcp_seal)
            _verify_phase_prompt(phase_prompt)
            prepared.control_pin.verify()
            prepared.workspace_pin.verify()
            # This post-process view can only support a visibly incomplete
            # fallback assertion diff.  Semantic marker/diff claims remain
            # bound solely to the stream-time snapshots captured above.
            final_workspace_snapshots[execution_id] = snapshotter.capture(
                execution_id=execution_id, trace_sequence=0, role="final",
            )
        except RunnerError as error:
            reasons.append("execution_integrity_failure")
            writer.add_json(f"diagnostic-{phase_index}", "assertion", {"reason": str(error)})
            capture = ProcessCapture(127, b"", str(error).encode(), version_raw, help_raw)
            halt_after_phase = True
        except Exception as error:  # child/injection errors must not mint a pass
            reasons.append("execution_failure")
            writer.add_json(f"diagnostic-{phase_index}", "assertion", {"reason": type(error).__name__})
            capture = ProcessCapture(127, b"", repr(error).encode(), version_raw, help_raw)
            halt_after_phase = True

        if capture.exit_code != 0:
            reasons.append("client_exit_nonzero")
            halt_after_phase = True
        normalized = normalize_native_transcript(client=client, version=observed_version, transcript=capture.stdout)
        if not normalized.complete:
            reasons.append(normalized.reason or "unsupported_native_format")
        try:
            trace_rows = trace.records()
        except RunnerError:
            trace_rows = []
            reasons.append("shared_trace_invalid")
        if not trace_rows:
            reasons.append("shared_trace_missing")
        if (phase == "approved_capture" and phase_process_started
                and not halt_after_phase and phase_control_seal is not None):
            prepared.control_pin.verify()
            descriptor_asset = phase_control_seal.fixture_assets.get("fixture-descriptor.json")
            static_asset = phase_control_seal.fixture_assets.get("static-shell.html")
            rendered_asset = phase_control_seal.fixture_assets.get("rendered-dom.html")
            if descriptor_asset is None or static_asset is None or rendered_asset is None:
                raise RunnerError("approved web phase lacks sealed fixture assets")
            _descriptor_seal, descriptor_raw = descriptor_asset
            _strict_json(descriptor_raw, label="fixture descriptor")
            writer.add_bytes(
                "fixture-descriptor", "fixture_descriptor", descriptor_raw, suffix=".json"
            )
            writer.add_bytes("fixture-static-shell", "file_capture", static_asset[1])
            writer.add_bytes("fixture-rendered-dom", "file_capture", rendered_asset[1])
            phase_capability_id = "fixture-capability"
            writer.add_json(phase_capability_id, "fixture_capability", {
                "run_id": run_id, "execution_id": execution_id, "phase": phase,
                "fixture_id": scenario["fixture_id"], "fixture_sha256": prepared.fixture["tree_sha256"],
                "capability_id": phase_capability_id, "approval_event_id": phase_approval["event_id"],
                "scope": phase_approval["scope"], "note": phase_approval["note"],
                "enabled_fixture_ids": [
                    "web-approval-and-capture.initial", "web-approval-and-capture.rendered",
                ],
                "descriptor_id": "fixture-descriptor",
            })
        # The shim configuration may use the scripted approval to reject or
        # allow a phase, but only a successfully launched, captured phase two
        # may project that authority into indexed policy/process evidence.
        recorded_phase_approval = (
            phase_approval if phase_capability_id is not None else None
        )
        transcript_retained = True
        try:
            transcript_raw = _preserve_transcript(
                prepared.control_root, transcript_id, capture.stdout
            )
        except RunnerError as error:
            reasons.append("transcript_preservation_failed")
            writer.add_json(
                f"transcript-diagnostic-{phase_index}", "assertion", {"reason": str(error)}
            )
            # Keep the raw process bytes only for an explicitly incomplete
            # diagnostic record.  They are not a retained transcript and
            # therefore cannot authorize a phase transition or semantic
            # projection.
            transcript_raw = capture.stdout
            transcript_retained = False
            halt_after_phase = True
            semantic_collection_reasons.append("semantic_transcript_unpreserved")
        policy_id = writer.add_json(f"policy-{phase_index}", "policy", {
            "run_id": run_id, "execution_id": execution_id, "phase": phase, "client": client,
            "profile": "codex-workspace-egress-denied-v1" if client == "codex" else "claude-restricted-tool-surface-v1",
            "network_attestation": network_attestation, "argv": phase_argv, "argv_sha256": _sha256(_canonical_json(phase_argv)),
            "version_id": f"version-{phase_index}", "help_id": f"help-{phase_index}",
            "fixture_id": scenario["fixture_id"], "fixture_sha256": prepared.fixture["tree_sha256"],
            "fixture_capability_id": phase_capability_id, "approval": recorded_phase_approval,
            "phase_prompt_id": phase_prompt.artifact_id,
            "phase_prompt_sha256": phase_prompt.sha256,
            "phase_prompt_transport": phase_prompt.transport,
            **({"executable_id": live_phase.executable_id} if live_phase is not None else {}),
            **({
                "mcp_config_id": phase_mcp_id, "mcp_config_sha256": mcp_seal.sha256,
                "mcp_path": str(phase_mcp_path), "mcp_identity": dict(mcp_seal.identity),
            } if client == "claude" else {}),
        })
        if live_phase is None:
            writer.add_bytes(f"version-{phase_index}", "version", version_raw)
            writer.add_bytes(f"help-{phase_index}", "help", help_raw)
        writer.add_bytes(transcript_id, "transcript", transcript_raw)
        writer.add_bytes(f"stderr-{phase_index}", "file_capture", capture.stderr)
        conversion: ShimCaptureConversion | None = None
        try:
            clean_no_command_bridge = _clean_repository_no_command_bridge(
                scenario, trace_rows, control_pin=prepared.control_pin,
            )
        except RunnerError:
            clean_no_command_bridge = False
        if clean_no_command_bridge:
            # This closed repository-only case has no command bridge at the
            # conversion boundary.  Its streamed native rows and marker-time
            # snapshots are still complete execution evidence, so write the
            # canonical process-bound trace directly.  The classification is
            # intentionally made before conversion; never retry it after an
            # attempted bridge conversion fails.
            trace_id = f"trace-{execution_id}"
            fallback_trace = {
                "schema_version": 1, "run_id": run_id, "execution_id": execution_id,
                "records": trace_rows,
            }
            trace_sha256 = _sha256(_canonical_json(fallback_trace))
            writer.add_json(trace_id, "execution_trace", fallback_trace)
        else:
            try:
                prepared.control_pin.verify()
                conversion = convert_shim_captures(
                    writer, control_root=prepared.control_root, run_id=run_id,
                    execution_id=execution_id, phase=phase, transcript_id=transcript_id, trace=trace,
                    control_pin=prepared.control_pin,
                    prior_raw_index=prior_raw_capture_index,
                    prior_raw_command_log=prior_raw_command_log,
                    prior_raw_preapply_manifests=prior_raw_preapply_manifests,
                )
                prepared.control_pin.verify()
                trace_id, trace_sha256 = conversion.trace_id, conversion.trace_sha256
                prior_raw_capture_index = conversion.raw_index
                prior_raw_command_log = conversion.raw_command_log
                prior_raw_preapply_manifests = conversion.raw_preapply_manifests
            except RunnerError as error:
                reasons.append("shim_capture_conversion_failed")
                writer.add_json(f"capture-diagnostic-{phase_index}", "assertion", {"reason": str(error)})
                # Any attempted conversion failure retains a deliberately
                # noncanonical trace ID.  It cannot enter execution binding,
                # even if a malicious test deletes its raw input afterward.
                trace_id = f"trace-unconverted-{phase_index}"
                fallback_trace = {
                    "schema_version": 1, "run_id": run_id, "execution_id": execution_id,
                    "records": trace_rows,
                }
                trace_sha256 = _sha256(_canonical_json(fallback_trace))
                writer.add_json(trace_id, "execution_trace", fallback_trace)
        semantic_execution_order[execution_id] = phase_index - 1
        if normalized.complete and transcript_retained:
            # A complete stdout buffer arrives only after the injected process
            # has returned, so it cannot establish what the workspace looked
            # like when a marker was emitted.  Marker/diff/packet support is
            # therefore stream-only; plain buffered output remains useful for
            # failure diagnostics but never semantic authority.
            if (not marker_time_streamed
                    and _native_records_contain_event_text(normalized.records)):
                semantic_collection_reasons.append("semantic_marker_capture_not_streamed")
                candidates = ()
            else:
                candidates = None
            try:
                if candidates is None:
                    candidates = extract_event_markers(
                        transcript=transcript_raw,
                        native_records=normalized.records,
                        trace_records=trace_rows,
                        transcript_id=transcript_id,
                        allowed_event_names=_semantic_events_for_phase(scenario, phase),
                    )
                for candidate in candidates:
                    semantic_markers.append(SemanticMarkerEvidence(
                        marker_id=f"marker-{len(semantic_markers) + 1}",
                        execution_id=execution_id, candidate=candidate,
                        transcript_id=transcript_id,
                    ))
                if conversion is not None:
                    semantic_commands.extend(_semantic_commands_from_conversion(writer, conversion))
            except RunnerError:
                semantic_collection_reasons.append("semantic_evidence_collection_failed")
        elif conversion is None:
            semantic_collection_reasons.append("semantic_command_bridge_unavailable")
        if live_phase is None:
            writer.add_json(f"executable-{phase_index}", "assertion", {
                "reason": "test_process_not_actual",
            })
        writer.add_json(f"process-{phase_index}", "process", {
            "run_id": run_id, "execution_id": execution_id, "phase": phase, "client": client,
            "client_version": observed_version, "argv": phase_argv, "argv_sha256": _sha256(_canonical_json(phase_argv)),
            "exit_code": capture.exit_code, "transcript_id": transcript_id,
            "transcript_sha256": _sha256(transcript_raw), "trace_id": trace_id,
            "trace_sha256": trace_sha256,
            "native_format": "claude-stream-json-2.1.251-v1" if client == "claude" else "codex-jsonl-unverified-v1",
            "fixture_id": scenario["fixture_id"], "fixture_sha256": prepared.fixture["tree_sha256"],
            "fixture_capability_id": phase_capability_id, "approval": recorded_phase_approval,
            "phase_prompt_id": phase_prompt.artifact_id,
            "phase_prompt_sha256": phase_prompt.sha256,
            "phase_prompt_transport": phase_prompt.transport,
            **({"executable_id": live_phase.executable_id} if live_phase is not None else {}),
            **({"mcp_identity": dict(mcp_seal.identity)} if client == "claude" else {}),
        })
        executions.append({
            "id": execution_id, "phase": phase, "kind": "actual_client_process",
            "policy_id": policy_id, "process_id": f"process-{phase_index}", "transcript_id": transcript_id,
        })
        # The web transition is authorized only after phase one's complete
        # policy/process/executable evidence has been indexed.  A phase-two
        # launch must never be released based solely on a parser-valid stream
        # whose host launch provenance has not yet been bound.
        if (phase == "approval" and scenario["network_mode"] == "mock_only"
                and transcript_retained):
            if _phase_one_web_capture_authorized(
                writer=writer, scenario=scenario, capture=capture,
                marker_time_streamed=marker_time_streamed,
                normalized=normalized, transcript=transcript_raw,
                transcript_id=transcript_id, trace_rows=trace_rows, conversion=conversion,
                workspace=prepared.workspace, execution_id=execution_id,
                registered_phase=live_phase,
            ):
                web_approval_authorized = True
                writer.add_json("web-approval", "approval", {
                    "run_id": run_id, "execution_id": execution_id,
                    **({**approval, "decision": "approved"} if approval is not None else {}),
                    "fixture_id": "web-approval-and-capture.initial",
                    "capability_id": "fixture-capability", "manifest_id": None,
                })
            else:
                reasons.append("web_approval_phase_unverified")
                halt_after_phase = True
        if (phase == "approved_capture"
                and phase_capability_id == "fixture-capability"):
            # A phase-one approval grants no retrospective capture authority.
            # Only an actually recorded phase-two process with its own typed
            # capability artifact may appear in the final run manifest.
            approved_capture_evidence_recorded = True
        if halt_after_phase:
            break

    fixture_capability_id = (
        "fixture-capability"
        if web_approval_authorized and approved_capture_evidence_recorded else None
    )
    manifest_approval = (
        {**approval, "decision": "approved"}
        if approval is not None and fixture_capability_id is not None else None
    )
    semantic_events: tuple[dict[str, Any], ...] = ()
    semantic_receipts: tuple[dict[str, Any], ...] = ()
    semantic_deliveries: tuple[dict[str, Any], ...] = ()
    semantic_plan: SemanticEventPlan | None = None
    semantic_plan_candidate: SemanticEventPlan | None = None
    semantic_diff_references: dict[str, dict[str, str]] = {}
    trace_snapshot_ids: dict[tuple[str, int], str] = {}
    if semantic_collection_reasons:
        reasons.extend(semantic_collection_reasons)
    else:
        try:
            # A marker's parser-side trace sequence selects marker-time
            # workspace snapshots below.  Bind it to the indexed native row
            # before *any* support projection can emit an artifact.
            semantic_markers = list(_verified_marker_trace_evidence(
                writer, tuple(semantic_markers),
            ))
            trace_snapshot_ids = _indexed_native_snapshot_ids(writer)
            receipt_operations = scenario.get("receipt_operations")
            if type(receipt_operations) is not list:
                raise RunnerError("scenario receipt operations unavailable")
            semantic_delivery_evidence = _semantic_deliveries_from_commands(
                writer, tuple(semantic_commands), tuple(receipt_operations),
            )
            semantic_cursor_proofs = _build_semantic_cursor_proofs(
                writer, run_id=run_id, commands=tuple(semantic_commands),
            )
            semantic_diff_references = _build_marker_diff_references(
                writer, run_id=run_id,
                required_events=tuple(scenario["required_events"]),
                markers=tuple(semantic_markers),
                initial_snapshots=initial_workspace_snapshots,
                snapshots=tuple(marker_workspace_snapshots),
                execution_order=semantic_execution_order,
                trace_snapshot_ids=trace_snapshot_ids,
            )
            packet_references = _build_semantic_packet_references(
                writer, run_id=run_id,
                required_events=tuple(scenario["required_events"]),
                markers=tuple(semantic_markers), commands=tuple(semantic_commands),
                cursor_proofs=semantic_cursor_proofs,
                marker_snapshots=tuple(marker_workspace_snapshots),
                execution_order=semantic_execution_order,
                trace_snapshot_ids=trace_snapshot_ids,
            )
            interpretation_references, interpretation_approval = (
                _build_interpretation_approval_reference(
                    writer, run_id=run_id, scenario=scenario,
                    markers=tuple(semantic_markers), commands=tuple(semantic_commands),
                    execution_order=semantic_execution_order,
                )
            )
        except RunnerError as error:
            if str(error) == "marker trace sequence is not sealed":
                reasons.append("semantic_marker_trace_unverified")
            else:
                reasons.append("semantic_support_projection_failed")
        else:
            if interpretation_approval is not None:
                if manifest_approval is not None:
                    raise RunnerError("multiple run approval projections")
                manifest_approval = interpretation_approval
            artifact_types = {str(entry["id"]): str(entry["type"]) for entry in writer.entries}
            private_decision_id = (
                interpretation_references.get("ask_interpretation_approval", {})
                .get("interpretation_decision_id")
            )
            if private_decision_id is not None:
                if (private_decision_id != _PRIVATE_INTERPRETATION_DECISION_ID
                        or private_decision_id in artifact_types
                        or any(kind == "interpretation_decision"
                               for kind in artifact_types.values())):
                    raise RunnerError("private interpretation decision predeclaration invalid")
                # The event planner needs this closed type to enforce the
                # accepted Task 3 EventRule.  It is only a temporary type
                # declaration; bytes are derived later in private replay and
                # are never written through EvidenceWriter.
                artifact_types[private_decision_id] = "interpretation_decision"
            semantic_references = _known_semantic_references(
                artifact_types, semantic_cursor_proofs,
            )
            for name, generated in interpretation_references.items():
                target = semantic_references.setdefault(name, {})
                if set(target) & set(generated):
                    raise RunnerError("semantic interpretation approval reference collision")
                target.update(generated)
            for name, generated in packet_references.items():
                target = semantic_references.setdefault(name, {})
                if set(target) & set(generated):
                    raise RunnerError("semantic packet reference collision")
                target.update(generated)
            for name, generated in semantic_diff_references.items():
                target = semantic_references.setdefault(name, {})
                if set(target) & set(generated):
                    raise RunnerError("semantic support reference collision")
                target.update(generated)
            plan = plan_semantic_events(SemanticNormalizationInput(
                run_id=run_id, scenario=scenario,
                execution_order=semantic_execution_order,
                markers=tuple(semantic_markers), commands=tuple(semantic_commands),
                artifact_types=artifact_types,
                event_references=semantic_references,
                deliveries=semantic_delivery_evidence,
                cursor_proofs=semantic_cursor_proofs,
            ))
            if plan.complete:
                # Policy/process/trace evidence is intentionally checked only
                # after the run manifest has been fixed below.  Retain this
                # in-memory candidate for now; no marker or event artifact
                # (and therefore no log-facing semantic claim) is emitted
                # until the strict execution binding accepts it.
                semantic_plan_candidate = plan
            else:
                reasons.extend(plan.incomplete_reasons)
    # The semantic replay below must bind approval/capability decisions to the
    # same runner-owned manifest that the eventual public validator consumes.
    # Create that fixed indexed input before assertion projection, rather than
    # letting an in-memory plan choose its own phase or approval context.
    run_manifest = {
        "schema_version": 1, "run_id": run_id, "client": client, "scenario_id": scenario["id"],
        "fixture_id": scenario["fixture_id"], "fixture_sha256": prepared.fixture["tree_sha256"],
        "workspace": str(prepared.workspace), "phases": list(phase_plan(scenario_id)),
        "policy_profiles": [
            "codex-workspace-egress-denied-v1" if client == "codex" else "claude-restricted-tool-surface-v1"
            for _phase in phase_plan(scenario_id)
        ],
        "fixture_capability_id": fixture_capability_id, "approval": manifest_approval,
        "software_paths": list(_software_paths_for_scenario(scenario)),
        "scenario_sha256": scenario_sha256(scenario),
        "phase_prompt_protocol": PROMPT_PROTOCOL,
        "phase_prompts": [
            phase_prompt_bindings[execution["id"]]
            for execution in executions
            if execution["id"] in phase_prompt_bindings
        ],
    }
    # Task 7a deliberately reads this by its fixed run-root name; indexing the
    # same bytes (rather than a second artifact copy) lets the evidence seal
    # bind that fixed contract input too.
    writer.add_fixed_json("run-manifest", "run_manifest", "run-manifest.json", run_manifest)

    if semantic_plan_candidate is not None:
        binding = _indexed_execution_binding(
            writer, run_id=run_id, scenario=scenario,
            execution_order=semantic_execution_order, workspace=prepared.workspace,
            client=client, fixture_sha256=prepared.fixture["tree_sha256"],
            fixture_capability_id=fixture_capability_id, approval=manifest_approval,
        )
        if binding is None:
            reasons.append("semantic_execution_binding_unavailable")
        elif actual_client_verified:
            try:
                private_decision_id = _private_interpretation_decision_id(
                    writer, scenario=scenario, plan=semantic_plan_candidate,
                )
            except RunnerError:
                private_decision_id = _PRIVATE_INTERPRETATION_DECISION_ID
            if private_decision_id is not None:
                # The accepted decision contract has a public artifact join,
                # but Task 7c implements it only in a private incomplete
                # replay.  Never emit marker/event rows that would reference
                # an unindexed virtual ID; Task 7d must add registered-client
                # public projection as one atomic feature.
                reasons.append("semantic_public_interpretation_projection_unavailable")
            else:
                # Persist marker/event artifacts only after the pre-emission
                # binding has established exact runner-owned policy/process,
                # probes, shared trace, and workspace-snapshot graph joins.
                _emit_semantic_plan(writer, semantic_plan_candidate)
                indexed_commands = _indexed_semantic_replay(
                    writer, run_id=run_id, scenario=scenario,
                    plan=semantic_plan_candidate, markers=tuple(semantic_markers),
                    commands=tuple(semantic_commands), execution_order=semantic_execution_order,
                    workspace=prepared.workspace, client=client,
                    fixture_sha256=prepared.fixture["tree_sha256"],
                    fixture_capability_id=fixture_capability_id, approval=manifest_approval,
                )
                if indexed_commands is None:
                    # The event artifacts stay retained for diagnosis, but remain
                    # unreferenced by the incomplete log when full lifecycle
                    # replay rejects them.
                    reasons.append("semantic_indexed_replay_unavailable")
                else:
                    semantic_plan = semantic_plan_candidate
                    semantic_events = semantic_plan.events
                    semantic_receipts = semantic_plan.receipts
                    semantic_deliveries = semantic_plan.deliveries
        else:
            # An injected fake can prove that the parser/normalizer would
            # replay the runner-owned command and snapshot evidence, but it
            # cannot publish marker/event artifacts or any log-facing claims.
            # The replay receives only an in-memory canonical overlay and is
            # deliberately discarded after this diagnostic gate.
            private_commands = _indexed_semantic_replay(
                writer, run_id=run_id, scenario=scenario,
                plan=semantic_plan_candidate, markers=tuple(semantic_markers),
                commands=tuple(semantic_commands), execution_order=semantic_execution_order,
                workspace=prepared.workspace, client=client,
                fixture_sha256=prepared.fixture["tree_sha256"],
                fixture_capability_id=fixture_capability_id, approval=manifest_approval,
                private_candidate=True,
            )
            if private_commands is None:
                reasons.append("semantic_private_replay_unavailable")

    fallback_before: WorkspaceSnapshot | None = None
    fallback_after: WorkspaceSnapshot | None = None
    if final_workspace_snapshots:
        final_execution_id = max(
            final_workspace_snapshots,
            key=lambda item: semantic_execution_order.get(item, -1),
        )
        fallback_before = initial_workspace_snapshots.get(final_execution_id)
        fallback_after = final_workspace_snapshots[final_execution_id]
    assertion_projection = _project_repository_assertions(
        writer, run_id=run_id, scenario=scenario,
        marker_diff_references=semantic_diff_references,
        fallback_before=fallback_before, fallback_after=fallback_after,
        actual_client_verified=actual_client_verified,
        semantic_plan=semantic_plan,
        markers=tuple(semantic_markers),
        marker_snapshots=tuple(marker_workspace_snapshots),
        initial_snapshots=initial_workspace_snapshots,
        commands=tuple(semantic_commands),
        execution_order=semantic_execution_order,
        workspace=prepared.workspace,
        trace_snapshot_ids=trace_snapshot_ids,
        client=client,
        fixture_sha256=prepared.fixture["tree_sha256"],
        fixture_capability_id=fixture_capability_id,
        approval=manifest_approval,
    )
    reasons.extend(assertion_projection.incomplete_reasons)
    if scenario["id"] == "repository-development-not-archived":
        if not assertion_projection.marker_time_available:
            reasons.append("repository_assertion_marker_diff_unavailable")
        elif not assertion_projection.rules_satisfied:
            reasons.append("repository_assertion_scope_violation")
    # Test injection can exercise semantic planning/capture conversion but
    # cannot provide a runner-registered executable.  It therefore remains
    # incomplete even when a future focused fixture supplies a complete plan.
    log = _incomplete_log(
        run_id=run_id, scenario=scenario, client=client, version=observed_version,
        fixture_sha256=prepared.fixture["tree_sha256"], executions=executions, reasons=reasons,
        events=semantic_events, receipts=semantic_receipts, deliveries=semantic_deliveries,
        repository_assertions=assertion_projection.assertions,
    )
    path = _finalize_log(writer, log)
    return RunOutcome(
        log, path, prepared.workspace, prepared.control_root,
        trusted_context=retained_trusted_context,
    )


def _cli_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--client", required=True, choices=("codex", "claude"))
    parser.add_argument("--scenario", required=True)
    parser.add_argument("--client-command-json", required=True)
    parser.add_argument("--network-attestation", required=True, choices=("workspace-egress-denied", "mock-only"))
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _cli_parser().parse_args(argv)
    try:
        scenario_ids = _scenario_ids_for_cli(args.scenario)
    except RunnerError as error:
        print(json.dumps({"scenario_id": args.scenario, "result": "incomplete", "reason": str(error)}, sort_keys=True))
        return 1
    status = 0
    for scenario_id in scenario_ids:
        try:
            outcome = run_scenario(
                client=args.client, scenario_id=scenario_id,
                client_command_json=args.client_command_json,
                network_attestation=args.network_attestation,
            )
            print(json.dumps({"scenario_id": scenario_id, "result": outcome.log["result"], "log_path": str(outcome.log_path)}, sort_keys=True))
            status |= 0 if outcome.log["result"] == "pass" else 1
        except RunnerError as error:
            print(json.dumps({"scenario_id": scenario_id, "result": "incomplete", "reason": str(error)}, sort_keys=True))
            status = 1
    return status


if __name__ == "__main__":
    raise SystemExit(main())
